INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1325,NULL,'정치','도널드 트럼프 미국 대통령이 2024년 1월 25일 워싱턴DC 힐튼호텔에서 열린 백악관 출입기자단 만찬 중 총격 사고 발생 후 에이브러햄 링컨 전 대통령을 언급하며 자신을 ''가장 영향력 있고 바쁜 사람들이 암살 대상이 된다''고 자화자찬했다.','2024년 1월 25일 워싱턴DC 힐튼호텔에서 열린 백악관 출입기자단 만찬 중 도널드 트럼프 미국 대통령이 총격 사고를 당했으며, 총격범은 31세 콜 토마스 앨런으로 사건 직후 체포됐다. 트럼프는 에이브러함 링컨 전 대통령을 언급하며 자신을 ''영향력 있는 대상''으로 자화자찬했고, 언론의 책임감 있는 보도를 칭찬하며 이례적으로 긍정적 평가를 내렸다. 그러나 그는 동시에 언론에 대한 비판적 태도를 유지하며 이중적 입장을 보였고, 백악관 연회장 보수 필요성을 강조하며 4억 달러 규모의 신축 계획 재추진 가능성을 시사했다. 뉴욕타임스는 보안 실패를 지적했고, 국제사회는 정치적 폭력의 정당성 부정을 강조하며 각국 정상들이 메시지를 발표했다.',2,2,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202604/334036_477892_1729.jpg','2026-07-27 16:08:00.107949'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'도널드 트럼프 미국 대통령이 2024년 1월 25일 워싱턴DC 힐튼호텔에서 열린 백악관 출입기자단 만찬 중 총격 사고 발생 후 에이브러햄 링컨 전 대통령을 언급하며 자신을 ''가장 영향력 있고 바쁜 사람들이 암살 대상이 된다''고 자화자찬했다.','title: 총격 사고에도 ‘자화자찬’ 나선 트럼프, 언론에 ‘이례적’ 칭찬
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1326,NULL,'정치','트럼프 행정부, 언론자유지수 180개국 중 64위','도널드 트럼프 행정부 기간 동안 미국의 언론자유지수는 180개국 중 64위로 역대 최저를 기록했다. 이는 전년 대비 7계단 하락한 수치로, RSF 보고서와 퓰리처상이 트럼프 행정부의 언론 탄압과 검열 행위를 지적하며 공공서비스, 탐사보도, 전국 및 지역 보도 부문에서 주요 언론사들이 수상하는 계기를 마련했다. 언론인 구금, 자금 지원 삭감, 소송 제기, 내부 고발자 위축 등이 지속되며, ABC 방송 면허 재검토와 육군 참전 용사 체포 사건이 주요 논란이 되었다. RSF는 전 세계 절반 이상의 국가가 언론자유지수 ''나쁨'' 또는 ''매우 나쁨''으로 평가받으며 권위주의, 무능 정치, 온라인 플랫폼 규제 미흡을 주요 원인으로 지적했다.',2,2,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202605/334198_478170_2338.jpg','2026-07-27 16:08:16.579037'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'도널드 트럼프 미국 대통령 행정부 기간 동안 미국의 언론자유지수가 180개국 중 64위로 역대 최저를 기록했다.','title: 트럼프의 미국, 언론자유 역대 최저… 180개국 중 64위
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1327,NULL,'정치','중국공산당 대외연락부 관계자들이 평양을 방문해 경호 및 의전 점검을 진행했다.','김정은 북한 국무위원장과 시진핑 중국 국가주석이 7년 만의 정상회담을 준비 중이며, 중국공산당 대외연락부 관계자들이 평양을 방문해 경호 및 의전 점검을 진행한 것으로 확인됐다. 이는 도널드 트럼프 미국 대통령의 베이징 방문 이후 미북대화 재개를 위한 중국의 중재 역할을 전제로 한 것으로, 지난달 북중 교역이 약 3억2600만달러로 8년 5개월 만에 최고 수준을 기록하며 양국 관계 회복이 진행 중이다. 정부는 시 주석의 방북이 성사될 경우 북미대화 재개가 당연히 논의될 것이라며 중국의 건설적 역할을 기대하고 있으며, 이는 동북아 정세에서의 중재력 강화와 대미 공조를 위한 전략적 움직임으로 해석된다. 현재 시 주석의 방북 시기와 구체적 일정은 공식 발표 없이 예정된 절차와 반응이 주목되고 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202605/21/news-p.v1.20260521.da8b89b73020400c99684c04b5886c77_P1.jpg','2026-07-27 16:08:28.949601'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'중국공산당 대외연락부 관계자들이 평양을 방문해 경호 및 의전 점검을 진행했다.','title: 트럼프 방중 이후 바빠지는 평양·베이징…김정은와 시진핑, 평양서 미북대화 퍼즐 맞추나
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1328,NULL,'정치','삼성전자 동행노조, 2026년 임금협상 잠정합의안 찬반투표 중지를 요구하며 26일 오전 9시경 수원지법에 가처분 신청을 예고했다.','삼성전자 DX 부문 중심의 동행노조는 2026년 임금협상 잠정합의안 찬반투표 중지를 요구하며 26일 수원지법에 가처분 신청을 예고했다. 이는 삼성전자 노사가 지난 20일 공동교섭단을 통해 잠정합의안을 도출한 후, 동행노조가 반도체 부문 중심의 성과급 교섭에 불만을 제기하며 4일 공동교섭단을 탈퇴한 데 따른 것이다. 동행노조는 가입자 수가 1만3000여명으로 증가했으며, 현재 잠정합의안 부결 운동을 벌이고 있으며, 투표는 27일 오전 10시까지 진행된다. 이후 가처분 신청의 법적 심리 여부와 투표 절차의 합법성, 노조 간 협의체 구성 방식에 대한 후속 논의가 예정되어 있다.',1,1,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202605/334668_479052_5024.jpg','2026-07-27 16:08:31.314810'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성전자 동행노조, 2026년 임금협상 잠정합의안 찬반투표 중지를 요구하며 26일 오전 9시경 수원지법에 가처분 신청을 예고했다.','title: 삼성전자 동행노조, 잠정합의안 찬반투표 중지 가처분 예고
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1329,NULL,'정치','2024년 2월 28일 북한 외무성 대변인이 조선중앙통신을 통해 ''비핵화는 절대적·영원히 없을 것''이라고 밝혔다.','2024년 2월 26일 쿼드 외교장관 회의에서 미국·일본·인도·호주가 ''북한의 완전한 비핵화''를 재확인하고 탄도미사일 개발 및 대량살상무기 프로그램을 규탄하며, 인도·태평양 해양 감시 협력(IPMSC) 구상을 출범시켰다. 이에 대해 북한 외무성 대변인은 28일 조선중앙통신을 통해 ''비핵화는 절대적·영원히 없을 것''이라며 쿼드를 미국의 일극지배 전략을 위한 정치외교적 도구로 규정하고, 지역 평화를 파괴하는 진영 대결 기도를 강하게 규탄했다. 또한 북한은 13일 한국과 유럽연합(EU)의 공동성명을 ''체제존중''과 ''적대행위 불추구''라는 가면을 내던진 것이라며, 한국을 ''절대 존재 불가한 제1의 적대국''으로 규정하고 적대적 관계 유지 의지를 재확인했다. 이로 인해 북한은 쿼드 및 한-EU 공동성명에 대한 반발을 지속하며, 외교적·군사적 대응 방안 논의와 대남 정책의 강경화를 예고하고 있다.',2,0,0,2,0,'https://wimg.mk.co.kr/news/cms/202605/28/news-p.v1.20260528.6c31df837a0a4ccebfd95dca9bfd6f81_P1.jpg','2026-07-27 16:08:33.159016'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 2월 28일 북한 외무성 대변인이 조선중앙통신을 통해 ''비핵화는 절대적·영원히 없을 것''이라고 밝혔다.','title: ‘북한 비핵화’ 쿼드 공동성명에…北 “비핵화 절대·영원히 없어”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1330,NULL,'정치','싱가포르 외교장관, 베이징·평양 거쳐 서울 방문','2024년 2월 28일, 비비안 발라크리쉬난 싱가포르 외교장관이 베이징과 평양을 거쳐 서울을 방문하며 조현 외교부 장관과 회담을 진행했다. 발라크리쉬난 장관은 평양에서 최선희 외무상과 회담하고 조용원 최고인민회의 상임위원장과 환담하며 7월 필리핀 ARF에 최 외무상을 초청하는 등 대화 채널 유지에 관심을 표명했다. 이 과정에서 북한은 적대적 국가 관계를 현장에서 체험했다고 발언하며, 개헌을 통한 민족·통일 개념 폐기 및 남북 접경지역 군사력 강화를 언급한 것으로 전해졌다. 싱가포르는 2018년 미북 정상회담 장소 제공 이후 중재 역할을 수행해 왔으며, 이번 연쇄 방문은 한반도 대화 재개 여건 조성에 대한 국제적 관심을 반영한 것으로 분석된다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202605/28/news-p.v1.20260528.0cb4e3f298ba40a895ad716ab4a77c1d_P1.jpeg','2026-07-27 16:08:39.244134'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 2월 28일, 비비안 발라크리쉬난 싱가포르 외교장관이 베이징과 평양을 거쳐 서울을 방문하여 조현 외교부 장관과 회담을 진행했다.','title: 베이징·평양 거쳐 서울 온 싱가포르 외교장관 “적대적 두 국가 관계 현장서 체험해”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1331,NULL,'경제','마포구, 6월 1일부터 구룡근린공원, 양화어린이공원, 삼개어린이공원 등 3개소의 바닥분수를 물놀이 가능한 시설로 개선해 운영을 시작했다.','마포구는 6월 1일부터 구룡근린공원, 양화어린이공원, 삼개어린이공원 등 3개소의 바닥분수를 물놀이 가능한 시설로 개선해 운영을 시작했다. 기존의 경관용 바닥분수에 여과기와 정화설비를 추가해 수질을 관리하고, 안전을 확보하기 위해 주 1회 저류조 청소와 물 교체, 월 1회 시설 안전점검을 실시하고 있다. 현재 마포구는 창전어린이공원, 새빛문화숲을 포함해 총 5곳에서 물놀이용 바닥분수를 운영하며, 매일 오전 11시부터 오후 6시까지 40분 가동·20분 휴식 방식으로 운영된다. 수질은 15일마다 검사해 결과를 안내판에 공개하고, 공덕오거리 교통섬 등 23개소의 경관 수경시설과 함께 여름철 쾌적한 휴식 공간을 제공하고 있다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:08:41.071710'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'마포구, 6월 1일부터 구룡근린공원, 양화어린이공원, 삼개어린이공원 등 3개소의 바닥분수를 물놀이 가능한 시설로 개선해 운영을 시작했다.','title: 시원한 물줄기 속 여름이 시작된다…마포구, 바닥분수로 더위 날리자
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1332,NULL,'정치','정동영 통일부 장관이 몽골 정부의 요청으로 3~6일 울란바타르를 방문해 제11차 울란바타르 동북아 안보대화에서 ''한반도 평화공존과 동북아 공동번영의 길''을 주제로 특별연설을 했다.','정동영 통일부 장관이 몽골 정부의 요청으로 3~6일 울란바타르를 방문해 제11차 울란바타르 동북아 안보대화에 참석하며 ''한반도 평화공존과 동북아 공동번영의 길''을 주제로 특별연설을 했다. 이 대화는 2014년부터 몽골 주도로 개최되는 1.5트랙 다자안보 대화체로, 올해는 25개국에서 약 250명이 참석했으며, 동북아 평화와 안보협력을 논의하는 자리이다. 정 장관은 후렐수흐 몽골 대통령 등 고위관계자와 면담해 한반도 평화공존 정책과 상호 존중·인정 방침을 설명하고, 남북한에 모두 상주공관을 운영 중인 몽골의 협조를 요청했으며, 평화적 두 국가 개념을 국제사회에 제시했다. 북한은 참석 의사를 밝히지 않았으나, 몽골은 남북 이산가족 상봉행사 개최 가능성 등을 남북한에 전달한 바 있어, 이번 방문이 동북아 안보 협력 기반 확대와 국제적 지지 확보에 기여할 전망이다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202606/02/news-p.v1.20260602.45ee52190f464a8a99cd3db2af335a7e_P1.jpg','2026-07-27 16:08:43.192134'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정동영 통일부 장관이 몽골 정부의 요청으로 3~6일 울란바타르를 방문해 제11차 울란바타르 동북아 안보대화에서 ''한반도 평화공존과 동북아 공동번영의 길''을 주제로 특별연설을 했다.','title: 정동영, 몽골 방문…동북아 안보대화서 ‘한반도 평화공존’ 특별연설
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1333,NULL,'정치','김정은, 새로운 HEU 생산시설 공개','김정은 북한 국무위원장은 3일 새로 조업한 고농축우라늄(HEU) 생산시설을 현지지도하며 무기급 핵물질 생산 능력이 기존의 2배를 초과했다고 밝혔다. 이는 미국과 이란의 종전 협상에서 HEU 처리를 두고 기싸움을 벌이는 상황에서 핵보유국 지위를 재차 공고화하려는 의도로, 특히 도널드 트럼프 2기 미국 행정부 출범 전후로 비핵화 대화를 전제로 한 미북 대화는 없다는 입장을 분명히 한 후의 행보다. 조선중앙통신은 시설의 위치나 규모는 밝히지 않았으나, 영변 핵단지 내에 새로 건설된 것으로 관측되며, 원심분리기 밀집 구조를 통해 농축 효율을 높인 것으로 분석된다. 이에 따라 북한의 핵물질 양산 능력과 불가역성 강화가 본격화될 전망이며, 시진핑 중국 주석의 방북을 앞두고 중국에 대한 외교적 메시지로도 해석되고 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202606/04/news-p.v1.20260604.dd912a8296874368ae94eaf33a50de0a_P1.jpeg','2026-07-27 16:08:49.674254'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'김정은 북한 국무위원장이 3일 새로 건설된 고농축우라늄(HEU) 생산시설을 공개 방문하며 무기급 핵물질 생산 능력이 기존의 2배를 초과했다고 밝혔다.','title: 북한, 새로운 우라늄 농축시설 공개…김정은 “무기급 핵물질 생산능력 2배 능가”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1334,NULL,'사회','최보윤 의원, 4일 국회의원회관 제3간담회의실에서 ''장애인권리보장법 제정, 그 이후'' 긴급 간담회를 개최했다.','4일 국회 보건복지위원회 소속 최보윤 의원은 ''장애인권리보장법 제정, 그 이후''라는 주제로 장애계와 긴급 간담회를 개최했다. 이번 간담회는 최근 국회 본회의를 통과한 장애인권리보장법의 실질적 이행을 위해 하위법령 제정과 장애인복지법 전부개정 등 법제 정비 방향을 모색하기 위해 마련됐다. 참석자들은 장애 정의의 사회적 모델 확대, 장애수당의 소득과 무관한 보전, 탈신청주의 복지 체계 도입, 생애주기별 지원 확대, 장애 분리 통계 도입 등 구체적 개정 방향을 제안했으며, 행정 혼선을 막기 위해 권리 중심의 제도 연계 필요성을 강조했다. 최 의원은 간담회에서 도출된 의견을 후속 입법 과정에 반영하고, 보건복지부와 장애계 간 정례 소통 창구를 신속히 가동해 유엔 장애인권리협약 정신을 국내 법제에 실현할 계획이라고 밝혔다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231276_127871_3239.jpg','2026-07-27 16:08:51.413130'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'최보윤 의원, 4일 국회의원회관 제3간담회의실에서 ''장애인권리보장법 제정, 그 이후'' 긴급 간담회를 개최했다.','title: 최보윤 의원, 장애계와 ‘장애인권리보장법 제정, 그 이후’ 긴급 간담회 성료
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1335,NULL,'경제','마포구, 초등학생 대상 생활과학교실 운영','마포구는 2024년 7월 6일부터 9월 18일까지 주 1회 총 10회에 걸쳐 초등학생 2~5학년을 대상으로 생활과학교실을 운영한다. 이 프로그램은 마포구에 거주하는 학생을 대상으로 하며, 이화여자대학교 생활과학교실 지역운영센터의 전문 강사진이 인공지능, 생물, 물리, 공학, 수학 등 다양한 과학 주제를 체험형 수업으로 진행한다. 수강료는 무료이나 실험 재료비 5만 원이 별도 부담되며, 기초생활수급자 등 사회적 배려계층은 반별 선착순 3명까지 재료비 전액 지원받을 수 있다. 신청은 마포구청 누리집에서 통합온라인신청으로 진행되며, 모집 인원 초과 시 전자추첨을 실시한다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:08:57.327146'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'마포구는 2024년 7월 6일부터 9월 18일까지 주 1회 총 10회에 걸쳐 마포구에 거주하는 초등학생 2~5학년을 대상으로 생활과학교실을 운영한다.','title: AI부터 생물, 수학까지…마포구와 함께하는 신나는 과학여행
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1336,NULL,'정치','젠슨 황, 네이버와 AI 팩토리 공동 구축 합의','젠슨 황 엔비디아 CEO가 8일 오후 네이버 사옥을 방문해 이해진 네이버 이사회 의장과 회동하며, 기가와트(GW)급 초대형 글로벌 AI 팩토리 구축을 위한 공동 사업을 합의했다. 이는 네이버의 국내 최대 하이퍼스케일 데이터센터 ''각 세종''을 기반으로 2027년 상반기 55MW, 같은 해 100MW, 2028년 200MW 규모로 해외 확장을 통해 글로벌 시장 진출을 추진하는 계획이다. 양사는 2027년까지 1GW급 인프라 구축을 목표로 하며, 엔비디아의 최신 GPU 수십만 장을 수용할 수 있는 규모로, 아시아·태평양을 넘어 유럽·중동 시장까지 공동 진출 방안을 논의했다. 이후 네이버는 엔비디아의 DSX 플랫폼과 자체 GPU 클러스터 기술을 융합하고, ''코스모스'' 모델에 서울 월드 모델 구축을 포함한 공간 인텔리전스 분야 협력을 확대할 예정이다.',1,1,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202606/335022_479653_3414.jpg','2026-07-27 16:09:03.687851'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'젠슨 황 엔비디아 CEO가 8일 오후 네이버 사옥을 방문해 이해진 네이버 이사회 의장과 함께 기가와트(GW)급 초대형 글로벌 AI 팩토리 구축을 위한 공동 사업을 합의했다.','title: 젠슨 황 8일 네이버 방문… “네이버·엔비디아, 초대형 AI 팩토리 구축”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1337,NULL,'경제','2024년 6월 4일 서울시 통합심의위원회가 남영동 업무지구 제2구역 도시정비형 재개발사업의 정비계획·건축·경관·교육·교통·소방·재해·환경 등 8개 분야 통합심의안을 조건부가결했다.','서울 용산구 남영동 업무지구 제2구역 도시정비형 재개발사업이 2024년 6월 4일 서울시 통합심의위원회에서 조건부가결을 받아 본격 추진된다. 이 지역은 서울지하철 1호선 남영역과 4호선 숙대입구역에 인접한 역세권으로, 노후 건축물 밀집으로 도시정비 필요성이 지속 제기되었으며, 2022년 정비구역 지정 및 2023년 조합설립인가를 거쳐 진행됐다. 이번 심의를 통해 지하 8층∼지상 최고 42층의 공동주택 3개 동과 지상 35층 업무시설 1개 동이 건설되며, 건축물 최고 높이는 기존 120m에서 150m로 상향되고 주거 비율은 57.5%에서 68.8%로 확대된다. 총 657세대가 공급되며, 재개발 의무임대주택 35세대와 공공임대주택 45세대를 포함하고, 지하 1층부터 지상 1층까지 판매시설과 운동시설이 조성되며, 약 1만5000㎡ 규모의 공공임대업무시설과 5700㎡ 규모의 남영동 복합청사가 기부채납된다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:09:05.834519'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 6월 4일 서울시 통합심의위원회가 남영동 업무지구 제2구역 도시정비형 재개발사업의 정비계획·건축·경관·교육·교통·소방·재해·환경 등 8개 분야 통합심의안을 조건부가결했다.','title: 용산구, 남영동 업무지구 제2구역 통합심의 통과…복합단지로 탈바꿈
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1338,NULL,'정치','이재명 대통령, 남북 평화공존 정책 강조','이재명 대통령은 취임 1주년 기자회견에서 북한과의 신뢰 회복을 위해 대북 확성기 방송 중단 등 선제적 긴장 완화 조치를 이어가며, 통일보다 평화공존을 우선 목표로 삼겠다고 밝혔다. 14일 이탈리아 로마에서 열린 특별미사에서는 ''칼을 쳐서 낫을 만들자''는 이사야서 메시지를 인용해 남북 평화적 협력의 필요성을 강조하며, 유럽연합 정상회의 공동성명 이후 북한의 적대적 관계 고착화 비판에 대응하는 외교적 전략을 펼쳤다. 16일 프랑스 에비앙에서 열린 G7 정상회의에서 트럼프 미국 대통령과 한반도 평화와 북핵 문제를 논의하며, 미국의 역할을 요청하고 트럼프 대통령은 이를 위한 협력 의지를 표명했다. 이어 양 정상은 한미일 협력과 한미동맹 강화, 중동 안정 등 글로벌 안보 문제에 대해 공감대를 형성하며 지속적 협의를 약속했다.',3,0,0,3,0,'https://wimg.mk.co.kr/news/cms/202606/08/news-p.v1.20260608.ba43345cafc346f8a3d6e5e59fee471b_P1.jpeg','2026-07-27 16:09:15.807298'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령은 8일 청와대 영빈관에서 열린 취임 1주년 기자회견에서 남북 간 평화공존 정책을 지속적으로 추진해 한반도 정세를 점진적으로 개선해 나가겠다고 밝혔다.','title: [속보] 이 대통령 “남북, 소통·존중하고 함께 평화공존하는 길로 가야”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1339,NULL,'사회','이재명 대통령이 8일 청와대 영빈관에서 열린 취임 1주년 기자회견에서 발달장애인들의 그림투표용지 도입 요구에 대해 ''현실적으로 불가능하다''고 밝혔다.','이재명 대통령은 취임 1주년 기자회견에서 발달장애인들이 요구한 그림투표용지 도입에 대해 ''현실적으로 불가능하다''고 밝혔다. 이는 전국 사전투표소에서 출마자가 1만 명 이상인 상황에서 모든 후보자 사진을 그림으로 반영하는 것이 기술적·운영적으로 어렵기 때문이며, 전자투표 방식을 고려할 수 있다고 제안했다. 6월 29일 사전투표 후 발달장애인 활동가들과 면담을 진행한 이후, 6월 17일 한국피플퍼스트 등 단체는 청와대 분수대 앞에서 기자회견을 열어 대통령의 발언을 환영하며 제도 개선을 위한 협의를 지속해 나가겠다고 밝혔다. 이후 대통령비서실과의 면담에서 이해하기 쉬운 선거자료, 공적 투표보조인, 모의투표 전국 실시 등 구체적 방안이 제안되었으며, 비서실은 자료를 검토 중이며 추가 논의를 약속했다.',2,0,2,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231320_127916_5341.jpg','2026-07-27 16:09:21.860468'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령이 8일 청와대 영빈관에서 열린 취임 1주년 기자회견에서 발달장애인들의 그림투표용지 도입 요구에 대해 ''현실적으로 불가능하다''고 밝혔다.','title: 이재명 대통령, "발달장애인 그림투표용지 현실 불가능, 다른 방법 찾아야"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1340,NULL,'사회','장애인공단·고용정보원, AI 고용서비스 협약 체결','2024년 4월 9일 한국장애인고용공단과 한국고용정보원은 공단 본부에서 AI 기반 고용서비스 협력체계 구축을 위한 업무협약을 체결했다. 이는 장애인 취업지원 데이터와 고용정보원의 AI 분석·매칭 기술을 결합해 취업 매칭 시스템 개선, 데이터 기반 맞춤형 서비스 제공, 디지털 접근성 향상을 목표로 하며, 2024년 하반기 중 시범 서비스를 도입하고 전국 확대를 검토한다. 한편, 한국경제인협회는 7일 서울 여의도에서 AI와 일자리의 공존을 주제로 세미나를 개최해 AI 시대에 근로자 역량 강화와 직무 재설계의 필요성을 강조하며, 중소기업과 취약계층 지원, 교육훈련 확대, 고용 친화적 AI 도입 지원 등 정책적 대응이 시급하다고 제안했다. 이는 2024년 이후 평생학습 제도 확대와 기업 지원, 역량 기반 채용·육성 생태계 구축 등 정책 논의의 핵심 과제로 부상하고 있다.',2,0,2,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231346_127951_1717.jpg','2026-07-27 16:09:28.328566'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국장애인고용공단과 한국고용정보원이 2024년 4월 9일 공단 본부에서 차세대 인공지능(AI) 고용서비스 협력체계 구축을 위한 업무협약을 체결했다.','title: 장애인공단·고용정보원, AI 기반 장애인 고용서비스 혁신 맞손
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1341,NULL,'사회','이정헌 의원, 장애인 최저임금 전면 적용 법안 발의','이정헌 더불어민주당 의원은 2024년 5월 9일 장애인 최저임금 적용 제외 규정 폐지를 골자로 한 ''장애인 소득·안전 보장 3법''을 대표발의했다. 현행 최저임금법 제7조는 정신·신체장애로 근로능력이 현저히 낮은 사람에 대해 고용노동부장관 인가를 받으면 최저임금 적용을 제외할 수 있도록 규정하고 있으며, 이는 1988년 최저임금법 시행 이후 38년간 유지되어 왔다. 이번 개정안은 최저임금을 장애 여부와 관계없이 모든 근로자에게 전면 적용하도록 제도를 개선하고, 중증장애인 고용을 유도하기 위해 고용노동부장관이 임금 일부를 지원할 수 있도록 근거를 마련했다. 또한 다중이용시설의 피난안내도 점자 제작과 피난안내 영상에 한국수어 통역·자막 제공을 의무화하고, 위반 시 과태료 부과 조항을 신설해 장애인의 안전권 보장을 강화했다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231354_127952_5657.png','2026-07-27 16:09:35.917792'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이정헌 더불어민주당 의원이 2024년 5월 9일 장애인 최저임금 적용 제외 규정 폐지를 골자로 한 ''장애인 소득·안전 보장 3법''을 대표발의했다.','title: 이정헌 의원, 장애인 최저임금 전면 적용 ''''장애인 소득·안전 보장 3법'' 발의
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1342,NULL,'사회','장애인고용공단, 2026년 고용컨설팅 추진 논의','2026년도 대기업 장애인 고용촉진 협의체 간담회에서 한국장애인고용공단은 장애인 고용컨설팅 사업의 추진 방향을 논의했다. 이는 장애인 고용 확대와 고용 유지 지원을 위한 기업과의 협력 강화를 목적으로 하며, 2026년도 사업의 운영 개선과 장애 대학생의 노동시장 진입 지원 방안을 중심으로 논의되었다. 현재까지 장애인 고용컨설팅 사업은 기업의 고용 안정성 제고와 장애 근로자의 장기근속을 목표로 하고 있으며, 현장에서의 개선 필요성과 컨설팅의 지속 가능성에 대한 의견이 제기되었다. 향후 공단은 협의체와의 지속적 소통을 통해 장애인 고용 친화적 환경 조성과 정책 발전 방향을 모색할 예정이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231404_128020_5240.jpg','2026-07-27 16:09:43.540377'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국장애인고용공단이 11일 ‘2026년도 대기업 장애인 고용촉진 협의체 간담회’를 개최하고 장애인 고용컨설팅 사업 추진 방향을 논의했다.','title: ‘2026년도 대기업 장애인 고용촉진 협의체’ 장애인 고용컨설팅 추진 논의
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1343,NULL,'사회','국회, 장애인 고용부담금 중과 검토 제안','국회예산정책처는 민간기업의 장애인 고용 확대를 위해 기업 규모별 차등 적용과 완전미고용기업에 대한 고용부담금 중과를 검토해야 한다고 제안했다. 우리나라 장애인 고용률은 2023년 기준 48.3%로 독일·프랑스·영국보다 낮으며, 2024년 민간기업 의무고용이행률은 42.4%로 전년 대비 감소 추세다. 특히 근로자 100인 미만 기업의 고용이행률은 32.0%로 하락하고, 완전미고용기업 비중이 33.4%에 달해 소규모 기업의 고용 기반이 취약한 상황이다. 국회는 2026년까지 의무고용률을 공공 3.8%, 민간 3.1%로 상향하고, 독일·프랑스 사례를 참고해 완전미고용기업에 대한 부담금 중과 및 기업 규모별 차등 적용 방안을 도입할 필요성을 강조했다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231405_128021_053.png','2026-07-27 16:09:52.507469'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국회예산정책처는 민간기업의 장애인 고용 확대를 위해 기업 규모별 차등 적용과 완전미고용기업에 대한 고용부담금 중과를 검토해야 한다고 제안했다.','title: 민간기업 장애인 고용 한명도 안 한다? 국회 "고용부담금 중과해야"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1344,NULL,'정치','JTBC가 2026년 6월 12일 206억 원 규모의 유동화 차입금 일부를 상환하지 못해 나이스신용평가로부터 무보증사채 신용등급을 BBB/부정적에서 CCC로 하향 조정받았다.','JTBC는 2026년 6월 12일 유동화차입금 206억 원 중 일부를 상환하지 못해 나이스신용평가와 한국기업평가로부터 무보증사채 신용등급을 각각 BBB/부정적에서 CCC, BBB 부정적에서 BB로 하향 조정받았다. 이는 미르제이차 56억 원과 제일티비씨제이차 150억 원의 상환 불이행 발생으로 인한 유동성 위험 증가와 방송광고시장 위축, 콘텐츠 투자 부담 증가, 당기순손실 누적 및 차입금 증가 등 재무적 악화가 원인으로 분석된다. 단기신용등급도 기업어음과 전자단기사채 모두 A3에서 C로 하향 조정되며, 기업의 적기상환능력에 대한 의문이 제기됐다. JTBC는 방송 콘텐츠 제작과 방영은 정상 운영 중이며, 유동성 위기 극복을 위해 비상경영체제를 가동하고 있으며, 대·내외적 수단을 동원해 최선을 다할 것이라고 밝혔다.',1,1,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202606/335150_479871_3143.jpg','2026-07-27 16:09:54.525089'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'JTBC가 2026년 6월 12일 206억 원 규모의 유동화 차입금 일부를 상환하지 못해 나이스신용평가로부터 무보증사채 신용등급을 BBB/부정적에서 CCC로 하향 조정받았다.','title: JTBC, 206억 채무불이행 신용등급 CCC 강등… “최선 다할 것”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1345,NULL,'정치','이재명 대통령, 기자 선행매매 자수 촉구','이재명 대통령은 2025년 12월 13일 X 계정을 통해 금융감독원 특별사법경찰이 12일 구속한 기사 브로커 A씨와 현직 기자 등 2명을 중심으로 드러난 선행매매 사건을 언급하며, 관련 기자들에게 자수를 촉구했다. 조사에 따르면, 공인회계사 출신 브로커 지시 하에 3명의 기자가 2000건 이상의 기사를 작성해 주가조작을 벌였으며, 일부는 기사 노출 직전 3초 전 매수, 8초 후 매도 방식으로 90억 원 이상의 부당이익을 취한 것으로 확인됐다. 현재 수사가 진행 중이며, 주가 변동과 매매 내역이 정밀 분석되고 있다. 정부는 기자들의 부정행위에 대한 처벌 강화와 언론 윤리 제도 개선을 포함한 후속 조치를 검토 중이며, 언론노조는 취재 정보를 금융투자에 활용하지 말라는 가이드라인을 제정했다.',2,2,0,0,0,'https://cdn.mediatoday.co.kr/news/photo/202606/335156_479879_710.jpg','2026-07-27 16:10:02.078204'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령이 2025년 12월 13일 X 계정을 통해 기자 선행매매 사례를 언급하며 관련자들에게 자수를 촉구했다.','title: 이재명 대통령, 기사로 90억 챙긴 기자 선행매매 언급하며 “자수하라”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1346,NULL,'정치','트럼프, 김정은과 산책 사진 공개','트럼프 미국 대통령이 2024년 5월 중순 예정된 방중을 계기로 김정은 북한 국무위원장과의 정상회담 재개 가능성을 시사하며, 2018년 6월 12일 싱가포르에서 열린 제1차 북미정상회담 당시 산책하는 사진을 SNS에 공개했다. 이는 이란 문제 해결 후 북한 문제로의 관심 전환 가능성을 시사하며, 2018년 회담에서 합의된 한반도 완전한 비핵화와 평화체제 구축 방향에 대한 재확인을 의미한다. 정동영 통일부 장관은 사진 공개를 계기로 트럼프 대통령과 김정은 간 친서외교 재개 가능성을 제기하며, 과거 하노이 회담의 ''노딜'' 실패를 반면교사로 삼아 대화 재개와 평화공존을 강조했다. 현재까지 구체적 친서 교환 사실은 확인되지 않았으나, 미·북 대화 재개 가능성과 한반도 정세 전환 여부가 주목받고 있다.',2,0,0,2,0,'https://wimg.mk.co.kr/news/cms/202606/14/news-p.v1.20260614.649fceefbd0447ba87592cd78809c684_P1.jpg','2026-07-27 16:10:24.168802'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'트럼프 미국 대통령이 2018년 6월 12일 싱가포르에서 열린 제1차 북미정상회담 당시 김정은 북한 국무위원장과 함께 산책하는 사진을 SNS에 공개했다.','title: “이란 다음은 북한?”…트럼프, 과거 김정은과 산책 사진 깜짝 공개
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1347,NULL,'정치','중앙그룹 계열사 회생절차 신청','2024년 5월 15일 중앙그룹 계열사 5곳( JTBC, 콘텐트리중앙, 메가박스중앙, 중앙홀딩스, 중앙피앤아이)이 법원에 기업회생절차를 신청했다. 이는 유동화 차입금 상환 실패와 채무불이행으로 인한 재무 위기로, 홍정도 부회장이 사과하며 회생 절차의 필요성을 밝혔다. 방송미디어통신위원회는 월드컵 중계 등 공적 역할을 고려해 상시 모니터링을 시작했고, JTBC는 자율구조조정 프로그램을 승인받아 운영 중이다. 그러나 임직원 복지 포인트 소멸, 법인카드 중단, 연기자 출연료 수십억 원 미지급 등 내부 혼란과 투자자·노동조합의 집단 반발이 지속되고 있으며, 중앙일보는 사옥 매각을 통한 자산 유동화와 워크아웃 추진으로 독립 운영을 유지하고 있다.',7,6,1,0,0,'https://cdn.mediatoday.co.kr/news/photo/202606/335180_479924_5641.png','2026-07-27 16:10:44.499923'::timestamp,'2026-07-27 18:59:56.324979'::timestamp,NULL,NULL,'검색 후보 없음','2024년 5월 15일, 홍정도 중앙그룹 부회장은 JTBC, 콘텐트리중앙, 메가박스중앙, 중앙홀딩스, 중앙피앤아이 등 5개 계열사가 법원에 회생절차를 신청했다','title: 홍정도 중앙그룹 부회장, 직원들에게 “송구해... 노력이 모이면 위기 극복할 수 있어”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1348,NULL,'사회','장애인공단·강동대, 장애대학생 취업역량 협약','한국장애인고용공단과 강동대학교는 2024년 4월 16일 강동대학교에서 장애대학생 취업역량 강화 및 취업 활성화를 위한 업무협약을 체결했다. 이번 협약은 장애대학생의 취업 장벽을 낮추고 기업 수요에 부합하는 인재를 양성하기 위해, 공단의 전문성과 강동대학교의 교육 인프라를 결합하려는 목적을 가졌다. 양 기관은 장애대학생 인력풀 구축, 전문가 연계, 진로·취업 상담, 맞춤형 취업지원 등 다양한 분야에서 협력할 예정이며, 이를 통해 장애대학생의 취업률 향상과 사회적 자립을 목표로 하고 있다. 향후 협약 이행 상황과 효과에 따라 장애인 고용 활성화 모델의 확산 여부와 정부 정책에 대한 반영 가능성 등이 주요 쟁점이 될 전망이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231478_128116_499.jpg','2026-07-27 16:11:16.863291'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국장애인고용공단과 강동대학교가 2024년 4월 16일 강동대학교에서 장애대학생 취업역량 강화 및 취업 활성화를 위한 업무협약을 체결했다.','title: 장애인공단·강동대학교, 장애대학생 취업역량 강화·활성화 협력
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1349,NULL,'사회','학대피해 장애인 녹음금지 예외 인정 촉구 집회 예고','2024년 4월 22일, 전국장애인부모연대 등이 모인 대책위가 대법원 앞에서 학대피해 장애인의 권리보장을 위해 제3자 녹음금지 예외를 인정할 것을 촉구하는 1차 집회를 예고했다. 이는 자폐성 장애아동 학대 의심 사건에서 어머니가 교실 내 발언을 녹음한 행위가 통신비밀보호법 위반 여부를 놓고 1심은 증거능력을 인정했으나 2심은 이를 배제해 무죄 판결이 나면서 발생한 법적 쟁점이다. 현재 대법원은 해당 사건을 계류 중이며, 녹음이 학대 피해 입증의 유일한 수단이 되는 중증장애인·치매노인 등에 대한 일률적 증거 배제는 헌법상 실질적 평등과 인권 보호에 반한다는 지적이 제기되고 있다. 대책위는 미국·영국·독일·일본 등 주요국의 사례를 들어 사안별로 녹음 증거의 허용을 촉구하며, 법률가 112명이 의견서를 제출해 헌법합치적 해석을 요구했고, 온라인 탄원서 모집도 진행 중이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231522_128169_2613.jpg','2026-07-27 16:12:00.437455'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 4월 22일, 전국장애인부모연대 등이 모인 대책위가 대법원 앞에서 학대피해 장애인 권리보장을 위한 제3자 녹음금지 예외 촉구 1차 집회를 연다.','title: "학대피해 장애인에 대해 녹음금지 예외 인정해야" 대법원 앞 집회 예고·탄원도
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1350,NULL,'정치','국방부, 국방백서 주적 표현 유지 결정','국방부는 2026 국방백서에서 북한 정권과 북한군을 ''주적''으로 규정하는 방침을 유지할 예정이며, 북한의 대남 핵타격 전력 증강과 적대적 태도를 근거로 삼고 있다. 반면 통일부는 남북 평화공존 정책과의 모순을 이유로 주적 표현을 재검토해야 한다며, 국가안전보장회의(NSC) 상임위원회에서 논의를 요청했다. 국방부와 통일부 간의 정책적 입장 차이가 명확히 드러나며, NSC에서의 논의 결과에 따라 국방백서의 표현이 수정될 가능성도 제기되고 있다. 이는 남북 관계의 방향성과 국방 정책의 근본적 조정을 의미할 전망이다.',2,0,0,2,0,'https://wimg.mk.co.kr/news/cms/202606/18/news-p.v1.20260618.183ca4e6b6674690a109e42362d4d44a_P1.jpg','2026-07-27 16:12:06.875256'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국방부, 2026 국방백서에서 북한 정권과 북한군을 적으로 규정할 방침을 유지하기로 결정했다.','title: 국방부-통일부, 국방백서 ‘북한은 주적’ 표현 두고 입장차 드러내
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1351,NULL,'사회','국회, 특수학급 설치 계획 의무화 법안 통과','국회는 2024년 3월 18일 ''특수교육법'' 일부개정안을 통과시켜 각 시도 교육감이 매년 특수학급 설치 계획을 교육부 장관에게 제출하도록 의무화했다. 기존 법은 특수학교 및 각급학교의 특수학급 설치 기준을 정했지만, 교육청의 대응 부족으로 학교 현장에서 수요에 비해 학급이 부족한 문제가 지속됐다. 이번 개정으로 지역별 특수교육 수요를 반영한 연차별 계획 수립이 법적으로 보장되며, 장애학생의 원거리 통학 문제 해소와 교육 환경 개선이 기대된다. 이후 교육부는 각 교육청의 계획을 검토하고, 특수교육 연차보고서에 반영하는 절차를 진행할 예정이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231533_128184_530.jpg','2026-07-27 16:12:16.787730'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국회는 2024년 3월 18일 ''특수교육법'' 일부개정안을 통과시켜 각 시도 교육감이 매년 특수학급 설치 계획을 교육부 장관에게 제출하도록 의무화했다.','title: 장애학생 교육환경 개선, ''매년 특수학급 설치계획 의무화'' 국회 통과
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1352,NULL,'사회','장애학생 교육권 차별 집단 진정','19일 장애인교육아올다를 비롯한 10개 단체는 국가인권위원회 앞에서 장애 등 특별지원이 필요한 아동·청소년의 교육권 차별 문제를 이유로 집단 진정을 제기했다. 이들은 건강장애와 중증식품알레르기, 최중증뇌병변장애, 발달장애, 청각장애 등 다양한 장애 유형의 학생들이 어린이집 입학 거부, 각서 요구, 수어 통역 부재, 의료 지원 인력 부족 등으로 교육 현장에서 배제되고 있다고 주장했다. 특히 중증식품알레르기 학생은 외식을 한 번도 하지 못했고, 학부모가 매일 도시락을 준비하거나 학교에 상주해야 했으며, 현장체험학습과 방과 후 수업 참여도 부모 동행 없이는 불가능한 상황이었다. 이들 단체는 인권위의 면담 조사와 포럼을 통해 교육기본권 침해 문제를 지속적으로 제기하고, 정부가 전담간호사 배치, 특수교육지원인력 확충, 평생교육 기관 설치 등 근본적 대안을 마련할 것을 촉구했다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231558_128229_2817.jpg','2026-07-27 16:12:52.439161'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'19일 장애인교육아올다를 비롯한 10개 단체가 국가인권위원회 앞에서 장애 등 특별지원이 필요한 아동·청소년의 교육권 차별 문제를 이유로 집단 진정을 제기했다.','title: ‘입학 거부·각서 요구·수어 지원 부재’ 학교 안에서 배제된 학생들
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1353,NULL,'정치','이란군, 호르무즈 해협 통행 제한','이란은 2024년 5월 17일 이스라엘과의 종전 합의 체결 후 3일 만에 호르무즈 해협의 선박 통행을 제한하며 재봉쇄에 들어갔다. 이는 미국의 MOU 이행 미이행과 이스라엘군의 지속적 공습을 계기로 한 조치로, 해상 운송이 중단되며 국제 에너지 수송에 영향을 미쳤다. 이후 6월 19일 미국과 이란은 스위스에서 호르무즈 해협 전면 재개방 합의를 발표하며 해협 통행을 재개했으며, 6월 마지막 주에는 원유 수송량이 전주 대비 1218.8% 증가한 422만 DWT를 기록했다. 이어 10일 HMM의 ''유니버설 위너''호가 울산에 도착해 원유 하역을 완료하며 국내 수송 체계 회복의 신호를 보였다.',3,2,1,0,0,'https://cdn.mediatoday.co.kr/news/photo/202606/335297_480156_4621.jpg','2026-07-27 16:13:27.819739'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이란군은 20일(현지시간) 미국이 종전 양해각서(MOU) 제1조를 이행하지 않았다며 호르무즈 해협의 선박 통행을 허용하지 않겠다고 밝혔다.','title: 이란군, 호르무즈 해협 다시 봉쇄한다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1354,NULL,'국제','일본은행, 정책금리 1.0%로 인상','2025년 6월 16일 일본은행은 정책금리를 0.75%에서 1.0%로 31년 만에 최고 수준으로 인상했다. 이는 다카이치 사나에 총리가 영국·프랑스·이탈리아 순방과 G7 정상회의를 마치며 ''경제안보 동맹 외교''를 강화하는 가운데 이뤄진 것으로, 중국 견제와 영유럽과의 협력을 통한 ''다카이치노믹스 2.0''의 핵심 전략이다. 일본은 2026년도 본예산으로 사상 최대인 122조 엔을 편성하고, 적극 재정을 추진하며, 동시에 금리 인상으로 통화 정상화를 추진하고 있다. 이에 따라 일본의 금리·엔화 향방, 공급망 재편, 동북아 안보 비용 증가 등이 한국 경제에 영향을 미칠 전망이며, 시장과 전문가들은 재정 지속 가능성과 일본은행의 독립성 존중을 주문하고 있다.',1,0,1,0,0,'https://cdn.sisajournal.com/news/photo/202606/376869_384652_2615.jpg','2026-07-27 16:13:44.643878'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2025년 6월 16일 일본은행은 정책금리를 0.75%에서 1.0%로 인상했다.','title: 中 때리고, 英 손잡고…드러난 ‘다카이치노믹스 2.0’ 청사진
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1355,NULL,'사회','정신의료기관, 전과 환자 입원 시 보호의무자 2명 동의 요구','국가인권위원회는 2025년 9월, 정신의료기관에 전과된 환자가 1개월 이상 다른 병원에서 치료를 받은 후 복귀할 경우 보호의무자 2명 이상의 동의와 전문의 진단을 거쳐야 입원 절차를 다시 진행해야 한다고 판단했다. 이는 정신건강복지법 제43조 및 국립정신건강센터의 안내에 따라 전과 기간이 30일 이상일 경우 퇴원 처리가 원칙이기 때문이며, 해당 병원은 2025년 5월부터 9월까지 3개 병원에서 치료를 받은 진정인을 복귀 시 배우자 1명의 동의만으로 입원시켰다. 인권위는 이 과정에서 보호의무자 2명 이상의 동의와 전문의 진단이 이뤄지지 않아 신체의 자유 침해로 인권 침해로 판단했으며, 병원장에게 퇴원 신청 시 즉시 퇴원 처리하고 직원 대상 입·퇴원 절차 교육을 실시할 것을 권고했다. 이 사건은 정신질환자 입원 절차의 법적 준수 여부와 보호의무자 수의 중요성에 대한 제도적 쟁점으로 이어지고 있으며, 향후 병원의 절차 개선과 교육 시행 여부가 주목된다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231580_128260_5348.jpg','2026-07-27 16:13:51.379797'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2025년 9월, 해당 정신의료기관은 전과 기간이 1개월 이상인 진정인을 복귀시켜 배우자 1명의 동의만으로 입원시켰다.','title: “정신병원 입원 중 다른 병원 전과기관 1개월 넘으면 입원 절차 다시 거쳐야”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1356,NULL,'사회','장애인기업 경기 체감 지수 상승','2026년 5월 장애인기업종합지원센터는 장애인기업의 경기 체감 지수(BSI)가 전월 대비 2포인트 상승한 95.7p, 6월 경기 전망 지수는 2.6포인트 상승한 101.9p로 나타났다. 이는 전반적인 경기 회복세를 반영하며, 강원권과 수도권, 경상권 등 주요 지역과 제조업, 서비스업 등 업종에서 상승세를 보였으나 충청권과 제주권 등 일부 지역과 도소매업, 건설업은 하락했다. 장애 정도별로는 심한 장애 기업의 체감 지수가 93.1p에서 7.9포인트 상승했으며, 전망 지수는 105.7p로 중증 장애 기업의 회복세가 두드러졌다. 센터는 내수 변화에 대응하기 위해 공영홈쇼핑 및 경기청년복지몰 연계 사업을 확대하고, 해외 온라인 쇼핑몰 입점 지원과 수출상담회 규모 확대를 통해 판로 다각화를 추진할 계획이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231607_128292_5146.png','2026-07-27 16:14:17.714659'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'장애인기업종합지원센터가 2026년 5월 장애인기업 동향 조사 결과를 23일 발표했다.','title: 5월 장애인기업 경기 체감·전망지수 상승‥완만한 회복세
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1357,NULL,'사회','2026년 지방장애인기능경기대회 개최','2026년도 지방장애인기능경기대회는 7월 1일부터 10일까지 전국 4개 권역(수도권, 중부권, 영남권, 호남권)에서 순차적으로 개최되며, 고용노동부 주최, 한국장애인고용공단 주관으로 진행된다. 총 2766명의 장애인 선수가 정규직종 17개, 시범직종 5개, 레저직종 3개 등 25개 직종에 참가하며, 입상자에게는 상장, 메달, 상금(최고 50만원) 및 기능사 실기시험 면제 혜택이 주어진다. 특히 발달장애인기능경기대회는 수도권에서 1일 일산직업능력개발원에서 시작되어 데이터입력, 바리스타, 영상콘텐츠편집, 사무행정, 요양보호보조, e스포츠 등 6개 직종에서 149명이 참가해 총 16명이 입상했다. 정규직종 금상 수상자는 9월 부산에서 열리는 전국장애인기능경기대회 출전 자격을 부여받으며, 이는 장애인의 직업능력 향상과 고용 기회 확대를 위한 제도적 지원의 일환으로 이어진다.',3,0,3,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231613_128305_4744.png','2026-07-27 16:14:28.606914'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'고용노동부가 주최하고 한국장애인고용공단과 한국장애인고용안정협회가 주관하는 ‘2026년도 지방장애인기능경기대회’가 24일부터 26일까지 전국 17개 시도에서 개최된다.','title: ‘2026년도 지방장애인기능경기대회’ 24~26일 개최‥2766명 참가
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1358,NULL,'경제','정부가 전세사기 방지를 위해 ''126% 룰''을 도입했다.','정부가 전세사기 방지를 위해 도입한 ''126% 룰''이 빌라 전세 시장을 마비시켰다. 이 규제는 공시가격과 담보인정비율을 기준으로 전세보증금의 보증보험 가입 한도를 제한하며, 실제 시세와 공시가격의 괴리로 인해 빌라 전세보증금이 2억2000만 원을 초과하면 보호를 받지 못하게 한다. 결과적으로 세입자는 경매 시 보호받지 못하고 보증금 손실 위험이 커지며, 이로 인해 아파트 전세로의 전환을 선택하는 등 전세 시장의 불균형이 심화되고 있다. 이에 전세권 설정 등기 의무화, 전세 에스크로 제도 도입, 공인중개사의 무한 연대책임 법 개정 등 세입자 보호를 위한 제도 개선이 필요하다는 주장이 제기되고 있으나, 정부는 여전히 전세대출 규제와 공공임대 매입에 집중하고 있어 정책의 균형성에 대한 비판이 제기되고 있다.',1,1,0,0,0,'https://www.pressian.com/_resources/10/2026/06/24/2026062407533727439_l.jpg','2026-07-27 16:14:41.282524'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정부가 전세사기 방지를 위해 ''126% 룰''을 도입했다.','title: 정부 잘못된 규제가 세입자 ''영끌'' 매매판으로 등떠밀었다hellip;세입자 안전망 마련해야
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1359,NULL,'정치','김정은, 5000t급 구축함 실전배치','북한은 2024년 5월 23일 남포항에서 5000t급 신형 구축함 ''최현호''의 취역식을 개최하고 김정은 국무위원장이 참석해 실전 배치를 발표했다. 이어 7월 3일 김정은은 같은 규모의 ''강건호'' 구축함의 무기체계 시험을 참관하며 2개월 내 취역을 지시했으며, 이는 지난해 좌초 사고 이후의 복귀를 의미한다. 두 함정은 해상 전력 강화와 원해 전략 타격 능력 확보를 위한 전략적 전환의 일환으로, 향후 5년간 매년 2척씩 5000t급 이상 수상함을 건조하고, 전략유도탄순양함과 수중 무기체계도 개발할 계획이다. 이에 따라 북한의 해군 중심 기지 확충과 중국·러시아 해군과의 연합훈련 가능성도 주목받고 있다.',2,0,0,2,0,'https://wimg.mk.co.kr/news/cms/202606/24/news-p.v1.20260624.70a61b14fce9402db6c7d8f3a7f7d52b_P1.jpeg','2026-07-27 16:14:49.429291'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'김정은 국무위원장이 2024년 5월 23일 남포항에서 열린 최현호 취역식에서 5000t급 신형 구축함 ''최현호''를 서해에 실전배치했다.','title: 北, 5000t급 신형구축함 최현호 서해에 실전배치…김정은 “핵무력 다각적·효과적 운용”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1360,NULL,'경제','증권사 ''빚투'' 금액 역대 최대','2026년 5월 말 기준 증권사 ''빚투'' 금액은 39조4000억 원으로, 전년 동기 대비 두 배 이상 증가하며 역대 최대치를 기록했다. 이는 레버리지 ETF 및 지수선물·옵션 거래 확대와 함께 신용융자 잔액이 최근 5년 평균 대비 17조9000억 원 증가한 결과로, 올해 1분기 연체진입률은 5.5%로 장기평균을 상회하고 장기연체차주 비중도 8.0%로 전년 대비 증가했다. 금감원은 가계신용 레버리지(88.2%)와 기업신용 레버리지(110.4%)가 선진국 및 신흥국 평균을 상회하는 상황에서 시장 변동성 확대와 취약차주 증가 가능성을 우려하며, 신용융자 및 증권담보대출 지표를 상시 모니터링하고 과도한 레버리지 투자 위험을 투자자에게 지속 안내할 계획이다. 또한 보험대리점의 불건전 영업행위 방지를 위해 이해상충 업무 겸영 금지 범위를 확대하고, 보험 수수료 개편 방안도 차질 없이 이행할 예정이다.',2,2,0,0,0,'https://www.pressian.com/_resources/10/2026/06/24/2026062411530358071_l.jpg','2026-07-27 16:14:58.468896'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 5월 말 기준 한국 투자자가 증권사에서 빌린 ''빚투'' 금액이 39조4000억 원으로 집계되었다.','title: ''빚투''에 지른 돈, 1년새 두배 급증hellip; 증권사 ''빚투'' 금액만 39.4조, 역대 최대
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1361,NULL,'정치','이재명 대통령, 6·25전쟁 기념식에서 참전용사 기리기','이재명 대통령은 2024년 6월 25일 경기도 수원컨벤션센터에서 열린 6·25전쟁 제76주년 기념식에서 참전용사들의 희생을 기리며 국가의 평화와 번영이 그들의 헌신에서 비롯됐다고 강조했다. 76년 전 대한민국은 전쟁의 위기 속에 있었으며, 학도병과 평범한 시민들이 총을 들며 국토를 지키는 희생을 감행했고, 이는 오늘의 민주주의와 번영의 기반이 됐다. 최근 시행된 참전유공자법 개정으로 유족까지 보훈단체 회원 자격이 확대되었으며, 고 김장성, 이영복, 고 전하정 등 3명의 비정규군 공로자에게 신규 포상이 진행됐다. 이 대통령은 영웅들의 헌신을 기리는 것이 국가의 책무이며, 유엔 참전용사에 대한 감사와 국제적 책임을 강조하며, 앞으로도 보훈 제도를 강화해 후대에 이어질 수 있도록 하겠다고 밝혔다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202606/25/rcv.YNA.20260625.PYH2026062507230001300_P1.jpg','2026-07-27 16:15:08.039833'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령이 2024년 6월 25일 경기도 수원컨벤션센터에서 열린 6·25전쟁 제76주년 기념식에서 참전용사들의 희생을 기리며 국가의 평화와 번영이 그들의 헌신에서 비롯됐다고 강조했다.','title: 이재명 대통령 “영웅들이 만든 위대한 대한민국…흔들림 없이 지켜나갈 것”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1362,NULL,'사회','청각장애인 복직 후 업무 배치 및 인권위 권고 거부','2024년 2월, A병원은 청각장애가 있는 간호사 출신의 보험심사관리사가 육아휴직 후 복직하자 건강검진센터에 배치했으며, 이에 대해 국가인권위원회는 차별 행위로 판단하고 특별인권교육 수강과 인사 매뉴얼 마련, 장애차별 예방교육 실시를 권고했다. 진정인은 병원 업무 중 청각장애가 발생한 후 보험심사 업무를 수행해 왔으나, 복직 후 건강검진센터 업무로 배치되면서 업무 적합성과 차별을 주장했다. 병원 측은 사전 면담을 통해 동의했고, 업무 성격이 유사하며 정원 초과로 인해 추가 배치가 불가능했다며 인권위 권고를 거부했다. 인권위는 병원의 불수용을 유감스럽게 여기며 장애인차별금지법 제42조에 따라 법무부장관에게 통보했으며, 향후 법적 조치 가능성과 제도 개선이 쟁점으로 부각되고 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231651_128344_3059.jpg','2026-07-27 16:15:18.253213'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 2월, A병원은 청각장애가 있는 보험심사관리사가 육아휴직 후 복직하자 건강검진센터에 배치했다.','title: 청각장애인 육아휴직 복직하자 건강검진센터 배치, 인권위 권고도 거부
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1363,NULL,'사회','장애여성 모성권 보장 법제 정비 촉구','국가인권위원회는 2022년 유엔 장애인권리위원회의 지적을 바탕으로, 장애여성들이 임신·출산·양육 전 과정에서 정보 부족, 의료 접근성 문제, 사회적 편견 등 교차적 차별을 경험하고 있음을 확인했다. 조사 대상 669명의 장애여성 중 11.3%만이 장애친화 산부인과를 이용했으며, 주요 이유로는 장애친화 산부인과를 모른다는 응답이 48.9%에 달했다. 응답자들은 임신 중 가장 어려운 점으로 ''장애인 맞춤 정보 부족''을 꼽았고, ''자녀를 입양해서는 안 된다''는 인식적 차별이 가장 높은 차별로 인식됐다. 보고서는 장애인복지법과 모자보건법에 모성권 보장 조항을 명시하고, 자기결정권과 양육권, 안전한 양육 환경까지 포괄하는 법제 정비가 필요하다고 제안했다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231655_128349_3310.jpg','2026-07-27 16:15:30.380627'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국가인권위원회는 2022년 유엔 장애인권리위원회의 지적을 바탕으로 장애여성들이 임신·출산·양육 전 과정에서 교차적 차별을 경험하고 있음을 확인했다.','title: 임신·출산·양육 전 과정서 교차적 차별‥‘장애여성 모성권’ 보장 미흡
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1364,NULL,'경제','MBK, 홈플러스 기업회생절차 신청','홈플러스는 2024년 3월 서울회생법원의 기업회생절차 폐지 결정을 받으며 파산 절차 진입이 확정됐다. MBK파트너스의 2015년 인수 이후 2016년부터 2024년까지 28개 점포와 물류창고를 매각하며 자산 유동화를 추진했으나, 임차료 부담 증가와 온라인 전환 실패로 EBITDA가 2019년 7351억원에서 2023년 3214억원으로 감소했고, 2021년부터 2023년까지 5년 연속 적자로 누적 손실 2조7341억원을 기록했다. 2024년 5월 기준 공익채권은 1조999억원으로 증가했으며, 익스프레스 매각으로 확보한 1,206억원 중 실제 활용 가능한 자금은 756억원에 그쳤다. 현재 2천억원 규모의 신규 자금 조달 논의가 진행 중이나, 대주주인 MBK파트너스의 개입이 임금 체불 및 협력사 피해 최소화의 핵심 과제로 부각되고 있다.',7,5,1,1,0,'https://www.pressian.com/_resources/10/2026/06/30/2026062415254640154_l.jpg','2026-07-27 16:15:38.842953'::timestamp,'2026-07-27 19:01:55.478480'::timestamp,NULL,NULL,'검색 후보 없음','2025년 3월 홈플러스는 MBK파트너스의 차입매수(LBO) 방식 인수 후 부채비율이 1400%를 초과하며 서울회생법원에 기업회생절차(법정관리)를 신청했다.','title: ''흡혈귀 경영'' MBK는 어떻게 홈플러스를 망가뜨렸나?
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1365,NULL,'사회','김예지 의원, 중증장애인 기업 대표자 업무지원인 제도 확대 법안 발의','국민의힘 김예지 의원은 26일 중증장애인 기업 대표자도 업무지원인 서비스를 받을 수 있도록 하는 ''장애인기업활동 촉진법 일부개정법률안''을 대표발의했다. 현행법은 중증장애인 기업 대표자를 근로자로 보지 않아 업무지원인 제도 대상에서 제외해 왔으며, 소규모 기업(종사자 10명 이하) 중 94.3%가 중증장애인 대표자인 것으로 조사됐다. 이로 인해 대표자가 업무를 수행하는 데 어려움을 겪고 있으며, 업무지원인 서비스를 받을 수 없어 경영 부담이 크다. 이번 개정안은 소상공인인 장애인기업 대표자를 업무지원인 지원 대상에 포함시켜 영세 기업 대표자의 경영 안정성을 높이고, 후속적으로 예산 및 지원체계 확충이 필요하다는 점이 쟁점으로 부각되고 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231669_128363_232.jpg','2026-07-27 16:15:51.469630'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국민의힘 김예지 의원이 26일 중증장애인 기업 대표자도 업무지원인 서비스를 받을 수 있도록 하는 ''장애인기업활동 촉진법 일부개정법률안''을 대표발의했다.','title: 영세 장애인기업 중증장애인 대표자도 ‘업무지원인 지원 확대’ 추진
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1366,NULL,'국제','2026 FIFA 월드컵 아시아 2차 예선 D조에서 한국은 26일 호주와 0-0 무승부를 기록했다.','2026 FIFA 월드컵 아시아 2차 예선 D조에서 한국은 26일 호주와 0-0 무승부를 기록하며 32강 진출 가능성이 크게 줄었다. 한국은 이전까지 파라과이와의 경기에서 승리해 32강 진출을 앞두고 있었으나, 호주와의 무승부로 인해 진출 조건을 충족하지 못했다. 현재 한국은 32강 진출 확률이 55.10%로 낮아졌으며, 나머지 2경기에서 승리해야만 진출 가능성이 생긴다. 이후 남은 경기 결과에 따라 진출 여부가 결정되며, 특히 파라과이와의 마지막 경기에서 승리해야만 32강 진출이 가능하다.',1,0,1,0,0,'https://cdn.sisajournal.com/news/photo/202606/377881_385609_017.jpg','2026-07-27 16:15:53.351088'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026 FIFA 월드컵 아시아 2차 예선 D조에서 한국은 26일 호주와 0-0 무승부를 기록했다.','title: 호주-파라과이 무승부…더 멀어진 한국 32강 진출
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1367,NULL,'국제','미국-이란 무력 충돌 재개','2023년 9월 26일 미국과 이란은 군사적 합의(MOU) 체결 후 9일 만에 무력 충돌을 재개했다. 이란의 이슬람혁명수비대(IRGC)는 미국의 무인기 격추를 통해 합의 위반을 주장했고, 미국은 이를 반박하며 군사적 대응을 강조했다. 이후 2024년 2월 27일, 미 중부사령부의 이란 내 감시 기반시설 및 방공 기지 공습에 이란은 쿠웨이트와 바레인의 미군 기지를 미사일과 드론으로 공격하며 보복에 나섰다. 이에 따라 호르무즈 해협과 레바논 지역의 긴장이 고조되었고, 헤즈볼라의 평화 합의 거부로 레바논 휴전 협정도 위태로운 상태가 됐다.',3,2,1,0,0,'https://cdn.sisajournal.com/news/photo/202606/377929_385655_1030.jpg','2026-07-27 16:16:00.177222'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'미국과 이란은 2023년 9월 26일, 9일 전 체결한 군사적 합의(MOU)를 위반하며 무력 충돌을 재개했다.','title: 미·이란 휴전 9일 만에 무력 충돌…서로 “합의 어겼다”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1368,NULL,'국제','한국 축구대표팀은 2026 FIFA 월드컵 아시아 지역 예선 A조 4차전에서 28일 일본과의 맞대결을 앞두고 있으며, 승리 시 32강 직행이 확정된다.','한국 축구대표팀은 2026 FIFA 월드컵 아시아 지역 예선 A조 4차전에서 28일 일본과 맞대결을 앞두고 있다. 현재 조 1위를 유지하며 3승 2무 3패로 11점 기록하고 있으며, 일본과의 승점 차는 3점이다. 승리 시 32강 직행이 확정되며, 플레이오프 진출 가능성은 36.04%로 나타났다. 나머지 3경기에서 최소 6점 이상 확보해야 12위 이내 진출이 가능하며, 12월 11일과 30일에 각각 J조와 K조 상위팀과의 경기가 예정되어 있다.',3,1,2,0,0,'https://cdn.sisajournal.com/news/photo/202606/377931_385657_4417.jpg','2026-07-27 16:16:07.047230'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국 축구대표팀은 2026 FIFA 월드컵 아시아 지역 예선 A조 4차전에서 28일 일본과의 맞대결을 앞두고 있으며, 승리 시 32강 직행이 확정된다.','title: 32강까지 딱 한 자리 남았다…한국 축구에 남은 가능성 ‘36%’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1369,NULL,'국제','한국 선박 2척, 호르무즈 해협서 이탈','2024년 3월 27일, 호르무즈 해협에서 한국 선박 2척이 이탈하며 총 5척 중 3척이 남아 있는 상태가 되었다. 이후 2026년 5월 6일 기준, 한국인 선원 5명이 탑승한 외국 국적 선박 1척이 안전하게 이탈했으며, 현재 해협 내 남아 있는 한국인 선원은 총 23명(한국 선박 2척 7명, 외국 선박 16명)이다. 이란 해상 경비대의 감시를 받는 선박 2척과 중립국 지역으로 이동한 선박 1척이 남아 있으며, 해양수산부는 선원 안전 확보를 위해 외교적 대응과 해상 경비대 추가 배치, 국제 협력 강화를 추진 중이다.',2,0,2,0,0,'https://cdn.sisajournal.com/news/photo/202606/377930_385656_407.jpg','2026-07-27 16:16:13.481296'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 3월 27일, 한국 선박 2척이 호르무즈 해협에서 이탈했다.','title: 한국 선박 2척, 호르무즈 해협서 추가 탈출…남은 선박 3척
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1370,NULL,'국제','북한, 2026 월드컵 예선 32강 진출 실패','2026년 월드컵 아시아 지역 예선에서 북한이 32강 진출에 실패했다. 북한은 2026년 월드컵 아시아 3차 예선 A조에서 3경기에서 1승 2패를 기록하며 조 4위에 머물렀고, 32강 진출을 좌절했다. 이로써 북한은 2018년 러시아 월드컵 이후 8년 만에 월드컵 본선 진출에 실패했으며, 2010년과 2022년 월드컵에서도 본선 진출에 실패한 바 있다. 북한은 2026년 월드컵 예선에서 33경기 중 34경기에서 1승을 기록하며 성적 부진을 이어갔고, 향후 국제축구연맹(FIFA)과 아시아축구연맹(AFC)의 규정에 따라 추가 예선 절차를 밟을 예정이다.',1,0,1,0,0,'https://cdn.sisajournal.com/news/photo/202606/377954_385684_613.jpg','2026-07-27 16:16:32.651051'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'북한은 2026년 월드컵 아시아 3차 예선 A조에서 3경기에서 1승 2패를 기록하며 32강 진출에 실패했다.','title: ‘기적은 없었다’…홍명보호, 북중미 월드컵 32강 진출 좌절
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1371,NULL,'정치','베네수엘라에서 24일 발생한 연쇄 강진으로 사망자가 1430명으로 늘어났다.','2026년 6월 24일 베네수엘라 라과이라주에서 발생한 규모 7.2와 7.5의 연쇄 강진으로 사망자 수는 3,535명으로 집계되었으며, 부상자는 1만 6,740명, 이재민은 약 1만 7,854명에 달했다. 지진으로 건물 856채가 피해를 입고 190채가 붕괴되었으며, 구조 활동은 발생 후 11일째를 넘긴 현재 대부분 중단된 상태로, 매몰자 생환 가능성은 희박하다. 일부 SNS를 통해 퍼진 어린이 4명 구조 소식은 과거 장면을 오보로 전달한 것으로 확인되었고, 현지 언론은 이를 정정했다. 신원 미확인 시신은 라 에스페란자 공동묘지에 개별 무덤으로 매장되었으며, 유가족들은 지문, 옷가지 등으로 신원 확인을 시도하는 등 어려움을 겪고 있다.',16,6,4,6,0,'https://www.pressian.com/_resources/10/2026/06/28/2026062618072601500_l.jpg','2026-07-27 16:17:01.596175'::timestamp,'2026-07-27 19:02:42.214920'::timestamp,NULL,NULL,'지역, 사건 유형, 피해 규모, 전개 흐름이 모두 새로운 사안으로, 기존 토픽과는 관련 없음','베네수엘라에서 24일 발생한 연쇄 강진으로 사망자가 1430명으로 늘어났다.','title: 베네수엘라 지진 사망자 1430명으로 늘어hellip;실종자 무려 7만명
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1372,NULL,'경제','5대 시중은행의 6월 개인 신용대출 잔액이 전월 대비 2조2118억 원 증가했다.','5대 시중은행의 6월 개인 신용대출 잔액이 전월 대비 2조2118억 원 증가하며 2021년 4월 이후 5년 2개월 만에 가장 큰 폭으로 증가했다. 이는 주식 투자 열풍과 집값 상승 기대감에 따른 ''빚투''와 ''영끌'' 수요가 지속되며, 대출 규제 강화 전 ''막차'' 수요가 집중된 결과로 분석된다. 마이너스 통장 잔액은 43조3363억 원으로 3년 8개월 만에 최대 규모이며, 보험계약대출도 4월 46조3203억 원에서 46조8430억 원으로 약 5000억 원 증가했다. 금융당국은 가계대출 증가 추세 안정화를 위해 가계부채 비상 관리체계를 유지하고, 일부 카드사에 대한 소집도 예정하며, 은행권은 주택담보대출 모기지보험 가입 중단 및 타행 대출 접수 중단 등 자율 규제를 시행하고 있다.',1,1,0,0,0,'https://www.pressian.com/_resources/10/2026/06/29/2026062905124485302_l.jpg','2026-07-27 16:17:24.589030'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'5대 시중은행의 6월 개인 신용대출 잔액이 전월 대비 2조2118억 원 증가했다.','title: ''빚투'' ''영끌'' 열풍에 은행 신용대출 5년 만 최대hellip;''마통'' ''보험대출'' 수요까지 폭증
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1373,NULL,'사회','국민의힘 김예지 의원이 29일 장애인학대범죄자 및 성범죄자 전력자가 중증장애인 근로지원인으로 활동하지 못하도록 하는 ''장애인복지법 일부개정법률안''을 대표발의했다.','국민의힘 김예지 의원은 장애인학대범죄자 및 성범죄자 전력자가 중증장애인 근로지원인으로 활동하지 못하도록 하는 ''장애인복지법 일부개정법률안''을 29일 대표발의했다. 현재 법은 장애인학대나 성범죄 전력자가 장애인관련기관에 취업하는 것을 제한하고 있으나, 근로지원인 서비스 제공기관은 제외되어 사각지대가 존재했으며, 이로 인해 범죄경력 조회가 법적 근거 없이 거부되는 사례도 발생했다. 개정안은 ''장애인고용촉진 및 직업재활법''에 따른 근로지원인 채용 기관을 취업제한 대상에 포함함으로써 전국 136개 근로지원인 수행기관의 제도적 공백을 해소할 예정이다. 이후 법안은 국회 보건복지위 심사 절차를 거칠 예정이며, 장애인 안전과 권리 보장을 위한 제도적 기반 마련이 핵심 쟁점으로 부각되고 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231703_128401_1214.jpg','2026-07-27 16:17:37.443636'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국민의힘 김예지 의원이 29일 장애인학대범죄자 및 성범죄자 전력자가 중증장애인 근로지원인으로 활동하지 못하도록 하는 ''장애인복지법 일부개정법률안''을 대표발의했다.','title: 장애인학대범죄자·성범죄자 등 근로지원인 취업 제한 입법화
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1374,NULL,'경제','마포구, 실뿌리배움터 하반기 교육프로그램 운영','마포구는 2026년 7월부터 10월까지 용강동, 신수동, 서강동, 서교동, 합정동, 망원1동, 연남동, 성산1동의 8개 동평생학습센터에서 ''실뿌리배움터 하반기 교육프로그램''을 운영한다. 이 프로그램은 주민 생활권 내에서 평생학습 기회를 제공하기 위해 마련된 마포구의 동 단위 학습 거점으로, 디지털 역량, 인문·독서, 건강·생활, 문화예술, 가족 소통 분야의 총 16개 강좌를 제공한다. 수강 대상은 마포구민 및 소재 직장인으로, 7~8월 강좌는 6월 29일, 9~10월 강좌는 8월 18일 오전 10시부터 온라인 및 전화로 신청 가능하며, 수강료는 무료이나 재료비·교재비 등은 별도 부담해야 한다. 마포구는 이번 프로그램을 통해 주민의 삶의 질 향상과 지역사회 활성화를 도모하고, 향후에도 맞춤형 평생학습 프로그램을 지속적으로 발굴할 계획이다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:17:48.273283'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'마포구는 2026년 7월부터 10월까지 용강동, 신수동, 서강동, 서교동, 합정동, 망원1동, 연남동, 성산1동의 8개 동평생학습센터에서 ''실뿌리배움터 하반기 교육프로그램''을 운영한다.','title: 집 가까이서 배우는 즐거움…마포구, ''실뿌리배움터 교육프로그램'' 운영
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1375,NULL,'정치','강북구, 여름철 공원 물놀이시설 운영','서울 강북구는 7월 4일부터 8월 23일까지 벌말어린이공원, 고갯마루어린이공원, 우이동만남의광장 등 3곳에서 물놀이시설을 본격 운영한다. 이는 지난해 정비공사를 통해 단장된 고갯마루어린이공원과 우이동만남의광장이 올해 처음으로 물놀이장을 운영하는 것을 포함하며, 지역 어린이들이 가까운 공원에서 여름을 즐길 수 있도록 하기 위한 조치다. 물놀이장은 평일 오후 1시~4시(3회), 주말·공휴일 낮 12시~오후 5시(5회) 운영되며, 회차별 50분 가동 후 10분 휴식을 반복한다. 또한 수유일어린이공원 등 7개소는 9월 30일까지 바닥분수와 계류시설을 운영하고, 북서울꿈의숲은 8월 30일까지 주말·공휴일에 3회 운영되며, 안전과 위생 관리를 위해 시설 점검과 운영 중단 조치를 시행할 예정이다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:17:56.121050'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울 강북구는 7월 4일부터 8월 23일까지 벌말어린이공원, 고갯마루어린이공원, 우이동만남의광장 등 3곳에서 물놀이시설을 본격 운영한다.','title: 우리 동네 공원의 시원한 변신…강북구, 물놀이 시설 본격 운영
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1376,NULL,'사회','중소벤처기업부, 장애인기업 지원 정책 강화','2024년 기준 장애인기업 수는 17만5176개사로 전년 대비 0.5% 증가했으며, 이 중 92.1%가 소상공인이다. 조사에 따르면 장애인기업은 금융지원(71.3%)과 세제지원(49.8%)을 가장 필요로 하는 정책으로 꼽았으며, 전체 종사자 수는 58만6595명, 장애인 종사자 수는 18만5821명으로 전체의 31.7%를 차지했다. 매출총액은 70조 1830억원, 영업이익은 6조 6316억원으로 각각 전년 대비 0.8%, 1.5% 증가했다. 중소벤처기업부는 이번 조사 결과를 바탕으로 금융·판로 등 맞춤형 지원을 강화할 계획이며, 장애인기업의 지속적 성장을 위한 정책 수립이 예정되어 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231718_128417_5052.jpg','2026-07-27 16:18:25.111171'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'중소벤처기업부는 2024년 기준 장애인기업실태조사를 29일 발표했다.','title: 장애인기업 수 17.5만개, 대부분 소상공인‥“금융 지원 필요”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1377,NULL,'사회','민주당, 장애인 당선자 워크숍 개최','더불어민주당 전국장애인위원회와 서미화 의원실은 2024년 5월 29일 이룸센터에서 2026 지방선거 장애인 당선자를 대상으로 한 워크숍을 개최했다. 이번 워크숍은 장애인 당선자들의 의정 역량 강화를 위해 예산·결산 검토, 조례 제정, 행정사무감사 등 실무 중심 교육을 진행하며, 장애 당사자의 목소리가 지역사회에 실질적으로 반영될 수 있도록 지원하는 데 목적을 뒀다. 서미화 위원장과 김용석·정병기 전 의원 등이 강사로 참여해 조례 개정, 예산감시, 행정감사 활용 등 현장 중심의 전문 지식을 공유했으며, 참석자들은 워크숍을 통해 실질적인 의정 역량을 강화하는 데 기여했다. 이후 전국장애인위원회는 당선자들이 지역에서 유능한 민생 정치인으로 성장할 수 있도록 정책 지원과 연대 활동을 지속할 계획이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231740_128438_529.png','2026-07-27 16:18:37.390521'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'더불어민주당 전국장애인위원회와 서미화 의원실이 2024년 5월 29일 이룸센터에서 2026 지방선거 장애인 당선자 워크숍을 개최했다.','title: 민주당 전국장애인위원회, ‘2026 지방선거 장애인 당선자 워크숍’ 성료
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1378,NULL,'정치','노원구, 폭염 대응시설 확충 및 취약계층 보호 대책 추진','노원구는 2024년 폭염 예상에 따라 7억 원을 투입해 생활밀착형 폭염 대응시설을 확충하고, 취약계층 보호를 위한 대책을 추진했다. 지난해 210개였던 횡단보도 그늘막을 217개로 늘리고, 노후 그늘막 35곳을 교체하며, 쿨링포그 시설을 총 10곳으로 확대하고 야외 무더위쉼터 ‘해피소’를 2곳 추가 조성했다. 현재 298곳의 무더위쉼터가 운영 중이며, 7월 1일부터 8월 16일까지 구청 카페도 주말에 개방하고, 폭염특보 발효 시 고령자 대상 야간 쉼터도 제공한다. 폭염특보 발효 시 야외 작업 현장에 대한 안전점검을 실시하고, 저소득층 가구 197곳에는 벽걸이형 에어컨 설치를 지원하며, 야외 근로자 165명에게는 휴대용 선풍기 등 맞춤형 방한물품을 지급할 예정이다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:18:44.017125'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'노원구는 2024년 폭염 예상에 따라 7억 원을 투입해 생활밀착형 폭염 대응시설을 확충하고, 취약계층 보호를 위한 대책을 추진했다.','title: 그늘막 늘리고 쉼터 늘리고… 노원구 ‘역대급 폭염’과 맞선다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1379,NULL,'사회','HIV 감염인 수술 거부 사건 인권위 각하 결정','2025년 4월 17일, HIV 감염인 A 씨가 대구 달서구의 접합 전문병원에서 골절 수술을 거부당한 사건에 대해 장애인차별금지추진연대 등 10개 단체가 국가인권위원회에 진정을 제기했으나, 인권위는 ''HIV 감염인이라는 이유로 수술을 거부했다는 직접적 증거가 없고 피해가 확인되지 않는다''며 진정을 각하했다. A 씨는 수술 거부로 인해 대체 치료도 제공되지 않아 6주간 깁스 치료를 받아야 했으며, 병원 측은 면역계통의 내과적 이유로 수술 불가를 주장했다. 연대는 이 사건이 장애인차별금지법 제2조에 해당하는 장애 상태에 기반한 차별이며, 의료법 제15조에 위반된 진료 거부 행위라며 인권위의 각하 결정을 명백한 행정법 위반으로 지적했다. 현재 공익인권법재단 공감 등 12개 단체는 인권위의 결정을 즉각 철회하고 재조사를 실시할 것을 촉구하며, 이 사건이 취약계층의 구조적 차별을 보여주는 사례라고 강조하고 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231748_128444_4158.jpg','2026-07-27 16:18:55.513589'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2025년 4월 17일, 대구 달서구의 접합 전문병원이 HIV 감염인 A 씨의 골절 수술을 거부했다.','title: "HIV 감염인 수술거부, 명백한 장애인 차별" 인권위 각하 결정 규탄
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1380,NULL,'정치','홍명보 감독 사임','2026년 북중미 월드컵 조별리그 탈락 후, 홍명보 감독은 2024년 6월 28일 멕시코 과달라하라에서 사임 기자회견을 열고 사임했다. 이는 정몽규 대한축구협회장의 장기 집권과 감독 선임 절차의 비공정성, 법원이 선임 절차 하자를 인정한 점 등이 누적된 결과로, 문체부는 2024년 11월 임원진의 직무 정지를 권고했으며, 정 회장은 2025년 2월 26일 4연임에 성공했으나 사임 의사를 밝히며 책임을 인정했다. 국회 문화체육관광위원회는 2022년 월드컵 성적 부진과 선임 논란을 이유로 청문회를 개최할 예정이며, 조직 개편, 선임 제도 개선, 장기적 전략 수립이 주요 쟁점으로 부상하고 있다. BBC는 한국 축구의 정치적·개인적 변덕에 따른 감독 변화를 비판하며, 현재의 분노가 아시아 축구 강국으로의 전환점이 될 수 있다고 조언했다.',3,2,0,1,0,'https://www.pressian.com/_resources/10/2026/06/30/2026063018072203141_l.jpg','2026-07-27 16:19:03.416732'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 6월 28일, 홍명보 감독이 멕시코 과달라하라에서 사퇴 기자회견을 열며 사임했다.','title: BBC quot;한국 팬, 축구 모르는 한 사람 변덕에 감독 바뀐다 비판hellip;지금 전환점 삼아야quot;
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1381,NULL,'경제','자영업자 대출 잔액 역대 최대','올해 1분기 자영업자 대출 잔액은 1095조 5000억 원으로 통계 작성 이후 최대치를 기록했다. 이는 지난해 말보다 2조 6000억 원 증가한 것으로, 사업자대출(745조 5000억 원)과 가계대출(350조 원)이 각각 역대 최대 규모를 기록한 결과다. 연체율은 2.04%로 2015년 2분기 이후 최고 수준이며, 저축은행과 카드·캐피털 등 2금융권 연체율도 각각 12.79%와 3.98%로 최고치를 기록했다. 기준금리 인상 시 연간 이자 부담이 1조 8000억 원 증가할 수 있어, 향후 금리 정책과 자영업자 지원 정책의 방향성이 주목된다.',1,1,0,0,0,'https://www.pressian.com/_resources/10/2026/07/01/2026063013190559808_l.jpg','2026-07-27 16:19:11.331883'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'올해 1분기 말 자영업자의 전체 금융기관 대출 잔액이 1095조 5000억 원으로 집계됐다.','title: 자영업자 대출 1100조 육박, 역대 최고hellip;연체율도 2%대로 올라
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1382,NULL,'사회','강남구 율현공원 책쉼터 장애인 편의 점검 결과','서울 강남구 율현공원 책쉼터가 2024년 6월 24일 한국장애인개발원으로부터 ''장애물 없는 생활환경(Barrier Free) 본인증 우수등급''을 획득했다. 이는 1층 단층 구조로 건립된 대지 52,143.50㎡ 규모의 시설로, 장애인 편의시설 점검을 통해 접근성 문제를 확인한 결과다. 점검 결과 주출입문은 터치식자동문 1곳과 점자블록 설치로 휠체어 이용 시 불편이 발생했으며, 계단 점자표지판은 한쪽 손잡이에만 설치되어 있어 시각장애인의 이용에 제한이 있었고, 책상 및 세면대는 높낮이 조절이 불가해 휠체어 사용자에게 불편함이 있었다. 현재는 남녀 장애인화장실과 경사로, 음성안내기 등 일부 편의시설이 설치되어 있으나, 직원호출벨 부재, 점자블록 미설치, 배관 구조물로 인한 휠체어 접근 방해 등 개선이 필요한 사항이 남아 있으며, 향후 시설 개선 계획과 추가 점검이 예정되어 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202606/231759_128468_2729.jpg','2026-07-27 16:19:21.163326'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울 강남구 율현공원 책쉼터가 2024년 6월 24일 한국장애인개발원으로부터 ''장애물 없는 생활환경(Barrier Free) 본인증 우수등급''을 획득했다.','title: 장애물 없는 ‘강남구 율현공원 책쉼터’ 장애인 편의 점검
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1383,NULL,'사회','국가인권위원회가 오세훈 서울시장의 ''기형적인 일자리'' 발언에 대한 장애인 집단 진정을 기각했다.','오세훈 서울시장이 2023년 9월 16일 서울시 장애정책 5개년 계획 기자간담회에서 ''권리중심 공공일자리''를 ''기형적인 일자리''라고 표현해 장애계의 강력한 반발을 일으켰다. 이 발언은 장애인 당사자 90여명이 국가인권위원회에 ''수치심과 모욕감''을 느꼈다며 괴롭힘 차별 진정을 제기한 계기가 되었으며, 인권위는 이 진정을 기각했다. 기각 결정에 따라 장애계는 인권위가 유엔장애인권리협약 이행 의무를 방기한 것이라며 사과와 기각 근거 공개를 촉구했고, 오 시장의 발언이 장애인 정책을 비하하는 차별적 표현이라는 점에서 동일한 법리 적용이 이뤄져야 한다는 주장이 제기됐다. 현재까지 인권위는 기각 결정의 구체적 판단 근거를 공개하지 않았으며, 장애계는 차별 인정과 정책 개선을 위한 추가 절차를 예고하고 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202607/231764_128477_5617.jpg','2026-07-27 16:19:33.310344'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국가인권위원회가 오세훈 서울시장의 ''기형적인 일자리'' 발언에 대한 장애인 집단 진정을 기각했다.','title: 오세훈 ''기형적 일자리'' 발언에 인권위 "차별 아냐"‥장애계 즉각 반발
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1384,NULL,'경제','한국, 월 수출 1000억 달러 돌파','2024년 6월 한국의 월간 수출액은 1022억5000만 달러를 기록하며 사상 처음으로 1000억 달러를 돌파했다. 이는 전년 동기 대비 70.9% 증가한 수치로, 반도체 수출도 월 400억 달러를 처음으로 초과하며 독일·중국·미국에 이어 세계 네 번째로 월 수출 1000억 달러를 달성한 국가가 됐다. 상반기 누적 수출은 4967억 달러로 전년 동기 대비 48.4% 증가했으며, 무역수지는 1383억 달러의 역대 최대 흑자 기록을 달성했다. 그러나 수출 증가에도 불구하고 원화 가치는 1545.2원으로 2009년 이후 17년 만에 최고 수준을 기록하며 달러 수요 부족과 외국인 투자자의 달러 확보 경향으로 인해 환율 안정이 어려운 상황이며, 한국은행은 외환스왑을 통해 국민연금의 달러 수요를 분리해 환율 안정을 추진하고 있다.',2,1,0,1,0,'https://www.pressian.com/_resources/10/2026/07/01/2026070109282542472_l.jpg','2026-07-27 16:19:40.140637'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국의 6월 수출액이 1022억5000만 달러를 기록하며 사상 처음으로 월간 수출 1000억 달러를 돌파했다.','title: [속보] 한국, 月수출 1000억弗 첫 돌파hellip;獨middot;中middot;美 이어 세계 네번째
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1385,NULL,'경제','원민경 장관, AI 시대 여성기업 성장 전략 논의','1일 서울 중구 더플라자 호텔에서 열린 제4차 대한상공회의소 여성기업위원회에서 원민경 성평등가족부 장관은 AI 시대 여성기업의 성장 전략을 논의하며, 신뢰할 수 있는 데이터셋 구축을 통한 성편향 방지와 공정한 기회 보장을 추진하겠다고 밝혔다. 이날 회의에는 정기옥 대한상의 여성기업위원장과 김지현 SK AI위원회 부사장 등이 참석해 AI를 협업 파트너로 활용한 조직 변화의 필요성을 강조했으며, 김민영 방앗간컴퍼니 대표 등 3명이 신규 위원으로 위촉됐다. 같은 달 1일 서울 신라호텔에서 열린 제5회 여성기업주간 개막식에서는 세계 최초 AI 아이돌 ''이터니티''와 AI 더빙 기술 등 여성기업의 기술 혁신 성과가 전시되었고, 중소벤처기업부는 여성기업 전용 벤처펀드 200억원, 정책자금 1조원을 발표했다. 올해는 대한오케이스틸 김연선 대표 등 11명의 여성기업인이 정부포상을 수상했으며, 여성기업주간은 7월 한 달간 전국에서 창업경진대회, 판로 지원 등 다양한 행사로 이어질 예정이다.',2,2,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279429_450386_2415.jpg','2026-07-27 16:19:48.839554'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'원민경 성평등가족부 장관이 1일 서울 중구 더플라자 호텔에서 열린 제4차 대한상공회의소 여성기업위원회에서 AI 생태계에서 성편향을 방지하고 공정한 기회를 보장하기 위해 신뢰할 수 있는 데이터셋 구축을 추진하겠다고 밝혔다.','title: 여성 기업인들 만난 원민경 성평등부 장관, AI 시대, 여성기업 성장 전략 모색
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1386,NULL,'정치','트럼프, ''$TRUMP'' 코인 판매로 8억 달러 벌어','도널드 트럼프 미국 대통령은 2024년 6월 초, 가족이 설립한 암호화폐 기업 ''월드 리버티 파이낸셜''과 함께 ''$TRUMP'' 코인을 출시해 지지층을 대상으로 판매를 유도했다. 코인 가격은 최고 75.35달러까지 치솟았으나, 2025년 6월 기준 1.76달러로 약 97% 폭락하며 투자자 98만8905명이 총 38억1000만달러의 손실을 입었다. 트럼프는 이 코인 사업으로 2024년 한 해 동안 최소 6억3600만달러의 수익을 올렸으며, 2025년 1월 아랍에미리트(UAE) 정부와 연계된 투자사가 지분 49%를 인수한 직후 반도체 칩 수출 계약이 체결되며 이해충돌 논란이 확산됐다. 취임 후 트럼프는 스테이블코인 규제 완화와 암호화폐 친화적 인사 임명 등 정책을 도입하며 업계에 유리한 환경을 조성했고, 이는 대통령의 정책 입안자로서의 역할과 개인 사업 수익 간 이해충돌을 야기했다.',3,2,0,1,0,'https://www.pressian.com/_resources/10/2026/07/01/2026070118170161208_l.jpg','2026-07-27 16:19:56.846146'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'도널드 트럼프 미국 대통령이 백악관 복귀 첫 해에 가족이 공동 설립한 암호화폐 기업 ''월드 리버티 파이낸셜''을 통해 ''$TRUMP'' 코인 판매로 약 8억 달러를 벌어들였다.','title: NYT quot;트럼프, 암호화폐 사업으로 ''놀라운 횡재''quot;hellip;코인 팔아 2조 원 벌었다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1387,NULL,'경제','김성주 이사장, ''74조 매도폭탄'' 반박','국민연금공단은 2024년 6월 말까지 국내 주식 리밸런싱을 유예하며, 목표 투자 비중을 14.9%에서 20.8%로 상향 조정했다. 리밸런싱은 주가 수준뿐 아니라 채권 수익률, 금리, 환율 등 다양한 요소를 종합적으로 고려해 결정되며, 단기 수익 실현을 목적으로 하지 않는다. 1~3일 유가증권시장에서의 순매도 규모는 2158억원에 그쳤으며, 예상된 60조~70조원 규모의 매도 폭탄은 발생하지 않았다. 실제 매도 물량은 14조~15조원 수준으로 추산되며, 반도체 기업 실적 발표 이후 리밸런싱 압박이 재부각될 수 있으나, 국민연금법 개정안을 통해 시장 상황에 따라 목표 비중 조정을 유예할 수 있도록 조치가 추진되고 있다.',2,1,0,1,0,'https://www.pressian.com/_resources/10/2026/07/02/2026070120305731847_l.jpg','2026-07-27 16:20:17.136407'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'김성주 국민연금공단 이사장이 1일 페이스북을 통해 ''74조 매도폭탄'' 우려를 ''터무니없는 소리''라고 반박했다.','title: 국민연금 이사장 quot;연금 ''74조 매도폭탄'' 터무니없어hellip;''폭탄'' 가능성 제로quot;
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1388,NULL,'경제','코스피 5%대 급락 및 사이드카 발동','2024년 7월 7일 코스피 지수가 장중 7.73% 급락하며 7,428.60까지 하락했고, 삼성전자와 SK하이닉스는 각각 9.28%, 10.07% 하락하며 시장 하방을 주도했다. 이에 따라 오전 10시 23분 41초, 코스피200 선물지수가 전일 종가 대비 5% 이상 하락한 상태가 1분간 지속되며 매도 사이드카가 발동됐고, 프로그램매도호가가 5분간 정지됐다. 외국인과 기관은 각각 3조1천908억원, 1천631억원 순매도를 기록한 반면, 개인은 3조2천866억원 순매수로 시장 하방을 지지했다. 이후 시장 안정화 조치와 향후 회복 가능성, 외부 요인에 대한 시장 반응이 주요 쟁점으로 부각되고 있다.',12,3,0,9,0,'https://www.pressian.com/_resources/10/2026/07/02/2026070209150860716_l.jpg','2026-07-27 16:20:23.989012'::timestamp,'2026-07-27 19:03:34.832593'::timestamp,NULL,NULL,'기존 후보와 직접 상관관계가 없다는 배정 사유가 감지되어 새 토픽으로 생성','2024년 4월 2일 코스피지수는 반도체 지수 급락 여파로 전거래일 대비 5.34% 하락하며 8000선이 무너졌고, 거래소는 매도 사이드카를 발동했다.','title: [속보] 코스피 5%대 급락해 사이드카 발동hellip;반도체지수 급락 여파
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1389,NULL,'정치','노원구가 2024년 7월 16일부터 8월 16일까지 화랑대 철도공원(화랑로 622)에서 ''2026 꿀잼 워터파크''를 운영한다.','노원구는 2024년 7월 16일부터 8월 16일까지 화랑대 철도공원(화랑로 622)에서 ''2026 꿀잼 워터파크''를 운영한다. 이는 기존 서울과학기술대학교 운동장에서 옮겨진 것으로, 폐선된 경춘선 철길과 옛 역사를 활용한 기차 테마공원인 화랑대 철도공원에서 열리며, 문화체육관광부 ''대한민국 로컬100''에 2회 연속 선정된 공간이다. 올해는 워터슬라이드를 무료로 전환하고 50m 에어바운스형으로 개선하며, 클라이밍풀, 유수풀, 에어슬라이드, 회전물썰매 등 전 연령층 시설을 확충했으며, 안전요원 배치, 수질 2시간마다 측정, 인조잔디 및 방수포 설치로 미끄럼 사고 예방에 주력했다. 입장료는 노원구민 무료, 타 자치구 주민 2천 원, 36개월 미만 영유아 무료이며, 주말에는 가족 참여형 프로그램 운영과 함께 20일 휴장일에 장애인 가족 초청 행사도 진행한다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:20:32.901401'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'노원구가 2024년 7월 16일부터 8월 16일까지 화랑대 철도공원(화랑로 622)에서 ''2026 꿀잼 워터파크''를 운영한다.','title: 노원구, 화랑대 철도공원서 ''꿀잼 워터파크'' 7월 16일 개장
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1390,NULL,'정치','이재명·문재인, 청와대 오찬 회동','2024년 1월 1일 이재명 대통령과 문재인 전 대통령은 청와대 상춘재에서 오찬 회동을 갖고 민주진영의 단합과 국민통합을 강조했다. 이는 더불어민주당 전당대회를 앞두고 친문·친이재명계 간 내분이 심화된 상황에서, 검찰개혁, 한반도 평화, 지방 주도 성장 등 주요 정책 방향에 대해 공감하며 수시 소통을 약속한 것으로, 수도권 집중 해소를 위한 호남 반도체 클러스터 투자 등 구체적 과제도 논의했다. 이 회동은 2018년 평양 정상회담 당시 이재명이 방북 명단에서 제외된 이후 친문 진영과의 갈등이 심화된 데 따른 것으로, 당내 통합 신호로 해석되며 청년 문제 해결과 국가균형 발전이 주요 쟁점으로 부각되고 있다.',2,1,0,1,0,'https://cdn.womennews.co.kr/news/photo/202607/279471_450449_238.jpg','2026-07-27 16:20:39.649838'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령과 문재인 전 대통령이 2024년 1월 1일 청와대 상춘재에서 오찬 회동을 갖고 민주진영의 단합을 강조했다.','title: “민주진영 단합” 이재명·문재인 뜻 모았다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1391,NULL,'정치','이주민 혐오 조장 언론 보도 분석','2024년 2월 1일부터 6월 5일까지의 지방선거 기간 중, 국내 주요 언론의 보도 817건을 분석한 결과, 이주민 혐오를 조장하는 기사 51건이 발견됐으며, 이 중 45건이 선거 전 의제 형성기(2월 1일~5월 20일)에 집중됐다. 정치인의 혐오 발언을 그대로 인용한 보도가 24건(47%)으로 가장 많았으며, 외국인 여론 왜곡 방지법, 원정투표 금지법 발의 등이 주요 사례로 나타났다. 특히 2025년 지방선거에서 외국인 참정권이 보장된 이후, 선거 전후 언론보도에서 이주민을 ''민주주의 위협''이나 ''잠재적 범죄자''로 묘사하는 보도가 지속되며, 중국계 이주자에 대한 혐중 시위와 연계된 보도도 확인됐다. 인권운동네트워크 바람은 언론의 인권보도준칙 미준수와 선거관리의 부실을 지적하며, 이주민 혐오보도 감시와 민주주의·인권 보장을 위한 모니터링의 필요성을 강조했다.',2,2,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279472_450451_79.jpg','2026-07-27 16:20:46.960362'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'인권운동네트워크 바람이 2024년 2월 1일부터 6월 5일까지 국내 주요 언론의 보도 817건을 분석해 이주민에 대한 혐오를 조장하는 기사 51건을 발견했다.','title: ‘받아쓰기’ 지방선거 언론보도, 이주민 혐오 키웠다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1392,NULL,'경제','유동균 마포구청장, 재개발·재건축 전담반 구성 승인','유동균 마포구청장은 취임 후 첫 결재로 재개발·재건축 신속 추진 전담반(TF) 구성 계획을 승인하며, 현재 61개소로 진행 중인 정비사업의 체계적 관리와 신속한 추진을 위해 권역별 책임관제를 도입했다. 전담반은 월 1회 구청장 주재 간담회를 통해 조합장 등과 직접 소통하고, 긴급 현안에 대해 수시 면담을 실시하며 사업 지연 해소와 주민 갈등 조정을 추진한다. 이와 별도로 중랑구는 2만 86세대 규모의 30년 이상 노후 공동주택 정비사업을 본격화하기 위해 주거개선과 내에 신속추진지원팀을 신설했으며, 재건축 교육과 포럼을 통해 주민 참여를 확대하고 현장 중심의 소통 체계를 구축했다.',2,0,2,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:20:54.560918'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'유동균 마포구청장, 2024년 7월 1일 취임 후 첫 결재로 ''재개발·재건축 신속 추진 전담반(TF) 구성 계획''을 승인했다.','title: 유동균 마포구청장, 민선 9기 첫 결재로 재개발·재건축 속도 낸다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1393,NULL,'정치','더불어민주당이 제13대 목포시의회 개원 전 의장단과 상임위원장 자리를 모두 민주당 몫으로 구성하려는 방침을 내세웠다.','제13대 목포시의회는 6일 개원 전 민주당 소속 의원들이 의장, 부의장 및 상임위원장 5개 직책을 전부 차지하며 의장단 ''전석 독식''을 실현했다. 총 22석 중 민주당은 15석을 차지했으나, 비민주당 및 무소속 의원 7석(31.8%)은 의장단 및 상임위원장단에서 완전히 배제되며 소수의견 반영 부족과 협치 실패에 대한 비판이 제기됐다. 이는 울산시의회와 유사한 의석 구조에서도 협치를 선택한 사례와 대비되며, 무소속 손혜원 의원을 포함한 야당 의원들은 시민의 선택을 무시한 일당 독식이라며 반발했다. 7일 개원식을 개최하며, 다수당 독식에 따른 견제 기능 상실과 협치 방식의 재고가 필요하다는 목소리가 커지고 있다.',2,2,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279469_450457_2331.jpg','2026-07-27 16:20:56.407384'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'더불어민주당이 제13대 목포시의회 개원 전 의장단과 상임위원장 자리를 모두 민주당 몫으로 구성하려는 방침을 내세웠다.','title: 손혜원, 더불어민주당 원 구성 독식에 제동… "시민이 만든 다당 구도 무시"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1394,NULL,'정치','국회 국조특위, 잠실 개표소 진입','국회 6·3 지방선거 투표용지 부족 사태 국정조사특위(국조특위)는 7일 중앙선관위 과천청사와 서울시선관위 사무소를 현장 조사한 데 이어, 2일 송파구 올림픽공원 핸드볼경기장 개표소에 27일 만에 진입했다. 이곳에는 서울시장 선거 37매, 송파구의회 마선거구 25만매, 잠실7동 4만매 등 총 247만장의 투표용지가 보관되어 있으며, 중앙선관위는 이송 전 검증에 9시간과 5000만원이 소요될 것으로 추산했다. 국조특위는 재검표 및 수개표 추진 방안을 여야 협의를 통해 적극 검토 중이며, 선관위는 자체 재검표가 불가능해 국조특위 의결을 전제로 비용 5000만원을 직접 부담하겠다고 밝혔다. 감사원도 회계 검사를 시작하며 예산 집행 내역을 점검하고, 국조특위는 사태 초기 인지 지연과 상황실 운영 부실판을 지적하며 제도 개선 필요성을 강조했다.',24,5,7,12,0,'https://cdn.womennews.co.kr/news/photo/202607/279483_450467_3544.jpg','2026-07-27 16:21:03.219517'::timestamp,'2026-07-27 19:00:23.592046'::timestamp,NULL,NULL,'국조특위의 잠실 개표소 진입은 투표용지 부족 사태의 후속 조사 행보로, 기존 토픽과는 지역, 주체, 쟁점이 다르며 별도의 사건 전개로 판단됨','국회 국조특위 의원들, 2일 서울 송파구 올림픽공원 핸드볼경기장 개표소에 진입했다.','title: 국회 국조특위 의원들, 봉쇄 27일 만에 잠실 개표소 진입
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1395,NULL,'사회','색동원 공대위, 재판부 공정성 촉구 기자회견','인천 중증장애인거주시설 색동원 성폭력사건 공동대책위원회(색동원 공대위)는 2일 서울지방법원 앞에서 기자회견을 열어 시설장에 대한 성폭력 재판부에 선입견 없이 공정한 재판을 진행해달라고 촉구했다. 사건은 2023년 인천의 중증장애인거주시설 색동원에서 발생한 성폭력 피해와 관련된 것으로, 피해자의 진술이 유도됐거나 영향을 받았을 가능성에 대한 재판부의 반복적 질문이 논란이 되고 있다. 재판부는 피해자의 진술 형성 과정에 대해 ''아이스브레이킹'', ''권유'', ''압박'' 등을 언급하며 신빙성을 의심하는 발언을 반복했으며, 이에 대해 공대위는 장애인 특성과 시설 내 권력관계를 고려하지 않은 편견적 판단이라고 지적했다. 공대위는 장애인권과 성인지 감수성을 기반으로 한 국제인권기준에 따라 재판이 진행되어야 하며, 향후 재판의 중립성과 공정성에 대한 감시가 필요하다고 강조했다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202607/231790_128519_211.jpg','2026-07-27 16:21:15.968972'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'색동원 공대위가 2일 서울지방법원 앞에서 기자회견을 열어 시설장 성폭력 사건 재판부에 선입견 없이 공정한 재판을 진행해달라고 촉구했다.','title: 색동원 공대위 "시설장 성폭력 재판부, 선입견 아닌 공정한 재판 진행해달라"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1396,NULL,'경제','서울시, 은마아파트 재건축 사업시행계획 인가','서울시는 2024년 2월 은마아파트 재건축 사업시행계획을 인가하며, 준공 후 47년 만에 재건축을 추진한다. 이 사업은 지하 6층~지상 49층, 총 29개 동, 5850세대 규모로 조성되며, 그중 909세대는 공공임대, 195세대는 공공분양주택으로 제공된다. 착공은 2028년 목표로, 강남구는 신속화를 위해 구청장 직속 TF를 운영 중이다. 이와 함께 중랑구 상봉7구역은 지상 49층·841세대의 주상복합단지로 확대되며, 문화시설과 공공보행통로 등 인프라 확충도 예정되어 있다.',3,1,1,1,0,'https://www.pressian.com/_resources/10/2026/07/02/2026070214204106153_l.jpg','2026-07-27 16:21:40.104278'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 2월 서울시가 은마아파트 재건축 사업시행계획을 인가했다.','title: ''정말 재건축?''hellip; 은마아파트, 준공 47년만 재건축 인가
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1397,NULL,'정치','2026년 7월1일, 대한야구소프트볼협회는 청룡기 전국고교야구에서 광주일고 선수를 조롱하며 ''스타벅스 가야지''라고 외친 배재고 야구부에 출전 정지 6개월을 결정했다.','2024년 5월 18일, 서울 배재고등학교 야구부 선수들이 전국고교야구선수권대회에서 광주제일고를 상대로 ''스타벅스 가야지''라는 구호를 외치며 5·18 민주화운동을 희화화한 사건이 발생했다. 이에 따라 대한야구소프트볼협회는 배재고 야구부에 6개월 출전정지를 결정했고, 이후 5월 6일 배재고 선수단과 지도자, 학부모 등 86명이 광주제일고를 찾아 자필 사과문을 전달하며 눈물로 반성의 자세를 보였다. 사과 후 광주제일고는 사과를 수용하고 두 학교 선수들이 함께 5·18 민주묘지와 광주학생독립운동기념탑을 참배하며 화해의 시간을 가졌다. 광주제일고와 총동창회는 징계 완화를 요청하며 재심 절차를 신청했고, 서울시교육청은 교장·교감 등 관리자에 대한 책임 소재를 검토 중이며, 교육부는 유사 사례 예방을 위한 인성 교육 강화 방안을 검토하고 있다.',27,15,5,7,0,'https://cdn.mediatoday.co.kr/news/photo/202607/335536_480590_434.jpg','2026-07-27 16:21:42.239969'::timestamp,'2026-07-27 19:00:34.975127'::timestamp,NULL,NULL,'배재고 선수들의 5·18 희화화 발언과 그에 따른 출전 정지 징계는 ''청룡기 전국고교야구에서의 조롱 발언''이라는 후보 토픽의 핵심 사건과 직접적인 결과 흐름을 이어가며, 사건 주체, 지역, 쟁점, 전개 방식이 일치함','2026년 7월1일, 대한야구소프트볼협회는 청룡기 전국고교야구에서 광주일고 선수를 조롱하며 ''스타벅스 가야지''라고 외친 배재고 야구부에 출전 정지 6개월을 결정했다.','title: 배재고 징계에 국힘 “표현자유, 이재명탓”? … SBS “제재 없어 조롱 난무”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1398,NULL,'정치','국민의힘, 3일 중앙선관위가 위철환 직무대행의 사퇴를 거부하고 전원 유임을 목표로 한 대응 문건을 작성한 사실을 공개하며 위철환 직무대행의 즉각적인 사퇴를 요구했다.','국민의힘은 중앙선관위가 위철환 직무대행의 사퇴를 거부하고 전원 유임을 목표로 한 대응 문건을 작성한 사실을 공개하며, 선관위의 조직 보전 중심 태도를 비판했다. 이에 따라 국민의힘은 6·3 지방선거 투표용지 부족 사태 진상규명을 위해 야당 추천 특검을 요구하며, 수사 대상에 위철환 직무대행을 1호로 지목하고 행정안전부까지 포함할 것을 주장했다. 민주당은 제3자 추천 방식을 통해 중립성을 확보해야 한다며 국민의힘의 추천 독점 요구를 반박했고, 특검법 처리에 대한 실질적 논의 필요성을 강조했다. 국민의힘은 내부 고발자 면책안 마련과 사전투표제 폐지, 상임위원 확대, 독립 감사기구 설치 등 선거관리 개혁안을 추진하며, 특별위원회를 통해 전면적 개혁안을 정부에 제안할 계획이다.',5,1,2,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GNSGEMTEGRSWEZLGME4TEMLBGI.jpg','2026-07-27 16:21:44.886571'::timestamp,'2026-07-27 19:01:11.225682'::timestamp,NULL,NULL,'국회 국조특위의 잠실 개표소 진입과 재검표 논의는 투표용지 부족 사태의 진상규명을 위한 후속 조치로, 국민의힘의 특검 요구와 직접적인 사건 흐름을 이어가며 같은 사안의 전개이다.','국민의힘, 3일 중앙선관위가 위철환 직무대행의 사퇴를 거부하고 전원 유임을 목표로 한 대응 문건을 작성한 사실을 공개하며 위철환 직무대행의 즉각적인 사퇴를 요구했다.','title: 국힘 “선관위, 국조특위 와중에 ‘조직 보전’ 문건…魏 거취 결단해야“
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1399,NULL,'정치','이재명 대통령, 나토 정상회의 참석 및 몽골 국빈 방문','이재명 대통령은 7일부터 11일까지 3박 5일간 나토 정상회의 참석과 몽골 국빈 방문을 위한 순방을 진행했다. 취임 후 처음으로 참석한 나토 정상회의는 인도·태평양 파트너국(IP4)으로 초청된 한국의 역할을 강조하는 자리로, 대통령은 방위산업포럼에서 기조발언을 통해 K-방산의 글로벌 경쟁력을 제시하고, 나토 회원국들과의 방산 협력 확대를 선언했다. 튀르키예에서는 뤼터 나토 사무총장과 회담하고, 에르도안 대통령의 환영 만찬에 참석하며 방산 수요국과의 양자 회담을 진행했으며, 트럼프 미국 대통령과의 만남 가능성도 주목받았다. 이후 몽골에서는 후렐수흐 대통령과 정상회담을 통해 ''한몽 관계의 황금시대'' 공동선언을 발표하고, 협정 및 양해각서(MOU)를 교환하며 경제·외교 협력 강화를 다짐했으며, 나담축제 개막식에 참석한 뒤 11일 귀국했다.',19,3,7,9,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/RHEIG3JVNJIBRFYCEEBHDNEBYE.JPG','2026-07-27 16:21:52.368423'::timestamp,'2026-07-27 19:00:40.576821'::timestamp,NULL,NULL,'후보 토픽들과 주체, 지역, 이슈 전개가 모두 다름','이재명 대통령이 7일 튀르키예 앙카라에서 열리는 2026 나토 정상회의에 참석한다.','title: 李대통령, 7일 NATO 정상회의·9일 몽골 국빈 방문
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1400,NULL,'국제','뉴욕증시, 반도체 약세 속 혼조로 마감','2024년 6월 말부터 7월 초까지 뉴욕증시는 기술주 중심의 상승세와 반도체 업종의 급락이 공존하는 혼조세를 보였다. 6월 2일 다우존스30 산업평균지수는 5만2,900.07로 사상 최고치를 기록했으나, 나스닥 종합지수는 반도체주 약세로 0.80% 하락하며 2만5,832.67에 마감했다. 이후 7월 6일에는 AI 수요에 대한 우려가 진정되며 엔비디아, 애플, 아마존 등 대형 기술주가 반등하며 다우지수는 5만3,000선을 처음 돌파했고, 나스닥은 1.1% 상승했다. 반도체 섹터는 6월 하순 급락 후 7월 초 반등세를 보였으나, 장기적인 수익성과 AI 투자 수익률에 대한 우려가 지속되고 있으며, 향후 12개월 동안 S&P500은 약 21% 상승할 것이라는 전망이 제기됐다.',5,1,2,2,0,'https://cdn.womennews.co.kr/news/photo/202607/279509_450499_414.jpg','2026-07-27 16:22:11.807194'::timestamp,'2026-07-27 19:01:33.955292'::timestamp,NULL,NULL,'검색 후보 없음','2024년 6월 2일(현지시각) 다우존스30 산업평균지수는 전장 대비 594.83포인트(1.14%) 상승해 사상 최고치인 5만2,900.07을 기록했다.','title: 뉴욕증시, 반도체 약세속 혼조...다우존스 최고치 마감
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1401,NULL,'정치','민주당, 공영방송 이사 후보 내정','더불어민주당은 2024년 3월 KBS, EBS, 방송문화진흥회 이사 후보를 내정하며 친여 시민단체 출신을 다수 포함시켰다. 이후 방송미디어통신위원회는 KBS·MBC·EBS 이사 임명 및 임명제청안을 의결했으나, 국민의힘의 추천 누락으로 총 6명의 후보 추천이 지연되고 있다. 2025년 9월, 민주당 추천 이사 후보 중 이창현과 류일형에 대해 방송법 결격사유 논란이 발생했으며, 이창현은 대선 관련 자문 활동, 류일형은 연임 위반 가능성이 지적됐다. 현재 임명은 법적 해석 차이로 보류 중이며, 국회 추천공직자격심사특별위원회의 추가 검토가 예정되어 있다.',3,2,0,1,0,'https://www.chosun.com/pf/resources/images/thumb_meta.png?d=2276','2026-07-27 16:22:17.997287'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'더불어민주당은 2024년 3월 3일 KBS, EBS, 방송문화진흥회 이사 후보를 내정했다.','title: 민주당, 공영방송 이사 후보 친여 시민단체 출신 다수 내정
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1402,NULL,'정치','이재명 대통령의 국정 수행 지지율이 한국갤럽의 6월 30일~7월 2일 조사에서 전주 대비 3%p 상승한 54%를 기록했다.','이재명 대통령의 국정 수행 지지율이 한국갤럽의 6월 30일~7월 2일 조사에서 전주 대비 3%p 상승한 54%를 기록하며, 취임 후 최저 지지율 이후 회복세를 보였다. 긍정 평가의 주요 이유는 경제·민생(24%), 외교(14%), 전반적 수행(8%) 순이었으며, 부정 평가는 5%p 하락한 36%를 기록했다. 동시에 더불어민주당 지지율은 리얼미터 조사에서 43.0%로 국민의힘(40.3%)을 3주 만에 다시 앞지르며 지지율 1위로 재진입했으며, 이는 정부의 서남·충청·영남권 대규모 투자 발표와 호남권 산업 육성 정책 기대감이 중도층 및 특정 지역에서 지지율 상승을 이끌었기 때문으로 분석된다.',2,2,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279519_450519_2242.jpg','2026-07-27 16:22:39.228506'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령의 국정 수행 지지율이 한국갤럽의 6월 30일~7월 2일 조사에서 전주 대비 3%p 상승한 54%를 기록했다.','title: 이재명 대통령 지지율 54%, 3%p↑...민주 41%·국힘 26%[한국갤럽]
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1403,NULL,'정치','강북구, 장애인 건강보건사업 우수기관 선정','강북구는 2026년 6월 26일 열린 ''장애인 건강보건 통합성과대회''에서 보건복지부 장관상을 수상하며 2023년부터 2026년까지 4년 연속 장애인 건강보건관리사업 우수기관으로 선정됐다. 이는 2023년 수유보건지소 개소 이후 지역사회 중심의 재활서비스 확대와 발달장애인·시각장애인 등 대상자 확대, 유관기관과의 협력체계 구축 등 지속적인 정책 시행 결과다. 현재까지 재가 장애인 대상 방문재활서비스를 운영하며 근력 강화, 그룹운동, 요가 등 맞춤형 프로그램을 제공하고 있으며, 의료·복지자원 연계를 통한 통합 지원 체계가 정착된 상태다. 정창수 강북구청장은 앞으로도 의료·복지기관 협력을 강화하고, 맞춤형 서비스를 확대해 장애인의 삶의 질 향상을 목표로 하고 있다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:22:51.197440'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'강북구는 2026년 6월 26일 열린 ''장애인 건강보건 통합성과대회''에서 보건복지부 장관상을 수상하며 4년 연속 장애인 건강보건관리사업 우수기관으로 선정됐다.','title: 강북구, 장애인 건강보건관리사업 4년 연속 우수기관 선정
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1404,NULL,'국제','테일러 스위프트와 트래비스 켈시가 2024년 5월 2일(현지 시간) 미국 전역의 20개 자선 단체에 총 2600만달러를 기부했다.','테일러 스위프트와 트래비스 켈시가 결혼을 앞두고 미국 전역의 20개 자선 단체에 총 2600만달러(한화 약 400억원)를 기부했다. 두 사람은 결혼식을 치르기 전인 2024년 5월 2일(현지 시간) 뉴욕 매디슨 스퀘어 가든에서 예정된 행사에 앞서, 푸드 뱅크, 의료·교육·식량 지원 단체 및 동물보호 기관 등에 기부를 완료했다. 기부 대상은 내슈빌과 캔자스시티 등 두 사람과 인연이 깊은 지역의 단체들이 포함되었으며, 이는 그동안의 사회적 기여와 연계된 것으로 분석된다. 결혼식은 사전 파티를 포함해 5월 2일부터 3일까지 진행되며, 공식 허가를 받은 대규모 행사로 전 세계 팬들의 관심이 집중되고 있다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279537_450524_3358.png','2026-07-27 16:23:05.365697'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'테일러 스위프트와 트래비스 켈시가 2024년 5월 2일(현지 시간) 미국 전역의 20개 자선 단체에 총 2600만달러를 기부했다.','title: 결혼도 선행으로... 테일러 스위프트, 400억 사회 환원
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1405,NULL,'국제','트럼프, 폭염 속에서 긴 연설 예고','2024년 7월 4일 워싱턴 DC 내셔널 몰에서 열린 미국 건국 250주년 기념행사에서 도널드 트럼프 대통령은 폭염과 뇌우, 강풍 등 악천후 속에서도 야외 연설을 강행하며 공산주의를 ''암''에 비유하고 진보주의자를 ''공산주의자''로 낙인찍는 반공주의 메시지를 반복했다. 행사에는 약 86만 발의 불꽃놀이와 공군 편대의 에어쇼가 예정되었으나, 퍼레이드는 취소되고 관람객 수천 명이 대피하는 등 차질을 빚었으며, 기네스 세계기록 도전이 목표였지만 공식 인증은 아직 이루어지지 않았다. 이 행사에는 민주당 지지 주 10여 곳이 불참했고, 트럼프 행정부가 ''프리덤250''을 통해 기념행사를 사유화하며 초당적 기념위원회 ''아메리카250''의 내용을 대체한 점이 비판을 받았다. 연설은 국가통합보다 당파적 정치와 애국주의를 강조하며 정치적 분열을 부추기며, 중간선거를 앞두고 이념 대립이 심화될 전망이다.',8,2,0,6,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/ZDNUL2VMMJPVFHQYU2WZXB6GCI.jpg','2026-07-27 16:23:37.328795'::timestamp,'2026-07-27 19:00:59.190678'::timestamp,NULL,NULL,'폭염은 사건의 배경이지만, 주체와 쟁점, 전개 흐름이 후보 토픽과 전혀 다름','트럼프 대통령이 4일 워싱턴 DC 내셔널 몰에서 섭씨 40도 안팎의 폭염 속에서도 아주 긴 연설을 할 것이라고 예고했다.','title: 40도 넘는 폭염에도… 80세 트럼프 “아주 긴 연설 할 것”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1406,NULL,'국제','이란 당국이 알리 하메네이 전 최고지도자의 장례식을 2월 4일 테헤란에서 시작하여 9일 고향 마슈하드에서 안장하는 일정으로 진행하기로 결정했다.','이란 전 최고지도자 아야톨라 알리 하메네이의 장례식이 2024년 2월 4일 테헤란에서 시작되어, 7일 곰, 8일 이라크의 카르발라와 나자프를 거쳐 9일 고향 마슈하드에서 안장된다. 장례는 100여 개국 대표단이 참석한 가운데 진행되며, 반미·반이스라엘 성향의 집회가 벌어졌고, 트럼프 대통령의 사진을 향해 돌을 던지는 퍼포먼스와 암살 요구 구호가 나타났다. 하메네이의 세 아들 중 차남 모즈타바는 불참하며 건강 이상설이 확산되고, 후계자로서의 공개 출현 여부가 주목된다. 이란은 장례를 통해 내부 결속과 외교적 입지를 강화하는 정치적 목적을 갖고 있으며, 한국은 조문 참석을 거부받아 외교적 이슈로 부각됐다.',23,12,5,6,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/6CBQCXUXERMD7KUKW3AVGV6EK4.jpg','2026-07-27 16:23:39.212821'::timestamp,'2026-07-27 19:01:44.682924'::timestamp,NULL,NULL,'이란의 장례식과 트럼프의 연설은 모두 정치적 상징성과 외교적 반응을 포함한 국제적 이슈로, 같은 사건의 후속 전개로 볼 수 없으나, 두 사건 모두 정치적 메시지 전달과 외부 반응이라는 공통점이 있어 유사한 사안으로 간주됨','이란 당국이 알리 하메네이 전 최고지도자의 장례식을 2월 4일 테헤란에서 시작하여 9일 고향 마슈하드에서 안장하는 일정으로 진행하기로 결정했다.','title: 엿새간 역대급 ‘하메네이 장례’… 주민들 “살기 힘든데 세금 퍼붓나”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1407,NULL,'정치','민주당, 보완수사권 전면 폐지 입법 추진','더불어민주당은 2026년 10월 2일 중대범죄수사청과 공소청 출범을 앞두고 검찰의 보완수사권을 전면 폐지하는 형사소송법 개정안을 신속히 추진 중이다. 당내 확고한 원칙으로, 8월 17일 전당대회 전까지 법사위 소위 논의를 시작해 입법 절차를 완료할 계획이며, 현재는 법사위와 행정안전위 간사 등이 참여하는 TF가 주도하고 있다. 보완수사권 폐지 이후 수사 공백을 막기 위해 경찰 수사심의위원회 실질화, 인권보호국 설치, 보완수사 기한 명확화 등 제도적 보완책을 마련하고 있으며, 일부에서는 조건부 폐지나 경찰 기소 의견 송치 사건에 한해 예외를 두는 방안도 제기되고 있다. 이에 대해 대검찰청은 심각한 우려를 표명하며 의견서를 제출할 예정이며, 여야 간 협의와 제도적 대안 논의가 지속될 전망이다.',10,1,3,6,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRTGEOLGGRSTKMZXHBTGGMRRGY.jpg','2026-07-27 16:23:45.743943'::timestamp,'2026-07-27 19:01:22.630649'::timestamp,NULL,NULL,'보완수사권 폐지 논의는 중대범죄수사청 출범과 관련된 검찰 개혁의 일환으로, 기존 토픽의 후속 전개로 볼 수 있으나, 주체와 구체적 쟁점은 다름.','더불어민주당이 2024년 10월 검찰청 폐지와 중대범죄수사청 출범을 앞두고 형사소송법 개정을 통해 검찰의 보완수사권을 전면 폐지하기로 결정했다.','title: 與 보완수사권 폐지 속도전에… 내부서도 “부작용 커”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1408,NULL,'정치','민주당 당권 주자 워크숍 참석','2024년 8월 17일 치러지는 더불어민주당 전당대회에서 처음으로 1인 1표제가 도입되며, 당원 주권 강화를 핵심으로 한 당권 경쟁이 본격화되고 있다. 김민석 전 국무총리는 6일 광주에서 출마 기자회견을 열고 정청래 전 대표의 ''자기 정치''를 비판하며 당정 협력의 혼선과 공천 문제, 검찰개혁 과정의 숙의 부족을 지적하며 보완수사권 폐지, 당내 개혁 등을 공약으로 제시했다. 이에 정청래 전 대표는 페이스북을 통해 자신은 당정 협력과 입법 성과를 이룬 공적인 가치 실현을 위해 노력했으며, 1인 1표제를 통해 권력 내려놓기를 실천했다고 반박하며 ''자기 정치'' 개념의 모호성을 지적했다. 송영길 의원도 8일 출마를 예고하며 2030세대 지지 확보를 전략으로 내세우며, 당권 주자들이 별도 캠프 없이 당원과의 소통 중심으로 경쟁을 펼치고 있다.',8,2,0,6,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/5GUSVDP5RZAV7PKEIO45GP2TRI.jpg','2026-07-27 16:23:55.573500'::timestamp,'2026-07-27 19:02:13.579974'::timestamp,NULL,NULL,'당권 주자들의 공개 논쟁과 워크숍 활동이 당내 개혁과 1인 1표제 도입이라는 같은 정치적 이슈 흐름의 일부로 연결됨','민주당 당권 주자인 김민석 전 국무총리, 송영길 의원, 정청래 전 대표가 3일 서울 용산구의 한 호텔에서 열린 국회의원 워크숍에 한자리에 모였다.','title: 與 당권 주자 한자리에… 만나선 웃음꽃, 나가선 신경전
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1409,NULL,'국제','트럼프, 러시모어산에서 독립기념일 연설','도널드 트럼프 미국 대통령은 2024년 7월 3일 사우스다코타주 러시모어산에서 독립기념일 기념 연설을 했다. 이는 2020년 이후 6년 만의 러시모어산 방문으로, 11월 중간선거를 앞두고 지지층 결집을 위한 정치적 행보로 분석된다. 트럼프는 공산주의를 ''암''에 비유하며 반공 메시지를 강조하고, 6·25전쟁 참전용사들을 소개하며 미국의 군사력 강화와 SAVE 법 통과를 촉구했다. 연설은 폭염과 폭풍으로 인해 약 1시간 지연됐으며, 경제 성과와 무역적자 감소 등을 내세워 ''미국의 황금기''를 선언하며 중간선거 전후 정치적 영향력 확대를 노렸다.',3,0,0,3,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/2QRVML7NZBBQJLC5GJNVIKCBWU.gif','2026-07-27 16:24:32.905867'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'도널드 트럼프 미국 대통령이 2024년 7월 3일(현지 시각) 사우스다코타주 러시모어산을 방문해 독립기념일 기념 연설을 했다.','title: ‘대통령 큰바위 얼굴’ 앞에서... 트럼프, 反공산주의 외쳤다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1410,NULL,'정치','정부는 장흥댐, 나주댐, 주암댐에서 하루 65만톤의 용수를 확보할 계획을 발표했다.','정부는 2026년 6월 30일부터 영산강·섬진강 유역의 동복댐, 주암댐, 장흥댐, 보성강댐, 나주댐을 통해 하루 65만톤의 용수를 호남 반도체 클러스터에 공급할 계획을 발표했다. 이는 2023년 ''영산강·섬진강유역 가뭄백서''에 근거한 가뭄 비상용수 계획으로, 과거 가뭄으로 저수율이 역대 최저 수준에 도달한 댐들에서 수자원을 확보하는 방식이다. 그러나 반도체 공급용 수자원이 주민 생활용수 및 여수·광양산단 용수 공급 계획과 중복되며, 주암댐의 도수관로 설치 진행 중인 상황에서 수자원 배분 우선순위에 대한 논란이 제기되고 있다. 이에 따라 국회 차원의 국정조사 필요성이 제기되며, 반도체 산업용 수질 정화를 위한 대규모 수리시설 확충과 지역 협의 절차의 필요성이 강조되고 있다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MI3DOZBSMQYGGN3DHEZDEZTBGU.gif','2026-07-27 16:26:25.766314'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정부는 장흥댐, 나주댐, 주암댐에서 하루 65만톤의 용수를 확보할 계획을 발표했다.','title: ‘초순수’ 필요한 반도체… 영산강 수질은 ‘매우 나쁨’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1411,NULL,'사회','안규백 국방부 장관, 방첩사 해체 및 사관학교 통합 추진','안규백 국방부 장관은 2024년 6월 10일 국군방첩사령부를 공식 해체하고, 육·해·공군 사관학교 통합 및 전시작전통제권 전환을 추진하며 군 개혁을 속도전으로 진행하고 있다. 사관학교 통합은 1·2학년 공통 교육, 3·4학년 군별 특화 교육을 기반으로 하며, 입학 성적 하락(2026학년도 육사 212점 등)과 인재 양성 위기 등을 이유로 내세우고 있으나, 예비역 장성, 동문회, 오세훈 서울시장 등은 전문성 약화와 합동성 구현의 비현실성, 절차적 투명성 부족을 이유로 반발하고 있다. 국방부는 6일 기본계획 발표를 예정했으나, 안 장관의 나토 정상회의 참석을 앞두고 2시간 전에 연기했으며, 8일에는 반대 총궐기대회가 예정된 상태다. 이로 인해 정책의 정당성과 군 내부 합의 수립 여부가 주요 쟁점으로 부상하고 있다.',4,2,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GQ2WIOBXGEZTGMBRGY4TMOBTHA.gif','2026-07-27 16:26:49.859482'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'안규백 국방부 장관은 2024년 6월 10일 국군방첩사령부를 공식 해체했다.','title: 사관학교 통합·방첩사 해체... 안규백 속도전, 軍원로들 탄식
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1412,NULL,'국제','도널드 트럼프 미국 대통령이 2024년 7월 3일(현지시각) 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 했다.','도널드 트럼프 미국 대통령은 2024년 7월 3일(현지시각) 미국 건국 250주년 기념일을 하루 앞두고 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 진행했다. 이는 트럼프 행정부가 우크라이나 지원을 재확인한 후의 행보로, 7월 6일 터키 앙카라에서 열리는 나토 정상회의를 앞두고 전쟁 종식을 위한 외교적 접근을 강화하고 있음을 시사한다. 트럼프는 회담을 통해 젤렌스키 대통령과의 양자 대화를 계획하고 있으며, 러시아의 키이우 공습과 같은 전면적 충돌 격화 상황 속에서 외교적 해결책 마련이 국제적 관심을 끌고 있다. 이와 병행해 트럼프는 블라디미르 푸틴 러시아 대통령과도 85분간 통화를 나누며 중재 의지를 표명했으며, 스티브 윿코프와 재러드 쿠슈너가 모스크바 재방문을 준비 중임을 전달했다.',5,1,2,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GY4DOYRYGU3WCZRZMRSWKZTGGY.jpg','2026-07-27 16:27:18.630798'::timestamp,'2026-07-27 19:02:24.376253'::timestamp,NULL,NULL,'트럼프 대통령의 우크라이나 정상 통화는 트럼프 행정부의 외교적 접근 재확인과 관련된 사건으로, 후보 토픽의 ''트럼프 행정부의 우크라이나 지원 태도 재확인 필요성''과 직접적인 사건 흐름을 이어가며 국제적 외교 전개의 일환으로 분류됨','도널드 트럼프 미국 대통령이 2024년 7월 3일(현지시각) 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 했다.','title: “트럼프, 美 독립기념일 앞두고 젤렌스키와 통화”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1413,NULL,'국제','프리덤 250는 폭풍우와 낙뢰로 인한 안전사고 위험을 이유로 2024년 7월 4일 워싱턴DC 내셔널몰에서 예정된 ''미국에 바치는 헌사'' 행사와 ''위대한 미국 박람회''를 연기했다.','2024년 7월 4일 워싱턴DC 내셔널몰에서 예정된 미국 건국 250주년 기념행사인 ''미국에 바치는 헌사''와 ''위대한 미국 박람회''는 폭염과 폭우, 낙뢰로 인한 안전사고 위험을 이유로 연기됐다. 행사 주최 측 프리덤 250는 기상 상황을 고려해 공공 안전을 최우선으로 판단했으며, 보스턴의 불꽃놀이 행사도 동일한 이유로 연기됐다. 이날 미국 동부는 기록적인 폭염과 강한 뇌우로 최소 25명이 사망하고 약 90만 가구가 정전하는 등 피해가 발생했으며, 워싱턴DC에서는 온열질환자가 속출해 주방위군이 긴급 투입됐다. 행사 일정은 기상 상황에 따라 재조정될 예정이며, 백악관은 트럼프 대통령의 연설은 예정대로 진행될 수 있다고 밝혔다.',9,2,0,7,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GUZWGN3BG5QWEZDFGM3DEYLEMM.jpg','2026-07-27 16:28:00.300805'::timestamp,'2026-07-27 19:02:54.073542'::timestamp,NULL,NULL,'폭풍우와 낙뢰로 인한 안전사고 위험은 후보 토픽의 ''폭염''과 함께 행사 연기의 직접적 원인으로 작용하며, 주체, 지역, 사건 전개가 일치함','프리덤 250는 폭풍우와 낙뢰로 인한 안전사고 위험을 이유로 2024년 7월 4일 워싱턴DC 내셔널몰에서 예정된 ''미국에 바치는 헌사'' 행사와 ''위대한 미국 박람회''를 연기했다.','title: 美 폭염 이어 폭풍우 예보… 건국 250주년 기념행사 차질
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1414,NULL,'경제','아파트 전세 수요 감소로 빌라 전세 거래 증가','올해 1∼5월 전국 아파트 전월세 거래량은 전년 동기 대비 7.2% 감소한 반면, 비아파트 거래는 11.5% 증가하며 임차인들의 이동 흐름이 나타났다. 전세 물건 부족과 가격 상승, 대출 규제로 인해 아파트 전세 수요가 줄었고, 서울 아파트 전월세 매물은 2년 전 대비 14.5% 감소한 3만7551건으로 집계됐다. 서울 아파트 신규 전세 평균 보증금은 2년 전 대비 19.0% 상승한 6억5875만원이며, 월세 비중은 51.3%로 절반을 넘어섰고, 전세 갱신계약 비중도 51.3%로 과반을 차지했다. 이에 따라 비아파트로의 전환 수요가 증가하며 전세 물건 부족과 월세화, 갱신계약 확대 등 주거 안정성 문제와 함께 정책적 대응이 필요해지고 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GE2DOYJUHEZDGMTDGBSTOOBZG4.jpg','2026-07-27 16:28:24.604814'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'올해 1∼5월 전국 아파트 전월세 거래량은 전년 동기 대비 7.2% 감소했다.','title: 전세난에 아파트 떠나는 임차인들… 빌라 전월세 거래 증가
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1415,NULL,'경제','금융당국, LP 관리 강화 방안 검토','금융당국이 단일종목 레버리지 ETF의 괴리율 확대 사고를 계기로 LP 관리 강화 방안을 검토 중이다. 지난달 단일종목 레버리지 ETF의 괴리율 초과 공시가 57건에 달했으며, 삼성전자·SK하이닉스 기초자산 ETF는 코스피 시가총액의 60%를 차지하며 일일 리밸런싱과 프로그램 매매로 시장 변동성을 심화시켰다. 이에 따라 안철수 국민의힘 의원은 상장폐지와 금융당국 수장 파면을 요구하며 단일종목 레버리지 금지 및 액티브 ETF 규제 완화를 제안했고, 금감원장은 가계 재무건전성 훼손 우려를 제기하며 소비자 설명 강화와 모니터링 강화를 추진 중이다. 민주당도 제도 보완 필요성을 제기하며 불완전 판매 예방 및 취약계층 보호 장치를 점검하고, 메가 프로젝트를 통한 시장 안정화 방안을 모색하고 있다.',5,0,1,4,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GZSWGNZSMNRGKZJZMQ3WINZUGY.jpg','2026-07-27 16:28:33.271320'::timestamp,'2026-07-27 19:04:11.742168'::timestamp,NULL,NULL,'단일종목 레버리지 ETF의 괴리율 확대 사고와 LP 관리 강화 방안은 기존 토픽의 사건 전개와 직접적인 연관성 있음','금융당국이 단일종목 레버리지 ETF의 괴리율 확대 사고를 막기 위해 유동성공급자(LP) 관리 강화 방안을 검토 중이다.','title: 단일종목 레버리지 ETF 괴리율 확대 사고에… LP 관리 강화 방안 검토
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1416,NULL,'경제','신동빈 회장, 롯데바이오 송도 공장 점검','신동빈 롯데그룹 회장은 인천 송도에 위치한 롯데바이오로직스 1공장을 방문해 시설 점검과 글로벌 위탁개발생산(CDMO) 사업 준비 상황을 점검했다. 송도 1공장은 2024년 착공 후 약 2년 만에 건설을 완료하고 사용승인을 획득했으며, 미국 시러큐스 공장과의 ''듀얼 사이트'' 전략을 통해 2024년 하반기부터 시운전을 시작해 GMP 인증을 연내 완료하고 내년부터 본격적인 상업 생산에 들어갈 계획이다. 이에 맞춰 롯데바이오로직스는 2553억원 규모의 유상증자를 통해 공장 잔금 및 운영 비용을 확보했으며, 그룹은 총 1조4600억원을 바이오 분야에 투자하며 글로벌 CDMO 경쟁력 강화를 지속하고 있다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G43DKYZVGQ2TMNJYHEYWKNBQMM.jpg','2026-07-27 16:28:57.232832'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'신동빈 롯데그룹 회장이 3일 인천 송도에 위치한 롯데바이오로직스 1공장을 방문해 주요 시설을 점검하고 글로벌 위탁개발생산(CDMO) 사업 준비 상황을 살폈다.','title: 신동빈 회장, 롯데바이오 송도 공장 점검…“바이오는 새 도약 핵심"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1417,NULL,'경제','카드사, 저신용자 금리 하락 고신용자 금리 상승','5월 전업카드사 평균 카드론 금리는 13.54%로 전월 대비 0.03%p 하락했으나, 신용점수 700점 이하 저신용자 금리는 평균 0.09%p 하락한 반면 900점 초과 고신용자 금리는 0.47%p 상승했다. 이는 정부의 포용금융 정책과 중금리대출 공급 확대를 위한 총량 예외 인센티브 적용이 중저신용자 대상 금리 하락을 유도한 것으로 분석된다. 자금조달 비용은 금융채Ⅱ 3년물 금리가 1월 3.3%에서 5월 4.2%로 상승하며 증가했으나, 저신용자 금리 하락은 리스크 관리와 정책 유도의 결과로 보인다. 금융당국은 가계대출 증가세를 1.5% 이내로 관리하고 있으며, 카드사들은 일일·주간·월간 보고 체계를 통해 감독을 받고 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAYTOMBZGE4DOMJQMEZGCMRXGU.jpg','2026-07-27 16:29:56.597129'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'5월 전업카드사 평균 카드론 금리는 13.54%로 전월 대비 0.03%p 하락했다.','title: 카드사 포용금융에...카드론 금리 저신용자 내리고 고신용자 오르고
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1418,NULL,'경제','금융위, 청년 재무상담 서비스 시행','금융위원회는 만 19~34세 청년을 대상으로 청년미래적금을 234만3000명이 신청하며, 27일부터 계좌 개설을 시작했다. 이 상품은 연 1000만원까지 납입 가능하며, 정부가 연 50만원까지 보조금을 지급하고, 최대 연 19.4%의 금리(이자소득 비과세 및 정부 기여금 포함)를 제공한다. 신청자 중 30~34세가 38.8%로 가장 많았으며, 자격심사는 6일부터 3주간 진행되어 24일에 개별 안내를 완료했다. 청년미래적금 가입자 중 재무상담을 완료한 경우 우대금리 0.2%포인트가 적용되며, 상담은 온라인, 찾아가는, 금융기관 방문 중 선택 가능하다.',3,0,1,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRSGEZLGHE3GMNLGG5RDKNZZHE.jpg','2026-07-27 16:30:02.116206'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'금융위원회는 6일부터 만 19~34세 청년을 대상으로 상시 재무상담 서비스를 시행한다.','title: 청년 재무상담 받으면 미래적금 우대금리… 6일부터 신청
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1419,NULL,'국제','세계 정상, 미국 건국 250주년 축하 메시지 발송','미국 건국 250주년을 맞아 프랑스, 독일, 영국, 이스라엘, 아랍에미리트, 사우디아라비아, 인도, 일본 등 세계 각국 정상들이 축하 메시지를 보내며 미국과의 동맹 및 협력 관계를 강조했다. 이는 미국이 자유와 민주주의, 책임을 기반으로 세워진 국가라는 점과 대서양 동반자 관계의 중요성을 부각하기 위한 것으로, 프랑스 파리 에펠탑, 독일 베를린 브란덴부르크문 등 주요 상징물에 미국 국기 색상 조명을 점등하며 기념했다. 영국, 프랑스, 독일 등 주요 동맹국과 이스라엘, 아랍에미리트 등 중동 국가들이 미국의 번영과 자유의 수호를 기원하며, 인도와 일본은 민주주의와 법치, 역사적 교류를 기반으로 한 협력 강화를 약속했다. 이와 함께 러시아, 우크라이나, 카타르, 파키스탄 등 분쟁 당사국 및 중재국도 축하 메시지를 발표하며 국제적 공감대를 형성했으며, 교황도 종교의 자유를 미국의 핵심 가치로 평가하며 기념 분위기를 뒷받침했다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRTGCOBRME4GEZJXGYYGIMTDGY.jpg','2026-07-27 16:30:11.604813'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'프랑스 파리 에펠탑에 미국 건국 250주년을 기념해 빨강·흰색·파란색 조명과 ''USA 250'' 문구가 점등됐다.','title: 세계 정상들, 美 건국 250주년 축하…‘동맹과 협력’ 한목소리
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1420,NULL,'경제','신한금융, AI 전환 경영 포럼 개최','신한금융그룹은 2024년 6월 3~4일 경기 용인 신한은행 블루캠퍼스에서 ''2026년 하반기 경영 포럼''을 개최하고, ''생동하는 신한, 압도적 몰입''을 슬로건으로 인공지능 전환(AX)과 시장 지위 강화 전략을 논의했다. 진옥동 회장은 ''야성''을 강조하며 차별화된 상품·서비스 개발과 몰입 기반의 도전적 목표 설정의 필요성을 언급했으며, 그룹 경영진 300여 명과 자회사 비상임이사, 실무자로 구성된 워킹그룹이 참여했다. 포럼에서는 2030년 시장에서 사라진 상황을 가정한 영상 시청, 외부 시각 점검, 시행착오 반성 세션, AX 정밀 진단 등이 진행되었고, 자체 개발한 AI 에이전트가 경영진 토론에서 레드팀 역할을 수행하며 실시간 분석과 반론 제시를 통해 의사 결정을 지원했다. 신한은행은 이와 병행해 ''와이드 앤드 딥''(Wide & Deep) 전략을 발표하며 고객 접점 확대와 차별화된 솔루션 제공을 핵심 방향으로 삼고, 그룹 통합 앱 ''신한 슈퍼SOL''과 비금융 플랫폼을 통한 접점 확장, AI 기반 업무 생산성 제고를 추진하며 2026년 하반기까지 실질적 성과 도출을 목표로 하고 있다.',2,1,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAYWMOBQGA2TANRTG4ZTAMDCG4.jpg','2026-07-27 16:30:19.727701'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'신한금융그룹은 2026년 하반기 경영 포럼을 3~4일 경기 용인 신한은행 블루캠퍼스에서 개최했다.','title: 진옥동 신한금융 회장 “야성으로 미래 금융혁신 주도”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1421,NULL,'경제','6일부터 서울 외환시장에서 원화와 달러를 주중 24시간 거래한다.','6일부터 서울 외환시장은 원화와 달러를 주중 24시간 거래한다. 기존 거래 시간(오전 9시~익일 오전 2시)에서 확대되어 월요일 오전 6시부터 토요일 오전 6시까지 연중무휴로 운영되며, 주말과 1월 1일을 제외한 공휴일에도 거래가 가능해졌다. 첫 거래일인 7일 오전 6시 기준 원·달러 환율은 전 거래일 종가 대비 0.3원 내린 1530.0원을 기록했고, 달러인덱스는 장중 101선을 넘어섰으나 오전 6시 15분 기준 100.84를 기록했다. 엔·달러 환율은 162.053엔으로 상승하며 원·엔 재정환율은 100엔당 943.26원으로 전날보다 0.26원 하락했다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HE4WCOLFGE2TAMJUGEZGGMRQMQ.jpg','2026-07-27 16:30:40.069442'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'6일부터 서울 외환시장에서 원화와 달러를 주중 24시간 거래한다.','title: 6일부터 원화와 달러 주중 24시간 거래…외환 거래 공백 줄지만, 환율 변동성 커질 우려
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1422,NULL,'경제','김용범 정책실장, AI 생산혁명론 발표','김용범 청와대 정책실장은 5일 페이스북에 게시한 ''AI 생산혁명론''에서 인공지능이 기술혁명이 아닌 생산혁명이라고 강조하며, 국가의 역할은 AI 기반 생산 인프라 구축과 분배 체계 마련이라고 밝혔다. 그는 AI가 연구개발, 소프트웨어 개발, 물류 최적화 등에서 실패 비용을 줄이고 자본의 제약을 완화해 생산 효율을 극대화한다고 설명하며, 향후 핵심은 AI의 설계보다는 생산·운영 능력이라고 지적했다. 김 실장은 국가의 역할을 전력망 조성, 산업부지 개발, 공급망 조직 등 인프라 구축과 교육을 통한 생산능력 재생산, 초과이윤을 다음 세대의 생산력으로 투자하는 분배 체계 마련으로 규정했다. 이후 정부는 AI 기반 생산혁명 시대에 맞춰 산업정책을 시장 조절에서 국가 전체를 하나의 생산 플랫폼으로 조직하는 방향으로 전환할 예정이며, 교육, 이민, 창업 정책도 생산능력 확대를 위한 제도로 재정립될 것으로 보인다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MFTGMMRWMFSTQMTDMI4TCMBTGE.jpg','2026-07-27 16:30:49.848837'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'김용범 청와대 정책실장이 5일 페이스북에 ''AI 생산혁명론''이라는 제목의 글을 올려 인공지능은 기술혁명이 아닌 생산혁명이라며 국가의 역할은 생산 인프라 구축과 분배 방안 마련이라고 밝혔다.','title: 김용범 靑 정책실장 “AI는 생산혁명...국가는 인프라 구축·분배해야”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1423,NULL,'경제','농식품 수출액 사상 최대 기록','올해 상반기 농식품 및 농기자재 등 농산업 관련 수출액은 70억5천만달러로 사상 최대를 기록했다. 라면 수출액은 9억4천만달러로 작년 대비 27.9~28% 증가하며 주요 성장 동력이 되었고, 미국과 중동, 중남미 지역에서의 수출이 확대되었다. 과자류는 4억달러로 7% 이상 증가했으며, 아이스크림, 김치, 농기계, 비료 등도 유럽, 인도, 필리핀 등지로 수출이 확대되었다. 하반기 농림부는 해외 인·허가 지원과 현지 마케팅 확대를 통해 수출 회복을 추진하며, K-푸드의 해외 시장 확대와 수출 다각화 전략을 지속할 계획이다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAYTIZBZMY2TOZRXME2DKNJXHA.jpg','2026-07-27 16:31:58.042985'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'농림축산식품부는 올해 상반기 농식품 및 농기자재 등 농산업 관련 수출액이 70억5000만달러를 돌파했다고 5일 밝혔다.','title: 올 상반기 농식품산업 수출 70억달러 돌파… 역대 최고치
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1424,NULL,'경제','삼성전기 주가 상승률 1위','올해 상반기 코스피 상장사 중 주가 상승률 1위를 기록한 삼성전기는 1~6월 동안 주가가 756.4% 상승하며 시가총액을 20조1672억원에서 163조1310억원으로 증가시켰다. 이는 AI 서버용 MLCC 수요 증가와 1조6000억원 규모의 실리콘 커패시터 및 4500억원 규모의 MLCC 공급 계약 체결이 주요 원인으로, 삼성전자와 SK하이닉스를 상회하는 성과를 거두었다. 지난주(6월 29일~7월 3일) 외국인 투자자는 코스피에서 19조8374억원을 순매도했으나 삼성전기에는 4462억원을 순매수하며 4개 종목 중 가장 많은 금액을 투입했다. 증권사들은 하반기 실적 개선과 공급 부족 심화 전망을 바탕으로 목표주가를 대폭 상향하며, AI 수혜 지속 가능성에 따른 추가 상승 전망을 제시하고 있다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GYYTSZLCMU2DGODDGBQTMOBRGU.jpg','2026-07-27 16:32:05.911253'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성전기는 2024년 1월 초 27만원대에서 6월 말 218만4000원으로 주가가 상승하며, 1~6월 주가 상승률 756.4%를 기록했다.','title: 삼성전자·SK하이닉스도 아니었다… 상반기 주가 상승률 1위는 ‘MLCC’ 만드는 이 기업
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1425,NULL,'국제','OPEC+, 8월 원유 증산 논의','OPEC+는 8월에 하루 18만8천배럴의 원유 생산량을 증산하기로 결정하며, 4월부터 5개월 연속 증산을 이어가고 있다. 이는 2023년 4월 감산 이후 누적 165만 배럴의 생산량 회복을 목표로 하며, 9월에도 동일한 증산이 예정되어 있다. 호르무즈 해협의 정상화로 인한 생산 회복과 미국·이란 간 잠정 평화협상으로 에너지 공급이 안정화되고 있으나, 브렌트유와 WTI 가격은 약보합세를 유지하며 증산의 시장 영향력이 약화되고 있다는 분석이 제기되고 있다. 이에 따라 내년 공급과잉 우려와 이라크의 쿼터 증가 없이 탈퇴 가능성 등 협의체의 지속 가능성에 대한 우려가 커지고 있다.',3,1,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G44TIYRQGU2DQNBZMFSTSZLCG4.jpg','2026-07-27 16:32:32.319581'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'OPEC+ 소속 7개국 에너지 장관들이 8월 원유 생산 목표를 논의할 예정이다.','title: OPEC+, 5개월 연속 증산 전망… 내년 원유 공급과잉 우려
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1426,NULL,'경제','강훈식, 반도체 세수로 미래대응기금 신설 추진','정부는 반도체 산업 호황으로 예상되는 추가세수를 재원으로 하여 ''미래대응기금''을 특별법 형태로 신설할 계획이다. 이 기금은 3대 메가프로젝트(반도체, 피지컬 AI, AI 데이터센터) 지원, 청년 주거·일자리·창업 지원, 양극화 완화, 지방균형발전 등에 사용되며, 8월 정부 예산안 편성 시점에 구체적 방안을 반영할 예정이다. 지방 근로자에 대한 소득세 감면, 자녀 교육비 지원, 국유재산을 활용한 청년 창업·주거 공간 확대 등 세제 및 인프라 지원도 병행하며, 2027년까지 청년·서민용 공공주택 3만5000호를 공급하는 목표도 유지된다. 관련 법안은 9월 정기국회 전에 처리를 목표로 하며, 산업통상부와 민주당은 메가특구법 및 관련 입법 절차 개편을 추진 중이다.',17,1,3,13,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G5TDGZTDGYZWIYZYHEYGGZLBGQ.jpg','2026-07-27 16:32:41.264947'::timestamp,'2026-07-27 19:05:16.464601'::timestamp,NULL,NULL,'반도체 호황에 따른 세수 증가와 기금 신설은 후속 정책 전개이지만, 기존 토픽과는 주체, 지역, 쟁점, 전개 흐름이 모두 다름','강훈식 대통령비서실장이 5일 고위당정협의회에서 반도체 호황으로 발생한 추가 세수를 활용해 ''미래대응기금'' 신설을 추진한다고 발표했다.','title: 강훈식 “반도체 추가 세수로 미래대응기금 신설”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1427,NULL,'경제','전남 신안 지도 인근 해역에서 잡은 자연산 민어를 한입 크기로 손질해 부레, 뱃살, 몸통살, 꼬릿살 등 모든 부위를 포함한 민어회를 3만원대 초특가로 공동구매했다.','전남 신안 지도 인근 해역에서 잡은 자연산 민어를 한입 크기로 손질해 부레, 뱃살, 몸통살, 꼬릿살 등 모든 부위를 포함한 민어회를 3만원대 초특가로 공동구매한 것이 핵심 사건이다. 민어는 7월 초부터 9월 말까지가 제철이며, 신안 지도 해역의 풍부한 플랑크톤과 조류로 인해 살이 단단하고 풍미가 뛰어나 고급 횟감으로 평가된다. 제품은 약 300g으로 성인 2~3인이 먹기에 적당하며, 4중 포장과 통얼음 사용으로 한여름에도 신선도를 유지해 배송 후 바로 섭취 가능하다. 이후에는 신선도 유지와 보관 방법에 대한 소비자 반응이 주목되며, 냉동 보관은 피하고 수령 당일 또는 하루 냉장 보관을 권장하는 점이 후속 쟁점으로 부각되고 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/LYQUITOQUSVWHVVXCEHZQKRFFI.jpg','2026-07-27 16:32:43.138295'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'전남 신안 지도 인근 해역에서 잡은 자연산 민어를 한입 크기로 손질해 부레, 뱃살, 몸통살, 꼬릿살 등 모든 부위를 포함한 민어회를 3만원대 초특가로 공동구매했다.','title: 비싸서 먹기 어려웠던 민어회 한 접시, 부레 포함 3만원대 초특가 공동구매
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1428,NULL,'정치','조국, 일베 표현과 사투리 구분 주장','조국 전 조국혁신당 대표가 걸그룹 리센느 멤버의 ''무섭노'' 발언을 일베식 혐오 표현으로 지적하며 논란을 일으켰다. 이에 대해 야권과 시민사회는 사투리까지 일베로 낙인찍는 언어 감시의 위험성을 지적하며, 정치적 개입과 표현의 자유 침해를 우려했다. 나경원 국민의힘 의원은 민주당의 이중 잣대를 문제 삼으며, 최욱의 ''탱크 발언''에 대한 침묵을 비판하며 표현의 자유와 사회적 책임의 경계에 대한 논의가 확산되고 있다고 지적했다. 이는 방언의 정체성, 정치적 낙인찍기, 언어 감시의 경계를 둘러싼 사회적 논의로 확대되고 있으며, 향후 정책적 논의의 주요 이슈로 부상할 전망이다.',3,1,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MY4DINLGMQ2GCOJVHAZTGNTDGE.jpg','2026-07-27 16:33:03.608644'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'조국 전 대표가 5일 페이스북에 글을 올려 일베는 표준어 뒤에 기계적으로 ''노''를 붙여 사용한다고 설명하며 영남 사투리와 일베의 ''노'' 사용을 구별해야 한다고 주장했다.','title: 조국, ‘무섭노’ 일베 감별법에... 野 “말끝 하나로 사상 검증?”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1429,NULL,'경제','삼성전자 DX 부문 성과급 불만 반응','삼성전자 DX 부문 직원들이 반도체(DS) 부문과의 성과급 격차에 불만을 표하며 ''We Deserve It'' 영상 제작 및 공유로 내부 갈등이 확산됐다. DS 부문은 2024년 메모리 사업부 평균 5억5000만원의 특별경영성과급을 받은 반면, DX 부문은 1인당 약 756만원 상당의 자사주를 지급받아 직원 간 불균형이 부각됐으며, DX 부문 임직원 약 5만2000명 중 절반 이상이 영상에 공감했다. 임금협약 체결로 분쟁은 일시 종결되었으나, 노조 찬성율 차이(80.6% vs 21.1%)로 공정성 논란이 지속되며 산업 전반의 성과급 이중구조와 노노갈등이 심화되고 있다. 정부는 경영성과급에 이사회 사전 검토와 주주총회 결의를 의무화하는 방안을 검토 중이며, 노동법제 현대화와 계약 기반 법제 도입 등이 제안되고 있다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GJRTMZLFGRSDINBSMMYGMNJUME.jpg','2026-07-27 16:33:27.024734'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성전자 DX 부문 직원들이 반도체(DS) 부문과의 성과급 격차를 비판하며 ''We Deserve It''이라는 영상 제작 및 공유를 시작했다.','title: “갤럭시 만들었는데, 빌어먹을” 노래까지 나온 성과급 갈등
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1430,NULL,'경제','금융위, 기후변화 공시 의무화 방침 추진','금융위원회가 2028년부터 연결 자산 총액 10조원 이상 코스피 상장사 107곳을 대상으로 기후변화가 매출·생산 시설·공급망에 미치는 영향과 탄소 배출량·감축 목표를 사업보고서에 의무적으로 공시하도록 하는 방침을 추진 중이다. 이는 유럽연합(EU) 및 일본 등 해외 추세에 부합하려는 것으로, 기업의 지속 가능성 대응을 투자자 판단에 반영하기 위한 목적이다. 하지만 기업들은 추정치가 많은 미래 전망 정보를 법적 구속력 있는 공시 대상으로 삼을 경우 허위·누락 공시 논란과 형사 책임 위험에 직면할 수 있다고 우려하며, 초기에는 한국거래소에 공시하는 방식으로 유예 기간을 두고 점진적으로 법정 공시로 전환할 것을 요구하고 있다. 이후 2030년에는 자산 2조원 이상 기업까지 대상이 확대되며, 협력사의 공정, 임직원 출퇴근, 소비자 사용·폐기 과정 등 기업 밖에서 발생한 탄소까지 포함될 가능성이 있어, 데이터 수집 및 정확도 문제와 함께 제3자 인증 기준의 불명확성, 컨설팅 업체 수익 증가 우려도 제기되고 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GRQTEZTFGRRTONRVHFTDCMZVHE.jpg','2026-07-27 16:34:09.630576'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'금융위원회가 2028년부터 연결 자산 총액 10조원 이상 코스피 상장사 107곳을 대상으로 기후변화가 매출·생산 시설·공급망에 미치는 영향과 탄소 배출량·감축 목표를 사업보고서에 의무적으로 공시하도록 추진한다.','title: [단독] 기후변화가 매출에 미칠 영향도 사업보고서에 써라? 금융위 방침에 재계 비상
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1431,NULL,'경제','롯데건설, 성수4지구 시공사 선정','롯데건설이 서울 성동구 성수동2가 219-4번지 일대에서 진행되는 성수4지구 재개발 사업의 시공사로 선정됐다. 총 공사비는 1조3628억 원으로, 지하 6층에서 지상 최고 64층, 1439가구 규모의 ''성수 르엘 S70''으로 조성될 예정이다. 조합원 753명 중 620명이 참여한 투표에서 롯데건설이 449표, 대우건설이 169표를 얻어 승리했으며, 최저 이주비 20억 원 조건은 제안서에서 삭제됐다. 시공사 선정 과정에서 조합의 절차적 중립성과 정보 공개 문제 등이 제기되며, 계약 이행과 조합 운영의 신뢰 회복이 향후 과제로 남았다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/G5STMZLGMYZWEY3GMYZDMMTFGU.jpg','2026-07-27 16:34:31.148927'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'롯데건설이 2024년 5월 5일 서울 성동구 성수동2가 219-4번지 일대에서 진행되는 성수4지구 재개발 사업의 시공사로 선정되었다.','title: 롯데건설, ''1.3조'' 성수4지구에 ''르엘'' 꽂았다...대우건설에 수주전 승리
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1432,NULL,'정치','추미애, 경기도 병원 괴롭힘 점검 지시','2024년 3월 3일 추미애 경기도지사는 광주 병원 간호사의 ''태움'' 사망 사건을 계기로 경기도의료원 산하 6개 병원(수원·의정부·파주·이천·안성·포천)에 직장 내 괴롭힘 실태 전면 점검을 지시했다. 이는 병원 내 위계적 폭력과 괴롭힘 문화가 뿌리내린 상황에서 발생한 피해 사례로, 피해자에 대한 안타까움과 함께 ''태움''을 교육이 아닌 명백한 직장 내 괴롭힘으로 규정한 것이 배경이다. 점검은 익명 상담과 현장 면담을 통해 진행되며, 도내 120여명의 마을노무사를 통해 노동자 권리구제를 지원하고, 2024년 170명, 2025년까지 총 562명 규모의 지방노동감독관 조직을 차질 없이 구축할 예정이다. 이후 3년간 소규모 사업장과 취약 노동현장을 중심으로 임금체불, 부당한 근로조건, 산업안전 기준 위반, 직장 내 괴롭힘 등 반복적 문제를 예방하는 방향으로 정책을 추진할 계획이다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279583_450589_537.jpeg','2026-07-27 16:34:38.955976'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'추미애 경기도지사가 2024년 3월 3일 경기도의료원 산하 6개 병원에 직장 내 괴롭힘 실태 전면 점검을 지시했다.','title: 추미애 “‘태움’은 위계폭력”... 병원 내 괴롭힘 점검 지시
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1433,NULL,'국제','경찰, 광주일고 폭파 협박 글 수사 착수','광주일고에 폭발물을 설치했다는 협박성 게시글이 온라인 커뮤니티에 게시되면서 경찰청은 5일 수사에 착수했다. 이 사건은 4일 오후 11시 47분경 특정 온라인 커뮤니티에 ''광주일고에 폭발물을 설치했다. 배재고 청소년들의 미래를 짓밟았다''는 내용의 협박성 글이 올라온 데서 시작되었으며, 이는 전날 광주일고 야구부가 전국대회에서 배재고 선수단의 지역 비하성 응원으로 인해 상처를 입은 사건과 관련이 있다. 경찰과 소방은 해당 게시글을 접한 후 폭발물 수색 작업을 실시했으나 특이 사항은 발견되지 않았고, 현재까지 피해는 없었다.',1,1,0,0,0,'https://www.pressian.com/_resources/10/2026/07/05/2026070510241759857_l.jpg','2026-07-27 16:34:44.940260'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'경찰청은 5일 광주일고에 폭발물을 설치했다는 협박성 게시글을 접한 후 수사에 착수했다.','title: [속보] 경찰, ''광주일고 폭파물 설치'' 협박 사건 수사 착수
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1434,NULL,'정치','이재명 대통령이 2024년 7월 5일 공식 X 계정을 통해 트럼프 대통령과 미국 국민에게 미국 독립 250주년을 축하하며 한미동맹의 새로운 도약을 밝혔다.','이재명 대통령은 2024년 7월 5일 미국 독립 250주년을 맞아 공식 X 계정을 통해 트럼프 대통령과 미국 국민에게 축하 인사를 전하며 한미동맹의 새로운 도약을 강조했다. 이는 한국전쟁 당시 미국의 희생을 기리며 70년 이상 지속된 한미 안보 동맹의 가치를 재확인하는 것으로, 최근 안보를 넘어 경제, 첨단기술, 에너지, 원자력, 인공지능 등 미래 분야로 협력 영역을 확대하고 있는 상황이다. 현재 한미동맹은 군사적 협력뿐 아니라 기술·에너지 분야에서의 공동 연구 및 투자 확대를 추진 중이며, 양국은 2025년까지 협력 프로젝트를 정비할 계획이다. 이에 따라 한미동맹의 지속 가능성과 미래 협력 방향에 대한 논의가 정책 회의와 외교적 대화를 통해 이어질 전망이다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279584_450590_357.jpg','2026-07-27 16:34:57.525901'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령이 2024년 7월 5일 공식 X 계정을 통해 트럼프 대통령과 미국 국민에게 미국 독립 250주년을 축하하며 한미동맹의 새로운 도약을 밝혔다.','title: 이재명 대통령 “미국 독립 250주년, 한미동맹 새 도약”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1435,NULL,'정치','정보통신망법 개정안이 7일 시행되었다.','2024년 7월 7일, 정보통신망법 개정안이 시행되며, 고의로 허위·조작 정보를 유포한 게재자는 손해액의 최대 5배 배상 책임을 지고, 법원 판결로 확인된 정보를 2회 이상 반복 유포한 경우 최대 10억원의 과징금이 부과된다. 대규모 플랫폼(하루 100만명 이상 이용)과 구독자 10만명 이상 또는 월평균 조회수 10만회 이상 유튜버는 허위정보 신고 처리 및 삭제·차단 의무를 지닌다. 이 법은 악의적 가짜뉴스와 혐오 표현에만 적용되며, ''핀셋 규제''라며 여당은 정당한 비판과 감시는 보호한다고 설명했으나, 야당과 시민단체는 허위 정보 기준의 모호성과 표현의 자유 침해를 우려하며 헌법소원을 예고하고 법의 재개정을 요구하고 있다. 이후 법의 시행 이후 공론장의 자기 검열 현상과 플랫폼의 과잉 삭제 조치 우려가 제기되며, 사실확인 기관의 독립성, 신고 제도 남용 방지, 정보 처리 내역 공개 절차 등이 후속 논의의 주요 과제로 부상했다.',9,2,2,5,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GBSTSYLFMYYDCOLDGY4DMMLBMU.jpg','2026-07-27 16:36:52.498752'::timestamp,'2026-07-27 19:03:48.304871'::timestamp,NULL,NULL,'정보통신망법 개정안 시행과 야당·시민단체의 법 개정 요구는 같은 사안의 후속 전개로, 허위 정보 기준 모호성과 표현의 자유 침해라는 쟁점이 일치함','정보통신망법 개정안이 7일 시행되었다.','title: 정보통신망법 내일 시행… 野 “국민 입틀막법, 법 개정 나설 것”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1436,NULL,'국제','트럼프, FIFA 회장에게 발로건 징계 재검토 요청','도널드 트럼프 전 미국 대통령은 2022년 카타르 월드컵 32강전에서 레드카드를 받은 미국 축구대표팀 공격수 폴라린 발로건의 출전정지 처분에 대해 FIFA 회장 잔니 인판티노와 직접 통화해 재검토를 요청한 것으로 확인됐다. 발로건은 상대 수비수의 발목을 밟아 퇴장했으나, FIFA는 규정 제27조에 따라 징계 집행을 1년간 유예하는 이례적 결정을 내렸으며, 이는 1962년 이후 64년 만에 처음이다. 이에 유럽축구연맹(UEFA)과 벨기에축구협회는 ''규칙 훼손''과 ''정치적 개입''을 지적하며 항소를 제기했고, 국제사회에서는 스포츠 기관의 중립성과 공정성에 대한 논의가 확산되고 있다. 현재 항소 절차가 진행 중이며, FIFA는 결정이 독립적으로 이뤄졌다고 밝혔다.',10,4,2,4,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/6NDRNF76OVOLLE4MRMCCJOYR6I.jpg','2026-07-27 16:39:00.327882'::timestamp,'2026-07-27 19:03:24.337765'::timestamp,NULL,NULL,'트럼프 대통령의 FIFA 회장 전화 요청은 후보 토픽의 ''트럼프 미국 대통령이 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 했다''는 저장된 원인과 유사한 정치적 개입 행위로, 국제적 기관에 대한 직접적 영향을 주는 사건 흐름에 해당함.','도널드 트럼프 미국 대통령이 1월 1일 월드컵 32강전 직후 잔니 인판티노 FIFA 회장에게 전화를 걸어 미국 축구대표팀 공격수 폴라린 발로건의 출전 정지 징계 재검토를 요청했다.','title: 트럼프가 FIFA에 직접 전화? 美 에이스 퇴장 징계 뒤집혔다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1437,NULL,'정치','제주도의회, 제13대 의회 개원 및 상임위원장 선출','제주특별자치도의회는 2024년 4월 2일 제13대 의회 개원식을 개최하고, 송영훈 의장이 의장으로 선출된 후 상임위원장 선거를 진행했다. 이는 1일 제1차 본회의에서 의장단을 구성한 데 이어, 의정활동을 본격화하기 위한 절차로, 전반기 상임위원장 7명이 선출됐다. 개원식 이후 의원들은 국립제주호국원과 제주4·3평화공원을 참배하며 책임 있는 의회 운영을 다짐했으며, 송영훈 의장은 민생 중심, 미래지향, 도민 신뢰를 기반으로 한 ''행동하는 의회''를 목표로 제시했다. 이후 제13대 의회는 민생 정책과 지역 현안 해결을 위한 상임위원회 활동을 본격화할 예정이며, 정파 간 협력과 소통을 통한 의정 활동의 질적 향상이 주요 과제로 부상하고 있다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279595_450608_218.jpg','2026-07-27 16:40:24.459488'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'제주특별자치도의회는 2024년 4월 2일 개원식과 경축연회를 열고 제13대 의회의 의정활동 시작을 공식적으로 알렸다.','title: 제주도의회, 새 임기 첫발...“행동하는 의회 되겠다”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1438,NULL,'정치','더불어민주당 제주특별자치도의회 김대진 의원이 제13대 의회 더불어민주당 교섭단체의 제1기 원내대표단을 확정했다.','제13대 제주도의회 더불어민주당은 김대진 의원을 원내대표로 선출하고, 수석부대표 양경호, 정책위의장 강명균, 부대표 장정훈·박안수·오경남, 대변인 고석준·오은초로 구성된 제1기 원내대표단을 확정했다. 이는 제주도의회가 2024년 7월 1일 제13대 의회로 개원한 후 여당으로서의 교섭단체 운영을 위한 조직 구성을 마무리한 것으로, 전문성과 경험을 갖춘 인물들로 팀을 구성해 소통과 협력을 중시하는 운영 체계를 구축했다. 현재 원내대표단은 의원 간 소통 창구로서의 역할과 정책 역량 강화를 통해 제주도민의 삶을 최우선으로 하는 정책 마련과 집행부와의 건전한 협력·견제를 추진하고 있다. 향후 원내대표단은 제주도정의 정책 추진에 대한 견제와 협력, 민생 안정 및 제주 발전을 위한 의정 활동의 성과를 높이기 위한 구체적 정책 제안과 의회 운영 방향을 수립할 예정이다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279596_450609_3032.jpg','2026-07-27 16:40:32.032520'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'더불어민주당 제주특별자치도의회 김대진 의원이 제13대 의회 더불어민주당 교섭단체의 제1기 원내대표단을 확정했다.','title: 민주당 제주도의회, 김대진 원내대표 체제 원내대표단 구성
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1439,NULL,'사회','정유사 4사, 중동 전쟁 후 가격 담합 기소','2024년 3월 중동 전쟁 발발 직후, HD현대오일뱅크와 SK에너지 등 국내 4대 정유사가 공정거래법 위반 혐의로 기소됐다. 검찰 조사 결과, 이들 기업은 2024년 7월부터 2025년 2월까지 가격 정보를 공유하고 사전에 가격 인상 합의를 한 것으로 확인됐으며, 특히 SK에너지가 리터당 30~40원 추가 인상 방식으로 시장 가격을 조정했다. GS칼텍스와 에쓰오일은 이를 따르며 유가 상승을 유도했고, 전체 담합으로 인한 경쟁 제한 효과는 약 26조 원으로 추산된다. 이로 인한 피해 규모는 14조2000억 원으로 집계되었으며, 전량구매계약 강제, 공정위 조사 회피, 산업부 허위 보고 등 부가적 위법 행위도 적발됐다.',5,2,0,3,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MZSDAYTGGZTDKNLGHEZWMZBSGA.jpg','2026-07-27 16:41:34.219184'::timestamp,'2026-07-27 19:02:26.124940'::timestamp,NULL,NULL,'검색 후보 없음','2024년 3월 4일, 국내 4대 정유사와 임직원 4명이 중동 전쟁 발발 직후 가격 정보를 공유하고 가격 급등을 합의하여 공정거래법 위반 혐의로 기소됐다.','title: 중동 전쟁에 “트럼프 만세”...檢, ‘14조 유가 담합’ 정유 4사·임직원 기소
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1440,NULL,'사회','광주경찰서 수사팀장 증거인멸 혐의 수사','광주지검은 장윤기 여고생 살인 사건의 부실 수사와 경찰 유착 의혹을 규명하기 위해 2026년 7월 7일 광주광산경찰서 형사과 및 수사팀장 A경감 자택 등 5곳에서 압수수색을 실시했다. 수사팀장은 케이블타이 등 핵심 증거를 확보하지 않아 증거인멸 혐의로 긴급체포되었으며, 경찰청은 홍장득 총경이 팀장인 27명 규모의 특별수사팀을 편성해 독립적으로 수사를 진행하고 있다. 검찰은 공무상비밀누설 및 증거인멸 혐의로 수사팀 관계자들을 입건했고, 장윤기 아버지인 장모 경감은 친족 특례로 형사입건되지 않았으나 유착 의혹 조사 대상이다. 현재까지 케이블타이 등 핵심 증거는 확보되지 않았으며, 수사 결과는 국가수사본부장에게 보고될 예정이다.',16,5,6,5,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GZSDEYRSGU4DGMRQHA3GIODFGA.jpg','2026-07-27 16:42:48.065915'::timestamp,'2026-07-27 19:05:05.766014'::timestamp,NULL,NULL,'장윤기 사건과 관련된 수사팀의 증거인멸 혐의로, 후보 토픽과는 지역, 주체, 쟁점이 다르며 별도의 사건 전개로 판단됨','광주광산경찰서 소속 담당 팀장이 증거인멸 등 혐의로 체포되었다.','title: 장윤기 아버지·수사팀 유착 정황... 궁지 몰린 경찰 “엄정 수사하겠다”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1441,NULL,'정치','정부는 6일 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다.','정부는 6일 이재명 대통령 주재로 ''3대 메가 프로젝트'' 일환으로 호남권 반도체 클러스터를 광주 군공항 부지(약 250만 평, 여의도 면적의 약 3배)에 조성하기로 결정했다. 해당 부지는 국유지로 평탄화가 완료되어 공사 기간 단축이 가능하며, 도심 및 KTX역 인접으로 인력 확보와 정주 여건이 우수하고, 토지 수용과 보상 절차가 간소화된 점이 선정 요인이다. 정부는 전력(1GW), 산업용수(6만t 이상) 확보와 함께 군공항 이전 과정에서의 안보 공백 해소를 위한 후속 절차를 추진하며, 매달 민관합동 점검회의를 개최해 프로젝트 진도를 직접 관리할 계획이다. 이에 따라 2027년부터 본격적인 공사에 들어가고, 2026년 하반기 중 토지 보상 절차를 완료하는 것을 목표로 하고 있다.',31,11,5,15,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/XDAPVE4B4RMD3PUEAOPVLHLWMY.jpg','2026-07-27 16:43:09.489188'::timestamp,'2026-07-27 19:02:42.214920'::timestamp,NULL,NULL,'정부의 반도체 클러스터 조성 결정은 광주 군공항 부지의 적합성에 기반한 구체적 실행 결과로, 후보 토픽의 ''광주 군공항 부지의 적합성''이라는 원인과 직접적인 결과 흐름을 이룬다.','정부는 6일 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다.','title: 靑 “호남 반도체 클러스터, 광주 군공항 부지에 조성”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1442,NULL,'사회','경기남부경찰청, 간호사 일기장 분석 중','경기남부경찰청은 20대 간호사 A씨가 병원에서 약 1년간 선배 간호사로부터 지속적인 괴롭힘을 당한 뒤 지난 3월 병원을 그만두고 노동당국에 진정을 제기한 사건을 조사 중이다. A씨는 2월 2일 자택에서 숨진 채 발견되었으며, 경찰은 유족과 동창 등에 대한 참고인 조사를 완료하고 일기장, 휴대전화 등을 분석 중이다. 병원 측은 노동당국 조사 결과 일부 사실을 인정받아 시정 지시를 받았고, 경찰은 광역범죄수사대장을 팀장으로 하는 20명 규모의 수사전담팀을 구성해 증거 분석을 마친 뒤 입건 여부를 결정할 예정이다. 또한 전북 군산시의 한 종합병원에서 근무한 20대 방사선사 A씨도 출근하지 않은 지 3일 만에 아파트 화단에서 숨진 채 발견되었으며, 유족과 지인들은 직장 내 괴롭힘을 주장하고 있다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRSTEMBRMJSWEN3DGRQTGMRZGI.jpg','2026-07-27 16:43:29.487119'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'경기남부경찰청이 유족으로부터 제출받은 A씨의 일기장과 휴대전화 등을 분석 중이다.','title: 병원 근무 1년간 ‘괴롭힘’ 기록... 경찰, ‘태움 사망 간호사’ 일기장 분석
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1443,NULL,'국제','트럼프, 나토 동맹국에 이란 전쟁 불참 비판','2024년 7월 7일 터키 앙카라에서 열린 나토 정상회의는 도널드 트럼프 미국 대통령의 국방비 증액 압박과 미국산 무기 구매 촉진을 중심으로 진행됐다. 트럼프는 이란 공습에 동맹국들이 병력 파견을 거부한 점을 비판하며, 2035년까지 GDP 대비 5% 국방비 투자 합의 이행 여부를 점검하고, 유럽 국가들이 지난해 5740억달러(약 880조원)의 국방비를 투입해 전년 대비 20% 증가한 실적을 거둔 점을 공식적으로 부각했다. 이와 함께 유럽은 미국산 무기 주문 규모가 3000억달러에 달하며, 영국과 독일은 라이선스 생산을 통해 자국 내 생산을 확대하고 있다. 회의에서는 제5조 집단방위 조항 재확인, 우크라이나 및 이란 문제, 호르무즈 해협 해양 안보 협력 등이 논의되었으며, 이재명 대통령은 방산 수출 외교를 위해 인도·태평양 파트너(IP4) 국가들과의 협력 강화를 주도했다.',8,4,0,4,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GRRWCM3FMJRGMYZXGQ3TCMJZGA.jpg','2026-07-27 16:43:57.220135'::timestamp,'2026-07-27 19:02:54.073542'::timestamp,NULL,NULL,'트럼프의 이란 전쟁 불참 비판과 유럽 동맹국의 병력 파견 거부는 후보 토픽의 ''트럼프 대통령이 폭염 속에서도 긴 연설을 했다''는 사건과 동일한 주체와 정치적 맥락에서 발생한 국제적 이슈 전개로, 이념적 분열과 동맹 정책에 대한 비판이라는 쟁점 흐름이 일치함','도널드 트럼프 미국 대통령이 2024년 7월 튀르키예 앙카라에서 열리는 나토 정상회의를 앞두고, 최근 이란 전쟁에 직접 참전하지 않은 일부 유럽 동맹국을 비판하며 동맹에 ''충성''을 추궁했다.','title: ‘돈 더 냈지만, 참전은 안했다’… 美 트럼프, 나토 정상에 이란戰 불참 추궁
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1444,NULL,'사회','국민의힘은 제13대 경남도의회 개원일에 의원만 참석한 투표를 통해 전반기 의장, 제1부의장, 제2부의장 모두를 단독 선출했다.','제13대 경남도의회는 6일 개원일에 국민의힘 의원만 참석한 투표를 통해 전반기 의장(박준), 제1부의장(신종철), 제2부의장(이찬호)을 단독 선출하며 의장단을 싹쓸이했다. 이는 6·3지방선거에서 국민의힘 44석, 민주당 23석을 차지한 다수당 지위에 기반한 것으로, 민주당은 의석 비율에 따라 부의장 1석, 상임위원장 2석을 요구했으나 국민의힘은 부의장 1석, 상임위원장 1석만 제안하며 협상이 결렬됐다. 민주당은 본회의장 퇴장과 항의 시위를 벌이며 협치 테이블을 요구했고, 개원식은 민주당 의원들이 참석한 가운데 진행됐다. 이후 7일 오후 2시 제2차 본회의에서 운영위원회 등 7개 상임위원회 위원장을 선출할 예정이며, 원 구성 협의는 여전히 결렬 상태로 지속될 전망이다.',2,0,0,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/46GNI7IZCFPRJFN3AS3EC5U4G4.jpg','2026-07-27 16:44:06.906600'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국민의힘은 제13대 경남도의회 개원일에 의원만 참석한 투표를 통해 전반기 의장, 제1부의장, 제2부의장 모두를 단독 선출했다.','title: 국민의힘, 경남도의회 의장단 싹쓸이 강행에 민주당 반발
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1445,NULL,'국제','중국 해군, 태평양에서 잠수함발사탄도미사일 시험 발사','2026년 7월 6일 중국 해군은 보하이해에서 전략핵잠수함을 통해 잠수함발사탄도미사일(SLBM)을 시험 발사하며, 이는 1982년 이후 처음으로 태평양 공해상으로 발사된 핵무기 탑재 미사일이다. 발사된 미사일은 사거리 7000km 이상으로 추정되며, JL-2 또는 JL-3 계열로 분석되며, 중국은 이를 연례 군사 훈련의 일환으로 설명하며 관련국에 사전 통보했다고 밝혔다. 일본, 호주, 뉴질랜드는 투명성 부족과 역내 안정 침해를 우려하며 반발했고, 미국은 정기적 통보 체제 마련과 군비통제 논의 참여를 촉구했다. 나토 사무총장은 중국의 군사력 증강에 대해 ''순진하게 대응해선 안 된다''며 인도태평양 지역과의 글로벌 안보 연계 필요성을 강조했다.',15,4,6,5,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/42FS4GLAJBGDROK4TWZ3W6JVUI.png','2026-07-27 16:44:46.889380'::timestamp,'2026-07-27 19:03:12.292406'::timestamp,NULL,NULL,'후보 토픽과는 지역과 주체가 다르며, 사건 전개 흐름이 별개이므로 같은 사안으로 보기 어렵다.','중국 해군 전략핵잠수함이 6일 태평양 공해 해역에서 훈련용 모의 탄두를 탑재한 잠수함발사탄도미사일 한 발을 성공적으로 발사했다','title: 중국 핵잠수함, 태평양으로 탄도미사일 쐈다… 美·日 동맹망 압박
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1446,NULL,'국제','베냐민 네타냐후 이스라엘 총리가 2023년 10월 5일 미국 폭스뉴스 인터뷰에서 이란 문제를 포함해 미국과의 관계에 균열이 없다고 밝혔다.','베냐민 네타냐후 이스라엘 총리는 2023년 10월 5일 폭스뉴스 인터뷰에서 이란 핵 문제를 포함해 미국과의 관계에 균열이 없다고 밝혔으며, 양국이 이란의 핵무기 프로그램 폐기와 핵연료 농축시설 해체라는 공동 목표를 공유하고 있다고 강조했다. 2024년 4월 5일 동일한 매체에 출연한 네타냐후는 레바논 남부의 보포르 능선과 리타니강 인근에서 헤즈볼라에 대한 군사 작전을 지속하며, 헤즈볼라 무장해제 전까지 철수하지 않겠다고 밝혔다. 이는 미국과 이란이 맺은 종전 양해각서(MOU) 제1조의 전선 중단 요구와 충돌하며, 이스라엘은 협상 당사자가 아니라는 입장을 고수하고 있다. 네타냐후는 트럼프 대통령과의 관계를 ''99% 생각이 같으며 균열이 없다''고 일축하며, 백악관 회동을 제안받아 NATO 정상회의 다음 주에 회담이 열릴 가능성을 시사했다.',2,1,0,1,0,'https://img.mbn.co.kr/newmbn/white.PNG','2026-07-27 16:44:56.150803'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'베냐민 네타냐후 이스라엘 총리가 2023년 10월 5일 미국 폭스뉴스 인터뷰에서 이란 문제를 포함해 미국과의 관계에 균열이 없다고 밝혔다.','title: 네타냐후 "이란 문제, 미국과 균열 없다…우린 모범 동맹"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1447,NULL,'경제','호날두, 2026 월드컵 마지막 출전 선언','크리스티아누 호날두(41, 알나스르)가 2026 북중미 월드컵을 자신의 마지막 월드컵이라고 밝혔다. 호날두는 2006년 독일 월드컵부터 6회 연속 출전하며 월드컵 역사상 최다 출전 기록을 보유하고 있으며, 이번 대회에서는 조별리그에서 우즈베키스탄전 2골, 32강전 크로아티아전 페널티킥 1골을 기록했다. 그는 월드컵 우승이 자신의 이력을 완성하는 데 필수적이지 않다고 강조하며, 경기에서의 열정과 즐거움을 중시한다고 밝혔다. 다음 16강전에서 스페인과 맞붙게 되며, 라민 야말에 대해 미래의 주목할 만한 선수라고 평가하며 스페인팀에 대한 존중을 표했다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.542bc47389394ad5bb0860d1bab73e36_P1.jpg','2026-07-27 16:46:20.761997'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'크리스티아누 호날두가 2026 북중미 월드컵이 자신의 마지막 월드컵이 될 것이라고 밝혔다.','title: “내일이 마지막이 아니길”…이번이 월드컵 마지막이라는 호날두
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1448,NULL,'경제','노르웨이, 브라질 격파로 8강 진출','2026 FIFA 월드컵 북중미 지역 16강전에서 노르웨이 축구대표팀이 브라질을 2대1로 물리치고 사상 첫 8강 진출을 달성했다. 엘링 홀란은 후반 34분 헤더와 후반 45분 왼발 슈팅으로 멀티골을 기록하며 팀 승리를 이끌었고, 이번 대회 득점 공동 선두에 올랐다. 브라질의 네이마르는 후반 23분 교체 출전해 추가 시간 페널티킥 골을 기록하며 대표팀 데뷔전 장소인 미국 뉴욕 뉴저지 스타디움에서 은퇴를 선언했다. 경기 후 라커룸에서 노르웨이 공주 잉리드 알렉산드라와 그의 남동생 스베레 마그누스가 선수들을 축하했으며, 홀란은 상의를 탈의한 상태에서 공주와 포옹하는 장면이 화제가 되었다.',3,0,0,3,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.a3597649361c471ebde0543b249d0749_P1.jpg','2026-07-27 16:46:45.480281'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'노르웨이 축구대표팀은 2026 FIFA 월드컵 북중미월드컵 16강전에서 브라질을 2대1로 물리쳐 사상 첫 8강 진출을 달성했다.','title: 노르웨이, 브라질 격파… ‘멀티골’ 홀란, 바이킹 노젓기도 리드
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1449,NULL,'정치','이재명 대통령은 6일 청와대에서 한성숙 신임 국무총리와 주례 보고 회동을 열고, 총리에게 AI 대전환, 규제 합리화, 창업 르네상스, 청년 정책 내실화를 4대 역점 과제로 지정하고 전권을 부여해 국정 전반의 근본적 혁신을 이끌어달라고 주문했다.','이재명 대통령은 6일 청와대에서 한성숙 신임 국무총리와 주례 보고 회동을 갖고, AI 대전환, 규제 합리화, 창업 르네상스, 청년 정책 내실화를 4대 역점 과제로 지정하고 전권을 부여해 국정 전반의 근본적 혁신을 추진하도록 주문했다. 이 대통령은 총리의 IT 전문성과 민간 혁신 경험을 인정하며 AI·데이터 기반 국민 생명 보호 방안의 신속한 추진을 지시했고, 향후 정기적인 회동을 통해 국정 현안을 점검하기로 했다. 이날 서남권 반도체 클러스터 민관합동 점검회의에서는 야당의 메가 프로젝트 비판에 대해 ''실현 가능성을 판단해 협조하거나 반대해야 한다''며 방해를 자제할 것을 당부했고, 이에 대해 야당은 프로젝트 재검토 필요성을 제기하며 향후 국회 심사 절차가 예정된 상태다. 총리실은 4대 과제에 대한 구체적 실행 계획 수립과 정부 내부 혁신 추진 절차를 진행할 예정이다.',2,1,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/33SOPVQABZJZ5P27JJW2HE2BLY.jpg','2026-07-27 16:47:16.671697'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이재명 대통령은 6일 청와대에서 한성숙 신임 국무총리와 주례 보고 회동을 열고, 총리에게 AI 대전환, 규제 합리화, 창업 르네상스, 청년 정책 내실화를 4대 역점 과제로 지정하고 전권을 부여해 국정 전반의 근본적 혁신을 이끌어달라고 주문했다.','title: 李대통령, ‘4대 역점 과제’ 보고한 韓총리에 “전권 갖고 국정 혁신 이끌어 달라”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1450,NULL,'정치','강북구, 장애인 통합돌봄 서비스 본격 시행','서울 강북구는 65세 미만 심한 장애인을 대상으로 보건·의료, 일상돌봄, 주거지원을 통합한 통합돌봄 서비스를 2024년 4월부터 본격 시행한다. 기존 동 주민센터 중심의 노인 통합돌봄과 달리 구청이 행정과 서비스를 총괄하며, 사전조사 절차를 간소화하고 종합판정조사 중심의 단일 체계를 도입했다. 서비스 대상은 강북구에 거주하는 65세 미만 심한 장애인으로, 초기에는 지체·뇌병변 장애인을 우선 지원하며, 총 65개의 맞춤형 서비스를 제공한다. 이후 3개월마다 정기 모니터링을 실시하고, 이상 징후 발생 시 48시간 이내 보고해 7일 이내 지원계획을 조정하는 등 지속적인 사후관리를 시행할 예정이다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:49:01.261434'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울 강북구는 2024년 4월부터 65세 미만 심한 장애인을 대상으로 보건·의료, 일상돌봄, 주거지원을 통합한 통합돌봄 서비스를 본격 시행한다.','title: 촘촘한 돌봄으로 잇는 일상…강북구, 장애인 통합돌봄 본격 시동
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1451,NULL,'사회','서울시 종로구는 2일 창신소담 공영주차장 및 복합시설을 한국부동산원으로부터 ''장애물 없는 생활환경(Barrier Free)'' 본인증 우수등급을 받았다.','서울시 종로구는 창신소담 공영주차장 및 복합시설이 2일 한국부동산원으로부터 ''장애물 없는 생활환경(Barrier Free)'' 본인증 우수등급을 받았다. 이 시설은 지하 1층에서 지하 5층까지의 주차공간(총 180면, 장애인전용주차구역 4면 포함)과 지상 1층 청소년 소담도서관, 2층 청소년문화의집, 3층 한옥 청소년 문화의집으로 구성되어 있다. 점검 결과, 차량 진입로는 보행통로와 구분돼 있으나 주차현황판에 장애인전용주차구역 안내가 부족했으며, 지상 1층 주출입문은 여닫이로 점자블록 설치로 인해 휠체어 이용 시 불편이 발생했다. 또한 2층 모임룸 책상 높낮이 조절 불가, 3층 한옥 구조로 휠체어 접근 어려움, 세면대 하부 배관 방해, 휴지걸이 높이 등 개선이 필요한 시설이 확인됐으며, 향후 시설 개선 및 정기 점검이 예정되어 있다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202607/231844_128571_2930.jpg','2026-07-27 16:49:32.517260'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울시 종로구는 2일 창신소담 공영주차장 및 복합시설을 한국부동산원으로부터 ''장애물 없는 생활환경(Barrier Free)'' 본인증 우수등급을 받았다.','title: 장애물 없는 종로구 창신소담 공영주차장 및 복합시설 장애인 편의 점검
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1452,NULL,'경제','삼성화재, ''온(ON)통보장'' 출시','삼성화재는 암·뇌혈관·심장질환 등 6개 질병 영역의 치료비와 간·폐·신장·근골격계 질환까지 보장하는 신상품 ''온(ON)통보장''을 출시했다. 기존 상품은 치료비 보장에 그쳤으나, 이번 상품은 치료비 외에도 돌봄 서비스인 방문요양과 가사 돌봄을 지원하는 요양보호사 서비스를 추가하며 치료 후 회복 단계까지 보장하는 통합보장 구조를 도입했다. 가입 후 10년마다 보장금액이 최초 수준으로 복원되며, 치료비로 사용하지 않은 잔여 보장금액의 일정 비율을 사망보험금(상해)으로 활용할 수 있다. 삼성화재는 이 상품을 건강고지형과 간편고지형으로 운영하며, 갱신형·비갱신형 및 해약환급금 미지급형을 선택할 수 있도록 했으며, 향후 의료 환경 변화에 맞춘 서비스 확대를 예고했다.',1,0,0,1,0,'https://img.mbn.co.kr/newmbn/white.PNG','2026-07-27 16:50:13.098032'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성화재가 암·뇌혈관·심장질환 등 6개 질병 영역의 치료비와 간·폐·신장·근골격계 질환까지 보장하는 신상품 ''온(ON)통보장''을 출시했다.','title: 삼성화재, ''온(ON)통보장'' 출시…치료비 넘어 돌봄까지 보장
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1453,NULL,'정치','서울 노원구는 2024년 7월 22일부터 8월 20일까지 산책로 11곳과 하천변 7곳 총 18곳에서 ''힐링냉장고''를 운영해 무료 냉장 생수를 제공한다.','서울 노원구는 2024년 7월 22일부터 8월 20일까지 산책로 11곳과 하천변 7곳 총 18곳에서 ''힐링냉장고''를 운영해 무료 냉장 생수를 제공한다. 이는 2020년부터 시행된 폭염 대응 사업으로, 전국 지방자치단체가 벤치마킹한 제도로, 지난해에는 약 228만 병의 생수를 공급하고 약 183만 병을 회수해 회수율 80%를 기록했다. 생수는 하루 평균 8~12차례 보충되며, 회수된 페트병은 친환경 의류 등으로 재활용되며, 지난해 만족도 조사에서 응답자 4만 5786명 중 98.2%가 만족했다. 노원구는 우천 시 운영 중단 여부를 현장 여건에 따라 판단하며, 자율방재단이 현장 관리를 맡는다.',1,0,1,0,0,'https://www.seoulnews.org/storage/advertisement/g2iCfL5r9dRILd3iZCuj8KDf9h9Ac9AlaxEca4uG.jpg','2026-07-27 16:50:34.833470'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울 노원구는 2024년 7월 22일부터 8월 20일까지 산책로 11곳과 하천변 7곳 총 18곳에서 ''힐링냉장고''를 운영해 무료 냉장 생수를 제공한다.','title: 노원구 ''힐링냉장고'' 올해도 뜬다... 산책로·하천변 18곳에 무료 냉장 생수 제공
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1454,NULL,'국제','정몽규 축협 회장 사임','정몽규 대한축구협회 회장이 2026년 월드컵을 앞두고 6일 천안 코리아풋볼파크에서 열린 마지막 임원회의를 마무리하며 사임서를 제출했다. 그는 2013년 첫 당선 이후 11년간 4선을 역임했으며, 지난달 29일 월드컵 전 사퇴를 공식 선언한 바 있다. 사임 후 협회는 정관 제23조에 따라 부회장 중 한 명이 대한체육회의 인준을 거쳐 회장 직무를 대행하며, 신임 회장 선출 절차와 함께 내부 혁신 및 조직 개편이 주요 과제로 부상하고 있다. 이와 함께 박지성을 중심으로 구성된 축구 혁신위가 제도적 개선과 투명성 강화를 위한 방안 수립을 진행 중이다.',2,2,0,0,0,'https://www.pressian.com/_resources/10/2026/07/06/2026070611191444699_l.jpg','2026-07-27 16:51:18.031206'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정몽규 대한축구협회 회장이 2024년 6월 6일 천안 코리아풋볼파크에서 열린 마지막 임원회의를 마무리하며 사임서를 제출했다.','title: 정몽규 축협 회장, 사임서 제출 quot;대한민국 축구는 다시 높이 비상할 것quot;
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1455,NULL,'국제','캐나다 정부가 초계잠수함 프로젝트(CPSP)의 우선협상대상자로 독일 TKMS를 선정했다.','캐나다 정부는 2024년 7월 6일 차세대 잠수함 프로젝트(CPSP)의 우선협상대상자로 독일 티센크루프마린시스템즈(TKMS)를 선정했다. 이는 빅토리아급 잠수함 4척을 대체하는 12척 규모의 디젤 잠수함 건조 사업으로, 총비용은 약 60조 원(600억 캐나다달러)이며, 2034년부터 첫 4척이 인도될 예정이다. 한국의 한화오션이 TKMS와 함께 적격 후보로 선정되었으나, 나토 동맹국인 독일의 군수 상호운용성과 장기적 안보 협력 관계를 고려해 수주에 실패했으며, TKMS와의 협상이 결렬 시 한화오션을 예비 공급업체로 지정할 계획이다. 정부는 결과를 존중하면서도 기술력과 성능 면에서 국제 경쟁력을 입증한 점을 긍정적으로 평가하고, 연구개발, 수출 지원, 국제협력 강화를 통해 향후 방산 수출 경쟁력을 제고할 방침이다.',17,3,5,9,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GQ2TOYRTHFRDKN3CHE3TENJSME.jpg','2026-07-27 16:51:47.628862'::timestamp,'2026-07-27 19:03:12.292406'::timestamp,NULL,NULL,'캐나다의 초계잠수함 프로젝트 선정은 중국의 SLBM 시험 발사와 마찬가지로 인도태평양 지역의 군사력 증강과 안보 연계를 둘러싼 국제적 동향의 일환으로, 전략적 군사 협력과 지역 안정성 문제라는 공통 쟁점이 있음','캐나다 정부가 초계잠수함 프로젝트(CPSP)의 우선협상대상자로 독일 TKMS를 선정했다.','title: 캐나다 매체 “60조 캐나다 잠수함…韓 아닌 獨 TKMS 선정”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1456,NULL,'국제','폴 매카트니, 62년 만에 ''아이 원트 홀드 유어 핸드'' 불러','2024년 9월 3일(현지시간) 미국 뉴욕 매디슨 스퀘어가든에서 팝스타 테일러 스위프트와 미식축구 선수 트래비스 켈시의 결혼식이 비밀리에 치러졌다. 결혼식에는 폴 매카트니가 축가로 1964년 이후 62년 만에 ''아이 원트 홀드 유어 핸드''를 불러 화제가 되었으며, 배우 애덤 샌들러가 주례를 맡았다. 참석자는 가족·친구·지인 포함 1000명 이상으로, 식장 인근 교통 통제와 삼엄한 경비로 인해 지역 상인과 주민들 사이에서 전력난과 영업 피해에 대한 불만이 제기되었다. 결혼식 전 스위프트 부부는 뉴욕 지역 및 국립 자선단체 20곳에 총 2600만 달러(약 400억 원)를 기부했으나, 여전히 호화 결혼식에 대한 비판 여론이 지속되고 있으며, 정보 통제와 비밀 유지 조항의 철저함이 권력과 영향력의 상징으로 지적되고 있다.',1,1,0,0,0,'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260706.366efcf029534c028019c056a2742584_P1.jpg','2026-07-27 16:51:54.837094'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 9월 뉴욕 매디슨 스퀘어가든에서 폴 매카트니가 62년 만에 ''아이 원트 홀드 유어 핸드''를 불렀다.','title: 62년 만에 ‘이 노래’ 부른 매카트니···테일러 스위프트 ‘세기의 결혼식’이 드러낸 것
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1457,NULL,'국제','러시아, 키이우에 미사일·드론 공격','2024년 7월 5일부터 6일에 걸쳐 러시아는 나토 정상회의 개막 전날인 7월 5일과 6일 새벽, 우크라이나 수도 키이우를 대상으로 탄도미사일 68발, 드론 351대를 포함한 대규모 복합 공격을 감행했다. 이 공격으로 키이우 시내 및 외곽 지역에서 최소 23명 사망, 100명 이상 부상하며 주거지역과 기반시설이 파괴되고 아파트 3동이 붕괴되는 등 심각한 피해가 발생했다. 러시아는 군수산업 및 에너지 시설을 타격했다고 주장했으나, 우크라이나는 외교적 관심이 집중되는 시점에 의도적으로 공격을 실시한 것이라며 국제적 대응을 촉구했다. 젤렌스키 대통령은 패트리엇 방공체계의 요격미사일 재고 부족 문제를 지적하며 미국과 유럽의 추가 지원을 요청했고, 트럼프 미국 대통령과의 회동 및 EU의 방공 능력 증강 논의가 예정되어 있다.',7,0,3,4,0,'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134250171.1.thumb.jpg','2026-07-27 16:52:01.532307'::timestamp,'2026-07-27 19:03:24.337765'::timestamp,NULL,NULL,'러시아의 키이우 공격은 후보 토픽의 ''트럼프 미국 대통령이 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 했다''는 사건과 직접적인 외교적 전개 관계를 가지며, 공격 전후의 외교적 대응과 방공체계 지원 요청이 같은 사안의 연속이다.','러시아는 6일(현지시간) 우크라이나 수도 키이우 일대에 미사일과 드론을 다수 발사했다.','title: 러시아, 우크라 키이우 닷새만에 재공습…사망 6명·부상 18명
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1458,NULL,'경제','금융연구원, 원달러 환율 1500원대 유지 전망','2024년 이후 원·달러 환율이 1400~1500원대에 고착화되며 금융권의 리스크가 확대되고 있다. 6대 은행의 거래상대방신용위험(CCR)은 2026년 1분기 기준 26조원으로 2년 전 대비 45% 증가했으며, 기업의 환헤지 파생계약 증가와 내국인의 해외주식 투자 확대가 주요 원인이다. 금융연구원은 환율이 1500원대를 상당 기간 유지할 가능성이 높다고 전망하며, 강달러 국면은 약 10개월 지속될 것으로 예측했다. 정부는 24시간 외환시장 운영을 통해 시장 모니터링을 강화하고 있으나, 야간 변동성 확대와 금융사의 자본 적정성 관리가 시급한 상황이다.',5,0,1,4,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.674b0c0e60cf42b8b55fdff94d6a7d43_P1.jpg','2026-07-27 16:52:46.192437'::timestamp,'2026-07-27 19:04:23.407564'::timestamp,NULL,NULL,'환율 상승과 금융 리스크 확대는 코스피 급락과 같은 시장 하방 압력의 연속적 전개로, 외국인·기관 매도와 시장 변동성 확대라는 공통 요인을 공유함','한국금융연구원, 2024년 하반기 이후 원·달러 환율이 1400~1500원대를 상당 기간 유지될 가능성이 높다고 전망했다.','title: 금융硏,“1500원대 환율…상당 기간 유지될 가능성 높아”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1459,NULL,'경제','금감원, 30년 국채 금리 상승 시 손실 경고','금융감독원은 국채도 만기 전 매도 시 시장금리 상승으로 인해 평가손실이 발생할 수 있다고 경고하며, 30년 만기 국채는 시장금리가 1%p 상승할 경우 약 17%의 손실이 발생할 수 있다고 설명했다. 이는 국채가 신용위험이 낮아 안전자산으로 분류되지만, 장기채는 금리 변동에 민감해 중도 매도 시 가격 하락 위험이 있다는 배경에서 비롯된 것으로, 최근 고령 투자자 등이 판매직원의 권유로 장기채를 매수한 사례에서 부적합한 권유가 발생한 점이 원인이다. 2025년 1분기 기준금리 2.75%에서 2분기 2.50%로 하락했지만, 국고채 30년물 금리는 3분기 2.80~2.95%, 4분기 3.10~3.20%로 상승하며 채권가격 하락이 발생했으며, 장외채권 거래 시 민평금리와 실제 매매수익률의 차이도 손실 원인이 될 수 있다. 금감원은 투자자 보호를 위해 장내채권 거래 정보 확인과 장외거래 시 수익률 차이 분석을 당부하며, 향후 분쟁사례를 바탕으로 제도 개선을 추진할 계획이다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.b99f4c46f457489fae5e519c6312f8e9_P1.jpg','2026-07-27 16:54:53.478557'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'금융감독원이 30년 만기 국채의 시장금리가 1%p 상승할 경우 약 17%의 평가손실이 발생할 수 있다고 안내했다.','title: 금감원 “국채 무조건 안전자산 아냐”…30년 국채금리, 1%p 오르면 17% 손실
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1460,NULL,'사회','전국 교육청, 현금 지원 예산 3배 증가','2021년부터 2026년까지 전국 시도교육청의 학생 대상 현금 및 현물 지원 예산은 2846억원에서 7658억원으로 2.7배 증가했으며, 이는 학생 수 감소와 함께 재정 적자 확대 속에서 발생한 현상이다. 인천·강원·부산 등 여러 교육청이 초등입학 준비금, 진로활동지원금, 현장체험학습비 등 다양한 사업을 시행했고, 광주교육청의 꿈드리미, 경기도교육청의 운전면허 취득비 지원 등이 대표적 사례로 지적됐다. 교육부는 상위 8개 교육청에 대해 2027년부터 지방교육재정교부금을 10억원씩 삭감하는 페널티를 적용할 예정이며, 기획예산처와 교육부는 교부금 산정 방식 개선을 위해 공개 토론회를 개최할 계획이다. 이종욱 국회의원은 일률적 지원의 적정성과 정책 효과를 검증해야 한다며, 취약계층 지원은 유지하되 재정 효율성 확보가 필요하다고 주장했다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MMZWKZBVMRQWGMLDHBQWCZLGGQ.jpg','2026-07-27 16:56:22.043172'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'인천교육청은 2023년부터 초등학교 입학생 모두에게 입학 준비금 20만원씩을 매년 41억~48억원씩 지원하기 시작했다.','title: [단독] 전국 교육청, 5년간 현금 지원 예산 3배로 늘렸다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1461,NULL,'정치','이병태 대통령 직속 규제합리화위원회 부위원장이 6일 청와대의 사퇴 권고에 따라 자진 사퇴했다.','이병태 대통령 직속 규제합리화위원회 부위원장이 5·18 민주화운동을 ''성역''이라고 표현하며 배재고등학교 야구부의 응원 구호를 비판한 발언으로 논란을 일으켰다. 청와대는 이 발언이 정부의 혐오·조롱에 대한 단호한 거부 기조와 부합하지 않으며, 책임 있는 공직자로서 부적절하다고 판단해 4일 공개 경고한 후, 6일 사퇴를 권고했다. 이 부위원장은 권고 후 약 두 시간 만에 자진 사퇴했으며, 청와대는 이를 수용했다. 이 사건은 표현의 자유와 역사적 민감성 간의 갈등, 공직자의 발언 책임, 정치적 갈등 심화 문제를 촉발하며, 향후 정책적 일관성과 교육 현장의 역사 교육 방향성에 대한 논의로 확산되고 있다.',13,8,1,4,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/ULBNT3QWAZBU5C26ZPRDUZXWTA.gif','2026-07-27 16:57:26.787136'::timestamp,'2026-07-27 19:04:00.088313'::timestamp,NULL,NULL,'이병태 부위원장의 5·18 민주화운동 비판 발언은 국조특위의 허위정보 규제 논의와 표현의 자유 침해 문제와 직접적인 관련이 있으며, 공직자의 발언 책임과 정치적 갈등 심화라는 쟁점이 일치함','이병태 대통령 직속 규제합리화위원회 부위원장이 6일 청와대의 사퇴 권고에 따라 자진 사퇴했다.','title: ‘5·18 발언’ 이병태, 靑 권고에 결국 자진사퇴
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1462,NULL,'경제','삼성카드, iD 셀렉트업 카드 출시','삼성카드는 6일 소비 패턴에 맞춰 의료 및 생활 혜택을 직접 선택할 수 있는 ''삼성 iD 셀렉트업 카드''를 출시했다. 이 카드는 전월 이용 실적을 충족할 경우 병·의원, 약국, 요양병원, 동물병원 이용금액의 20%를 월 최대 1만5000원까지 할인하거나, 보험료, 주유, 이동통신 요금 결제금액의 10%를 동일한 한도로 할인받을 수 있도록 설계됐다. 모든 가맹점에서 0.5% 기본 할인을 제공하며, 할인점·온라인쇼핑몰은 1%, 골프·항공·면세점·철도·공연 업종은 2% 할인을 제공하고, 해외 이용 수수료 할인 및 병원·약국 업종 2~3개월 무이자 할부도 지원한다. 연회비는 국내전용과 해외겸용 모두 1만8000원이며, 고객은 발급 시 및 이용 중 매월 혜택을 변경할 수 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.7688908d859046169bc08a781887dcac_P1.jpg','2026-07-27 16:57:51.885062'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성카드는 6일 소비 패턴에 맞춰 의료 및 생활 혜택을 직접 선택할 수 있는 ''삼성 iD 셀렉트업 카드''를 출시했다.','title: 병원비·보험료 할인혜택…삼성카드 ‘iD 셀렉트업’ 출시
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1463,NULL,'정치','2023년 10월 15일 가해자 B는 피해자 A를 살해한 혐의로 기소되었다.','2023년 10월 15일 경기 성남에서 전 연인인 60대 여성 피해자 A를 살해한 혐의로 가해자 B가 기소되었다. 피해자는 스토킹 신고를 여러 차례 한 바 있으나, 위험도 평가에서 ''보통''으로 분류되어 전자장치 부착이나 구속 처분이 이뤄지지 않았으며, 접근금지 명령을 위반한 것으로 확인되었다. 가해자 B는 구속 상태이며, 검찰은 영장 청구를 하지 않았고 법원은 구속 전 피의자 심문을 진행 중이다. 이 사건은 피해자 보호 제도의 한계를 드러내며 전자장치 부착 요건 완화, 접근금지 기간 무기한 확대, 유관기관 간 정보 공유 체계 구축 등 제도 개선이 필요하다는 지적이 제기되고 있다.',2,1,1,0,0,'https://cdn.sisajournal.com/news/photo/202607/378849_386632_301.jpeg','2026-07-27 16:59:09.503618'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2023년 10월 15일 가해자 B는 피해자 A를 살해한 혐의로 기소되었다.','title: 결국 막지 못한 ‘성남 교제살인’…피해자는 ‘A등급’, 가해자는 ‘영장 제외’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1464,NULL,'정치','국민의힘 중앙윤리위원회가 6일 무소속 한동훈 의원을 지지한 당원들을 징계 심의 대상으로 결정했다.','국민의힘 중앙윤리위원회는 6일 부산 북갑 보궐선거에서 무소속 한동훈 의원을 지지한 당원들을 징계 심의 대상으로 결정했다. 이는 당헌·당규에 위반된 행위로 판단되며, 친한동훈계 의원들과 조경태 의원 등 수십 명이 징계 대상에 포함됐다. 장동혁 대표는 해당행위자에 대해 복당을 영구 금지해야 한다고 주장하며 당내 갈등이 심화되고 있으며, 윤리위는 비공개로 약 2시간30분 동안 심의를 진행했으나 아직 결론을 내리지 못했다. 징계 절차의 공정성과 기준 명확성에 대한 논란이 지속되며, 당내에서는 징계 정치의 부작용과 기강 확립 필요성에 대한 엇갈린 반응이 나타나고 있다.',8,4,2,2,0,'https://photo.jtbc.co.kr/news/jam_photo/202607/06/ae374ed5-7ac0-4a14-9b26-923e32008022.jpg','2026-07-27 17:02:02.734273'::timestamp,'2026-07-27 19:04:44.503964'::timestamp,NULL,NULL,'무소속 한동훈 의원 지지 행위와 징계 심의는 국조특위의 선거개혁 논의와 같은 정치적 갈등 흐름 속에서 발생한 사건으로, 당내 기강 문제와 징계 정치 논란이라는 공통 쟁점이 존재함','국민의힘 중앙윤리위원회가 6일 무소속 한동훈 의원을 지지한 당원들을 징계 심의 대상으로 결정했다.','title: 국민의힘 윤리위, ''한동훈 지원 의원'' 징계 심의 착수
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1465,NULL,'경제','직방, 서울 전용면적 59㎡ 아파트의 1월부터 6월까지 신규계약 보증금이 5억원에서 5억4750만원으로 4750만원 상승했다고 6일 밝혔다','서울 아파트 전세시장에서 신규계약과 재계약 간 보증금 격차가 심화되며 ''이중가격'' 현상이 지속되고 있다. 1월부터 6월까지 서울 전용면적 59㎡ 아파트의 신규계약 보증금은 5억원에서 5억4750만원으로 4750만원 상승한 반면, 재계약은 500만원 상승에 그쳐 차이가 7750만원으로 확대됐다. 전세 매물은 지난해 동기 대비 18.7% 감소하며 2만258건에 그치고, 전세수급지수는 126.7로 2021년 1월 이후 최고치를 기록하며 수요가 공급을 상회하는 상황이 지속되고 있다. 이는 토지거래허가제 확대, 전세대출 한도 축소, 신규 입주 물량 감소 등이 복합적으로 작용한 결과로, 월세 비율은 49.8%로 전세와 근접하며 월세화가 가속화되고 있다.',3,1,1,1,0,'https://img.khan.co.kr/news/2026/07/06/news-p.v1.20260601.c402b1fff64b41c8abfae29aaec9fdad_P1.png','2026-07-27 17:02:29.076284'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'직방, 서울 전용면적 59㎡ 아파트의 1월부터 6월까지 신규계약 보증금이 5억원에서 5억4750만원으로 4750만원 상승했다고 6일 밝혔다','title: 전세 부족이 만든 ‘이중가격’…서울 전세 재계약 500만원 올릴 때 신규는 5000만원 올렸다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1466,NULL,'국제','나토 사무총장, 방산 계약 발표 예정','2026년 7월 7일 튀르키예 앙카라에서 열린 나토 정상회의에서 마르크 뤼터 사무총장이 수백억 달러 규모의 신규 방산 계약을 발표할 예정이다. 이는 2023년 헤이그 정상회의에서 합의한 2035년까지 회원국이 GDP의 5%를 국방비로 지출하기로 한 목표의 이행 조치로, 유럽 및 캐나다 회원국들이 이미 약 4%를 투자하고 있는 상황에서 미국의 방위비 증액 압박에 대응하고자 마련된 실질적 조치다. 회의에서는 2035년 목표 달성을 위한 각국의 구체적 계획과 함께, 중국 견제 및 인도·태평양 지역 안보 전략 전환도 논의되며, 미국은 유럽 동맹국의 방위비 증액을 기반으로 미국산 무기 수출 기회를 확대하는 전략을 추진하고 있다. ''앙카라 선언''을 통해 집단 방위 원칙을 재확인하고 러시아에 대한 장기적 위협을 지적하며, 향후 계약 이행 상황과 방위비 분담 비율 변화에 대한 지속적 모니터링과 외부 감사 절차를 예정하고 있다.',4,0,2,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/SYBGLFWBOLG2HB5BH6TCGBAJEQ.jpg','2026-07-27 17:02:38.228735'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'나토 사무총장 마르크 뤼터가 7일 튀르키예 앙카라에서 열리는 나토 정상회의에서 수백억 달러 규모의 신규 방산 계약을 발표할 예정이다.','title: 나토 사무총장 “7일 수백억 달러 방산 계약 발표”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1467,NULL,'정치','한국 해군, RIMPAC에서 연합지휘 임무 수행','2026 환태평양훈련(RIMPAC)에서 한국 해군은 아시아 국가 최초로 연합해군구성부대사령관(CFMCC) 임무를 수행하며 다국적 해상작전을 지휘했다. 정조대왕함과 도산안창호함, P-8A 포세이돈 해상초계기 등 최신 장비를 활용해 방공전 훈련과 잠수함발사탄도미사일(SLBM) 수직발사관 6기, 중어뢰 ''범상어'' 발사관 등 전략무기 운용 능력을 공개했다. 도산안창호함은 4,300km에 이르는 장거리 작전을 통해 태평양을 횡단하며 국내 기술로 개발된 3천 톤급 잠수함의 전력 운용 능력을 입증했으며, 캐나다 정부가 발표할 예정인 60조 원 규모의 차세대 잠수함 사업 수주 가능성에 긍정적 영향을 미칠 전망이다. 미국의 원자력 항공모함 시어도어 루스벨트함(CVN-71)은 10만t 규모의 항공전력 기지로서 항공모함 중심의 유·무인체계와 정보 자산 통합 운용이 미래 해전의 핵심임을 보여주며, 한국 해군도 이에 맞춰 전력 체계 개편을 추진하고 있다.',3,0,0,3,0,'https://image.kmib.co.kr/online_image/2026/0707/2026070620070644668_1783336026_1783326745.jpg','2026-07-27 17:03:03.886398'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026 환태평양훈련(RIMPAC)에 참가한 한국 해군은 아시아 국가 최초로 연합해군구성부대사령관(CFMCC) 임무를 수행했다.','title: 진주만에 위용 드러낸 K-해군… 정조대왕함·도산안창호함 내부 공개
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1468,NULL,'국제','이란 초등학생 폭사 유가족, 하메네이 장례식 참석','2024년 2월 28일 이란 남부 미나브의 초등학교가 미군의 토마호크 미사일 공습으로 폭격되면서 최소 175명의 민간인이 사망했으며, 대부분은 어린이였다. 공격 피해 유가족들은 이란 수도 테헤란에서 열린 전 최고지도자 아야톨라 세예드 알리 하메네이의 장례식에 참석하기 위해 약 1300km 떨어진 지역에서 기차와 버스를 이용해 수일간 이동했다. 하메네이는 7일 곰에서 장례 예배를 거행한 뒤 8일 이라크의 시아파 성지 카르발라와 나자프로 운구된 후 9일 고향 마슈하드에 안장될 예정이다. 이란 의회 의장 모하마드 바게르 갈리바프는 미국과 이스라엘의 공습에 대해 복수를 경고하며 예루살렘 해방을 목표로 군사적·외교적 수단을 병행해 투쟁을 지속할 것임을 밝혔다.',2,1,1,0,0,'https://photo.jtbc.co.kr/news/jam_photo/202607/06/7c1c0d63-d707-4ad8-8dae-707ee7ce92d8.jpg','2026-07-27 17:03:13.081116'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'미군이 2024년 2월 28일 이란 남부 미나브 소재 초등학교를 토마호크 미사일로 공습했다.','title: 분노의 이란 초등생 폭사 유가족들, 최고지도자 장례식 참석
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1469,NULL,'경제','홈플러스, 카드사 지급 보류 철회 요구','2026년 7월 3일 서울회생법원은 홈플러스의 기업회생절차를 폐지했으나, 이는 즉시항고 가능 기간(14일)이 있어 법적 불확실성이 지속되고 있다. 홈플러스는 2000억 원의 운영자금 조달 실패로 파산 절차에 들어갈 위기에 처했으며, 메리츠금융그룹의 대출 제안이 MBK파트너스의 보증 부족으로 불발되며 자금 조달 협상이 결렬됐다. 삼성카드는 홈플러스의 반발에 따라 대금 지급 보류를 철회하고 정상 지급을 재개했으나, 현대카드는 포인트 결제만 중단했으며, 온라인몰 주문 취소 불가 및 상품 공급 중단으로 매장 운영이 사실상 정지된 상태다. 정부는 임금 체불 노동자에 대한 최대 2100만원 대지급과 중소기업·소상공인에 4400억 원 유동성 지원을 결정했으나, 회생을 위한 직접적 공적자금 투입은 이뤄지지 않았고, 시민사회는 정부의 긴급 개입과 MBK에 대한 수사 강화를 촉구하고 있다.',10,4,5,1,0,'https://cdn.sisajournal.com/news/photo/202607/378861_386643_3217.jpg','2026-07-27 17:04:04.738611'::timestamp,'2026-07-27 19:04:11.742168'::timestamp,NULL,NULL,'홈플러스의 자금 조달 실패와 카드사 지급 보류는 MBK파트너스의 개입과 자금 조달 논의라는 후속 전개와 직접적인 사건 흐름을 공유함','홈플러스가 2024년 3월부터 일부 카드사의 매출 대금 지급 보류를 즉각 철회할 것을 요구했다.','title: 홈플러스 “일부 카드사, 대금 지급 보류 즉각 철회해야”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1470,NULL,'정치','일베 사용자, 노무현·리센느 혐오 표현 확산','2024년 5월 23일, 대한민국의 온라인 커뮤니티 ''일베''(일반인 베이비)에서 ''노무현''과 ''리센느'' 등 정치적·문화적 인물에 대한 혐오 표현이 확산되며 사회적 논란이 일었다. 이는 5·18 민주화 운동을 기념하는 날에 발생한 것으로, 일베 사용자들이 특정 인물과 사건을 비하하는 표현을 반복적으로 사용하며 공적 논의의 토대를 훼손했다는 비판이 제기됐다. 관련 게시물은 수천 건에 달하며, 일부는 ''노무현''과 ''리센느''를 혐오 대상으로 지목해 사회적 갈등을 유발했고, 이에 대해 시민단체와 언론이 ''인터넷 혐오 표현의 확산''을 우려하며 제재 필요성을 강조했다. 이후 일베 운영진은 일부 게시물을 삭제했으나, 혐오 표현의 지속적 유포와 관련된 법적·제도적 대응 방안이 논의되고 있으며, 정부는 온라인 공간의 건전한 운영을 위한 정책 절차를 검토 중이다.',1,0,1,0,0,'https://cdn.sisajournal.com/news/photo/202607/378866_386648_5221.jpg','2026-07-27 17:05:48.330509'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 5월 23일, 일베 사용자들이 노무현과 리센느 등 정치적·문화적 인물을 혐오 대상으로 지목하며 혐오 표현을 확산시켰다.','title: ‘노무현’부터 ‘리센느’까지···‘일베 표 혐오’로 물드는 대한민국
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1471,NULL,'사회','경찰이 오늘 새벽 5시 20분쯤 서울 종로구 창신동의 한 거리에서 마약을 투약한 상태로 길바닥에 누워 있던 60대 남성을 마약류 관리법 위반 혐의로 긴급체포했다.','서울 종로구 창신동의 한 거리에서 오늘 새벽 5시 20분쯤 60대 남성이 마약을 투약한 상태로 길바닥에 누워 있는 것을 경찰이 발견하고, 온몸 떨림과 주머니 내 일회용 주사기, 팔의 주사 자국을 확인해 마약류 관리법 위반 혐의로 긴급체포했다. 이 남성은 음주 측정 결과 술을 마시지 않았으며, 경찰은 마약 간이시약 검사를 통해 실제 투약 여부와 범행 동기를 조사 중이다. 현재 남성은 서울 혜화경찰서에 구속되어 있으며, 마약 투약 사실이 확인될 경우 마약류 관리법에 따라 최대 10년 이하의 징역형에 처해질 수 있다. 경찰은 추가 조사와 함께 마약 사용의 유통 경로 및 관련 범죄 여부를 수사할 예정이며, 도심 내 마약 사용 사례가 증가함에 따라 관계 기관의 대응 방안이 주목받고 있다.',1,1,0,0,0,'https://photo.jtbc.co.kr/news/jam_photo/202607/06/1fbf1a6b-0f57-4f05-bd9c-ea0d96d76c97.jpg','2026-07-27 17:06:32.236811'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'경찰이 오늘 새벽 5시 20분쯤 서울 종로구 창신동의 한 거리에서 마약을 투약한 상태로 길바닥에 누워 있던 60대 남성을 마약류 관리법 위반 혐의로 긴급체포했다.','title: 서울 도심 한복판에 쓰러진 남성…온몸 떨며 주머니 주사기
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1472,NULL,'경제','정부, 2040년 원전 4기 추가 건설 결정','정부는 2040년까지 원전 4기를 추가로 건설해야 한다는 분석을 내놨다. 반도체 클러스터와 AI 데이터센터 등 대규모 전력 수요가 예상되며, 2040년까지 총 24.7GW의 추가 전력 수요가 발생할 것으로 전망된다. 기후에너지환경부는 12차 전력수급기본계획의 전력 수요 전망을 재산출하고, 전남 영광군과 울산 울주군에 원전 2기씩 총 4기 건설 가능 용지를 활용해야 한다고 밝혔다. 전문가들은 원전 외에도 액화천연가스(LNG) 발전소 확대를 통해 유연성 자원을 확보해야 한다고 제언하며, 정부의 화석연료 규제 완화가 필요하다고 강조했다.',1,0,0,1,0,'https://static.mk.co.kr/2026/css/images/ic_myagent_jb.png','2026-07-27 17:06:40.664409'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정부는 2040년까지 원전 4기를 추가로 건설해야 한다고 분석했다.','title: 추가원전 4기 필요 …"영광·울주 영끌하고 LNG 활용을"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1473,NULL,'국제','박지성-유승민, K-축구 혁신위 출범','2024년 6월 17일, 한국 축구의 위기 극복을 위해 ''K-축구 혁신위원회''가 출범했다. 이는 홍명보 감독과 정몽규 회장의 잇따른 사임으로 인한 축구 혁신의 필요성과 국민 신뢰 저하가 원인이다. 박지성 위원장과 유승민 공동위원장이 공동으로 이끌며, 대표팀 경쟁력, 유소년 시스템, 축구 행정 개선 등 주요 과제를 논의하고 실질적 실행 방안 마련에 나설 예정이다. 혁신위는 대한축구협회 회장 선거를 앞두고 있으며, 향후 정책 제안과 제도 개혁의 방향성에 따라 축구 행정의 구조적 변화가 예상된다.',1,1,0,0,0,'https://thumb.jtbc.co.kr/photo/r600x0/etc/2026/07/07/20260707081755407001.png','2026-07-27 17:07:03.919022'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 6월 17일, 박지성과 유승민이 공동으로 K-축구 혁신위원회를 출범시켰다.','title: 박지성-유승민 손잡았다...''위기의 한국 축구'' 혁신위 출범
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1474,NULL,'경제','테슬라, 기가프레스로 무인 공장 확대','테슬라가 차체를 일체형으로 주조하는 ''기가 프레스'' 기술을 도입하며 생산 공정을 단순화하고, AI와 로봇을 활용한 무인 공장인 ''다크팩토리''를 확대하고 있다. 기존 수십 개의 부품을 용접해 조립하던 방식을 하나의 대형 알루미늄 부품으로 대체함으로써 생산 시간과 원가를 절감하는 것이 핵심 전략이다. 글로벌 스마트팩토리 시장은 2024년 1700억달러에서 2034년 4700억달러로 성장할 전망이며, 중국 전기차 업체들은 5G와 AI 기반의 다크팩토리를 통해 다품종 생산에 대응하고 있다. 현재는 기업별로 다양한 제조 전략이 경쟁 중이며, AI, 로봇, 제조 공법의 결합 방식이 차세대 제조 패권을 좌우할 것으로 보인다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01110114000003_L00.jpg','2026-07-27 17:07:10.488223'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'테슬라가 차체를 일체형으로 주조하는 ''기가 프레스'' 기술을 도입하여 생산 공정을 단순화하고 있다.','title: 불꺼져도 돌아가는 무인 ''다크팩토리'' … 조립대신 차체 찍어내는 ''기가프레스''
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1475,NULL,'경제','현대차그룹은 싱가포르 글로벌 혁신센터(HMGICS)에서 컨베이어벨트를 폐기하고 AI와 자율주행 로봇, 디지털 트윈 기반의 셀 생산 시스템을 도입했다.','현대차그룹은 싱가포르 글로벌 혁신센터(HMGICS)에서 컨베이어벨트를 폐기하고 AI와 자율주행 로봇, 디지털 트윈 기반의 셀 생산 시스템을 도입해 자동차 생산 방식을 100년 만에 대전환하고 있다. 기존의 대량 생산 중심 방식에서 벗어나 전기차와 소프트웨어중심차량(SDV) 등 맞춤형 수요에 유연하게 대응하기 위해 AI가 생산 계획을 실시간으로 수립하고, 로봇이 부품을 운반하며 공정을 조정하는 자율 제조 시스템을 구현했다. HMGICS는 연간 3만대 규모지만, 디지털 트윈 기반의 메타 팩토리로 가상에서 생산 시나리오를 검증하고, 품질 관리도 실시간 비전 시스템과 센서를 통해 공정 중에 수행한다. 이 기술은 미국 조지아주 메타플랜트 아메리카 등 글로벌 공장으로 확대될 예정이며, 보스턴다이내믹스의 휴머노이드 로봇 아틀라스도 조립 및 품질 관리에 활용될 전망이다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01160114000001_L00.jpg','2026-07-27 17:07:19.220330'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'현대차그룹은 싱가포르 글로벌 혁신센터(HMGICS)에서 컨베이어벨트를 폐기하고 AI와 자율주행 로봇, 디지털 트윈 기반의 셀 생산 시스템을 도입했다.','title: AI·로봇이 바꾼 완성車 생산… 컨베이어 없애고 셀 오가며 작업
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1476,NULL,'경제','마이크론, 주요 수요국에 반도체 공장 확대','마이크론은 미국, 싱가포르, 대만, 일본, 인도 등 주요 수요국에 반도체 공장을 확대하며 글로벌 생산거점 다변화 전략을 추진하고 있다. 이는 AI 데이터센터 수요 증가와 지정학적 리스크로 인해 고객사와 가까운 지역에서의 안정적 공급이 새로운 경쟁력으로 부상한 데 따른 것이다. 마이크론은 미국에 2000억달러를 투자해 D램 및 HBM 생산시설을 건설하고, 싱가포르에 240억달러를 투입해 3D 낸드 생산능력을 확대하며, 대만·일본·인도 등에서도 첨단 메모리 생산을 확대하고 있다. 삼성전자와 SK하이닉스도 해외 공장 증설을 진행하고 있으나, 마이크론의 현지 생산·현지 공급 전략에 따라 국내 기업들도 주요 시장별 공급망 다변화를 더욱 적극적으로 고려해야 한다는 지적이 제기되고 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01110104000003_S00.jpg','2026-07-27 17:07:29.356545'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'마이크론, 미국, 싱가포르, 대만, 일본, 인도 등 주요 수요국에 반도체 공장을 확대하고 있다.','title: 마이크론, 대만·印·싱가포르에도 공장 … 삼성·SK, 공급망 다변화 과제
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1477,NULL,'경제','30대 가계대출 평균 1억원 돌파','2013년부터 2025년까지 30대 가계대출 평균액이 5374만원에서 1억218만원으로 90.1% 증가하며 사상 처음으로 1억원을 돌파했다. 이는 20대도 1611만원에서 3047만원으로 89.1% 증가한 것으로, 20·30대 평균 대출 증가율은 89.9%에 달해 12년 만에 두 배로 늘어난 상황이다. 반면 40대는 68%, 50대는 30.8%, 60대는 16.3% 증가에 그쳐 연령대별 대출 증가 폭이 30대에서 가장 높았다. 이에 따라 청년층의 결혼, 취업, 주거 안정 등 삶의 기반이 위협받고 있으며, 정부와 금융당국의 대책 마련이 시급한 상황이다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/20260707_01160110000002_M00.jpg','2026-07-27 17:08:38.689331'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2013년부터 2025년까지 30대 가계대출 평균액이 5374만원에서 1억218만원으로 증가하며 사상 처음으로 1억원을 돌파했다.','title: [단독] 30대 가계빚, 12년만에 2배로 … 사상 첫 ''평균 대출 1억'' 돌파
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1478,NULL,'경제','일본, 폐에어컨에서 희토류 재활용 시범 사업 추진','일본 미쓰비시전기가 폐에어컨 실외기에서 희토류를 재활용하는 시범 사업을 추진하고 있으며, 에어컨 한 대당 약 10.5g의 희토류를 추출해 약 35%의 제조 원료를 대체할 수 있도록 체계를 구축했다. 중국은 이 사업을 ''실행 불가능''하고 ''홍보용''으로 평가하며, 재활용된 희토류 대부분이 경희토류에 그쳐 전기차 및 군사장비에 필수적인 중희토류는 거의 포함되지 않아 전략적 가치가 제한적이라고 지적했다. 또한 수집 및 정제 비용이 원광석 구매보다 높아 경제성 부족을 문제로 제기했으며, 일본의 자원 안보 대비 차원의 도시광산 전략임을 강조했다. 중국은 지난해 10월 이후 일본의 방위비 증액과 살상무기 수출 허용 등 군사적 움직임에 대응해 일본 기업 60곳을 수출통제 명단에 올리는 조치를 취했다.',2,0,1,1,0,'https://static.mk.co.kr/2026/css/images/ic_myagent_jb.png','2026-07-27 17:09:03.878401'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'일본의 미쓰비시전기가 폐에어컨 실외기에서 희토류를 추출해 군사용 자원으로 활용하려는 시범 사업을 추진한다.','title: 희토류 재활용 나선 日에 … 中 "군사화 야심" 비난
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1479,NULL,'경제','삼성전자가 2024년 2분기 잠정 매출 171조 원, 영업이익 89.4조 원을 기록하며 역대 최대 실적을 달성했다.','삼성전자는 2024년 2분기 연결 기준 매출 171조 원, 영업이익 89조4000억 원을 기록하며 분기 기준 역대 최대 실적을 달성했다. 이는 전년 동기 대비 영업이익 1810.3% 증가한 것으로, 인공지능(AI) 인프라 확대에 따른 메모리 반도체 수요 증가와 고대역폭메모리(HBM) 납품 확대, 특히 엔비디아향 HBM4 첫 납품으로 인한 반도체 부문의 강세가 주요 원인이다. 영업이익에는 약 15조~20조 원 규모의 성과급 충당금이 포함되어 있으며, 이를 제외하면 실제 영업이익은 약 100조 원 이상으로 추정된다. 삼성전자는 이 실적을 바탕으로 하반기에도 공급 부족 지속과 시장 점유율 확대 전망 속에서 반도체 투자 확대 및 AI 기반 신제품 개발을 계획하고 있으며, 글로벌 기업 중 영업이익 1위로 올라섰다.',18,4,5,9,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002179473_web.jpg?rnd=20260707071112','2026-07-27 17:09:31.209451'::timestamp,'2026-07-27 19:04:33.868950'::timestamp,NULL,NULL,'삼성전자의 반도체 실적 증가가 코스피 급락의 원인 중 하나로 작용했으며, 이는 후속 사건의 직접적인 전개 흐름에 해당한다.','삼성전자가 2024년 2분기 잠정 매출 171조 원, 영업이익 89.4조 원을 기록하며 역대 최대 실적을 달성했다.','title: [인사]기획예산처
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1480,NULL,'국제','이재명 대통령, 탈모 치료제 급여화 정책 연기','2026년 상반기, 이재명 대통령 지시로 청년층 대상 탈모 치료제 건강보험 급여화 정책이 추진되었으나, 청년 세대의 상대적 박탈감과 건강보험 재정의 중노년 중심 편중, 의료화 논란 등으로 비판 여론이 확산되며 정부는 정책 추진을 무기한 연기하고 국민토론회를 전격 취소했다. 이는 고령화에 따른 재정 압박과 약물의 저가 처방 및 전립선비대증 치료 경유 등 우회적 접근이 이미 정착되어 있어 공식 급여화가 실질적 변화를 가져오지 않을 가능성도 제기된 데서 비롯되었다. 논의는 생존과 삶의 질의 경계, 자원 희소성 속에서의 우선순위 문제로 확대되었으며, 중증질환자와 소수자들의 목소리가 배제되는 구조적 문제와 보편적 건강보장 원리의 재고가 필요하다는 점이 후속 쟁점으로 부각되었다. 2025년 기준 102조 4000억 원에 달하는 건강보험 재원의 효율적 배분이 시급하며, 중증질환 및 아동 치료에 우선순위를 두고 양입제출 방식의 전환과 기금화가 제안되었다.',2,2,0,0,0,'https://www.pressian.com/_resources/10/2026/07/06/2026070608560969427_l.jpg','2026-07-27 17:10:41.302161'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 상반기, 정부는 탈모 치료제의 건강보험 급여화 정책 추진을 무기한 연기하고 국민토론회를 전격 취소했다.','title: 탈모 급여화 논쟁, ''게으른 비판''을 넘어야 한다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1481,NULL,'경제','SK하이닉스 나스닥 상장 추진','SK하이닉스는 2024년 6월 6일(현지시간) 나스닥에 미국주식예탁증서(ADR)로 상장하며, 총 280억달러 규모의 기업공개(IPO)를 진행한다. 발행주식의 약 2.5%에 해당하는 1779만 주를 신주로 공모해 약 43조1400억원을 조달하며, 조달 자금은 용인 반도체 클러스터와 청주 패키징 공장, EUV 장비 구매 등 국내 생산설비 확대에 사용된다. 미국 헤지펀드 시추에이셔널 어웨어니스, 영국 베일리 기포드, 미국 코튜 등 3개 기관이 공모 물량의 약 25%에 해당하는 최대 70억달러를 인수할 의향을 밝혔으며, 나스닥 100 지수 편입 가능성과 ETF 수요 기대가 기업가치 재평가를 유도할 전망이다. 다만 메모리 반도체 시장의 사이클 변동성, 공급 과잉 우려, 규제 리스크, 국내 주가와 ADR 간 가격 괴리 등이 후속 쟁점으로 남아 있다.',9,1,5,3,0,'https://img1.newsis.com/2025/10/29/NISI20251029_0021034888_web.jpg?rnd=20251029134215','2026-07-27 17:12:52.081065'::timestamp,'2026-07-27 19:05:27.075412'::timestamp,NULL,NULL,'SK하이닉스의 나스닥 상장 추진은 코스피 급락과 환율 고착화 토픽에서 반도체지수 급락 여파와 직접 연결된 후속 전개로, 주체와 쟁점, 전개 흐름이 일치함','SK하이닉스는 2026년 7월 10일경 나스닥에 상장한다.','title: SK하이닉스의 나스닥 상장, 외국기업 최대의 최초 주식매각
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1482,NULL,'정치','국민의힘 최고위원들이 정보통신망법 개정안 시행 하루 전에 검은 마스크를 착용하고 ''입틀막법''이라며 반발했다.','2026년 7월 7일 정보통신망법 개정안이 시행을 앞두고 여야 간 격렬한 논쟁이 벌어졌다. 국민의힘은 법을 ''입틀막법''이라며 조선시대 연산군의 신언패를 비유하며 헌법소원심판 청구와 전면 재개정안 발의를 당론으로 추진했고, 검은 마스크 착용으로 표현의 자유 침해를 항의했다. 반면 민주당은 허위정보와 혐오 표현을 방지하기 위한 방어벽으로서 법의 필요성을 강조하며, 유럽연합의 유사 사례를 들어 정당성을 제시했다. 법 시행 이후 관련 신고는 12건에 그쳤으나, 이재명 대통령에 대한 탄핵 청원이 47만 명을 넘는 등 정치적 반발이 확산되고 있으며, 향후 법의 시행 효과와 위헌 여부에 대한 법원 판단이 주요 쟁점이 될 전망이다.',7,1,2,4,0,'https://www.mbn.co.kr/player/videojs/png/ic_caution.png','2026-07-27 17:14:13.746231'::timestamp,'2026-07-27 19:04:56.221789'::timestamp,NULL,NULL,'정보통신망법 개정안 시행과 국민의힘의 검은 마스크 반발이 후보 토픽의 ''허위정보 규제 논의''와 직접적인 사건 흐름으로 연결됨','국민의힘 최고위원들이 정보통신망법 개정안 시행 하루 전에 검은 마스크를 착용하고 ''입틀막법''이라며 반발했다.','title: 국힘, 검은 마스크 쓰고 "입틀막법" 비난 vs 민주당 "가짜뉴스 방지"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1483,NULL,'정치','대구 북구의회는 6일 제302회 임시회에서 김상혁 의원을 의장, 채장식 의원을 부의장으로 단독 선출했다.','2026년 7월 6일 대구 북구의회는 제302회 임시회에서 국민의힘 김상혁 의원을 의장, 더불어민주당 채장식 의원을 부의장으로 단독 선출하며 제10대 전반기 원구성을 완료했다. 여야는 사전 협의를 통해 의장은 국민의힘, 부의장은 더불어민주당이 맡기로 합의해 원구성에 진통 없이 마무리했으며, 상임위원장도 모두 단독 입후보로 선출됐다. 북구의회는 7일 개원식을 열고 제10대 의회 출범을 공식 선언하며 본격적인 의정활동에 들어갈 예정이다. 김상혁 의장은 구민 삶을 최우선으로 하는 의정활동을 약속했다.',3,0,3,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0002179394_web.jpg?rnd=20260706191622','2026-07-27 17:15:41.129527'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'대구 북구의회는 6일 제302회 임시회에서 김상혁 의원을 의장, 채장식 의원을 부의장으로 단독 선출했다.','title: 대구 북구의회, 김상혁 의장·채장식 부의장 선출…원구성 마무리
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1484,NULL,'정치','정청래 전 더불어민주당 대표가 6일 경기 수원시 경기도의회 의원총회에 참석하고 추미애 경기도지사와 회동했다.','정청래 전 더불어민주당 대표가 6일 경기 수원시 경기도의회 의원총회에 참석하며 추미애 경기도지사와 회동했다. 이날 정 전 대표는 추 지사가 여성 최초의 광역단체장으로 경기도지사로서 업무를 수행하는 모습에 대해 뿌듯함을 표하며, 유능한 도지사로 성장하길 기원했다. 민주당은 6·3 지방선거에서 경기도의회 의원 167명 중 144명(86%)이 당선되며 전국에서 가장 높은 당선률을 기록했으며, 추미애 지사의 리더십이 성과에 기여했다고 평가했다. 정 전 대표는 이후 세월호 참사 희생자 박성호 군의 이름을 딴 임마누엘 성호 성당을 방문해 진상규명 미흡에 대한 미안함을 표하며, 참사의 아픔을 잊지 않겠다고 밝혔다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0021352228_web.jpg?rnd=20260706154242','2026-07-27 17:16:40.222553'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정청래 전 더불어민주당 대표가 6일 경기 수원시 경기도의회 의원총회에 참석하고 추미애 경기도지사와 회동했다.','title: 추미애 만난 정청래 "유능한 도지사로 우뚝 서길 기원"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1485,NULL,'정치','노재헌 주중국대사, 2026년 7월 11일 북·중 우호조약 체결 65주년을 계기로 양측 고위급 교류 동향을 주시한다고 밝힘','2026년 7월 11일을 기점으로 북·중 우호협력상호원조조약 체결 65주년이 되며, 양국 고위급 교류 동향이 주목되고 있다. 이 조약은 일방이 전쟁에 휘말릴 경우 상대방이 군사 원조를 제공하는 자동개입 조항을 포함하고 있으며, 특히 5년 단위의 정주년으로 사회주의 국가들이 중요하게 여기는 해이다. 노재헌 주중국대사는 북·중 관계가 한반도 평화와 안정에 기여할 수 있기를 기대하며, 중국이 한반도 문제에 건설적 역할을 하기를 바란다고 밝혔다. 한편 중국은 2026년 1월부터 시행된 민족단결진보촉진법으로 인해 외국인 방문객이 언어·문화 활동에서 주의가 필요하다고 당부하며, 이 법의 범위가 모호해 자의적 집행 가능성이 있다는 우려도 제기되고 있다.',1,0,1,0,0,'https://img1.newsis.com/2025/11/03/NISI20251103_0001982945_web.jpg?rnd=20251103173141','2026-07-27 17:17:53.243535'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'노재헌 주중국대사, 2026년 7월 11일 북·중 우호조약 체결 65주년을 계기로 양측 고위급 교류 동향을 주시한다고 밝힘','title: 주중대사 "북·중 우호조약 65주년 고위급 교류 주시"(종합)
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1486,NULL,'정치','김민석 전 국무총리는 7일 친청계 의원들의 ''계엄 해제 표결 불참'' 의혹에 대해 ''대장동 때를 보는 듯하다''며 허위사실 유포에 책임을 지라고 반박했다.','2024년 12월 3일 비상계엄 사태 당시 김민석 전 국무총리가 국회 계엄 해제 표결에 불참한 점을 두고 친청계 이성윤 최고위원이 ''감기약 성분''을 문제 삼으며 의혹을 제기하자, 김 전 총리는 이 발언을 ''대장동 때를 보는 듯하다''며 허위사실 유포로 반박했다. 그는 표결 당시 국회에 있었으며 직후 본회의장에 착석했다고 해명하며, 이성윤 의원의 발언이 명예훼손에 해당할 수 있다고 지적했고, 사법정의 바로세우기 시민행동은 이 의원을 정통망법상 허위사실적시 명예훼손 혐의로 서울경찰청에 고발했다. 이는 2026년 7월 전당대회를 앞두고 친청계와 친명계 간 진영 대립이 심화되며, 당내 갈등이 정치적 공방으로 확대된 상황이다. 김 전 총리는 당 대표 출마를 앞두고 5·18 정신 헌법 수록과 선관위 개혁을 투포인트 개헌안으로 제시하며 내부 혁신과 가짜뉴스 정리 필요성을 강조했다.',11,2,2,7,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GZRWMYTEGAZDKZTBGUZTONRTG4.jpg','2026-07-27 17:27:15.962590'::timestamp,'2026-07-27 19:04:56.221789'::timestamp,NULL,NULL,'허위사실 유포 논란과 정보통신망법 개정 논의가 같은 사안의 연속적 전개로, 허위정보 규제와 명예훼손 문제에서 일관된 쟁점 흐름을 보임','김민석 전 국무총리는 7일 친청계 의원들의 ''계엄 해제 표결 불참'' 의혹에 대해 ''대장동 때를 보는 듯하다''며 허위사실 유포에 책임을 지라고 반박했다.','title: 김민석, 친청계 ‘감기약 발언’에 “대장동 보는 듯...허위사실 유포 책임져야”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1487,NULL,'경제','금융위원회가 7일 서울 중구 은행회관에서 ''포용금융 전략 추진단'' 금융산업분과 킥오프 회의를 열고, 금융회사의 포용금융 실적 평가에 금리 인하 효과, 금융 접근성 개선, 지배구조 반영 등을 종합적으로 반영하기로 결정했다.','금융위원회는 7일 서울 중구 은행회관에서 ''포용금융 전략 추진단'' 금융산업분과 킥오프 회의를 개최하고, 금융회사의 포용금융 실적 평가에 금리 인하 효과, 금융 접근성 개선, 지배구조 반영 등을 종합적으로 반영하기로 결정했다. 중저신용자 대출 시장의 금리 절벽 문제 해결을 위해 은행과 제2금융권의 협업 모델, 신용평가 인프라 확충, 비용 구조 개선 방안을 검토하며, 올해 3월 기준 중신용자 평균 금리는 연 7.9%, 하위 20% 차주는 연 13.4%에 달했다. 건전성 규제의 합리화도 추진되며, 중저신용자 대출에 대한 위험가중치, 채무조정 자산 분류 기준, 대손충당금 적립 기준 등이 폭넓게 검토된다. 상호금융 제도 개선과 평가체계 개편을 병행해 포용금융 실적을 경영평가에 반영하고, 우수 기관에 인센티브를 부여하는 제도 개선 방안을 마련할 예정이다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/CRUPK5HZUVWBUGGGUAP6F253VU.jpg','2026-07-27 17:29:02.410367'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'금융위원회가 7일 서울 중구 은행회관에서 ''포용금융 전략 추진단'' 금융산업분과 킥오프 회의를 열고, 금융회사의 포용금융 실적 평가에 금리 인하 효과, 금융 접근성 개선, 지배구조 반영 등을 종합적으로 반영하기로 결정했다.','title: 금융위, 금융사 포용금융 실적 평가 때 지배구조 반영 여부까지 본다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1488,NULL,'사회','50대, 후진 차량 고의 충돌로 보험금 사기','2024년 4월 26일 경기 구리시와 서울 강남구에서 50대 남성이 후진 중인 차량을 고의로 충돌한 뒤, 사고 후 10분에서 11분간 누워있는 방식으로 보험금을 사기로 청구한 사건이 발생했다. CCTV 영상 분석 결과, 남성은 사고 10분 전부터 사고를 유도할 목적으로 횡단보도 주변을 돌아다니며 접근 행동을 취한 것으로 확인됐으며, 처음에는 술에 취해 기억이 없다고 주장했으나 영상 확인 후 혐의를 인정했다. 경찰은 보험사기방지 특별법 위반 혐의로 남성을 불구속 송치했으며, 현재 검찰 수사가 진행 중이다. 이 사건을 계기로 보험사기 방지 대책과 사고 조작에 대한 법적 처벌 강화, 관련 법 개정안의 국회 제출이 예상된다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/FPF7OCPWNFHOLHLET5S3Z7DNEY.jpg','2026-07-27 17:29:26.168329'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 4월 26일 오전 11시쯤 경기 구리시의 한 도로에서 A씨(50대)가 후진 중인 모닝 차량을 고의로 부딪혀 보험금을 타내려 한 사건이 발생했다.','title: 후진 차량에 접근해 ‘쾅’…보험금 노린 50대 송치
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1489,NULL,'경제','NHN, AI 기반 보안 서비스 데모 공개','2024년 2월 2일, NHN은 판교 사옥에서 기술 공유 행사 ''에이전틱 데이''를 개최하며 AI 도입 사례를 공유했다. 양철웅 NHN CTO는 AI 시대의 다음 과제로 데이터 안전 연결과 보안 강화를 강조하며, 개발 단계부터 보안성을 고려한 AI 활용을 추진하겠다고 밝혔다. 이 행사에서 NHN클라우드는 AI 기반 보안 취약점 점검 서비스의 데모 버전을 최초 공개했으며, 이 서비스는 AI 토큰을 최소한으로 사용해 효율성을 극대화했고, NHN클라우드에서 시범 적용 후 전 그룹사로 확대될 예정이다. 또한 NHN은 전 임직원 대상으로 앤트로픽의 AI 모델 클로드를 제공하며 내부 AI 전환(AX)을 확대하고 있으며, 기획자 등 비개발 직군도 자연어 입력을 통해 데이터 분석을 빠르게 수행할 수 있도록 지원하고 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HEZDOYZQGI3TGOJSMI4DSN3FGI.jpg','2026-07-27 17:30:49.491090'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 2월 2일, NHN은 판교 사옥에서 기술 공유 행사 ''에이전틱 데이''를 개최했다.','title: 양철웅 NHN CTO “AI 시대 다음 과제는 안전한 데이터 연결과 보안”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1490,NULL,'경제','LG전자 2분기 영업이익 1조원 돌파','LG전자는 2024년 2분기 연결 기준 매출 23조8297억원, 영업이익 1조5788억원을 기록하며 두 분기 연속 영업이익 1조원을 돌파했다. 전년 동기 대비 영업이익은 146.9% 증가하며 시장 전망치를 약 47% 상회하는 어닝 서프라이즈를 기록했다. 성장 원인으로는 프리미엄 가전·TV 판매 확대, 웹OS 및 구독 서비스 성장, 미국 관세 환급 일회성 수익, 원가경쟁력 개선 및 전사 비상경영 체제의 효과가 꼽혔다. 향후 AI 데이터센터 냉각 솔루션 분야 투자 확대와 AI 기반 제품 확대, 글로벌 시장 진출 전략을 통해 성장세를 지속할 계획이다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GVSTKNRSMZSDGNZYMY2DGZJUGM.jpg','2026-07-27 17:31:12.967081'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'LG전자가 2024년 7일 올해 2분기 연결 기준 매출 23조8297억원, 영업이익 1조5788억원의 잠정실적을 발표했다.','title: LG전자 ‘어닝 서프라이즈’… 2분기 연속 영업익 1조원 돌파
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1491,NULL,'경제','남해군 갯장어 샤부샤부 특별 공동구매','경남 남해군 미조항에서 조업한 자연산 갯장어를 활용한 샤부샤부용 특별 공동구매 행사가 진행되며, 기존 인당 10만원 수준이던 제품을 한 접시 2만원대에 제공한다. 갯장어는 6월부터 9월까지 남해안에서만 얻을 수 있는 여름 보양식으로, 단백질과 불포화지방산, 콜라겐 등이 풍부해 혈관 건강과 기력 회복에 도움을 준다. 이번 공동구매는 400g 중량의 정교하게 손질된 갯장어와 전용 육수를 진공 포장 후 스티로폼 박스에 얼음을 넣어 냉장 배송하며, 수령 후 최대 1일간 냉장 보관 가능하다. 이후 냉동 보관 시 식감 손실이 발생할 수 있어 가급적 빠른 조리가 권장되며, 조리법은 끓는 육수에 갯장어를 살짝 익히는 간단한 방식이다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/3XVKYFLZZ5GO6CLIDVLDBOBFUM.jpg','2026-07-27 17:32:04.061167'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'남해군 미조항에서 조업한 자연산 갯장어를 활용한 샤부샤부용 특별 공동구매 행사가 진행되며, 한 접시를 2만원대에 제공한다.','title: 비싸서 못 먹던 갯장어 샤부샤부, 한 접시 2만원대 특별 공동구매
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1492,NULL,'경제','암웨이, 2024년 하반기 한국 시장에 독점 균주 2종을 적용한 프로바이오틱스 신제품 ''뉴트리라이트''를 출시한다.','암웨이는 2024년 하반기 한국 시장에 독점 균주 2종을 적용한 프로바이오틱스 신제품 ''뉴트리라이트''를 출시한다. 이 균주는 한국인의 식습관과 생활환경을 반영한 대규모 데이터 기반으로, 장내 미생물 다양성 저하 및 뷰티르산 생성 촉진에 기여하는 것으로 확인됐으며, 위장관 모델과 인간 오가노이드를 활용한 연구 플랫폼을 통해 실제 장 환경에서의 기능을 검증했다. 국내 프로바이오틱스 시장 규모는 2023년 약 7200억원으로, 전체 건강기능식품 시장에서 홍삼에 이어 2위를 차지했으며, 암웨이는 11만 건 이상의 장내 마이크로바이옴 데이터베이스를 기반으로 3428개 균주 라이브러리에서 스크리닝해 독점 라이선스를 확보했다. 암웨이는 건강수명 연장에 기여하는 전 생애주기 솔루션 개발을 지속할 예정이며, 이는 장 건강이 전신 건강에 미치는 영향이 커진 사회적 트렌드와 관련이 있다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GQ3GKZJXMRRTGNRRMYZDCM3GMY.jpg','2026-07-27 17:32:05.852757'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'암웨이, 2024년 하반기 한국 시장에 독점 균주 2종을 적용한 프로바이오틱스 신제품 ''뉴트리라이트''를 출시한다.','title: 암웨이, 독점 균주 2종 담은 프로바이오틱스 하반기 출시
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1493,NULL,'사회','경찰, 정이한 구속영장 청구','정이한 전 개혁신당 부산시장 후보는 2024년 4월 27일 부산 금정구 구서나들목에서 선거 유세 중 차량에서 던진 음료에 맞아 뇌진탕 진단을 받았다고 주장했으나, 경찰은 그와 음료를 던진 A씨(전 헬스 트레이너)가 사전에 통화한 정황과 친분 관계를 근거로 자작극 의혹을 수사했다. 경찰은 위계에 의한 공무집행방해 및 공직선거법 위반 혐의로 정 전 후보와 A씨에 대해 구속영장을 청구했으며, 검찰은 6월 3일 부산지법에 이를 신청했다. 구속 전 피의자 심문은 6월 8일 오후 2시 부산지법에서 진행되며, 증거인멸 및 도주 우려를 이유로 구속을 요청했다. 현재 정 전 후보는 6·3 지방선거에서 2만7,418표(득표율 1.56%)를 얻어 3위에 머물렀으며, 부친 소유 기업의 선거운동 동원 및 여론조사기관의 공정성 문제 등 추가 수사가 병행 중이다.',10,2,3,5,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MY2TGZJYGA3DIYJXMJRDQOJTGA.jpg','2026-07-27 17:33:14.249143'::timestamp,'2026-07-27 19:05:05.766014'::timestamp,NULL,NULL,'정이한 전 후보의 음료 피습 사건과 증거인멸, 공무집행방해 혐의는 광주경찰서 수사팀장 사건과 유사한 공무집행 방해 및 증거인멸 쟁점과 전개 흐름이 일치함','경찰이 6월 1일 정이한 전 부산시장 후보에 대해 음료 컵 피습 자작극 의혹과 관련해 위계에 의한 공무집행방해 및 공직선거법 위반 혐의로 구속영장을 신청했다.','title: 경찰, ‘피습 자작극 의혹’ 정이한 구속영장 청구
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1494,NULL,'경제','이재명 정부, 부동산 세제 개편 방향 발표','이재명 정부는 2026년 7월 말 부동산 세제 개편안을 발표할 예정이며, 보유세 인상과 다주택자 거래세 완화를 통해 실거주자 중심의 주택시장을 확립하는 것을 목표로 한다. 공정시장가액비율 조정과 비거주 장기보유특별공제 축소 등 구체적 방안을 검토 중이며, 국민 의견 수렴 절차를 거쳐 최종 방침을 결정할 계획이다. 세제 개편은 9월 정기국회 전에 관련 법안으로 제출되며, 반도체 호황으로 예상되는 초과세수(약 600조원)는 미래대응기금에 투입되어 혁신 산업과 청년 지원에 사용된다. 또한 지방 근로자에 대한 소득세 감면 및 자녀 교육비 지원 등 지역 균형발전을 위한 세제 혜택도 함께 검토 중이다.',5,1,3,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAYGMYJQMM3TGNRTGIYDIMTFHE.jpg','2026-07-27 17:33:39.091366'::timestamp,'2026-07-27 19:05:37.863750'::timestamp,NULL,NULL,'이재명 정부의 부동산 세제 개편안과 반도체 세수를 활용한 미래대응기금 신설은 동일한 정책 목표와 재원 배분 흐름을 공유하며, 반도체 호황으로 인한 초과세수의 사용 방향이 명확히 연결됨.','이재명 정부는 내년도 세제 개편안에서 부동산 보유세를 인상하고 다주택자에 대한 거래세를 낮추는 방향으로 조정할 예정이다.','title: "보유세는 올리고 거래세는 낮추나"…이달 말 부동산 세제 개편 발표
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1495,NULL,'경제','제당사 전분당 가격 담합 과징금 부과','공정거래위원회는 대상, 사조CPK, 삼양사, CJ제일제당 등 4개사가 2018년 5월부터 2025년 10월까지 전분당 가격을 담합한 혐의로 총 7476억원의 과징금을 부과했다. 이는 공정위 역사상 최대 규모로, 전분 시장 점유율 95.7%, 전분당 시장 점유율 86.4%를 차지하며 13차례에 걸쳐 가격 인상·인하 시기와 폭을 합의한 것으로 확인됐다. 담합으로 인해 전분당 평균 가격이 1kg당 559원에서 최대 971원으로 73% 인상되었으며, 관련 매출액은 6조525억원으로 추정된다. 또한 입찰담합 및 부산물 가격 담합 혐의에 대해 별도 심의를 진행 중이며, 입찰담합 관련 매출액 9400억원, 부산물 담합 1조5500억원에 대해 최대 4980억원의 과징금 부과 가능성이 제기되고 있다.',11,1,8,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MZRGGNBVMYZWGYJZGJRGGZJQMU.jpg','2026-07-27 17:34:58.115132'::timestamp,'2026-07-27 19:05:27.075412'::timestamp,NULL,NULL,'전분당 가격 담합과 코스피 급락은 모두 공정거래 위반과 시장 불안을 유발한 경제적 사건으로, 담합으로 인한 가격 인상과 시장의 반응이라는 직접적인 경제적 흐름이 연결됨','공정거래위원회가 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 제당사에 2018년 5월부터 2025년 10월까지 전분당 가격 담합 혐의로 과징금 7476억원을 부과했다.','title: 공정위, 물엿·포도당 등 전분당 가격 담합한 제당사 4곳에 과징금 7476억원 부과...담합 과징금 역대 최대 규모
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1496,NULL,'경제','국가데이터처, 소비자물가지수 조사 방식 개편','국가데이터처는 2025년 12월부터 소비자물가지수 조사 방식을 개편해 고사리, 땅콩, 유치원납입금 등 13개 품목을 제외하고, 소프트웨어 구독료, 스마트워치, 전기차충전료 등 10개 디지털 소비 항목을 신규 포함한다. 이는 2025년 가계동향조사 결과를 기초로 한 5년 주기 개편으로, 대표품목은 기존 468개에서 455개로 조정되며, 2025년 기준 지수는 12월 18일 공표된다. 또한 2025년 1월부터 외식물가지수에 클라우드 서비스와 마라탕 등 신규 품목이 반영되며, 2026년 12월까지 총 10개 추가 품목이 포함될 예정이다. 개편은 12월 7일부터 17일까지 국민 의견 수렴을 거쳐 국가통계위원회 심의를 거쳐 최종 확정된다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HEYGMZRTMFSTSZJUGEYGINJXHE.jpg','2026-07-27 17:35:08.300534'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'국가데이터처가 2025년 12월부터 소비자물가지수 조사 방식을 개편해 고사리, 땅콩, 유치원납입금 등 13개 품목을 제외하고 소프트웨어 구독료, 스마트워치, 전기차충전료 등 10개 디지털 소비 항목을 신규 포함한다.','title: 12월부터 소비자물가 항목에 고사리 빠지고 소프트웨어 구독료, 스마트워치 들어간다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1497,NULL,'경제','다주택자 명의 이전으로 양도세 회피 혐의','국세청은 2023년 10월부터 서울 ''한강 벨트'' 지역의 30억 원 이상 고가 아파트 거래를 대상으로 한 세무조사를 통해 104명의 부동산 탈세 혐의를 적발했다. 주요 수법은 다주택자가 친척이나 지인에게 저가주택을 허위 이전해 1세대 1주택 비과세 혜택을 부당하게 적용하거나, 부모로부터 증여받은 자금을 은폐하고 법인자금을 유출하는 방식이었다. 이 과정에서 총 731억 원의 세금 누락이 확인되었으며, 318억 원을 추징하고, 6명은 조세포탈 혐의로 검찰 고발, 4명은 통고처분을 받았다. 국세청은 향후 다주택자 증여거래, 가족 간 저가 양도, 매매 위장 거래 등을 집중 점검하고, 부동산 탈세 신고센터를 통해 제보를 검증해 제보자에 대한 포상금을 신속 지급할 계획이다.',8,1,4,3,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GQZDANZRMUZWGMRYGVQTONTDGM.jpg','2026-07-27 17:35:15.576928'::timestamp,'2026-07-27 19:05:37.863750'::timestamp,NULL,NULL,'부동산 탈세와 세금 회피 방식이 동일하며, 국세청의 조사와 추징, 고발 결과가 후속 전개로 이어짐','A씨가 아파트를 지인에게 명의만 이전해 1주택자로 신고하고 20억원 매도 수익에 대해 양도세 10억원을 회피했다.','title: 아파트 20억에 팔고 양도세 0원...다른 집 지인에 넘긴 척 세금 탈루
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1498,NULL,'사회','친모, 딸 영양결핍 사망 혐의로 검찰 구형','인천지법 형사14부는 생후 19개월 된 딸을 67시간 동안 음식을 주지 않고 방치해 영양결핍과 탈수로 사망하게 한 친모 A(29)씨에게 징역 30년과 출소 후 5년간 보호관찰을 구형했다. A씨는 2월 28일부터 92시간 동안 딸을 혼자 방치했으며, 부검 결과 체중 4.7㎏(평균 10.4㎏)으로 영양결핍이 사망 원인으로 확인됐다. A씨는 기초생활수급자로 월 300만 원 이상의 공적 지원을 받았으나, 집안은 쓰레기와 배설물로 어지럽고, 개 사체와 담배꽁초가 방치되는 등 양육 소홀이 심각했다. 재판부는 반성 여부, 재범 가능성, 지원 시스템의 한계 등을 고려해 판결을 예정하고 있으며, A씨는 항소할 계획이다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/FUWESJXKZJJKDGR5IORYSOJM4I.jpg','2026-07-27 17:35:56.072378'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'검찰이 19개월 된 딸을 음식을 주지 않고 방치해 숨지게 한 친모 A씨에게 징역 30년과 출소 후 5년간 보호관찰을 구형했다.','title: 19개월 딸 영양결핍으로 숨지게 한 친모… 檢, 징역 30년 구형
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1499,NULL,'국제','중국 광시 홍수 피해 대응','2026년 7월 6일 중국 광시좡족자치구 난닝시에서 집중호우로 인한 홍수로 최소 2명이 사망하고, 5만5000여명이 이재민으로 발생했다. 이는 난닝시 헝저우 지역의 류란 저수지 제방 일부 손상으로 인한 침수 피해가 주요 원인으로, SNS에서 저수지 붕괴설이 확산되며 사회적 우려가 커졌다. 당국은 저수지 붕괴가 아니며 시설 손상에 따른 긴급 대응 중이라고 밝히고, 현재까지 4만8000명이 대피했으며, 국가발전개혁위원회는 복구를 위해 1억 위안(약 225억 원)의 예산을 배정했다. 또한 국가방재감재구재위원회와 응급관리부는 텐트, 접이식 침대, 의류 등 중앙 구호물자 15만 점을 긴급 지원해 이재민의 생활 안정을 도모하고 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0021352442_web.jpg?rnd=20260707030858','2026-07-27 17:36:19.724312'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 7월 6일 중국 광시좡족자치구 난닝시에서 집중호우로 인한 홍수로 최소 2명이 사망하고 5만5000여명이 이재민으로 발생했다.','title: 中 광시 홍수로 2명 사망·5만5000명 피해
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1500,NULL,'경제','미국 증시 상반기 상승','미국 증시는 상반기 S&P500이 8%, 나스닥은 11% 상승하며 최근 5년 최고 성과를 기록했으며, 2분기에는 S&P500이 15%, 나스닥은 21% 급등해 2020년 2분기 이후 6년 만에 최고 상승률을 달성했다. 이 상승은 인공지능(AI) 투자 확대와 이란전쟁 휴전 등이 시장에 미친 영향으로, AI는 증시 변동성의 주요 요인으로 작용하고 있다. 하반기에는 미국 연방준비제도(Fed)의 금리 결정과 중간선거, 이란전쟁의 전개가 시장에 영향을 미칠 전망이며, 시장 전망은 낙관론이 우세하다. AI 관련 투자 지속 가능성과 지정학적 리스크가 하반기 투자 환경의 주요 쟁점으로 부각되고 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/06/news-p.v1.20260706.716d9553b7044878b0107126e39366d2_P1.jpg','2026-07-27 17:36:31.157179'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'미국 증시는 상반기에 S&P500이 8%, 나스닥은 11% 상승하며 최근 5년 최고 상승률을 기록했다.','title: 월가 “코스피가 미장 움직인다” … AI투자 2년은 더 간다는데
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1501,NULL,'경제','은행 예금 금리 인상','금리 상승 기조에 따라 시중은행의 12개월 만기 정기예금 최고 금리는 연 3.82%까지 올랐으며, 저축은행은 평균 3.9%로 4%대 금리를 제공하고 있다. 이는 증시 상승으로 인한 자금 유출 우려와 하반기 기준금리 인상 전망에 따라 은행들이 고객 유지를 위해 예금 금리를 인상한 결과다. 은행채 1년물(AAA) 금리는 4월 초 3.182%에서 지난달 29일 3.724%로 상승했으며, 16일 예정된 금융통화위원회에서 기준금리 인상 가능성에 따라 여·수신 금리 조정이 예상된다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MY2WKMLCGZRWGOJVGE4GKNJWMY.jpg','2026-07-27 17:36:42.889174'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'광주은행과 SC제일은행이 12개월 만기 정기예금 상품을 각각 연 3.82%, 연 3.75% 금리로 제공했다.','title: 금리 상승 기조에… 시중은행 예금 年 3%대, 저축은행은 4%대
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1502,NULL,'국제','도널드 트럼프 미국 대통령이 6일(현지시간) 백악관에서 새 연회장 건설 계획을 설명하는 자리에서 시진핑 중국 국가주석이 9월24일께 백악관을 방문할 것으로 예상한다고 밝혔다.','도널드 트럼프 미국 대통령이 6일(현지시간) 백악관에서 새 연회장 건설 계획을 설명하는 자리에서 시진핑 중국 국가주석이 9월24일께 백악관을 방문할 것으로 예상한다고 밝혔다. 이는 지난 5월 베이징 정상회담에서 트럼프 대통령이 시 주석과 부인 펑리위안 여사에게 9월24일 백악관 방문을 초청한 것의 연장선으로, 중국 외교부도 올가을 시 주석의 미국 국빈 방문 가능성을 확인한 바 있다. 다만, 구체적인 방미 일정과 회담 형식은 양국 정부가 별도로 발표하지 않아 최종 확정되지 않았으며, 9월24일은 뉴욕에서 열리는 유엔총회 제81차 고위급 회기와 겹치는 시점이다. 시 주석이 실제로 미국을 방문할 경우 유엔총회 참석과 백악관 회담을 병행할 가능성이 제기되며, 이는 그가 집권 후 유엔총회에 직접 참석한 첫 번째 사례가 될 수 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0001410861_web.jpg?rnd=20260706235839','2026-07-27 17:40:52.137052'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'도널드 트럼프 미국 대통령이 6일(현지시간) 백악관에서 새 연회장 건설 계획을 설명하는 자리에서 시진핑 중국 국가주석이 9월24일께 백악관을 방문할 것으로 예상한다고 밝혔다.','title: 트럼프 "시진핑, 9월24일께 백악관 방문 예상"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1503,NULL,'경제','정부, 지역필수의료특별회계 신설 추진','정부는 내년 1월부터 국립대병원을 중심으로 지역 주도의 필수의료 체계를 강화하기 위해 지역필수의의료특별회계를 신설한다. 특별회계는 수도권에서 멀수록 지원을 확대하고, 공공의료기관 우선 투자 및 지역 여건에 맞는 의료계획 수립을 원칙으로 하며, 2026년 3월 공포된 지역필수의료법의 하위법령은 2024년 3월 시행 예정이다. 보건복지부는 2026년 7월 7일 제3차 지역·필수·공공의료 추진전략 중앙·지방 협의체 회의를 개최해 17개 시도와 협의하며, 시도 및 권역기관의 투자 수요를 반영해 예산 편성과 사업 구체화를 진행 중이다. 이후 의견 반영을 거쳐 하위법령을 보완하고 조속히 입법예고를 진행할 계획이며, 지역완결적 의료체계 구축을 위한 정책 체계의 유기적 연계를 강화할 예정이다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/HAZDEM3FGJQWEOBZMQ4DKNDEGE.jpg','2026-07-27 17:42:21.284366'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'정부가 내년 1월부터 국립대병원을 중심으로 지역 주도의 필수의료 체계를 강화하기 위해 지역필수의료특별회계를 신설한다.','title: 국립대병원 중심 지역 필수의료 강화…내년부터 전용 예산 마련
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1504,NULL,'사회','조경식 전 KH그룹 부회장이 2023년 2월 15일 경기 용인시 아파트 지하 주차장에서 전 여자친구를 흉기로 위협하고 폭행하며 7시간 넘게 감금한 혐의로 수원지법에서 징역 4년을 선고받았다.','조경식 전 KH그룹 부회장이 2023년 2월 15일 경기 용인시 아파트 지하 주차장에서 전 여자친구를 흉기로 위협하고 폭행하며 7시간 이상 감금한 혐의로 수원지법에서 징역 4년을 선고받았다. 피해자에게 600만원을 갈취하고 13차례 스토킹한 혐의도 인정받았으며, 과거 실형 전력과 누범 중 범행으로 죄질이 심각하다는 점이 재판부 판단에 반영되었다. 이와 별개로 조씨는 2023년 5월 국회 청문회에서 ''연어 술 파티''를 주장했으나, 법무부 특별 점검 결과 해당 발언은 거짓으로 확인되었고, 당시 이미 사기죄로 수감 중이었음이 밝혀졌다. 조씨는 징역 4년 판결에 대해 항소할 예정이며, 사건은 향후 항소심에서 재판될 예정이다.',2,0,1,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/MRQWMNJYGYYWKZBZG42WENRVGY.jpg','2026-07-27 17:44:02.295160'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'조경식 전 KH그룹 부회장이 2023년 2월 15일 경기 용인시 아파트 지하 주차장에서 전 여자친구를 흉기로 위협하고 폭행하며 7시간 넘게 감금한 혐의로 수원지법에서 징역 4년을 선고받았다.','title: ‘연어 술파티’ 증언 前 KH부회장, 전 여친 흉기 위협·감금 혐의 ‘징역 4년’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1505,NULL,'경제','모건스탠리는 2024년 6월 6일 고객에게 삼성전자, SK하이닉스, 마이크론 등 메모리 반도체 관련주의 투자 비중을 축소할 것을 권고했다.','모건스탠리는 2024년 6월 6일 보고서를 통해 삼성전자, SK하이닉스, 마이크론 등 메모리 반도체 주식의 투자 비중 축소를 권고하며, 반도체 실적 모멘텀 정점과 하이퍼스케일러의 AI 투자 속도 조절로 인한 수요 약화를 지적했다. 이는 메타의 잉여 AI 컴퓨팅 용량 외부 판매 발표가 하이퍼스케일러 투자 조절 신호로 해석되며, 자금이 AI클라우드 기업으로 이동하는 순환매를 유발한 것으로 분석된다. 필라델피아반도체지수는 지난달 고점 대비 약 14% 하락했으며, 6월 한 달간 상승 후 최근 2주 사이 11% 넘게 급락했고, 외국인 투자자는 삼성전자 보유율을 2009년 이후 최저인 46.69%까지 떨어뜨리며 13거래일 연속 순매도를 이어갔다. 반면 개인 투자자들의 빚투는 확대되며 삼성전자 신용잔고는 5조5천75억원, SK하이닉스는 5조3천49억원으로 사상 최대치를 기록했으며, SK하이닉스의 미국 ADR 상장과 하반기 메모리 가격 강세 전망이 외국인 투자 회복의 변수로 작용할 전망이다.',3,0,1,2,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GU3DCZTEGEYWMNLEGI4TIMBRGQ.jpg','2026-07-27 17:44:31.813746'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'모건스탠리는 2024년 6월 6일 고객에게 삼성전자, SK하이닉스, 마이크론 등 메모리 반도체 관련주의 투자 비중을 축소할 것을 권고했다.','title: “메모리 겨울 온다”던 모건스탠리, 이번엔 “삼전닉스 팔아라”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1506,NULL,'사회','대출 브로커 허위 대출 공모 기소','2022년 4월부터 2024년 11월까지 대출 브로커 A씨는 의사와 약사 278명과 공모해 위조된 잔고증명서와 허위 의료기기 매매계약서를 제출해 신용보증기금 예비창업보증 보증서 1970억원 상당을 부정하게 발급받은 혐의로 구속 기소됐다. A씨는 페이퍼 컴퍼니를 설립해 허위 계약서를 작성하고 포토샵으로 잔고증명서를 위조하며, 예비창업보증 제도의 서류 중심 심사와 은행의 신용보증기금 신뢰 구조를 악용한 것으로 조사됐다. 전체 1970억원 중 약 1796억원이 변제되었으며, 피해를 입은 의료인 80명 중 273명은 기소유예, 3명은 혐의없음 처분을 받았으나, 대출금을 개원 외 목적으로 사용하고 폐업한 의사 2명은 불구속 기소됐다. 검찰은 공적자금 편취 행위에 대해 엄단할 방침을 밝히며, 향후 유사 범죄 예방을 위한 제도 개선과 감시 강화가 필요하다는 점을 강조했다.',1,0,0,1,0,'https://cloudfront-ap-northeast-1.images.arcpublishing.com/chosun/GY3DOZJVHEYGCYZQG42GMZJXMQ.jpg','2026-07-27 17:46:31.083048'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'대출 브로커 A씨는 2022년 4월부터 2024년 11월까지 의사와 약사 278명과 공모해 위조된 잔고증명서와 허위 의료기기 매매계약서를 제출하여 신용보증기금 예비창업보증 보증서 1970억원 상당을 부정하게 발급받았다.','title: 병원 개원 미끼로 2000억 허위 대출…대출 브로커 재판행
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1507,NULL,'국제','이스라엘-레바논 6차 평화협상 개최','이스라엘과 레바논은 14~15일 이탈리아 로마에서 6차 평화 협상을 개최한다. 이는 지난달 말 워싱턴DC에서 열린 5차 협상에서 휴전을 위한 기본협정에 합의한 데 이어 진행되는 것으로, 헤즈볼라의 공격 중단과 이스라엘의 레바논 남부 리타니 지역 철수를 전제로 한다. 미국은 트럼프 대통령, 네타냐후 총리, 아운 레바논 대통령 간 3자 회담을 주선하려 했으나 레바논 측이 이스라엘군 철수를 우선 조건으로 제시하며 거부했다. 현재 협상은 이탈리아 주도로 진행 중이며, 휴전 조치의 구체적 이행 시점과 감시 체계 마련이 후속 쟁점으로 남아 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/06/27/NISI20260627_0001376633_web.jpg?rnd=20260627033452','2026-07-27 17:55:10.450951'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이스라엘과 레바논이 14~15일 이탈리아 로마에서 6차 평화 협상을 개최한다.','title: "이스라엘·레바논 평화협상 14~15일 이탈리아 로마서 개최"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1508,NULL,'경제','파라과이 상원의원이 프랑스 축구대표팀의 음바페를 향해 ''모유 대신 코코넛을 빨고 자랐다''는 인종차별적 발언을 했다.','2026 FIFA 북중미 월드컵 16강전에서 프랑스가 파라과이를 1-0으로 이기고 8강에 진출한 직후, 파라과이 상원의원 셀레스테 아마리야가 프랑스 대표팀 주장 킬리앙 음바페를 향해 ''모유 대신 코코넛을 빨고 자랐다''는 인종차별적 발언을 SNS에 게시했다. 이에 음바페는 해당 발언을 ''비열한 여성''이라며 강력히 규탄했고, 프랑스 스포츠부 장관과 프랑스축구협회는 이를 ''용납할 수 없는 혐오 발언''으로 규정하며 사법 당국에 고발할 계획을 밝혔다. 파라과이 정부와 축구 협회는 발언에 대해 공식 사과를 요구했으며, 국제축구연맹(FIFA)은 인종차별 행위에 대한 조사 절차를 검토 중이다.',2,0,1,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.e28975e2e8774a85a80248c48c04cfe4_P1.jpg','2026-07-27 17:56:10.319877'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'파라과이 상원의원이 프랑스 축구대표팀의 음바페를 향해 ''모유 대신 코코넛을 빨고 자랐다''는 인종차별적 발언을 했다.','title: “모유 대신 코코넛 빨고”…파라과이 패하자 음바페 모욕한 여성의 정체
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1509,NULL,'사회','합수본, 6월 7일 인쇄업자 1명과 송파·강남·관악·서대문·강서·중랑·마포·서초구 선관위 관계자 총 9명을 참고인 신분으로 소환했다.','합동수사본부는 6월 7일 6·3 지방선거 투표용지 부족 사태와 관련해 인쇄업자 1명과 송파·강남·관악·서대문·강서·중랑·마포·서초구 선관위 관계자 총 9명을 참고인 신분으로 소환했다. 조사 대상은 투표용지 인쇄 계약 체결 및 납품 과정, 상급 기관과의 소통 여부, 대응 지침 준수 여부 등으로, 특히 2023년 9월 총선 당시 1470만 원 규모의 비공개 인쇄 계약에 대한 공정성과 투명성 문제를 중심으로 진행된다. 이전에 중앙선관위 및 서울시·구 선관위 7곳에 압수수색을 실시했으며, 서울시·송파구 선관위 관계자 12명의 휴대전화를 확보한 바 있다. 합수본은 인사·예산 전담팀을 운영해 선관위 채용 비리 및 외유성 출장 의혹, 노태악 전 중앙선관위원장 부부의 해외 출장 의혹도 수사 중이며, 향후 조사 결과를 바탕으로 공직자 징계 여부와 투표용지 제도의 투명성 강화 방안을 검토할 예정이다.',2,0,1,1,0,'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134251785.1.thumb.jpg','2026-07-27 17:56:22.965047'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'합수본, 6월 7일 인쇄업자 1명과 송파·강남·관악·서대문·강서·중랑·마포·서초구 선관위 관계자 총 9명을 참고인 신분으로 소환했다.','title: 합수본, 투표지 인쇄업자·서초구 선관위원 등 9명 무더기 소환
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1510,NULL,'경제','LG에너지솔루션, 2분기 실적 공시','LG에너지솔루션은 2024년 2분기 연결 기준 매출 7조5602억원, 영업이익 1133억원의 잠정 실적을 공시하며 흑자 전환했으나, 전년 동기 대비 영업이익은 77.0% 감소했다. 이는 미국 인플레이션 감축법(IRA)의 첨단 제조 생산 세액공제(AMPC) 제도에 따른 북미 생산 보조금 2410억원이 반영된 결과로, 보조금을 제외한 순수 영업이익은 1277억원 적자이며 영업이익률은 마이너스 1.7%였다. 상반기 누계 실적은 매출 14조1152억원(전년 동기 대비 10.5% 증가)이며, 영업이익은 945억원 적자로 적자 전환했다. LG에너지솔루션은 보조금 회계 방식을 변경해 보조금을 매출 및 기타수익으로 표기하고 있으며, 현재 잠정 실적이며 외부 감사 완료 후 확정치가 달라질 수 있다고 밝혔다.',1,1,0,0,0,'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260528.31d719043f4c4dc78a42ad8f51b9cfb3_P1.png','2026-07-27 18:00:11.714987'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'LG에너지솔루션, 2024년 2분기 연결 기준 매출 7조5602억원, 영업이익 1133억원의 잠정 실적을 공시했다.','title: [속보]LG엔솔, 2분기 매출 7.56조…‘흑자 전환’ 했다지만 영업이익은 급감
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1511,NULL,'사회','hy, 바이오리브 면역 유산균 출시','hy는 7일 면역 기능과 장 건강을 동시에 관리할 수 있도록 설계한 ''바이오리브 면역 유산균''을 출시하며 브랜드 라인업을 확대했다. 이 제품의 주원료인 ''HY7017''은 인삼 뿌리에서 분리한 유산균으로, 식품의약품안전처로부터 국내 최초로 면역 증진 기능성을 인정받았으며, 동물실험과 인체적용시험에서 자연살해세포(NK Cell) 활성도가 5.0% 증가하고 면역 반응에 관여하는 사이토카인 2종에서 긍정적 변화가 확인됐다. 제품은 실온 보관이 가능한 3중 차단 구조의 유산균 전용 용기와 초소형 캡슐 형태로 제작되어 섭취 편의성을 높였으며, 네이버 스마트스토어 등 주요 온라인 채널에서 판매 중이다. hy는 이 제품을 계기로 액상 중심이던 기존 제품군을 분말과 캡슐 등으로 확대하며 고기능성 프로바이오틱스 제품의 지속적 개발을 추진할 예정이다.',1,0,1,0,0,'https://img.etoday.co.kr/pto_db/2026/07/20260707091507_2355863_956_727.jpg','2026-07-27 18:01:01.609485'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'hy는 7일 면역 기능과 장 건강을 동시에 관리할 수 있도록 설계한 ''바이오리브 면역 유산균''을 출시했다.','title: hy, 면역·장 건강 한 번에…''바이오리브 면역 유산균'' 출시
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1512,NULL,'경제','DB금융투자, 삼성SDI 목표주가 84만원 유지','삼성SDI의 올 하반기 실적 반등 여부를 놓고 증권사 간 전망이 엇갈리고 있다. DB금융투자는 ESS 부문의 관세 환급과 북미 수요 확대, 전기차 부문 가동률 유지 등을 근거로 2분기 영업이익이 손익분기점(BEP)에 도달할 것으로 전망하며 목표주가 84만원, 투자의견 ''매수''를 유지했다. 반면 LS증권은 전기차용 배터리 시장 점유율이 5월 기준 1.4%로 전년 대비 35% 감소했고, 각형 배터리 가격 경쟁과 고객 집중도 문제로 인해 실적 회복이 어렵다고 보며 목표주가를 41만9천원으로 하향 조정하고 ''보유'' 의견을 유지했다. 현재 삼성SDI는 ESS 부문에서 글로벌 출하량 성장률(78%)보다 낮은 36% 성장에 그치며 시장 점유율이 2%에서 1.5%로 하락했고, 전기차 부문의 가동률은 70%대 유지가 예상되나, 장기적 수익성은 설비투자와 감가상각비 부담으로 인해 우려되고 있다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/news-p.v1.20260707.29719a81fa1d4617be2800ac74d546ff_P1.jpg','2026-07-27 18:02:26.760911'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'DB금융투자가 삼성SDI의 2분기 영업이익이 손익분기점(BEP)에 도달할 것으로 전망하며 목표주가 84만원, 투자의견 ''매수''를 유지했다.','title: ESS로 반등 vs 전기차 역성장…삼성SDI 실적반등 ‘엇갈린 전망’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1513,NULL,'사회','투썸플레이스, 텀블러 캠페인 진행','투썸플레이스와 IPARK현대산업개발은 7일 서울국제정원박람회 아이파크 정원 및 서울숲에서 ''텀블러와 함께하는 특별한 한 잔'' 캠페인을 공동으로 진행했다. 이는 성동구자원봉사센터와 협력해 일회용 컵 사용을 줄이고 다회용기 사용 문화를 확산하기 위한 민관 협력 활동으로, 선착순 400명에게 세척된 텀블러에 아이스 아메리카노와 아이스티를 제공했다. 캠페인은 HDC랩스, IPARK호텔, IPARK신라면세점 임직원 30명이 텀블러를 제작하고 시민들에게 나누며 탄소 절감과 자원순환의 중요성을 알렸으며, 투썸플레이스는 POS, 키오스크, 앱 등 모든 주문 채널에서 개인 텀블러 사용 옵션을 운영 중이다. 이후 IPARK현대산업개발은 중랑천 환경정화와 강서습지 생태환경 보전 등 임직원 참여형 사회공헌 프로그램을 지속적으로 운영할 계획이다.',2,0,2,0,0,'https://img.etoday.co.kr/pto_db/2026/07/20260707092252_2355885_1200_724.jpg','2026-07-27 18:02:33.840189'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'투썸플레이스는 7일 서울국제정원박람회 아이파크 정원에서 IPARK현대산업개발과 함께 ''IPARK X 투썸플레이스, 텀블러와 함께하는 특별한 한 잔'' 캠페인을 개최했다.','title: 투썸플레이스, 서울국제정원박람회서 ''텀블러 캠페인''…다회용기 사용 확산
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1514,NULL,'경제','산단공, 수출박람회 참가기업 모집','한국산업단지공단은 2026년 9월 14일부터 16일까지 대구 엑스코에서 열리는 ''제2회 대한민국 산업단지 수출박람회(KICEF 2026)''에 참가할 기업을 7일부터 모집한다. 이 박람회는 국내 산업단지 입주기업의 해외시장 진출을 지원하기 위해 마련된 산업단지 대표 수출 행사로, 올해는 ''지역의 힘을 미래로, 기업의 도전을 세계로''를 슬로건으로 전시회와 수출상담회를 중심으로 운영된다. 이번 행사에는 500개사 400부스 규모로 운영되며, 유럽·미국·동남아 등 전 세계 100여 명의 산업 바이어를 초청해 1대1 수출상담회를 진행하고, ICT·첨단산업·에너지·소비재·의료·바이오·콘텐츠 등 6개 분야 기업을 대상으로 참가를 모집한다. 참가기업은 공식 누리집을 통해 온라인 신청이 가능하며, 행사에는 제62회 산업단지의 날 기념식과 글로벌 오픈이노베이션, 세미나 등 유관기관 협력 프로그램도 포함된다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002179688_web.jpg?rnd=20260707092948','2026-07-27 18:03:52.671843'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국산업단지공단, 2026년 9월 14일부터 16일까지 대구 엑스코에서 열리는 ''제2회 대한민국 산업단지 수출박람회(KICEF 2026)''에 참가할 기업을 7일부터 모집한다.','title: 산단공, 대한민국 산단 수출박람회 참가기업 모집
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1515,NULL,'정치','김민석 전 국무총리가 2026년 7월 7일 당원 직선 방식으로 청년 최고위원을 선출할 것을 제안했다.','2026년 7월 7일 김민석 전 국무총리는 서울 여의도 국회에서 ''3대 메가프로젝트와 지방주도성장''을 주제로 한 토론회를 개최하며 이재명정부의 메가프로젝트 성공 지원을 핵심 과제로 제시했다. 이어 같은 날 그는 당원 직선 방식으로 청년 최고위원을 선출할 것을 제안하며 당원 주권 확대와 청년 세대의 참여 강화를 목표로 했다. 이는 2026년 8월 예정된 더불어민주당 당대표 선거를 앞두고 당내 혁신 논의의 일환으로, 청년 최고위원 제도 도입 방향성에 대한 논의가 본격화되고 있음을 시사한다. 반면 국민의힘은 8월 전당대회에서 30세 미만 당원 중 선출하는 청년최고위원제를 도입하기로 결정하며, 세대 간 불균형 해소를 위한 개혁적 조치를 추진하고 있다.',3,0,3,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0021352253_web.jpg?rnd=20260706154640','2026-07-27 18:07:23.893674'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'김민석 전 국무총리가 2026년 7월 7일 당원 직선 방식으로 청년 최고위원을 선출할 것을 제안했다.','title: 김민석 "당원 직선 청년 최고위원 제안…당원주권 확대의 길"
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1516,NULL,'사회','20대 남성 마약 투약 후 부모 신고로 체포','20대 남성 A씨가 김포시의 한 아파트에서 마약을 투약한 혐의를 받고 7일 부모의 신고로 경찰에 긴급체포됐다. A씨는 마약류 관리에 관한 법률 위반 혐의를 받으며, 현장에서 투명 비닐봉투에 담긴 하얀 가루와 주사기 3개를 발견했고, 소변 검사에서 필로폰 양성 반응이 나왔다. 경찰은 마약 소지 및 투약 사실을 확인하고, 범행 경위를 조사한 뒤 구속영장 신청을 검토할 예정이다. 이후 A씨에 대한 수사 결과와 구속 여부, 마약 중독 치료 및 가족 간 관리 방안에 대한 사회적 논의가 예상된다.',1,1,0,0,0,'https://cdn.womennews.co.kr/news/photo/202607/279651_450702_4019.png','2026-07-27 18:09:34.511325'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'20대 남성 A씨가 김포시의 한 아파트에서 마약을 투약한 혐의를 받고 부모의 신고로 7일 경찰에 긴급체포됐다.','title: 집에서 마약투약 20대 남성, 부모 신고로 경찰에 체포
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1517,NULL,'경제','마이크론이 포드자동차와 차세대 차량용 반도체 장기공급 계약을 체결했다.','마이크론은 포드자동차와 차세대 차량용 반도체 장기공급 계약을 체결했다. 이는 최근 자동차의 첨단 운전자 보조 시스템(ADAS)과 고전력 인포테인먼트 시스템 등에 메모리 칩이 증가하면서 반도체 수요가 급증한 배경에서 이뤄졌다. 마이크론은 버지니아주에 첨단 D램 생산시설을 확충하는 투자 계획을 추진하며, 올해 들어 D램 가격이 약 70% 상승한 상황에서 공급 안정화를 도모하고 있다. 이후 마이크론은 미국 내 반도체 생산 인프라 확대와 함께 자동차 업계와의 장기 협력 관계를 강화할 예정이며, 이는 글로벌 반도체 공급망 재편의 일환으로 주목받고 있다.',1,0,0,1,0,'https://img.mbn.co.kr/newmbn/white.PNG','2026-07-27 18:09:43.541974'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'마이크론이 포드자동차와 차세대 차량용 반도체 장기공급 계약을 체결했다.','title: 마이크론, GM 이어 포드와 차 반도체 공급 계약
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1518,NULL,'경제','삼성전자는 2024년 7월 29일 코스피 시장에서 주가가 전일 대비 6.29% 하락하며 29만 8000원을 기록했다.','삼성전자는 2024년 7월 29일 코스피 시장에서 주가가 전일 대비 6.29% 하락하며 29만 8000원을 기록하며 30만원선을 하회했다. 이는 엔비디아 등 글로벌 반도체 기업의 성장세 속에서도 삼성전자의 시장 점유율과 수익성 악화가 지속되고 있음을 반영한다. 삼성전자의 주가는 최근 1개월간 약 4% 하락했으며, 이는 메모리 반도체 수요 둔화와 경쟁사들의 기술적 우위로 인한 시장 압박이 주요 원인이다. 현재 삼성전자는 반도체 사업의 재편과 신기술 투자 확대를 통해 실적 회복을 추진하고 있으며, 향후 2분기 실적 발표와 기술 혁신 전략 발표가 주요 이벤트로 예정되어 있다.',1,0,1,0,0,'https://cdn.sisajournal.com/news/photo/202607/378914_386698_5655.jpg','2026-07-27 18:10:10.491806'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'삼성전자는 2024년 7월 29일 코스피 시장에서 주가가 전일 대비 6.29% 하락하며 29만 8000원을 기록했다.','title: 엔비디아도 제쳤는데 주가는 ‘털썩’…삼성전자 30만원 밑으로
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1519,NULL,'국제','엔화, 미 장기금리 하락에 1달러=162엔대 상승','2026년 7월 7일, 엔화는 미국 장기금리 하락으로 인해 1달러=162.03~162.04엔 수준으로 상승하며 출발했다. 이는 미국 6월 고용통계와 ISM 비제조업 PMI가 시장 예상에 못 미치며 연준의 금리 인상 전망이 후퇴한 결과로, 미일 금리차 축소에 따른 엔 매수, 달러 매도 흐름이 반영됐다. 도쿄 외환시장에서 엔화는 오전 9시48분 기준 1달러=162.14~162.15엔으로 0.01% 상승했으나, 이날 오후 1시 기준으로는 달러당 161.88엔까지 하락하며 약세 베팅이 2007년 이후 최대치로 증가했다. 일본은행의 예상보다 빠른 금리 인상과 대규모 지출 계획에도 불구하고 금리 격차 확대 우려가 지속되며, 일본 당국은 4월 28일부터 약 727억 달러를 투입해 엔화 방어에 나섰으나, 시장은 추가 개입과 연준의 금리 정책 방향에 따라 변동성이 지속될 것으로 전망하고 있다.',2,0,2,0,0,'https://img1.newsis.com/2024/07/02/NISI20240702_0020400930_web.jpg?rnd=20240702145035','2026-07-27 18:10:47.220600'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 7월 7일, 도쿄 외환시장에서 엔화 환율은 미국 장기금리 하락으로 인해 1달러=162.03~162.04엔으로 전일 오후 5시 대비 0.13엔 상승했다.','title: 엔화, 美 장기금리 하락에 1달러=162엔대 전반 상승 출발
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1520,NULL,'경제','한국탄소산업진흥원, 카본코리아 2026 참가기업 모집','한국탄소산업진흥원은 2026년 11월 4일부터 6일까지 서울 마곡 코엑스 컨벤션센터에서 ''카본코리아 2026''을 개최하며, 참가기업을 31일까지 모집한다. 이번 행사 주제는 ''인공지능(AI)과 함께하는 탄소소재의 미래: 우주·항공·방산, 에너지''로, AI 기술과 탄소소재 산업의 융합을 강조하며 우주항공, 방산, 에너지 등 핵심 수요산업과의 협력 기회를 확대한다. 전시 규모를 확대하고 코엑스 마곡으로 장소를 이전해 기업 간 비즈니스 상담과 기술 교류를 원활히 하며, 미국·일본·독일 등 해외 기업과의 국제관 운영 및 글로벌 기업 관계자들의 연사 참여를 예정하고 있다. 참가기업은 1차 모집 기간(31일까지)에 신청 시 부스 우선 배정 및 운송료 지원 혜택을 받을 수 있으며, 행사 기간 동안 전시, 컨퍼런스, B2B 상담회, 글로벌 기업 교류 프로그램 등이 진행될 예정이다.',1,0,1,0,0,'https://img1.newsis.com/2024/10/23/NISI20241023_0020569520_web.jpg?rnd=20241023160612','2026-07-27 18:11:00.359970'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국탄소산업진흥원, 2026년 11월 4일부터 6일까지 서울 마곡 코엑스 컨벤션센터에서 ''카본코리아 2026''을 개최한다.','title: 한국탄소산업진흥원, ''카본코리아 2026'' 참가기업 모집
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1521,NULL,'정치','다카이치 사나에, 일본 총리 취임','다카이치 사나에가 2025년 10월 21일 일본 자민당 창당 이후 첫 여성 총리로 취임하며 전후 140년 만에 여성 총리 탄생을 이뤘다. 그는 아베 신조 총리의 정책을 계승하며 헌법 개정, 방위력 강화, 경제 성장 등을 주요 과제로 제시했고, 2026년 2월 중의원 선거에서 자민당이 단독으로 316석을 확보하며 안정적 지지를 확보했다. 이에 따라 방위비 증액(향후 5년간 GDP 대비 2% 이상), 반격 능력 보유, 무기 수출 확대 등을 포함한 안보 3문서 개정을 추진 중이며, 특히 비핵 3원칙 중 ''핵 반입 금지'' 조항의 재검토 가능성을 시사하며 연내 개정 논의를 예고했다. 이는 중국의 군사력 증강과 대만 문제를 둘러싼 외교적 긴장 속에서 일본의 군비 경쟁과 외교적 대응의 균형을 모색하는 과정에서 발생하며, 중·일 관계 악화와 한국의 지정학적 난처함을 초래할 수 있다.',2,1,1,0,0,'https://www.pressian.com/_resources/10/2026/07/07/2026070615215548943_l.jpg','2026-07-27 18:11:09.773807'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2025년 10월 21일 다카이치 사나에가 자민당 창당 이후 첫 여성 총리로 취임하며 전후 140년 만에 여성 총리가 탄생했다.','title: 핵에 여지두는 日 다카이치hellip;''인도-태평양의 빛나는 등대'' 될 수 있을까
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1522,NULL,'경제','박항서, 2023년 6월 28일 멕시코 현지에서 한국 축구 국가대표팀 선수단장 및 대한축구협회 부회장 직을 사퇴했다.','박항서는 2026 국제축구연맹(FIFA) 북중미 월드컵 조별리그에서 한국 축구 국가대표팀이 32강 진출에 실패한 책임을 지고, 2023년 6월 28일 멕시코 현지에서 대한축구협회 부회장 및 선수단장 직을 사퇴했다. 이는 2022년 카타르 월드컵 이후 한국 축구의 성적 부진이 지속되며, 기대에 못 미친 결과에 대한 책임 소재 논란이 제기된 데 따른 조치였다. 박 부회장은 기자회견에서 국민 기대에 미치지 못한 성적에 대해 사과하며, 선수단장으로서의 공식 일정을 마무리하고 귀국했다. 이후 그는 2023년 7월부터 태국 2부리그 깐짜나부리 FC 감독으로 임명되어 새 역할을 시작할 예정이다.',1,0,0,1,0,'https://wimg.mk.co.kr/news/cms/202607/07/rcv.YNA.20260629.PYH2026062900820001300_P1.jpg','2026-07-27 18:14:41.815459'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'박항서, 2023년 6월 28일 멕시코 현지에서 한국 축구 국가대표팀 선수단장 및 대한축구협회 부회장 직을 사퇴했다.','title: “기대 못미쳐 죄송”…박항서, 축구협회 부회장 사퇴
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1523,NULL,'사회','어린이집 버스에 원아 45분 방치','제주지역 한 어린이집의 교사 A씨와 운전기사 B씨가 지난 6월 15일 통학버스에 원아 1명을 약 45분간 방치한 혐의로 아동복지법 위반(아동학대)으로 불구속 입건됐다. 사건은 어린이집 교사와 기사가 버스를 운행한 후 원아가 잠든 상태로 뒷좌석에 남아 있음을 인지하지 못한 데서 발생했으며, 당시 시간에 쫓겨 점검을 소홀히 한 것으로 전해졌다. 아이는 건강에 이상이 없었으나, 경찰은 정확한 사건 경위를 조사 중이며 어린이집 측도 관리 소홀을 인정하고 있다. 이후 제주경찰청은 사건에 대한 추가 조사를 진행하고 있으며, 관련 기관은 어린이집 통학버스 운영 절차의 개선 필요성을 제기하고 있다.',1,0,0,1,0,'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134249717.1.thumb.jpg','2026-07-27 18:17:18.434867'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'제주지역 한 어린이집의 교사 A씨와 운전기사 B씨가 6월 15일 어린이집 통학버스에 원아 1명을 약 45분간 방치한 혐의로 아동복지법 위반(아동학대)으로 불구속 입건됐다.','title: 잠든 아이 깜빡, 차에 45분 방치…어린이집 버스 기사·교사 입건
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1524,NULL,'사회','서미화 의원이 2025년 기준 전국 226개 기초지방자치단체 중 139개가 장애인 의무고용률을 달성하지 못했다고 7일 밝혔다.','2025년 기준 전국 226개 기초지방자치단체 중 139개(61.5%)가 장애인 의무고용률(3.8%)을 달성하지 못한 것으로 나타났다. 장애인고용촉진 및 직업재활법에 따라 지자체는 일정 비율 이상의 장애인을 고용해야 하며, 이는 장애인의 노동권 보장과 지역사회 자립 가능성을 나타내는 지표로 평가된다. 전라남도 보성군(1.14%)이 가장 낮은 고용률을 보였고, 부산광역시 연제구(5.85%)가 가장 높았다. 서울·부산·광주·대전·울산은 모두 의무고용률을 충족했으나, 수도권과 일부 지방권에서는 대부분의 지자체가 미달 상태이며, 향후 지자체별 맞춤형 공공일자리 확대와 법적 의무 이행 강화가 필요하다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202607/231872_128620_5913.jpg','2026-07-27 18:21:19.004914'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서미화 의원이 2025년 기준 전국 226개 기초지방자치단체 중 139개가 장애인 의무고용률을 달성하지 못했다고 7일 밝혔다.','title: 기초지자체 60% 이상 장애인고용률 미달, “장애인 자립 출발은 일자리”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1525,NULL,'사회','코스맥스, 프랑스 BIPEA가 주관한 자외선 차단 지수 숙련도 평가에서 ISO 23675 기반 체외 SPF 평가법을 활용해 ''새티 스팩 토리(Satisfactory)'' 등급을 달성했다.','코스맥스는 프랑스 BIPEA가 주관한 자외선 차단 지수 숙련도 평가에서 ISO 23675 기반 체외 SPF 평가법을 활용해 ''새티 스팩 토리(Satisfactory)'' 등급을 달성했다. 이 평가는 PMMA 판을 이용한 비임상 평가 방식으로, 인체 시험 없이도 자외선 흡수 특성을 정밀하게 측정할 수 있어 평가 기간 단축과 재현성 향상에 기여한다. 코스맥스는 2024년 2월 국내 화장품 업계 최초로 이 평가법을 도입했으며, 선케어 부문 매출은 지난해 대비 47%, 올해 1분기에는 전년 동기 대비 35% 성장했다. 이번 인증을 통해 유럽 시장 진출을 위한 선케어 제품 개발 속도가 가속화되고, 글로벌 고객사의 제품 개발 및 시장 대응력 강화에 기여할 전망이다.',2,0,1,1,0,'https://img.etoday.co.kr/pto_db/2026/07/20260707101844_2355950_1199_799.jpg','2026-07-27 18:21:38.816277'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'코스맥스, 프랑스 BIPEA가 주관한 자외선 차단 지수 숙련도 평가에서 ISO 23675 기반 체외 SPF 평가법을 활용해 ''새티 스팩 토리(Satisfactory)'' 등급을 달성했다.','title: 코스맥스, 프랑스 BIPEA 자외선 차단지수 숙련도 ‘최고 등급’ 달성
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1526,NULL,'경제','해양수산부는 4월17일부터 시작된 홍해를 통과한 한국 선박 한 척이 7일 오전 10시 기준 국내로 원유를 운송하고 있다고 밝혔다.','한국 선박 한 척이 4월17일부터 시작된 홍해를 통과해 사우디아라비아 얀부항에서 적재한 원유를 국내로 운송했다. 이는 호르무즈 해협이 미국과 이란 간 중동전쟁으로 인해 봉쇄된 이후 대체 항로로 홍해를 활용한 12번째 운송이다. 해양수산부는 선박의 안전을 위해 실시간 모니터링과 소통 채널을 운영했으며, 현재까지 국내 원유 수급 안정화를 위해 홍해 경로를 지속적으로 활용할 계획이다. 한편, 호르무즈 해협 내에는 이란 공격으로 수리 중인 HMM 나무호를 포함해 한국 선박 2척과 선원 23명이 남아 있어 안전 상황이 주목되고 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/01/NISI20260701_0002175751_web.jpg?rnd=20260701204749','2026-07-27 18:21:46.386890'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'해양수산부는 4월17일부터 시작된 홍해를 통과한 한국 선박 한 척이 7일 오전 10시 기준 국내로 원유를 운송하고 있다고 밝혔다.','title: 홍해서 12번째 한국 원유수송선 통과…국내 원유 운송
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1527,NULL,'국제','이란 이슬람혁명수비대(IRGC)가 2024년 3월 7일 오만 리마 동쪽 15km 지점에서 남쪽으로 항해 중이던 유조선 1척을 미사일로 공격했다.','이란 이슬람혁명수비대(IRGC)는 2024년 3월 7일 오만 리마 동쪽 약 15km 지점에서 남쪽으로 항해 중이던 유조선 1척을 미사일로 공격했다. 공격은 아야톨라 하메네이 전 최고지도자 장례기간 나흘차에 발생하며, 피해 선박은 카타르 국영 LNG 산업의 해운 계열사가 소유한 ''알 레카야트''로 추정된다. 발사체는 유조선 좌현에 충돌해 화재를 유발했으나 인명피해나 환경오염은 보고되지 않았다. 혁명수비대는 해상 무선통신을 통해 미사일과 드론의 발사 준비를 강조하며, 오만 해안 인근 미군이 지정한 항로를 이용하지 말 것을 경고했고, 이는 해상 안보 리스크와 외교적 긴장의 신호로 해석된다.',2,0,1,1,0,'https://img.mbn.co.kr/newmbn/white.PNG','2026-07-27 18:21:58.169592'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'이란 이슬람혁명수비대(IRGC)가 2024년 3월 7일 오만 리마 동쪽 15km 지점에서 남쪽으로 항해 중이던 유조선 1척을 미사일로 공격했다.','title: 아슬아슬한 정전 협정…이란, 호르무즈 상선 2척에 미사일
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1528,NULL,'사회','장애인공단·진흥원, 판로 활성화 협약','한국장애인고용공단과 한국사회적기업진흥원은 7일 서울 소재 진흥원 대회의실에서 ''장애인 표준사업장과 사회적기업의 판로 활성화를 위한 업무협약''을 체결했다. 이번 협약은 장애인 표준사업장과 사회적기업의 경제적 자립과 사회적 가치 창출을 목표로 하며, 판로개척을 위한 ''같이일터''와 ''가치장터'' 연계, 사회적기업 인증교육 지원, 우선구매제도 강화 및 지역 기반 인프라 구축을 주요 내용으로 한다. 양 기관은 협약을 통해 표준사업장의 판로 확대와 장애인 고용 확대를 추진하며, 특히 ''같이일터''와 ''가치장터'' 플랫폼을 활용한 공동 홍보 및 구매 촉진을 계획하고 있다. 이후 협약 이행 상황 점검과 함께, 지역별 협력 모델 확산 및 정부 지원 정책과의 연계 방안이 후속 쟁점으로 부각될 전망이다.',1,0,1,0,0,'https://cdn.ablenews.co.kr/news/photo/202607/231873_128625_5610.jpg','2026-07-27 18:25:02.435254'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한국장애인고용공단과 한국사회적기업진흥원이 7일 서울 소재 진흥원 대회의실에서 ''장애인 표준사업장과 사회적기업의 판로 활성화를 위한 업무협약''을 체결했다.','title: 장애인공단·진흥원, ‘장애인 표준사업장과 사회적기업 판로 활성화’ 맞손
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1529,NULL,'사회','고속도로 사고 위험 예방 대책 당부','2026년 7월 장마와 휴가철이 겹치며 고속도로 사고 위험이 증가하고 있다. 최근 3년간 7월 평균 강수량은 378㎜로 연중 최고이며, 빗길 사고의 치사율은 맑은 날 대비 약 1.4배 높다. 특히 노면이 젖은 상태에서는 타이어 접촉력 저하로 제동거리가 늘어나며, 폭우 시에는 속도를 50% 이상 감속해야 한다. 도로공사와 한국교통안전공단은 출발 전 타이어 및 와이퍼 점검, 차간 거리 확보, 2시간 이상 운전 시 휴게소 휴식, 비상 탈출 도구 비치 등을 통해 사고 예방을 당부하고 있다.',2,0,2,0,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002179914_web.jpg?rnd=20260707110738','2026-07-27 18:25:33.490905'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2025년 7월 영동고속도로 여주휴게소 인근(인천 방향)에서 2차로를 달리던 차량의 타이어가 파손돼 차량이 미끄러지는 사고가 발생했다.','title: 장마·휴가철 겹친 7월…고속도로 사고 위험 커진다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1530,NULL,'사회','허위 렌탈계약으로 자금 사기','2026년 7월 7일, 창원지방검찰청은 허위 렌탈계약을 통해 금융회사로부터 141억원을 사기로 빼돌린 혐의로 A렌탈사 대표 B씨와 이사 C씨를 구속기소하고, 금융심사 편의를 제공한 캐피탈사 직원 D씨를 배임수재 혐의로 불구속 기소했다. 이 사건은 병원, 공장, 호텔 등 사업자를 대상으로 ''백렌탈''과 ''공렌탈'' 방식의 허위 계약을 체결하고, 실제 물품 없이 리스·팩토링 등 금융상품을 신청해 허위 확인서를 제출해 자금을 유치한 조직적 사기 구조로, 전국적으로 약 414억원 규모의 허위 계약이 확인된 것으로 파악됐다. 검찰은 A렌탈사가 금융기관에서 받은 자금 중 약 11%를 수수료로 챙기며 불법 대부업을 운영했으며, 캐피탈사 직원에게 약 4년간 현금 1억6000만 원과 고급 승용차 렌트비 4300만 원 등 총 2억원 상당의 금품을 제공해 심사 편의를 제공받은 사실도 확인했다. 검찰은 해외 체류 중인 관련자까지 수사 범위를 확대하고 있으며, 범죄수익 환수와 외부 공범 수사, 엄정한 처벌을 지속할 예정이다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002179905_web.jpg?rnd=20260707110234','2026-07-27 18:25:41.513161'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 7월 7일, 창원지방검찰청은 A렌탈사 대표 B씨와 이사 C씨를 허위 렌탈계약을 이용해 금융회사로부터 141억원 상당의 자금을 받아 가로챈 혐의로 구속기소했다.','title: 허위 렌탈계약으로 141억 빼돌렸다…신종 금융사기
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1531,NULL,'정치','종합특검, 이원모 전 비서관 소환 조사','2024년 7월 7일, 종합특검은 김건희 여사의 최측근으로 지목된 유경옥 전 대통령실 행정관을 특정범죄가중처벌법상 알선수재 방조 혐의로 피의자 신분으로 조사했다. 이는 김건희 여사와의 친분을 이용해 종합건설업 면허가 없는 21그램이 부당하게 공사를 수주한 의혹과 관련된 것으로, 유 전 행정관은 명품 의류 제공 사실을 알고 있었는지 등에 대해 조사받았다. 7월 20일에는 이원모 전 대통령실 비서관이 김건희씨 청와대 입성과 관련한 정보 처리 과정에서 ''황제조사 의혹''과 관련해 참고인 신분으로 소환 조사되었으며, 관련 정보를 보고한 바가 없음을 밝혔다. 특검은 추가 증거 확보를 위해 다른 관계자 조사와 수사 방향성 수립을 지속할 예정이다.',2,1,1,0,0,'https://cdn.sisajournal.com/news/photo/202607/378924_386716_5533.jpg','2026-07-27 18:26:22.225505'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 7월 20일, 종합특검은 김건희씨 관련 ''황제조사 의혹''과 관련해 이원모 전 대통령실 비서관을 참고인으로 소환해 조사를 진행했다.','title: 종합특검, ‘김건희 황제조사 의혹’ 이원모 전 대통령실 비서관 참고인 소환
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1532,NULL,'사회','서울시, 출산 가구 월세 지원 확대','서울시가 전·월세 부담이 큰 무주택 출산 가구를 대상으로 월세를 최대 2년간 월 30만원씩 지원하는 ''자녀 출산 무주택 가구 주거비 지원 사업''을 하반기 접수 중이다. 기존 전세보증금 3억원 이하에서 5억원 이하로 요건을 완화하고, 부모 모두 무주택자이며 기준 중위소득 180% 이하인 가구가 신청 가능하며, 출생 신고지와 거주지가 서울이어야 한다. 올해 상반기 신청 가구는 지난해 전체 대비 88% 증가한 1754가구로, 지원금은 전세대출 이자 및 월세 납부 내역을 증빙한 후 6개월 단위로 4회 분할 지급되며, 자녀 1명당 지원 기간이 1년씩 연장되어 최대 4년까지 가능하다. 하반기 신청 기간은 7월 1일부터 12월 31일까지이며, 자격 검증 후 2027년 1월 결과 발표 후 2월부터 지원금 지급이 시작되며, 출산 후 1년 이내 신청이 필수이다.',1,1,0,0,0,'https://img.khan.co.kr/news/2026/07/07/news-p.v1.20260707.2acab18102324e5c809ddba40eb7b9d1_P1.jpg','2026-07-27 18:26:33.660207'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울시가 전·월세 부담이 큰 무주택 출산 가구를 대상으로 2024년 하반기부터 최대 2년간 월 30만원씩 월세를 지원한다.','title: 비싼 월세에 부담스러운 출산 가정, 서울시가 2년간 월세 지원한다
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1533,NULL,'경제','GS건설, 용산 서계통합구역 수주전 준비','서울 용산구 서계동 33번지 일대 서계통합구역 재개발 사업의 시공사 선정 절차가 올해 말에서 내년 초 본격화될 전망이다. 이 사업은 지하 3층~지상 39층, 20개 동, 2937세대 규모로 조성되며, 사업비는 약 1조 원으로 추산된다. GS건설은 조합 설계사 선정 이후 설계합동사무소를 개설하고 글로벌 설계사 SMDP와 협업하며 맞춤형 설계안을 검토하고 있으며, 성수전략정비구역 1지구 수주 경험을 바탕으로 전담 팀을 투입하는 등 사전 경쟁을 강화하고 있다. 현재는 입찰 지침이 공개되지 않아 정확한 수주 전망은 불투명하지만, 삼성물산, 대우건설 등 주요 건설사들의 관심이 높아지고 있으며, 공사비, 금융 조건, 이주 지원, 사업 기간 등 다양한 요소가 경쟁의 초점이 될 전망이다.',1,0,0,1,0,'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134248225.1.thumb.jpg','2026-07-27 18:28:50.659698'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울 용산구 서계동 33번지 일대 서계통합구역 재개발 사업의 시공사 선정 절차가 이르면 올해 말에서 내년 초 본격화될 전망이다.','title: 용산 정비사업 대어 서계통합구역… GS건설, 초반 수주전 속도전
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1534,NULL,'국제','중국 증시, 경제지표 발표 전 관망세로 하락','중국 증시는 7일 주요 경제지표 발표를 앞두고 관망세로 속락 출발했다. 상하이 종합지수는 전일 대비 0.53% 하락한 4019.49로, 선전 성분지수는 0.46% 하락한 1만5345.39로 개장했으며, 창업판 지수는 0.44% 하락한 3931.44로 거래를 시작했다. 반도체주, 금광주, 보험주, 약품주, 양조주 등이 약세를 보였고, 특히 더밍리(-6.20%), 베이징 쥔전(-6.09%), 란치과기(-3.94%) 등이 하락폭이 컸으며, 반면 중국은행(+1.42%), 닝더스다이(+4.12%) 등 일부 은행주와 전지 관련주는 상승세를 보였다. 이후 오전 10시40분 기준 상하이 종합지수는 0.76% 하락한 4010.64를 기록했으며, 주요 지수는 지속적인 하락세를 보이고 있으며, 경제지표 발표 전후 시장의 방향성과 정책 대응이 주요 쟁점으로 부각되고 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/06/10/NISI20260610_0002157837_web.jpg?rnd=20260610165637','2026-07-27 18:29:00.089797'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'중국 증시는 7일 주요 경제지표 발표를 앞두고 관망세로 속락 출발했다.','title: [올댓차이나] 中 증시, 주요지표 발표 전 관망세로 속락 개장…창업판 0.2%↓
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1535,NULL,'사회','검찰이 친모 A씨에 대해 무기징역을, 친부 B씨에 대해 징역 10년을 각각 구형했다.','2026년 7월 7일 광주고법 형사2부는 생후 4개월 된 아들 ''해든이''를 학대해 사망하게 한 친모 A씨(34)와 친부 B씨(36)에 대해 각각 무기징역과 징역 10년을 구형했다. A씨는 19차례에 걸쳐 아동학대를 하고, 수차례 폭행 및 욕조에 샤워기 물을 틀어 방치해 아동을 사망하게 한 혐의로 1심에서 무기징역을 선고받았으며, B씨는 아내의 학대를 방임하고 사건 참고인을 협박한 혐의로 1심에서 징역 4년 6개월을 선고받았다. 검찰은 A씨가 감정 표현의 대상으로 아동을 학대했고, B씨는 아동 보호 의무를 소홀히 해 책임을 회피했다며 엄벌을 요청했으며, 재판 과정에서 여검사의 구형 의견 낭독과 A씨의 ''좋은곳 가길'' 편지 낭독으로 방청객이 울먹이는 등 사회적 공감대가 형성됐다. 항소심 선고는 2026년 8월 25일 오후에 예정되어 있으며, 사건은 아동학대 방지 및 양육 책임에 대한 사회적 논의를 촉발하고 있다.',1,0,1,0,0,'https://img1.newsis.com/2024/03/06/NISI20240306_0020256265_web.jpg?rnd=20240306181910','2026-07-27 18:29:07.823491'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'검찰이 친모 A씨에 대해 무기징역을, 친부 B씨에 대해 징역 10년을 각각 구형했다.','title: ''해든이 사건'' 울먹인 여검사…母 "좋은곳 가길" 편지낭독
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1536,NULL,'사회','경기도, 주거 안정 정책 선호도 조사','경기도는 3일부터 5일까지 수원KT위즈파크에서 열린 ''경기도-KT위즈 브랜드 협업'' 행사에서 현장 여론조사를 실시한 결과, 도민이 가장 바라는 정책으로 ''내 집 걱정 없는 경기''가 520표(41.6%)로 1위를 차지했다. 이는 주거 안정을 위한 정책 수요가 높은 상황을 반영하며, 추미애 경기도지사의 ''대청마루'' 소통 철학과 일치한다. 현장 조사 외에도 온라인 여론조사 누리집을 통해 만 14세 이상 경기·서울·인천 거주자 누구나 참여 가능하며, 현재 누적 참여자 수는 7만6000여 명에 달한다. 경기도는 온라인과 현장 소통 경로를 확대해 도민의 목소리가 정책에 충실히 반영되도록 할 방침이다.',2,0,1,1,0,'https://dimg.donga.com/a/232/131/95/1/wps/NEWS/IMAGE/2026/07/03/134224350.3.jpg','2026-07-27 18:29:14.119939'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'경기도는 3일부터 5일까지 수원KT위즈파크에서 열린 ''경기도-KT위즈 브랜드 협업'' 행사에서 현장 여론조사를 실시했다.','title: “집 걱정부터 덜어달라”…경기도민이 가장 바란 정책 1위는 ‘주거 안정’
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1537,NULL,'경제','기후부, AI 업무혁신 팀 선발 추진','기후부는 8일 세종시에서 ''기후 에이아이 프렌즈'' 발대식을 열고, 부처 산하기관 직원 2~3명으로 구성된 총 20개 팀을 선발해 인공지능 기반 업무혁신 과제를 추진한다. 이는 공공부문의 인공지능 대전환에 발맞춰 직원들의 기술 활용 역량을 높이고, 실제 업무에 AI를 적용할 수 있는 혁신 과제를 발굴하기 위한 것으로, 사전 신청한 40개 팀 중 창의성, 실현 가능성, 업무 활용성 등을 기준으로 선정했다. 선정된 팀들은 9월까지 ''인공지능 기반 업무자동화''와 ''인공지능 서비스 기획·구현'' 두 분야에서 활동하며, 기후부는 실습 교육과 전문가 조언을 지원하고 성과공유회를 통해 우수 사례를 확산할 계획이다. 이후 기후부는 과제 성과를 바탕으로 공공행정 혁신과 국민 편의 증진을 위한 정책적 적용 방안을 검토할 예정이며, 이는 공공부문 AI 전환의 모범 사례로 자리매김할 가능성이 있다.',1,0,1,0,0,'https://img1.newsis.com/2025/11/18/NISI20251118_0001996230_web.jpg?rnd=20251118152920','2026-07-27 18:31:38.664806'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'기후부, 8일 세종시에서 ''기후 에이아이 프렌즈'' 발대식을 열고 부처 산하기관 직원으로 구성된 20개 팀을 선발해 인공지능 기반 업무혁신 과제를 추진한다.','title: "AI로 일하는 방식 바꾼다"…기후부, AI 업무혁신 추진
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1538,NULL,'국제','2024년 4월 7일 홍콩 증시는 글로벌 반도체 시장 조정 영향으로 항셍지수와 H주 지수가 각각 0.20%, 0.41% 하락하며 반락 개장했다.','2024년 4월 7일 홍콩 증시는 글로벌 반도체 시장 조정 영향으로 항셍지수와 H주 지수가 각각 0.20%, 0.41% 하락하며 반락 개장했다. 이는 반도체주와 비철금속, 보험, 소비 관련주 등이 약세를 보이며 투자심리가 악화된 데서 비롯되었으며, 특히 창페이, 란치과기, 콰이서우, 신이광넝 등 주요 종목이 급락했다. 오전 10시59분 기준 항셍지수는 2만3549.96(-0.28%), H주 지수는 7785.87(-0.34%)를 기록하며 하락세 지속 중이다. 반면 인공지능(AI) 및 전기차, 전자상거래, 은행주 등은 상승세를 보이며 시장 분위기의 양극화가 지속되고 있으며, 향후 글로벌 반도체 수요 회복 여부와 중국 경제 정책 동향이 주요 쟁점으로 부상하고 있다.',1,0,1,0,0,'https://img1.newsis.com/2021/02/06/NISI20210206_0017129752_web.jpg?rnd=20260429002746','2026-07-27 18:35:44.416974'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 4월 7일 홍콩 증시는 글로벌 반도체 시장 조정 영향으로 항셍지수와 H주 지수가 각각 0.20%, 0.41% 하락하며 반락 개장했다.','title: [올댓차이나] 홍콩 증시, 글로벌 반도체 조정에 반락 개장…H주 0.34%↓
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1539,NULL,'정치','교육교부금법 개정안 3건 연달아 발의','2026년 6월 29일부터 7월 3일까지 국회에 교육교부금법 개정안 3건이 연달아 발의됐다. 조은희 국민의힘 의원안은 내국세 연동 방식을 폐지하고 경제성장률, 물가상승률, 학령인구 변화를 반영한 산식을 도입하며, 교부금이 전년도의 95% 미만으로 줄어들 경우 최소 95%를 보장하는 안정장치를 마련했다. 이헌승 의원안은 고정된 20.79% 교부율을 대통령령으로 조정 가능하게 하여 교육재정 수요에 유연하게 대응하되, 교육청의 재원 예측 불확실성이 증가할 수 있다는 우려가 제기됐다. 강경숙 조국혁신당 의원안은 교육청의 재정운용 노력 평가를 교부금 배분 기준에 반영해 교육청의 책임성을 강화하는 방식으로, 교부금 총량을 줄이기보다는 배분 효율성을 높이는 데 초점을 맞췄다.',1,0,1,0,0,'https://img1.newsis.com/2026/06/22/NISI20260622_0002166481_web.jpg?rnd=20260622095706','2026-07-27 18:38:53.103074'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 6월 29일부터 7월 3일까지 국회에 교육교부금법 개정안 3건이 연달아 발의되었다.','title: 정부 합의해도 국회 문턱 넘어야…교육교부금 개편 법안 핵심은
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1540,NULL,'경제','기후부, 자연자본공시 토론회 개최','기후에너지환경부는 2026년 7월 7일 서울 강남구 코엑스에서 대한상공회의소와 함께 제4차 자연자본공시 토론회를 개최했다. 이는 자연자본공시 표준을 제정한 TNFD 등 국제 기구와 해외 기업·금융기관 전문가들이 참여해 국제 동향과 대응 전략을 공유하는 자리로, 삼성전자와 SK증권도 각각 제조업 및 금융기관 차원의 경험을 발표했다. 이번 토론회에는 국내외 기업·학계·전문가 등 150여 명이 참석했으며, 기후부는 기업의 대응 역량 강화를 통해 생물다양성 보전 투자 확대를 목표로 하고 있다. 향후 기업들의 자연자본 공시 이행률 제고와 국내 기준 마련을 위한 정책 방향성 논의가 예정되어 있으며, 기업의 실질적 대응 체계 구축이 핵심 과제로 부상하고 있다.',1,0,1,0,0,'https://img1.newsis.com/2025/11/18/NISI20251118_0001996228_web.jpg?rnd=20251118152904','2026-07-27 18:40:42.833737'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'기후에너지환경부는 2026년 7월 7일 서울 강남구 코엑스에서 대한상공회의소와 함께 제4차 자연자본공시 토론회를 개최했다.','title: 기후부, 전문가들과 자연자본공시 대응 전략 논의
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1541,NULL,'정치','2026년 7월 7일, 제310회 고성군의회 제1차 본회의에서 정영환 의원과 우정욱 의원이 만장일치로 제10대 고성군의회 전반기 의장과 부의장으로 선출됐다.','2026년 7월 7일, 제310회 고성군의회 제1차 본회의에서 제10대 고성군의회 전반기 의장으로 정영환 의원(국민의힘·나선거구), 부의장으로 우정욱 의원(국민의힘·다선거구)이 만장일치로 선출됐다. 이번 선거는 기존의 ''교황식'' 방식에서 ''후보 등록제''로 변경된 첫 번째 시행으로, 재적의원 11명 중 출석의원 11명 전원이 표를 행사해 각각 만장일치로 당선됐다. 정영환 의장은 군민의 기대에 부응하는 신뢰받는 의회를 만들겠다며 책임감을 강조했고, 우정욱 부의장은 동료 의원과의 협력을 통해 의회의 역량을 결집하겠다고 밝혔다. 다음 날인 8일에는 의회운영위원장, 기획행정위원장, 산업경제위원장 등 3개 상임위원장 선거가 예정되어 있으며, 이는 의회 운영의 정상화를 위한 후속 절차로 진행될 예정이다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002180095_web.jpg?rnd=20260707134841','2026-07-27 18:44:14.792864'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2026년 7월 7일, 제310회 고성군의회 제1차 본회의에서 정영환 의원과 우정욱 의원이 만장일치로 제10대 고성군의회 전반기 의장과 부의장으로 선출됐다.','title: 고성군의회, 의장 정영환 의원·부의장 우정욱 의원 선출
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1542,NULL,'경제','한전원자력연료, AI전략위원회 출범','한전원자력연료는 2024년 4월 7일 대전 본사에서 AI전략위원회를 출범시켰다. 이는 생성형 AI 확산과 공공부문 AI 활용 확대 등 디지털 환경 변화에 선제적으로 대응하고 전사적 AI 전략을 수립하기 위한 목적이다. 위원회는 최고경영자(CEO)가 위원장으로, 대내외 전문가가 참여해 AI 전략 수립, 실행과제 관리, 현장 역량 확산, 보안·윤리 리스크 대응 등 전사적 현안을 논의하며, 우선과제 선정과 실행 방향을 구체화했다. 이후 AI 기반 업무혁신의 지속적 추진과 함께, 기술 도입의 윤리적·보안적 관리, 조직 내 역량 강화 등 후속 절차가 진행될 예정이다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/07/NISI20260707_0002180148_web.jpg?rnd=20260707141752','2026-07-27 18:52:14.477221'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'한전원자력연료는 2024년 4월 7일 대전 본사에서 AI전략위원회를 출범시켰다.','title: 한전원자력연료, ''AI전략위원회'' 출범…업무혁신 추진
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1543,NULL,'사회','20대 아들, 어머니 폭행해 사망','20대 남성 이 모 씨는 지난해 12월 어머니를 둔기와 흉기로 공격해 숨지게 한 혐의로 서울남부지법에서 존속살해罪로 징역 12년을 선고받았다. 재판부는 이 씨가 조현병으로 인한 심신미약 상태에서 범행을 저지른 것으로 보이며, 범행을 인정하고 전력이 없어 양형에 반영했다고 설명했다. 범행 당시 이 씨는 환청과 과대망상을 경험했으며, 정신감정 결과 치료가 필요하고 재범 위험이 있는 것으로 판단됐다. 검찰은 징역 15년을 구형했고, 이 씨는 10년간 위치추적 전자장치 부착과 치료감호도 명령받았다.',1,0,0,1,0,'https://dimg.donga.com/a/464/260/95/1/wps/NEWS/FEED/Donga_Home_News2/134245903.1.thumb.gif','2026-07-27 18:53:42.335768'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'서울남부지법 형사합의13부는 20대 남성 이 모 씨에게 존속살해 혐의로 징역 12년을 선고했다.','title: 어머니 폭행해 숨지게 한 20대 아들, 1심 징역 12년…“남은 가족 고통”
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1544,NULL,'사회','아들·아버지, 어머니 살해 후 헌법재판소 재판소원 제기','2024년 3월, 경기 고양시에서 80대 어머니를 살해한 아들 A씨와 아버지 B씨가 ''촉탁살인''을 주장하며 헌법재판소에 재판소원을 제기했다. 이들은 2014년부터 11년간 어머니를 간병하며 병세 악화와 생활고, 주거지 퇴거 위기 등으로 인해 동반자살을 결심했으며, 피해자가 사망 전 지속적으로 ''죽여달라''고 요청했다고 주장한다. 범행 후 아들은 한강에 투신했으나 구조되었고, 법원은 각각 존속살해 및 마약류관리법 위반 혐의로 아들 A씨에게 징역 7년, 아버지 B씨에게 징역 3년을 선고했다. 헌법재판소는 이들의 재판소원을 받아들일지 여부가 불확실하며, 지난달까지 접수된 재판소원 1200건 중 전원재판부 회부는 단 10건에 그쳤다.',1,0,1,0,0,'https://img.sbs.co.kr/news/pc/thumb_v3.png','2026-07-27 18:58:04.548893'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'2024년 3월, 아들 A씨와 아버지 B씨가 경기 고양시 자택에서 어머니를 살해한 후 헌법재판소에 재판소원을 제기했다.','title: "죽여달라" 혀 깨물고 비명 참아…''11년 간병살인'' 부자의 호소
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1545,NULL,'경제','박홍근 기획예산처 장관이 2026년 7월 7일 오후 국회 의원회관에서 청년 국회의원들과 청년정책 간담회를 개최했다.','기획예산처는 2026년 7월 7일 박홍근 장관 주재로 국회 의원회관에서 청년 국회의원들과 청년정책 간담회를 개최했다. 이번 간담회는 일자리, 창업, 주거, 자산 등 청년정책 핵심 과제를 논의하며, 기획처가 지난 3월 청년 일자리 현장 방문과 5월 청년 라이브톡 등을 통해 현장 의견을 수렴한 후 진행된 것으로, 청년 전문가 간담회를 거쳐 2027년도 예산안과 중장기 전략에 반영할 계획이다. 기획처는 청년 실업률 상승과 주거비 부담 증가 등 현실적 어려움을 국가적 과제로 인식하고, 청년의 공정한 기회 제공과 회복 사다리 마련을 정책 목표로 삼고 있다. 이후 청년 전문가 간담회를 추가로 개최하고, 제시된 의견을 검토해 예산과 정책에 구체적으로 반영할 예정이며, 야당 의원은 실망감 해소를 위한 실질적 성과가 필요하다는 지적을 제기하며 정책 이행의 지속성과 효과성에 주목하고 있다.',1,0,1,0,0,'https://img1.newsis.com/2026/01/06/NISI20260106_0021117580_web.jpg?rnd=20260106152620','2026-07-27 18:59:23.803765'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'박홍근 기획예산처 장관이 2026년 7월 7일 오후 국회 의원회관에서 청년 국회의원들과 청년정책 간담회를 개최했다.','title: 기획처, 청년의원과 첫 정책간담회…내년 예산에 반영
INSERT INTO public."events" ("id","topic_id","category","title","summary","article_count","left_count","mid_count","right_count","abusing_count","event_image_url","created_at","updated_at","prev_event_id","next_event_id","reason","core_content","embedding_text") VALUES (1546,NULL,'정치','대구 동구의회, 7일 제353회 임시회에서 상임위원장을 선출하며 전반기 원구성을 완료했다.','제10대 대구 동구의회는 7일 제353회 임시회에서 상임위원장을 선출하며 전반기 원구성을 완료했다. 전날 열린 제1차 본회의에서 국민의힘 이연미 의원이 의장, 더불어민주당 안평훈 의원이 부의장으로 선출되었으며, 의회운영위원장 유병진, 기획행정위원장 노남옥, 경제복지위원장 김은옥, 도시건설위원장 김동규 의원이 상임위원장으로 각각 선출되었다. 이연미 의장은 의회운영의 책임감을 강조하며 소통과 협치를 기반으로 현장 중심의 의정 활동을 펼칠 계획이라고 밝혔다. 이후 2년간 지역 현안 해결과 주민 복리 증진을 위한 의정 활동이 예정되어 있으며, 의장단과 상임위원회의 운영 방향에 대한 주민 반응과 정책 효과가 주목된다.',1,0,1,0,0,'https://img1.newsis.com/2026/07/06/NISI20260706_0002178859_web.jpg?rnd=20260706112954','2026-07-27 18:59:34.115493'::timestamp,'2026-07-27 18:59:53.925526'::timestamp,NULL,NULL,NULL,'대구 동구의회, 7일 제353회 임시회에서 상임위원장을 선출하며 전반기 원구성을 완료했다.','title: 대구 동구의회, 전반기 원구성 완료…의장은 국힘 이연미
