INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1182,2,'강훈식 대통령 비서실장은 5일 추가 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 미래 대응 기금 신설을 추진하고자 한다고 밝혔다. 반도체 호황으로 내년까지 더 걷힐 것으로 예상되는 세금은 최대 100조원 안팎에 이를 전망이다. 강 실장은 미래 대응 기금 신설은 ''대체 불가 대한민국'' 실현의 초석이 될 것이라고 말했다. 이날 고위 당정에서는 이재명 대통령이 발표한 반도체, 인공지능(AI) 데이터센터, 피지컬AI 등 ''3대 메가 프로젝트'' 추진 방안이 집중 논의됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 07:52:34'::timestamp,'2026-07-27 16:32:56.924651'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1183,3,'당정은 5일 ''대한민국 대도약 3대 메가프로젝트''를 위해 ''미래대응기금''을 신설하겠다고 밝혔다. 반도체, AI 데이터센터, 피지컬 AI를 전략사업으로 집중 육성할 계획이다. 추가 세수를 미래세대와 대한민국 성장동력 양극화 대응 등에 사용할 예정이다. AI 데이터센터 구축에 차질이 발생하지 않도록 전력, 부지, 인허가를 전폭적으로 지원할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 07:52:36'::timestamp,'2026-07-27 16:34:24.668217'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1184,4,'국회 6·3 지방선거 투표용지 부족 사태 국정조사특위 위원장인 윤상현 국민의힘 의원은 5일 서울 올림픽공원 핸드볼경기장에 보관 중인 247만 장의 투표용지에 대해 공개 재검표를 추진하겠다고 밝혔다. 이는 지난 6·3 지방선거에서 투표용지 부족 사태 발생 후, 선관위의 투·개표 과정에 대한 신뢰 회복을 위해 마련된 조치로, 선관위가 투표지 보관 비용(7월 10일까지 약 2억 원)을 지속 지출하는 것보다 한 번의 재검표로 명분을 확보하자는 취지다. 윤 의원은 재검표 비용을 약 5000만 원으로 예상하며, 여야 간사 간 협의를 통해 결론을 도출할 것으로 전망했고, 중앙선관위 기관 보고에서 강동완 사무총장 대행도 재검표에 긍정적 입장을 밝힌 바 있다. 오는 7일 예정된 중앙선관위·서울시선관위 현장 조사에서는 투표지 50% 인쇄 축소 결정 과정과 지휘·보고 체계 누락 문제를 집중적으로 조사할 계획이며, 관련 보고서의 기록 부족과 위임 전결 규정의 문제점도 검토된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:27:54'::timestamp,'2026-07-27 16:33:19.385858'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1185,5,'조국 전 대표는 5일 유튜브에서 ''무섭노''라고 발언한 아이돌 원이에 대해 일베식 표현과 영남 사투리의 차이를 구분해야 한다며 ''노'' 사용 방식을 분석한 글을 페이스북에 게시했다. 이는 최근 경남 거제 출신 아이돌의 발언이 ''일베 혐오 표현''이라는 비판과 ''자연스러운 사투리''라는 반박이 맞서는 논란 속에서 나온 것으로, 조 전 대표는 일베는 표준어 뒤에 기계적으로 ''노''를 붙이는 방식이라고 설명했다. 야권과 여권에서는 조 전 대표의 발언을 비판하며, 방언까지 일베로 낙인찍는 것에 대해 ''숨 막히는 감시 사회''라며 사상 검증의 위험성을 지적했고, 말의 맥락을 무시한 감별 행위가 부적절하다고 주장했다. 이후 정치권과 사회적 논의는 방언의 정체성과 표현의 자유, 그리고 정치적 낙인찍기의 경계에 대한 쟁점으로 확대되고 있으며, 이는 향후 언어 정체성과 사회적 논의의 주요 이슈로 남을 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:27:59'::timestamp,'2026-07-27 16:33:03.608644'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1186,9,'2024년 5월 29일 목동 야구장에서 열린 청룡기 고교 야구 대회에서 배재고 선수들이 광주제일고를 향해 ''가야지 가야지 스타벅스 가야지''라는 야유를 외쳐 논란이 발생했다. 이는 스타벅스의 ''5·18 탱크데이'' 마케팅 논란을 패러디한 것으로, 광주제일고 측의 항의와 제소로 인해 대한야구소프트볼협회는 배재고 야구팀에 6개월 출전 정지를 결정했다. 이에 대해 여권은 ''5·18 비하용납불가''를 외치며 일벌백계를 요구했고, 야당은 선수들의 선수 생애에 미치는 영향을 이유로 징계의 과도함을 지적하며 재고를 촉구했다. 현재 배재고 선수들은 광주제일고에 사과하고 5·18 민주묘지에 참배하는 방식으로 책임을 지려 하고 있으며, 여권 내부에서는 ''5·18 성역화'' 발언으로 인한 갈등이 지속되고 있어 교육적 접근과 정치적 과잉 반응의 균형이 필요하다는 지적이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:10'::timestamp,'2026-07-27 16:26:24.259865'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1187,11,'김정은 북한 국무위원장은 7월 3일 5000t급 구축함 ''강건호''의 주요 무기체계 시험을 참관하고, 2개월 내 취역을 지시했다. 강건호는 지난해 진수식 당시 김 위원장 앞에서 좌초한 바 있어, 이번 시험은 해상 전력 강화를 위한 전략적 의지의 표출로 평가된다. 시험에서는 전략 순항미사일, 함상포, 전자전 장비 등이 발사 및 검증되었으며, 해안가에서 관측된 미사일은 동해상으로 발사된 것으로 확인됐다. 북한은 해군 중심의 함대 기지 확충과 조선소 능력 강화를 추진하며, ''강건호''의 실전 배치가 1년여 만에 이뤄질 것으로 보이며, 이는 해상 전력의 전환점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:14'::timestamp,'2026-07-27 16:29:29.685379'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1188,12,'더불어민주당 한병도 대표 직무대행은 5일 이번 주 내 선관위 특검법을 제출할 예정이라고 밝혔다. 이번 조치는 선거일 투표용지 부족 사태로 인한 국민 참정권 침해라는 헌정사상 초유의 사태를 계기로, 투표용지 인쇄 물량 축소, 지휘부 보고 누락 및 지연, 선관위 내부 부패와 무능까지 포함한 전방위적 수사 필요성을 강조한 것이다. 특검 추천권에 대해 국민의힘은 여당 배제를 주장했으나, 한 대행은 통상 여야와 제3자 추천을 거쳐 대통령이 임명하는 방식을 지지하며, 대한변협 등 제3자 추천이 선관위의 독립성과 중립성을 고려해 더 공정하다고 설명했다. 이후 특검법 제출과 추천 절차에 대한 여야 간 논의가 예상되며, 정치적 활용 여부와 특검의 독립성 확보가 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:18'::timestamp,'2026-07-27 16:29:47.468495'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1189,13,'2024년 8월 1일 이재명 대통령이 문재인 전 대통령을 청와대로 초청해 오찬을 함께하며 공개적인 회동을 진행했다. 이는 2018년 9월 평양 정상회담 당시 이재명 경기지사가 방북 특별수행원 명단에서 제외된 이후 친문 진영과의 갈등이 심화된 데 따른 것으로, 당시 문 전 대통령 측은 이 지사에 대한 거부감이 있었으며, 특히 2017년 대선 경선 과정에서 문 후보 아들 취업 논란을 지적한 것이 계기가 됐다. 이재명 대통령은 북한 문제에 적극적인 정책을 추진해왔으나, 평양 방문 배제로 인해 정책적 실망을 겪었고, 이후 아태평화교류협회와의 협력 과정에서 쌍방울 대북 송금 사건과 관련해 법적 논란이 지속되고 있다. 현재 민주당 내부에서는 친문과 친명의 갈등이 심화된 상태로, 이재명-문재인 회동이 통합의 신호인지, 연출인지에 대한 평가가 엇갈리며, 8월 전당대회를 앞두고 당내 통합의 진전 여부가 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:27'::timestamp,'2026-07-27 16:26:41.610826'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1190,15,'광주와 전남 지역에 조성될 예정인 반도체 팹 공장의 수자원 확보가 핵심 과제로 부상하고 있다. 영산강 승촌보와 월산보의 수질은 COD 11.7, TOC 9.6으로 ''매우 나쁨'' 수준이며, 반도체 공정에 필요한 초순수 기준에 부적합한 것으로 확인됐다. 정부는 장흥댐, 나주댐, 주암댐 등에서 하루 65만t의 용수를 확보할 계획이지만, 기존 댐의 저수량은 반도체 공장 수요에 미치지 못하고, 섬진강 수계 물을 활용할 경우 여수 산업단지의 용수 부족 우려도 제기된다. 현재 광주 지역의 고도정수처리 시설은 제한적이고, 반도체 산업용 수질 정화를 위한 대규모 수리시설 확충이 필요하며, 과거 4대강 사업 당시 발생한 정치적 반대와 재자연화 논의가 재현될 가능성도 있어 향후 절차와 지역 협의가 중요할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:34'::timestamp,'2026-07-27 16:26:25.766314'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1191,102,'롯데건설이 서울 성동구 성수동2가 219-4번지 일대에서 진행되는 성수4지구 재개발 사업의 시공권을 확보했다. 이 사업은 총 공사비 1조3628억원, 지하 6층에서 지상 최고 64층, 1439가구 규모로, ''성수 르엘 S70''으로 재탄생할 예정이다. 총회에서 롯데건설은 조합원 753명 중 451표를 얻어 대우건설(166표)을 제치며 시공사로 선정됐으며, 조합원 전원의 한강 조망과 9162평 규모의 공원형 조경, 중앙광장 등 조건을 제시했다. 이후 롯데건설은 제안 내용을 계약서에 반영해 즉시 계약 체결을 추진하며, 하이엔드 초고층 시공 경험을 바탕으로 조합원 자산가치 제고를 목표로 하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:38'::timestamp,'2026-07-27 16:34:31.148927'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1192,103,'금융위원회가 2028년부터 연결 자산 총액 10조원 이상 코스피 상장사 107곳을 대상으로 기후변화가 매출·생산 시설·공급망에 미치는 영향과 탄소 배출량·감축 목표를 사업보고서에 의무적으로 공시하도록 하는 방침을 추진 중이다. 이는 유럽연합(EU) 및 일본 등 해외 추세에 부합하려는 것으로, 기업의 지속 가능성 대응을 투자자 판단에 반영하기 위한 목적이다. 하지만 기업들은 추정치가 많은 미래 전망 정보를 법적 구속력 있는 공시 대상으로 삼을 경우 허위·누락 공시 논란과 형사 책임 위험에 직면할 수 있다고 우려하며, 초기에는 한국거래소에 공시하는 방식으로 유예 기간을 두고 점진적으로 법정 공시로 전환할 것을 요구하고 있다. 이후 2030년에는 자산 2조원 이상 기업까지 대상이 확대되며, 협력사의 공정, 임직원 출퇴근, 소비자 사용·폐기 과정 등 기업 밖에서 발생한 탄소까지 포함될 가능성이 있어, 데이터 수집 및 정확도 문제와 함께 제3자 인증 기준의 불명확성, 컨설팅 업체 수익 증가 우려도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:45'::timestamp,'2026-07-27 16:34:09.630576'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1193,104,'삼성전자 DX 부문 직원들이 반도체(DS) 부문과의 성과급 격차를 비판하며 ''We Deserve It''이라는 영상 제작 및 공유로 내부 갈등이 확산됐다. DS 부문은 2024년 메모리 사업부 평균 5억5000만원의 특별경영성과급을 받은 반면, DX 부문은 1인당 600만원 상당의 자사주(공지일 기준 약 756만5100원)를 지급받으며 불만이 커졌다. 이에 따라 DX 부문 임직원 약 5만2000명 중 절반 이상이 영상에 공감하며 공유했고, DS와 DX 간 직원 간 갈등이 댓글 싸움으로까지 확대되고 있다. 삼성전자는 성과급 협상이 이미 마무리된 상태지만, 내부 불만이 지속되며 조직 간 균형과 공정성에 대한 조치가 시급한 상황이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:49'::timestamp,'2026-07-27 16:33:27.024734'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1194,106,'정부는 반도체 호황으로 인한 초과 세수를 미래 세대를 위한 투자 재원으로 활용하기 위해 ''미래대응기금'' 신설을 공식화했다. 이는 국가재정법상 초과 세수를 지방교부세 상환, 공적자금 상환, 국채 상환 순으로 사용해야 하는 규정을 넘어서는 방식으로, 1~5월 국세수입이 전년 대비 16% 증가한 199조9000억원으로, 연말까지 유지될 경우 약 434조원에 달할 전망이다. 미국의 50개 주는 평균 266조원 규모의 불황대비기금을 운영하며, 기금 사용 시 주지사의 비상사태 선포와 주 의회 동의를 필요로 하는 등 엄격한 요건을 두고 있다. 향후 미래대응기금 운영을 위해 국가재정법 개정이 필요하며, 사용 요건과 의회 동의 절차 등 제도 설계가 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:55'::timestamp,'2026-07-27 16:33:59.666813'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1195,107,'한성숙 국무총리는 5일 서울 삼청동 총리공관에서 열린 고위당정협의회에서 반도체·인공지능(AI) 데이터 센터·피지컬AI를 결합한 3대 메가 프로젝트를 속도감 있게 추진하면 대한민국의 새로운 성장 시대를 열 수 있다고 밝혔다. 이 프로젝트는 정보화 분야에서 세계 최고의 경쟁력을 갖춘 한국의 산업화와 정보화 성공 경험을 기반으로, 인공지능 시대 선도를 위한 국가 차원의 전략적 과제로 평가된다. 정부는 이 프로젝트를 통해 향후 3년간 국가 경쟁력을 강화하고, 민생 경제 회복을 위한 법안의 조속한 국회 통과를 요청하며 당·정·청 및 민간의 협력을 강조했다. 이후 3대 메가 프로젝트의 구체적 실행 계획과 관련 법안의 처리 속도, 그리고 민간 투자 유치 여부가 주요 후속 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:28:59'::timestamp,'2026-07-27 16:33:44.392893'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1196,117,'전남 신안 지도 인근 해역에서 잡은 자연산 민어를 한입 크기로 손질해 부레, 뱃살, 몸통살, 꼬릿살 등 모든 부위를 포함한 민어회를 3만원대 초특가로 공동구매한 것이 핵심 사건이다. 민어는 7월 초부터 9월 말까지가 제철이며, 신안 지도 해역의 풍부한 플랑크톤과 조류로 인해 살이 단단하고 풍미가 뛰어나 고급 횟감으로 평가된다. 제품은 약 300g으로 성인 2~3인이 먹기에 적당하며, 4중 포장과 통얼음 사용으로 한여름에도 신선도를 유지해 배송 후 바로 섭취 가능하다. 이후에는 신선도 유지와 보관 방법에 대한 소비자 반응이 주목되며, 냉동 보관은 피하고 수령 당일 또는 하루 냉장 보관을 권장하는 점이 후속 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:05'::timestamp,'2026-07-27 16:32:43.138295'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1197,2288,'더불어민주당 전당대회준비위원회는 당대표 선거에서 결선투표제를 폐지하고 선호투표제를 도입하기로 결정했다. 선호투표제는 1순위부터 후보를 순위로 표시해 과반 득표자가 없을 경우 최하위 후보를 제외하고 2순위로 표시한 후보의 득표수를 합산해 당선자를 결정하는 방식으로, 별도 결선투표 없이 당일 결과를 도출할 수 있다. 이번 전당대회에서는 청년최고위원제 도입을 결정했으나, 연령 기준(기존 45세 이하에서 39세 이하로 조정 제안), 쿼터 운영 방식, 지명직과의 연계 여부 등은 추가 논의를 거쳐 확정할 예정이다. 전당대회는 3주간 주말 순회경선 방식으로 진행되며, 대의원과 권리당원의 표 비중은 1대 1로 반영되며, 전략지역 가중치 부여 방식과 관련해 영남권 5개 광역시·도와 강원도 등이 대상 논의 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:10'::timestamp,'2026-07-27 17:40:10.735976'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1198,2291,'더불어민주당은 8월 17일 전당대회 이전까지 검찰 보완수사권 폐지를 골자로 한 형사소송법 개정안을 처리하기 위해 법사위 소위 논의를 이번 주부터 시작할 예정이다. 보완수사권 폐지 논의는 이미 당과 정부의 공식 입장으로 정리되었으며, 중대범죄수사청(중수청)과 공소청의 10월 2일 출범을 고려해 6개월 전인 4월 말까지 입법 완료가 필요하다는 배경이 있다. 폐지 이후 수사권 공백을 보완수사요구권의 실질화와 경찰 보완수사 시기의 명확화, 인권보호국 설치, 경찰 수사심의위원회 실질화 등 제도적 보완을 통해 최소화할 계획이다. 이후 보완수사권 폐지 법안은 전당대회 전 처리를 목표로 하되, 10월 2일 공소청 출범까지 입법 절차를 완료하는 것이 최우선 과제로 설정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:15'::timestamp,'2026-07-27 17:33:52.746639'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1199,2294,'이재명 대통령은 7일 캐나다의 차세대 잠수함 도입 사업에서 한국 업체가 아닌 독일의 TKMS가 우선협상 대상자로 선정된 데 대해 ''도전을 멈추지 않겠다''고 밝혔다. 캐나다 정부는 6일(현지 시각) 노바스코샤주 해군 기지에서 TKMS를 우선협상 대상자로 선정했으며, 한화오션과 TKMS 모두 캐나다 해군의 요구 조건을 충족했지만, NATO 동맹 관계가 영향을 미쳤다는 분석이 나왔다. 이번 수주 실패로 한국의 잠수함 기술력은 국제적으로 인정받았으나, 정치적·군사적 동맹 구조가 수주에 영향을 미친 것으로 평가되며, 정부는 연구 개발, 수출 지원, 국제 협력 강화를 통해 다음 도전을 준비하고 있다. 강훈식 대통령 비서실장은 이번 실패가 기회의 전환점이 될 것이라며, 폴란드의 K-2 전차 수주 사례처럼 장기적 성과로 이어질 수 있음을 강조하며, 향후 국제 시장에서의 경쟁력을 높이기 위한 정책적 노력을 지속할 계획이라고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:20'::timestamp,'2026-07-27 17:27:49.148484'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1200,118,'강훈식 대통령비서실장은 5일 고위당정협의회에서 반도체 호황으로 발생한 추가 세수를 활용해 ''미래대응기금''을 신설할 계획을 발표했다. 이는 반도체 산업의 성장으로 인한 세수 증가가 장기적 국가 발전과 청년 문제 해결을 위한 투자 재원으로 활용되려는 목적에서 비롯된 것으로, 3대 메가 프로젝트 지원, K자형 양극화 완화, 2030 청년 주거·창업·일자리 지원 등이 포함된다. 기금은 2024년 내 정부안 마련을 목표로 하며, 당정 협의를 통해 법제화 절차를 진행할 예정이다. 이후 기금 운영 방안과 예산 배분 기준에 대한 논의가 본격화될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:24'::timestamp,'2026-07-27 16:32:41.264947'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1201,123,'6일부터 서울 외환시장은 원화와 달러를 주중 24시간 거래할 수 있게 됐다. 기존에는 평일 오전 9시부터 다음 날 새벽 2시까지 거래하고 7시간 휴장했으며, 공휴일도 주말이 아니면 거래 중단됐다. 이제는 월요일 오전 6시부터 토요일 오전 6시까지 연중무휴로 운영되며, 특히 평일 오전 2~9시의 환율 공백이 해소된다. 이로 인해 외국인 투자자들의 환전 편의성이 높아지고, 장기적으로 원화 환율 하락 요인으로 작용할 수 있다는 전망이 제기된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:27'::timestamp,'2026-07-27 16:30:40.069442'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1202,130,'올해 상반기 국내 주식 시장에서 주가 상승률 1위는 AI 서버용 적층세라믹캐패시터(MLCC)를 생산하는 삼성전기로, 1~6월 주가 상승률이 756.4%를 기록했다. 삼성전기는 1월 초 27만원대에서 6월 말 218만4000원으로 상승하며 시가총액은 20조1672억원에서 163조1310억원으로 증가했고, 시가총액 순위도 33위에서 5위로 상승했다. 이는 삼성전자(178.6%)와 SK하이닉스(307.1%)를 크게 상회하며, MLCC 수요 증가와 1조6000억원 규모의 실리콘 커패시터 및 4500억원 규모의 MLCC 공급 계약 체결이 주요 원인으로 분석된다. 주가 상승률 2위는 MLCC 생산 기업인 삼화콘덴서(416.24%)가 차지했으며, 코스닥에서는 반도체 장비 기업 주성엔지니어링(625.6%)이 1위를 기록했고, 향후 MLCC 수요 전망과 반도체 산업의 지속적 성장 여부가 주가 동향에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:33'::timestamp,'2026-07-27 16:32:05.911253'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1203,132,'올해 상반기 농식품 및 농기자재 등 농산업 관련 수출액은 70억5000만달러로 사상 최대치를 기록했다. 이는 작년 동기 대비 4.1% 증가한 수치로, 농식품 분야 수출은 53억8000만달러로 5% 증가했으며, 중동(25.2%)과 중남미(19.5%) 지역에서 증가율이 높았다. 주요 품목 중 라면 수출액은 9억4000만달러로 27.9% 증가했고, 미국 시장에서의 수출은 10억4000만달러로 11.3% 증가했다. 하반기 농림부는 해외 인·허가 지원과 현지 마케팅 확대를 통해 수출 회복을 추진할 계획이며, 농약 수출은 중동 정세 불안으로 인해 4.1% 감소했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:38'::timestamp,'2026-07-27 16:31:58.042985'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1204,147,'김용범 청와대 정책실장은 5일 페이스북에 게시한 ''AI 생산혁명론''에서 인공지능이 기술혁명이 아닌 생산혁명이라고 강조하며, 국가의 역할은 AI 기반 생산 인프라 구축과 분배 체계 마련이라고 밝혔다. 그는 AI가 연구개발, 소프트웨어 개발, 물류 최적화 등에서 실패 비용을 줄이고 자본의 제약을 완화해 생산 효율을 극대화한다고 설명하며, 향후 핵심은 AI의 설계보다는 생산·운영 능력이라고 지적했다. 김 실장은 국가의 역할을 전력망 조성, 산업부지 개발, 공급망 조직 등 인프라 구축과 교육을 통한 생산능력 재생산, 초과이윤을 다음 세대의 생산력으로 투자하는 분배 체계 마련으로 규정했다. 이후 정부는 AI 기반 생산혁명 시대에 맞춰 산업정책을 시장 조절에서 국가 전체를 하나의 생산 플랫폼으로 조직하는 방향으로 전환할 예정이며, 교육, 이민, 창업 정책도 생산능력 확대를 위한 제도로 재정립될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:43'::timestamp,'2026-07-27 16:30:49.848837'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1205,2305,'이재명 대통령과 도널드 트럼프 미 대통령이 7~8일 튀르키예 앙카라에서 열리는 나토 정상회의에 참석한다. 최근 한미 간 쿠팡 문제로 갈등이 발생하며, 미측은 한국 정부가 미국 기업을 차별했다고 주장하고, 이에 따라 한미 조인트 팩트시트 안보 분야 후속 협의 일정이 6일까지 확정되지 않은 상태다. 이재명 대통령은 취임 후 첫 나토 정상회의 참석을 계기로 한미 안보 협력과 쿠팡 문제 해결을 논의할 예정이며, 외교부는 개인정보 유출 수사가 법과 원칙에 따라 진행되고 있다고 반박했다. 이후 한미 간 2차 안보 협의 일정 확정 여부와 쿠팡 문제 해결이 원자력 추진 잠수함 도입 및 우라늄 농축·재처리 권한 확보 등 안보 협의 후속 진전에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:47'::timestamp,'2026-07-27 16:56:50.158799'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1206,2307,'2024년 7월 7일, 더불어민주당 주도로 개정된 정보통신망법이 시행되며, 국민의힘은 이 법이 표현의 자유를 침해하는 ''입틀막법''이라며 총공세에 나섰다. 이 법은 온라인상에서 허위·조작 정보를 악의적·반복적으로 유포할 경우 손해액의 최대 5배 배상 및 최대 10억원 과징금을 부과하는 내용을 담고 있으며, 야당과 시민단체는 표현의 자유 침해를 우려해 반대했지만 민주당은 다수석으로 강행 처리했다. 국민의힘은 법의 시행을 유예하고 독소 조항을 삭제하는 재개정을 요구하며, 민주당은 법이 악의적 가짜뉴스와 혐오 표현에만 적용되는 ''핀셋 규제''라며 반박했다. 이후 법의 시행 여부와 표현의 자유 보장 여부에 대한 논쟁이 지속될 전망이며, 향후 법적·정치적 쟁점이 확대될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:52'::timestamp,'2026-07-27 16:57:02.178745'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1207,151,'신한금융그룹은 2026년 하반기 경영 포럼을 3~4일 경기 용인 신한은행 블루캠퍼스에서 개최하고, ''생동하는 신한, 압도적 몰입''을 슬로건으로 인공지능 전환(AX)과 시장 지위 강화를 위한 전략을 논의했다. 포럼에서는 2030년 신한금융이 시장에서 사라진 상황을 가정한 영상 시청과 외부 시각 점검, 시행착오 반성 세션, AX 정밀 진단 등이 진행되었으며, 그룹이 자체 개발한 AI 에이전트가 경영진 토론에서 레드팀 역할을 수행하며 실시간 분석과 반론 제시를 통해 의사 결정을 지원했다. 진옥동 회장은 ''야성''을 강조하며 차별화된 상품·서비스 개발과 몰입·팀워크 기반의 도전적 목표 설정의 필요성을 언급했고, 포럼에는 그룹 경영진 300여 명과 자회사 비상임이사, 실무자로 구성된 워킹그룹이 참여했다. 이후 신한금융은 AI 기반 전략 수립과 조직 문화 혁신을 위한 후속 절차를 진행할 예정이며, AX 전환의 성과는 2027년 중반까지 평가될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:29:57'::timestamp,'2026-07-27 16:30:19.727701'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1208,154,'금융위원회는 6일부터 만 19~34세 청년을 대상으로 상시 재무상담 서비스를 시행한다. 이 서비스는 청년미래적금 가입자에게 우대금리 0.2%포인트를 제공하기 위해 마련되었으며, 상담 완료 후 자동 적용된다. 신청은 전용 홈페이지에서 인증 후 온라인 재무진단을 거친 뒤, 찾아가는, 금융기관 방문, 온라인 세 가지 방식 중 선택 가능하며, 상담 완료 후 만기 3개월 전 말일까지 적금 가입 시 우대금리가 소급 적용된다. 이후 청년미래적금 가입자 중 상담 미이행자는 우대금리 혜택을 받지 못하며, 상담 절차의 효율성과 접근성 확대가 향후 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:01'::timestamp,'2026-07-27 16:30:02.116206'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1209,160,'5월 전업카드사 평균 카드론 금리는 13.54%로 전월 대비 0.03%p 하락했으나, 신용점수 700점 이하 저신용자 금리는 평균 0.09%p 하락한 반면 900점 초과 고신용자 금리는 0.47%p 상승했다. 이는 정부의 포용금융 정책과 중금리대출 공급 확대를 위한 총량 예외 인센티브 적용이 중저신용자 대상 금리 하락을 유도한 것으로 분석된다. 자금조달 비용은 금융채Ⅱ 3년물 금리가 1월 3.3%에서 5월 4.2%로 상승하며 증가했으나, 저신용자 금리 하락은 리스크 관리와 정책 유도의 결과로 보인다. 금융당국은 가계대출 증가세를 1.5% 이내로 관리하고 있으며, 카드사들은 일일·주간·월간 보고 체계를 통해 감독을 받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:06'::timestamp,'2026-07-27 16:29:56.597129'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1210,174,'신동빈 롯데그룹 회장은 3일 인천 송도에 위치한 롯데바이오로직스 1공장을 방문해 주요 시설을 점검하고 글로벌 위탁개발생산(CDMO) 사업 준비 상황을 점검했다. 이는 송도 1공장이 착공 약 2년 만에 건설을 완료하고 사용 승인을 획득한 직후로, 미국 시러큐스 공장과의 ''듀얼 사이트'' 전략을 통해 대규모 상업 생산을 준비 중이다. 회사는 하반기 시운전과 시스템 검증을 진행하고 연내 GMP 인증을 완료해 내년부터 본격적인 상업 생산에 들어갈 계획이며, 기존 계획보다 약 6개월 앞당긴 일정으로 추진 중이다. 신 회장은 바이오 사업을 그룹의 새로운 도약 핵심으로 강조하며, 현장 경영을 지속하고 있으며, 향후 글로벌 CDMO 경쟁력 강화를 위한 전략적 투자가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:10'::timestamp,'2026-07-27 16:28:57.232832'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1211,177,'금융당국이 단일종목 레버리지 ETF의 괴리율 확대 사고를 막기 위해 유동성공급자(LP) 관리 강화 방안을 검토 중이다. 이는 지난달 초 한국투자신탁운용의 ''ACE SK하이닉스단일종목레버리지'' ETF가 기초자산인 SK하이닉스 주가가 8% 하락한 상황에서 시장가격이 약 50% 급등하며 괴리율이 확대된 사례를 계기로 한 조치다. 지난달 단일종목 레버리지 ETF의 괴리율 초과 공시는 총 57건에 달했으며, 괴리율은 ETF의 시장가격과 순자산가치(NAV) 간 차이를 나타내는 지표로, 높은 수준에서는 투자자 손실 위험이 증가한다. 금융당국은 LP 평가 기준 강화나 사고 발생 운용사에 대한 ETF 심사 불이익 부과 방안을 검토하며, 향후 제도 개선 절차를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:15'::timestamp,'2026-07-27 16:28:33.271320'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1212,2286,'민주당은 이번 주 내 형사소송법 개정안을 발의해 검찰의 보완수사권을 완전 폐지할 계획을 밝혔다. 이는 검찰청 폐지와 공소청, 중대범죄수사청 신설을 골자로 한 검찰개혁의 일환으로, 수사와 기소의 분리를 목표로 한다. 그러나 당내에서는 경찰 부실수사와 피해자 보호 공백을 우려하며 보완수사권 폐지 이후의 견제 장치와 예외 규정 마련이 필요하다는 신중론이 제기되고 있다. 특히 광주 여고생 살해 사건에서 경찰 수사의 한계와 검찰 보완수사의 중요성이 부각되며, 보완수사권 존폐 논의는 예외 규정과 검사의 보완수사 요구권 유지 여부를 포함한 제도적 설계로 확대될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:20'::timestamp,'2026-07-27 17:44:47.074503'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1213,2287,'정청래 전 더불어민주당 대표는 8·17 전당대회를 앞두고 김민석 전 국무총리가 당대표 출마를 선언하며 ''자기 정치''를 비판한 것에 대해, 현직 총리로서 TPO에 맞지 않게 당대표 로망을 발언해 평지풍파를 일으켰다고 반박했다. 김 전 총리가 전날 당권 주자로 출마를 선언하며 ''자기 정치''의 폐해를 지적한 지 하루 만에 정 전 대표는 페이스북을 통해 자신은 당대표 재임 중에 당직 인선에서 탕평책을 썼고, 이재명 대통령의 정책 기조에 부합해 단독 인터뷰를 하지 않았으며, 1인 1표제를 통해 권력 내려놓기를 실천했다고 강조했다. 그는 조국혁신당과의 합당 추진도 자기 정치가 아니라 공적인 가치 실현이라고 주장하며, 당정청 협력으로 검찰개혁, 사법개혁, 정보통신망법 시행 등 입법 성과를 이뤘다고 밝혔다. 정 전 대표는 자기 정치라는 개념의 모호성과 이를 상대방 공격 도구로 삼는 것의 부정확성을 지적하며, 앞으로 주제별로 인포그래픽을 활용한 글을 자주 쓸 것이라고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:26'::timestamp,'2026-07-27 17:44:19.236943'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1214,2296,'한병도 더불어민주당 당대표 직무대행은 6·3 지방선거에서 올림픽공원 핸드볼 경기장에 보관된 247만 장의 투표용지에 대해 재검표 및 수개표를 여야 협의를 통해 국정조사 특별위원회에서 추진할 방안을 적극 검토하겠다고 7일 밝혔다. 이는 투표용지 인쇄 물량 축소와 선거 당일 지휘 체계의 문제로 인한 투표지 부족 사태에 따른 것으로, 선관위 대상 2차 현장조사가 예정된 가운데 사태의 실체와 책임 소재를 규명하기 위한 조치다. 현재까지 국회의장실에 제출된 법안 중 국민의힘 반대로 본회의를 통과하지 못한 법안은 59건에 달하며, 민생법안 처리를 위한 본회의 개최를 9일 예정하고 있다. 한 원내대표는 국민의힘의 상임위 보이콧을 비판하며 일할 것을 촉구하며, 특검법의 제3자 추천 방식을 제안했으나 야당이 단독 추천을 고집하고 있어 정치적 논란이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:31'::timestamp,'2026-07-27 17:30:22.757312'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1215,2297,'중앙선거관리위원회는 7일 국회 국정조사특별위원회에 보고하며, 서울 올림픽공원 핸드볼경기장에 보관 중인 247만표에 대한 공개 재검표를 검토하겠다고 밝혔다. 이는 6·3 지방선거 투표용지 부족 사태로 인한 국민 참정권 침해 논란과 함께, 윤상현 국민의힘 의원이 주도한 국조특위의 요구에 따른 조치다. 재검표는 현행 법규상 선관위 직권으로는 불가능하나, 국조특위 의결을 거쳐 검증 형식으로 진행할 수 있으며, 비용 약 5000만원은 선관위가 부담한다. 재검표는 육안 확인, 정당별 분류, 심사 계수기 매수 확인 등을 거쳐 9시간 소요되며, 여야 위원과 정당·후보자 추천 참관인, 언론 등이 과정을 공개 관찰할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:35'::timestamp,'2026-07-27 17:30:38.834316'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1216,2302,'김민석 전 국무총리는 7일 더불어민주당 당대표 선거 출마 직후 친청계 의원들이 제기한 ''계엄 해제 표결 불참'' 의혹에 대해 ''대장동 때를 보는 듯하다''며 허위사실 유포에 책임을 지라고 반박했다. 이성윤 최고위원 등 친청계 의원들은 김 전 총리가 계엄 해제 표결 당시 감기약을 먹고 잠을 잔 것처럼 말하며 불참 이유를 의심했고, 표결 직전 민주당 의원과 통화했다는 점을 근거로 지적했다. 김 전 총리는 표결 시점에 국회에 있었으며, 직후 본회의장에 착석했고, 이 과정을 여러 차례 설명했다며 허위사실 유포로 명예훼손을 주장했다. 현재 친청계와 친명계 의원들 간 진영 대립이 심화되며, 당대표 선거 전후 정치적 논란이 확산되고 있으며, 향후 정당 내부 갈등과 선거 전략에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:40'::timestamp,'2026-07-27 17:27:15.962590'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1217,2303,'이재명 대통령은 7일 나토 정상회의 참석을 위해 서울공항에서 출국했으며, 취임 후 첫 나토 정상회의 참석이다. 이번 일정은 마르크 뤼터 나토 사무총장의 초청으로 진행되며, 3박 5일간 튀르키예 앙카라에서 일본, 호주, 뉴질랜드 등 인도·태평양 파트너국(IP4)과의 소인수회담과 나토 방위산업포럼 기조발언을 예정하고 있다. 이 대통령은 8일까지 튀르키예에 머무르며 도널드 트럼프 미국 대통령의 현지 방문과 대면 가능성에 관심이 집중되고 있으며, 이후 몽골로 국빈방문을 이어갈 예정이다. 이번 순방은 대한민국이 국제사회의 평화와 안보에 책임 있게 기여하는 국가로 전환된 것을 보여주는 계기가 될 것으로 기대된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:44'::timestamp,'2026-07-27 17:26:32.315487'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1218,2304,'2024년 6월 7일, 캐나다 차세대 잠수함 도입 사업(CPSP)에서 한화오션과 HD현대중공업으로 구성된 한국 컨소시엄이 독일 티센크루프마린시스템스(TKMS)에 밀려 수주 탈락했다. 캐나다 정부는 기술력과 납기, 작전 지속성 등에서 TKMS를 우선 협상 대상자로 선정했으며, 한국 측은 도산안창호함이 태평양 횡단 항해를 통해 장거리 운항 능력을 입증한 점을 강조했다. 방위사업청은 이번 결과를 아쉬운 실패로 보지 않고 방산 4강 도약을 위한 교훈으로 삼겠다며, 향후 대형 방산 수출 전략과 범정부 지원 강화를 추진할 계획이다. 이에 따라 한국은 잠수함 기술의 국제 경쟁력과 외교적 협력 가능성에 대한 평가를 바탕으로 향후 수출 전략을 재정비할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:48'::timestamp,'2026-07-27 17:23:02.419848'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1219,2309,'김민석 전 국무총리는 2024년 6월 6일 더불어민주당 전당대회 최고위원 출마를 선언하며 정청래 전 대표를 겨냥해 ''자기 정치''의 폐해를 지적했다. 그는 정 전 대표 시절의 조국혁신당 합당 실패, 검찰 개혁 논란, 6·3 지방선거 공천 문제 등을 들어 당내 협력과 절차의 부족을 비판했으며, 전일빌딩245에서 출마 기자회견을 열었다. 이번 전당대회는 대의원과 권리당원 1인 1표제가 처음 적용되며, 호남 지역 표심이 결정적 영향을 미칠 전망이다. 친청계는 김 전 총리의 과거 탈당과 계엄 당시 국회 표결 불참 문제를 거론하며 반박하고 있으며, 송영길 의원도 조만간 출마를 예고하며 2030 세대 지지 확보를 핵심 전략으로 내세우고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:53'::timestamp,'2026-07-27 16:57:16.860783'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1220,2311,'이병태 대통령 직속 규제합리화위원회 부위원장이 5·18 민주화 운동을 ''성역''이라며 비판한 발언으로 인해 청와대의 사퇴 권고를 받고 6일 자진 사퇴했다. 이 부위원장은 지난 2일 페이스북에서 배재고 야구부의 5·18 조롱 행위를 비판하며 ''5·18이 성역이 됐다''고 주장했으며, 이후 ''김일성 만세'' 외치는 것도 허용돼야 한다는 등의 발언을 반복해 논란을 키웠다. 청와대는 이 부위원장의 발언이 정부 국정 기조와 부합하지 않으며, 사안이 매우 엄중하다며 사퇴를 권고했고, 이 부위원장은 고심 끝에 사퇴 의사를 밝혔다. 이 사태는 8월 전당대회를 앞두고 민주당 내 중도·보수 성향 인사에 대한 지지층 반발을 우려한 정치적 배경이 있으며, 이재명 정부의 ''외연 확장'' 정책과 당내 균형 문제를 반영한 것으로 분석된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:30:59'::timestamp,'2026-07-27 16:57:26.787136'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1221,2312,'이재명 대통령은 6일 청와대에서 열린 ''3대 메가 프로젝트'' 민관합동 점검회의에서 호남 반도체 클러스터 조성을 위한 전력과 용수 인프라 확보를 선제적으로 추진해야 한다고 강조했다. 반도체 산업의 안정적 가동을 위해 기저 전원 확보가 필요하다는 우려가 제기되며, 원전 신규 건설과 추가 댐 건설이 검토되고 있다. 삼성전자와 SK하이닉스 등 기업의 전력 수요는 약 30GW로, 이는 원전 20기 분량에 해당하며, 현재 한빛원전과 울주지역에 신규 원전 4기 건설 부지가 확보된 상태다. 정부는 원전 건설 절차 간소화와 가뭄 취약 지역인 호남의 공업용수 공급을 위해 추가 댐 건설도 검토 중이며, 주민 반발과 건설 기간 9~10년 등의 과제가 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:04'::timestamp,'2026-07-27 16:57:44.694668'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1222,2313,'정부는 삼성전자와 SK하이닉스의 협의를 거쳐 광주 군 공항 부지를 호남권 반도체 산단 조성지로 결정했다. 이 부지는 국유지로 토지 보상 문제 없이 820만㎡(약 250만평) 규모의 평탄화된 대지로, KTX 송정역과 직선거리 2km 이내에 위치해 인프라 접근성이 뛰어나며, 용수·전력 공급 조건과 인근 대학 기반의 전문 인력 양성 시스템도 갖췄다. 다만 군 공항은 무안국제공항으로 이전해야 하며, 무안군 주민 동의와 주민투표, 3대 조건(민간공항 선 이전, 1조원 지원, 인센티브 제공) 이행이 전제되어야 하며, 이전 기간은 2026년 내 부지 선정, 2030년대 초중반 완료 예상이다. 이후 미군 전시 증원 기지(COB) 이전도 무안군 반발 가능성으로 인해 추가 논의가 필요하며, 현재 탄약고 이전 사업은 반도체 산단 조성으로 인해 중단될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:11'::timestamp,'2026-07-27 16:58:06.953751'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1223,2314,'청와대는 6일 이재명 대통령 주재로 열린 메가 프로젝트 민관 합동 점검 회의에서 삼성전자와 SK하이닉스가 총 800조원을 투자해 광주 군 공항 부지에 반도체 팹 4기를 건설하기로 결정했다. 이는 호남권 반도체 클러스터 조성의 핵심 사업으로, 광주 군 공항 부지는 약 250만평 규모로 평탄화가 완료되어 공사 기간 단축이 가능하며, KTX역 및 도로·항만과의 연계성도 뛰어나 물류 접근성이 우수하다는 평가를 받았다. 그러나 군 공항 이전이 전제되어야 하며, 현재 무안공항 통합 이전 추진 중이나 무안군의 동의가 필요하며, 국방부는 이전 완료 시점을 2030년대 초중반으로 예상하고 있다. 정부는 안보 공백을 최소화하면서 군 공항 조기 이전 방안을 다각적으로 검토하고 있으며, 전력과 용수 등 인프라 구축 방안은 다음 회의에서 공개될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:16'::timestamp,'2026-07-27 16:59:07.098518'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1224,2319,'정부는 6일 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 삼성전자와 SK하이닉스가 800조원을 투자해 호남에 반도체 팹 4기를 건설하겠다는 계획을 발표한 데 따라, 기업들의 후보지 중 광주 군공항 부지가 가장 적합하다는 평가를 받았다. 광주 군공항 부지는 약 250만평 규모로 평탄화가 완료되어 공사 기간 단축이 가능하며, 도심과 KTX 역 인접, 도로·항만 등과의 물류 연계성이 뛰어나 인력 확보와 정주 여건도 우수하다는 평가를 받았다. 정부는 관계 부처 협의를 거쳐 후보지 선정 절차를 마무리하고 산단 개발 후속 절차에 착수할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:20'::timestamp,'2026-07-27 16:43:09.489188'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1225,2320,'이병태 규제합리화위원회 부위원장이 5·18 민주화운동을 ''성역''으로 보는 것에 대해 논란을 일으킨 데 이어, 청와대의 사퇴 권고에 따라 6일 자진 사퇴했다. 이 부위원장은 배재고 야구부의 ''스타벅스 응원가'' 논란을 계기로 ''5·18이 성역이 되는 것은 바람직하지 않다''는 발언을 하며 정치적 이념 대립을 유발했고, 이에 민주당을 비롯한 여권은 즉각 사퇴를 요구했다. 청와대는 4일 경고를 내렸으나 이 부위원장이 입장을 굽히지 않자 6일 사퇴 권고를 내리고, 이에 따라 사퇴가 결정됐다. 이후 이 부위원장은 사퇴 의사를 밝히며 자유로운 표현의 중요성을 강조했으나, 여전히 5·18을 성역으로 보는 것에 대한 비판적 입장을 유지하며 사회적 논의의 지속 가능성에 대한 쟁점이 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:25'::timestamp,'2026-07-27 16:48:06.056241'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1226,2321,'이재명 대통령은 6일 청와대에서 한성숙 신임 국무총리와 주례 보고 회동을 열고, AI 대전환, 규제 합리화, 창업 르네상스, 청년 정책 내실화를 총리 4대 역점 과제로 지정하고 전권을 부여해 국정 전반의 근본적 혁신을 이끌어달라고 주문했다. 이는 총리가 취임 후 처음으로 대통령과 정례적으로 진행하는 주례 보고 회동에서 이루어졌으며, 청와대 정책실장, 국가안보실장, 총리실 국무조정실장 등이 배석했다. 이 대통령은 한 총리의 IT 전문성과 민간 혁신 경험을 인정하며, AI·데이터 기반 국민 생명 보호 방안도 신속히 추진하라고 지시했고, 두 정상은 향후 주례 회동을 통해 국정 현안을 점검하고 협력해 나가기로 했다. 이후 총리실은 4대 과제에 대한 구체적 실행 계획 수립과 정부 내부 혁신 추진 절차를 진행할 예정이며, 특히 AI 기반 정책의 실질적 적용과 규제 개혁의 속도가 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:30'::timestamp,'2026-07-27 16:47:16.671697'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1227,2322,'더불어민주당 김민석 전 국무총리는 6일 전남 광주 동구에서 열린 기자회견을 통해 8·17 전당대회 당대표 선거 출마를 선언했다. 그는 지난 1년간 당정 협력의 혼선과 숙의 부족, 절차 미비 등을 이유로 정청래 전 대표 지도부의 책임을 지적하며, 이재명 정부 국정 성공과 총선 승리를 위해 당의 단합과 개혁이 필요하다고 강조했다. 김 전 총리는 당원 주권 강화, 보완수사권 폐지, 검찰·사법·언론 개혁, 공천 공정성 회복 등을 주요 공약으로 제시하며, 이재명 대표 시절의 민주적 운영 방식을 부활하겠다고 밝혔다. 현재 김민석은 당원 투표를 통한 당대표 선거 절차에 참여 중이며, 1인 1표 제도 하에서 압도적 지지를 얻어 리더십 교체를 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:35'::timestamp,'2026-07-27 16:42:23.175789'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1228,2348,'더불어민주당은 2024년 10월 검찰청 폐지와 중대범죄수사청 출범을 앞두고 형사소송법 개정을 통해 검찰의 보완수사권을 전면 폐지하는 입법을 추진 중이다. 이는 검찰 개혁의 핵심 과제로, 민주당은 법사위를 통해 법안을 쾌속 처리하려 하고 있으며, 당내 강경파는 7월 내 통과를 목표로 하고 있다. 그러나 법조계와 야권은 보완수사권 폐지로 인해 증거인멸 우려, 수사 공백, 경찰 권력 견제 약화 등의 부작용이 발생할 수 있다고 우려하고 있으며, 일부 의원은 조건부 보완수사권이나 경찰 수사심의위원회 상설화 등 대안을 제시하고 있다. 현재 민주당은 법안 처리 시기와 방식에 대해 내부 논의를 진행 중이며, 당권 주자들도 입장을 명확히 하며 입법 절차에 대한 반응이 분분한 상황이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:41'::timestamp,'2026-07-27 16:23:45.743943'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1229,2324,'안철수 국민의힘 의원은 6일 삼성전자·SK하이닉스 레버리지 ETF가 주가 변동성을 증폭시켜 코스피가 ''카지노''처럼 변했다며 상장폐지를 포함한 강력한 교정 조치 필요성을 주장했다. 이는 삼전닉스 레버리지 ETF에 212조원이 몰리며 코스피 시가총액의 60%를 차지하는 주요 종목에 레버리지가 적용되면서 일일 리밸런싱과 프로그램 매매로 시장이 불안정해졌기 때문이며, 올해 들어 사이드카 31회, 서킷 브레이커 5회가 발동된 바 있다. 현재 코스피 공포 지수는 90.8로 역대급 수준에 도달했고, 증시는 글로벌 시장에서 예측 불가능한 ''잡주''로 평가받을 위험에 처해 있다. 안 의원은 이재명 대통령에게 금융위원장과 금융감독원장의 책임을 묻고, 단일 종목 레버리지 금지 및 상관계수 0.7 이하 액티브 ETF 규제 완화를 제안하며, 당국의 대응 실패를 비판했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:46'::timestamp,'2026-07-27 16:42:41.891155'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1230,2326,'이재명 대통령은 6일 청와대에서 열린 3대 메가 프로젝트 민관 합동 점검 회의에서 호남에 삼성전자와 SK하이닉스가 800조원을 투자해 반도체 팹 4기를 건설하는 프로젝트의 속도전을 강조하며, 지역 차별과 실현 불가능성이라는 비판에 대해 ''협조는 못하더라도 방해는 하지 말라''고 당부했다. 이 프로젝트는 정부가 이 대통령 임기 내에 팹 4기를 완공하겠다는 목표를 세우고 있으며, 현재 부지 확보와 전력·용수 확보가 주요 과제로 지적되고 있다. 특히 토지 취득 과정에서 협의 절차가 지연되며 강제 수용 절차를 조기에 적용할 것을 제안했고, 전력과 용수 문제도 기다리지 않고 선제적으로 해결해야 한다고 강조했다. 이후 정부는 부지 확보와 인프라 확보 절차를 병행해 프로젝트 추진 속도를 높일 방침이며, 이는 임기 내 완공 목표 달성 여부에 직접적인 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:52'::timestamp,'2026-07-27 16:42:07.359750'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1231,2327,'국방부는 6일 오전 육·해·공군 사관학교 통합을 위한 ''국군사관학교 창설 기본계획''을 발표할 예정이었으나, 안규백 국방부 장관의 청와대 메가프로젝트 민관합동 점검회의 참석으로 브리핑을 2시간 전에 연기했다. 이는 나토 정상회의 참석을 앞두고 안 장관이 7∼8일 튀르키예 앙카라에서 열리는 회의에 대통령 수행을 위해 출국할 예정이기 때문이며, 나토는 한국을 포함한 IP4 국가 국방장관들을 별도 업무만찬에 초청했다. 국군사관학교는 1·2학년 공통 교육, 3·4학년 군별 특화 전공 교육을 통해 사관생도 통합 선발을 목표로 하고 있으며, 사관학교 입학 성적 하락과 인재 양성 규모 확대 필요성 등이 통합 추진 배경이다. 반면 야권과 사관학교 총동창회, 예비역 장성 등은 통합 쟁점에 대해 반발하며 8일 국회 앞에서 반대 궐기대회를 예정하고 있어, 국방부의 계획 추진 과정에 대한 신뢰성과 절차적 투명성에 대한 논란이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:31:58'::timestamp,'2026-07-27 16:41:49.407798'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1232,2332,'감사원은 6일 선거관리위원회에 대한 현장 감사를 착수하며, 투표용지 인쇄 예산 집행, 직원 해외 출장, 재외선거관 파견 등 12개 항목을 중심으로 감사를 진행한다. 이는 2022년 6·3지방선거 투표용지 부족 사태와 선관위의 수의계약 의혹, 외유성 출장 논란 등에 따른 국민의 의혹 해소를 목적으로 하며, 헌법재판소 결정으로 직무 감찰은 불가능하지만 회계 검사는 가능하다는 점에서 제한적 감사 범위 내에서 실시된다. 감사는 중앙선관위와 서울·경기·부산선관위, 송파구선관위 등에서 1차로 19일간 진행되며, 이후 2차 감사도 예정되어 있으며, 인력과 시간은 통상 감사보다 3~4배 투입된다. 감사 결과에 따라 감사 범위 확대나 추가 조사가 가능하며, 선관위의 수당 지급 적정성, 공무 외유성 출장 여비 집행, 재외선거관 경비 및 수당 지급, 과거 감사 지적 사항 이행 여부 등이 후속 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:04'::timestamp,'2026-07-27 16:41:26.894434'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1233,2335,'강훈식 대통령 비서실장은 5일 반도체 호황으로 예상되는 추가 세수를 활용해 ‘미래 대응 기금’을 신설하겠다고 밝혔다. 반도체 산업의 성장으로 내년까지 약 100조원 규모의 추가 세수가 발생할 것으로 전망되며, 이는 3대 메가 프로젝트(호남 반도체 등), 청년 세대 지원 등에 사용될 예정이다. 정부는 기금을 통해 미래 성장 동력 확충, K자형 양극화 완화, 2030 청년 주거·창업·일자리 지원 등에 투자할 계획이며, 더불어민주당도 이에 공감하고 당정 협력을 강화하겠다고 밝혔다. 다만 기금의 규모, 세부 운영 방안, 입법 절차 등은 아직 결정되지 않았으며, 향후 당정 협의를 통해 구체화될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:07'::timestamp,'2026-07-27 16:37:05.327523'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1234,2337,'정보통신망법 개정안이 7일 시행되며, 야당인 국민의힘은 이 법을 ''국민 입틀막법''이라며 법 개정을 추진하겠다고 밝혔다. 이 법은 인터넷상 허위·조작 정보 유포 시 손해액 최대 5배 배상 및 최대 10억원 과징금 부과를 규정하고, 하루 100만명 이상 이용하는 플랫폼에 정보 삭제·차단 의무를 부과한다. 시행 전까지 국회 청원 사이트에 14만2248명이 법 철회 촉구 청원에 동의했으며, 야권과 시민단체, 해외 기관은 법의 허위 정보 기준 모호성과 표현의 자유 침해를 우려하고 있다. 국민의힘 주진우 의원은 법 시행 직전 기구가 미비한 졸속 입법이라며 헌법소원을 예고했고, 향후 법의 시행 여부와 허위 정보 판단 기구의 독립성에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:12'::timestamp,'2026-07-27 16:36:52.498752'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1235,2339,'더불어민주당은 6·3 지방선거 투표 용지 부족 사태와 관련해 5일 선거관리위원회 특검법을 이번 주 발의할 예정이며, 특검 추천권을 제3자인 대한변호사협회 등에 위임하겠다고 밝혔다. 이는 정치적 편향을 배제하고 선관위의 독립성과 중립성을 고려한 조치로, 민주당은 수사 범위에 투표용지 인쇄 물량 축소 경위, 지휘부 보고 누락 및 지연, 내부 부패와 무능 등을 포함할 계획이다. 반면 국민의힘은 특검의 공정성을 위해 야당이 후보자를 추천해야 한다며 강력 반발하며, 지난달 9일 야당이 2명의 후보를 추천하고 대통령이 임명하는 방식의 특검법을 이미 발의한 바 있다. 현재 여야는 특검법 처리에 대한 합의가 이뤄지지 않아 7월 임시국회에서 단독 처리 가능성도 제기되며, 국민의힘은 올림픽공원 핸드볼경기장 개표소에 남아 있는 투표지 247만장에 대한 공개 재검표를 추진 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:18'::timestamp,'2026-07-27 16:36:33.821209'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1236,2341,'정부와 민주당은 5일 고위당정협의를 통해 반도체, 피지컬 AI, AI 데이터센터 등 3대 메가프로젝트를 지원하기 위한 ''메가특구특별법'' 제정을 추진하며, 법인세·소득세 감면 및 과세이연, 부담금 감면, 국공유지 임대료 인하 등을 검토하고 있다. 이는 대규모 투자 기업의 인허가 신속 처리, 전력·용수 인프라 확충, 서남권 기업형 첨단 도시 조성 등 지역 성장과 산업 경쟁력 강화를 목표로 한 장기적 국가 전략이다. 7월 임시국회에서 일부 법안은 처리될 전망이나, 여야 원 구성 협상 결렬로 야당의 반발이 예상되며, 민주당은 패스트트랙 기간 단축과 필리버스터 요건 강화를 포함한 입법 절차 개편도 검토 중이다. 이후 메가프로젝트 입법은 여야 간 대립 심화 가능성과 함께, 정부의 주요 국정과제 1차 통과 목표 달성 여부에 따라 정치적 논쟁의 중심에 서게 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:25'::timestamp,'2026-07-27 16:36:51.333312'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1237,2342,'국민의힘 이진숙 의원은 5월 5일 배재고등학교 야구부가 5·18 민주화운동을 희화화했다는 논란으로 징계를 받은 후, 학생들을 응원하기 위해 화환을 보냈다. 이 의원은 화환 리본에 ''스타벅스가 5·18과 무슨 관계가 있나'', ''배재고 학생들과 함께 합니다''라는 문구를 적으며, 이재명 정권이 생각에 수갑을 채운다고 비판했다. 대한야구소프트볼협회는 지난 1일 배재고 야구부에 전국대회 6개월 출전 정지를 결정했고, 배재고는 학생들을 대상으로 생활교육위원회를 열어 자체 징계를 진행 중이다. 6일 배재고 야구부와 학부모, 교직원은 광주일고를 방문해 사과하고, 국립 5·18민주묘지 참배를 계획하고 있으며, 학교 앞에는 응원과 비판을 담은 화환이 함께 놓여 있는 상황이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:30'::timestamp,'2026-07-27 16:35:11.173251'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1238,2351,'2026년 북중미 월드컵에서 한국 축구 대표팀은 조별 리그 탈락에 그치며 최종 순위 34위를 기록했다. 이는 역대 최고의 선수진을 보유하고도 32강 진출에 실패한 것으로, 홍명보 전 감독의 선임 절차에 법원이 절차적 하자를 인정한 점과 정몽규 회장의 감독 선임 개입 의혹이 여론의 중심에 섰다. 빅데이터 분석에 따르면 홍 감독은 ''탈락'', ''비판'', ''분노'' 등 부정적 감성어와 함께 ''충격'', ''실패하다'' 등이 높게 나타났으며, 기자회견 후 한 손을 주머니에 넣고 퇴장하는 태도가 국민적 공분을 일으켰다. 정몽규 회장은 ''논란'', ''신뢰'', ''중징계'', ''의혹'' 등이 연관어로 나타났고, 법원 판결로 선임 절차 하자가 확인된 이후에도 4연임에 성공하며 책임 회피 논란이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:40'::timestamp,'2026-07-27 16:38:22.695284'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1239,2352,'민주당 당권 주자인 김민석 전 국무총리, 송영길 의원, 정청래 전 대표가 8·17 전당대회를 앞두고 서울 용산구의 한 호텔에서 열린 국회의원 워크숍에서 한자리에 모였다. 이날 행사장 내부에서는 화기애애한 분위기가 연출되었지만, 행사 전까지는 김 전 총리와 송 의원이 정 전 대표의 강경 노선과 1인 1표제, 지방선거 결과 등을 두고 공개적으로 비판하며 대립각을 세운 바 있다. 김 전 총리는 당의 대대적 혁신 필요성을 강조하며, 정 전 대표와 송 의원의 경험을 상회하는 실적을 내세웠고, 정 전 대표는 1인 1표제 흔들림을 경계하며 친명계의 보완 요구를 반박했다. 이후 워크숍에서는 22대 후반기 국회 운영 전략과 이재명 정부 2년 차 국정 과제 입법 추진을 선언했으며, 당정청 협력과 민생 입법 완수를 목표로 하되, 야당과의 협치는 언급되지 않았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:46'::timestamp,'2026-07-27 16:23:55.573500'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1240,2353,'더불어민주당은 2024년 3월 3일 KBS, EBS, 방송문화진흥회 이사 후보를 내정하며, 친여 성향의 시민단체 출신을 다수 포함시켰다. 이는 지난해 민주당이 국민의힘 반대에도 불구하고 ''방송3법'' 개정안을 강행 처리해 시민단체 등에 이사 추천 권한을 부여한 데 따른 후속 조치다. KBS 이사 후보 4인 중 3인, EBS 이사 후보 5인 중 3인, 방송문화진흥회 이사 후보 5인 중 3인을 여당 몫으로 추천했으며, 이 중 다수는 민주언론시민연합, 시민사회단체연대회의 등 친여 시민단체 출신이다. 이후 이사 후보들은 국회 인사청문회를 거쳐 최종 임명 절차를 밟을 예정이며, 이 과정에서 여야 간 공방이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:51'::timestamp,'2026-07-27 16:22:17.997287'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1241,2356,'이재명 대통령은 7일 튀르키예 앙카라에서 열리는 2026 나토 정상회의에 참석한 뒤, 9일부터 11일까지 몽골을 국빈 방문한다. 이는 취임 1년 만에 성사된 역대 최초의 몽골 국빈 방문으로, 한·나토 안보 협력 강화와 K방산의 나토 공급망 편입을 위한 기조 발언 및 방산 포럼 참석이 핵심이다. 이번 순방에서는 한·몽 관계의 황금시대 공동선언을 발표하며 2030년까지 인적 교류 50만명 달성과 핵심 광물 공급망, 식량 안보, 황사 대응 네트워크 다변화 협력이 논의된다. 이 대통령은 11일 몽골 최대 명절인 나담축제 개막식에 최고 주빈으로 참석하며, 몽골의 외교적 자산을 활용해 대북 대화 재개를 위한 외교적 기반을 마련할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:32:56'::timestamp,'2026-07-27 16:21:52.368423'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1242,2358,'국민의힘은 3일 중앙선관위가 위철환 직무대행의 사퇴를 거부하고 전원 유임을 목표로 한 대응 문건을 작성한 사실을 공개하며, 선관위가 국민의 개혁 요구에 반응하지 않고 조직 보전에만 집중했다고 비판했다. 이는 이재명 대통령이 선관위에 대한 검경 합동 수사를 지시한 지 3일 만에 3팀 16명 규모의 대응 태스크포스(TF)를 구성한 것과 맞물려, 선관위의 자정 능력에 대한 신뢰가 흔들리는 상황이다. 국민의힘은 위철환 직무대행의 즉각적인 사퇴를 요구하며, 야당 추천 특검과 탄핵을 포함한 정치적·법적 책임 추궁을 예고했다. 현재 선관위의 대응 문건과 태스크포스 구성은 선거 관리의 투명성과 책임성에 대한 논란을 불러일으키며, 향후 정치권과 시민사회에서의 추가 조치와 개혁 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:01'::timestamp,'2026-07-27 16:21:44.886571'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1243,2367,'모건스탠리는 2024년 6월 6일 보고서를 통해 삼성전자, SK하이닉스, 마이크론 등 메모리 반도체 관련주의 투자 비중을 축소할 것을 권고했다. 이는 반도체 실적 모멘텀이 정점을 지나 추가 조정 가능성이 높고, 하이퍼스케일러의 AI 투자 속도 조절로 인해 메모리 수요 전망이 약화되고 있음을 반영한 것이다. 특히 메타의 잉여 AI 컴퓨팅 용량 외부 판매 발표가 하이퍼스케일러의 투자 조절 신호로 해석되며, 반도체 주도주 지위가 알파벳, 아마존 등 AI클라우드 기업으로 이동할 전망이다. 이후 모건스탠리는 반도체주에서 AI클라우드 기업으로 자금 이동이 시작된 신호로 보며, 소비재, 운송, 지역은행, 바이오 등 다른 업종에 수혜를 예상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:06'::timestamp,'2026-07-27 17:44:31.813746'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1244,2369,'올해 1∼5월 전국 아파트 전월세 거래량은 전년 동기 대비 7.2% 감소한 반면, 비아파트 거래는 11.5% 증가하며 임차인들의 이동 흐름이 나타났다. 전세 물건 부족과 가격 상승, 대출 규제로 인해 아파트 전세 수요가 줄었고, 서울 아파트 전월세 매물은 2년 전 대비 14.5% 감소한 3만7551건으로 집계됐다. 서울 아파트 신규 전세 평균 보증금은 2년 전 대비 19.0% 상승한 6억5875만원이며, 월세 비중은 51.3%로 절반을 넘어섰고, 전세 갱신계약 비중도 51.3%로 과반을 차지했다. 이에 따라 비아파트로의 전환 수요가 증가하며 전세 물건 부족과 월세화, 갱신계약 확대 등 주거 안정성 문제와 함께 정책적 대응이 필요해지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:11'::timestamp,'2026-07-27 16:28:24.604814'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1245,2411,'이재명 정부는 내년도 세제 개편안에서 부동산 보유세를 인상하고 다주택자에 대한 거래세를 낮추는 방향으로 조정할 예정이다. 이는 서울 아파트값이 정부 규제에도 불구하고 지난 1년간 평균 15% 이상 상승했고, 특히 광진구, 동작구, 강동구 등 비강남 지역에서 20% 이상 급등한 데 따른 것으로, 주거비 부담과 세금 부담이 전연령층에 걸쳐 사회적 불안을 초래하고 있다. 공시가격 상승으로 인해 2024년 공동주택가격은 9.13% 상승했으며, 종합부동산세와 재산세의 과세 기준이 되는 공시가격이 지속적으로 오르면서 보유세 부담이 증가하고 있다. 정부는 보유세 강화와 거래세 완화의 균형을 통해 주택 거래 활성화를 유도하고, 국민 의견 수렴을 거쳐 7월 말 최종 방침을 발표할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:17'::timestamp,'2026-07-27 17:33:39.091366'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1246,2374,'서울 고가아파트를 20억원에 양도한 2주택자 A씨는 모친의 지인 B씨에게 저가아파트를 허위 이전한 후, 1세대 1주택자로 신고해 양도세를 0원으로 회피했다. 이는 ''가장매매''라는 부동산 탈세 수법으로, 다주택자가 친척이나 지인에게 저가주택을 명의만 이전한 뒤 고가주택을 양도하면서 비과세 혜택을 부당하게 적용한 사례다. 국세청은 지난해 10월부터 104명을 대상으로 조사해 총 731억원의 탈루금액을 적발했으며, 이 중 318억원을 추징했다. 국세청은 명의신탁, 증여세 탈루, 사업소득 누락 등에 대한 조사 범위를 확대하고, 40%에 달하는 과소신고에 대해 가산세를 부과하며 6명은 검찰 고발, 4명은 통고처분, 20명은 과징금 및 형사처벌 통보를 진행했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:23'::timestamp,'2026-07-27 17:40:39.231766'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1247,2377,'금융감독원장 이찬진은 레버리지 투자 확산으로 가계 재무 건전성이 심각하게 훼손될 수 있다고 우려하며 금융사에 소비자 위험 설명과 과도한 대출 영업 관리를 강화할 것을 당부했다. 최근 증시 변동성 확대와 함께 미수 거래 반대 매매 금액은 3월 262억원에서 527억원으로 두 배 이상 증가했으며, 신용 융자 잔액은 3월 말 32조9000억원에서 4월 말 37조3000억원으로 증가했다. 특히 단일 종목 레버리지 ETF는 5월 27일부터 6월 22일까지 8조9000억원어치 순매수되었고, 일평균 거래 대금은 9조6000억원에 달했다. 금감원은 레버리지 투자 위험에 대한 소비자 설명 의무 강화, 단일 종목 ETF 모니터링, 카드 부정 결제 예방 TF 운영, 제3자 리스크 관리 가이드라인 시행 등 후속 조치를 추진하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:29'::timestamp,'2026-07-27 17:35:49.429146'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1248,2380,'공정거래위원회는 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 제당사가 2018년 5월부터 2025년 10월까지 7년 5개월 동안 전분당 가격을 담합한 혐의로 총 7476억원의 과징금을 부과했다. 이는 국내 담합 사건 중 역대 최대 규모로, 전분당은 라면, 빵 등 식품 원료 및 산업용 접착제 소재로 사용되며, 이들 업체는 전분 시장 점유율 95.7%, 전분당 시장 점유율 86.4%를 차지하고 있었다. 담합으로 인해 옥수수 가격 상승기에는 판매가를 73%까지 인상하며 영업이익 하락을 최소화했고, 가격 하락기에는 인하 시기를 늦추며 이익을 유지한 것으로 확인됐다. 공정위는 제당사들에게 독자적 가격 재결정 명령과 3년간 반기별 보고 의무를 부과했으며, 입찰 시장 및 부산물 분야 담합 혐의에 대한 추가 제재 절차도 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:36'::timestamp,'2026-07-27 17:34:58.115132'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1249,2382,'국가데이터처는 2025년 12월부터 소비자물가지수 조사 방식을 개편해 고사리, 땅콩, 유치원납입금 등 13개 품목을 제외하고 소프트웨어 구독료, 스마트워치, 전기차충전료 등 10개 디지털 소비 항목을 신규 포함한다. 이는 5년 주기로 실시되는 소비패턴 변화 반영 조치로, 2025년 가계동향조사 결과를 기초로 소비지출 비중 증가 품목을 반영한 것으로, 대표품목은 기존 468개에서 455개로 조정된다. 개편된 지수는 2025년 기준으로 산정되며, 2025년 12월 18일 공표되고, 2026년 12월 및 연간 소비자물가동향은 12월 31일에 발표될 예정이다. 이번 개편에 대해 12월 7일부터 17일까지 국민 의견 수렴을 진행하고, 국가통계위원회의 심의를 거쳐 최종 확정할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:42'::timestamp,'2026-07-27 17:35:08.300534'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1250,2383,'삼성전자는 2026년 2분기 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 사상 최대 실적을 발표했으나, 시장 예상치(약 85조원)를 웃돌았지만 일부 전망치(90조~100조원)에는 미치지 못해 ''어닝 미스''로 평가받았다. 이에 따라 7일 삼성전자 주가는 전일 대비 2.83% 하락하며 30만9000원에 출발했고, 오후 1시 44분 기준 9.43% 하락해 28만8000원까지 떨어지며 29만원선이 무너졌다. 코스피는 7.51% 하락한 7446.86를 기록했고, SK하이닉스와 일본 키옥시아, 미국 메모리 반도체 기업들의 주가도 하락하며 반도체 시장 전반에 하락세가 확산됐다. 증권가에서는 실적이 호조였지만 시장 기대가 사전에 반영되면서 ''재료 소멸'' 현상이 발생했고, 이는 최근 2년간 8차례 실적 발표 중 7차례에서 주가 하락이 이어진 패턴과 일치하며, 향후 주가 변동성과 차익 실현 매물의 영향이 지속될 것으로 전망된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:49'::timestamp,'2026-07-27 17:27:08.154211'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1251,2385,'구윤철 부총리 겸 재정경제부 장관은 7일 지방 근로자에 대한 소득세를 서울보다 더 감면하는 방안을 검토하겠다고 밝혔다. 이는 지방 근로자의 환경적 열악성과 자녀 교육비 지원 가능성 등을 고려한 것으로, 소득공제 및 세액공제 방식을 포함한 세제 지원 방안을 마련 중이다. 반도체·AI 산업 지원을 위해 R&D 및 투자에 대한 세제 혜택 확대와 이월공제 도입을 검토하며, 삼성전자와 SK하이닉스의 올해 예상 영업이익 600조원을 기반으로 한 초과 세수를 ''미래대응기금''에 활용할 계획이다. 정부는 이달 말 세제 개편안을 발표하고, 9월 정기 국회 전에 관련 법안을 처리할 방침이며, 호남·충청·영남권을 각각 반도체 제2 생산기지, 패키징 중심지, AI 소부장 중심지로 특화하는 지역 산업 육성 전략도 추진 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:33:55'::timestamp,'2026-07-27 17:43:47.912942'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1252,2386,'SK하이닉스는 10일(현지시각) 나스닥에 미국 예탁주식(ADS)으로 상장하며, 전직 오픈AI 연구원이 설립한 헤지펀드 시추에이셔널 어웨어니스를 포함한 다수 기관투자가가 최대 70억달러어치를 인수하겠다고 밝혔다. 이번 상장은 외국 기업 중 사상 최대 규모로, 발행주식의 약 2.5%인 1779만 주를 신주로 발행해 약 43조1400억원 규모의 자금을 조달하며, 조달 자금은 용인 반도체 클러스터와 청주 패키징 공장, EUV 장비 구매 등 국내 생산설비 투자에 사용된다. 상장 후 SK하이닉스의 2026년 선행 PER은 7.42배로, 미국 경쟁사 마이크론의 9.44배보다 낮아 저평가된 상태이며, 나스닥 100 지수 편입 가능성과 ETF 수요 기대로 기업가치 재평가가 기대된다. 다만 신주 발행으로 인한 지분 희석 위험과 메모리 수요 변동, 중국 수출통제 감시 강화, 삼성전자 HBM4 시장 공략 등이 후속 쟁점으로 남아 있으며, ADR 예탁비율을 10대 1로 설정해 주당 가격을 150달러 수준으로 낮춰 접근성과 유동성을 높였다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:04'::timestamp,'2026-07-27 17:26:14.602540'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1253,2391,'정부는 내년 1월부터 국립대병원을 중심으로 지역 주도의 필수의료 체계를 강화하기 위해 지역필수의료특별회계를 신설한다. 이는 수도권에서 멀수록 지원을 확대하고, 공공의료기관 우선 투자, 지역 주도 사업 설계를 원칙으로 하며, 지방자치단체가 지역 여건에 맞는 의료계획을 수립·추진할 수 있도록 하는 것이 핵심이다. 지역필수의료법의 하위법령은 2024년 3월 시행 예정으로, 필수의료 종합계획, 시·도 시행계획, 실태조사, 성과평가, 책임의료기관 중심 진료협력체계 등이 포함되며, 복지부는 정책 기준과 재정 지원을, 시·도는 시행계획 수립을, 권역책임의료기관은 네트워크 조정을 담당한다. 이후 지방정부와 의료기관의 의견을 반영해 하위법령을 보완하고 입법예고 등 후속 절차를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:10'::timestamp,'2026-07-27 17:42:21.284366'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1254,2394,'2024년 7월 7일 오후 1시 51분, 코스피 지수가 전일 종가 대비 8.07% 하락하며 8% 이상 하락 상태가 1분 이상 지속되면서 유가증권시장에 서킷브레이커가 발동됐다. 이는 올해 들어 6번째로, 역대 12번째 발생한 서킷브레이커로, 지난달 26일 이후 7거래일 만의 발동이다. 발동 당시 코스피 지수는 8051.33포인트에서 7401.56포인트로 하락했으며, 모든 종목의 거래가 20분간 중단됐고, 거래 재개 전 10분간 호가 접수 후 단일가 방식으로 매매가 진행됐다. 한국거래소는 반도체 관련주 차익 실현 매물이 출회된 것이 원인으로 분석했으며, 이날 오전 10시 23분에는 코스피200선물지수도 5.12% 하락하며 매도 사이드카가 발동된 바 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:15'::timestamp,'2026-07-27 17:41:41.490861'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1255,2396,'국민연금은 2024년 6월 말까지 국내 주식 리밸런싱을 유예했으며, 목표 투자 비중을 14.9%에서 20.8%로 상향 조정했다. 국내 주식 평가액이 증시 급락으로 감소하면서 리밸런싱 부담이 일시적으로 완화되었고, 1~3일 유가증권시장에서의 순매도 규모는 2158억원에 그쳤다. 기존 예상된 60조~70조원 규모의 매도 폭탄은 발생하지 않았으며, 실제 매도 물량은 14조~15조원 수준으로 추산된다. 다만 반도체 기업 실적 발표 이후 리밸런싱 압박이 재부각될 수 있고, 시장 상황에 따라 목표 비중 조정을 유예할 수 있도록 하는 국민연금법 개정안이 발의된 상태다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:21'::timestamp,'2026-07-27 17:41:08.247773'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1256,2400,'금리 상승 기조에 따라 시중은행의 12개월 만기 정기예금 최고 금리는 연 3.82%까지 올랐으며, 저축은행은 평균 3.9%로 4%대 금리를 제공하고 있다. 이는 증시 상승으로 인한 자금 유출 우려와 하반기 기준금리 인상 전망에 따라 은행들이 고객 유지를 위해 예금 금리를 인상한 결과다. 은행채 1년물(AAA) 금리는 4월 초 3.182%에서 지난달 29일 3.724%로 상승했으며, 16일 예정된 금융통화위원회에서 기준금리 인상 가능성에 따라 여·수신 금리 조정이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:25'::timestamp,'2026-07-27 17:36:42.889174'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1257,2404,'A씨는 다주택자임에도 아파트를 지인에게 명의만 이전해 1주택자로 신고하고 20억원의 매도 수익에 대해 양도세 10억원을 회피한 혐의를 받았다. 이는 지인에게 거주 및 세금 납부를 대신해주는 등 사실상 거래 없이 명의만 이전한 허위 거래로, 국세청 조사에서 드러났다. 국세청은 이번 조사에서 80여명의 부동산 탈세 혐의자로부터 총 318억원의 세금을 추징하고, 6명을 조세포탈 혐의로 검찰에 고발했다. 특히 다주택자들이 1주택자로 가장하거나 증여를 통해 세금을 회피하는 사례가 늘어나고 있어, 증여 재산의 저가 평가 및 대납 여부에 대한 추가 검증이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:30'::timestamp,'2026-07-27 17:35:15.576928'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1258,2405,'공정거래위원회는 2018년 5월부터 2025년 10월까지 전분당 가격을 담합한 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 기업에 총 7476억원의 과징금을 부과했다. 이들 기업은 국내 전분 시장에서 95.7%, 전분당 시장에서 86.4%의 점유율을 차지하며, 13차례에 걸쳐 가격 인상·인하 시기와 폭을 합의한 것으로 확인됐으며, 가격 담합으로 인해 판매 가격이 평균 73% 인상된 것으로 분석됐다. 공정위는 관련 매출액이 6조525억원으로 추정하고, 공정거래법 제40조 제1항 제1호 위반으로 판단해 과징금 부과기준율을 15%로 설정했다. 또한 전분당 입찰담합 및 부산물 가격 담합 혐의에 대해 조사를 마무리하고 위원회 심의를 거쳐 추가 조치를 예정하고 있으며, 입찰담합 관련 매출액은 9400억원, 부산물 담합은 1조5500억원으로 추정된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:35'::timestamp,'2026-07-27 17:35:29.385724'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1259,2408,'2024년 4월 7일 오전, 외국인과 기관의 매도세로 코스피 지수가 5.73% 하락하며 7590.12를 기록, 7500선까지 밀렸다. 이는 올해 16번째로 발동된 유가증권시장 매도 사이드카로, 외국인이 2조167억원, 기관이 894억원 순매도한 것이 주요 원인이다. 삼성전자와 SK하이닉스 등 시가총액 상위 종목들이 각각 8%대, 7%대 하락하며 지수 하락을 주도했으며, 코스닥 지수도 1.52% 하락한 834.19를 기록했다. 현재 외국인과 기관의 순매도가 지속되고 있으며, 향후 시장 회복 여부와 외환 및 금리 정책의 영향이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:40'::timestamp,'2026-07-27 17:34:51.036151'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1260,2417,'암웨이는 2024년 하반기 한국 시장에 독점 균주 2종을 적용한 프로바이오틱스 신제품 ''뉴트리라이트''를 출시한다. 이 균주는 한국인의 식습관과 생활환경을 반영한 대규모 데이터 기반으로, 장내 미생물 다양성 저하 및 뷰티르산 생성 촉진에 기여하는 것으로 확인됐으며, 위장관 모델과 인간 오가노이드를 활용한 연구 플랫폼을 통해 실제 장 환경에서의 기능을 검증했다. 국내 프로바이오틱스 시장 규모는 2023년 약 7200억원으로, 전체 건강기능식품 시장에서 홍삼에 이어 2위를 차지했으며, 암웨이는 11만 건 이상의 장내 마이크로바이옴 데이터베이스를 기반으로 3428개 균주 라이브러리에서 스크리닝해 독점 라이선스를 확보했다. 암웨이는 건강수명 연장에 기여하는 전 생애주기 솔루션 개발을 지속할 예정이며, 이는 장 건강이 전신 건강에 미치는 영향이 커진 사회적 트렌드와 관련이 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:47'::timestamp,'2026-07-27 17:32:05.852757'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1261,2421,'경남 남해군 미조항에서 조업한 자연산 갯장어를 활용한 샤부샤부용 특별 공동구매 행사가 진행되며, 기존 인당 10만원 수준이던 제품을 한 접시 2만원대에 제공한다. 갯장어는 6월부터 9월까지 남해안에서만 얻을 수 있는 여름 보양식으로, 단백질과 불포화지방산, 콜라겐 등이 풍부해 혈관 건강과 기력 회복에 도움을 준다. 이번 공동구매는 400g 중량의 정교하게 손질된 갯장어와 전용 육수를 진공 포장 후 스티로폼 박스에 얼음을 넣어 냉장 배송하며, 수령 후 최대 1일간 냉장 보관 가능하다. 이후 냉동 보관 시 식감 손실이 발생할 수 있어 가급적 빠른 조리가 권장되며, 조리법은 끓는 육수에 갯장어를 살짝 익히는 간단한 방식이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:52'::timestamp,'2026-07-27 17:32:04.061167'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1262,2422,'8일 더불어민주당 산업통상자원중소벤처기업위원회(산중위)와 산업통상부는 메가특구 특별법 논의를 위한 비공개 당정협의를 진행했다. 이는 정부가 발표한 ''3대 메가프로젝트'' 중 호남 반도체를 중심으로 한 산업 구조 혁신을 뒷받침하기 위한 법안 마련을 목표로 하며, 반도체·피지컬AI·AI데이터센터 투자 기업에 대한 세제 감면, 보조금, 국공유지 임대료 감면 등 혜택을 포함할 예정이다. 산업부는 메가프로젝트 및 대미 투자 등 현안을 보고했으며, 산중위 소속 호남 지역 의원들의 참여로 입법 속도가 예상된다. 이후 산중위는 메가특구 특별법 외에도 물관리기본법, 수도법, 산업입지법 개정도 추진할 계획이며, 민주당은 조속한 특별위원회 구성과 예산 확보를 강조하며 입법 속도전을 예고했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:34:58'::timestamp,'2026-07-27 17:31:57.224904'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1263,2423,'LG전자는 2024년 2분기 연결 기준 매출 23조8297억원, 영업이익 1조5788억원을 기록하며 두 분기 연속 영업이익 1조원을 돌파했다. 이는 전년 동기 대비 매출 14.9%, 영업이익 146.9% 증가한 것으로, 시장 전망치를 약 47% 상회하는 어닝 서프라이즈다. 주요 원인은 프리미엄 가전·TV 판매 확대, 웹OS·구독 등 고수익 사업 성장, 미국 관세 환급 일회성 수익, 그리고 원가경쟁력 개선과 전사 비상경영 체제의 효과였다. LG전자는 8월 말 2분기 순이익과 사업본부별 확정 실적을 발표할 예정이며, AI 데이터센터 냉각 솔루션 분야 투자 확대도 지속할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:03'::timestamp,'2026-07-27 17:31:12.967081'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1264,2424,'서울시는 강동구 명일동 삼익맨숀아파트 재건축 사업의 통합심의안을 수정가결·조건부 의결했다. 이 사업은 1984년 준공된 기존 아파트를 39층, 990가구 규모로 재건축하며, 전용면적 173㎡ 대형 평형으로 구성된 5동을 제외한 구조로 진행된다. 5동 소유주들과의 갈등으로 2020년 정비구역 지정 후 지연됐으나, 법원 판결을 통해 분리 재건축이 가능해졌으며, 공공주택 104가구와 근린공원, 공영주차장 조성도 계획 중이다. 이후 제척된 5동의 별도 정비 방안 마련이 남은 쟁점으로, 도시 미관과 재산권 문제 해결이 필요하며, 독자적 재건축 가능성도 검토될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:07'::timestamp,'2026-07-27 17:31:02.786100'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1265,2426,'2024년 2월 2일, NHN은 판교 사옥에서 기술 공유 행사 ''에이전틱 데이''를 개최하며 AI 도입 사례를 공유했다. 양철웅 NHN CTO는 AI 시대의 다음 과제로 데이터 안전 연결과 보안 강화를 강조하며, 개발 단계부터 보안성을 고려한 AI 활용을 추진하겠다고 밝혔다. 이 행사에서 NHN클라우드는 AI 기반 보안 취약점 점검 서비스의 데모 버전을 최초 공개했으며, 이 서비스는 AI 토큰을 최소한으로 사용해 효율성을 극대화했고, NHN클라우드에서 시범 적용 후 전 그룹사로 확대될 예정이다. 또한 NHN은 전 임직원 대상으로 앤트로픽의 AI 모델 클로드를 제공하며 내부 AI 전환(AX)을 확대하고 있으며, 기획자 등 비개발 직군도 자연어 입력을 통해 데이터 분석을 빠르게 수행할 수 있도록 지원하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:12'::timestamp,'2026-07-27 17:30:49.491090'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1266,2432,'코스피 지수가 7일 오전 10시 23분 전 거래일 대비 5% 이상 하락하면서 한국거래소는 유가증권시장에 매도 사이드카를 발동했다. 이는 올해 들어 32번째 사이드카 발동으로, 매도 사이드카는 16번, 매수 사이드카는 16번 각각 발동된 것으로 집계됐다. 사이드카 발동 당시 코스피200선물지수는 5.12% 하락한 1227.32포인트를 기록했고, 프로그램 매매 거래 규모는 1조1856억원에 달했다. 사이드카는 코스피200 선물가격이 전일 종가 대비 5% 이상 변동이 1분간 지속될 경우 프로그램 매매 호가를 5분간 제한하는 제도로, 급락 시 매도호가 효력을 일시 정지한다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:16'::timestamp,'2026-07-27 17:29:42.840877'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1267,2450,'금융위원회는 7일 서울 중구 은행회관에서 ''포용금융 전략 추진단'' 금융산업분과 킥오프 회의를 열고, 금융회사의 포용금융 실적 평가에 금리 인하 효과, 금융 접근성 개선, 지배구조 반영 등을 종합적으로 반영하기로 결정했다. 중저신용자 대출 시장의 금리 절벽 문제를 해결하기 위해 은행과 제2금융권의 협업 모델과 신용평가 인프라 확충, 비용 구조 개선 방안을 검토하며, 올해 3월 기준 중신용자 평균 금리는 연 7.9%로, 하위 20% 차주는 연 13.4%에 달했다. 건전성 규제의 합리화도 추진되며, 중저신용자 대출에 대한 위험가중치, 채무조정 자산 분류 기준, 대손충당금 적립 기준 등이 폭넓게 검토된다. 상호금융 제도 개선과 평가체계 개편도 병행해, 포용금융 실적을 경영평가에 반영하고, 우수 기관에 인센티브를 부여하는 방향으로 제도 개선 방안을 마련할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:22'::timestamp,'2026-07-27 17:29:02.410367'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1268,2463,'2022년 4월부터 2024년 11월까지 대출 브로커 A씨는 의사와 약사 278명과 공모해 위조된 잔고증명서와 허위 의료기기 매매계약서를 제출해 신용보증기금 예비창업보증 보증서 1970억원 상당을 부정하게 발급받은 혐의로 구속 기소됐다. A씨는 페이퍼 컴퍼니를 설립해 허위 계약서를 작성하고 포토샵으로 잔고증명서를 위조하며, 예비창업보증 제도의 서류 중심 심사와 은행의 신용보증기금 신뢰 구조를 악용한 것으로 조사됐다. 전체 1970억원 중 약 1796억원이 변제되었으며, 피해를 입은 의료인 80명 중 273명은 기소유예, 3명은 혐의없음 처분을 받았으나, 대출금을 개원 외 목적으로 사용하고 폐업한 의사 2명은 불구속 기소됐다. 검찰은 공적자금 편취 행위에 대해 엄단할 방침을 밝히며, 향후 유사 범죄 예방을 위한 제도 개선과 감시 강화가 필요하다는 점을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:28'::timestamp,'2026-07-27 17:46:31.083048'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1269,2469,'광주광산경찰서 수사팀장 A 경감이 ''광주 여고생 살해 사건'' 수사 과정에서 피의자 장윤기의 차량 압수수색 시 증거인멸 및 수사 정보 유출 혐의를 받으며, 경찰청 특별수사팀이 7일 구속영장을 신청했다. 사건은 2023년 5월 발생한 강간살인죄로, 최소 무기징역이 가능한 중대 범죄로, 증거인멸로 인해 법적 입증이 어려워지며 사회적 파장이 커졌다. 특별수사팀은 경찰청 수사관과 광주경찰청 수사팀이 합동으로 수사를 진행하며, 유착 의혹과 증거인멸 경위를 철저히 조사하고 있으며, 국민 신뢰 회복을 목표로 엄정한 수사를 진행 중이다. 이후 특별수사팀은 수사 결과를 공개하고, 관련자에 대한 징계 및 법적 책임 여부를 판단할 예정이며, 경찰 내부 감찰 제도의 개선 필요성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:33'::timestamp,'2026-07-27 17:36:12.641326'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1270,2476,'조경식 전 KH그룹 부회장이 전 여자친구 A씨를 흉기로 위협하고 폭행, 7시간 넘게 감금한 혐의로 수원지법에서 징역 4년을 선고받았다. 이 사건은 2023년 2월 15일 경기 용인시 아파트 지하 주차장에서 발생했으며, 조씨는 피해자에게 600만원을 갈취하고 13차례에 걸쳐 스토킹한 혐의도 인정받았다. 재판부는 조씨가 과거 여러 차례 실형을 선고받은 전력이 있고, 사기죄 누범 중에 범행을 저질러 죄질이 매우 나쁘다고 판단하며, 피해자의 신체적·정신적 고통과 반성 부족을 고려해 유죄를 선고했다. 조씨는 이와 별개로 2023년 5월 ‘연어 술 파티’ 의혹을 주장하며 국회 청문회에 출석했으나, 법무부 특별 점검 결과 해당 발언은 거짓으로 확인되었고, 그 시점에 조씨는 이미 사기죄로 수감 중이었음이 밝혀졌다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:39'::timestamp,'2026-07-27 17:44:02.295160'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1271,2480,'인천지법 형사14부는 19개월 된 딸 B양을 음식을 주지 않고 방치해 영양결핍과 탈수로 사망하게 한 혐의로 기소된 친모 A(29)씨에게 징역 30년과 출소 후 5년간 보호관찰을 구형했다. A씨는 지난 3월 4일 인천시 남동구의 한 빌라에서 생후 19개월 된 딸 B양에게 67시간 동안 음식을 주지 않았고, 2월 28일부터 92시간 동안 혼자 방치한 것으로 조사됐으며, 부검 결과 체중 4.7㎏(평균 10.4㎏)으로 영양 결핍이 원인으로 확인됐다. A씨는 기초생활수급자로 월평균 300만 원 이상의 공적 지원을 받으며 푸드마켓 이용 등 지원을 받았으나, 집안은 쓰레기와 배설물로 어지럽고, 개 사체와 담배꽁초도 방치하는 등 양육 소홀이 심각했다. 재판부는 A씨의 반성 여부와 재범 가능성, 지원 시스템의 한계 등이 후속 논의의 초점이 될 것으로 보이며, 판결은 향후 공개될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:46'::timestamp,'2026-07-27 17:35:56.072378'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1272,2481,'경찰은 6·3 지방선거 기간 부산시장 후보였던 정이한(38)에 대해 음료 컵 피습 자작극 의혹과 관련해 위계에 의한 공무집행방해 및 공직선거법 위반 혐의로 구속영장을 청구했다. 이 사건은 선거운동 중 정 전 후보가 음료 컵에 맞아 피습당한 것으로 꾸며진 것으로, 경찰은 정 전 후보가 이를 조작했으며 증거 인멸과 도주 우려가 있어 구속 필요성을 인정했다. 구속영장은 6월 1일 신청해 6월 3일 검찰이 법원에 청구했으며, 영장실질심사는 6월 8일 부산지법에서 진행된다. 현재 정 전 후보는 3위로 2만7418표(득표율 1.56%)를 얻었으며, 부친 소유 기업의 선거운동 동원 및 여론조사기관의 공정성 문제 등 추가 수사가 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:50'::timestamp,'2026-07-27 17:33:14.249143'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1273,2482,'2024년 4월 26일 경기 구리시의 한 도로에서 A씨(50대)가 후진 중인 모닝 차량을 고의로 부딪혀 보험금을 타내려 한 사건이 발생했다. A씨는 사고 10분 전부터 횡단보도 주변을 돌아다니며 접촉사고를 유도하는 행동을 보였으며, CCTV 영상에 고의로 차량 뒷부분에 부딪혀 넘어지는 장면이 포착됐다. 경찰은 CCTV 분석을 바탕으로 A씨를 보험사기방지 특별법 위반 혐의로 불구속 송치했으며, A씨는 처음엔 술에 취해 기억이 없다고 주장했으나 사고 영상을 확인한 후 혐의를 인정했다. 현재 사건은 검찰 수사가 진행 중이며, 보험사기 방지 대책과 관련해 보험사 및 법적 제도 개선 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:35:54'::timestamp,'2026-07-27 17:29:26.168329'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1274,2502,'전국 시도교육청은 2021년부터 2025년까지 현금 및 현물 지원 예산을 2846억원에서 7658억원으로 3배 이상 증가시켰다. 이는 교육감들의 선거 공약을 실현하기 위한 현금 지원 확대 정책으로, 인천·강원·부산 등 여러 교육청이 초등입학 준비금, 진로활동지원금, 현장체험학습비 등 다양한 사업을 시행했다. 교육부는 현금 지원을 남발한 상위 8개 교육청에 2027년부터 지방교육재정교부금을 10억원씩 삭감하는 페널티를 적용할 예정이지만, 교육감들의 공약 중심 예산 편성은 여전히 확대 추세다. 이에 따라 기획예산처와 교육부는 8일 교부금 개편을 위한 공개 토론회를 개최하며, 학생 수 반영 및 경상성장률 고려 등 산정 방식 개선을 논의할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:00'::timestamp,'2026-07-27 16:56:22.043172'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1275,2509,'서울 배재고 야구부 학생들(86명)이 6일 전남 광주광역시 광주일고를 찾아 사과하며, 지난달 29일 청룡기 전국고교야구선수권대회에서 상대 팀 더그아웃을 향해 ''스타벅스 가야지'', ''탱크 데이''라고 외친 발언으로 논란을 빚은 후 반성의 자세를 보였다. 이 발언은 스타벅스 코리아의 5·18민주화운동 기념일 이벤트와 겹쳐 역사적 감수성을 훼손했다는 비판이 제기되었으며, 대한야구소프트볼협회는 배재고 야구부에 전국대회 6개월 출전 정지와 청룡기 몰수패를 내렸다. 사과 행사 후 두 학교 선수들은 국립5·18민주묘지와 학생독립운동기념탑을 참배했으며, 서울시교육감과 전남광주통합특별시교육감도 동행했다. 배재고는 자체 진상 조사와 징계 절차를 진행 중이며, 사태는 학생들의 인성 교육과 역사 인식 문제로 확대되며 교육계의 책임 논의로 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:07'::timestamp,'2026-07-27 16:58:38.588218'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1276,2529,'서울 배재고 야구부 학생 36명과 학부모, 교직원 등 총 86명이 6일 광주일고를 방문해 지역 비하 논란을 일으킨 ''스타벅스 가야지'' 등의 응원 구호에 대해 공식 사과했다. 이는 지난 5월 29일 목동구장에서 열린 광주일고와의 경기 도중 발생한 것으로, ''5·18탱크데이''라는 문구와 맞물려 5·18민주화운동을 희화화한다는 비판이 제기됐다. 사과 이후 배재고는 관련 학생 2명을 생활교육위원회에 회부하고, 대한야구소프트볼협회는 6개월 출전 정지와 남은 경기 몰수패를 결정했다. 서울시교육청은 조사 결과에 따라 교장·교감 등 관리자에 대한 책임 물음도 검토 중이며, 배재고는 자체 진상 조사 및 징계 절차를 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:13'::timestamp,'2026-07-27 16:43:44.373441'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1277,2533,'민형배 광주광역시장은 6일 청와대의 서남권 반도체 산단 조성 부지 발표에 대해 광주 군공항이 반도체 공장 최적지라고 평가하며 환영의 뜻을 밝혔다. 광주 군공항은 1964년 광산구에 건설된 이후 도심 확장으로 민가와 인접해 소음 문제로 인해 2013년 ''군공항 이전 및 지원 특별법''이 제정되며 이전 사업이 본격화됐으며, 현재는 김포·제주 노선의 민간 여객기와 전투기가 함께 운항하는 복합 공항이다. 군공항 이전 후에는 반도체 공장 부지로 활용될 전망이며, 이전 기간은 최대 5년, 비용은 8~9조원으로 예상된다. 정부는 군공항 이전과 반도체 산단 조성의 동시 추진 방안을 마련해야 하며, 이에 따라 대체 공항 건설과 인프라 준비가 핵심 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:18'::timestamp,'2026-07-27 16:48:49.336125'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1278,2534,'2024년 3월 중동 전쟁 발발 직후, HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 국내 4대 정유사와 임직원 4명이 공정거래법 위반 혐의로 기소됐다. 검찰 수사 결과, 이들 정유사는 2024년 7월부터 2025년 2월까지 가격 정보를 공유하고, 전쟁 발발 후 SK에너지가 리터당 30~40원 더 높은 가격을 제시하는 방식으로 가격 급등을 합의한 것으로 확인됐으며, GS칼텍스와 에쓰오일은 가격 추종을 통해 시장 전체 가격 상승을 유도했다. 이번 담합으로 인한 직접 피해 규모는 14조2000억원으로 추산되며, 전량구매계약을 통해 주유소를 종속시킨 유통 구조와 산업부에 허위 공급가를 보고한 행위도 함께 적발됐다. 검찰은 관련 자료 삭제 및 공정위 조사 회피 시도, 산업부 허위 보고 등에 대해 추가 조치를 예고하며, 공정거래위원회는 제재 강화와 제도 개선을 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:24'::timestamp,'2026-07-27 16:41:34.219184'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1279,2542,'광주 광산경찰서 수사팀장 박모 경감이 장윤기 사건의 핵심 증거인 SUV 내 케이블타이를 인멸한 혐의로 6일 긴급 체포됐다. 이 사건은 2023년 10월 여고생 납치·살해 사건으로, 수사팀장이 범죄 은폐를 위해 장윤기 아버지인 장모 경감과 유착해 증거를 인멸하고 수사 정보를 공유한 것으로 드러났다. 경찰청은 사건의 진상 규명을 위해 국가수사본부 산하 ''광주광산서 살인사건 관련 진상규명 특별수사팀''을 구성하고, 홍장득 총경이 팀장으로 지휘하며 총 27명의 수사관을 투입해 독립적 수사를 진행할 예정이다. 특별수사팀은 수사팀 형사 전원과 지휘 라인 간부도 조사 대상으로 삼으며, 사건의 진상과 책임 소재에 대한 최종 결과는 국가수사본부장에게 보고될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:29'::timestamp,'2026-07-27 16:45:23.030701'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1280,2583,'중국 인민해방군은 6일 태평양 공해에서 원자력 추진 잠수함에서 잠수함발사탄도미사일(SLBM)을 성공적으로 발사했다. 이는 인·태 지역에서 중국이 원잠 기반 SLBM으로 전략핵 타격 능력을 공개한 최초 사례로, 미국의 인도·태평양 동맹국인 일본·호주·뉴질랜드 등이 우려를 표하며 안정성 해치는 행위라고 지적했다. 발사는 미국 하와이에서 열리는 30개국 참여 림팩 훈련과 겹쳐졌으며, 중국은 사전 통보 없이 발사한 것으로 확인됐고, 일본은 재고를 요구했으나 중국이 수용하지 않았다. 이후 일본·호주·뉴질랜드는 중국의 군사력 증강과 투명성 부족을 문제 삼으며, 미국과의 동맹 강화 및 방위 산업 기반 확충 필요성을 강조했고, 미국 하원과 상원의원들은 중국의 핵 능력 확대에 대한 억제 전략과 국제 조약 체결의 시급성을 제기했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:35'::timestamp,'2026-07-27 17:17:11.569039'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1281,2543,'대구시의회는 6일 제326회 임시회에서 3선의 임인환 시의원(중구1·국민의힘)을 제10대 전반기 의장으로 단독 선출했다. 임 의장은 시민 중심 의회 구현을 약속하며 소통과 협치, 집행부와의 건강한 견제와 협력을 강조했다. 부의장은 이태손(달서구4·국민의힘)과 김재용(북구5·국민의힘)이 각각 제1·제2부의장으로 선출되었으며, 상임위원장과 운영위원장 선거는 7일과 8일에 각각 진행될 예정이다. 제10대 대구시의회는 총 36명으로, 국민의힘 34명, 더불어민주당 비례의원 2명으로 구성되어 있으며, 전반기 원 구성은 8일까지 완료될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:39'::timestamp,'2026-07-27 16:46:02.553644'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1282,2544,'2024년 5월 5일 전남 광주에서 여고생 살해 사건을 저지른 장윤기의 아버지(현직 경감)가 증거 인멸을 하고, 사건 담당 광산경찰서 수사팀장이 수사 정보를 유출한 정황이 확인되며 경찰 수사의 신뢰성에 의문이 제기됐다. 장윤기의 아버지는 아들의 자취방에 있던 리얼돌을 버리는 등 증거를 인멸했고, 수사팀은 피해자의 혈흔이 묻은 SUV를 돌려주고 아버지와 통화해 수사 진행 상황을 공유했다는 의혹을 받고 있다. 이에 따라 경찰청은 광주경찰청의 수사를 배제하고 반부패 수사 인력을 포함한 전담 수사팀을 구성해 수사를 진행하며, 홍석기 국가수사본부장은 ''한 점의 의혹 없이 진상을 밝히겠다''고 밝혔다. 현재 경찰은 수사팀장과 팀원 등 관련자에 대한 수사를 진행 중이며, 사건의 후속 조치로 감찰 결과와 언론 보도 내용을 종합해 책임 소재를 명확히 할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:45'::timestamp,'2026-07-27 16:42:48.065915'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1283,2548,'안규백 국방부 장관은 2024년 6월 10일 국군방첩사령부를 공식 해체하고, 삼군 사관학교 통합 및 전시작전통제권(전작권) 전환을 추진하며 군 개혁을 속도전으로 진행하고 있다. 이는 이재명 정부 출범 이후 국방부 장관급 공인에 대한 탄핵소추 청원이 약 24만 명을 돌파하며 정치적 논란을 일으키고 있으며, 전작권 전환은 군의 자주성과 전투력 강화를 위한 필요성으로 제기되고 있다. 그러나 예비역 장성들 및 군 전문가들은 개혁이 군 내부 합의 없이 정치적 목적에 따라 추진되며 방첩 역량 약화와 사관학교 통합의 전문성 훼손, 합동성 구현의 비현실성 등을 우려하고 있으며, 민간 자문위원 중 군 현장 경험이 부족한 점도 문제로 지적되고 있다. 현재까지 국방부는 개혁안에 대한 군 내부 의견 수렴을 충분히 하지 않았고, 사관학교 통합과 방첩사 해체의 정당성과 장기적 안보 영향에 대한 논의가 지속되고 있으며, 향후 국방개혁의 정책적 타당성과 군 내부 합의 수립 여부가 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:53'::timestamp,'2026-07-27 16:26:49.859482'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1284,2550,'제13대 경남도의회는 6일 개원일에 국민의힘 의원만 참석한 투표를 통해 전반기 의장(박준), 제1부의장(신종철), 제2부의장(이찬호)을 단독 선출하며 의장단을 싹쓸이했다. 이는 6·3지방선거에서 국민의힘이 44석, 민주당이 23석을 차지한 데 따른 다수당 지위를 바탕으로 한 것으로, 민주당은 의석 비율과 전례를 근거로 부의장 1석, 상임위원장 2석을 요구했으나 국민의힘은 부의장 1석, 상임위원장 1석만 제안하며 협상이 결렬됐다. 결과적으로 국민의힘은 단독으로 의장단 10명을 내정하고, 민주당은 협치 테이블을 요구하며 본회의장 퇴장과 항의 시위를 벌였으며, 개원식은 민주당 의원들이 참석한 가운데 진행됐다. 이후 7일 오후 2시 제2차 본회의에서 운영위원회 등 7개 상임위원회 위원장을 선출할 예정이며, 원 구성 협의는 여전히 결렬 상태로 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:36:59'::timestamp,'2026-07-27 16:44:06.906600'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1285,2557,'20대 간호사 A씨가 경기 광주 소재 병원에서 근무 중 약 1년간 직장 내 괴롭힘(태움)을 당한 뒤 지난 3월 병원을 그만두고 노동당국에 피해를 신고한 사건과 관련, 경기남부경찰청이 유족으로부터 제출받은 일기장과 휴대전화 등을 분석 중이다. A씨는 병원에서 선배 간호사로부터 지속적인 괴롭힘을 당하며 업무를 강요받았고, 이에 대해 노동당국에 진정을 제기했으며, 조사 결과 일부 사실로 인정되어 병원에 시정 지시가 내려졌다. A씨는 지난 2월 2일 자택에서 숨진 채 발견되었으며, 경찰은 유족과 대학 동창 등에게 참고인 조사를 진행하고 있으며, 현재까지 형사 입건된 사람은 없다. 경찰은 광역범죄수사대장을 팀장으로 하는 20명 규모의 수사전담팀을 구성해 증거 분석을 마친 뒤 입건 여부를 결정하고, 소환 조사를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:05'::timestamp,'2026-07-27 16:43:29.487119'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1286,2563,'2024년 6월 6일 러시아는 우크라이나 수도 키이우를 이스칸데르 탄도미사일 23발과 지르콘 극초음속 미사일 6발로 공격해 20명 이상 사망, 50여 명 부상시켰다. 이 공격은 패트리엇 미사일 시스템의 요격미사일 재고가 소진된 상태에서 발생했으며, 러시아는 속도 마하 7~9의 극초음속 미사일을 활용해 기존 방공체계를 회피했다. 현재 우크라이나는 패트리엇 시스템의 요격미사일이 전량 소진된 상태로, 탄도미사일 522발 중 70%가 방공망을 뚫고 들어오는 등 방어력이 크게 약화됐다. 미국과 유럽은 패트리엇 미사일 공급을 확대하고 있으며, 독일 신공장은 2024년 말 가동 예정이지만, 우크라이나는 자체 개발 미사일과 재정 지원을 통해 방어 체계를 회복할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:11'::timestamp,'2026-07-27 17:33:26.810573'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1287,2566,'중국은 6일 핵잠수함에서 잠수함발사탄도미사일(SLBM)을 처음으로 발사하며, 남태평양을 향해 발사한 것으로 확인됐다. 이는 중국이 미국 본토를 타격할 수 있는 JL-3 미사일을 상시 발사할 가능성을 시사하며, 대만 문제를 둘러싼 미·중 관계 악화와 트럼프 행정부의 대만 무기 판매 정책에 대한 압박 메시지로 분석된다. 발사 지점은 하이난섬 동쪽 해역으로 추정되며, 일본 EEZ도 포함된 설정 구역이 통보된 바 있으나, 실제 낙하 지점은 일본에서 멀리 떨어진 남태평양으로 확인됐다. 이번 발사는 미국과 일본, 필리핀 등에 중국의 해상 핵 위협이 상시화되고 있음을 시사하며, 향후 미·중 정상회담과 대만 문제 해결을 위한 외교적 긴장이 고조될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:17'::timestamp,'2026-07-27 17:32:48.105408'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1288,2574,'도널드 트럼프 미국 대통령은 2022년 카타르 월드컵 32강전에서 미국 대표팀 공격수 폴라린 발로건이 레드카드를 받고 퇴장한 후, FIFA 회장 잔니 인판티노에게 직접 전화해 출장정지 처분의 재검토를 요청한 사실을 인정했다. 발로건은 상대 수비수의 발목을 밟아 퇴장했으나, 트럼프는 이 플레이가 반칙이 아니라고 주장하며 슬로모션 영상이 판정을 왜곡했다고 비판했다. FIFA는 1962년 이후 64년 만에 처음으로 레드카드 퇴장 선수의 다음 경기 출전을 유예했으며, 이는 FIFA 규정의 적용에 대한 논란을 불러일으켰다. 트럼프의 개입은 FIFA의 독립성과 공정성에 대한 우려를 키우며, 향후 국제 스포츠 기구의 정치적 개입 방지 방안에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:22'::timestamp,'2026-07-27 16:54:00.228811'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1289,2580,'캐나다 정부는 60조원 규모의 초계 잠수함 프로젝트(CPSP)에서 독일 방산업체 TKMS를 우선협상대상자로 선정했다. 이 사업은 2035년까지 국방비를 GDP의 5%로 확대하는 캐나다의 방위력 강화 계획의 핵심이며, 냉전 이후 처음으로 신형 잠수함을 도입하는 것으로, 현재 작전 가능한 잠수함은 1척에 불과하다. 한화오션과 TKMS가 경쟁했으며, TKMS는 캐나다 GDP 860억 캐나다달러 증가와 65만개 이상의 고용 창출을 제안한 반면, 한화오션은 2만5000개 이상의 일자리와 700억 캐나다달러 이상의 투자 약속을 제시했다. 최종 계약 체결까지는 수년이 소요될 전망이며, 캐나다 정부는 우선협상대상자와 세부 협상을 거쳐 결정할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:28'::timestamp,'2026-07-27 16:56:33.468987'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1290,2581,'2024년 7월 6일 뉴욕 증시는 미국 독립기념일 휴장 이후 첫 거래일에 다우 평균이 사상 처음으로 5만3000선을 돌파하며 일제히 상승했다. AI에 대한 우려가 진정되면서 엔비디아, 애플, 아마존, 테슬라, 메타, 알파벳 등 대형 기술주가 강세를 보였고, 나스닥 지수는 1.1% 상승했다. 이날 다우 평균은 0.3% 상승하며 5만3000선을 처음 넘었으며, S&P500 지수는 0.7% 올랐고, 국제 유가는 브렌트유 배럴당 71.99달러, WTI는 68.55달러로 소폭 하락했다. 8일 연방준비제도는 지난달 회의 의사록을 공개해 금리 정책 방향에 대한 시장 예측을 유도하며, 10일 SK하이닉스의 미국 ADR이 나스닥에 상장될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:33'::timestamp,'2026-07-27 17:17:41.875496'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1291,2588,'도널드 트럼프 미국 대통령이 6일(현지 시각) FIFA 회장 잔니 인판티노와 통화해 미국 축구 대표팀 선수 폴라린 발로건의 레드카드 출전정지 처분 재검토를 요청한 사실이 공개되며 국제적 비판이 확산됐다. 발로건은 2일 미국과 보스니아 헤르체고비나의 32강전에서 상대 선수의 발목을 밟아 레드카드를 받았으나, FIFA는 다음 날 한 경기 출전 정지 처분을 1년 유예한다고 결정했다. 이에 유럽축구연맹(UEFA)은 ''전례 없고 이해할 수 없고 정당화할 수 없는 결정''이라며 FIFA의 권한 남용을 비판했고, 벨기에 부총리 겸 외무장관인 막심 프레보도 정치적 개입을 지적하며 스포츠 규칙 훼손을 우려했다. 현재 미국 내외에서 FIFA의 결정에 대한 신뢰 위기가 발생했으며, 트럼프의 개입 여부와 스포츠 기관의 중립성에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:39'::timestamp,'2026-07-27 17:07:49.821824'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1292,2589,'나토 사무총장 마르크 뤼터는 7일 튀르키예 앙카라에서 열리는 나토 정상회의에서 수백억 달러 규모의 신규 방산 계약을 발표할 예정이다. 이는 2035년까지 회원국이 GDP의 5%를 국방비로 지출하기로 한 2023년 헤이그 정상회의 합의의 이행 조치로, 유럽 동맹국과 캐나다가 이미 GDP의 약 4%를 국방에 투자하고 있는 상황에서 미국과의 지출 격차 해소를 목표로 한다. 이번 회의에서는 5% 목표 달성을 위한 구체적 계획과 헤이그 합의 이행 진척 상황이 점검되며, 미국은 이를 주요 의제로 다룰 예정이다. 이후 회원국들의 국방비 투자 계획 이행 여부와 나토의 방위 역량 강화 방향이 후속 논의의 핵심 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:43'::timestamp,'2026-07-27 17:02:38.228735'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1293,2590,'베네수엘라 라과이라주 카라바예다 지역에서 지난 5일 밤 9시쯤 지진 발생 후 267시간 만에 어린이 2명과 젊은 남성·여성 각 1명 등 4명의 생존자가 건물 잔해에서 구조됐다. 이 지진은 지난달 24일 발생해 수도 카라카스를 포함한 북부 6개 주를 강타했으며, 특히 해안가에 위치한 라과이라주가 가장 큰 피해를 입었다. 베네수엘라 정부에 따르면 이번 지진으로 최소 3342명이 사망하고, 1만6700명이 부상했으며, 생존자 구조는 골든타임(72시간)을 훨씬 초과한 267시간 만에 이뤄져 이례적인 사례로 평가된다. 현재 피해 복구와 생존자 치료가 진행 중이며, 정부는 추가 피해 조사와 국제 지원 요청을 예정하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:47'::timestamp,'2026-07-27 17:01:36.817293'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1294,2591,'미국 뉴욕 증시는 6일(현지 시각) 혼조세로 출발했으며, 다우지수는 0.15% 하락한 5만2818.29, S&P 500지수는 0.54% 상승한 7523.89, 나스닥 종합지수는 1.09% 상승한 2만6114.43을 기록했다. 반도체주가 지난주 부진 후 이날 반등하며 시장의 주요 동력이 됐으며, 브로드컴은 애플과 2031년까지 맞춤형 칩 공급 계약을 체결했다는 소식에 주가가 4.81% 상승했다. 웨스턴디지털, 시게이트, 마이크론 테크놀로지 등 메모리 반도체 업체와 ASML도 각각 11.28%, 7.75%, 4.42%, 5.02% 상승하며 반도체 섹터의 회복세를 이끌었다. 번스타인은 인공지능 수요에 따른 로직 반도체 및 디램 생산 능력 확대를 반영해 ASML의 목표 주가를 2300달러로 상향 조정했으며, 국제 유가는 2026년 8월 인도분 WTI 기준 배럴당 68.98달러로 강보합세를 유지했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:54'::timestamp,'2026-07-27 16:54:17.020713'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1295,2592,'도널드 트럼프 미국 대통령이 1월 1일 월드컵 32강전 직후 잔니 인판티노 FIFA 회장에게 전화를 걸어 미국 축구대표팀 공격수 폴라린 발로건의 출전 정지 징계 재검토를 요청했다. 발로건은 보스니아전에서 상대 수비수의 발목을 밟아 레드 카드를 받았고, 규정상 6일 벨기에전에 출전할 수 없었으나 FIFA는 징계는 유지하되 출전 정지 집행을 1년 유예하는 이례적인 조치를 취했다. 이는 월드컵 본선에서 출전 정지 집행 유예를 적용한 것이 1962년 이후 64년 만에 처음으로, FIFA의 독립성과 공정성에 대한 비판이 제기되고 있다. 벨기에축구협회는 법적 대응을 검토하며, 인판티노 회장과 트럼프 대통령 간의 긴밀한 관계도 논란의 중심에 서 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:37:59'::timestamp,'2026-07-27 16:39:00.327882'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1296,2594,'캐나다 정부는 차세대 잠수함 도입 사업인 초계잠수함 프로젝트(CPSP)의 우선협상대상자로 독일 TKMS를 선정한 것으로 전해졌다. CPSP는 캐나다 왕립 해군이 운용 중인 2400t급 빅토리아급 잠수함 4척을 2030년대 중반까지 최대 3000t급 디젤 추진 잠수함 12척으로 교체하는 대규모 사업으로, 도입 및 30년간 유지보수(MRO) 비용을 포함해 최대 600억 캐나다달러(약 60조원) 규모다. 한화오션과 HD현대중공업이 최종 경쟁자로 선정됐으나, 북대서양조약기구(NATO) 회원국인 독일과의 안보 협력 강화를 고려한 결정으로 분석되고 있다. 캐나다 정부의 공식 발표는 아직 이뤄지지 않았으며, 한화오션은 현지 상황 파악 중이며 공식 연락은 받지 않았다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:04'::timestamp,'2026-07-27 16:51:47.628862'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1297,2596,'중국 인민해방군은 6일 오후 1시 1분(한국시각), 태평양 공해를 향해 핵잠수함에서 잠수함발사 탄도미사일(SLBM)을 발사했다. 이번 발사는 중국의 연례 군사훈련 계획에 따른 것으로, 중국군은 훈련용 모의 탄두를 탑재하고 국제법과 관례에 따라 사전에 일본 등 관계국에 통보했다고 밝혔다. 일본 정부는 발사 약 1시간 반 전인 오전 11시 30분에 통보를 받았으며, 발사 구역은 오사카 남쪽 와카야마현 시오노미사키 남쪽 해역으로 지정됐다. 중국은 이전에 우주 쓰레기 낙하 구역이라고 통보했으나, 이후 탄도미사일 발사였다고 설명하며 일본의 안전 우려에 대한 반응을 보이지 않았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:10'::timestamp,'2026-07-27 16:45:34.012964'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1298,2597,'중국 해군은 6일 태평양 공해 해역에서 전략핵잠수함 발사 탄도미사일(SLBM)을 성공적으로 시험 발사했다. 이는 2024년 9월 태평양으로 대륙간탄도미사일(ICBM)을 발사한 지 1년 10개월 만이며, 미국·일본·호주가 포함된 서태평양 안보망을 겨냥한 것으로 분석된다. 중국군은 사전에 파푸아뉴기니, 뉴질랜드, 호주 등 태평양 주변국에 계획을 통보했으나, 발사한 미사일의 제원과 탄착 지점은 공개하지 않았다. 이번 발사는 중국의 해상 기반 핵보복 능력과 원해 작전 능력을 과시한 것으로, 미국 주도의 동맹망에 대한 압박 신호로 해석되며, 중러 ''해상연합-2026'' 연합훈련과의 직접적 연계는 확인되지 않았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:15'::timestamp,'2026-07-27 16:44:46.889380'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1299,2604,'도널드 트럼프 미국 대통령은 2024년 7월 튀르키예 앙카라에서 열리는 나토 정상회의를 앞두고, 이란 공습에 직접 참전하지 않은 유럽 동맹국들을 비판하며 ''충성''을 요구했다. 트럼프는 지난해 나토 회원국들이 2035년까지 GDP의 5%를 국방에 투자하기로 합의했지만, 미국이 주도한 이란 전쟁에 동맹국들이 기지 제공이나 병력 파견에 소극적이었다며 협조 부족을 지적했다. 이란 전쟁 당시 일부 회원국은 공격용 기지와 영공 사용을 제한했으며, 미 국방부는 유럽 주둔 미군의 전력 배치를 6개월간 재검토하고 공동기지 사용 및 병력 이동 권한을 명확히 보장받겠다고 밝혔다. 나토는 조약 5조에 따라 유럽·북미 회원국이 공격받을 경우 전체 동맹의 공격으로 간주하지만, 미국이 주도한 역외 군사작전에 자동 병력 파견 의무는 없으며, 앞으로 동맹의 협력 기준과 미국의 방어 의지에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:23'::timestamp,'2026-07-27 16:43:57.220135'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1300,2611,'2024년 2월 28일 미국과 이스라엘의 공습으로 사망한 이란 제2대 최고지도자 알리 하메네이의 국장 행사가 4일(현지 시각) 테헤란의 이맘 호메이니 대모살라 광장에서 시작됐다. 하메네이는 생후 14개월인 외손녀를 포함한 가족 4명과 함께 사망했으며, 그의 관은 검은 터번이 놓인 가장 높은 자리에 배치됐다. 행사에서는 ''미국에 죽음을'', ''피의 복수'' 등 반미 구호가 외쳐졌고, 중국·파키스탄·이라크·튀르키예·러시아 등 30개국이 조문단을 파견했으며, 유해는 6일 곰으로 이송된 후 이라크의 카르발라와 바그다드, 나자프에서 장례를 이어갈 예정이다. 하메네이의 후계자인 모즈타바 최고지도자는 공개 활동을 하지 않고 있으며, 장례 마지막 날인 9일 마슈하드에서 안장식에서 기도문 낭독을 계획하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:30'::timestamp,'2026-07-27 16:35:57.016798'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1301,2612,'도널드 트럼프 미국 대통령은 2024년 6월 4일 워싱턴 DC 내셔널 몰에서 열린 건국 250주년 기념 연설에서 공산주의를 ''암''에 비유하며 도려내야 할 위협으로 규정했다. 이는 민주사회주의가 미국 내에서 세력을 확장하고 있는 상황에서, 11월 중간선거를 앞두고 공화당이 좌파 이념을 견제하기 위한 이념 프레임 전략을 강화한 것으로 분석된다. 트럼프는 공산주의를 진주만 공격이나 9·11 테러보다 더 큰 위협으로 평가하며 민주당을 ''공산당''이라고 비판했고, JD 밴스 부통령도 뉴욕 관함식에서 민주사회주의를 비판하며 국가관에 대한 논쟁을 촉발했다. 이에 따라 민주사회주의자들의 복지 확대 주장과 맘다니 뉴욕시장의 에어컨 온도 조절 조치 등이 공산주의적 정책으로 비판받으며, 정치적 대립이 심화되고 있으며, 이는 중간선거를 앞두고 이념 대결이 더욱 격화될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:37'::timestamp,'2026-07-27 16:36:15.512375'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1302,2617,'도널드 트럼프 미국 대통령은 2023년 9월 4일 워싱턴 DC 내셔널 몰에서 열린 독립 250주년 기념행사에서 6·25 전쟁 장진호 전투 참전용사인 해병대 팻 핀 상병과 루디 미킨스 일병을 호명하며 그들의 희생을 기렸다. 장진호 전투는 1950년 11월 26일부터 12월 13일까지 진행된 것으로, 중공군의 포위망 속에서 미군이 2500명 전사, 8000명 동상 피해를 입는 등 약 1만8000명의 사상자를 냈으며, 생존자 수가 극히 적어 ''Chosin Few''으로 불린다. 트럼프는 이들의 전투를 ''치열한 전투''라 평가하며 반공산주의 메시지를 강조하며 ''공산주의는 암과 같다''며 미국의 공산주의 반대 입장을 재확인했다. 이어 트럼프는 3일 러시모어산 방문 시에도 공산주의에 대한 경계를 강조하며 독립 250주년을 계기로 미국의 정체성과 가치를 재확인하는 연설을 했으며, 기록적인 폭염과 뇌우 속에서도 야외 연설을 강행해 정치적 메시지를 전달했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:44'::timestamp,'2026-07-27 16:30:38.862144'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1303,2619,'미국 건국 250주년 기념 행사에서 도널드 트럼프 대통령의 연설과 불꽃놀이를 앞두고 워싱턴DC에 기록적인 폭염과 심각한 뇌우가 겹쳐 4일 저녁 관람객 수천 명이 긴급 대피 명령을 받았다. 행사 전날까지 폭염으로 기온이 40도에 육박했고, 이어 오후 10시까지 뇌우 주의보가 발령되며 보안 검색을 마친 시민들이 대피를 거부하는 등 혼란이 발생했다. 당국은 공공 안전을 이유로 보안 검색을 중단하고 대피 건물의 수용 capacity 초과 및 문 잠김으로 인해 현장 혼선이 지속됐으며, 이후 기상 상황 호전으로 오후 9시 45분부터 출입 재개를 발표했다. 트럼프 대통령은 소셜미디어를 통해 새벽 2시라도 연설을 하겠다며 행사 강행 의지를 밝히며, 약 85만 발의 불꽃놀이를 오후 11시에 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:50'::timestamp,'2026-07-27 16:28:49.261624'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1304,2621,'도널드 트럼프 미국 대통령은 2024년 6월 초, 자신의 이름을 딴 밈코인 ''$TRUMP''를 출시하고 지지층을 대상으로 구매를 유도한 결과, 코인 가격이 최고 75.35달러에서 현재 1.76달러로 약 97% 폭락하며 투자자 98만8905명이 총 38억1000만달러(약 5조9000억원)의 손실을 입었다. 트럼프는 이 코인 사업으로 6억3600만달러(약 9800억원)를 수익으로 신고했으며, 가족이 운영하는 암호화폐 업체 ''월드 리버티 파이낸셜''의 다른 코인 ''$WLFI''도 투자자 85%가 손실을 기록하는 등 유사한 구조를 보였다. 트럼프는 코인 거래 수수료와 지분을 통해 가격 하락에도 불구하고 수익을 확보하는 구조를 설계했으며, 대선 당시 가상화폐 반대 입장을 보였으나 취임 후 규제 완화와 함께 암호화폐 사업에 적극 참여했다. 이에 따라 투자자들의 집단소송 가능성과 정치적 이해충돌 논란이 확산되며, 향후 법적 조치와 규제 정책의 방향성에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:38:57'::timestamp,'2026-07-27 16:27:51.593337'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1305,2624,'이란의 알리 하메네이 전 최고지도자(2024년 2월 28일 사망)의 장례식이 4일부터 테헤란을 시작으로 9일 고향 마슈하드에서 안장되는 일정으로 진행된다. 하메네이의 시신은 사망 약 4개월 만인 2월 2일 테헤란 이맘 호메이니 모살라에 안치되었으며, 가족 4명(사위, 장녀, 며느리, 생후 14개월 손녀)의 관과 함께 전시되어 공격으로 일가족이 사망한 상황을 부각시켰다. 당국은 장례식을 통해 국민 결속과 항전 의지를 고취하고, 외신 취재 허용, 공개 행사 확대 등 선전을 강화했으나, 경제난과 지난 1월 반정부 시위 진압의 트라우마를 겪은 주민들은 세금 투입에 대한 불만을 표하며 참석을 거부하거나 강제 동원된다는 증언이 나왔다. 현재까지 장례식 참석은 공무원, 학생, 수감자까지 동원되며 강제성과 압박이 존재하고 있으며, 모즈타바 하메네이(후임 지도자)의 공개 부재로 권위에 의문이 제기되고 있어 향후 정권 안정성과 휴전 협상의 지속 가능성에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:05'::timestamp,'2026-07-27 16:23:39.212821'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1306,2625,'미국은 건국 250주년 기념 행사의 핵심 행사인 4일 워싱턴 DC 내셔널 몰에서 트럼프 대통령이 섭씨 40도 안팎의 폭염 속에서도 긴 연설을 예고했다. 이는 1898년 기록한 역대 최고 기온인 섭씨 38도를 상회하는 폭염이 지속되고 있는 동북부 지역에서 열리는 행사로, 기네스 기록 도전을 목표로 한 85만 발의 불꽃놀이와 군용기 에어쇼, 퍼레이드 등이 예정되어 있다. 그러나 박람회는 민주당 주지사가 이끄는 10여 곳의 불참과 전기 공급 문제, 높은 음식 가격(프레젤 25달러, 레모네이드 9달러) 등으로 인해 관람객 수가 기대에 못 미치고 있으며, 청중 감소 우려가 제기되고 있다. 이후 행사 운영 개선과 더위 대응 조치, 관람객 유치 전략이 후속 과제로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:11'::timestamp,'2026-07-27 16:23:37.328795'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1307,2628,'이란은 2월 28일 미국과 이스라엘의 공습으로 사망한 알리 하메네이 전 최고지도자의 장례식을 4일(현지 시각)부터 일주일간 테헤란과 곰, 마슈하드 등지에서 진행한다. 하메네이는 사망 후 약 4개월 만인 2일 테헤란 이맘 호메이니 모살라에 안치되었으며, 사위, 장녀, 며느리, 생후 14개월 손녀 등 일가족의 관도 함께 안치됐다. 이란 정부는 조문객으로 최대 2000만명이 모일 것으로 예상하며, 40개국 대표단과 100여 개 국제 단체가 참석했고, 러시아, 파키스탄, 아프가니스탄, 아르메니아, 사우디아라비아, 중국, 하마스, 헤즈볼라 등이 조문단을 파견했다. 이란은 장례식을 국가적 선전 행사로 활용하며 외신 취재를 선별적으로 허용하고, 국경 검문 강화와 비행 제한 등 최고 수준의 경비를 실시하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:17'::timestamp,'2026-07-27 16:24:21.881237'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1308,2630,'도널드 트럼프 미국 대통령은 2024년 7월 3일(현지 시각) 사우스다코타주 러시모어산을 방문해 독립기념일 기념 연설을 했다. 이는 그가 집권 1기 때인 2020년 독립기념일 전날 방문한 이후 6년 만이며, 11월 중간선거를 앞두고 지지층 결집을 위한 정치적 행보로 분석된다. 트럼프 대통령은 미국을 ''가장 오래된 공화국''이라며 민주사회주의를 ''공산주의''로 규정하고, 공산주의 위협에 맞서 냉전 승리 이후에도 미국의 정체성을 방어해야 한다고 강조했다. 그는 이란 협상에 대해 ''친절함''을 보였다는 점을 언급하며 주식시장 급등, 감세 정책, 무역적자 감소 등 경제 성과를 내세우며 ''미국의 황금기''를 선언했고, 이는 중간선거 전후 정치적 영향력 확대를 위한 전략으로 해석된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:22'::timestamp,'2026-07-27 16:24:32.905867'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1309,2633,'도널드 트럼프 미국 대통령은 이란의 아야톨라 알리 하메네이 전 최고지도자 장례식을 계기로 11일 파키스탄에서 대이란 제재, 동결 자산 해제, 핵 문제 등 핵심 사안을 논의하는 협상 재개를 전망했다. 이란은 4일 하메네이 전 지도자의 장례식을 시작하며, 미국과 이스라엘의 공습으로 인한 피해와 정치적 불안정이 지속되고 있으며, 이에 따라 외교적 접근이 필요하다는 평가가 나왔다. 트럼프는 장례식 기간을 ''협상 휴가''로 평가하며, 이스라엘 네타냐후 총리와의 회담을 다음 주 약 5개월 만에 재개할 수 있다고 밝혔고, 이는 이란 핵 협상 재개의 전조로 해석된다. 이후 나토 정상회의 참석을 앞두고 있으며, 이란 문제와 우크라이나 드론 작전 등이 주요 의제로 다뤄질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:27'::timestamp,'2026-07-27 16:27:08.419328'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1310,2640,'도널드 트럼프 미국 대통령은 2023년 7월 4일(현지 시각) 워싱턴DC 내셔널몰에서 열린 미국 건국 250주년 기념행사가 폭우로 인해 한때 취소된 후, 그 결정을 자신이 뒤집어 행사 재개를 지시했다. 이날 행사장에는 오후 7시 5분 기준 약 42만4000명이 모였으나, 악천후 예보로 인해 관람객들이 인근 건물로 대피했으며, 행사 재개 결정 후 약 15만명이 다시 행사장으로 복귀했다. 행사 재개로 인해 트럼프 대통령의 연설은 예정보다 약 1시간 30분 늦은 오후 11시 15분에 시작되었고, 자정 무렵 세계 최대 규모 기록을 시도한 40분간의 불꽃놀이가 진행됐다. 이후 워싱턴포스트는 행사가 폭염, 낙뢰, 대피령 등으로 인해 혼란스러운 하루였으며, 불꽃놀이가 끝난 직후 폭우가 쏟아져 극적인 마무리가 됐다고 보도했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:33'::timestamp,'2026-07-27 16:40:04.196169'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1311,2641,'미국은 4일(현지 시각) 건국 250주년을 기념해 워싱턴 DC 내셔널 몰에서 대규모 독립기념일 행사를 개최했으며, 도널드 트럼프 대통령은 악천후 속에서도 연설을 통해 ''공산주의 세력을 잘라내야 한다''며 반(反)공산주의 메시지를 강조했다. 행사 전날부터 미 동부 지역에 폭염(38도 이상), 강풍, 뇌우가 예보되며 퍼레이드는 취소되고, 행사장은 모래가 섞인 강풍과 폭우로 인해 대피 명령이 내려졌으며, 주최 측은 관람객 수천 명을 대피시켰다. 악천후에도 불구하고 약 86만 발의 폭죽을 사용한 불꽃쇼와 공군 특수비행팀의 비행, F-22 랩터, B-2·B-1B·B-52 등 핵심 전략 자산의 비행이 이어졌으며, 트럼프는 참전 용사와 가족을 추모하며 전쟁 역사와 미국의 안보 정체성을 강조했다. 트럼프의 연설에서 반공주의적 발언이 반복되며 정치적 논란이 제기되었고, 이는 향후 미국 내 정치적 대립과 외교 정책 방향성에 대한 논의로 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:40'::timestamp,'2026-07-27 16:31:33.226769'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1312,2643,'OPEC+는 8월에도 5개월 연속 원유 생산량을 늘릴 전망이며, 7월부터 호르무즈 해협 정상화로 인한 생산 회복이 시작될 것으로 예상된다. 이란전쟁으로 인한 호르무즈 해협 봉쇄로 인해 2024년 1분기부터 5월까지 사우디아라비아, 이라크, 쿠웨이트 등 주요 산유국의 원유 생산량이 하루 600만배럴 감소한 바 있다. 현재 해협 통항이 정상화되면서 7월부터 생산이 개선되며, 8월에는 회복세가 가속화될 것으로 보이지만, 내년에는 공급과잉이 발생할 가능성이 제기되고 있다. 이에 따라 OPEC+ 내부 결속이 약화될 수 있으며, 이라크는 생산 쿼터 증가 없이 탈퇴를 검토할 수 있다는 압박을 가하고 있어 협의체의 지속 가능성에 대한 우려가 커지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:45'::timestamp,'2026-07-27 16:32:32.319581'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1313,2644,'미국 워싱턴DC에서 5일(현지시각) 열린 건국 250주년 기념행사 ''미국에 바치는 헌사''에서 약 85만발의 불꽃놀이가 악천후와 낙뢰에도 불구하고 예정대로 진행됐다. 이번 행사에서는 링컨기념관 반사연못, 포토맥강 바지선, 웨스트 포토맥 공원 등 10개 지역에서 불꽃놀이를 펼쳐 예년 독립기념일 행사보다 규모를 대폭 확대했으며, 사상 최대 규모로 기네스 세계기록 도전 가능성도 제기됐다. 행사 비용은 약 85만달러(13억원)로 추산되었고, 도널드 트럼프 미국 대통령은 기념 연설을 통해 행사에 참석하며 ''역대 최고의 불꽃놀이''라고 평가했다. 현재 불꽃놀이가 기네스 기록을 경신했는지 여부는 공식적으로 검증되지 않았으며, 관련 기록 인증 절차가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:50'::timestamp,'2026-07-27 16:32:23.587924'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1314,2645,'도널드 트럼프 미국 대통령은 2023년 7월 4일 워싱턴DC 내셔널몰에서 열린 미국 건국 250주년 기념식 연설에서 공산주의를 ''암''에 비유하며 반공 메시지를 강조했다. 그는 6·25전쟁 참전용사인 패트릭 핀 해병대 병장과 루디 미킨스 일병을 소개하며 미국의 전사들이 공산주의와 싸워왔다고 강조했고, ''SAVE 법''의 통과를 촉구하며 유권자 신분증 제시와 우편투표 제한 등을 포함한 유권자 신분 강화 정책을 내세웠다. 트럼프 대통령은 미국의 군사력 강화를 내세우며 베네수엘라와 이란의 군대를 궤멸시켰다고 주장했고, 11월 중간선거를 앞두고 정치적 메시지를 전달했다. 이 연설은 역대 독립기념일 연설과 달리 당파적 성향을 드러내며 정치적 호소가 강조된 것으로 평가받고 있으며, 향후 중간선거와 SAVE 법의 처리 과정이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:39:55'::timestamp,'2026-07-27 16:31:09.633869'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1315,2646,'미국 건국 250주년을 맞아 프랑스, 독일, 영국, 이스라엘, 아랍에미리트, 사우디아라비아, 인도, 일본 등 세계 각국 정상들이 축하 메시지를 보내며 미국과의 동맹 및 협력 관계를 강조했다. 이는 미국이 자유와 민주주의, 책임을 기반으로 세워진 국가라는 점과 대서양 동반자 관계의 중요성을 부각하기 위한 것으로, 프랑스 파리 에펠탑, 독일 베를린 브란덴부르크문 등 주요 상징물에 미국 국기 색상 조명을 점등하며 기념했다. 영국, 프랑스, 독일 등 주요 동맹국과 이스라엘, 아랍에미리트 등 중동 국가들이 미국의 번영과 자유의 수호를 기원하며, 인도와 일본은 민주주의와 법치, 역사적 교류를 기반으로 한 협력 강화를 약속했다. 이와 함께 러시아, 우크라이나, 카타르, 파키스탄 등 분쟁 당사국 및 중재국도 축하 메시지를 발표하며 국제적 공감대를 형성했으며, 교황도 종교의 자유를 미국의 핵심 가치로 평가하며 기념 분위기를 뒷받침했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:02'::timestamp,'2026-07-27 16:30:11.604813'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1316,2648,'도널드 트럼프 미국 대통령은 2024년 6월 4일(현지시각) 폭염과 폭풍우 예보에도 불구하고 워싱턴DC 내셔널몰에서 예정된 미국 건국 250주년 기념 연설과 불꽃놀이 행사를 강행하겠다고 밝혔다. 기상청은 해당 일자에 강수 확률이 높고, 기념행사가 열릴 예정이던 내셔널몰 지역에 폭풍우가 예상되며, 행사 일정이 연기될 가능성이 제기된 상황이다. 행사 주최 측 ''프리덤 250''는 원래 연설은 오후 9시 45분, 불꽃놀이는 오후 10시 30분으로 예정했으나, 기상 상황에 따라 시작 시간이 크게 지연될 수 있다고 밝혔다. 트럼프 대통령은 기상 조건을 무시하고 행사 진행을 강행하겠다는 의지를 밝히며, 지난달 14일 백악관 앞 UFC 행사에서도 비가 예보됐지만 실제로는 비가 내리지 않았다고 언급하며 행사 지연에 대한 우려를 일축했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:07'::timestamp,'2026-07-27 16:29:14.861378'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1317,2650,'미국 동부를 강타한 폭염과 예보된 폭풍우로 2024년 7월 4일 워싱턴DC 내셔널몰에서 예정된 ''미국에 바치는 헌사'' 행사와 ''위대한 미국 박람회''가 연기됐다. 이는 도널드 트럼프 대통령의 기념 연설과 대규모 불꽃놀이가 포함된 건국 250주년 기념행사로, 악천후 예보에 따라 참가자들이 박물관과 관공서로 대피하는 조치가 취해졌다. 행사 주최 측인 ''프리덤 250''은 폭풍우와 낙뢰로 인한 안전사고 위험을 이유로 연기를 결정했으며, 보스턴의 불꽃놀이 행사도 동일한 이유로 연기됐다. 이후 행사 일정은 기상 상황에 따라 재조정될 예정이며, 백악관은 트럼프 대통령의 연설은 예정대로 진행될 수 있다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:17'::timestamp,'2026-07-27 16:28:00.300805'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1318,2652,'미국은 1776년 7월 4일 독립선언서 채택을 기념해 250주년 기념행사를 워싱턴DC 내셔널몰에서 개최했다. 이번 행사에는 도널드 트럼프 대통령의 기조연설과 미 공군 편대 비행, 군악대 공연, 약 40분간 85만발의 폭죽을 쏘아 올리는 불꽃놀이가 포함되었으며, 기네스 세계기록 경신을 목표로 했다. 행사 당일 미국 동부를 강타한 폭염으로 인해 워싱턴DC 독립기념일 퍼레이드가 취소되었고, 코네티컷, 일리노이, 매사추세츠, 오리건 등 민주당 지지 주들은 ''위대한 미국 박람회''에 불참하며 정치적 분열이 드러났다. 트럼프 대통령은 연설에서 미국의 성과와 국가 정체성, 미래 비전을 강조했으며, 부통령 JD 밴스는 국가 통합을 촉구하며 정치적 갈등을 지적했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:22'::timestamp,'2026-07-27 16:27:34.742230'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1319,2654,'도널드 트럼프 미국 대통령은 2024년 7월 3일(현지시각) 미국 건국 250주년 기념일을 하루 앞두고 볼로디미르 젤렌스키 우크라이나 대통령과 전화 통화를 했다. 이는 트럼프가 2024년 6월 G7 정상회의에서 우크라이나의 장거리 드론 작전에 대해 긍정적인 반응을 보였고, 러시아 에너지 부문에 대한 추가 제재에 동의한 이후의 행보로 이어졌다. 통화 내용은 구체적으로 공개되지 않았으나, 트럼프 행정부가 우크라이나 지원에 대한 태도를 재확인한 것으로 해석된다. 이후 트럼프 행정부의 우크라이나 정책 방향성과 향후 미국의 군사·경제 지원 여부가 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:26'::timestamp,'2026-07-27 16:27:18.630798'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1320,2656,'미국과 이란은 아야톨라 하메네이 전 이란 최고지도자의 장례식이 종료된 후 파키스탄에서 종전 후속 협상을 재개할 예정이다. 하메네이의 장례는 4일부터 6일간 진행되며, 이 협상은 대이란 제재 해제와 동결 자금 해제, 핵 협상 재개를 핵심 과제로 삼는다. 이전 도하에서 진행된 간접 회담에서 양국은 제재 완화와 일부 동결 자금 해제에 합의했으며, 트럼프 전 대통령은 회담을 ''매우 좋았다''고 평가했다. 이후 협상 재개를 위한 준비가 진행 중이며, 파키스탄에서의 회담은 11일 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:30'::timestamp,'2026-07-27 16:25:56.519240'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1321,2663,'국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 14일 1차 청문회에 중앙선관위원 전원을 포함해 행정안전부·경찰·국방부 관계자 등 총 97명을 증인으로 채택했다. 이는 2023년 자녀 채용 비리 논란과 2022년 서울 구로구 개표 오류, 군 거소투표 이중투표, 잠실 올림픽공원 투표함 반출 시위 충돌 등 다수의 선거 관련 이슈를 조사하기 위한 조치다. 증인 명단에는 박찬진 전 사무총장, 송봉섭 전 사무차장, 김필곤·김창보·이승택·정은숙 전 상임위원, 유재성 경찰청장 직무대행, 김태훈 검경합동수사본부장 등이 포함되었으며, 행정안전부·국방부 실무자도 포함됐다. 여당과 야당의 협의를 거쳐 윤호중 행정안전부 장관, 안규백 국방부 장관에 대한 증인 채택 여부는 추후 결정될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:36'::timestamp,'2026-07-27 18:52:02.110168'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1322,2666,'청와대는 반도체 산업 호황으로 발생하는 추가 세수를 활용해 ''미래대응기금''을 신설할 계획이며, 8월 정부 예산안 편성 시기에 맞춰 구체적 사용 방안을 공개할 예정이다. 이 기금은 잠재성장률 반등, K자 양극화 완화, 지방균형발전, 청년 주거·일자리 문제 해결 및 교육 개선을 위한 정책 재원으로 사용될 예정이며, 정부의 3대 메가프로젝트 인프라 투자도 주요 용처로 포함된다. 기금은 특별법을 통해 신설되며, 현재 청년 정책의 대대적 재편과 지방균형발전 프로그램 마련을 위한 준비가 진행 중이다. 이후 기금의 세부 지출 항목과 예산 배분 방식에 대한 정책 논의와 국회 심의 절차가 예정되어 있으며, 이는 8월 이후 본격화될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:40'::timestamp,'2026-07-27 18:42:39.539970'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1323,2649,'푸틴 러시아 대통령은 미국 독립 250주년을 맞아 도널드 트럼프 미국 대통령과 85분간 전화 통화를 진행하며 우크라이나 전쟁 해결과 양국 관계를 논의했다. 이는 트럼프 대통령이 다음 주 튀르키예에서 열리는 NATO 정상회의를 앞두고 우크라이나 전쟁 해결을 위한 중재 노력을 지속하겠다는 입장을 밝힌 데 따른 것으로, 미국 특사인 스티브 윿코프와 재러드 쿠슈너가 모스크바 재방문을 준비 중임을 전달했다. 통화에서 푸틴은 우크라이나 동부 코스티안티니우카 장악을 주장하며 하르키우와 수미 지역의 안보 완충지대 확대를 예고했으나, 우크라이나는 이를 ''러시아의 거짓말''로 반박했다. 이후 트럼프 대통령은 젤렌스키 우크라이나 대통령과도 통화를 나누며 전쟁 문제를 논의했으며, 푸틴의 전선 방문과 군사적 발언은 국제사회에서 우크라이나 전쟁의 지속 가능성과 외교적 접근의 방향성에 대한 논의를 촉발하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:45'::timestamp,'2026-07-27 16:28:15.962305'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1324,2667,'국정조사특위는 6·3 지방선거 투표용지 부족 사태 발생 직후 중앙선관위 상황실의 늑장 대응과 고질적 업무 태만을 질타했다. 사태는 6월 3일 오후 4시 25분에 최초 인지되었으나, 투표관리관들에게 문자 안내까지 1시간 30분 이상 소요되며 상황실의 비효율적 운영이 문제로 지적됐다. 조사 과정에서 송파구 잠실 올림픽공원 핸드볼경기장에 보관된 투표용지의 이송 전 공개 재검표 가능성도 논의되었으며, 여야는 국무위원 증인 채택 문제로 공방을 벌였다. 이후 여야 간사 협의를 통해 후속 절차를 논의하고 있으며, 특검 도입 여부와 청와대·행안부의 개입 여부가 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:50'::timestamp,'2026-07-27 18:42:17.768418'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1325,2669,'전분당 가격 담합 혐의로 사조CPK, 삼양사, 동아제약, 한미약품 등 4개사가 2018년 5월부터 2025년 9월까지 13차례에 걸쳐 가격을 조정한 결과, 공정거래위원회는 역대 최대인 7,476억 원의 과징금을 부과했다. 이들은 옥수수 원가 변동을 명분으로 납품가를 조정하고, 사전에 목표가격을 합의한 뒤 협상 주관사가 이를 제시하고 나머지 기업이 가격을 높이도록 압박하는 방식으로 담합을 지속했다. 전분당 평균 가격은 1kg당 559원에서 최고 971원까지 상승하며 73% 이상 인상되었고, 이로 인해 관련 매출액은 6조 원을 초과했다. 현재 공정거래위원회는 추가로 대형 실수요처 입찰 과정에서의 투찰가 및 물량 합의, 전분당 부산물 판매 가격 담합 혐의에 대해 심의 중이며, 관련 매출액 1조 5,500억 원에 대해 최대 20% 과징금 부과 가능성이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:40:56'::timestamp,'2026-07-27 18:54:03.564119'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1326,2672,'홈플러스는 2024년 5월 말 기준 공익채권 규모가 1조999억원으로, 지난해 3월 회생절차 개시 당시보다 7,671억원 증가했다. 이는 미지급 납품 대금(7,940억원), 긴급운영자금(DIP) 채권(1,614억원), 제세공과금(820억원), 미지급 급여(625억원) 등으로 구성됐으며, 지난달 익스프레스 매각으로 1,206억원의 현금을 확보했으나 질권 설정으로 실제 활용 가능한 자금은 756억원에 그쳤다. 이 중 650억원은 4~5월 급여 지급에 사용되었고, 6월 급여 250억원이 추가 발생하면서 공익채권은 6월 말 기준 약 1조800억원 수준으로 추산된다. 현재 2천억원 규모의 신규 자금 조달이 논의되고 있으나, 공익채권 우선 변제 원칙상 자금 대부분이 기존 채권 상환에 투입될 전망이며, 대주주인 MBK파트너스의 직접적 개입이 임금 체불 및 협력사 피해 최소화를 위한 핵심 과제로 지적되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:03'::timestamp,'2026-07-27 18:50:11.699864'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1327,2678,'삼성전자는 2024년 2분기 영업이익 8조9000억원을 기록하며 엔비디아를 넘어 글로벌 테크기업 중 분기 영업이익 최고 기록을 세웠다. 이는 엔비디아가 전년 2월~4월에 기록한 약 8조1900억원을 상회하는 수치로, 삼성전자의 역대 최고 실적이다. 이 실적에는 노사 협상에서 합의된 성과급 충당금 약 20조원이 반영되어 있으며, 충당금을 제외하면 영업이익이 110조원에 육박할 것으로 분석된다. 삼성전자는 하반기에도 이 같은 성장세를 유지할 수 있을지, 그리고 성과급 충당금의 재무적 영향이 장기적으로 어떻게 작용할지 시장의 주목이 집중되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:07'::timestamp,'2026-07-27 18:36:33.423703'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1328,2679,'국세청은 ''한강 벨트'' 지역의 30억 원 이상 고가 주택 거래를 대상으로 한 세무조사를 통해 80여명의 부동산 탈세를 확인하고 총 731억 원의 누락 세금을 드러냈다. 이는 부모로부터 증여받은 자금을 은폐하거나 가장 매매를 통해 1세대 1주택 비과세를 악용하는 등 자금 출처 누락과 매매 방식을 통한 세금 회피가 주요 탈루 수법이었다. 조사 결과, 318억 원의 세금을 추징하고 부당 과소신고에 대해 40%의 가산세를 부과하며, 6명은 검찰 고발, 4명은 7억 원 상당의 벌금 통고처분을 받았다. 국세청은 향후 부동산 거래 전 과정에 대한 지속적인 세무조사와 신고센터 제보자에 대한 포상금 신속 지급을 계획하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:11'::timestamp,'2026-07-27 18:32:39.624829'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1329,2682,'검찰은 장윤기 부실 수사 의혹과 관련해 광주 광산경찰서 형사들의 주거지 압수수색을 포함한 강제수사를 진행하며, 유착 의혹과 공무상비밀누설, 증거인멸 혐의를 수사 중이다. 이는 수사 초기 발견됐던 결박 도구인 케이블 타이가 사라진 점과 수사 지휘 체계에서 강간살인 혐의가 반영되지 않은 점 등에서 비위 의심이 제기된 데 따른 것으로, 특별수사팀이 수사 담당을 맡았다. 현재까지 케이블 타이는 확보되지 않았으며, 이는 장윤기 사건의 강간살인죄 적용 여부에 직접적인 영향을 미칠 수 있는 핵심 증거로 평가되고 있다. 검찰은 수사팀장에 대해 구속영장을 신청했고, 장윤기 아버지의 친족 특례 형사처벌 제외 가능성과 경찰 간부 출신이라는 점이 징계 수위에 영향을 미칠 것으로 보이며, 향후 보완수사와 징계 절차의 공정성에 대한 사회적 관심이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:19'::timestamp,'2026-07-27 18:55:42.633659'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1330,2690,'광주지검은 장윤기 사건 수사팀장인 박 모 경감과 팀원 1명을 대상으로 압수수색을 실시했다. 이는 장윤기 아버지와의 유착 정황과 공무상비밀누설, 증거인멸 혐의가 제기되면서 검찰이 정식 수사에 들어간 결과로, 광주광산경찰서와 관련자 주거지 등이 압수수색 대상이 됐다. 박 경감은 경찰청 국가수사본부에 의해 긴급체포되었으며, 케이블타이 등 핵심 증거가 누락되고 현장검증 영상이 검찰로 송치되지 않은 점 등이 증거인멸 정황으로 확인됐다. 검찰은 압수물 분석과 관련자 소환을 진행할 예정이며, 검찰과 경찰의 동시 수사로 인해 검경 간 수사 경쟁 구도가 확대되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:24'::timestamp,'2026-07-27 18:41:12.580737'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1331,2692,'러시아와 우크라이나의 전쟁이 2024년 3월 1일 키이우 공습 이후 다시 격화되고 있으며, 4월 6일 우크라이나군은 러시아 옴스크 정유 공장을 드론으로 타격해 전쟁 발발 후 최장거리 공격을 수행했다. 이는 패트리어트 요격 미사일 재고 부족으로 키이우가 러시아 탄도미사일 공격에 노출된 상황에서, 우크라이나가 후방 에너지 시설을 공격해 반격하는 전략으로 이어졌다. 러시아는 민간인 시설을 겨냥한 공습을 강화하며 양측 충돌이 심화되었고, 3월 1일 공습만으로도 최소 26명이 사망하는 등 피해가 누적되고 있다. 트럼프 미국 대통령은 4월 7일부터 열리는 나토 정상회의에서 우크라이나 전쟁 종식을 논의할 예정이며, 젤렌스키 대통령과의 양자 회담을 통해 전쟁 종식을 위한 돌파구 마련이 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:29'::timestamp,'2026-07-27 18:54:41.756730'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1332,2698,'베네수엘라 라과이라 지역에서 발생한 연쇄 강진으로 사망자가 3,500명을 넘었으며, 실종자는 최대 5만 명으로 추정된다. 이 지진은 2024년 4월 24일에 발생했으며, 구조 활동은 골든타임을 훨씬 초과한 11일째에 접어들어 대부분 중단된 상태다. 현지 주민들은 맨손으로 콘크리트를 뚫으며 가족을 찾는 수색을 이어가고 있으나, 생존자 구조는 거의 불가능한 상황이다. 일부 소셜미디어에서 11일째에 어린이 4명이 구조됐다는 보도가 있었으나, 이는 과거의 장면을 오보로 잘못 전달한 것으로 확인됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:33'::timestamp,'2026-07-27 18:37:44.853869'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1333,2701,'도널드 트럼프 미국 대통령 행정부는 2022년 카타르 월드컵 32강전에서 레드카드를 받은 미국 축구대표팀 공격수 폴라린 발로건의 16강전 출전정지 처분에 대해 FIFA에 직접 압박한 것으로 확인됐다. 발로건은 2일 미국-보스니아 헤르체고비나전에서 상대 선수의 발목을 밟아 레드카드를 받았으며, 이로 인해 6일 벨기에전 출전이 불가능한 상황이었다. 트럼프 행정부는 하워드 러트닉 상무장관과 앤드루 줄리아니 백악관 월드컵 태스크포스 책임자 등이 참여해 법적 대응과 FIFA에 대한 직접 압박을 추진했고, 트럼프 대통령은 잔니 인판티노 FIFA 회장에게 직접 전화를 걸어 판정 재검토를 요청했다. 이후 FIFA는 규정 제27조를 적용해 징계 집행을 1년 유예하는 결정을 내리며, 이에 트럼프 대통령은 5일 트루스 소셜을 통해 감사를 표했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:39'::timestamp,'2026-07-27 18:24:50.076309'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1334,2707,'이재명 대통령은 2024년 6월 25일 경기도 수원컨벤션센터에서 열린 6·25전쟁 제76주년 기념식에서 참전용사들의 희생을 기리며 국가의 평화와 번영이 그들의 헌신에서 비롯됐다고 강조했다. 76년 전 대한민국은 전쟁의 위기 속에 있었으며, 학도병과 평범한 시민들이 총을 들며 국토를 지키는 희생을 감행했고, 이는 오늘의 민주주의와 번영의 기반이 됐다. 최근 시행된 참전유공자법 개정으로 유족까지 보훈단체 회원 자격이 확대되었으며, 고 김장성, 이영복, 고 전하정 등 3명의 비정규군 공로자에게 신규 포상이 진행됐다. 이 대통령은 영웅들의 헌신을 기리는 것이 국가의 책무이며, 유엔 참전용사에 대한 감사와 국제적 책임을 강조하며, 앞으로도 보훈 제도를 강화해 후대에 이어질 수 있도록 하겠다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:45'::timestamp,'2026-07-27 16:15:08.039833'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1335,2708,'북한은 2024년 5월 23일 남포항에서 5000t급 신형 구축함 ''최현호''의 취역식을 개최하고, 김정은 국무위원장이 참석해 실전 배치를 발표했다. 이는 북한이 해군의 핵무장화와 대형 수상함 건조를 통해 해상 전력 강화를 가속화하고, 연안 방어에서 벗어나 원해 전략 타격 능력을 갖추겠다는 의지를 재확인한 것으로, 지난 노동당 전원회의에서 핵보유 정당화와 함께 이어진 전략적 전환이다. 김정은은 앞으로 5년간 1만t급 전략유도탄순양함과 5000t급 이상 수상함을 매년 2척씩 건조하고, 호위함 및 수중 무기체계도 개발하겠다고 밝혔으며, 이에 따라 ''강건호''도 조만간 동해함대에 배치될 전망이다. 이에 따라 한·미·일 해상 방어체계에 대한 북한의 ''반접근/지역거부(A2/AD)'' 전략 가능성과 중국·러시아 해군과의 연합훈련 가능성 등이 국제사회에서 주목받고 있으며, 북한의 기술적 진보 여부와 실질적 운용 능력은 검증이 필요한 과제로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:52'::timestamp,'2026-07-27 16:14:49.429291'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1336,2714,'정동영 통일부 장관은 2026 국제 한반도 포럼에서 도널드 트럼프 미국 대통령이 SNS에 2018년 싱가포르 미·북정상회담 사진을 올린 것을 계기로 미·북 정상 간 친서외교 재개 가능성을 제기했다. 이는 트럼프 대통령이 2018년과 2019년 회담 전후로 김정은 북한 국무위원장과 친서를 주고받으며 개인적 유대를 유지했던 사례를 상기시킨 것으로, 최근 사진 게시가 친서 외교의 시동일 수 있다는 분석이다. 정 장관은 2018년 하노이 회담에서의 ''노딜'' 실패를 언급하며 한반도 평화공존을 위해 과거 실패를 반면교사로 삼아야 한다고 강조했고, 윤석열 정부의 대북 적대·대결 정책을 청산하고 민주 정부의 평화 유산을 계승해야 한다고 밝혔다. 현재까지는 구체적 친서 교환 사실은 확인되지 않았으나, 미·북 대화 재개 가능성에 대한 기대감이 제기되며, 향후 대화 재개 여부와 한반도 정세 전환 여부가 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:41:58'::timestamp,'2026-07-27 16:14:07.780526'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1337,2715,'정동영 통일부 장관은 2026 국방백서에서 북한을 ''주적''으로 규정하는 방안에 대해 국방부와 통일부 간 이견이 발생하자, 국가안전보장회의(NSC)에서 논의해야 한다고 밝혔다. 이는 전임 윤석열 정부 시기 국방백서가 북한을 ''적''으로 규정한 것과 달리, 이재명 정부가 추구하는 남북 평화 공존 기조에 부합하도록 수정해야 한다는 주장의 일환으로, 통일부는 북한과의 평화 공존을 가능하게 하기 위해 주적 규정을 재검토해야 한다고 강조했다. 현재까지 국방부는 북한을 주적으로 유지하되, 통일부는 이를 평화적 접근에 맞게 조정해야 한다는 입장으로, NSC 상임위원회에서 이 문제에 대한 논의가 예정되어 있다. 이후 NSC에서의 논의 결과에 따라 국방백서의 북한 관련 표현이 수정될지 여부가 결정될 전망이며, 이는 남북 관계의 방향성과 국방 정책의 근본적 변화를 의미한다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:03'::timestamp,'2026-07-27 16:13:21.165779'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1338,4604,'더불어민주당 한병도 당대표 직무대행은 6·3 지방선거 서울 송파구 올림픽공원 핸드볼경기장에 보관된 247만장의 투표용지에 대해 여야 협의를 통해 재검표 및 수개표를 추진할 방안을 적극 검토하겠다고 7일 밝혔다. 이는 국민의힘 윤상현 국조특위 위원장이 공개 재검증을 제안한 데 대한 반응으로, 선거 참정권 침해 진상 규명과 국민 신뢰 회복이 핵심 목표다. 현재까지 국민의힘은 특검법안을 야당 단독 추천 방식으로 추진하려는 입장이며, 이로 인해 상임위와 법사위를 통과한 법안 59건이 본회의 문턱에서 정지된 상태다. 한 원내대행은 9일 조정식 국회의장에게 민생법안 처리를 위한 본회의 개최를 요청할 예정이며, 국민의힘의 상임위 보이콧을 ''민생 보이콧''으로 규정하며 즉각적인 법안 처리를 촉구했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:09'::timestamp,'2026-07-27 18:23:36.580793'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1339,2717,'국방부는 2026 국방백서에서 북한 정권과 북한군을 ''적''으로 규정할 방침을 유지하겠다고 밝혔다. 이는 북한이 대남 핵타격 전력을 증강하며 적대적 관계를 고수하고 있다는 판단에서 비롯된 것으로, 국방부는 과거와 마찬가지로 주적 개념을 유지할 것임을 강조했다. 반면 통일부는 남북 평화공존을 정책 목표로 삼고 있으며, 주적 개념과 이 목표가 모순된다고 지적하며 표현 수정을 요구했다. 현재 국방부와 통일부는 주적 표현 유지 여부를 두고 정책적 입장 차이를 드러내며, 향후 정부 차원의 협의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:13'::timestamp,'2026-07-27 16:12:06.875256'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1340,2719,'이재명 대통령은 16일(현지시간) 프랑스 에비앙에서 열린 G7 정상회의에서 도널드 트럼프 미국 대통령과 한반도 평화와 북핵 문제, 중동 정세 등을 논의했다. 이 대통령은 트럼프 대통령의 이란 핵 합의 성과를 축하하며, 한반도 지속 가능한 평화 정착을 위해 미국의 역할을 요청했고, 트럼프 대통령은 이를 위한 필요 역할을 하겠다고 밝혔다. 양 정상은 호르무즈 해협의 항행 안전성과 중동 안정이 국제 유가 및 세계 경제 회복에 기여할 수 있다는 데 공감했으며, 한미일 협력과 한미동맹 강화의 중요성도 재확인했다. 이후 두 정상은 공식 만찬 및 G7 회의 기간 중 여러 차례 접촉하며 친밀한 관계를 유지하고, 한반도 평화와 역내 안보 증진을 위한 협력 방안을 지속적으로 논의할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:18'::timestamp,'2026-07-27 16:11:50.548413'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1341,2726,'이재명 대통령은 14일(현지시간) 이탈리아 로마 성바오로대성당에서 열린 ''평화와 연대를 위한 특별미사''에 참석해 남북 평화체제 구축을 위한 정책 추진 의지를 재확인했다. 이는 앞서 유럽연합(EU) 정상회의 공동성명 발표 후 북한이 ''적대적 두 국가 관계 고착화''를 비판한 상황에서 나온 것으로, 정전 상태를 넘어 지속가능한 평화 체제를 구축하겠다는 입장을 명확히 한 것이다. 이 대통령은 대북 확성기 방송 중단 등 선제적 긴장 완화 조치와 흡수통일이나 일방적 체제 경쟁을 지양하겠다는 입장을 반복하며, ''칼을 쳐서 낫을 만들자''는 이사야서의 메시지를 통해 평화적 협력의 필요성을 강조했다. 이후 이 대통령의 이탈리아 국빈방문을 계기로 진행된 특별미사는 유흥식 추기경이 집전했으며, 이는 남북 평화 정책의 외교적 지지 확보를 위한 전략적 행보로 해석된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:23'::timestamp,'2026-07-27 16:10:38.285662'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1342,2727,'트럼프 미국 대통령이 2018년 6월 12일 싱가포르에서 열린 제1차 북미정상회담 당시 김정은 북한 국무위원장과 함께 산책하는 사진을 SNS에 공개하며 북한 문제에 대한 관심을 재부각시켰다. 이는 트럼프 대통령이 14일(미국 현지시간) 이란과의 종전 및 비핵화 합의 서명을 예고한 직후로, 이란 문제 해결 후 북한 문제로의 관심 전환 가능성을 시사한 것으로 해석된다. 2018년 1차 회담에서 양국은 한반도 완전한 비핵화와 평화체제 구축을 합의했으나, 2019년 2차 회담에서 이행 방안 합의 실패로 인해 합의는 표류했고, 북한은 이후 핵무력 증강을 지속해왔다. 트럼프 대통령은 현재까지도 김정은과의 대화 가능성에 대해 열린 태도를 유지하고 있으며, 2024년 5월 중순 예정된 방중 계기에서 회담이 성사될 가능성에 대한 논의가 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:29'::timestamp,'2026-07-27 16:10:24.168802'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1343,2728,'북한 외무성은 13일 한국과 유럽연합(EU)이 10일 브뤼셀 정상회담에서 채택한 공동성명을 ''체제존중''과 ''적대행위 불추구''라는 가면을 내던진 것이라며 강하게 비난했다. 이 성명은 러시아-북한 간 불법 군사협력을 규탄하고 북한을 핵보유국으로 인정하지 않겠다는 내용을 담고 있으며, 한국과 EU는 이를 통해 북한의 핵확산금지조약(NPT) 위반 행위에 대한 국제적 압박을 강화했다. 북한은 이에 대해 한국을 ''절대 존재 불가한 제1의 적대국''으로 규정하며, 앞으로도 적대적 관계를 유지할 것임을 명시했고, 미국의 ''단검''으로서의 한국을 강조하며 외교적 대립을 정당화했다. 이후 북한은 한국과 EU의 공동성명에 대한 추가 반응을 예고하며, 향후 대남 정책의 강경화와 국제적 고립을 지속할 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:34'::timestamp,'2026-07-27 16:10:15.945158'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1344,2734,'이재명 대통령은 8일 취임 1주년 기자회견에서 남북관계 개선을 위한 평화공존 정책을 지속 추진하겠다고 밝혔다. 그는 전임 윤석열 정부의 무인기 침투 사례를 언급하며 북한을 적대시한 정책이 남북 간 신뢰를 붕괴시켰다고 평가하고, 현재 북한이 군사분계선 철책 보강 등 단절 조치를 강화하고 있는 상황을 안타까워했다. 이 대통령은 현 정부 들어 북한의 대남 방송과 오물풍선 살포가 중단된 점을 언급하며 관계 개선의 가능성을 시사했고, 통일보다는 평화공존을 우선 목표로 삼겠다고 강조했다. 한일군수지원협정(ACSA) 체결에 대해서는 국민 정서상 시기상조라며 부정적인 입장을 유지했으며, 일본 총리와의 회담에서도 국민의 반응을 고려해 협의를 유보하겠다는 입장을 재확인했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:39'::timestamp,'2026-07-27 16:09:15.807298'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1345,2738,'김정은 북한 국무위원장은 3일 새로 조업한 고농축우라늄(HEU) 생산시설을 현지지도하며 무기급 핵물질 생산 능력이 기존의 2배를 초과했다고 밝혔다. 이는 미국과 이란의 종전 협상에서 HEU 처리를 두고 기싸움을 벌이는 상황에서 핵보유국 지위를 재차 공고화하려는 의도로, 특히 도널드 트럼프 2기 미국 행정부 출범 전후로 비핵화 대화를 전제로 한 미북 대화는 없다는 입장을 분명히 한 후의 행보다. 조선중앙통신은 시설의 위치나 규모는 밝히지 않았으나, 영변 핵단지 내에 새로 건설된 것으로 관측되며, 원심분리기 밀집 구조를 통해 농축 효율을 높인 것으로 분석된다. 이에 따라 북한의 핵물질 양산 능력과 불가역성 강화가 본격화될 전망이며, 시진핑 중국 주석의 방북을 앞두고 중국에 대한 외교적 메시지로도 해석되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:46'::timestamp,'2026-07-27 16:08:49.674254'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1346,2739,'정동영 통일부 장관이 몽골 정부의 요청으로 3~6일 울란바타르를 방문해 제11차 울란바타르 동북아 안보대화에 참석하며 ''한반도 평화공존과 동북아 공동번영의 길''을 주제로 특별연설을 했다. 이 대화는 2014년부터 몽골 주도로 개최되는 1.5트랙 다자안보 대화체로, 올해는 25개국에서 약 250명이 참석했으며, 동북아 평화와 안보협력을 논의하는 자리이다. 정 장관은 후렐수흐 몽골 대통령 등 고위관계자와 면담해 한반도 평화공존 정책과 상호 존중·인정 방침을 설명하고, 남북한에 모두 상주공관을 운영 중인 몽골의 협조를 요청했으며, 평화적 두 국가 개념을 국제사회에 제시했다. 북한은 참석 의사를 밝히지 않았으나, 몽골은 남북 이산가족 상봉행사 개최 가능성 등을 남북한에 전달한 바 있어, 이번 방문이 동북아 안보 협력 기반 확대와 국제적 지지 확보에 기여할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:53'::timestamp,'2026-07-27 16:08:43.192134'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1347,2741,'2024년 2월 28일, 비비안 발라크리쉬난 싱가포르 외교장관이 베이징과 평양을 거쳐 서울을 방문하며 조현 외교부 장관과 회담을 진행했다. 발라크리쉬난 장관은 평양에서 최선희 외무상과 회담하고 조용원 최고인민회의 상임위원장과 환담하며 7월 필리핀 ARF에 최 외무상을 초청하는 등 대화 채널 유지에 관심을 표명했다. 이 과정에서 북한은 적대적 국가 관계를 현장에서 체험했다고 발언하며, 개헌을 통한 민족·통일 개념 폐기 및 남북 접경지역 군사력 강화를 언급한 것으로 전해졌다. 싱가포르는 2018년 미북 정상회담 장소 제공 이후 중재 역할을 수행해 왔으며, 이번 연쇄 방문은 한반도 대화 재개 여건 조성에 대한 국제적 관심을 반영한 것으로 분석된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:42:59'::timestamp,'2026-07-27 16:08:39.244134'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1348,2742,'2024년 2월 26일, 미국·일본·인도·호주 4개국으로 구성된 쿼드(Quad) 외교장관 회의에서 인도·태평양 해양 감시 협력(IPMSC) 구상이 출범하고, 공동 성명을 통해 ''북한의 완전한 비핵화''를 재확인하며 탄도미사일 및 대량살상무기 개발을 규탄했다. 쿼드는 북한의 사이버 활동과 IT 노동자 활용을 통한 무기 프로그램 자금 조달에 대한 우려를 표명하며, 미국의 일극지배 전략에 기반한 안보 협력 강화를 추진했다. 이에 대해 북한 외무성 대변인은 28일 조선중앙통신을 통해 ''비핵화는 절대적·영원히 없을 것''이라며 쿼드를 미국의 일극지배 전략을 위한 정치외교적 도구로 규정하고, 지역 평화를 파괴하는 진영 대결 기도를 규탄했다. 이후 북한은 쿼드의 동향에 대해 적대적 입장을 유지하며, 지역 안보 환경의 악화를 우려하고 있으며, 향후 외교적·군사적 대응 방안에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:05'::timestamp,'2026-07-27 16:08:33.159016'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1349,2751,'김정은 북한 국무위원장과 시진핑 중국 국가주석이 7년 만의 정상회담을 준비 중이며, 중국공산당 대외연락부 관계자들이 평양을 방문해 경호 및 의전 점검을 진행한 것으로 확인됐다. 이는 도널드 트럼프 미국 대통령의 베이징 방문 이후 미북대화 재개를 위한 중국의 중재 역할을 전제로 한 것으로, 지난달 북중 교역이 약 3억2600만달러로 8년 5개월 만에 최고 수준을 기록하며 양국 관계 회복이 진행 중이다. 정부는 시 주석의 방북이 성사될 경우 북미대화 재개가 당연히 논의될 것이라며 중국의 건설적 역할을 기대하고 있으며, 이는 동북아 정세에서의 중재력 강화와 대미 공조를 위한 전략적 움직임으로 해석된다. 현재 시 주석의 방북 시기와 구체적 일정은 공식 발표 없이 예정된 절차와 반응이 주목되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:12'::timestamp,'2026-07-27 16:08:28.949601'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1350,2754,'2026년 7월 7일, 박홍근 기획예산처 장관은 여의도 국회의원회관에서 열린 청년정책 간담회에 참석해 청년 창업과 주거 지원을 대폭 확대하기로 밝혔다. 이는 30대 가계 평균대출이 사상 처음으로 1억 원을 돌파하고, 물가 상승률이 근로자 급여 증가율을 따라가지 못하는 등 청년층의 경제적 부담이 심화된 데 따른 조치다. 정부는 국유재산을 활용해 청년 창업 공간과 주거 지원을 확대할 계획이며, 해외 투자은행(IB)들은 2026년 한국의 성장률 전망을 평균 3%로 제시했다. 이후 정부는 이 정책의 구체적 실행 방안과 예산 배분 절차를 논의할 예정이며, 관련 법적·제도적 검토도 진행될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:17'::timestamp,'2026-07-27 18:56:25.251767'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1351,2757,'정부가 청년 일자리 및 주거 안정을 위해 국유재산을 활용한 창업·주거 지원을 대폭 확대하기로 결정했다. 이는 청년 고용 부진과 주거비 부담이 지속되는 상황에서, 노후 청·관사 및 유휴 국유지를 복합개발할 때 청년용 창업·주거 공간을 필수적으로 포함하는 방안을 포함한다. 2027년도 국유재산종합계획에 반영될 예정이며, 청년·소상공인의 국유재산 이용 부담을 낮추기 위해 대부료율을 재산가액의 1% 수준으로 인하하고, 사용료를 최대 80%까지 감면하는 세제 지원도 병행한다. 이후 국유재산을 첨단 산업 육성과 지역개발 정책 수단으로 활용하는 방향이 지속될 전망이며, 2035년까지 청년·서민에 공공주택 3만5000호를 공급하겠다는 목표도 유지된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:23'::timestamp,'2026-07-27 18:46:21.734283'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1352,2768,'국내 외환시장은 6일 오전 6시부터 24시간 거래 체제로 전환되며, 첫 거래일인 7일 오전 6시 기준 원·달러 환율은 전 거래일 주간거래 종가 대비 0.3원 내린 1530.0원에 거래를 마쳤다. 기존 거래 시간(오전 9시~익일 오전 2시)에 비해 거래 시간이 확대되어 월요일 오전 6시부터 토요일 오전 6시까지 중단 없이 운영되며, 주말과 1월 1일을 제외한 공휴일에도 거래가 가능해졌다. 이에 따라 달러인덱스(DXY)는 장중 101선을 넘어섰으나 오전 6시 15분 기준 100.84를 기록했고, 엔·달러 환율은 162.053엔으로 상승하며 원·엔 재정환율은 100엔당 943.26원으로 전날보다 0.26원 하락했다. 정부는 글로벌 금융시장과의 연계성 강화와 해외 투자자 편의성 제고를 위해 24시간 거래 체제를 도입했으며, 향후 시장의 국제 경쟁력 향상 여부와 시장 안정성 유지가 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:29'::timestamp,'2026-07-27 17:49:24.384863'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1353,2770,'2026년 1분기 기준 6대 은행의 거래상대방신용위험(CCR)이 2년 만에 18조원에서 26조원으로 45% 증가하며 금융권의 리스크가 확대되고 있다. 원화 가치가 1500원대에 고착화되면서 기업들이 환헤지 파생계약을 늘리면서 은행이 부담하는 외환 리스크가 급증한 것이 주요 원인이다. 이에 따라 은행은 자본 적정성 관리와 신용 리스크 점검을 강화하고 있으며, 6일부터 시행된 24시간 외환시장 운영으로 야간 변동성 우려도 제기되고 있다. 정부는 시장 모니터링을 강화하며 시장 안정을 지속 추진할 계획이며, 향후 환율이 1500원대 안팎에서 장기적으로 유지될 가능성이 높다고 전망하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:36'::timestamp,'2026-07-27 17:48:24.291345'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1354,2773,'미국 증시는 상반기 S&P500이 8%, 나스닥은 11% 상승하며 최근 5년 최고 성과를 기록했으며, 2분기에는 S&P500이 15%, 나스닥은 21% 급등해 2020년 2분기 이후 6년 만에 최고 상승률을 달성했다. 이 상승은 인공지능(AI) 투자 확대와 이란전쟁 휴전 등이 시장에 미친 영향으로, AI는 증시 변동성의 주요 요인으로 작용하고 있다. 하반기에는 미국 연방준비제도(Fed)의 금리 결정과 중간선거, 이란전쟁의 전개가 시장에 영향을 미칠 전망이며, 시장 전망은 낙관론이 우세하다. AI 관련 투자 지속 가능성과 지정학적 리스크가 하반기 투자 환경의 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:40'::timestamp,'2026-07-27 17:36:31.157179'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1355,2774,'2024년 6월 말 기준 원화 가치가 1545.2원으로 2009년 이후 17년 만에 최고 수준을 기록했으나, 이와 동시에 한국의 수출액은 1022억달러로 사상 처음 월 1000억달러를 돌파했다. 이는 수출 증가로 인한 달러 수입이 늘었음에도 불구하고 원화 가치가 하락한 비정상적인 현상으로, 1997년 외환위기와 달리 달러 부족이 아닌 원화 매수 수요 부족이 원인으로 분석된다. 수출 기업은 달러를 원화로 전환하지 않고 보유하고 있으며, 외국인 투자자는 한국 주식을 매도하고 달러를 확보하는 경향이 강해 현물환시장에서 원화 매수 주문이 부족한 상태다. 현재 한국은행은 외환스왑을 통해 국민연금의 달러 수요를 외부 시장에서 분리해 환율 안정을 도모하고 있으며, 달러 강세와 주요 통화 대비 원화 약세가 지속될 경우 추가 정책 조정이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:48'::timestamp,'2026-07-27 17:20:14.206416'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1356,2779,'2013년부터 2025년까지 30대 가계대출 평균액이 5374만원에서 1억218만원으로 90.1% 증가하며 사상 처음으로 1억원을 돌파했다. 이는 20대도 1611만원에서 3047만원으로 89.1% 증가한 것으로, 20·30대 평균 대출 증가율은 89.9%에 달해 12년 만에 두 배로 늘어난 상황이다. 반면 40대는 68%, 50대는 30.8%, 60대는 16.3% 증가에 그쳐 연령대별 대출 증가 폭이 30대에서 가장 높았다. 이에 따라 청년층의 결혼, 취업, 주거 안정 등 삶의 기반이 위협받고 있으며, 정부와 금융당국의 대책 마련이 시급한 상황이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:53'::timestamp,'2026-07-27 17:08:38.689331'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1357,2782,'정부는 2040년까지 원전 4기를 추가로 건설해야 한다는 분석을 내놨다. 반도체 클러스터와 AI 데이터센터 등 대규모 전력 수요가 예상되며, 2040년까지 총 24.7GW의 추가 전력 수요가 발생할 것으로 전망된다. 기후에너지환경부는 12차 전력수급기본계획의 전력 수요 전망을 재산출하고, 전남 영광군과 울산 울주군에 원전 2기씩 총 4기 건설 가능 용지를 활용해야 한다고 밝혔다. 전문가들은 원전 외에도 액화천연가스(LNG) 발전소 확대를 통해 유연성 자원을 확보해야 한다고 제언하며, 정부의 화석연료 규제 완화가 필요하다고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:43:57'::timestamp,'2026-07-27 17:06:40.664409'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1358,2784,'청년미래적금은 6월 22일부터 7월 3일까지 2주간 신청을 받은 결과, 총 234만3000명이 가입을 신청했다. 이 중 30~34세가 90만8000명(38.8%)으로 가장 많았으며, 소상공인 자격으로 신청한 인원은 약 8만명이었다. 자격심사는 6일부터 3주간 진행되며, 심사 결과는 24일에 개별 안내되며, 통과자는 27일부터 8월 7일까지 계좌를 개설할 수 있다. 청년미래적금은 최대 연 19.4%의 금리(정부 기여금 및 이자소득 비과세 포함)를 제공하며, 매월 1000원에서 50만원까지 납입 가능하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:01'::timestamp,'2026-07-27 17:05:38.443944'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1359,2789,'2026년 1분기 기준 6대 은행의 거래상대방신용위험(CCR)이 2년 만에 18조3061억원에서 26조6164억원으로 45% 증가하며 26조원대에 진입했다. 원화 가치가 달러당 1500원대에 고착화되면서 기업의 환헤지 거래가 늘어나, 은행이 파생상품 계약 상대방의 부도 리스크를 더 많이 떠안게 된 것이 주요 원인이다. 이에 따라 은행의 자본 적정성 관리가 시급해졌으며, 6일부터 시행된 외환시장 24시간 거래 체제로 인해 야간 변동성 확대 가능성도 제기되고 있다. 정부는 24시간 모니터링을 통해 시장 안정을 도모하겠다고 밝혔으나, 실제 야간 거래 활성화 여부가 시장 안정성에 결정적 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:07'::timestamp,'2026-07-27 17:05:24.819828'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1360,2863,'노르웨이 축구대표팀은 2026년 북중미월드컵 16강전에서 브라질을 2대1로 물리치며 28년 만에 월드컵 8강에 진출했다. 이 경기에서 엘링 홀란은 후반 34분 헤더와 후반 45분 왼발 슈팅으로 두 골을 기록하며 팀 승리를 이끌었다. 경기 후 라커룸에서 노르웨이 공주 잉리드 알렉산드라와 그의 남동생 스베레 마그누스가 선수들에게 축하를 전했으며, 홀란은 상의를 탈의한 상태에서 공주와 포옹하는 장면이 화제가 되었다. 다음 8강전은 홀란이 소속된 노르웨이와 해리 케인의 잉글랜드가 12일 오전 6시에 맞붙는다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:12'::timestamp,'2026-07-27 17:58:35.441802'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1361,2793,'삼성카드는 6일 소비 패턴에 맞춰 의료 및 생활 혜택을 직접 선택할 수 있는 ''삼성 iD 셀렉트업 카드''를 출시했다. 이 카드는 전월 이용 실적을 충족할 경우 병·의원, 약국, 요양병원, 동물병원 이용금액의 20%를 월 최대 1만5000원까지 할인하거나, 보험료, 주유, 이동통신 요금 결제금액의 10%를 동일한 한도로 할인받을 수 있도록 설계됐다. 모든 가맹점에서 0.5% 기본 할인을 제공하며, 할인점·온라인쇼핑몰은 1%, 골프·항공·면세점·철도·공연 업종은 2% 할인을 제공하고, 해외 이용 수수료 할인 및 병원·약국 업종 2~3개월 무이자 할부도 지원한다. 연회비는 국내전용과 해외겸용 모두 1만8000원이며, 고객은 발급 시 및 이용 중 매월 혜택을 변경할 수 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:17'::timestamp,'2026-07-27 16:57:51.885062'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1362,2795,'2024년 들어 달러당 원화 평균 환율이 1408.19원까지 하락하며 사상 최대 경상수지 흑자에도 불구하고 원화 가치가 지속적으로 약세를 보이고 있다. 과거 수출 증가로 인한 원화 강세와 달리, 국내 투자자들의 해외투자 확대와 외국인 자금의 국내 주식 매도로 인해 달러 수요가 급증하고, 실제 시장에 공급되는 달러는 감소하고 있다. 전문가들은 환율이 1400원대를 기준으로 한 ''뉴노멀'' 상태에 진입했으며, 미국의 고금리 지속 가능성으로 인해 1600원까지 상승할 가능성도 제기하고 있다. 이에 따라 환율 정상화 기대보다는 고환율 기준에 맞춘 대응 전략 수립이 필요하다는 전망이 나오고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:23'::timestamp,'2026-07-27 16:53:42.142264'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1363,2798,'한국금융연구원은 2024년 하반기 이후 원·달러 환율이 1400~1500원대를 지속할 가능성이 높다고 전망했다. 이는 글로벌 달러 강세와 내국인의 해외 주식 투자 확대, 특히 ''서학개미''의 미국 주식 보관액 증가와 관련된 구조적 변화로 분석됐다. 2022년 4월 이후 원·달러 환율과 해외 주식 투자 보관액 간 장기균형 관계가 형성된 것으로 나타났으며, 달러 강세 국면은 약 10개월 지속될 것으로 예상된다. 금융연구원은 고환율 지속에 따른 금융사의 수익성과 자본 적정성 영향을 점검할 필요성을 강조하며, 추가 외부 충격이 없을 경우 과거 수준으로 복귀하지 않을 것으로 전망했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:28'::timestamp,'2026-07-27 16:52:46.192437'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1364,2799,'안철수 국민의힘 의원은 삼성전자와 SK하이닉스를 기초자산으로 한 레버리지 ETF(삼전닉스 레버리지)의 상장폐지를 요구하며, 금융위원장과 금융감독원장을 파면해야 한다고 주장했다. 이는 코스피 시가총액의 60%를 삼성전자와 SK하이닉스가 차지하고 있으며, 레버리지 상품의 일일 리밸런싱으로 시장 변동성이 심화되고, 코스피 공포지수(90.8)가 역대급으로 치솟았기 때문이며, 14개 레버리지 상품 중 1개도 1개월간 수익률이 마이너스를 기록하며 평균 35.9%의 손실을 입혔다. 해외 투자자 유입 효과도 미미하며, 홍콩에서 유입된 11조원 중 한국 유입은 5000억원에 그치고, 환율은 1550원대를 넘나들고 있다. 안 의원은 레버리지 상품의 정책 실패를 지적하며 단일종목 레버리지 금지와 액티브 ETF 규제 완화를 제안했고, 금융당국의 책임을 묻는 파면 요구가 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:35'::timestamp,'2026-07-27 16:50:54.180882'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1365,2805,'정부는 광주 군공항 부지를 호남권 반도체 산업단지 입지로 확정하며 군공항 이전 사업의 추진 속도를 높일 전망이다. 군공항 이전은 반도체 산단 조성의 선결 과제로, 무안군은 광주 민간공항의 무안국제공항 선 이전, 전남광주특별시와 정부의 1조원 규모 지원, 국가 차원의 획기적 인센티브 제공 등 3대 조건의 구체적 이행 방안을 요구하고 있다. 현재 국방부는 망운면을 예비이전후보지로 선정하고 이전후보지 지정 절차를 진행 중이며, 5자 협의체(광주시장, 전남지사, 무안군수 등)가 구성돼 협의를 진행 중이다. 이후 이전후보지 공식 지정, 주민투표 등을 거쳐 최종 이전지가 결정되며, 정부는 안보 공백을 최소화하면서 조기에 이전을 추진하겠다는 입장이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:40'::timestamp,'2026-07-27 18:50:26.908881'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1366,2809,'정이한 전 개혁신당 부산시장 후보와 음료를 던진 A씨에 대해 경찰은 위계공무집행방해와 공직선거법 위반 혐의로 구속영장을 청구했으며, 이는 2024년 4월 27일 부산 금정구 구서 나들목에서 발생한 유세 중 피습 사건과 관련된다. 정 전 후보는 당시 차량에서 던진 음료에 맞아 쓰러졌다고 주장했으나, 경찰은 A씨가 그와 친분이 있는 헬스장 관계자이며 사전 연락 및 공모 가능성이 있는 점을 근거로 수사해왔다. 사건 발생 67일 만인 6월 3일 검찰이 부산지법에 구속영장을 신청했으며, 정 전 후보와 A씨는 6월 8일 오후 2시 부산지법에서 구속 전 피의자 심문을 받을 예정이다. 현재 경찰은 정 전 후보 부친의 온그룹 계열사 선거운동 동원 의혹과 여론조사기관의 공정성 문제 등도 별도로 수사 중이며, 개혁신당은 탈당한 정 전 후보에 대해 수사에 협조할 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:46'::timestamp,'2026-07-27 18:44:05.832988'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1367,2824,'2024년 상반기 서울 아파트 임대차 계약 중 월세 비율이 49.8%로 전세 비율(50.2%)과 근접하며 월세화가 가속화되고 있다. 전세제도 축소, 토지거래허가제로 인한 실거주 의무 강화, 전세대출 축소 및 임대인들의 월세 선호로 인해 임대 매물이 감소한 것이 주요 원인이다. 올해 상반기 서울 월세 100만원 이상 계약 비율은 41.6%로 전년 대비 1.9%포인트 증가했으며, 강북 지역에서는 월세 300만원 이상 계약이 속출하며 상승세가 강남보다 더 뚜렷하다. 현재 서울 월세 매물은 올해 초 대비 21.37% 감소한 1만6799건으로, 수요 대비 공급 부족이 지속되며 후속 임대차 3법 시행과 정부의 공공임대 확대 등 정책적 대응이 필요하다고 전문가들이 지적하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:53'::timestamp,'2026-07-27 18:15:48.053002'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1368,2864,'파라과이 상원의원이 프랑스 축구대표팀의 음바페를 향해 ''모유 대신 코코넛을 빨고 자랐다''는 인종차별적 발언을 하며 논란이 일었다. 이는 2026 FIFA 북중미 월드컵 16강전에서 프랑스가 파라과이를 1-0으로 이기고 8강 진출을 확정한 직후 발생한 사건이다. 음바페는 해당 발언에 대해 SNS를 통해 ''비열한 여자''라며 인종차별적 발언에 대한 강력한 반발을 표명했으며, 파라과이 국가대표팀의 노력과 여정이 훼손됐다고 지적했다. 이후 파라과이 정부와 축구 협회는 해당 의원의 발언에 대해 공식 사과를 요구했으며, 국제축구연맹(FIFA)은 인종차별 행위에 대한 조사 절차를 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:44:58'::timestamp,'2026-07-27 17:56:10.319877'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1369,2868,'OPEC+는 8월에도 하루 18만8천배럴의 원유 생산량을 늘리기로 합의했으며, 이는 4월부터 5개월 연속 증산으로 총 94만배럴에 달한다. 이는 전 세계 수요의 약 1%에 해당하며, 미국과 이란의 잠정 평화협상으로 호르무즈 해협 운항이 재개되면서 에너지 공급 정상화가 진행 중이나 완전 회복은 되지 않았다. 브렌트유 9월 인도분은 배럴당 71.99달러, WTI 8월물은 68.72달러로 약보합세를 유지했으며, OPEC+의 증산 영향력이 약화되고 있다는 분석이 제기됐다. 맥쿼리와 씨티그룹은 브렌트유 가격이 연말까지 배럴당 60달러 안팎으로 하락할 가능성을 예측했고, 이란의 협상력 약화 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:04'::timestamp,'2026-07-27 17:51:07.595719'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1370,2826,'광주지검은 장윤기 사건 담당 광산경찰서 수사관들에 대해 공무상비밀누설, 증거인멸 등 혐의로 강제수사에 착수했다. 이는 장윤기 아버지와 경찰 간 유착 의혹과 함께, 5월 5일 긴급체포 후 주요 증거물(케이블타이·리얼돌·SUV)을 확보하지 못한 점과 수사 상황을 누설한 행위가 확인되면서 발생했다. 검찰은 경찰의 자체 수사와 별도로 국가수사본부로 수사 주체를 격상하고, 관련 경찰관의 주거지 압수수색도 진행하며, 수사팀장도 증거인멸 혐의로 긴급체포했다. 현재 검찰은 사건의 중대성을 고려해 직접 수사 중이며, 향후 수사 결과에 따라 추가 입건 및 제재 조치가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:08'::timestamp,'2026-07-27 18:15:30.700135'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1371,2834,'20대 여성 방사선사 A씨가 전북 군산시의 한 종합병원에서 근무한 지 약 한 달 만에 아파트 화단에서 숨진 채 발견됐다. A씨는 입사 후부터 직장 내 괴롭힘을 호소하며 스트레스를 겪었다는 유족의 주장과 온라인 커뮤니티에서의 지인들의 증언이 제기됐으며, 출근하지 않은 지 3일 만에 사망한 것으로 파악됐다. 경찰은 타살 혐의는 없으며 유서도 발견되지 않았고, 현재까지 사망 경위를 조사 중이며 유족 조사를 완료했으며 직장 내 괴롭힘 여부도 포함해 전반적 조사를 진행 중이다. 병원 측은 사실관계 확인을 위해 외부 노무사를 선임해 직원 대상 조사를 진행하고 있으며, 유족은 진심 어린 사과를 요구하고 있으며, 경찰과 병원은 추가 조사와 결과 공개를 예정하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:13'::timestamp,'2026-07-27 17:51:20.010195'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1372,2835,'삼성전자 노동조합과의 임금협약 체결로 경영성과급 분쟁이 일시적으로 종결되었으나, 반도체와 비반도체 직원 간 찬성율 차이(80.6% vs 21.1%)로 성과급 배분의 공정성 논란이 심화되었다. 이는 현대자동차, 카카오, 삼성바이오로직스 등 다양한 산업에서 성과급 분쟁이 확산되고, 협력업체 노조가 원청과의 교섭을 요구하며 양대노총이 성과급 공유를 촉구하는 등 산업 내 이중구조 문제와 극심한 노노갈등을 야기했다. 정부는 경영성과급에 대해 이사회 사전 검토와 주주총회 결의를 의무화하는 방안을 검토 중이며, 정치권에서는 초과 수익의 국민 공유 주장도 제기되고 있다. 노동법제 현대화 필요성이 대두되며, 계약 기반 법제 도입, 노사 합의 중심의 임금·근로조건 설정, 해고 기준 합의 체계 도입 등이 제안되며, 기업의 법적 리스크 감소와 산업 특성 반영 가능한 성과급 제도 마련이 시급하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:22'::timestamp,'2026-07-27 17:49:45.393491'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1373,2836,'정부는 6일 광주 군공항 부지를 호남권 반도체 산업단지 입지로 확정했다. 이는 광주 도호동에 위치한 군공항을 무안으로 이전하는 계획에 따라 비게 된 약 248만㎡ 규모의 평지 용지를 활용한 것으로, 삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터 조성 계획의 핵심이다. 반도체 클러스터 조성으로 인해 지역 산업 구조 전환과 고용 창출이 기대되며, 정부는 이에 따른 인프라 및 지원 정책을 수립 중이다. 이후 반도체 산단의 구체적 설계와 투자 계획 수립, 주민 반응 및 환경 영향 평가 등이 진행될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:27'::timestamp,'2026-07-27 17:50:04.192829'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1374,2848,'이병태 대통령 직속 규제합리화위원회 부위원장이 5·18 성역 발언 논란으로 청와대의 사퇴 권고에 따라 6일 부위원장직을 사임했다. 이 부위원장은 배재고 학생들의 응원 구호를 정치적 이념 대결로 비화하는 현상을 우려해 표현의 자유와 다양성의 중요성을 강조했으나, 결과적으로 갈등을 증폭시킨 점을 인정하며 불찰을 시인했다. 사퇴 결정은 법치주의 원칙과 표현의 자유 보호를 고려해 고심 끝에 내린 것으로, 정치적 공세에 의한 사임 선례를 남기지 않겠다는 의도가 담겼다. 이후 이 부위원장의 사퇴는 민주주의 내 성역 문제와 권력의 개입 경계, 보수 인사의 정치적 역할 등에 대한 논의를 이어가야 할 후속 쟁점으로 남았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:32'::timestamp,'2026-07-27 17:16:16.503802'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1375,2857,'박항서는 2026 국제축구연맹(FIFA) 북중미 월드컵 조별리그에서 한국 축구 국가대표팀이 32강 진출에 실패한 책임을 지고, 2023년 6월 28일 멕시코 현지에서 대한축구협회 부회장 및 선수단장 직을 사퇴했다. 이는 2022년 카타르 월드컵 이후 한국 축구의 성적 부진이 지속되며, 기대에 못 미친 결과에 대한 책임 소재 논란이 제기된 데 따른 조치였다. 박 부회장은 기자회견에서 국민 기대에 미치지 못한 성적에 대해 사과하며, 선수단장으로서의 공식 일정을 마무리하고 귀국했다. 이후 그는 2023년 7월부터 태국 2부리그 깐짜나부리 FC 감독으로 임명되어 새 역할을 시작할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:36'::timestamp,'2026-07-27 18:14:41.815459'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1376,2862,'이재명 대통령은 7일 나토 정상회의 참석을 위해 튀르키예로 출국했으며, 취임 후 처음으로 나토 정상회의에 참석한다. 이 대통령은 나토 사무총장과 함께 일본·호주·뉴질랜드 정상이 참석하는 IP4 소인수 회담에 참여하고, 나토 방위산업포럼에서 ''공동의 가치, 더욱 강한 산업기반''을 주제로 기조연설을 할 예정이다. 이번 참석은 세계 국방비의 55%를 차지하는 나토 회원국들과의 방산 협력을 본격화하기 위한 것으로, 한국의 방산 수출 시장 확대에 기여할 전망이다. 이후 8일까지 튀르키예에 머무르며 도널드 트럼프 미국 대통령과의 현지 대면 여부에 대한 관심이 집중되고 있으며, 9일부터 몽골 국빈방문 일정을 이어갈 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:41'::timestamp,'2026-07-27 18:00:55.067507'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1377,2872,'브라질 축구대표팀의 네이마르가 2026 북중미 월드컵 16강전에서 노르웨이에 1대2로 패한 뒤 국가대표 은퇴를 선언했다. 이 경기는 네이마르의 대표팀 데뷔전이었던 미국 뉴욕 뉴저지 스타디움에서 열렸으며, 그는 이날 후반 23분 교체 출전해 추가시간 페널티킥으로 만회 골을 기록했다. 네이마르는 브라질 대표팀에서 130경기에 출전해 역대 2위의 출전 기록을 세우고, 월드컵 4회 연속 출전과 함께 브라질 대표팀 A매치 최다 골 기록(77골)을 수립했다. 은퇴 선언 이후 브라질 축구계와 팬들 사이에서는 그의 후속 인물 확보와 대표팀 전력 재편 방안에 대한 논의가 시작되고 있으며, 향후 국제축구연맹(FIFA)과 브라질축구협회는 그의 은퇴를 기념하는 공식 행사를 준비 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:47'::timestamp,'2026-07-27 17:25:27.435921'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1378,2874,'도널드 트럼프 미국 대통령이 2026년 월드컵에서 레드카드를 받은 미국 축구선수 폴라린 발로건의 출전정지 징계를 유예하도록 개입한 것으로 알려져 유럽 축구계에서 강한 비판이 제기됐다. 이 결정은 FIFA 징계위원회가 독립적으로 내렸다고 밝혔으나, 트럼프의 전화 개입이 영향을 미쳤다는 의혹이 제기되며 축구 규칙의 공정성과 독립성이 훼손된다는 지적이 확산됐다. 이번은 월드컵 역사상 레드카드 이후 자동 출전정지가 유예된 사례로, 1962년 칠레 월드컵 이후 처음이며, 현재까지 189장의 레드카드 중 유예된 경우는 이번이 두 번째다. 벨기에축구협회는 징계 유예 결정에 항소를 제기했고, 유럽의회와 국제사회에서는 FIFA의 정치적 중립성과 윤리위원회 조사 촉구 움직임이 확산되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:53'::timestamp,'2026-07-27 17:21:26.349080'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1379,2877,'일본이 폐에어컨에서 희토류를 재활용해 군사용 자원으로 활용하려는 시범 사업을 추진하면서 중국이 이를 ''재군사화 야심''으로 비판했다. 중국은 일본의 방산 기업인 미쓰비시전기가 폐에어컨 실외기에서 희토류를 추출해 약 35%의 에어컨 제조 원료를 대체할 수 있도록 체계를 구축했다고 밝혔으며, 이 과정이 군민 양용 생산망으로 연결될 가능성을 지적했다. 중국은 지난해 10월 이후 일본의 방위비 증액과 살상무기 수출 허용 등 군사적 움직임이 빈번해지자, 올해 2월 일본 기업 20곳을 수출통제 명단에 올리고, 최근에는 추가로 40곳을 제재했다. 중국은 이 같은 조치가 일본의 재군사화 추세에 대한 대응으로 정당하며, 희토류 수요 증가와 자원 확보 어려움은 우경화에서 비롯된다고 주장했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:45:59'::timestamp,'2026-07-27 17:09:03.878401'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1380,2878,'나토 정상회담이 7일(현지시간) 튀르키예 앙카라에서 개최되며, 미국산 무기 대량 구매를 통해 트럼프 행정부의 불만을 달래는 방향으로 진행되고 있다. 이란 전쟁과 그린란드 사태로 인해 나토 내 갈등이 심화된 상황에서, 유럽 국가들은 2024년 대비 약 20% 증가한 5740억달러(약 880조원)의 국방비를 투입하며 방위비 증액 약속을 이행하고 있다. 나토는 2035년까지 GDP 대비 5%의 국방 지출을 목표로 하며, 이번 회의에서는 미국산 무기 수십억 달러 규모의 계약이 성사될 전망이며, 제5조 집단방위 의무 재확인도 예정되어 있다. 이재명 대통령도 한국의 방산 수출 확대를 위해 초청받아 참석하며, 인도·태평양 파트너(IP4) 국가들과의 협력 강화가 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:05'::timestamp,'2026-07-27 17:08:57.084104'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1381,2896,'노르웨이 축구대표팀은 2026 FIFA 월드컵 북중미월드컵 16강전에서 브라질을 2대1로 물리치고 사상 첫 8강 진출을 달성했다. 이 경기에서 엘링 홀란이 후반 34분 헤더와 후반 45분 왼발 슛으로 멀티골을 기록하며 승리를 이끌었고, 네이마르의 후반 추가 시간 페널티킥 골로 만회했으나 동점은 만들지 못했다. 홀란은 이번 대회 7골을 기록해 메시, 음바페와 득점 공동 선두에 올랐으며, 노르웨이는 사상 최고 성적을 기록했다. 다음 8강전은 멕시코와 잉글랜드의 승자와의 경기로, 노르웨이의 바이킹 노젓기 응원 문화는 대회 중 큰 주목을 받았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:10'::timestamp,'2026-07-27 16:46:45.480281'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1382,2897,'크리스티아누 호날두(41, 알나스르)가 2026 북중미 월드컵을 자신의 마지막 월드컵이라고 밝혔다. 호날두는 2006년 독일 월드컵부터 6회 연속 출전하며 월드컵 역사상 최다 출전 기록을 보유하고 있으며, 이번 대회에서는 조별리그에서 우즈베키스탄전 2골, 32강전 크로아티아전 페널티킥 1골을 기록했다. 그는 월드컵 우승이 자신의 이력을 완성하는 데 필수적이지 않다고 강조하며, 경기에서의 열정과 즐거움을 중시한다고 밝혔다. 다음 16강전에서 스페인과 맞붙게 되며, 라민 야말에 대해 미래의 주목할 만한 선수라고 평가하며 스페인팀에 대한 존중을 표했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:15'::timestamp,'2026-07-27 16:46:20.761997'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1383,2901,'코스맥스는 프랑스 BIPEA가 주관한 국제표준시험법 ISO 23675 기반 체외 SPF 평가에서 만족(Satisfactory) 등급을 획득했다. 이는 사람 피부 실험 없이 로봇 팔을 활용한 PMMA 판을 통한 자외선 흡수 및 투과 측정 방식으로, 기존 인체 시험법(ISO 24444)보다 평가 기간을 단축하고 재현성과 일관성을 높일 수 있다. 코스맥스는 2024년 2월 국내 화장품 업계 최초로 이 방식을 도입했으며, 지난해 선케어 부문 매출은 전년 대비 47% 증가했고, 올해 1분기에는 전년 동기 대비 35% 성장했다. 이번 인증을 통해 유럽 시장 진출을 위한 선케어 제품 개발 속도가 가속화될 전망이며, 향후 글로벌 고객사의 제품 개발 및 시장 대응력 강화에 기여할 것으로 기대된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:21'::timestamp,'2026-07-27 18:43:50.871099'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1384,2909,'삼성전자는 2024년 2분기 영업이익 89조4000억원, 매출 171조원을 기록하며 분기 기준 세계 최대 영업이익을 달성했다. 이는 전년동기대비 영업이익 1810.26% 증가한 것으로, 엔비디아의 분기 영업이익(약 82조원)을 초과해 글로벌 1위에 올랐다. 영업이익률은 52.2%이며, 메모리 반도체 부문의 시장점유율 우세와 메모리 가격 상승, 클라우드 서비스 제공업체의 장기공급계약 확대가 주요 원인이다. 삼성전자는 3분기 영업이익 전망치로 110조원을 예상하며, 30일 실적 발표에서 사업부별 세부 실적을 공개할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:26'::timestamp,'2026-07-27 17:54:30.568554'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1385,2910,'삼성전자는 2024년 2분기 연결기준 매출액 171조원, 영업이익 89조4000억원을 기록하며 사상 최대 실적을 달성했다. 이는 전년 동기 대비 매출 129.31% 증가, 영업이익 1810.26% 급증한 결과로, 주로 메모리 반도체 시장 회복과 고부가 제품 중심의 수익 구조 전환에 기인했다. 삼성전자는 아직 결산을 완료하지 않았으나, 투자자 정보 접근성과 글로벌 회계 기준(IFRS)에 부합하기 위해 잠정 실적을 사전 공개했다. 이후 정식 결산과 함께 투자자들의 반응, 반도체 시장 전망, 향후 재무 전략 방향성 등이 주요 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:30'::timestamp,'2026-07-27 17:52:31.449854'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1386,2917,'정부는 6일 삼성전자와 SK하이닉스가 총 800조원을 투자하는 서남권 반도체 클러스터를 전남광주특별시 군공항 용지에 조성하기로 결정했다. 군공항 용지는 약 826만㎡(250만평) 규모로 평탄화가 완료되어 공사기간 단축이 가능하며, 기업들이 입지 적합성에서 가장 높은 평가를 받았다. 이는 이재명 대통령이 선포한 ''메가프로젝트 속도전''의 첫 번째 성과로, 미국과 일본도 반도체 산업 육성에 정부 보조금을 대규모로 투입하며 글로벌 경쟁이 심화되고 있다. 이후 행정 절차의 신속한 진행과 함께, 군공항 이전 사업과 연계된 산업단지 조성 계획의 구체적 실행 방안 및 지역 주민 반응 등이 주요 쟁점으로 부상할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:35'::timestamp,'2026-07-27 17:08:26.319442'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1387,2918,'마이크론은 미국, 싱가포르, 대만, 일본, 인도 등 주요 수요국에 반도체 공장을 확대하며 글로벌 생산거점 다변화 전략을 추진하고 있다. 이는 AI 데이터센터 수요 증가와 지정학적 리스크로 인해 고객사와 가까운 지역에서의 안정적 공급이 새로운 경쟁력으로 부상한 데 따른 것이다. 마이크론은 미국에 2000억달러를 투자해 D램 및 HBM 생산시설을 건설하고, 싱가포르에 240억달러를 투입해 3D 낸드 생산능력을 확대하며, 대만·일본·인도 등에서도 첨단 메모리 생산을 확대하고 있다. 삼성전자와 SK하이닉스도 해외 공장 증설을 진행하고 있으나, 마이크론의 현지 생산·현지 공급 전략에 따라 국내 기업들도 주요 시장별 공급망 다변화를 더욱 적극적으로 고려해야 한다는 지적이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:41'::timestamp,'2026-07-27 17:07:29.356545'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1388,2919,'현대차그룹은 싱가포르 글로벌 혁신센터(HMGICS)에서 컨베이어벨트를 폐기하고 AI와 자율주행 로봇, 디지털 트윈 기반의 셀 생산 시스템을 도입해 자동차 생산 방식을 100년 만에 대전환하고 있다. 기존의 대량 생산 중심 방식에서 벗어나 전기차와 소프트웨어중심차량(SDV) 등 맞춤형 수요에 유연하게 대응하기 위해 AI가 생산 계획을 실시간으로 수립하고, 로봇이 부품을 운반하며 공정을 조정하는 자율 제조 시스템을 구현했다. HMGICS는 연간 3만대 규모지만, 디지털 트윈 기반의 메타 팩토리로 가상에서 생산 시나리오를 검증하고, 품질 관리도 실시간 비전 시스템과 센서를 통해 공정 중에 수행한다. 이 기술은 미국 조지아주 메타플랜트 아메리카 등 글로벌 공장으로 확대될 예정이며, 보스턴다이내믹스의 휴머노이드 로봇 아틀라스도 조립 및 품질 관리에 활용될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:49'::timestamp,'2026-07-27 17:07:19.220330'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1389,2920,'테슬라가 차체를 일체형으로 주조하는 ''기가 프레스'' 기술을 도입하며 생산 공정을 단순화하고, AI와 로봇을 활용한 무인 공장인 ''다크팩토리''를 확대하고 있다. 기존 수십 개의 부품을 용접해 조립하던 방식을 하나의 대형 알루미늄 부품으로 대체함으로써 생산 시간과 원가를 절감하는 것이 핵심 전략이다. 글로벌 스마트팩토리 시장은 2024년 1700억달러에서 2034년 4700억달러로 성장할 전망이며, 중국 전기차 업체들은 5G와 AI 기반의 다크팩토리를 통해 다품종 생산에 대응하고 있다. 현재는 기업별로 다양한 제조 전략이 경쟁 중이며, AI, 로봇, 제조 공법의 결합 방식이 차세대 제조 패권을 좌우할 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:54'::timestamp,'2026-07-27 17:07:10.488223'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1390,2922,'정부는 전남광주특별시 군공항 용지에 호남 반도체 산업단지를 조성하기로 결정했다. 이는 삼성전자와 SK하이닉스가 서남권 반도체 클러스터에 총 800조원을 투자하겠다고 발표한 지 일주일 만에 이루어진 것으로, 기업들이 전남광주 군공항을 가장 적합한 후보지로 제시한 데 따른 것이다. 군공항 용지는 약 826만㎡(250만평) 규모로 이미 평탄화가 완료되었으며, 국유지이기 때문에 토지 수용 절차가 필요 없어 공사 기간 단축이 가능하다. 이후 정부는 산업단지 조성에 대한 구체적 추진 계획과 관련 부처 협의를 진행할 예정이며, 향후 지역 주민 반응과 환경 영향 평가 등이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:46:59'::timestamp,'2026-07-27 17:06:57.611651'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1391,2957,'삼성SDI의 올 하반기 실적 반등 여부를 놓고 증권사 간 전망이 엇갈리고 있다. DB금융투자는 ESS 부문의 관세 환급과 북미 수요 확대, 전기차 부문 가동률 유지 등을 근거로 2분기 영업이익이 손익분기점(BEP)에 도달할 것으로 전망하며 목표주가 84만원, 투자의견 ''매수''를 유지했다. 반면 LS증권은 전기차용 배터리 시장 점유율이 5월 기준 1.4%로 전년 대비 35% 감소했고, 각형 배터리 가격 경쟁과 고객 집중도 문제로 인해 실적 회복이 어렵다고 보며 목표주가를 41만9천원으로 하향 조정하고 ''보유'' 의견을 유지했다. 현재 삼성SDI는 ESS 부문에서 글로벌 출하량 성장률(78%)보다 낮은 36% 성장에 그치며 시장 점유율이 2%에서 1.5%로 하락했고, 전기차 부문의 가동률은 70%대 유지가 예상되나, 장기적 수익성은 설비투자와 감가상각비 부담으로 인해 우려되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:08'::timestamp,'2026-07-27 18:02:26.760911'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1392,2965,'SK하이닉스는 10일(현지시각) 미국 나스닥에 ADR 상장을 추진하며, 약 43조1400억원 규모의 신주 1779만주를 발행한다. 이는 해외 투자자 접근성 제약과 저평가된 주가(12개월 선행 PER 6.6배)를 해소하고, 글로벌 시장에서 기업가치를 재평가받기 위한 전략적 결정이다. 현재까지 미국 헤지펀드 3곳이 공모 물량의 약 25%에 해당하는 70억달러(약 10조7000억원)를 인수할 가능성이 제기되며, 국내외 투자자 기반 확대와 AI 메모리 생산 능력 강화(용인 팹 31조원, 청주 팹 19조원 등)가 예정되어 있다. 다만, 메모리 반도체 업황 과열과 투기 버블 우려, 상장 시점의 상승 모멘텀 약화 등에 대한 의구심도 제기되며, 향후 밸류에이션 변화와 장기 성장성에 대한 시장 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:16'::timestamp,'2026-07-27 17:57:21.602270'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1393,2979,'지난주(6월 29일~7월 3일) 외국인 투자자가 코스피시장에서 19조8374억원을 순매도한 가운데, 삼성전기(4462억원), DB하이텍(2860억원), LG이노텍(1657억원), 한미반도체(1485억원) 등 4개 종목에만 1000억원 이상 순매수했다. 이는 인공지능(AI) 인프라 확대에 따른 MLCC와 반도체 패키지 기판 수요 증가 기대와 메모리 반도체의 피크아웃 우려로 인한 자금 이동 때문으로 분석된다. 삼성전기는 올해 상반기 756.47% 상승하며 코스피 상장사 중 최고 수익률을 기록했고, 증권사들은 하반기 실적 개선과 공급 부족 심화 전망을 바탕으로 목표주가를 대폭 상향했다. 현재 삼성전기 주가는 최고가 이후 조정을 받았으나, 교보증권과 미래에셋증권 등은 2분기 실적 상향 조정과 AI 수혜 지속 가능성에 따라 추가 상승 전망을 제시하며 투자자 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:23'::timestamp,'2026-07-27 17:08:06.771886'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1394,2987,'금융감독원은 국채도 만기 전 매도 시 시장금리 상승으로 인해 평가손실이 발생할 수 있다고 경고하며, 30년 만기 국채는 시장금리가 1%p 상승할 경우 약 17%의 손실이 발생할 수 있다고 설명했다. 이는 국채가 신용위험이 낮아 안전자산으로 분류되지만, 장기채는 금리 변동에 민감해 중도 매도 시 가격 하락 위험이 있다는 배경에서 비롯된 것으로, 최근 고령 투자자 등이 판매직원의 권유로 장기채를 매수한 사례에서 부적합한 권유가 발생한 점이 원인이다. 2025년 1분기 기준금리 2.75%에서 2분기 2.50%로 하락했지만, 국고채 30년물 금리는 3분기 2.80~2.95%, 4분기 3.10~3.20%로 상승하며 채권가격 하락이 발생했으며, 장외채권 거래 시 민평금리와 실제 매매수익률의 차이도 손실 원인이 될 수 있다. 금감원은 투자자 보호를 위해 장내채권 거래 정보 확인과 장외거래 시 수익률 차이 분석을 당부하며, 향후 분쟁사례를 바탕으로 제도 개선을 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:31'::timestamp,'2026-07-27 16:54:53.478557'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1395,2988,'2026년 7월 7일 개정 정보통신망법 시행을 계기로 국민의힘은 ''입틀막법''이라며 헌법소원심판을 청구하고, 독소조항 삭제를 위한 전면 재개정안을 발의했다. 이 법안은 허위조작정보의 유포를 막고 피해자에 대한 책임을 묻기 위한 제도적 장치로, 민주당은 유럽연합(EU) 등 해외 사례를 들어 건강한 온라인 생태계 조성을 위한 필요성과 정당성을 강조했다. 국민의힘은 조선 시대 연산군의 입틀막 정책을 비유하며 법이 표현의 자유를 침해할 수 있다고 주장했고, 이재명 대통령에 대한 탄핵 청원은 12일 만에 47만7000명을 넘는 등 정치적 반발이 확산되고 있다. 이후 정부는 명백한 허위정보에 대해 단호히 대응하겠다며 방송미디어통신위원회 등 관계부처에 법 집행의 투명성과 국민 설명을 주문했으며, 향후 법의 시행 여부와 표현의 자유 간 균형에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:37'::timestamp,'2026-07-27 18:54:22.753051'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1396,2990,'한병도 더불어민주당 대표 직무대행은 7일 국회 원내대책회의에서 올림픽공원 핸드볼 경기장 개표소에 남은 투표용지 247만장에 대한 재검표와 수개표를 여야 협의를 통해 국조특위에서 추진하는 방안을 적극 검토하겠다고 밝혔다. 이는 선거 과정에서 투표지 인쇄 물량 축소, 의사결정 체계 및 당일 지휘 체계의 문제로 인한 국민참정권 침해 우려가 제기된 데 따른 조치로, 민주당은 특검법을 당론으로 추진하며 제3자 추천 방식을 제안했으나 국민의힘은 야당 단독 추천을 고집하고 있다. 현재 민주당은 재검표 추진을 공식 입장으로 삼고 있으며, 여야 간 사전 논의를 통해 국조특위에서 조사 절차를 진행할 예정이다. 이후 재검표 및 수개표의 실시 여부는 여야 협의와 국조특위의 결정에 따라 결정될 것으로 보이며, 선거 신뢰 회복과 책임 소재 규명이 핵심 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:43'::timestamp,'2026-07-27 18:27:49.539542'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1397,2991,'김민석 더불어민주당 당대표 후보는 7일 KBS라디오에 출연해 친정청계 이성윤 의원이 6일 계엄 해제 표결 불참에 대해 ''감기약 성분이 무엇인지''라고 묻는 발언을 한 것에 대해 ''대장동 때를 보는 것 같다''며 허위사실이라고 반박했다. 이 의원은 이날 페이스북에서 김 의원이 계엄 해제 표결 직전에 국회에 없었다며 감기약 복용을 근거로 의혹을 제기했고, 김 의원은 표결 당시 본회의장에 있었으며 이후 착석했다고 설명하며 허위사실로 지적했다. 김 의원은 이성윤 의원의 발언이 명예훼손에 해당할 수 있다고 우려하며, 검찰 출신이 허위사실을 공공연히 주장하는 것에 대해 사과를 요구했다. 현재 김 의원은 8·17 전당대회에서 호남을 비롯한 전국 지지층에서 여론조사를 통해 상대적으로 앞서는 상황이며, 5·18 성역 발언 논란으로 사퇴한 이병태 부위원장 사퇴에 대해 불가피했다고 평가하며 개헌을 통한 5·18 정신 헌법 수록과 선관위 개혁을 정치적 과제로 제시했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:50'::timestamp,'2026-07-27 18:25:59.297142'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1398,2992,'강훈식 대통령비서실장은 2024년 6월 6일(현지시간) 캐나다 정부가 CPSP(캐나다 잠수함 프로그램) 우선협상대상자로 독일 티센크루프마린시스템스(TKMS)를 선정함에 따라, 한화오션의 수주 불발을 발표하며 아쉬움을 표했다. 이는 1949년부터 지속된 나토 안보 동맹 구조와 경제·산업·안보 요소를 종합적으로 고려한 캐나다 정부의 결정으로, 대한민국 방산 기술의 성장과 세계 시장 경쟁력이 입증된 계기였다. 강 실장은 이번 결과가 기술력만으로는 나토 내 군사 동맹의 두터운 벽을 넘기 어렵다는 현실을 보여주었으며, 한화오션의 기술력은 독일과 어깨를 나란히 하거나 그 이상이라는 평가를 받았다고 설명했다. 강 실장은 부족한 점을 보완하고 정부·기업 협력 관계를 유지하며 다음 도전에 나설 것임을 밝히며, 이번 도전이 새로운 시장 개척의 이정표가 될 것이라고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:47:56'::timestamp,'2026-07-27 17:56:40.008862'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1399,2995,'캐나다 정부는 차세대 잠수함 사업의 우선협상대상자로 독일 방산업체 티센크루프마린시스템(TKMS)을 선정했다. 이 사업은 잠수함 건조비 200억~300억캐나다달러(약 21조~32조원)를 포함해 총사업비 최대 500억캐나다달러(약 54조원)로, 30년간 운영·유지보수 비용까지 포함된다. 한화오션은 KSS-III Batch-II 모델로 수주 경쟁을 벌였으나, 경제적 파급효과와 협력 방안에서 TKMS가 우세한 것으로 평가됐으며, 2026~2044년 캐나다에서 700억달러 이상의 교역과 2만5000명 이상의 고용 창출을 약속한 한화의 제안도 반영되지 않았다. 이후 캐나다 정부는 TKMS와의 계약 체결 절차를 진행할 예정이며, 한화오션은 기술력 강화를 통해 유럽 시장 진출을 지속할 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:02'::timestamp,'2026-07-27 17:24:55.328567'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1400,2997,'이재명 대통령은 6일 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 이는 약 800조원 규모의 기업 투자와 연계된 3대 메가프로젝트 중 하나로, 광주 군공항 부지는 약 250만평(826만㎡) 규모이며 평탄화가 완료된 국유지로 부지 공사 기간 단축이 가능하다는 장점이 있다. 정부는 환경영향평가 기간 단축과 함께 토지 보상 절차에서 협의 취득과 강제 수용을 동시 진행하도록 지시했으며, 이는 행정 지연을 방지하기 위한 조치다. 이후 매달 민관합동점검회의를 개최하고, 전담기구를 두어 산업단지 개발 일정을 총괄 관리할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:08'::timestamp,'2026-07-27 17:23:58.826383'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1401,2999,'광주 군공항은 2027년 12월까지 호남선 KTX 2단계 사업 완료를 전제로 무안국제공항으로 민항기 이전이 결정됐으며, 군공항도 무안 일대에 예비 이전 후보지로 지정된 상태다. 광주 군공항은 1964년 공군 기지로 조성되어 현재 공군 제1전투비행단과 국내선 민항기가 함께 사용 중이며, 국방부 소유로 도심 내 위치해 도시 개발에 유리한 조건을 갖추고 있다. 이전 후보지로 확정되면 국방부와 전남광주통합시가 주변 지역 지원계획을 수립하고 주민투표를 통해 최종 부지가 결정되며, 새 군공항 완공까지는 6~7년이 소요될 것으로 예상된다. 반도체 산업단지 조성에 따라 기존 부지 활용을 위해 군사시설 보호구역 조정, 개발제한구역 해제 등 법적 개정이 필요하며, 이는 2027년 이후의 개발 일정에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:13'::timestamp,'2026-07-27 17:22:16.026815'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1402,3001,'국민의힘 중앙윤리위원회는 6일 6·3 부산 북갑 국회의원 보궐선거에서 한동훈 무소속 의원을 지지한 당내 의원들에 대한 징계 심의를 시작했다. 이는 장동혁 대표가 당원들의 요구에 부응해 당원주권주의를 실현하려는 조치로, 특히 조경태 의원은 박덕흠 국회부의장 선출에 대해 민주당 의원들에게 반대 발언을 해 징계 대상이 됐다. 징계 대상은 친한동훈계 의원들과 조경태 의원 등으로, 윤리위는 약 2시간30분 동안 심의했지만 50여 건의 요청서를 완료하지 못했으며, 최고위원회의에 보고는 9일 예정이지만 지연될 전망이다. 반면 일부 의원들은 징계가 반장동혁 세력 축출용이라며 반발하며, 장 대표가 해당 행위자에 대해 영구 복당 금지를 주장한 점에서 당내 갈등이 심화되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:19'::timestamp,'2026-07-27 17:22:01.026874'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1403,3002,'감사원은 6일 6·3 지방선거 투표용지 부족 사태와 관련해 중앙선관위 및 서울·경기·부산 지역 선관위를 대상으로 2022년 이후 처음으로 예산 편성·집행 실태 감사를 착수했다. 감사 대상은 투표용지 인쇄 계약, 수당 및 일용 임금 집행, 선거 물품 구매·관리, 국외 출장 여비, 업무추진비 및 특근매식비 집행, 당선무효자 선거비용 반환채권 관리 등 총 12개 항목으로, 특히 수의계약 체결 의혹과 예산 집행의 투명성에 초점을 맞췄다. 감사는 6일부터 24일까지 1단계를 진행한 후 14일간 2단계 감사를 이어가며, 결과는 후속 조치와 제도 개선 논의에 활용될 예정이다. 현재까지 선관위는 감사 대상에 대한 자체 점검을 완료했으며, 감사 결과에 따라 정책 개선이나 책임자 처분 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:24'::timestamp,'2026-07-27 17:21:43.560268'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1404,3004,'이재명 대통령은 7일 튀르키예 앙카라에서 열리는 나토 정상회의에 참석해 한국의 방산 외교를 중점적으로 추진한다. 이는 윤석열 전 대통령에 이어 두 번째로 한국 대통령이 나토 정상회의에 참석한 것으로, 나토 회원국들이 차지하는 세계 국방비의 55%를 보유한 최대 방산시장을 겨냥한 실용외교 전략이다. 이번 회의를 계기로 한국은 드론·우주 등 미래전 핵심 기술 분야에서 나토 협력 네트워크에 참여하고, 방산 기업들의 공동 개발 기반을 마련할 전망이며, 유럽과의 전략적 연계를 강화한다. 다만, 러시아·우크라이나 전쟁과 중국·러시아 견제 요구 등으로 인해 북한과의 평화 공존 기조와의 균형 유지가 필요하며, 우크라이나 지원 문제 등 외교적 부담도 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:29'::timestamp,'2026-07-27 17:21:05.896169'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1405,3007,'민형배 전남광주통합특별시장은 2024년 6월 6일 정부가 광주 군 공항 부지를 서남권 반도체 산단으로 지정한 것을 환영하며, 이전 후 산단 조성 가능성을 강조했다. 군 공항은 국방·안보 기능과 직결된 지역으로, 오랫동안 이전 문제로 지역의 숙제였으며, 정부는 이전을 전제로 반도체 산단 조성 계획을 발표했다. 현재 공항 이전 절차가 진행 중이며, 통합특별시는 전력·용수·교통·물류망, 인재 양성 등 인프라를 종합적으로 준비 중이다. 이후 공항 이전 완료 후 산단 조성과 기업 유치가 본격화될 예정이며, 정부와 지자체는 입지 조성과 투자 유치를 위한 실무 지원단을 운영할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:34'::timestamp,'2026-07-27 17:12:04.754504'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1406,3011,'정부는 2026년 7월 6일 광주 군공항 부지(8.2㎢, 약 248만평)에 약 800조원 규모의 호남권 반도체 클러스터를 조성하기로 결정했다. 광주 군공항은 1964년 공군 기지로 조성된 국방부 소유 부지로, 현재 공군 제1전투비행단과 민항기가 함께 사용 중이며, 영산강·황룡강 인접, KTX 광주송정역과 고속도로 접근성 우수, 용수 확보 가능성 높아 반도체 산업 입지로 적합하다고 평가받고 있다. 군공항 이전은 2014년 광주시의 공식 건의 이후 2016년 승인되었으며, 무안공항 인근이 예비이전 후보지로 선정되었고, 2027년 12월까지 호남선 KTX 2단계 완공을 전제로 민간공항은 무안공항으로 이전될 예정이다. 그러나 새 군공항 완공까지 최소 6~7년이 소요되므로, 반도체 클러스터 조기 착공을 위해 군사시설 보호구역 조정, 비행안전구역 해제, 개발제한구역 해제 등 법적 절차 개선이 필요하며, 환경영향평가 기간 단축과 토지 보상 절차의 동시 진행이 정부의 주문사항이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:42'::timestamp,'2026-07-27 17:05:07.689271'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1407,3012,'김민석 전 국무총리가 6일 광주 전일빌딩에서 더불어민주당 당대표 출마를 공식 선언하며, 지난 1년간의 ''자기 정치 폐해''가 당과 정부 간 협력에 혼선을 초래했다고 지적하며 당·정 관계 복원과 숙의적 운영 회복을 강조했다. 그는 이재명 정부의 국정 성공을 위해 민주당을 강한 여당으로 재건하고, 1인1표 당원주권을 통해 압도적 결의로 리더십을 교체할 것을 호소했으며, 광주 선택은 5·18 민주화운동의 상징성과 민주주의의 미래를 동시에 상징하기 위한 전략적 결정이었다. 이에 대해 친정청래계 의원들과 이성윤·한민수 등 일부 의원들은 김민석의 ''남 탓'' 논조를 비판하며 자기 정치의 책임 회피라며 반발했고, 정청래 의원은 김용민 의원의 불출마에 대해 검찰개혁 완수를 약속하며 이른바 ''김용민 라인''과 협력할 의지를 밝혔다. 이후 송영길 의원도 이번 주 내 출마 선언을 예고하며, 2030세대 중심의 당 재건을 강조하며 당권 경쟁의 본격화가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:50'::timestamp,'2026-07-27 17:03:32.957662'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1408,3014,'2024년 6월 6일, 정부는 약 800조원 규모의 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 이는 기업들의 후보지 중 광주 군공항이 250만평(826만㎡) 규모의 평탄화된 국유지로 인프라 접근성과 토지 수용 리스크가 낮아 가장 적합하다는 평가를 반영한 것이다. 정부는 환경영향평가 기간 단축과 협의 취득 및 강제 수용 절차 동시 진행을 통해 투자 집행 속도를 높이기로 했으며, 이재명 대통령은 매달 민관합동 점검회의를 개최해 메가프로젝트 추진 상황을 직접 점검하겠다고 밝혔다. 이후 이는 지역 부동산 시장에 영향을 미치며, 반도체 클러스터 조성의 행정 절차 효율화와 야당의 반응, 정부의 추진력에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:48:56'::timestamp,'2026-07-27 17:02:18.626772'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1409,3015,'이재명 대통령은 취임 후 처음으로 7일(현지시간) 튀르키예 앙카라에서 열리는 나토 정상회의에 참석하며, 방산 세일즈 외교를 추진한다. 이는 중국·러시아·북한을 자극할 수 있는 진영 외교와 실용 외교 사이의 균형을 요구하는 상황에서 이루어진 것으로, 한국은 나토 회원국이 아닌 IP4 자격으로 초청받아 참석한다. 이번 회의에서 한국은 나토 회원국들의 55%에 달하는 세계 최대 방산시장을 겨냥해 드론·우주 등 미래전 기술 분야 협력 강화를 목표로 하며, 우크라이나 전쟁으로 인한 첨단 기술 적용의 중요성이 부각되고 있다. 그러나 나토와의 협력 확대가 한반도 평화 공존 정책과 충돌할 수 있다는 우려와 함께, 우크라이나 지원 문제 및 중국·러시아에 대한 견제 요구가 한국의 외교적 부담으로 작용할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:02'::timestamp,'2026-07-27 16:59:42.379438'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1410,3018,'중국은 2024년 6월 6일(현지시간) 태평양 공해상에서 전략핵잠수함 1척이 잠수함발사탄도미사일(SLBM)을 성공적으로 시험 발사했다고 공개했다. 이는 1982년 이후 처음으로 공개된 잠수함 기반 미사일 시험 발사로, 중국 해군의 094형 핵잠수함이 JL-2 또는 JL-3 미사일을 발사한 것으로 추정된다. 미사일은 일본 와카야마현 남쪽 태평양 해역에 낙하한 것으로 추정되며, 일본과 호주, 파푸아뉴기니, 뉴질랜드 등에 사전 통보가 완료됐다. 일본은 발사가 일본 EEZ를 포함한 해역에서 이뤄졌고, 상공을 통과할 수 있다는 점에서 안전 우려를 표명하며 중국의 군사 활동 확대에 대한 경계를 강화하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:08'::timestamp,'2026-07-27 16:53:24.347837'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1411,3152,'베네수엘라가 6월24일 발생한 연쇄 강진으로 인해 독립 215주년 기념일을 맞았으며, 사망자 수는 3342명으로 집계됐다. 지진은 라과이라주 카티아라마르 등지에서 발생해 전기 공급 중단, 식량과 물 부족, 구조팀 일부 철수 등으로 인해 복구가 지연되고 있으며, 유엔은 최대 5만명이 실종된 것으로 추산했다. 피해 규모는 약 67억달러(약 10조3000억원)로 추정되며, 재건 비용은 국내총생산(GDP)의 40%에 해당하는 370억달러(약 57조원)가 필요할 것으로 전망된다. 현지 인권단체 프로베아는 미국과 국제통화기금, 세계은행 등에 재건 지원을 촉구했으며, 교황 레오 14세도 희생자들을 추모하는 성명을 발표했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:13'::timestamp,'2026-07-27 17:19:26.166998'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1412,3019,'2026년 7월 6일, 정부는 광주 군공항 부지 약 250만평을 서남권 반도체 클러스터 산업단지 후보지로 결정했다. 이는 기업들의 의견을 반영한 결과로, 군공항 부지가 평탄화가 완료되어 공사 기간 단축이 가능하고, 도심 및 KTX 역과 인접해 인력 확보와 정주 여건이 우수하며, 도로·공항·항만과의 연계로 물류 접근성이 뛰어나다는 평가를 받았다. 정부는 관계부처 협의를 거쳐 후보지 선정 절차를 조속히 마무리할 예정이며, 이는 반도체 산업의 지역 균형 발전과 호남권 경제 활성화를 위한 핵심 정책 추진의 일환으로 평가된다. 이후 부지 선정 절차 완료 후 실시 예정인 토지 보상, 환경영향평가, 산업단지 개발 계획 수립 등이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:18'::timestamp,'2026-07-27 16:52:59.279607'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1413,3021,'국민의힘은 2024년 7월 6일 시행을 하루 앞둔 개정 정보통신망법을 ''입틀막법''이라며 검은 마스크를 착용하고 총공세를 펼쳤다. 이 법은 허위조작정보 유포 시 손해액의 최대 5배 배상과 10억원 이하 과징금을 부과하며, 법원 판결 기준으로 2회 이상 유통 시 처벌한다. 그러나 언론단체 등은 권력자에 대한 배액 배상 배제를 요구했으나 반영되지 않았고, 법원은 중간판결을 통해 정당한 비판·감시를 차단하는 소송임을 확인할 수 있도록 허용했다. 국민의힘은 법 시행을 즉시 유예하고 독소조항을 삭제하기 위한 재개정 논의를 민주당에 제안하며, 이 법이 헌법 위반일 수 있다고 주장하며 정치적 반발을 이어가고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:24'::timestamp,'2026-07-27 16:51:28.720338'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1414,3026,'이재명 대통령은 6일 청와대에서 열린 서남권 반도체 클러스터 민관합동 점검회의에서 야당의 3대 메가 프로젝트 비판에 대해 ''가능하다고 판단하면 협조를, 불가능하다고 판단하면 반대를 해야 한다''며 일관된 태도를 요구했다. 이 대통령은 야당이 프로젝트의 실현 가능성을 부정하면서도, 동시에 프로젝트가 사기적이고 불가능하다고 주장하는 모순을 지적하며, 정부의 국가적 과제에 대해 방해하지 말 것을 당부했다. 그는 프로젝트가 국민과 청년들에게 새로운 기회를 만들 수 있다는 점을 강조하며, 협조는 어려우나 방해는 자제해 달라고 요청했다. 이후 야당은 이 발언에 대해 반발하며 프로젝트의 재검토 필요성을 제기하며 향후 정책 논의와 국회 심사 절차가 예정된 상태다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:28'::timestamp,'2026-07-27 16:50:06.639957'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1415,3028,'감사원은 6월 6일 6·3 지방선거 투표용지 부족 사태와 관련해 중앙선관위 및 서울·경기·부산 지역 선관위의 예산 편성·집행 실태 감사를 착수했다. 이는 선관위에 대한 2022년 정기감사 이후 회계 분야 감사가 없었던 점과 국민의 의혹을 해소하기 위한 것으로, 헌법재판소의 직무감찰 제한 결정에 따라 회계검사라는 우회 절차를 밟은 것이다. 감사 대상은 투표용지 인쇄 예산, 수당 및 인건비 집행, 수의계약 체결, 공무국외출장 여비, 업무추진비 등 총 12개 항목이며, 감사반은 행정·안전감사국장을 단장으로 총 42명으로 구성되어 6월 6일부터 24일까지 진행된다. 감사원은 1단계 감사 결과를 바탕으로 14일간 2단계 감사를 진행할 예정이며, 이후 결과에 따라 후속 조치나 제도 개선 논의가 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:34'::timestamp,'2026-07-27 16:47:48.660075'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1416,3029,'6일 리얼미터가 에너지경제신문의 의뢰로 실시한 여론조사에서 더불어민주당 지지율이 43.0%로 국민의힘(40.3%)을 3주 만에 다시 앞지르며 지지율 1위로 재진입했다. 이는 지난 6월2주차부터 이어진 국민의힘의 4주간 지지율 우세 이후, 정부의 서남·충청·영남권 대규모 투자 발표와 호남권 산업 육성 정책 기대감이 중도층과 30대·50대, 서울·대구·경북 지역에서 지지율 상승을 이끌었기 때문으로 분석된다. 민주당은 지난 조사 대비 2.0%p 상승한 반면 국민의힘은 1.7%p 하락하며 오차범위 내 순위 변화를 겪었으며, 이재명 대통령의 국정수행 긍정 평가는 7주 만에 하락세를 멈추고 47.0%를 기록했다. 이후 정부의 경제 정책 효과와 주가 급락, 고환율 등 체감 경기 악화가 지지율 상승을 제한하며, 여야 지지율 격차는 오차범위 내(2.2%p)로 유지된 상태로, 향후 정당 간 정책 대응과 여론 변화 추이가 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:41'::timestamp,'2026-07-27 16:47:32.254848'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1417,3034,'정부, 반도체 호황으로 발생한 추가세수를 재원으로 하여 ''미래대응기금''을 신설하기로 결정했다. 이는 2024년 9월 5일 당·정·청 고위협의회에서 공식화되었으며, 기금은 3대 메가프로젝트(반도체·AI 데이터센터·피지컬 AI) 지원, 양극화 완화, 청년 주거·창업·일자리 지원 등에 사용될 예정이다. 기금 조성은 국가재정법상 법정 기금으로 지정하기 위한 법률 제정과 함께, 올해 가을 추가경정예산(가을 추경) 편성이 필요하다는 전망이 제기되고 있다. 이후 기획예산처와 관련 부처가 협의해 법안을 마련하고, 3대 메가프로젝트 지원 TF를 위원회로 격상해 실행 속도를 높일 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:47'::timestamp,'2026-07-27 16:41:10.268995'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1418,3037,'국방부가 육·해·공군 사관학교를 통합하고 육군사관학교를 지방으로 이전하는 방안을 추진하면서, 사관학교 출신 인사들과 동문회 등이 8일 국회와 국방부 앞에서 통합 반대 총궐기대회를 예정했다. 이는 입학 성적 하락(2026학년도 육사 212점, 공사 196점, 해사 161점), 자퇴율 증가(81기 23.3%) 등 군 인재 양성 위기와 전장 환경 변화에 따른 유기적 통합 필요성에 기반한 정책 추진이다. 반면, 역대 사관학교장과 전직 교육사령관들은 각 군의 전문성 약화와 교육 질 저하를 우려하며, 미국·영국·프랑스 등 주변 강국이 독립 사관학교 체계를 유지하고 있음을 들어 통합의 타당성을 반박하고 있다. 현재 정부는 통합 교육 체제(1·2학년 통합, 3·4학년 군별 특화)를 검토 중이며, 국군사관학교를 대전에 신설하고 육사 이전 방안을 추진하고 있으나, 공론화 부족과 반발로 인해 정책의 방향성과 절차에 대한 논의가 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:49:55'::timestamp,'2026-07-27 16:40:17.848994'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1419,3045,'공정거래위원회는 대상, 사조CPK, 삼양사, CJ제일제당 등 4개사가 2018년 5월부터 2024년 10월까지 전분 및 전분당 가격을 담합한 혐의로 총 7475억7800만원의 과징금을 부과했다. 이는 지난 5월 밀가루 담합 사건(6710억원)을 넘어 공정위 역사상 최대 과징금이며, 전분당 가격은 2022년 기준 4년 전 대비 73% 상승한 것으로 조사됐다. 담합 기간 동안 4개사의 전분 시장 점유율은 95.7%, 전분당은 86.4%에 달했으며, 전분당 입찰 담합과 부산물 가격 조정 혐의에 대해 별도 심의를 진행 중이며, 검찰은 3개사 대표이사 등 25명을 기소했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:01'::timestamp,'2026-07-27 18:32:24.500887'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1420,3046,'국세청은 서울에 고가 아파트와 저가 아파트를 보유한 A씨가 양도차익이 큰 고가 아파트를 처분하기 전 저가 아파트를 모친의 지인 명의로 허위 이전해 1세대 1주택 비과세 혜택을 부당하게 적용받은 사례를 적발했다. A씨는 지인의 세금을 대납하고 거주를 계속하며 명의만 옮긴 가장매매로 판단되었으며, 국세청은 비과세 적용을 배제하고 다주택자 중과세율을 적용해 약 10억원의 양도소득세를 추징했다. 7일 기준, 국세청은 부동산 탈세 혐의자 104명에 대해 총 318억원의 세금을 추징하고, 탈루 혐의 금액은 731억원에 달했다. 국세청은 증여세 탈루, 명의신탁, 편법 증여 등에 대한 추가 조사와 함께 관련자 6명을 검찰에 고발하고, 20명에 대해 과징금 및 형사처벌 통보를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:08'::timestamp,'2026-07-27 18:32:06.923326'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1421,3052,'2024년 7월 7일 코스피 지수가 장 초반 5.51% 급락하며 7,800선 아래로 밀리자, 한국거래소는 오전 10시 23분 41초에 유가증권시장에 매도사이드카를 발동했다. 매도사이드카는 코스피200 선물이 5% 하락한 상태가 1분간 지속될 경우 5분간 프로그램매도를 일시 정지하는 변동성 제어 장치로, 이날 코스피200 선물의 급락이 발동 조건을 충족시켰다. 이날 오전 10시 34분 기준 코스피 지수는 전장 대비 444.02포인트(5.51%) 하락한 7,607.31을 기록했으며, 삼성전자와 SK하이닉스는 각각 7.08%, 5.80% 하락하며 시장 하락을 주도했다. 이후 매도사이드카 발동 후 시장의 변동성 제어와 함께 향후 5분간의 프로그램매도 정지 여부, 장 후반 시장 회복 가능성 및 외부 요인(글로벌 금리 동향, 미중 무역 긴장 등)이 시장에 미치는 영향이 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:14'::timestamp,'2026-07-27 18:19:56.014282'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1422,3056,'LG에너지솔루션은 2024년 2분기 연결 기준 매출 7조5602억원, 영업이익 1133억원의 잠정 실적을 공시하며 흑자 전환했으나, 전년 동기 대비 영업이익은 77.0% 감소했다. 이는 미국 인플레이션 감축법(IRA)의 첨단 제조 생산 세액공제(AMPC) 제도에 따른 북미 생산 보조금 2410억원이 반영된 결과로, 보조금을 제외한 순수 영업이익은 1277억원 적자이며 영업이익률은 마이너스 1.7%였다. 상반기 누계 실적은 매출 14조1152억원(전년 동기 대비 10.5% 증가)이며, 영업이익은 945억원 적자로 적자 전환했다. LG에너지솔루션은 보조금 회계 방식을 변경해 보조금을 매출 및 기타수익으로 표기하고 있으며, 현재 잠정 실적이며 외부 감사 완료 후 확정치가 달라질 수 있다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:19'::timestamp,'2026-07-27 18:00:11.714987'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1423,3058,'삼성전자는 2024년 2분기 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 창사 이래 역대 최고 실적을 달성했다. 이는 지난해 동기 대비 매출 129.31%, 영업이익 1810.26% 증가한 것으로, 인공지능(AI) 수요 확대에 따른 메모리 반도체 수익성 상승과 3분기 연속 사상 최고 실적 달성의 결과다. 영업이익은 증권가 컨센서스인 84조5994억원을 초과했으며, 성과급 충당금을 제외하면 실제 영업이익은 100조원을 넘을 것으로 추정된다. 이는 엔비디아의 분기 영업이익(약 82조원)을 상회하며, 글로벌 빅테크 중에서도 유례없는 수치이며, 2023~2025년 3년간 삼성전자의 예상 영업이익 총합보다도 높다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:25'::timestamp,'2026-07-27 17:52:50.385979'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1424,3062,'홈플러스는 2024년 3월 법원의 기업회생절차 폐지 결정으로 창사 30년 만에 파산 위기에 직면했다. MBK파트너스가 2015년 약 7조2000억원을 투입해 인수한 후, 차입금 상환을 위해 2016년부터 2024년까지 총 28개 점포와 물류창고를 매각해 4조1149억원을 확보했으며, 이로 인해 경쟁력이 약화됐다. 매각된 점포 일부는 세일 앤드 리스백 방식으로 운영되며 2023년 임차료 현금유출액이 4516억원에 달했고, EBITDA는 2019년 7351억원에서 2023년 3214억원으로 감소해 현금창출력이 부족했다. 코로나19 팬데믹 이후 온라인 유통 시장이 연평균 10.1% 성장한 반면 대형마트는 연평균 4.2% 감소했고, 정부의 대형마트 영업시간 제한 등 규제가 시장 변화에 대응하지 못한 점도 몰락의 원인으로 지적되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:33'::timestamp,'2026-07-27 17:22:48.465637'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1425,3063,'정부는 6일 광주 군공항 부지를 호남권 반도체 클러스터 입지로 선정하며, 임기 내 완공을 목표로 빠른 추진을 강조했다. 광주 군공항은 국유지로 구성된 820만㎡ 규모의 평탄한 부지로, 토지 보상 문제 없이 공사 절차를 신속히 진행할 수 있으며, 도심과 KTX역 인접으로 교통·용수·인력 확보가 용이하다. 이에 따라 용인 반도체 클러스터가 착공까지 6년이 걸린 반면, 광주 부지는 공기 단축과 부동산 투기 차단 효과를 기대할 수 있다. 정부는 용인과 호남 클러스터를 병행 추진하며, 기업의 자율 설계와 함께 설계 및 인프라 구축 절차를 가속화할 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:39'::timestamp,'2026-07-27 17:22:28.697450'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1426,3067,'삼성카드는 홈플러스의 회생절차 폐지 결정 이후 오프라인 가맹점 대금 지급 보류를 철회하고, 7일부터 정상 지급을 재개하기로 밝혔다. 홈플러스는 회생절차 폐지 결정이 확정되지 않았고, 카드사가 이를 근거로 포인트 제휴 계약 종료를 통지한 것은 법적 요건을 충족하지 못했다고 반발했다. 삼성카드는 매출 취소 증가 추세로 인해 고객 피해를 방지하기 위해 일시적으로 지급 보류 조치를 취했으나, 이후 매출 취소 추이가 안정화되면서 보류 철회를 결정했다. 현대카드는 포인트 결제 서비스는 중단했으나 가맹점 대금 지급은 계속하고 있으며, 홈플러스의 온라인 영업 중단과 주문 취소 불가 상황에 대한 대응 방안이 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:44'::timestamp,'2026-07-27 17:18:23.388859'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1427,3078,'정부는 호남권 반도체 클러스터 투자 계획 발표 후 일주일 만인 6일 광주 군 공항 부지를 산업단지 입지 후보지로 선정했다. 이 부지는 국방부 소유의 국유지로, 총 820만㎡ 규모이며, 평탄화 작업이 이미 완료되어 대규모 반도체 공장 건설에 적합한 조건을 갖추고 있다. 정부는 민간 토지 보상 문제로 6년이 걸린 용인 반도체 클러스터와 달리, 국유지 특성상 행정 절차를 신속히 진행할 수 있어 ''임기 내 완공''을 목표로 속도전을 추진하고 있다. 이후 건축 설계 자율성 확대와 함께 용인 산단과의 병행 추진 가능성도 시사하며, 부동산 투기 억제와 생산 능력 확대 경쟁에 대응하는 전략을 세우고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:50'::timestamp,'2026-07-27 17:04:36.787995'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1428,3080,'서울 아파트 전세시장에서 신규계약과 재계약 간 보증금 격차가 심화되며 ''이중가격'' 현상이 발생했다. 전세 매물 부족으로 전셋값이 상승하면서 신규계약은 시세 상승을 반영해 보증금이 크게 오르는 반면, 재계약은 전월세상한제에 따라 보증금을 5% 이상 올릴 수 없어 상대적으로 오름폭이 제한된다. 직방 분석에 따르면 서울 59㎡ 아파트의 신규계약 보증금은 1월 5억원에서 6월 5억4750만원으로 4750만원 상승한 반면 재계약은 500만원 상승에 그쳤고, 차이는 6월 기준 7750만원으로 두 배 이상 확대됐다. 이에 따라 재계약 비율은 3월 48%에서 6월 55%로 증가했으며, 전세수급지수는 3월 103.2에서 6월 126.7로 상승해 수요가 공급을 상회하는 상황이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:50:56'::timestamp,'2026-07-27 17:02:29.076284'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1429,3081,'홈플러스는 2024년 3월 법원의 기업회생절차 폐지 결정으로 파산 절차 진입 가능성이 커졌다. 홈플러스는 1997년 창사 이후 2015년 MBK파트너스에 매각되었으며, MBK는 인수대금 약 7조2000억원 중 2조7000억원을 차입으로 조달해 2016년부터 2024년까지 점포와 물류창고 28곳을 매각해 4조1149억원을 확보한 것으로, 이 과정에서 경쟁력 약화와 임차료 부담 증가로 인해 2021년부터 2023년까지 5년 연속 적자(누적 손실 2조7341억원)를 기록했다. 코로나19 팬데믹 이후 온라인 유통의 급속한 성장(연평균 10.1%)과 대형마트 매출 감소(연평균 4.2%) 속에서 홈플러스는 신규 투자 여력 부족으로 온라인 전환에 실패했고, 2023년 EBITDA는 3214억원으로 2019년 7351억원에서 절반 이상 감소했다. 현재 홈플러스는 회생절차 폐지 결정에 대한 즉시항고를 준비 중이며, 카드사의 포인트 제휴 종료 통보에 대해 법적 효력이 없다는 입장이지만, 향후 파산 절차 진행 여부와 자산 매각, 주주 및 채권자 간 협의가 진행될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:07'::timestamp,'2026-07-27 17:01:54.379258'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1430,3085,'신한은행은 2024년 6월 6일 ''2026년 하반기 경영전략회의''를 개최하고, 고객 접점 확대와 차별화된 솔루션 제공을 핵심 전략으로 발표했다. 이 회의는 정상혁 은행장과 약 180명의 임직원이 참석한 가운데, 고객 기반의 수평적 확장과 관계의 수직적 심화를 의미하는 ''와이드 앤드 딥''(Wide & Deep) 전략을 제시했다. 주요 추진 방향으로는 고객관리 및 영업 지원 솔루션 고도화, 그룹 통합 앱 ''신한 슈퍼SOL''과 비금융 플랫폼을 통한 접점 확장, 인공지능 전환(AX)을 통한 업무 생산성 제고가 포함됐다. 이후 신한은행은 이 전략을 바탕으로 고객 중심의 서비스 혁신을 지속적으로 추진하며, 2026년 하반기까지 실질적인 성과를 도출할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:11'::timestamp,'2026-07-27 17:00:44.323889'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1431,3088,'2026년 7월 7일, 시민사회 각계 대표자 135명은 서울 정동 민주노총에서 홈플러스 회생 방안 마련을 위해 이재명 대통령과의 면담을 요구하며 정부의 긴급 개입을 촉구했다. 홈플러스는 3일 법원의 기업회생절차 폐지 결정을 받아 창사 30년 만에 파산 위기에 놓였으며, 회생을 위한 최소 2000억원의 운영자금을 20일까지 조달하지 못할 경우 파산 절차에 들어간다. 정부는 임금 체불 노동자에게 최대 2100만원까지 대지급금을 지급하고, 홈플러스의 주요 거래처인 중소기업과 소상공인에 4400억원 규모의 긴급 유동성 지원을 결정했으나, 사태 해결의 마지막 기회를 놓쳤다는 비판이 제기된다. 시민사회는 MBK파트너스의 투기적 자본 운영과 정부의 미흡한 감독을 문제 삼으며, 정부의 공적자금 투입과 MBK에 대한 수사 강화를 요구하고 있으며, 향후 회생 절차 재개 여부와 정부의 추가 대응 방안이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:19'::timestamp,'2026-07-27 18:57:02.453066'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1432,3101,'2024년 7월 7일, 권창영 2차 종합특별검사팀은 김건희 여사의 최측근으로 지목된 유경옥 전 대통령실 행정관을 특정범죄가중처벌법상 알선수재 방조 혐의로 피의자 신분으로 조사했다. 이는 대통령 관저 이전 공사 과정에서 종합건설업 면허가 없는 21그램이 김 여사와의 친분을 이용해 부당하게 수주했다는 의혹과 관련된 것으로, 유 전 행정관은 21그램이 김 여사에게 명품 의류를 제공한 사실을 알고 있었는지 등에 대해 조사받았다. 특검팀은 지난 4월 유 전 행정관의 휴대전화 압수수색을 통해 증거를 확보하고 참고인에서 피의자로 신분을 전환했으며, 이원모 전 인사비서관도 황제 조사 의혹과 관련해 참고인 신분으로 조사됐다. 현재 특검팀은 대통령실 등 윗선의 수사 개입 여부와 김 여사가 지정한 조사 일정을 검찰에 전달한 경위를 집중 조사하고 있으며, 이는 향후 수사의 방향성과 정치적 영향에 중요한 변수가 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:25'::timestamp,'2026-07-27 18:35:56.072157'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1433,3103,'정이한 전 개혁신당 부산시장 후보가 2024년 4월 27일 부산 금정구 구서나들목에서 선거 유세 중 차량에서 던진 음료에 맞아 부상당했다고 주장했으나, 이후 경찰 조사에서 그와 음료 투척 운전자 A씨가 사전에 통화한 사실이 드러나 자작극 의혹이 제기됐다. A씨는 정이한과 친분이 있던 헬스 트레이너로 확인되었으며, 경찰은 두 사람이 공모해 사건을 조작했을 가능성을 고려하고 있다. 경찰은 위계에 의한 공무집행방해 및 공직선거법 위반 혐의로 정이한과 A씨에 대해 구속영장을 신청했고, 8일 오후 2시 부산지법에서 구속 전 피의자 심문이 예정되어 있다. 이와 별개로 정이한 부친이 운영하는 병원의 의료법 위반 및 선거 개입 여부에 대한 수사도 병행 중이며, 사건의 진상 규명과 후속 조치가 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:31'::timestamp,'2026-07-27 18:29:28.177271'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1434,3106,'서울시가 전·월세 부담이 큰 무주택 출산 가구를 대상으로 월세를 최대 2년간 월 30만원씩 지원하는 ''자녀 출산 무주택 가구 주거비 지원 사업''을 하반기 접수 중이다. 기존 전세보증금 3억원 이하에서 5억원 이하로 요건을 완화하고, 부모 모두 무주택자이며 기준 중위소득 180% 이하인 가구가 신청 가능하며, 출생 신고지와 거주지가 서울이어야 한다. 올해 상반기 신청 가구는 지난해 전체 대비 88% 증가한 1754가구로, 지원금은 전세대출 이자 및 월세 납부 내역을 증빙한 후 6개월 단위로 4회 분할 지급되며, 자녀 1명당 지원 기간이 1년씩 연장되어 최대 4년까지 가능하다. 하반기 신청 기간은 7월 1일부터 12월 31일까지이며, 자격 검증 후 2027년 1월 결과 발표 후 2월부터 지원금 지급이 시작되며, 출산 후 1년 이내 신청이 필수이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:37'::timestamp,'2026-07-27 18:26:33.660207'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1435,3122,'2024년 3월 미·이란 전쟁 발발 직후 HD현대오일뱅크와 SK에너지가 유가를 담합해 14조2000억원 규모의 가격 인상에 나선 혐의로 서울중앙지검이 법인과 관련 책임자들을 기소했다. 이들은 전쟁 발발 직전까지 원유를 대량 비축한 상황에서 가격 인상 사유가 없음에도 불구하고 사전에 가격 조정을 합의했으며, GS칼텍스와 에쓰오일도 이에 편승해 유가를 올렸다. 검찰은 이로 인해 4대 정유사 간 약 26조원의 경쟁 제한 효과가 발생했고, 사내 메신저를 통한 가격 인상 공모 및 증거인멸 시도도 확인했다. 검찰은 전량구매계약 관행과 공정거래위원회 조사에 대한 방해 행위도 적발해 관련 법인과 임원들을 조사방해 혐의로 기소했으며, 향후 공정거래위원회의 추가 조사와 법적 처벌 절차가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:43'::timestamp,'2026-07-27 17:24:12.535066'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1436,3124,'서울 배재고등학교 야구부 학생들이 5·18민주화운동 폄하 및 지역 비하 응원 구호를 외친 사건에 대해 6일 전남 광주 북구 광주제일고등학교를 찾아 사과했다. 이는 지난 5월 29일 서울 목동구장에서 열린 청룡기 전국고교야구선수권대회에서 발생한 것으로, 배재고 학생들이 ''스타벅스 가야지'', ''탱크데이'' 등의 조롱성 구호를 외쳐 사회적 비판을 받았다. 사과 행사는 광주일고 학생들과 함께 국립5·18민주묘지 참배와 광주학생독립운동기념탑 헌화로 이어졌으며, 서울시교육감과 전남광주통합특별시교육감이 교육적 의미를 강조했다. 배재고는 대한야구소프트볼협회로부터 6개월 출전 정지 징계를 받았고, 이후 사과와 화해의 과정을 통해 교육적 성찰의 기회로 삼고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:50'::timestamp,'2026-07-27 17:23:41.670993'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1437,3126,'서울 마포구 홈플러스 합정점과 성북구 월곡점 등 주요 점포에서 법원의 회생절차 폐지 결정 이후 상품이 대거 사라지고, 카드 결제가 중단되며 매장이 텅 빈 상태로 전락했다. 회생절차 폐지 결정 이후 납품업체들이 상품 공급을 중단하고, 입주업체들은 결제 시스템을 중단하며 매장 운영이 사실상 정지됐으며, 일부 무인 계산대도 인력 부족으로 운영 중단됐다. 현재까지 홈플러스는 법원이 제시한 2주 내 2000억원 운영자금 조달을 못할 경우 파산 절차에 들어가며, 전국 60여개 점포와 9000여명의 직원이 일자리 위기에 직면한 상태다. 이후 20일까지 자금 조달 여부가 결정될 예정이며, 메리츠금융그룹과 대주주 MBK파트너스의 입장이 향후 회생 가능성에 큰 영향을 미칠 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:51:57'::timestamp,'2026-07-27 17:23:15.442346'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1438,3129,'2024년 5월 광주에서 귀가 중이던 여고생을 살해한 장윤기(23) 사건을 맡았던 광산경찰서 수사팀장 A경감이 범행 증거인 케이블타이를 압수하지 않고 수사 서류에 ''압수할 물건 없음''이라고 기재한 혐의로 긴급체포됐다. A경감은 차량에서 발견된 케이블타이를 인멸하고, 장씨 아버지가 훼손된 성인인형을 폐기할 때 주소와 비밀번호를 제공하는 등 경찰 가족을 감싸는 정황이 확인됐으며, 리얼돌에서 장씨의 DNA가 검출된 사실도 수사 초기에 알리지 않았다. 검찰은 추가 압수수색을 통해 블랙박스 메모리카드를 확보하고, 장씨가 범행 전까지 사용한 블랙박스를 확보하지 못한 상태로 수사가 진행됐음을 확인했으며, 현재 특별수사팀이 독립적으로 수사 중이다. 국가수사본부는 수사전담팀을 ''광주광산서 살인사건 관련 진상규명 특별수사팀''으로 확대하고, 홍장득 총경을 팀장으로 임명해 총 27명 규모로 운영하며, 수사 과정의 공정성과 투명성을 확보할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:05'::timestamp,'2026-07-27 17:20:26.386146'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1439,3138,'중국 해군은 6일 남중국해에서 핵잠수함을 통해 잠수함발사탄도미사일(SLBM)을 시험 발사했다. 이 발사는 호주와 피지의 상호방위조약 체결식과 겹쳐, 역내 국가들의 우려를 불러일으켰으며, 특히 뉴질랜드와 호주는 미사일이 남태평양 비핵지대 내로 발사됐다고 지적했다. 발사된 미사일은 JL-2로 추정되며, 직선 거리 약 6000~7000km에 달하는 비행 경로를 보였고, 미국은 사전 통보를 받지 못한 점을 문제 삼았다. 중국은 이번 발사가 연례 훈련의 일환으로 국제법에 부합하며 특정 국가를 겨냥하지 않았다고 설명하며, 주변국의 과도한 해석을 경계했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:10'::timestamp,'2026-07-27 18:55:11.002109'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1440,3140,'2024년 4월 7일 일본 정부는 중국이 하이난섬 동쪽 해역에서 태평양을 향해 잠수함발사탄도미사일(SLBM)을 시험 발사한 것을 계기로 국가안전보장전략, 국가방위전략, 방위력정비계획 등 3대 안보 문서의 연내 개정을 속도감 있게 추진하겠다고 밝혔다. 중국의 SLBM 발사는 남중국해에서 출발해 남태평양에 미사일을 떨어뜨리는 방식으로 진행되었으며, 이는 중국의 핵무기 증강 가능성과 불투명한 군사 전략에 대한 국제적 우려를 초래했다. 일본 정부는 방위력 증강과 방위비 확충을 포함한 안보 문서 개정을 추진하며, 핵 반입 금지 등 비핵 3원칙의 유지 여부도 검토 대상에 포함할 수 있다고 밝혔다. 한편 나토 사무총장은 중국의 발사 실험에 대해 ''달콤한 생각으로 대응할 수 없다''며 경계를 표명했으며, 나토 정상회담에서 한국·일본·호주·뉴질랜드와의 회담을 통해 중국 SLBM 발사에 대한 논의가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:17'::timestamp,'2026-07-27 18:48:00.735595'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1441,3141,'도널드 트럼프 미국 대통령은 2022년 카타르 월드컵 32강전에서 레드카드를 받은 미국 대표팀 공격수 폴라리 발로건의 출전정지 결정을 뒤집기 위해 잔니 인판티노 FIFA 회장과 직접 통화한 사실을 인정했다. 이는 축구 규정상 레드카드 시 자동 출전 정지가 적용되나, FIFA는 27조 규정에 따라 징계 집행을 1년간 유예한다고 결정했다. 그러나 이 결정에 대해 유럽 각국과 유럽축구연맹(UEFA)은 ''정치적 개입''이라며 강력 반발하며, 벨기에 대표팀은 경기 후 트럼프 대통령의 춤을 모방한 세리머니로 조롱했고, 브라질 축구협회도 심판에 대한 비난을 거부했다. 이후 유럽 정부와 국제 스포츠 기관은 트럼프의 ''미국 우선주의''가 스포츠의 독립성과 공정성을 훼손했다며 FIFA의 결정 과정에 대한 조사와 제재를 요구하며, 나토 정상회담을 앞두고 유럽의 대미 태도 변화를 예고하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:24'::timestamp,'2026-07-27 18:39:12.636128'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1442,3143,'미국 국무부는 중국군이 5일(현지시간) 남태평양 공해상에서 잠수함에서 비무장 대륙간 탄도 미사일을 시험 발사한 것을 두고 ''불투명한 핵무기 증강''으로 세계에 우려를 불러일으키고 있다고 지적했다. 이 발사는 중국 해군 전략핵잠수함이 연례 군사 훈련의 일환으로 국제법과 관례에 따라 진행한 것으로, 중국 외교부는 특정 국가나 목표물을 겨냥한 것이 아니라고 설명했다. 미국은 중국의 핵무기 증강이 지역 안보와 국제 군비 통제에 부정적 영향을 미치고 있으며, 유엔 안보리 상임이사국의 약속에 따라 대륙간 탄도미사일 및 우주 발사체에 대한 정기적 통보를 이행할 것을 촉구했다. 이후 미국은 동맹국 방위 약속을 강화하며, 중국과의 의미 있는 군비 통제 논의 참여를 재차 요구하며 향후 외교적 대응 방향이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:29'::timestamp,'2026-07-27 18:17:51.375962'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1443,3148,'지난 24일(현지시간) 베네수엘라에서 발생한 연쇄 지진으로 사망자가 3535명으로 집계됐으며, 이는 전날보다 193명 증가한 수치다. 지진은 라과이라주 카라바예다 등 지역에 피해를 주며 총 856채의 건물이 피해를 입었고, 그중 190채가 완전히 붕괴됐다. 부상자는 1만6740명, 이재민은 1만7854명으로 집계되었으며, 정부는 육군과 보안군 2만9567명, 자원봉사자 2만7930명을 동원해 구조·복구 작업을 진행 중이다. 현재까지 구조된 인원은 6462명이며, 지진 발생 후 10일이 경과하면서 생존 가능성은 낮아졌고, SNS를 통한 오보도 발생해 당국이 사실 여부를 바로잡고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:34'::timestamp,'2026-07-27 17:52:14.008255'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1444,3149,'캐나다 정부는 차세대 잠수함 사업의 우선협상대상자로 독일 방산업체 티센크루프마린시스템(TKMS)을 선정했다. 이 사업은 잠수함 건조비만 200억~300억캐나다달러(약 21조~32조원)이며, 30년간 운영·유지보수 포함 총사업비는 최대 500억캐나다달러(약 54조원)로 예상된다. 한화오션이 제안한 2026~2044년 동안 700억달러 이상의 교역·투자와 연간 2만5000명 이상 고용 창출 계획에도 불구하고, TKMS는 나토 동맹국으로서의 협력 관계와 풍부한 수출 실적을 내세워 승리했다. 캐나다는 냉전 이후 최대 규모의 국방력 강화를 추진하며, 2035년까지 국방비를 GDP의 5%로 확대할 계획이며, 현재 보유한 잠수함은 중고 4척에 불과해 실질 작전 가능 잠수함은 1척 정도로 알려져 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:41'::timestamp,'2026-07-27 17:24:42.857703'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1445,3150,'나토는 7일 튀르키예 앙카라에서 연례 정상회의를 개최하며, 도널드 트럼프 미국 대통령의 그린란드 병합 추진과 이란 전쟁 이후 유럽 회원국들과의 갈등이 심화된 상황에서 동맹 결속을 강조할 예정이다. 트럼프 대통령은 회원국들이 국방비를 충분히 분담하지 않아 미국의 의존도가 높다고 비판하며, 이란 공습 후 동맹국들의 군함 파견 요청 거부에 대해 나토 탈퇴와 미군 철수를 경고한 바 있다. 이번 회의에서는 나토 상호방위 조항 제5조가 재확인되며, 미국을 제외한 회원국들의 국방비 지출이 지난해 기준 전년 대비 20% 증가한 5740억달러(약 880조원)로 집계된 점이 공식적으로 부각될 전망이다. 우크라이나 전쟁, 이란과의 종전 양해각서 후속 협상, 호르무즈 해협 해양 안보 협력 방안 등이 주요 의제로 다뤄지며, 나토의 향후 방향성과 동맹 내 신뢰 회복이 핵심 쟁점으로 부각된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:47'::timestamp,'2026-07-27 17:20:47.784368'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1446,3151,'이란 테헤란에서 6일(현지시간) 전 최고지도자 아야톨라 알리 하메네이의 장례식 사흘째 행사가 열렸으며, 수백만 명이 참석해 반미 정서를 드러냈다. 하메네이의 죽음에 대한 보복을 요구하는 ''킬 트럼프'' 구호와 미국·이스라엘에 대한 적대감이 반복되며, 지도부는 미국·이스라엘 정치 지도자에 대한 보복과 처벌을 공식적으로 시사했다. 장례행렬은 이맘 후세인 광장에서 출발해 아자디 광장까지 이어졌으며, 시아파의 순교자와 동일시되는 상징적 표현이 대거 등장했고, 이란은 군중 규모를 통해 내부 결집력과 외부에 대한 메시지를 전달했다. 장례식은 9일 마슈하드의 이맘 레자 성지에서 안장되며, 중부 성지 곰과 이라크의 나자프·카르발라를 경유하며 도로와 공항이 통제되고 일부 영화관에서는 코미디 상영이 제한된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:54'::timestamp,'2026-07-27 17:19:46.895148'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1447,3153,'도널드 트럼프 미국 대통령은 7일 튀르키예 앙카라에서 열린 나토 정상회의에서 유럽 동맹국들에게 국방비 증액과 미국산 무기 구매를 압박하며 ''충성심''을 요구할 전망이다. 나토 회원국들은 GDP 대비 5% 국방비 지출을 약속했으나, 일부 국가는 이행이 미흡한 상태이며, 지난해 약 1200억달러의 국방비 지출 약속 중 절반을 미국산 무기 구매에 투자하기로 한 바 있다. 현재 유럽은 미국산 무기 주문 규모가 3000억달러에 달하며, 영국과 독일은 라이선스 생산을 통해 미국 무기 수출을 확대하고 있다. 이후 유럽은 미국의 요구에 따라 동맹 내 군사적 자립성 확보를 위한 장기적 전략 수립과 미국에 대한 의존도 조정이 필요하다는 쟁점이 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:52:59'::timestamp,'2026-07-27 17:19:11.575335'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1448,3158,'2024년 6월 6일(현지시간) 이란 테헤란에서 아야톨라 알리 하메네이 전 최고지도자의 장례식이 열렸으며, 수백만 명의 시민이 참석해 미국과 이스라엘에 대한 복수를 요구하는 반미 정서를 드러냈다. 하메네이의 죽음은 이란 내부의 반미 감정이 고조된 결과로, 이전 트럼프 행정부의 이란 정권 교체 촉구 발언과 미·이란 간 긴장 관계가 배경이 되었다. 장례행렬은 이맘 후세인 광장에서 출발해 아자디 광장까지 이어졌으며, 관은 10km의 경로를 약 10~12시간 동안 이동했고, 참가자들은 관에 닿기 위해 스카프 등을 제출하며 축복을 구했다. 이란 지도부는 미국·이스라엘 지도자에 대한 보복을 공식적으로 선언했으며, 장례식은 9일 마슈하드의 이맘 레자 성지에서 안장되며 도로와 공항 통제가 지속될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:06'::timestamp,'2026-07-27 17:01:02.662250'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1449,3159,'나토는 7일 튀르키예 앙카라에서 연례 정상회의를 개최하며, 도널드 트럼프 행정부의 그린란드 병합 추진과 대이란 전쟁 동참 요청 거부 등으로 인한 미국과 회원국 간 갈등을 봉합하고 향후 방향성을 논의한다. 트럼프 대통령은 나토 회원국들이 국방비를 충분히 분담하지 않아 미국에 의존한다고 비판하며, 이란 공습 후 동맹국들의 군함 파견 요청을 거부한 것에 대해 나토 탈퇴와 유럽 미군 철수를 압박했다. 이번 회의에서는 제5조 상호방위 조항 재확인, 2035년까지 국방비를 GDP의 5%로 증액하기로 한 32개국 합의 이행 점검, 지난해 국방비 5740억달러(약 836조7500억원)로 전년 대비 20% 증가한 실적 등이 주요 논의 사안이 될 전망이다. 이란·우크라이나 문제와 호르무즈 해협 해양 안보, 젤렌스키 우크라이나 대통령과의 양자 회담 등도 의제로 다뤄지며, 미국의 역할 축소와 유럽의 자체 안보 역량 강화 필요성에 대한 공감대 형성도 논의될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:13'::timestamp,'2026-07-27 17:00:26.736151'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1450,3160,'베네수엘라 라과이라주에서 6월24일 발생한 연쇄 강진으로 사망자 수가 5일 기준 3342명으로 증가했다. 이 지진은 라과이라주 카티아 라마르 지역의 건물 대부분을 무너뜨리며, 유엔과 민간 기관은 최대 5만명의 실종을 추산했고, 신원 미상 시신 150구는 공동묘지에 매장됐다. 피해 복구 비용은 유엔개발계획 추산 약 67억달러, 인권단체 프로베아는 총 370억달러(국내총생산(GDP)의 약 40%)가 필요하다고 전망하며 국제 지원을 촉구했다. 현재 일부 지역은 전력과 통신이 복구되지 않았고, 주민들은 식량과 물 부족, 약탈 등 치안 문제에 시달리며 임시 정부의 대응에 대한 비판이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:20'::timestamp,'2026-07-27 16:59:55.542724'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1451,3164,'도널드 트럼프 미국 대통령은 2024년 7월 7일 터키 앙카라에서 열리는 나토 정상회의에서 유럽 동맹국들에게 국방비 증액과 미국산 무기 구매를 압박할 전망이다. 이는 나토 회원국들이 지난해 1200억달러 규모의 국방비 지출 약속을 이행하지 못했고, 특히 이란 전쟁에 참여하지 않은 국가들에 대한 불만이 반영된 것으로, 미국은 동맹국들의 방위비 증액을 미국 무기 수출 확대와 연결하려는 전략을 추진하고 있다. 현재 유럽은 미국산 무기 3000억달러 규모의 주문 계획을 발표했으며, 영국과 독일은 라이선스 생산을 통해 자국 내 생산을 확대하고 있다. 그러나 트럼프 행정부는 충성심을 강조하며 무기 구매 외에도 동맹국들의 정치적 협력 요구를 내세우며, 이에 대한 유럽의 반응은 의존과 자율성 사이의 균형을 모색하는 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:26'::timestamp,'2026-07-27 16:52:38.422306'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1452,3165,'2024년 9월 3일(현지시간) 미국 뉴욕 매디슨 스퀘어가든에서 팝스타 테일러 스위프트와 미식축구 선수 트래비스 켈시의 결혼식이 비밀리에 치러졌다. 결혼식에는 폴 매카트니가 축가로 1964년 이후 62년 만에 ''아이 원트 홀드 유어 핸드''를 불러 화제가 되었으며, 배우 애덤 샌들러가 주례를 맡았다. 참석자는 가족·친구·지인 포함 1000명 이상으로, 식장 인근 교통 통제와 삼엄한 경비로 인해 지역 상인과 주민들 사이에서 전력난과 영업 피해에 대한 불만이 제기되었다. 결혼식 전 스위프트 부부는 뉴욕 지역 및 국립 자선단체 20곳에 총 2600만 달러(약 400억 원)를 기부했으나, 여전히 호화 결혼식에 대한 비판 여론이 지속되고 있으며, 정보 통제와 비밀 유지 조항의 철저함이 권력과 영향력의 상징으로 지적되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:33'::timestamp,'2026-07-27 16:51:54.837094'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1453,3168,'이란 전 최고지도자 아야톨라 하메네이의 장례식이 2024년 2월 5일(현지시간) 테헤란 그랜드 모살라 모스크에서 열렸으며, 미국과 이스라엘의 공습으로 175명이 사망한 미나브 여자초등학교 희생자 유가족이 참석했다. 이 공습은 2024년 2월 28일 이란 전쟁 개시 첫날에 발생했으며, 미군 토마호크 미사일로 추정되나 미국은 책임을 인정하지 않고 있으며, 국방부는 4개월이 넘도록 조사 결과를 발표하지 않았다. 장례식에는 이란 대통령, 국회의장, 혁명수비대 신임 사령관 등 고위 관료들이 참석했으며, 유가족들은 약 1287km를 이동해 참석했고, 테헤란 도심에는 희생 어린이들을 기리는 추모 조형물이 설치됐다. 하메네이의 유해는 곰으로 이동한 뒤 이라크 나자프·카르발라를 거쳐 고향 마슈하드에 안장될 예정이며, 후계자로 지목된 모즈타바 하메네이는 안전 문제로 참석하지 않았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:40'::timestamp,'2026-07-27 16:48:23.634077'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1454,3169,'도널드 트럼프 미국 대통령은 2023년 7월 4일(현지시간) 워싱턴DC 내셔널몰에서 열릴 예정이었던 독립기념일 행사가 폭우로 취소된 후, 자신의 결정으로 행사 재개를 지시했다. 행사 당일 오후 7시 5분 기준 약 42만4000명이 모였으나, 악천후로 인해 대피가 필요해졌고, 이에 따라 행사가 중단됐다. 트럼프 대통령은 행사 재개 결정을 내리고, 약 15만명이 다시 행사장으로 복귀하면서 원래 예정보다 더 큰 규모로 행사가 진행됐으며, 연설은 오후 11시 15분에 시작됐고 불꽃놀이는 자정 무렵에 열렸다. 이후 트럼프 대통령은 비밀경호국(SS)과 법 집행기관의 대응을 치하하며 행사의 성공을 강조했고, 이에 대해 일부는 행사 재개 결정의 적절성과 안전성에 대한 논의가 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:45'::timestamp,'2026-07-27 16:46:39.220245'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1455,3171,'네타냐후 이스라엘 총리는 2024년 4월 5일 폭스뉴스에 출연해 이스라엘군이 레바논 남부의 보포르 능선과 리타니강 인근에서 헤즈볼라에 대한 작전을 지속하며 필요한 만큼 머물 것이라고 밝혔다. 이는 미국과 이란이 맺은 종전 양해각서(MOU) 제1조에서 요구하는 ''레바논 포함 모든 전선의 군사 작전 중단''과 충돌하며, 이스라엘은 협상 당사자가 아니며 헤즈볼라 무장해제 전까지 철수하지 않겠다는 입장을 고수하고 있다. 이에 따라 이스라엘군은 레바논 남부에서 지속적인 군사 작전을 수행하고 있으며, 이란과 미국의 협상 과정에서 트럼프 대통령과의 불화설이 제기되었으나 네타냐후는 ''99%의 생각이 같으며 균열이 없다''고 반박했다. 현재 이스라엘은 외교적 합의 여부와 관계없이 이란의 핵무기 보유를 막겠다는 입장이며, 향후 이란과 미국의 협상 결과에 따라 이스라엘의 레바논 주둔 정책이 어떻게 변화할지가 주요 쟁점으로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:52'::timestamp,'2026-07-27 16:45:10.387395'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1456,3172,'2024년 1월 1일(현지시간) 베네수엘라에서 발생한 연쇄 강진으로 사망자가 3000명에 육박하고, 유엔은 실종자가 5만~6만명에 이를 것으로 추산했다. 피해가 가장 심각한 북부 항구 도시 라과이라 지역은 폐허가 되었으며, 수도 카라카스도 일부 건물이 무너지는 등 대규모 피해를 입었다. 굿네이버스 대응단장은 정부가 구호품 반입 절차를 마련하지 않아 국제구호 물자 반입이 지연되고 있으며, 현지에서의 물자 조달도 어려운 상황이라고 밝혔다. 현재 베네수엘라 정부는 재난 대응 클러스터 미팅을 개최하지 않아 구호 단체 간 협력이 원활하지 않고, 복구 속도는 정부의 컨트롤 역량에 달려 있어 장기적 재건이 어려울 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:53:59'::timestamp,'2026-07-27 16:43:22.738339'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1457,3173,'2024년 7월 4일 미국 워싱턴 내셔널몰에서 열린 건국 250주년 기념행사에서 도널드 트럼프 대통령은 ''프리덤250''을 주도하며 독립기념일을 자신의 정치적 이념을 강조하는 장으로 활용했다. 이는 2016년 설립된 초당적 ''아메리카250'' 위원회가 10년간 준비한 행사와 달리, 트럼프 행정부가 행정명령으로 별도의 기념 프로그램을 운영하며 권한과 예산을 몰아준 데서 비롯된 것으로, 악천후와 행사 취소, 불꽃놀이 지연 등으로 인해 파행을 빚었다. 행사에서는 86만 발의 불꽃놀이와 에어쇼가 진행되었으나, 트럼프 대통령은 진보주의자를 ''공산주의자''로 낙인찍고 부정선거 음모론을 제기하며 반이민 정서를 부채질했고, 중간선거를 앞두고 선거법 개정을 촉구하며 정치적 갈등을 조장했다. 이에 대해 AP통신은 트럼프의 연설이 역대 독립기념일 행사처럼 국민통합을 강조하는 것이 아니라 당파적 정치와 애국주의를 혼합한 이례적인 사례로 평가했으며, 향후 정치적 분열과 민주주의에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:07'::timestamp,'2026-07-27 16:40:54.916838'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1458,3174,'이란의 아야톨라 알리 하메네이 전 최고지도자가 2024년 2월 미국과 이스라엘의 공습으로 사망한 후, 5일(현지시간)부터 테헤란에서 장례식이 진행되고 있다. 장례식은 9일까지 총 6일간 진행되며, 중국·러시아 등 70개국 이상의 대표단이 참석했고, 조문객 규모는 1500만명에 달할 것으로 예상된다. 이란 정부는 학교 수천 곳을 임시 숙소로 개방했으며, 테헤란 지하철 이용 건수는 첫날만 700만건을 넘어섰다. 이란은 장례식 이후 11일 파키스탄에서 재개되는 미국과의 실무협상에서 대이란 제재 해제 및 핵 프로그램 논의를 추진할 예정이며, 트럼프 전 미국 대통령은 이 기간을 ''일주일 휴가''로 평가하며 무력 충돌을 피하겠다는 입장을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:13'::timestamp,'2026-07-27 16:39:45.014324'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1459,3177,'이란 전 최고지도자 아야톨라 알리 하메네이의 장례식이 2024년 5월 4일(현지시간) 이란 테헤란의 그랜드 모살라에서 시작됐으며, 9일까지 총 6일간 진행된다. 하메네이는 2월 미국과 이스라엘의 공습으로 사망했으며, 장례식 기간 동안 테헤란을 비롯한 이란 전역에서 수백만 명의 조문객이 몰렸고, 중국·러시아 등 70여 개국 대표단이 참석했다. 장례식 첫날 오후 5시30분부터 이튿날 오전 7시까지 테헤란 지하철 이용 건수가 700만 건을 넘었으며, 조문객 1500만 명이 예상된다. 새 최고지도자로 지명된 하메네이의 아들 모즈타바는 장례식 기간 동안 공개되지 않았고, 이란 보안당국이 그의 안전을 우려해 9일 마슈하드 안장식 참석을 허가하지 않았다는 보도가 나왔으며, 이란과 미국의 실무협상은 11일 파키스탄에서 재개될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:21'::timestamp,'2026-07-27 16:38:10.409584'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1460,3178,'이란 최고지도자 알리 하메네이의 장례식(2024년 3월 3일, 테헤란)에 그의 아들인 모즈타바 하메네이가 참석하지 않아 이란 지도부 내부의 분열이 심화되고 있다. 모즈타바는 장례식 참석을 원했으나 보안 당국이 신변 보호를 이유로 거부했으며, 이후 공개적 행보를 자제하며 지도력에 대한 의문이 확산되고 있다. 현재 이란 내 실용주의 세력(페제시키안 대통령, 갈리바프 의회 의장, 졸가드르 안보총장 등)이 후속 협상과 정책 결정을 주도하고 있으나, 강경파는 이 협상이 이란의 주권과 이념을 훼손할 수 있다고 우려하고 있다. 모즈타바가 장례식 이후 사법부, 국영 방송, IRGC 산하 바시즈 민병대 등 요직 인선을 시작할 것으로 예상되며, 이는 이란 지도부의 향후 방향을 결정짓는 중요한 계기가 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:27'::timestamp,'2026-07-27 16:37:39.237963'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1461,3179,'미국 건국 250주년을 기념해 4일(현지시간) 워싱턴 내셔널몰에서 86만발의 불꽃놀이가 터졌으나, 폭염과 뇌우·태풍 예보로 인해 퍼레이드 취소, 실내 행사 전환 등 차질을 빚었다. 이는 트럼프 대통령이 2016년부터 준비된 초당적 기념위원회 ''아메리카250''을 대체해 ''프리덤250''을 설립하고 예산과 권한을 집중함으로써 기념행사의 사유화가 진행된 결과로, 다문화·소수자 내용이 축소되고 애국주의 중심 행사로 전환됐다. 불꽃놀이는 트럼프 대통령의 연설이 끝난 후 자정에야 시작되었으며, 그는 연설에서 진보주의자를 ''공산주의''로 낙인찍고 부정선거 음모론을 퍼뜨리며 정치적 분열을 부추겼다. 이에 따라 백인우월주의 단체가 남부 연합기 행진을 벌이며 반발했고, 여론조사에 따르면 5명 중 1명은 행사 참여 의지가 없으며, 5명 중 2명은 미국이 극단적 갈등으로 인해 250년 더 버티기 어렵다고 전망했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:36'::timestamp,'2026-07-27 16:35:40.462992'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1462,3181,'2024년 7월 4일 베네수엘라 라과이라주에서 발생한 강진으로 사망자가 2954명에 달하며, 실종자 생존 가능성 감소로 인해 구조 작업이 종료되고 시신 수습 단계로 전환됐다. 이번 지진은 800여채의 건물 피해와 1만6309명의 이재민을 발생시켰으며, 유엔은 실종자 수를 최대 5만명으로 추산했다. 현재 시신 수습은 중장비 부족으로 지연되고 있으며, 임시 영안실 외에 수백구의 시신이 야외에 방치되며 부패가 급속히 진행되고 있다. 베네수엘라 임시 대통령 델시 로드리게스는 모든 희생자 신원을 개별 확인하겠다고 밝혔으나, 정부의 재난 대응 능력 약화와 구호물품 반입 차단 논란이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:42'::timestamp,'2026-07-27 16:35:21.628775'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1463,3183,'이란의 전 최고지도자 아야톨라 세예드 알리 하메네이의 장례식이 4일 테헤란의 이맘호메이니 대모살라 광장에서 시작됐다. 하메네이는 2월28일 이스라엘의 공습으로 사망했으며, 이란은 전쟁 상황으로 인해 장례식을 연기했고, 미국과의 휴전 합의 이후 126일 만에 장례를 치르게 됐다. 장례식에는 100여 개국 대표를 포함해 최대 1000만 명이 참석할 것으로 예상되며, 조문객들은 미국에 대한 복수를 외치며 붉은 깃발을 들었다. 장례는 9일까지 이어지며, 시신은 이라크의 나자프와 카르발라를 거쳐 이란 마슈하드의 이맘 레자 성묘에 안장될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:46'::timestamp,'2026-07-27 16:26:09.780802'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1464,3184,'미국은 7월4일 독립기념일을 맞아 노스캐롤라이나주 메도라에서 대규모 기념행사와 불꽃놀이를 개최하며, 트럼프 대통령이 장시간 연설을 예고했다. 이란은 3일(현지시간) 아야톨라 알리 하메네이 전 최고지도자의 장례식을 시작으로 7월4일부터 9일까지 이란과 이라크의 주요 도시를 순회하며 역사상 가장 큰 규모의 정치·종교 행사로 진행하고 있다. 이란은 장례식 기간 중 미국과 이스라엘의 공격을 경계하며 IRGC가 강력한 대응을 준비 중이라고 밝혔고, 트럼프 대통령은 이란 공습과 중동 휴전을 외교 성과로 강조할 가능성이 있다. 미국의 불꽃놀이 행사는 85만발을 목표로 기네스 기록 도전을 추진하며, 이는 11월 중간선거를 앞둔 지지율 반등 전략의 일환으로 분석된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:54:53'::timestamp,'2026-07-27 16:24:50.312411'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1465,3187,'이란의 전 최고지도자 아야톨라 알리 하메네이가 2월28일 이스라엘의 공습으로 사망한 후, 3일(현지시간) 테헤란의 이맘 호메이니 그랜드 모살라에 관이 안치되며 장례 절차가 사실상 시작됐다. 하메네이는 약 40년간 이란을 이끌었던 신정체제의 상징이었으며, 전쟁 상황 속에서 장례가 몇 달간 연기됐다. 공식 장례식은 4일부터 시작되며, 시신은 이라크의 성지 나자프와 카르발라를 거쳐 9일 마슈하드의 이맘 레자 성묘에 최종 안장될 예정이며, 테헤란에서만 1800만∼2000만 명이 참여할 것으로 예상된다. 현재 이란 정부는 장례를 통해 전쟁 후 흔들린 체제의 결속력을 시험하고, 대중 지지를 재확인하는 정치적 목적을 갖고 있으며, 아야톨라 모즈타바 하메네이(현 최고지도자)의 공개 출현 여부는 불확실하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:00'::timestamp,'2026-07-27 16:24:07.761296'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1466,3188,'정이한 전 개혁신당 부산시장 후보가 2022년 4월 27일 선거운동 중 음료 테러를 당했다고 주장했으나, 경찰은 이 사건이 자작극일 가능성이 높다고 보고 위계공무집행방해와 공직선거법 위반 혐의로 정 전 후보와 음료를 던진 A씨에 대해 구속영장을 청구했다. 사건 당시 정 전 후보는 유세 중 차량에서 던진 음료를 피하다 화단에 머리를 부딪혀 뇌진탕 진단을 받았다고 주장했으나, 경찰은 A씨가 정 후보의 헬스 트레이너로 사건 전 연락한 정황과 공모 가능성을 수사 중이다. 검찰은 4월 3일 부산지법에 구속영장을 신청했으며, 정 전 후보와 A씨는 8일 구속 전 피의자 심문을 받을 예정이다. 현재 정 전 후보는 선거에서 2만7418표(득표율 1.56%)를 얻어 3위에 머물렀으며, 선거운동 동원 및 여론조사기관의 공정성에 대한 추가 수사도 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:06'::timestamp,'2026-07-27 17:43:59.996976'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1467,3190,'김민석 전 국무총리가 12·3 비상계엄 당시 국회 계엄 해제 표결에 불참한 점을 두고 친청계의 비판에 대해 ''대장동 때 보는 것 같다''며 반박하며 계파 간 갈등이 격화됐다. 친청계 이성윤 최고위원은 김 전 총리가 감기약을 복용했다는 해명을 두고 ''약 성분이 무엇인지''라고 물으며 의심을 제기했고, 이에 김 전 총리는 허위사실에 의한 명예훼손이라고 반박했다. 사법정의 바로세우기 시민행동(사세행)은 이성윤 최고위원을 정통망법상 허위사실적시 명예훼손 혐의로 서울경찰청에 8일 고발했으며, 이는 전당대회를 앞두고 정치적 공방으로 확대되고 있다. 현재 이성윤 최고위원에 대한 고발이 접수된 상태이며, 향후 법적 절차와 당내 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:11'::timestamp,'2026-07-27 17:32:34.220038'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1468,3191,'국회는 7일 정보통신망법 개정안인 ''가짜뉴스법''을 시행했다. 이 법은 전년 말 기준 하루 평균 이용자가 100만명 이상인 대규모 플랫폼 사업자와 10만명 이상 구독자 또는 월평균 조회수 10만회 이상 유튜버를 대상으로 하며, 허위·조작정보에 대해 신고·처리 체계를 구축하고 자율 규제를 이행하도록 했다. 불법정보로 정의된 내용은 인종·성별·장애 등에 대한 차별이나 증오를 조장하는 정보이며, 법원에서 확정된 정보를 반복 유통한 게재자는 최대 10억원의 과징금을 부과받는다. 그러나 야당은 법이 ''입틀막법''이라며 헌법소원을 예고했고, 국민의힘은 국가가 사실과 혐오를 정의하는 권한을 행사하는 것이 문제라고 지적하며 공론장의 침묵과 검열 위험을 우려했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:17'::timestamp,'2026-07-27 17:32:21.421948'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1469,3195,'2026 환태평양훈련(RIMPAC)에 참가한 한국 해군은 아시아 국가 최초로 연합해군구성부대사령관(CFMCC) 임무를 수행하며 다국적 해상작전을 직접 지휘했다. 이는 정조대왕함과 도산안창호함, P-8A 포세이돈 해상초계기 등 최신 장비를 투입해 실전과 유사한 전투훈련을 진행한 결과로, 해군의 전술적 위상 제고와 국제적 신뢰도 향상에 기여했다. 훈련 기간 동안 정조대왕함은 전투지휘실에서 방공전 훈련을, 도산안창호함은 잠수함발사탄도미사일(SLBM) 수직발사관 6기와 중어뢰 ''범상어'' 발사관을 보유한 전략무기 운용 능력을 공개했다. 이후 한국 해군은 훈련 성과를 바탕으로 향후 국제 해상안보 협력 강화와 다국적 해군 작전 지휘 역량 확대를 위한 정책적 논의를 예정하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:24'::timestamp,'2026-07-27 17:03:03.886398'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1470,3196,'더불어민주당은 2024년 8월 17일 치러지는 차기 당대표 선거에서 처음으로 ''1인 1표'' 방식을 도입하며, 당원 중심의 선거 문화로 전환했다. 이는 과거 의원 중심의 대규모 캠프 구성과 공개 지지 전략에서 벗어나, 권리당원과 청년층을 대상으로 소셜미디어를 활용한 온라인 소통에 집중하는 전략으로 변화한 것이다. 지난해 전당대회에서 의원의 공개 지지가 오히려 권리당원의 반감을 불러일으키며 정청래 전 대표가 압승한 사례를 계기로, 당내에서는 의원 중심의 선거 전략이 더 이상 효과적이지 않다는 인식이 확산되고 있다. 현재 김민석 전 국무총리, 정청래 전 대표 등 주요 후보들은 별도 캠프를 구성하지 않고, 당원과의 직접 소통을 강화하며 검찰개혁 등 당원 선호 정책을 중심으로 메시지를 전달하고 있으며, 이로 인해 당내 경쟁이 강성 당원 중심으로 치우칠 수 있다는 우려도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:30'::timestamp,'2026-07-27 17:02:56.768052'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1471,3197,'청와대는 6일 광주 군공항 부지를 호남권 반도체 클러스터 사업지로 선정한 배경으로 삼성전자와 SK하이닉스 등 반도체 기업의 적합성 의견을 제시했다. 이 부지는 약 250만평 규모로, 국유지이며 평탄화 작업과 기반시설이 이미 완료되어 있어 부지 공사 기간을 최소화할 수 있고, KTX역 인접 및 물류 접근성 우수로 인프라와 정주 여건 측면에서 유리하다. 정부는 토지 수용 및 보상 절차의 리스크가 낮고, 부동산 가격 상승 조짐을 막기 위해 빠른 부지 확정이 필요하다고 판단했으며, 군공항 이전은 안보 공백 없이 조기에 진행될 예정이다. 국방부는 이전 구체 방안은 아직 결정되지 않았으나, 공군과 협의를 통해 국가정책에 부응할 계획이며, 다음 회의에서는 영남권과 충청권 투자도 점검할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:35'::timestamp,'2026-07-27 16:54:28.611898'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1472,3198,'홈플러스는 2023년 6월 29일 제출한 수정 회생 계획안에서 전자단기사채(ABSTB) 총 4811억원을 카드채권으로 분류하고, 이 중 개인 투자자 자금은 2033년부터 2037년까지 5년에 걸쳐 무이자 분할 상환하는 방안을 마련했다. 이 계획은 메리츠금융그룹의 1조2397억원 채권을 올해와 내년에 대부분 상환하는 것과 대비해 개인 투자자 채권의 변제 시기를 10년 이상 연기한 것으로, 지난 1월 계획안에서 예정된 2026~2027년 전액 현금 변제보다 약 9년 이상 지연된 것이다. 회생 계획안은 서울회생법원이 3일 회생 중단 결정을 내리면서 실행력이 상실되었으나, 홈플러스가 20일까지 2000억원 추가 자금을 확보하면 계획대로 변제가 이뤄질 가능성이 있다. 반면 파산 절차로 넘어가면 개인 투자자는 담보 없는 일반 파산채권자로 분류되며, 채권 성격을 재논의해야 하는 복잡한 법적 절차를 거쳐야 하여 상환 가능성은 낮아질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:43'::timestamp,'2026-07-27 17:46:20.311742'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1473,3266,'2026년 7월 7일, 국민의힘은 6·3 지방선거 투표용지 부족사태 진상규명을 위해 야당 추천 특검을 도입해야 한다고 주장하며 더불어민주당에 조건 없이 수용할 것을 촉구했다. 이는 선관위의 무능과 부실, 그리고 여당 추천 특검에 대한 공정성에 대한 의심이 지속되면서 발생한 정치적 갈등의 일환으로, 특히 위철환 선관위 상임위원이 이재명 대통령과 연수원 동기이자 대한변협 회장 출신이라는 점이 문제시됐다. 국민의힘은 제3자 추천 방식도 대한변협 등을 염두에 둔 경우 공정성에 의문을 제기하며, 특위 내부 고발자 보호를 위한 면책안과 익명성 보장, 불처벌 원칙을 정부에 촉구했다. 현재 민주당은 제3자 추천 특검을 제안했으나, 국민의힘은 이를 거부하며 특검 추천 방식에 대한 논의가 지속될 전망이며, 이는 선거관리 개혁과 정치적 신뢰 회복의 핵심 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:49'::timestamp,'2026-07-27 18:28:24.721073'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1474,3204,'코스피 시장이 삼성전자와 하이닉스의 급락으로 인해 7일 오전 10시 23분 41초에 매도 사이드카가 발동됐다. 이는 지난 2일 이후 3거래일 만의 발동으로, 코스피200 선물 가격이 전일 종가 대비 5% 이상 하락하며 1분간 지속된 것이 원인이다. 매도 사이드카 발동 당시 코스피 지수는 전일 대비 4.7% 하락한 7600선까지 후퇴했고, 삼성전자와 SK하이닉스는 각각 6.53%, 5.46% 하락하며 29만원대, 220만원대를 기록했다. 이후 거래소는 프로그램 매도 호가를 5분간 정지하고, 시장 안정화를 위한 추가 조치가 예정되어 있으며, 향후 시장 동향과 기업 실적 발표에 따른 투자자 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:55:54'::timestamp,'2026-07-27 17:30:00.098283'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1475,3206,'삼성전자는 2024년 2분기 연결 기준 영업이익 89조4000억원을 기록하며 지난해 동기 대비 1810.3% 증가했다. 이는 반도체 슈퍼사이클과 글로벌 인공지능(AI) 인프라 투자 확대에 따른 메모리 수요 증가, 삼성의 세계 최대 메모리 생산능력(CAPA) 및 HBM4 양산 등 기술 경쟁력 회복이 주요 원인이다. 매출은 171조원으로 전년 동기 대비 129.3% 증가했으며, 영업이익은 지난해 전체 실적(43조6011억원)의 2배를 초과 달성했다. 반도체 부문(DS)이 전사 실적의 대부분을 차지한 반면, 완제품 사업(DX)은 원가 부담으로 수익성 압박을 겪으며 상대적으로 부진한 실적을 보였으며, 내년까지 반도체 수요 증가 전망이 지속될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:00'::timestamp,'2026-07-27 17:25:12.184900'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1476,3217,'정이한 전 개혁신당 부산시장 후보와 헬스 트레이너 A씨가 2024년 4월 27일 부산 금정구 구서나들목에서 음료 투척 사건을 사전에 공모한 자작극 혐의로 경찰이 구속영장을 신청했다. 당시 정 전 후보는 유세 중 A씨에게 음료를 던지며 넘어져 뇌진탕과 근좌상 진단을 받았다고 주장했으나, 경찰은 두 사람의 사전 통화 기록과 친분 관계를 확보해 공모 가능성을 수사해왔다. 검찰은 6월 3일 부산지법에 구속영장을 청구했으며, 영장실질심사는 6월 8일 오후 2시에 열릴 예정이다. 경찰은 증거인멸과 도주 우려를 이유로 구속을 요청했고, 온병원의 진단서 발급 과정과 바로미터여론연구소 관련 의혹도 별도로 수사 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:05'::timestamp,'2026-07-27 17:41:53.281796'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1477,3218,'미국 해군 원자력 추진 항공모함 시어도어 루스벨트함(CVN-71)이 2024년 6월 6일(현지시간) 하와이 진주만 히캄 합동기지에 정박하며, 31개국 함정 중에서도 압도적인 존재감을 보였다. 이 함정은 길이 333m, 폭 77m의 비행갑판과 10만t의 규모를 지닌 바다 위 전략기지로, F/A-18, F-35C 등 70여 대의 함재기와 수천 명의 승조원을 수용하며 항공전, 상륙작전, 재난 구호 등 다양한 임무를 수행할 수 있다. 루스벨트함은 림팩 훈련에서 한국 해군이 처음으로 연합해군구성군사령관(CFMCC)을 맡아 다국적 해상 전력의 통합 지휘 능력을 시험했으며, 항모 중심의 유·무인체계와 정보 자산의 통합 운용이 미래 해전의 핵심으로 부상하고 있다. 앞으로도 항공모함의 역할은 단순한 비행장에서 벗어나 전장 지휘 거점으로 진화할 전망이며, 한국 해군도 이에 맞춰 전력 체계를 개편하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:13'::timestamp,'2026-07-27 17:41:23.263505'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1478,3223,'중국은 2024년 9월 6일 오후 12시 1분(현지시간) 해군 전략핵잠수함을 통해 태평양 공해 해역에 잠수함발사탄도미사일(SLBM) ''쥐랑-3(JL-3)''을 성공적으로 발사했다. 이는 2022년 9월 태평양을 향한 대륙간탄도미사일(ICBM) ''둥펑-31 AG'' 시험 발사 이후 약 2년 만의 태평양 방향 군사 시험으로, 중국은 이 발사를 정례적 연간 군사 훈련의 일환으로 설명하며 유관국에 사전 통보했다고 밝혔다. 발사된 미사일은 사거리가 8000km를 초과할 가능성이 크며, 중국은 ICBM과 SLBM, 전략폭격기로 구성된 ''삼위일체'' 핵전력 체계의 억지력을 강화했다고 평가했다. 일본·호주·뉴질랜드는 투명성 부족과 지역 안정 침해를 우려하며 반응했고, 미국의 전문가들은 중국의 군사 시험 빈도 증가가 핵 억지력에 대한 자신감 강화를 의미한다고 분석했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:20'::timestamp,'2026-07-27 16:54:40.656880'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1479,3225,'도널드 트럼프 미국 대통령은 2023년 7월 4일 워싱턴DC 내셔널몰에서 열릴 예정이었던 건국 250주년 기념행사를 악천후로 인해 취소한 후, 자신의 결정으로 행사 재개를 지시했다. 행사 당일 백인우월주의 단체 ''애국 전선''이 남부연합기와 함께 의회 의사당으로 행진하며 ''미국을 되찾자'' 등의 구호를 외쳤고, 이에 대해 내무장관 더그 버검은 ''표현의 자유''를 강조하며 논란을 일으켰다. 행사 취소 후 약 15만 명이 재입장해 밤 9시 이후 재개되었으며, 대통령 연설은 예정보다 1시간 30분 늦은 밤 11시 15분에 시작됐고, 트럼프는 약 40분간 연설을 마쳤다. 이후 ''애국 전선''의 행진과 관련된 표현의 자유 논란, 정부의 대응 방식, 그리고 극우 단체의 활동에 대한 후속 검토와 제도적 대응 방안이 논의될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:26'::timestamp,'2026-07-27 16:49:20.351752'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1480,3340,'2024년 4월 7일 홍콩 증시는 글로벌 반도체 시장 조정 영향으로 항셍지수와 H주 지수가 각각 0.20%, 0.41% 하락하며 반락 개장했다. 이는 반도체주와 비철금속, 보험, 소비 관련주 등이 약세를 보이며 투자심리가 악화된 데서 비롯되었으며, 특히 창페이, 란치과기, 콰이서우, 신이광넝 등 주요 종목이 급락했다. 오전 10시59분 기준 항셍지수는 2만3549.96(-0.28%), H주 지수는 7785.87(-0.34%)를 기록하며 하락세 지속 중이다. 반면 인공지능(AI) 및 전기차, 전자상거래, 은행주 등은 상승세를 보이며 시장 분위기의 양극화가 지속되고 있으며, 향후 글로벌 반도체 수요 회복 여부와 중국 경제 정책 동향이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:32'::timestamp,'2026-07-27 18:35:44.416974'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1481,3341,'중국은 6일 태평양 공해상으로 잠수함발사탄도미사일(SLBM)을 시험 발사하며, 이 미사일이 전략 핵무기인 ''쥐랑(JL)-3''일 가능성이 높다고 전망했다. 중국 관영매체 글로벌타임스는 이번 발사가 미국 본토를 타격할 수 있는 장거리 능력을 보유한 SLBM 시험으로, 중국의 전략 핵 역량 강화가 지역 평화를 보장하는 데 기여한다고 주장했다. 발사 전 주변국에 사전 통보한 점을 강조하며, 오판 위험을 줄이기 위한 선의의 조치라고 설명했고, 전문가들은 사거리가 8000km를 초과해 대륙간탄도미사일 수준일 것으로 분석했다. 이번 시험은 094형 또는 개량형 핵잠수함에서 발사된 것으로 추정되며, 중국의 해상 기반 핵전력이 서태평양 어디서든 안정적인 전략적 반격을 수행할 수 있음을 입증한 것으로 평가받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:39'::timestamp,'2026-07-27 18:35:09.233178'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1482,3228,'제10대 대구 동구의회는 7일 제353회 임시회에서 상임위원장을 선출하며 전반기 원구성을 완료했다. 전날 열린 제1차 본회의에서 국민의힘 이연미 의원이 의장, 더불어민주당 안평훈 의원이 부의장으로 선출되었으며, 의회운영위원장 유병진, 기획행정위원장 노남옥, 경제복지위원장 김은옥, 도시건설위원장 김동규 의원이 상임위원장으로 각각 선출되었다. 이연미 의장은 의회운영의 책임감을 강조하며 소통과 협치를 기반으로 현장 중심의 의정 활동을 펼칠 계획이라고 밝혔다. 이후 2년간 지역 현안 해결과 주민 복리 증진을 위한 의정 활동이 예정되어 있으며, 의장단과 상임위원회의 운영 방향에 대한 주민 반응과 정책 효과가 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:43'::timestamp,'2026-07-27 18:59:34.115493'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1483,3231,'2026년 7월 7일, 나경원 국민의힘 의원은 조국 전 조국혁신당 대표가 아이돌 그룹 리센느 원의 ''노'' 발언을 고(故) 노무현 전 대통령 조롱으로 규정한 것에 대해 ''입틀막''이라며 비판했다. 이는 사투리 사용까지 제한되는 언어 표현의 위축을 초래하고 있으며, 스타벅스 ''탱크데이'' 마케팅 논란과 배재고 야구부 혐오 표현 출전 정지 사건도 정치적 프레임에 의해 과도하게 다뤄지고 있다고 지적했다. 나 의원은 민주당이 특정 표현에만 반응하고 진보 유튜버 최욱의 ''탱크 발언''에는 침묵하는 이중 잣대를 문제 삼으며, 이는 표현의 자유를 심각하게 위협하는 결과를 초래할 수 있다고 경고했다. 현재 이 논란은 정치적 이념에 따른 표현 규제의 기준 불일치에 대한 사회적 논의로 확산되고 있으며, 향후 표현의 자유와 사회적 책임의 경계에 대한 정책적 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:49'::timestamp,'2026-07-27 18:58:51.718446'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1484,3244,'청와대는 2026년 5월 고위당정협의회에서 합의한 미래대응기금을 특별법 형태로 신설할 계획이며, 8월 말 정부 예산안 편성 시점에 구체적 내용을 반영할 예정이다. 이 기금은 반도체 슈퍼사이클로 인한 추가세수를 3대 메가프로젝트, 청년 지원, 양극화 완화 등에 투입하기 위해 마련되었으며, 지난 3월 추가경정예산안(26조2000억원)을 편성한 바 있다. 정부는 9월에 공식적으로 추가세수 전망을 발표할 예정이며, 올해 추경 때보다 더 많은 세수가 예상되며 내년과 내후년에도 상당 규모의 추가세수가 예상된다. 이후 국가재정전략회의를 통해 국회와의 협의를 진행하고, 학계·언론·공적 기구와의 소통을 통해 공감대 형성을 목표로 하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:56:54'::timestamp,'2026-07-27 18:49:31.395559'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1485,3247,'2026년 7월 7일, 제310회 고성군의회 제1차 본회의에서 제10대 고성군의회 전반기 의장으로 정영환 의원(국민의힘·나선거구), 부의장으로 우정욱 의원(국민의힘·다선거구)이 만장일치로 선출됐다. 이번 선거는 기존의 ''교황식'' 방식에서 ''후보 등록제''로 변경된 첫 번째 시행으로, 재적의원 11명 중 출석의원 11명 전원이 표를 행사해 각각 만장일치로 당선됐다. 정영환 의장은 군민의 기대에 부응하는 신뢰받는 의회를 만들겠다며 책임감을 강조했고, 우정욱 부의장은 동료 의원과의 협력을 통해 의회의 역량을 결집하겠다고 밝혔다. 다음 날인 8일에는 의회운영위원장, 기획행정위원장, 산업경제위원장 등 3개 상임위원장 선거가 예정되어 있으며, 이는 의회 운영의 정상화를 위한 후속 절차로 진행될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:00'::timestamp,'2026-07-27 18:44:14.792864'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1486,3251,'국민의힘은 2026년 8월 전당대회에서 청년최고위원제를 도입하기로 결정했다. 이는 당 내 젊은 세대의 참여를 확대하고, 정당의 청년층 수용력을 높이기 위한 개혁적 조치로, 당 내부의 세대 간 불균형 문제를 해소하려는 목적을 지닌다. 청년최고위원제는 30세 미만의 당원 중에서 선출되며, 당 최고위원회의에 상정된 제도로, 2026년 8월 전당대회에서 공식 시행될 예정이다. 이후 당은 청년 최고위원의 역할과 권한, 운영 방식에 대한 구체적인 규정 마련을 위한 논의를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:09'::timestamp,'2026-07-27 18:39:50.790297'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1487,3252,'2026년 6월 29일부터 7월 3일까지 국회에 교육교부금법 개정안 3건이 연달아 발의됐다. 조은희 국민의힘 의원안은 내국세 연동 방식을 폐지하고 경제성장률, 물가상승률, 학령인구 변화를 반영한 산식을 도입하며, 교부금이 전년도의 95% 미만으로 줄어들 경우 최소 95%를 보장하는 안정장치를 마련했다. 이헌승 의원안은 고정된 20.79% 교부율을 대통령령으로 조정 가능하게 하여 교육재정 수요에 유연하게 대응하되, 교육청의 재원 예측 불확실성이 증가할 수 있다는 우려가 제기됐다. 강경숙 조국혁신당 의원안은 교육청의 재정운용 노력 평가를 교부금 배분 기준에 반영해 교육청의 책임성을 강화하는 방식으로, 교부금 총량을 줄이기보다는 배분 효율성을 높이는 데 초점을 맞췄다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:19'::timestamp,'2026-07-27 18:38:53.103074'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1488,3256,'2026년 7월 7일, 더불어민주당 전당대회 본격화와 함께 친정청래계 인사들이 김민석 전 국무총리의 지방선거 공천 및 결과에 대한 책임을 문제 삼으며 공세를 가했다. 친청계 최민희 의원은 울산시장 승리와 평택 재보궐 패배의 결과를 비교하며 공천 실패의 책임을 회피하지 말 것을 촉구했고, 이성윤 최고위원은 김 전 총리가 계엄 해제 국회 표결에 불참한 점을 거론하며 ''감기약 성분''이라는 비유를 사용해 비판했다. 김 전 총리는 KBS 인터뷰에서 이 발언을 허위사실 명예훼손으로 반박하며, 해명된 사실을 다시 거론하는 것은 당을 위한 문제 제기라기보다는 정치적 공세라고 지적했다. 8일 송영길 의원의 출마 선언이 예정되었으며, 정청래 전 대표도 이번 주 후반 출마 가능성이 제기되며 당권 경쟁과 주자 간 대립이 심화되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:25'::timestamp,'2026-07-27 18:35:31.975562'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1489,3272,'2026년 7월 7일, 한병도 더불어민주당 대표 직무대행은 국회 원내대책회의에서 6·3 지방선거에서 올림픽공원 핸드볼 경기장에 보관된 247만 장의 투표용지에 대해 재검표와 수개표를 여야 협의를 통해 국정조사 특별위원회(국조특위)에서 추진하는 방안을 적극 검토하겠다고 밝혔다. 이는 선거관리위원회의 투표지 인쇄 물량 축소 과정, 의사결정 체계 및 당일 지휘 체계에 대한 의문이 제기되며, 국민의 참정권 침해 우려가 커진 데 따른 것이다. 국조특위는 이날 중앙선관위와 서울시선관위를 대상으로 2차 현장조사를 진행하며, 사태의 실체와 책임 소재를 규명하는 데 집중하고 있다. 민주당은 특검법을 야당 단독 추천이 아닌 제3자 추천 방식으로 추진하되, 국민의힘은 정치적 유불리를 고려해 단독 추천을 고집하고 있어 협의가 지연될 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:31'::timestamp,'2026-07-27 18:25:25.867269'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1490,3274,'제12대 경기도의회 전반기 의장으로 더불어민주당 4선 남종섭(용인3) 의원이 2026년 7월 7일 제392회 임시회 제1차 본회의에서 단독 출마해 167명 재적의원 중 165표를 득표해 당선됐다. 의장 선거는 재적의원 과반수 출석과 출석의원 과반수 득표 기준에 따라 진행되었으며, 남 의원은 최다선 연장자로서 이전까지 의장 직무대행을 맡아 왔다. 당선 후 남 의원은 ''167명 의원 모두의 의장''이 되겠다며 협치와 소수당 존중, 현장 목소리 정책화를 강조하며 책임감 있는 리더십을 약속했다. 이후 의장 임기는 2026년 7월 7일부터 2027년 6월 30일까지이며, 후속으로 제12대 경기도의회 후반기 의장 선거가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:36'::timestamp,'2026-07-27 18:24:29.656759'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1491,3275,'한정애 더불어민주당 정책위의장은 7일 삼성전자와 SK하이닉스 단일종목 레버리지 ETF의 과도한 자금 집중으로 시장 변동성이 확대되고 있다며 제도 보완 필요성을 제기했다. 이는 2024년 5월 기준 국내 주식형 ETF 중 삼성전자·SK하이닉스 편입 ETF 시가총액 비중이 73%에 달하고, 코스피 시총 절반 이상을 차지하는 두 종목의 주가 널뛰기로 VKOSPI 지수가 2008년 금융위기 이후 최고치를 기록한 데서 비롯된 우려다. 한국은행도 단일종목 레버리지 ETF가 시장 쏠림을 심화시켜 개인 투자자 손실 확대 가능성을 경고한 바 있으며, 민주당은 불완전 판매 예방 및 취약계층 보호 장치의 실효성 검토를 추진 중이다. 이후 정부와 민주당은 메가 프로젝트를 위한 인프라 조성과 기업 지원 체계 강화를 통해 시장 안정과 국가 균형 발전을 도모할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:42'::timestamp,'2026-07-27 18:24:15.346123'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1492,3279,'2026년 7월 7일 김민석 전 국무총리는 서울 여의도 국회에서 ''3대 메가프로젝트와 지방주도성장''을 주제로 한 토론회를 개최하며, 이재명정부의 메가프로젝트 성공 지원을 핵심 과제로 내세웠다. 이어 8일 정청래 전 대표는 같은 장소에서 ''서남권 반도체 클러스터 성공을 위한 정책토론회''를 공동 주최하며, 전남광주특별시장의 군공항 부지 활용 발표를 근거로 메가특구 입법 지원을 약속했다. 두 토론회는 모두 더불어민주당 내에서 메가프로젝트 관련 의제를 선점하려는 주자 간 경쟁의 일환으로, 당내 혁신 연속토론회 체계를 통해 지방주도성장과 산업 정책을 중심으로 논의가 진행되고 있다. 이후 당내에서는 특정 인물이 메가프로젝트를 독점하려는 것인지, 정책 논의의 공정성과 당의 통합 방향성에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:48'::timestamp,'2026-07-27 18:21:36.639097'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1493,3906,'김민석 전 국무총리는 2024년 12·3 비상계엄 당시 국회의 계엄 해제 표결에 불참한 점을 두고 친청계의 비판에 대해 ''대장동 때를 보는 듯하다''며 역공했다. 그는 표결 당시 국회에 있었으며, 감기약을 복용해 잠을 잔 것이라고 해명했으나, 이성윤 의원은 약 성분과 자는 척하는 행위를 문제 삼으며 명예훼손을 주장했다. 김 전 총리는 이에 대해 허위사실에 기반한 비판이라고 반박하며, 당 내부의 멸칭과 가짜뉴스 유포 문제를 지적하고 혁신 필요성을 강조했다. 그는 이병태 전 부위원장의 사퇴를 불가피하다고 평가하며 ''5·18 헌법 전문 수록''과 ''선거관리위원회 개혁''을 투포인트 개헌안으로 제안했고, 이재명 정부의 통합 인사 기조에 대해 엄격한 검증의 필요성을 언급했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:54'::timestamp,'2026-07-27 18:08:07.143715'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1494,3287,'한병도 더불어민주당 대표 직무대행은 6일 국회에서 열린 원내대책회의에서 형사소송법 개정 TF를 중심으로 보완수사권 완전 폐지를 위한 법안 마련을 추진하겠다고 밝혔다. 이는 민주당의 확고한 원칙으로, 당내 이견이 없으며, 제헌절이나 전당대회와 같은 특정 시기를 고려하지 않고 신속한 처리를 목표로 하고 있다. 개정안은 오는 10월 공소청과 중대범죄수사청(중수청) 출범에 차질이 없도록 빠른 시일 내 통과를 추진하며, 현재는 법사위와 행정안전위 간사 등이 참여하는 TF가 주도하고 있다. 다만 일부에서는 경찰의 부실 수사 우려를 고려해 예외적·제한적인 보완수사권 유지 필요성에 대한 반론도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:57:59'::timestamp,'2026-07-27 18:14:14.622454'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1495,3288,'2026년 7월 7일 기준, 전국 17개 시·도교육청이 모두 재정 적자를 기록한 가운데, 학생 대상 현금·현물성 지원 예산은 2021년 2846억원에서 2026년 7658억원으로 5년 만에 2.7배 증가했다. 이는 같은 기간 학생 수가 32만여 명 감소한 상황에서 발생한 것으로, 교육청의 총 적자 규모는 2024년에 8조7840억원에 달했다. 현금·현물 지원 사업은 보편적·일회성 성격이 강해 재정 경직성 심화 우려가 제기되었으며, 광주교육청의 학생교육비 꿈드리미(472억원), 경기도교육청의 운전면허 취득비 지원(252억원) 등이 대표 사례로 지적됐다. 이종욱 국회의원은 모든 학생에 대한 일률적 지원의 집행 적정성과 정책 효과를 철저히 검증해야 한다고 강조하며, 취약계층 지원과 교육격차 해소를 위한 투자는 유지하되, 재정 효율성 확보가 필요하다고 주장했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:05'::timestamp,'2026-07-27 18:12:19.809966'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1496,3289,'서영교 민주당 법제사법위원장은 2026년 7월 7일 KBS 라디오에 출연해 형사소송법 개정안 처리 시점과 관련해 전당대회(2026년 8월 17일) 이후로 미루기 어렵다고 전망했다. 그는 중대범죄수사청과 공소청이 2026년 10월 2일 출범함에 따라, 이로부터 6개월 전인 4월 말까지 형소법 개정이 완료돼야 한다고 강조하며 현재 남은 기간은 약 2개월 반임을 지적했다. 서 의원은 의견 수렴과 조율을 통해 민생 입법 및 타 상임위 법안과 병행해 빠르게 처리할 계획이라고 밝히며, 수사심의위원회 실질화와 인권보호국 설치 등을 검찰 수사권 폐지 후 경찰 견제 방안으로 제시했다. 이후 수사심의위에 과감한 인력 교체 권한 부여 등 구체적 제도적 방안 마련이 필요하다는 점을 강조하며, 입법 절차의 신속성과 실질적 운영 가능성에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:11'::timestamp,'2026-07-27 18:08:22.757704'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1497,3290,'2026년 8월 17일 예정된 더불어민주당 당대표 선거에 출마한 김민석 전 국무총리가 7일 당원 직선 방식으로 청년 최고위원을 선출할 것을 제안했다. 이는 당원 주권 확대와 청년 세대의 당 내 참여를 강화하기 위한 것으로, 최근 20·30대 당원 지지율 저하라는 문제 인식이 제기된 배경에서 나온 것이다. 민주당 전국당원대회 준비위원회는 이미 청년 최고위원 별도 선출안을 분과 회의에서 검토한 바 있으며, 이 제안은 당 내 젊은 세대의 목소리 반영을 위한 구체적 방안으로 논의되고 있다. 이후 당내 논의와 절차를 거쳐 청년 최고위원 선출 방식의 정착 여부가 결정될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:15'::timestamp,'2026-07-27 18:07:23.893674'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1498,3291,'2026년 7월 7일, 김민석 전 국무총리는 KBS 라디오에 출연해 더불어민주당이 추진 중인 검찰의 보완수사권 폐지에 대해 ''수사와 기소의 분리 원칙에 입각해 폐지하는 방향으로 정리하는 것이 불가피하다''고 밝혔다. 그는 대통령의 공개적 우려와 정부 내에서의 숙의 과정을 언급하며, 보완수사권 폐지와 관련한 다양한 보완책이 이미 정부 내 토론회 등을 통해 제기된 바 있다고 설명했다. 김 전 총리는 5월 당에 보완수사권 폐지 입장을 전달한 바 있으며, 이는 당 내 지도부에까지 전달된 것으로 보인다. 이에 대해 친청계 이성윤 최고위원이 김 전 총리의 계엄 해제 표결 불참과 관련해 허위사실을 주장한 것에 대해 ''명예훼손''이라며 우려를 표하며, 당 내 분열을 해소할 책임이 지도부에 있다고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:22'::timestamp,'2026-07-27 18:06:36.163248'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1499,4322,'국민의힘 중앙윤리위원회는 6일 무소속 한동훈 의원을 재보선에서 지지한 당원들을 징계 심의 대상으로 결정했다. 이는 당내 공천과 무관하게 무소속 후보를 지지한 행위가 당헌·당규에 위반된다는 판단에서 비롯되었으며, 특히 장동혁 대표 사퇴를 요구한 ''대안과 미래'' 소속 의원들도 포함된다. 징계 대상으로 지목된 최형두 의원과 한동훈 의원은 당원들의 지지가 당선에 기여했다며 반발했고, 장동혁 대표는 해당행위에 대해 복당을 영구 금지해야 한다고 주장했다. 현재 징계 절차가 진행 중이며, 지도부 내부에서도 징계의 적절성과 사법적 판단으로 이어질 수 있다는 우려가 제기되고 있어 향후 당내 분열 가능성과 징계 기준의 명확성에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:26'::timestamp,'2026-07-27 17:02:02.734273'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1500,3294,'중앙선거관리위원회는 6·3 지방선거 투표용지 부족 사태와 관련해 올림픽공원 핸드볼경기장 내 보관 중인 투표용지 247만표에 대한 재검표를 국정조사특별위원회의 의결을 거쳐 추진할 방침을 밝혔다. 이는 현행 법규상 선관위가 자체적으로 재검표를 할 수 있는 법적 근거가 없어, 국조특위의 결의가 필요하다는 점에서 비롯된 것으로, 국민참정권 침해 논란을 해소하고 신뢰 회복을 목표로 하고 있다. 재검표는 육안 확인, 정당별 분류, 심사계수기 매수 확인 등을 거쳐 440명 인력과 5000만원 예산, 9시간이 소요될 것으로 전망되며, 검증 과정은 국조특위 위원, 정당 추천 참관인, 언론 등에게 공개된다. 이후 국조특위가 재검표 방안을 의결하면 선관위가 검증 비용을 부담하고, 투표용지는 과천청사 선거홍보관으로 이송될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:32'::timestamp,'2026-07-27 18:01:40.546631'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1501,3295,'이재명 대통령은 2026년 7월 7일 나토 정상회의 참석을 위해 튀르키예 앙카라로 출국했다. 이 대통령은 7~8일 나토 정상회의에 참석한 뒤 9~11일 몽골을 국빈 방문하며, 나토 주관 방산포럼에서 ''공동의 가치, 더욱 강한 산업 기반''을 주제로 기조발언하고 주요 방산 수요국과 양자회담을 진행할 예정이다. 이번 순방은 이 대통령 취임 후 첫 해외 순방으로, K-방산 수출 확대와 국제평화안보 기여를 위한 전략적 기회로 평가된다. 이후 나토 및 몽골 방문 후속 조치와 외교적 성과에 대한 국내외 반응이 주목되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:37'::timestamp,'2026-07-27 18:01:19.205961'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1502,3296,'이재명 대통령은 2026년 7월 7일 서울공항에서 출국해 튀르키예 앙카라로 향한 닷새 간의 해외순방에 나섰다. 이 대통령은 7~8일 나토 정상회의에 참석해 방산포럼에서 기조발언을 하고, 주요 방산 수요국과 양자회담을 통해 K-방산 수출을 추진한다. 9~11일에는 몽골을 국빈방문하며, 이는 G7 정상회의 이후 세계 평화와 안보 분야에서 한국의 역할을 확대하는 것을 목표로 한다. 이번 순방은 한국의 외교적 위상 제고와 방산 수출 확대를 위한 전략적 행보로, 나토 및 몽골과의 협력 강화가 후속 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:41'::timestamp,'2026-07-27 17:58:00.669429'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1503,3298,'이재명 대통령은 2026년 7월 7일 캐나다의 차기 잠수함 도입 사업에서 우선협상대상자로 독일 기업이 선정된 것에 대해 기대한 결과를 얻지 못했지만, K-방산의 도전은 계속될 것이라고 밝혔다. 캐나다는 NATO 동맹국인 독일 기업의 기술적·안보적 우위와 장기적 군수 협력 관계를 고려해 우선협상대상자를 결정했으며, 이는 1949년부터 이어진 강력한 군사안보 동맹의 영향을 반영한 결과로 분석된다. 이번 사업에서 한국은 기술력과 성능 면에서 독일과 동등하거나 상회한다는 평가를 받았으나, 비용, 군수 상호운용성, 역사적 동맹 관계 등 다각적 요소에서 약세를 보였다. 강훈식 대통령비서실장은 다음 도전에서 성과를 내겠다며 연구개발, 수출 지원, 국제협력 강화를 통해 K-방산의 글로벌 경쟁력을 제고할 계획을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:47'::timestamp,'2026-07-27 17:53:55.031554'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1504,3300,'2026년 7월 6일 캐나다 정부는 차기 잠수함 사업(CPSP)에서 독일 티센크루프 마린 시스템즈(TKMS)를 우선협상대상자로 선정했다. 한국은 캐나다 잠수함 수주 경쟁에서 도산안창호함(SS-Ⅲ)과 대전함 등이 참여한 연합훈련을 통해 기술력과 작전 지속성을 입증했으나, 전략적 여건의 불리함으로 수주 실패를 인정했다. 방위사업청은 결과를 존중하면서도, 기술적 성과와 글로벌 방산시장 진출 가능성을 확인한 점을 긍정적으로 평가하며, 방산 AI 대전환과 현지화 전략을 통해 향후 수출 성과를 높이겠다고 밝혔다. 캐나다 정부는 내년 말까지 TKMS와 협상을 진행하며, 총 12척의 잠수함 중 첫 4척은 2034년 인도 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:58:53'::timestamp,'2026-07-27 17:48:54.162176'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1505,3304,'2026년 7월 7일, 정보통신망 이용촉진 및 정보보호 등에 관한 법률(정통망법) 개정안이 시행되며, 여야는 법안의 목적과 위헌성에 대해 공방을 벌이고 있다. 개정안은 고의로 불법·허위·조작 정보를 유포해 타인에게 손해를 끼친 경우 손해액의 최대 5배까지 가중 배상 책임을 묻고, 법원 판결로 확인된 정보를 반복 유통할 경우 방송미디어통신위원회가 최대 10억원의 과징금을 부과할 수 있도록 했다. 민주당은 법안이 악의적 가짜뉴스와 혐오 표현에만 적용되며, ''악의적 의도'', ''부당 이익'', ''명확한 법익 침해'' 등 세 가지 기준이 모두 충족될 때만 적용된다고 설명하며 ''핀셋 규제''라고 강조했다. 반면 국민의힘은 법의 기준이 모호하고 권력이 허위 정보 여부를 판단할 수 있는 길을 열어 놓았다고 비판하며, 헌법소원 청구와 전면 재개정을 요구하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:01'::timestamp,'2026-07-27 17:42:38.183755'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1506,3772,'2025년 9월, 더불어민주당이 추천한 이창현 전 서울연구원장과 류일형 KBS 이사의 임명이 방송법 결격사유에 위배된다는 논란이 발생했다. 이창현은 이재명 대통령 대선 당시 ''잘사니즘위원회'' 수석부위원장과 국정기획위원회 국가비전TF 자문위원으로 활동한 이력이 있어, 방송법 제46조 제3항에 따라 3년 내에 KBS 이사가 될 수 없으며, 류일형은 3년 임기 1회 연임만 허용된다는 방송법 제47조 제1항에 위배된다는 지적이 제기됐다. 민주당은 논의 과정에서 문제 제기가 있었으며, 추가 논의를 통해 최종 결정을 내리겠다고 밝혔고, 이창현 후보는 자문 활동이 방송·통신·법률·경영과 무관했다고 반박했다. 현재 이사 임명은 법적 해석 차이로 인해 보류 중이며, 향후 국회 추천공직자격심사특별위원회의 추가 검토가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:08'::timestamp,'2026-07-27 17:11:28.824845'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1507,3305,'이재명 대통령은 2026년 7월 7일부터 11일까지 나토 정상회의 참석과 몽골 국빈방문을 위한 4박 5일 간의 해외 순방을 실시했다. 이 대통령은 나토 회원국이 아닌 한국이 인도태평양 핵심 파트너국(IP4)으로 초청받아 7~8일 튀르키예 앙카라에서 열린 2026년 나토 정상회의에 참석하며, 방산포럼에서 기조연설을 하고 일본·호주·뉴질랜드 등 IP4 국가 대표들과 소인수 회담을 진행했다. 이후 9~11일 몽골 울란바타르에서 후렐수흐 몽골 대통령과 정상회담을 갖고 ''한몽관계의 황금시대'' 공동선언을 발표하며 핵심광물 협력과 한반도 평화 정착 방안을 논의했다. 이번 순방은 K-방산 수요국 확대와 인도태평양 지역 협력 강화를 목표로 하며, 나담축제 참석을 마지막으로 일정을 마무리했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:13'::timestamp,'2026-07-27 17:42:11.719200'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1508,3307,'7월7일 화요일, 국회는 정성호 법무부 장관과 한성숙 국무총리를 각각 접견했다. 이날은 제9회 전국동시지방선거 투표용지 부족 사태에 대한 국민참정권 침해 진상 규명 및 선거관리개혁을 위한 국정조사특별위원회가 전체회의를 열었으며, 재정경제기획위원회도 회의를 진행했다. 다양한 의원실은 AI경제, 기후에너지 정책, 양봉산업 위기 대응, 공공비정규직 교섭 실현, 대마 성분 의약품 도입 등 주제로 세미나와 토론회를 개최했고, 콘텐츠산업진흥법 개정안 발의 등 10건 이상의 기자회견이 진행됐다. 이후 국정조사특별위원회는 선거관리개혁 방안 마련을 위한 토론회를 추가로 개최하며, 선거 제도 개선과 관련된 정책 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:19'::timestamp,'2026-07-27 17:43:26.950847'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1509,3308,'7월 7일 화요일, 대통령은 튀르키예에서 열리는 나토 정상회의에 참석했다. 이는 한국이 국제적 안보 협력 강화를 위해 다자간 외교 활동을 지속하고 있음을 보여주는 것으로, 외교부 장관은 튀르키예와 몽골을 방문하며 외교적 활동을 전개했다. 국무회의는 각 부처 장관들이 참석해 정책 방향을 논의했으며, 국민의힘은 미국 독립선언 250주년을 기념하는 세미나와 KTX 경기남부역사 신설 토론회를 개최했다. 이후 각 정당은 내부 회의 및 외부 행사 등을 통해 정책 논의를 이어가며, 선거관리 개혁과 검찰개혁 등 주요 이슈에 대한 후속 절차가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:23'::timestamp,'2026-07-27 17:42:58.151273'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1510,3316,'2026년 7월 6일 김해시의회는 조종현 의원을 의장, 정준호 의원을 부의장으로 선출했다. 이날 선출은 국민의힘 10명의 의원 퇴장으로 인해 참여 의원 15명 중 15표를 얻어 이루어졌으며, 다수당인 민주당이 의장단을 단독 처리하려는 방침에 대해 야당은 반발했다. 조종현 의장은 시민의 목소리가 행정 변화로 이어지도록 마중물 역할을 하겠다고 밝혔고, 정준호 부의장은 여야를 넘어 소통하는 의회를 만들겠다고 강조했다. 이후 국힘 의원들은 부의장 1석과 운영위원장 1석 배분 및 상임위원회 구성에 대한 협의를 요구했으나 성사되지 않아, 향후 의회 운영에 대한 협의 절차와 다당제 협력 방안이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:28'::timestamp,'2026-07-27 17:18:07.775694'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1511,3317,'2026년 7월 11일을 기점으로 북·중 우호협력상호원조조약 체결 65주년이 되며, 양국 고위급 교류 동향이 주목되고 있다. 이 조약은 일방이 전쟁에 휘말릴 경우 상대방이 군사 원조를 제공하는 자동개입 조항을 포함하고 있으며, 특히 5년 단위의 정주년으로 사회주의 국가들이 중요하게 여기는 해이다. 노재헌 주중국대사는 북·중 관계가 한반도 평화와 안정에 기여할 수 있기를 기대하며, 중국이 한반도 문제에 건설적 역할을 하기를 바란다고 밝혔다. 한편 중국은 2026년 1월부터 시행된 민족단결진보촉진법으로 인해 외국인 방문객이 언어·문화 활동에서 주의가 필요하다고 당부하며, 이 법의 범위가 모호해 자의적 집행 가능성이 있다는 우려도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:34'::timestamp,'2026-07-27 17:17:53.243535'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1512,3852,'중랑구는 2024년 2월 상봉7구역 재개발 사업시행계획 변경인가를 고시하며, 지상 49층·841세대의 주상복합단지로 규모를 확대했다. 이는 2015년 최초 인가 당시 지상 43층·511세대였던 사업을 용적률 826.18%로 조정하고, 공동주택·오피스텔·판매시설·문화시설을 포함한 복합단지로 재편한 결과다. 현재 단지는 지하 7층~지상 49층, 총 4개 동으로 조성되며, 저층부에는 연면적 5,908㎡의 문화시설(국공립어린이집, 어린이종합체험관, 여성문화복지센터)이 조성되어 준공 후 구에 기부채납된다. 이후 공개공지 조성과 공공보행통로 신설 등 인프라 확충이 예정되며, 구는 GTX-B와 면목선 등 교통망 확충과 연계한 지역 랜드마크화를 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:39'::timestamp,'2026-07-27 16:48:36.445982'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1513,3318,'정청래 전 더불어민주당 대표가 6일 경기 수원시 경기도의회 의원총회에 참석하며 추미애 경기도지사와 회동했다. 이날 정 전 대표는 추 지사가 여성 최초의 광역단체장으로 경기도지사로서 업무를 수행하는 모습에 대해 뿌듯함을 표하며, 유능한 도지사로 성장하길 기원했다. 민주당은 6·3 지방선거에서 경기도의회 의원 167명 중 144명(86%)이 당선되며 전국에서 가장 높은 당선률을 기록했으며, 추미애 지사의 리더십이 성과에 기여했다고 평가했다. 정 전 대표는 이후 세월호 참사 희생자 박성호 군의 이름을 딴 임마누엘 성호 성당을 방문해 진상규명 미흡에 대한 미안함을 표하며, 참사의 아픔을 잊지 않겠다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:44'::timestamp,'2026-07-27 17:16:40.222553'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1514,3320,'대구 북구의회는 6일 제302회 임시회에서 국민의힘 김상혁 의원을 의장, 더불어민주당 채장식 의원을 부의장으로 단독 선출하며 제10대 전반기 원구성을 완료했다. 북구의회는 국민의힘 12명, 더불어민주당 8명, 무소속 1명으로 구성되며, 여야는 사전 협의를 통해 의장은 국민의힘, 부의장은 더불어민주당이 맡기로 합의해 원구성에 진통 없이 마무리했다. 상임위원장도 모두 단독 입후보로 선출되었으며, 행정문화위원장은 이현수 의원, 복지보건위원장은 한상열 의원, 경제도시위원장은 이성근 의원 등이 각각 선임됐다. 북구의회는 7일 개원식을 열고 제10대 의회 출범을 공식 선언하며 본격적인 의정활동에 들어갈 예정이며, 김상혁 의장은 구민 삶을 최우선으로 하는 의정활동을 약속했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:49'::timestamp,'2026-07-27 17:15:41.129527'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1515,3331,'2024년 4월 6일(현지 시간) 오만 리마 동쪽 약 14.8km 해상에서 한 유조선이 정체불명의 발사체에 피격되어 화재가 발생했다. 이는 호르무즈 해협 인근에서 발생한 것으로, 이란은 자국 승인 항로 외의 항로 이용 선박에 대해 공격 가능성을 시사하며 안전을 강조해 왔다. 현재까지 인명 피해는 확인되지 않았으나, 유조선의 피해 상황과 해상 운항 안전성에 대한 우려가 확산되고 있다. 이 사건은 이란의 전 최고지도자 알리 하메네이 장례식이 진행 중인 가운데 발생해 국제적 관심이 집중되며, 향후 해상 안보 및 외교적 대응 방향이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 11:59:53'::timestamp,'2026-07-27 18:49:11.172907'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1516,3332,'2026년 북중미 월드컵 16강전에서 미국 대표팀의 폴라린 발로건이 레드카드로 인해 자동 1경기 출전정지 처분을 받았으나, FIFA는 이에 대해 1년간 유예하는 이례적 결정을 내렸다. 이 결정은 도널드 트럼프 미국 대통령이 인판티노 FIFA 회장에게 징계 재검토를 요청한 후 나온 것으로, 유럽축구연맹(UEFA)과 유럽연합(EU)은 정치적 개입이 스포츠의 자율성과 규정의 일관성을 훼손했다며 강하게 반발했다. 벨기에 축구협회도 징계 규정 66.4조가 자동 출전정지를 명시하고 있음에도 불구하고 예외 처리된 점을 문제 삼으며, 공정성과 윤리의 원칙 수호를 강조했다. 이후 FIFA는 사법기구의 독립성을 강조하며 트럼프의 개입은 없었다고 밝히며, 향후 유사 사례에 대한 절차의 투명성과 규정 준수의 중요성을 재확인했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:00'::timestamp,'2026-07-27 18:48:55.446638'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1517,3333,'2026년 7월 5일(현지 시간), 이란 테헤란에서 이슬람 혁명 후 최고지도자였던 아야톨라 세예드 알리 하메네이의 장례식이 열렸으며, 조문객들은 도널드 트럼프 미국 대통령의 사진을 향해 돌을 던지는 상징적 의식을 거행했다. 이는 미국과 이스라엘의 표적 공습으로 하메네이가 사망한 데 대한 복수를 촉구하는 반미 시위의 일환으로, 이슬람 성지순례에서의 ''악마에게 돌 던지기'' 전통을 차용한 것으로, ''트럼프를 죽여라'', ''미국에 죽음을'' 등의 구호가 반복됐다. 장례식에는 수십만 명의 조문객이 모였으며, 일부는 트럼프 암살 현상금 2천만 달러를 제시한 플래카드를 들고 시위에 참여했고, 조문객들에게는 트럼프와 그의 참모들을 책임자로 지목한 유인물이 배포됐다. 이후 이란 정권은 장례 일정을 6일간으로 설정했고, 최고 지도자로 임명된 모즈타바 하메네이는 공개 활동을 자제하며 건강 이상설이 확산되고 있으며, 이는 미국과 이스라엘의 공습이 그의 신체에 심각한 피해를 입혔다는 보도와 연결되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:08'::timestamp,'2026-07-27 18:47:37.691275'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1518,3334,'2026년 7월 6일 중국 해군이 보하이해에서 핵잠수함에서 발사한 탄도미사일(SLBM)이 성공적으로 시험 발사된 것으로 확인됐다. 이 발사는 수심이 평균 18m에 불과한 내해에서 이뤄져, 기존에 미국과 동맹국이 설정한 태평양 진출 제한선인 제1도련선을 우회하거나 넘어서지 않고도 핵 공격 능력을 확보할 수 있음을 의미한다. 전문가 분석에 따르면 발사 궤적은 1980년 중국의 둥펑-5 미사일과 유사하며, 목표는 남태평양 공해상으로 추정된다. 이로써 중국은 지상 ICBM, 전략 폭격기, 핵잠수함 및 SLBM으로 구성된 ''핵 3축'' 체계를 국경 바로 앞에서 운영 가능하게 되었으며, 이는 동북아 및 태평양 지역의 군사 균형에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:13'::timestamp,'2026-07-27 18:46:41.080257'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1519,3338,'SK하이닉스는 2024년 6월 6일(현지 시간) 나스닥 상장 절차를 공식 개시하며, 280억 달러 규모의 기업공개(IPO)를 진행한다. AI 데이터센터 수요 증가로 메모리 반도체 수요가 급증하면서 SK하이닉스의 지난해 매출은 97조1000억원, 영업이익은 42조9000억원으로 전년 대비 각각 47%와 두 배 이상 증가했으며, 올해 1분기 매출은 전년 동기 대비 약 3배 증가한 52조6000억원을 기록했다. 이번 상장으로 조달한 자금은 국내 반도체 공장 신설과 네덜란드 ASML의 EUV 스캐너 구매 등 생산능력 확대에 사용되며, SK하이닉스는 전체 발행주식의 약 2.5%에 해당하는 1779만 주를 ADS 형태로 나스닥에 상장할 계획이다. 대표 주관사는 뱅크오브아메리카·JP모건·골드만삭스·씨티그룹이며, 미국 시장에서는 7월 10일부터 거래가 시작될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:20'::timestamp,'2026-07-27 18:36:15.957893'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1520,3345,'중국 증시는 7일 주요 경제지표 발표를 앞두고 관망세로 속락 출발했다. 상하이 종합지수는 전일 대비 0.53% 하락한 4019.49로, 선전 성분지수는 0.46% 하락한 1만5345.39로 개장했으며, 창업판 지수는 0.44% 하락한 3931.44로 거래를 시작했다. 반도체주, 금광주, 보험주, 약품주, 양조주 등이 약세를 보였고, 특히 더밍리(-6.20%), 베이징 쥔전(-6.09%), 란치과기(-3.94%) 등이 하락폭이 컸으며, 반면 중국은행(+1.42%), 닝더스다이(+4.12%) 등 일부 은행주와 전지 관련주는 상승세를 보였다. 이후 오전 10시40분 기준 상하이 종합지수는 0.76% 하락한 4010.64를 기록했으며, 주요 지수는 지속적인 하락세를 보이고 있으며, 경제지표 발표 전후 시장의 방향성과 정책 대응이 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:27'::timestamp,'2026-07-27 18:29:00.089797'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1521,3351,'중국 해군은 6일 북동부 보하이만에서 장거리 탄도미사일을 잠수함에서 시험발사해 태평양 지정 해역으로 7000km 이상 비행시켰다. 이는 중국의 연례 군사훈련이라는 설명이지만, 호주는 역내 안정을 훼손하는 행동이라며 비판했고, 일본은 잔해가 자국 배타적경제수역(EEZ)에 떨어질 수 있다고 통보받아 심각한 우려를 표명했다. 전문가 분석에 따르면 발사된 미사일은 JL-2 또는 JL-3 계열의 잠수함발사탄도미사일(SLBM)로 추정되며, 사거리는 JL-2 기준 7000km 이상, JL-3 기준 9600km 이상으로 평가된다. 이번 시험은 중국의 핵전력 강화와 수중 전력 확대를 보여주는 것으로, 미국과 동맹국들은 중국의 군사력 증강과 투명성 부족에 대한 우려를 지속하고 있으며, 2040년께 중국이 미국의 수중 전력 우위에 도전할 수 있다는 전망도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:34'::timestamp,'2026-07-27 18:27:12.034762'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1522,3360,'러시아는 2024년 7월 6일 새벽, 나토 정상회의 개막 하루 전 우크라이나 수도 키이우에 탄도미사일 68발과 드론 351대를 발사해 대규모 공습을 감행했다. 이는 러시아가 전선 밖 민간 시설을 지속적으로 타격하며 우크라이나의 방공망을 과부하 상태로 만들려는 전략의 일환으로, 특히 탄도미사일은 패트리엇 방공체계만 요격 가능해 요격 성공률이 낮았다. 공격으로 키이우에서 최소 16명 사망, 수십 명 부상, 주거건물 15곳 이상 파손되며 도심 곳곳에서 화재와 잔해가 발생했고, 일부 아파트는 상층부가 완전히 붕괴됐다. 나토 정상회의에서 우크라이나의 방공 지원 확대와 종전 논의가 예정된 가운데, 우크라이나는 패트리엇 시스템과 요격미사일 추가 지원을 요청했으며, 러시아의 극초음속 미사일 ''지르콘'' 사용 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:41'::timestamp,'2026-07-27 18:18:48.043877'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1523,3362,'2026년 7월 6일, 마크 뤼터 나토 사무총장은 튀르키예 앙카라에서 열리는 나토 정상회담을 앞두고 중국의 첫 태평양 핵잠수함 발사탄도미사일(SLBM) 시험발사에 대해 ''순진하게 대응해선 안 된다''고 강조했다. 중국은 이날 태평양 공해 해역에서 핵전략잠수함에서 발사하는 SLBM을 처음으로 시험 발사하며, 이는 1982년 이후 처음이자 핵무기 탑재 발사로 의미가 크다. 뤼터 총장은 일본 방위상 고이즈미 신지로와 문자 메시지를 통해 이 문제를 논의했으며, 인도태평양 지역의 안보가 대서양 지역과 밀접하게 연결되어 있다고 설명하며 나토의 글로벌 협력 필요성을 강조했다. 이에 따라 나토는 우크라이나 전쟁에서 중국·북한·이란이 러시아의 침략에 핵심적 역할을 했다고 지적하며, 회원국들의 국방비 증액과 인도태평양 4개국(IP4) 파트너와의 협력 강화를 추진하고 있으며, 올해 정상회담에는 호주·일본·뉴질랜드 정상이 불참했지만 이재명 대통령은 참석한다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:48'::timestamp,'2026-07-27 18:16:53.415579'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1524,3363,'2026년 7월 6일(현지시각), 볼로디미르 젤렌스키 우크라이나 대통령은 전쟁의 승패가 하늘 전투에 달려 있다고 강조하며, 우크라이나가 장거리 드론을 통해 러시아의 군사·에너지 시설을 지속적으로 타격하고 있음을 밝혔다. 이는 러시아의 지리적·병력적 우위를 상쇄하고, 전선 고착 상태에서 공중 영역을 전장으로 전환한 전략적 전환을 의미한다. 그러나 7월 2일과 6일에 각각 31명, 15명의 사망자가 발생한 러시아의 미사일 공격으로 방공 능력의 취약성이 여전히 문제로 지적되고 있으며, 우크라이나는 이에 대한 국제 지원 의존도가 높다. 젤렌스키는 모스크바를 향한 드론 공격이 1000대에 달할 경우 푸틴의 전략적 판단이 바뀌고, 거처를 옮기게 될 것이라며 전쟁 종료의 전환점으로 하늘 전투를 제시하며, 국제적 지원 유지 여부와 러시아의 전략적 반응이 향후 전개의 핵심 변수가 될 것으로 전망했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:00:56'::timestamp,'2026-07-27 18:14:55.637131'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1525,3365,'2026년 7월 7일, 엔화 환율은 미국 장기금리 하락으로 인해 1달러=162.03~162.04엔 수준으로 전반 상승하며 출발했다. 이는 미국 6월 고용통계와 ISM 비제조업 PMI가 시장 예상에 못 미치며 연방준비제도(Fed)의 금리 인상 전망이 후퇴하면서 미일 금리차 축소에 따른 엔 매수, 달러 매도 흐름이 반영된 결과다. 도쿄 외환시장에서 엔화는 오전 9시48분 기준 1달러=162.14~162.15엔으로 0.01% 상승했으며, 유로에 대해서는 1유로=185.47~185.48엔으로 약세를 보였다. 이후 8일 연준의 FOMC 회의록 공개와 내주 발표 예정인 미국 물가지표가 시장 흐름에 영향을 미칠 전망이며, 미일 금리차 유지 가능성에 따른 엔화 변동성은 지속될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:02'::timestamp,'2026-07-27 18:10:47.220600'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1526,3378,'이스라엘과 레바논은 14~15일 이탈리아 로마에서 6차 평화 협상을 개최한다. 이는 지난달 말 워싱턴DC에서 열린 5차 협상에서 휴전을 위한 기본협정에 합의한 데 이어 진행되는 것으로, 헤즈볼라의 공격 중단과 이스라엘의 레바논 남부 리타니 지역 철수를 전제로 한다. 미국은 트럼프 대통령, 네타냐후 총리, 아운 레바논 대통령 간 3자 회담을 주선하려 했으나 레바논 측이 이스라엘군 철수를 우선 조건으로 제시하며 거부했다. 현재 협상은 이탈리아 주도로 진행 중이며, 휴전 조치의 구체적 이행 시점과 감시 체계 마련이 후속 쟁점으로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:06'::timestamp,'2026-07-27 17:55:10.450951'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1527,3386,'2026년 6월 24일 베네수엘라에서 발생한 규모 7.2와 7.5의 쌍둥이 강진으로 사망자 수는 3535명, 부상자는 1만 6740명으로 집계됐다. 이 지진은 수도 카라카스를 포함한 여러 지역에 피해를 주었으며, 집을 잃은 난민은 1만 7854명으로 증가했고, 현재까지 구조된 인원은 6462명에 그쳤다. 구호품은 8만 6794 가구에 제공되었으며, 여진은 총 995건 발생했고, 외국 구조대 대부분이 구조 작업을 중단하고 귀국을 준비하고 있다. 이후 복구와 재건 정책, 국제 지원의 지속 가능성, 피해자 보상 방안 등이 주요 후속 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:11'::timestamp,'2026-07-27 17:49:11.735687'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1528,3390,'2026년 7월 6일, 이란 의회 의장 모하마드 바게르 갈리바프는 알리 하메네이 전 최고지도자와 가족이 2월 28일 미국과 이스라엘의 공습으로 사망한 데 대해, 살해범들에게 반드시 대가를 치르게 할 것이라고 경고했다. 하메네이는 이란의 종교도시 곰에 도착해 7일 장례 예배를 거행하며, 이후 8일 이라크의 시아파 성지 카르발라와 나자프로 운구된 뒤 9일 고향 마슈하드에 안장될 예정이다. 갈리바프 의장은 복수의 최종 목표로 예루살렘 해방을 언급하며 군사적·외교적 수단을 병행해 투쟁을 지속할 것임을 밝혔고, 미국과의 협상도 ''문명적 대결''의 일부로 규정했다. 이 사건은 이란 내부의 반미·반이스라엘 감정을 고조시키며, 중동 지역의 긴장이 지속될 가능성을 시사하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:17'::timestamp,'2026-07-27 17:47:47.802876'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1529,3392,'2026년 7월 7일 튀르키예 앙카라에서 열린 나토 정상회의는 32개 회원국 정상이 참석해 ''앙카라 선언''을 통해 집단 방위 원칙 재확인과 러시아에 대한 장기적 위협 지적을 담았다. 트럼프 미국 대통령은 회원국의 방위비 증액을 압박하며, 유럽과 캐나다가 지난해 방위비를 1390억 달러 이상 늘렸다고 강조하며 ''나토 3.0'' 전환을 요구했다. 회원국들은 2035년까지 GDP의 5%를 방위 지출에 투입하기로 합의했으며, 유럽의 방어 책임 이전과 실전 배치 가능한 전력 확대를 추진 중이다. 트럼프 대통령의 예측 불가능한 발언과 동맹국 비판이 지속되며 회의의 성과와 동맹의 지속 가능성에 대한 우려가 제기되고 있으며, 이어질 양자 회담과 정상 만찬 등 추가 일정이 회의의 결과에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:24'::timestamp,'2026-07-27 17:47:31.813404'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1530,3393,'캐나다 정부는 차세대 잠수함 12척 건조 사업의 우선협상대상자로 독일 방산업체 티센크루프마린시스템즈(TKMS)를 선정했다. 이는 노후한 빅토리아급 잠수함을 대체하기 위한 캐나다 역사상 최대 규모의 방위사업으로, 사업 총비용은 약 108조 원(1000억 캐나다달러)으로 예상된다. 한화오션은 TKMS와 함께 적격후보군에 포함되었으나, 최종 수주에 실패했으며, TKMS와의 협상이 결렬 시 예비 공급업체로 한화오션의 KSS-Ⅲ를 우선협상대상자로 지정할 계획이다. 캐나다 정부는 내년 중 최종 계약 체결을 목표로 하며, 산업 역량 강화와 일자리 창출을 핵심 목표로 삼고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:30'::timestamp,'2026-07-27 17:45:23.236204'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1531,3485,'국토교통부는 7월 7일 화요일에 장관과 1차관, 2차관, 대도시권광역교통위원장이 각각 통상일정 및 국무회의 참석 등 주요 일정을 진행했다. 이날 기준 국토교통부는 부동산 정책 및 대도시권 광역교통 협의체 운영을 중심으로 정책 추진을 지속하고 있으며, 특히 광주 반도체 클러스터 및 민간공항 이전 관련 현안을 점검하고 있다. 최근 삼성전자 2분기 실적이 역대 최대를 기록했으나 주가는 6.92% 하락하며 투자자들의 불안감이 확산되고 있으며, 이는 반도체 시장의 급변하는 흐름과 관련이 있다. 향후 국토교통부는 반도체 산업과 연계된 인프라 정비 및 공공교통 협의체 운영의 효율성 제고를 위한 정책 절차를 예정하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:41'::timestamp,'2026-07-27 17:45:07.163162'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1532,3398,'도널드 트럼프 미국 대통령이 6일(현지시간) 백악관에서 새 연회장 건설 계획을 설명하는 자리에서 시진핑 중국 국가주석이 9월24일께 백악관을 방문할 것으로 예상한다고 밝혔다. 이는 지난 5월 베이징 정상회담에서 트럼프 대통령이 시 주석과 부인 펑리위안 여사에게 9월24일 백악관 방문을 초청한 것의 연장선으로, 중국 외교부도 올가을 시 주석의 미국 국빈 방문 가능성을 확인한 바 있다. 다만, 구체적인 방미 일정과 회담 형식은 양국 정부가 별도로 발표하지 않아 최종 확정되지 않았으며, 9월24일은 뉴욕에서 열리는 유엔총회 제81차 고위급 회기와 겹치는 시점이다. 시 주석이 실제로 미국을 방문할 경우 유엔총회 참석과 백악관 회담을 병행할 가능성이 제기되며, 이는 그가 집권 후 유엔총회에 직접 참석한 첫 번째 사례가 될 수 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:47'::timestamp,'2026-07-27 17:40:52.137052'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1533,3399,'2026년 7월 6일(현지시간) 미군과 이스라엘의 표적 공습으로 사망한 이란 전 최고지도자 아야톨라 세예드 알리 하메네이의 시신이 이란의 종교도시 곰에 도착했다. 하메네이의 장례 절차는 4일 테헤란에서 시작되어, 7일 곰에서 시아파 고위 성직자들이 참석한 장례 예배를 거쳤으며, 8일 이라크의 시아파 성지 카르발라와 나자프로 시신을 운구할 예정이다. 9일에는 그의 고향이자 시아파 성지인 이란 북동부 마슈하드에서 안장될 예정이며, 이 과정은 이란 내외의 종교적·정치적 관심을 모으고 있다. 이후 장례 절차의 완료와 관련된 국가 차원의 공식 행사 및 외교적 반응이 예상되며, 이란 내부의 정치적 안정성과 국제 관계에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:51'::timestamp,'2026-07-27 17:40:27.164325'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1534,3401,'2026년 7월 6일 중국 광시좡족자치구 난닝시에서 집중호우로 인한 홍수로 최소 2명이 사망하고, 5만5000여명이 이재민으로 발생했다. 이는 난닝시 헝저우 지역의 류란 저수지 제방 일부 손상으로 인한 침수 피해가 주요 원인으로, SNS에서 저수지 붕괴설이 확산되며 사회적 우려가 커졌다. 당국은 저수지 붕괴가 아니며 시설 손상에 따른 긴급 대응 중이라고 밝히고, 현재까지 4만8000명이 대피했으며, 국가발전개혁위원회는 복구를 위해 1억 위안(약 225억 원)의 예산을 배정했다. 또한 국가방재감재구재위원회와 응급관리부는 텐트, 접이식 침대, 의류 등 중앙 구호물자 15만 점을 긴급 지원해 이재민의 생활 안정을 도모하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:01:57'::timestamp,'2026-07-27 17:36:19.724312'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1535,3405,'베네수엘라 북부 라과이라주 카라베예다 지역에서 발생한 규모 7.2와 7.5의 연쇄 강진 이후 267시간 동안 잔해 속에 갇혀 있던 생존자 4명(어린이 2명, 여성 1명, 남성 1명)이 6일(현지 시간) 구조됐다. 이 지진은 지난달 24일 오후 6시(현지 시간)에 발생했으며, 39초 간격으로 두 차례의 강진이 이어져 베네수엘라에서 최근 100년간 가장 큰 인명 피해를 초래한 재난으로 평가된다. 현재까지 베네수엘라 정부의 집계에 따르면 지진으로 최소 3342명이 사망하고 1만6700명이 부상했으며, 구조된 4명은 응급 처치를 받은 뒤 병원으로 이송돼 치료를 받고 있다. 이후에도 수색 작업이 지속되고 있으며, 피해 복구와 인도적 지원 확대가 예정된 가운데, 국제사회가 구호 물자와 전문 인력 제공을 논의하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:02'::timestamp,'2026-07-27 17:34:18.910576'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1536,3549,'2026년 7월 7일 광주고법 형사2부는 생후 4개월 된 아들 ''해든이''를 학대해 사망하게 한 친모 A씨(34)와 친부 B씨(36)에 대해 각각 무기징역과 징역 10년을 구형했다. A씨는 19차례에 걸쳐 아동학대를 하고, 수차례 폭행 및 욕조에 샤워기 물을 틀어 방치해 아동을 사망하게 한 혐의로 1심에서 무기징역을 선고받았으며, B씨는 아내의 학대를 방임하고 사건 참고인을 협박한 혐의로 1심에서 징역 4년 6개월을 선고받았다. 검찰은 A씨가 감정 표현의 대상으로 아동을 학대했고, B씨는 아동 보호 의무를 소홀히 해 책임을 회피했다며 엄벌을 요청했으며, 재판 과정에서 여검사의 구형 의견 낭독과 A씨의 ''좋은곳 가길'' 편지 낭독으로 방청객이 울먹이는 등 사회적 공감대가 형성됐다. 항소심 선고는 2026년 8월 25일 오후에 예정되어 있으며, 사건은 아동학대 방지 및 양육 책임에 대한 사회적 논의를 촉발하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:11'::timestamp,'2026-07-27 18:29:07.823491'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1537,3564,'2026년 7월 7일, 창원지방검찰청은 허위 렌탈계약을 통해 금융회사로부터 141억원을 사기로 빼돌린 혐의로 A렌탈사 대표 B씨와 이사 C씨를 구속기소하고, 금융심사 편의를 제공한 캐피탈사 직원 D씨를 배임수재 혐의로 불구속 기소했다. 이 사건은 병원, 공장, 호텔 등 사업자를 대상으로 ''백렌탈''과 ''공렌탈'' 방식의 허위 계약을 체결하고, 실제 물품 없이 리스·팩토링 등 금융상품을 신청해 허위 확인서를 제출해 자금을 유치한 조직적 사기 구조로, 전국적으로 약 414억원 규모의 허위 계약이 확인된 것으로 파악됐다. 검찰은 A렌탈사가 금융기관에서 받은 자금 중 약 11%를 수수료로 챙기며 불법 대부업을 운영했으며, 캐피탈사 직원에게 약 4년간 현금 1억6000만 원과 고급 승용차 렌트비 4300만 원 등 총 2억원 상당의 금품을 제공해 심사 편의를 제공받은 사실도 확인했다. 검찰은 해외 체류 중인 관련자까지 수사 범위를 확대하고 있으며, 범죄수익 환수와 외부 공범 수사, 엄정한 처벌을 지속할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:19'::timestamp,'2026-07-27 18:25:41.513161'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1538,3407,'2026년 7월 6일, 미국의 도널드 트럼프 전 대통령은 백악관에서 열린 ''트럼프 계좌'' 출시 행사에서 우크라이나 전쟁 종식이 사람들의 예상보다 훨씬 가까워졌다고 주장했다. 그는 블라디미르 푸틴 러시아 대통령과 볼로디미르 젤렌스키 우크라이나 대통령 모두 전쟁 종식을 원한다고 강조하며, 7~8일 튀르키예 앙카라에서 열리는 나토 정상회의에서 이 문제를 집중 논의할 예정이라고 밝혔다. 이 발언은 러시아가 나토 정상회의 직전인 6일 키이우를 대규모로 공습해 최소 22명 사망, 80명 이상 부상하는 피해를 입힌 상황에서 나왔다. 트럼프는 8일 젤렌스키 대통령과 회담을 통해 종전 방안을 논의할 계획이며, 이는 우크라이나 침공이 5년째 이어지는 상황에서 진행되는 것으로, 전쟁 종식 가능성과 관련해 국제적 관심이 집중되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:24'::timestamp,'2026-07-27 17:33:07.676408'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1539,3409,'2026년 7월 6일(현지시간), 이란의 마무드 아마디네자드 전 대통령이 알리 하메네이 전 최고지도자의 장례 행진에 참석하며 수개월 만에 공개석상에 모습을 드러냈다. 아마디네자드 전 대통령은 2005~2013년 재임 기간에 대이스라엘 강경 발언과 핵 프로그램 추진으로 강경파로 평가받았으나, 퇴임 후인 2019년에는 도널드 트럼프 미국 대통령을 긍정적으로 평가하며 미국과의 관계 개선을 제안한 바 있다. 최근까지 공개 활동을 중단하며 행방이 묘연했으나, 이란 내부에서의 정치적 지위 회복 가능성과 미국의 차기 지도자 후보 검토 보도가 있었던 상황에서 이번 참석이 주목받고 있다. 이에 대해 미국과 이란 정부는 공식 입장을 밝히지 않았으며, 아마디네자드 전 대통령의 정치적 입지와 테헤란 내 권력 구도 변화에 대한 분석이 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:30'::timestamp,'2026-07-27 17:31:35.024402'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1540,3411,'2026년 7월 5일(현지 시간) 이란 테헤란에서 사망한 아야톨라 세예드 알리 하메네이 전 이란 최고지도자의 장례식에서, 미국의 표적 공습을 비난하며 도널드 트럼프 미국 대통령을 겨냥한 ''악마에게 돌 던지기'' 퍼포먼스가 발생했다. 하메네이는 미국과 이스라엘의 공습으로 사망했으며, 이란 내에서는 반미 감정이 고조된 상황에서 장례 행진에 참석한 시민들이 트럼프 얼굴이 담긴 사진을 향해 돌을 던지는 의식을 재현했다. 일부 참가자들은 ''트럼프를 죽여라''는 문구와 함께 2000만 달러의 현상금을 제시하는 팻말을 들었으며, 미국 국기를 불태우는 행위도 관찰됐다. 장례식은 7월 9일까지 이어지며, 7일 곰, 8일 카르발라와 나자프에서 예배를 거쳐 9일 마슈하드에서 안장될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:36'::timestamp,'2026-07-27 17:28:14.204668'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1541,3414,'2026년 7월 7일, 나토 사무총장 마르크 뤼터는 튀르키예 앙카라에서 열리는 나토 정상회의 기간 중 수백억 달러 규모의 방산 계약을 공개할 예정이라고 밝혔다. 이 계약은 유럽 및 캐나다 회원국들이 GDP의 약 4%를 국방·안보에 투자하며, 도널드 트럼프 미국 대통령의 방위비 증액 압박에 대응해 실질적인 무기 조달과 공동 생산을 추진하는 데 기여한다. 나토는 2035년까지 국방·안보 지출을 GDP의 5%로 끌어올리겠다는 목표 달성을 위해 이번 회의에서 각국의 구체적 이행 계획을 제시할 예정이며, 중국 견제 및 인도·태평양 지역의 안보 변화에 대비한 전략적 전환점을 마련할 것으로 보인다. 이후 나토는 계약 이행 상황과 회원국의 방위비 분담 비율 변화를 지속적으로 모니터링하며, 향후 정기적 점검과 외부 감사 절차를 예정하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:42'::timestamp,'2026-07-27 17:27:32.772657'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1542,3417,'2026년 하반기 미국 증시에 대한 낙관론이 확산되며, 기업 실적과 유동성에 기반한 강세장이 2027년까지 지속될 것이라는 전망이 나왔다. 이는 미국과 이란의 긴장 완화로 유가 하락, 반도체주 강세 및 AI 관련 수익 전망 등 긍정적 요인이 작용한 결과로, S&P500 지수는 최근 6년 만에 가장 높은 분기 수익률을 기록했다. 애널리스트들은 향후 12개월 동안 S&P500이 약 21% 상승할 것으로 전망하며, JP모건은 연말 목표치를 7800으로 상향 조정했다. 다만 반도체주 급등에 따른 조정 가능성과 빅테크 기업의 대규모 AI 투자 수익성에 대한 우려가 제기되며, 투자자들은 중소형주와 해외 주식, 산업재·헬스케어 등 AI 수혜 업종에 주목할 필요가 있다고 조언했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:48'::timestamp,'2026-07-27 17:26:50.940698'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1543,3419,'2026년 7월 6일 새벽, 러시아는 우크라이나 수도 키이우와 주변 지역에 미사일 68발, 드론 351대를 동원해 대규모 복합 공격을 감행했다. 이는 나토 정상회의를 앞두고 진행된 것으로, 키이우 시내 및 외곽 도시 비슈네베에서 주거지역과 기반시설이 파괴되며 최소 14명 사망, 약 60명 부상하는 피해가 발생했다. 우크라이나 공군은 방공망으로 미사일 37발, 드론 326대를 요격했으나, 탄도미사일 29발과 드론 18대가 전국 34곳에 명중했으며, 구조 작업이 지속 중이다. 젤렌스키 대통령은 나토 정상회의에서 방공망 지원 강화를 촉구하며, 트럼프 미국 대통령과의 회동을 통해 우크라이나의 방어력 강화가 핵심 의제로 부상할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:02:54'::timestamp,'2026-07-27 17:25:56.177233'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1544,3565,'2026년 7월, 장마와 휴가철이 겹치며 고속도로 사고 위험이 증가하고 있다. 최근 3년간 7월 평균 강수량은 378㎜로 연중 최고이며, 빗길 교통사고로 인한 인명 피해는 6월 평균 0.7명에서 7월 1.3명, 8월 3.3명으로 증가했다. 지난해 7월 영동고속도로와 서해안고속도로에서 각각 타이어 파손과 졸음운전 사고로 사망자가 발생했으며, 최근 5년간 빗길 사고의 치사율은 4.7명으로 맑은 날보다 약 1.4배 높다. 도로공사는 출발 전 타이어 점검, 속도 감속, 차간거리 확보, 정기적 환기 및 2시간 이상 운전 시 휴게소 휴식을 통해 사고 예방을 당부하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:00'::timestamp,'2026-07-27 18:25:33.490905'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1545,3420,'2026년 7월 8일, 이란 대통령 마수드 페제시키안은 최고지도자 알리 하메네이의 장례식 참석을 위해 이라크 나자프와 카르발라를 방문한다. 하메네이의 장례는 6일 테헤란에서 시작되어 7일 이란 중부 곰에서 시아파 고위 성직자들이 참석한 장례 예배를 거쳐, 8일 이라크의 시아파 성지인 카르발라와 나자프에서 장례 행사가 진행된다. 장례 일정은 9일 이란 북동부 마슈하드에서 하메네이의 시신이 안장되며, 이는 이란 내외의 정치적·종교적 맥락에서 중요한 의미를 지닌다. 이후 이란 정부는 장례식 이후의 정치적 안정성과 외교적 반응, 특히 이라크와의 관계 유지 여부에 대한 후속 조치를 검토할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:05'::timestamp,'2026-07-27 17:25:43.071836'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1546,3423,'기획예산처는 2026년 7월 7일 박홍근 장관 주재로 국회 의원회관에서 청년 국회의원들과 청년정책 간담회를 개최했다. 이번 간담회는 일자리, 창업, 주거, 자산 등 청년정책 핵심 과제를 논의하며, 기획처가 지난 3월 청년 일자리 현장 방문과 5월 청년 라이브톡 등을 통해 현장 의견을 수렴한 후 진행된 것으로, 청년 전문가 간담회를 거쳐 2027년도 예산안과 중장기 전략에 반영할 계획이다. 기획처는 청년 실업률 상승과 주거비 부담 증가 등 현실적 어려움을 국가적 과제로 인식하고, 청년의 공정한 기회 제공과 회복 사다리 마련을 정책 목표로 삼고 있다. 이후 청년 전문가 간담회를 추가로 개최하고, 제시된 의견을 검토해 예산과 정책에 구체적으로 반영할 예정이며, 야당 의원은 실망감 해소를 위한 실질적 성과가 필요하다는 지적을 제기하며 정책 이행의 지속성과 효과성에 주목하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:12'::timestamp,'2026-07-27 18:59:23.803765'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1547,3425,'한전원자력연료는 2024년 4월 7일 대전 본사에서 AI전략위원회를 출범시켰다. 이는 생성형 AI 확산과 공공부문 AI 활용 확대 등 디지털 환경 변화에 선제적으로 대응하고 전사적 AI 전략을 수립하기 위한 목적이다. 위원회는 최고경영자(CEO)가 위원장으로, 대내외 전문가가 참여해 AI 전략 수립, 실행과제 관리, 현장 역량 확산, 보안·윤리 리스크 대응 등 전사적 현안을 논의하며, 우선과제 선정과 실행 방향을 구체화했다. 이후 AI 기반 업무혁신의 지속적 추진과 함께, 기술 도입의 윤리적·보안적 관리, 조직 내 역량 강화 등 후속 절차가 진행될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:16'::timestamp,'2026-07-27 18:52:14.477221'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1548,3427,'2023~2025년 최근 3년간 우천 시 교통사고 치사율은 맑은 날 대비 1.3배 높은 1.58명으로 집계됐다. 비나 노면이 젖은 상태에서는 타이어와 노면의 접촉력이 감소해 제동거리가 늘어나는 수막 현상이 발생해 사고 위험이 증가한다. 특히 노면이 ''젖음·습기''일 때 치사율은 1.85명으로 건조 상태(1.25명)보다 약 1.5배 높으며, 폭우 시에는 감속 운행을 50% 이상 해야 한다. 한국교통안전공단은 빗길 운전 시 타이어 점검, 와이퍼·워셔액 점검, 차간 거리 확보, 비상 탈출 도구 비치 등을 통해 사고 예방을 당부하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:21'::timestamp,'2026-07-27 18:46:51.899279'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1549,3434,'IPARK현대산업개발은 7일 서울숲 국제정원박람회에서 시민 대상으로 텀블러 나눔 캠페인을 진행하며 일회용품 사용 감소와 탄소중립 실천을 유도했다. 이는 IPARK현대산업개발의 ESG 사회공헌 활동 일환으로, HDC랩스, IPARK호텔, IPARK신라면세점 임직원 30명이 성동구자원봉사센터와 투썸플레이스와 협력해 텀블러를 제작하고 시민들에게 배부한 것이며, 친환경 생활 문화 확산을 목표로 했다. 행사에서는 텀블러 사용의 탄소 절감 효과와 자원순환의 중요성을 알리며 시민들과 실천 방법을 공유했으며, 캠페인은 지역사회와의 상생을 위한 지속 가능한 ESG 경영의 일환으로 평가받고 있다. 이후 IPARK현대산업개발은 중랑천 환경정화, 강서습지 생태환경 보전 등 임직원 참여형 사회공헌 프로그램을 지속적으로 운영할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:26'::timestamp,'2026-07-27 18:41:24.774967'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1550,3773,'청와대는 5·18 기념일을 ''성역''이라고 표현한 이병태 대통령 직속 규제합리화위원회 부위원장에 대해 사퇴를 권고했다. 이병태 부위원장은 2026년 4월 15일 이재명 대통령의 위촉으로 부위원장으로 임명되었으며, 배재고 야구부의 ''스타벅스 응원 구호'' 논란과 관련해 5·18을 성역화하는 것은 전체주의적 강요라고 주장해 사회적 논란을 일으켰다. 청와대는 이 발언이 정부의 국정 기조와 부합하지 않으며, 갈등을 증폭시켰다며 책임 소재를 지적하고 사퇴 권고를 결정했다. 현재 이병태 부위원장은 거취를 스스로 판단 중이며, 이 사건은 포용적 통합 정책의 실패 여부와 공직자 발언의 사회적 영향에 대한 논의로 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:30'::timestamp,'2026-07-27 16:59:25.695999'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1551,3437,'기후에너지환경부는 2026년 7월 7일 서울 강남구 코엑스에서 대한상공회의소와 함께 제4차 자연자본공시 토론회를 개최했다. 이는 자연자본공시 표준을 제정한 TNFD 등 국제 기구와 해외 기업·금융기관 전문가들이 참여해 국제 동향과 대응 전략을 공유하는 자리로, 삼성전자와 SK증권도 각각 제조업 및 금융기관 차원의 경험을 발표했다. 이번 토론회에는 국내외 기업·학계·전문가 등 150여 명이 참석했으며, 기후부는 기업의 대응 역량 강화를 통해 생물다양성 보전 투자 확대를 목표로 하고 있다. 향후 기업들의 자연자본 공시 이행률 제고와 국내 기준 마련을 위한 정책 방향성 논의가 예정되어 있으며, 기업의 실질적 대응 체계 구축이 핵심 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:35'::timestamp,'2026-07-27 18:40:42.833737'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1552,3440,'구윤철 부총리 겸 재정경제부 장관은 2026년 7월 말에 실거주자 중심의 부동산 세제 개편안을 발표할 예정이라고 밝혔다. 정부는 보유세와 거래세의 조화를 통해 주택시장의 실거주 중심화를 도모하며, 국민 의견 수렴 절차를 거쳐 최종 방침을 결정할 계획이다. 2026년 상반기 예상 초과세수는 삼성전자와 하이닉스의 영업이익 기반으로 600조원 규모로 추정되며, 이는 ''미래대응기금''에 우선 투입될 예정이다. 이 기금은 반도체 클러스터를 비롯한 혁신산업의 전력·용수 공급 및 R&D 지원에 사용되며, 하반기 물가상승률을 3% 이내로 관리하기 위해 1조 원 규모의 재정 지원을 시행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:41'::timestamp,'2026-07-27 18:37:28.012293'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1553,3442,'기후부는 8일 세종시에서 ''기후 에이아이 프렌즈'' 발대식을 열고, 부처 산하기관 직원 2~3명으로 구성된 총 20개 팀을 선발해 인공지능 기반 업무혁신 과제를 추진한다. 이는 공공부문의 인공지능 대전환에 발맞춰 직원들의 기술 활용 역량을 높이고, 실제 업무에 AI를 적용할 수 있는 혁신 과제를 발굴하기 위한 것으로, 사전 신청한 40개 팀 중 창의성, 실현 가능성, 업무 활용성 등을 기준으로 선정했다. 선정된 팀들은 9월까지 ''인공지능 기반 업무자동화''와 ''인공지능 서비스 기획·구현'' 두 분야에서 활동하며, 기후부는 실습 교육과 전문가 조언을 지원하고 성과공유회를 통해 우수 사례를 확산할 계획이다. 이후 기후부는 과제 성과를 바탕으로 공공행정 혁신과 국민 편의 증진을 위한 정책적 적용 방안을 검토할 예정이며, 이는 공공부문 AI 전환의 모범 사례로 자리매김할 가능성이 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:47'::timestamp,'2026-07-27 18:31:38.664806'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1554,3445,'2026년 7월 7일 공정거래위원회는 전분당 제조·판매업체 4곳(대상, 사조씨피케이, 삼양사, CJ제일제당)이 2018년 5월부터 2025년 10월까지 7년5개월간 B2B 시장에서 가격담합을 벌인 것으로 판단하고, 총 7476억원의 과징금을 부과했다. 이는 담합 사건 역사상 최대 규모로, 업체별 과징금은 대상 2341억원, 사조씨피케이 2001억원, 삼양사 2103억원, CJ제일제당 1029억원이며, 시장점유율에 따라 차이가 발생했다. 담합으로 인해 관련 매출액 6조525억원이 영향을 받았고, 공정위는 매출액의 15%를 기준으로 과징금을 산정했으며, 조사 협조를 고려해 20% 감경을 적용했으나 대상은 법 위반 전력으로 인해 10% 가중 처리했다. 공정위는 4개사에 3년간 반기별로 가격 재결정 결과를 보고하도록 명령했으며, 이는 지난 5월 밀가루 담합 사건 이후 네 번째로 시행된 조치로, 장기간 지속된 과점 구조와 담합 관행이 재발 가능성 높다고 판단했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:03:57'::timestamp,'2026-07-27 18:31:51.803645'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1555,3446,'공정거래위원회는 2016년 9월부터 2024년 6월까지 8년9개월간 대상, 사조씨피케이, 삼양사, CJ제일제당 등 4개 전분당 제조·판매업체가 입찰 및 부산물 가격을 담합한 의혹에 대해 심의를 착수했다. 입찰담합은 포스코 등 7개 실수요처의 전분당 구매 입찰에서 낙찰자와 가격, 물량을 사전 합의한 것으로, 관련 매출액은 9400억원으로 산정됐으며, 부산물 가격 담합은 2017년 8월부터 2024년 10월까지 매일 가격을 조율한 것으로, 관련 매출액은 1조5500억원에 달했다. 공정위는 이 사건을 ''매우 중대한 위법행위''로 판단해 관련 매출액의 최대 20%인 4980억원까지 과징금을 부과할 수 있으며, 향후 3년간 반기별로 가격 변경 내역을 보고하도록 시정명령을 부과할 예정이다. 공정위는 입찰담합과 부산물 담합이 별도로 산정된 점을 고려해 각각의 과징금을 별도로 적용하며, 담합 종료 후 가격이 독자적으로 결정된 사례를 감안해 가격 재결정 명령은 부과하지 않기로 했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:05'::timestamp,'2026-07-27 18:31:25.806497'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1556,3458,'한국 선박 한 척이 4월17일부터 시작된 홍해를 통과해 사우디아라비아 얀부항에서 적재한 원유를 국내로 운송했다. 이는 호르무즈 해협이 미국과 이란 간 중동전쟁으로 인해 봉쇄된 이후 대체 항로로 홍해를 활용한 12번째 운송이다. 해양수산부는 선박의 안전을 위해 실시간 모니터링과 소통 채널을 운영했으며, 현재까지 국내 원유 수급 안정화를 위해 홍해 경로를 지속적으로 활용할 계획이다. 한편, 호르무즈 해협 내에는 이란 공격으로 수리 중인 HMM 나무호를 포함해 한국 선박 2척과 선원 23명이 남아 있어 안전 상황이 주목되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:09'::timestamp,'2026-07-27 18:21:46.386890'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1557,3464,'한국탄소산업진흥원은 2026년 11월 4일부터 6일까지 서울 마곡 코엑스 컨벤션센터에서 ''카본코리아 2026''을 개최하며, 참가기업을 31일까지 모집한다. 이번 행사 주제는 ''인공지능(AI)과 함께하는 탄소소재의 미래: 우주·항공·방산, 에너지''로, AI 기술과 탄소소재 산업의 융합을 강조하며 우주항공, 방산, 에너지 등 핵심 수요산업과의 협력 기회를 확대한다. 전시 규모를 확대하고 코엑스 마곡으로 장소를 이전해 기업 간 비즈니스 상담과 기술 교류를 원활히 하며, 미국·일본·독일 등 해외 기업과의 국제관 운영 및 글로벌 기업 관계자들의 연사 참여를 예정하고 있다. 참가기업은 1차 모집 기간(31일까지)에 신청 시 부스 우선 배정 및 운송료 지원 혜택을 받을 수 있으며, 행사 기간 동안 전시, 컨퍼런스, B2B 상담회, 글로벌 기업 교류 프로그램 등이 진행될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:15'::timestamp,'2026-07-27 18:11:00.359970'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1558,3468,'한국산업단지공단은 2026년 9월 14일부터 16일까지 대구 엑스코에서 열리는 ''제2회 대한민국 산업단지 수출박람회(KICEF 2026)''에 참가할 기업을 7일부터 모집한다. 이 박람회는 국내 산업단지 입주기업의 해외시장 진출을 지원하기 위해 마련된 산업단지 대표 수출 행사로, 올해는 ''지역의 힘을 미래로, 기업의 도전을 세계로''를 슬로건으로 전시회와 수출상담회를 중심으로 운영된다. 이번 행사에는 500개사 400부스 규모로 운영되며, 유럽·미국·동남아 등 전 세계 100여 명의 산업 바이어를 초청해 1대1 수출상담회를 진행하고, ICT·첨단산업·에너지·소비재·의료·바이오·콘텐츠 등 6개 분야 기업을 대상으로 참가를 모집한다. 참가기업은 공식 누리집을 통해 온라인 신청이 가능하며, 행사에는 제62회 산업단지의 날 기념식과 글로벌 오픈이노베이션, 세미나 등 유관기관 협력 프로그램도 포함된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:22'::timestamp,'2026-07-27 18:03:52.671843'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1559,3469,'2026년 6월 30일 정부는 영산강·섬진강 유역의 5개 댐을 통해 일일 65만t의 용수를 호남 반도체 클러스터에 공급할 예정이라고 발표했다. 이는 2023년 기후에너지환경부가 발간한 ''영산강·섬진강유역 가뭄백서''에 따라 설정된 가뭄 비상용수 계획으로, 동복댐, 주암댐, 장흥댐, 보성강댐, 나주댐이 포함되며, 이들 댐은 과거 가뭄으로 인해 저수율이 역대 최저 수준에 도달한 상태였다. 박수영 국민의힘 의원은 이 용수 공급 계획이 이미 3년 전 가뭄 대책에서 주민 생활용수 및 산단 공급용으로 배정된 물량과 중복되며, 주암댐은 여수·광양산단 용수 공급을 위한 도수관로 설치가 진행 중인 상황임을 지적했다. 이에 따라 반도체 용수 공급 계획의 타당성과 수자원 배분의 우선순위에 대한 논란이 제기되며, 국회 차원의 국정조사 필요성이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:29'::timestamp,'2026-07-27 18:03:09.726472'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1560,3471,'구윤철 경제부총리는 2026년 7월 7일 정부의 3대 메가프로젝트에 대해 지방 근무자에 대한 소득세 차등 감면을 검토하고, 기업에는 연구개발 투자에 대한 이월공제까지 포함한 세제 지원을 추진하겠다고 밝혔다. 이는 반도체·인공지능 등 핵심 산업의 투자 활성화와 함께, 지방 근무 환경의 열악함을 고려한 세제 개편의 일환으로, 정부는 초과세수를 활용해 미래대응기금을 신설해 혁신산업 인프라 및 전력·용수 공급에 우선 투자할 계획이다. 2026년 상반기 예상 초과세수는 삼성전자와 하이닉스의 영업이익 기반으로 600조원 수준으로 추정되며, 이는 반도체 클러스터 외에도 조선, 항공, 로봇 등 다양한 분야의 R&D 지원에 활용될 예정이다. 또한 부동산 세제 개편은 실거주 중심의 주택시장 정착을 목표로 하며, 국민 의견 수렴 절차를 거쳐 2026년 하반기 중 최종 방침을 결정할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:37'::timestamp,'2026-07-27 17:59:16.436374'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1561,3482,'서울 아파트 전세난이 장기화 조짐을 보이고 있으며, 2024년 들어 전셋값은 전년 대비 5.1% 상승하며 매매가격 상승률과 비슷한 수준에 도달했다. 전세 매물은 지난해 동기 대비 18.7% 감소한 2만258건으로, 중랑구(82.9% 감소) 등 일부 자치구에서 감소 폭이 컸으며, 전세수급지수는 126.7로 2021년 1월 이후 최고치를 기록하며 수요와 공급의 불균형이 심화되고 있다. 이는 10·15 대책으로 인한 토지거래허가구역 확대, 전세대출 한도 축소(DSR 규제 포함), 신규 입주 물량 감소(2024년 1만7210가구) 등이 복합적으로 작용한 결과로, 전세의 월세화 현상이 가속화되고 있다. 전문가들은 전세 매물 부족과 입주 물량 감소가 지속될 것으로 전망하며, 단기적 해소는 어렵고, 임차인의 주거비 부담 확대와 월세 상승 압력이 지속될 것으로 보고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:45'::timestamp,'2026-07-27 17:46:48.447480'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1562,3483,'7월 7일 화요일, 구윤철 경제부총리 겸 재정경제부 장관은 국무회의에 참석해 경제 정책을 논의했으며, 이어 국회 재경위에서 업무보고를 진행했다. 이날 국무회의에는 김성환 기후에너지환경부 장관과 김정관 산업통상부 장관 등 주요 부처 장관들이 참석해 반도체 산단 전력·용수 공급 현장 점검과 탈탄소·순환성 포럼 등 산업 경쟁력 강화 정책을 논의했다. 공정거래위원회는 현대차그룹과 협력사 간 상생협약 체결식을 개최하며, 협력사 지원과 공정한 거래 환경 조성을 추진하고 있다. 이후 경제부총리와 기획예산처 장관은 청년정책 간담회와 재정투자평가위원회를 열어 청년 일자리와 재정 투자 효율성에 대한 논의를 이어갈 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:50'::timestamp,'2026-07-27 17:47:08.234286'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1563,3491,'2026년 7월 3일 서울회생법원은 홈플러스의 기업회생절차를 폐지하기로 결정했으나, 이는 공고일로부터 14일간 즉시항고 가능해 현재도 회생절차가 유지될 수 있다는 점에서 법적 불확실성이 지속되고 있다. 홈플러스는 회생절차 폐지 결정이 즉시 효력이 없으며 카드사들이 이를 근거로 온라인몰 포인트 제휴 종료 및 대금 지급 보류를 통보한 것은 부당하다고 반발했다. 삼성카드는 홈플러스의 반발 이후 대금 지급 보류 조치를 철회하고 지급을 재개했으며, 현대카드는 포인트 사용 일부만 제한했을 뿐 가맹점 대금 지급은 중단하지 않았다고 밝혔다. 이후 14일간의 즉시항고 기간 동안 홈플러스가 운영자금을 조달해 항고를 제기할 경우 회생절차 폐지 결정이 취소될 수 있으며, 이에 따라 카드사들의 대응 방향도 법적 절차에 따라 유동적으로 조정될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:04:57'::timestamp,'2026-07-27 17:18:51.993767'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1564,3492,'2026년 5월 6일 오후 6시 기준, 호르무즈 해협 내 한국인 선원 5명이 탑승한 외국 국적 선박 1척이 이탈하며 안전하게 빠져나왔다. 이는 이란 반다르아바스 앞 해상에서 발생한 해상 안보 위기 상황 속에서 외국 선박의 이탈이 증가한 결과로, 한국인 선원의 안전 확보를 위한 국제적 조치가 진행 중이다. 현재 호르무즈 해협 내에 남아 있는 한국인 선원은 한국 선박 2척에 7명, 외국 선박에 16명 등 총 23명으로 집계됐으며, 해양수산부는 하선한 선원의 귀국 정보는 개인정보 보호와 안전을 이유로 공개하지 않았다. 이후 해수부는 선원들의 안전 확보를 위한 추가 조치와 외교적 협의를 지속할 예정이며, 이란 및 주변 국가와의 협력이 중요해질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:01'::timestamp,'2026-07-27 17:15:32.954066'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1565,3493,'SK하이닉스는 2026년 7월 10일경 나스닥에 상장하며, 외국 기업 중 최대 규모의 최초 주식매각을 실시할 예정이다. 이는 미국 시장에 진출함으로써 마이크론 테크놀로지와의 할인 거래 관행을 변화시키고, AI 데이터센터 수요 증가에 따른 고대역폭 메모리칩 시장에서의 경쟁력을 강화하기 위한 전략이다. 현재 SK하이닉스는 향후 12개월 예상 실적의 6.2배로 거래되고 있으며, 지난 12개월 동안 한국 상장 주식과 마이크론 주식은 각각 약 700% 상승해 시가총액이 1조 달러를 초과했다. 나스닥 상장 이후 미국 투자자들은 스폰서 없는 ADR에 의존하지 않고도 직접 투자할 수 있게 되며, AI 메모리 사이클의 주요 플레이어에 대한 접근성이 높아질 전망이지만, 수익성의 지속 가능성과 시장 과열 우려는 여전히 주요 쟁점으로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:08'::timestamp,'2026-07-27 17:12:52.081065'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1566,3494,'삼성전자는 2024년 2분기 잠정 매출 171조 원, 영업이익 89.4조 원을 기록하며 역대 최대 실적을 달성했다. 이는 반도체 수요 증가와 HBM·LTA 등 신기술 적용, 파운드리 부문의 적자 폭 감소 등이 주요 원인으로 분석된다. 그러나 실적 발표 후 주가는 전 거래일 대비 6.92% 하락한 29만6000원에 마감했으며, 장중에는 10% 가까이 급락하는 등 투자자들의 불안감이 컸다. 현재 삼성전자의 주가 하락은 실적과의 괴리감과 함께 SK하이닉스의 나스닥 ADR 상장 추진, 시장의 레버리지 ETF 협의 등 시장 구조 변화가 반영된 것으로 보이며, 향후 증시 흐름과 기업의 주주환원 정책이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:21'::timestamp,'2026-07-27 17:09:31.209451'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1567,3507,'배재고등학교는 2024년 7월 6일 전국 고교야구대회에서 광주제일고등학교를 향해 ''스타벅스 가야지''라는 조롱성 구호를 외쳐 논란을 일으켰다. 이는 스타벅스 코리아의 ''5·18 탱크데이'' 이벤트와 연관된 것으로, 지역 비하 논란으로 이어졌으며, 대한야구소프트볼협회(KBSA)는 배재고에 전국대회 출전정지 6개월 징계를 부과했다. 서울시교육청은 7일부터 8월 말까지 배재고 전체 학생을 대상으로 역사·인권교육과 차별·혐오 표현 방지교육을 실시하며, 민주시민교육과 전문 인력을 파견해 진행한다. 배재고는 재심 신청 기한인 8일까지 논의 중이며, 재심 절차는 최소 2개월 이상 소요될 전망이며, 사과와 국립 5·18민주묘지 참배도 완료했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:26'::timestamp,'2026-07-27 18:56:03.399394'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1568,3514,'보건복지부는 2026년 7월 7일 ''제3차 지역·필수·공공의료 추진전략 중앙·지방 협의체'' 회의를 개최해 내년 3월 시행 예정인 지역필수의료법 하위법령과 2027년 1월부터 운영되는 지역필수의료특별회계의 추진 방향을 논의했다. 이 회의는 지역필수의료법이 2026년 3월 공포된 이후, 중앙정부와 17개 시도, 권역책임의료기관이 지역 간 의료격차 해소를 위해 협력하는 임시 기구로, 특별회계는 수도권에서 멀수록 더 지원하고 공공의료 우선, 지역 주도 원칙에 따라 운영된다. 특별회계는 안정적인 재정 기반을 마련해 필수의료 접근성 향상에 기여하며, 현재 시도와 권역기관의 투자 수요를 반영해 예산 편성과 사업 구체화를 진행 중이다. 복지부는 이번 회의에서 제기된 의견을 반영해 하위법령을 보완하고 조속히 입법예고를 진행할 계획이며, 지역완결적 의료체계 구축을 위한 정책 체계의 유기적 연계를 강화할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:33'::timestamp,'2026-07-27 18:46:00.041024'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1569,3831,'홍명보 감독이 이끄는 한국 축구대표팀은 2026 북중미 월드컵 조별리그에서 3승 1무 1패로 승점 4점에 그치며 32강 진출에 실패했다. 이는 JTBC와 KBS가 각각 185억 원, 180억 원의 광고를 완판한 한국전 3경기 이후 발생한 결과로, 이후 한국이 출전하지 않는 경기에서의 광고 수익 가능성에 불확실성이 커졌다. JTBC는 중계권료 1900억 원, KBS는 재판매 중계권료 140억 원을 지출했으며, 네이버도 온라인 중계권을 확보한 상태다. 문체부 최휘영 장관과 송영길 더불어민주당 의원은 대표팀 탈락을 계기로 대한축구협회의 책임과 구조적 문제를 지적하며 개혁 필요성을 제기했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:39'::timestamp,'2026-07-27 16:16:45.706888'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1570,3517,'2026년 7월 7일, 고용노동부는 홈플러스의 임금체불 사태에 대응하기 위해 ''홈플러스 사태 임금체불 TF''를 가동했다. 이는 지난 3월부터 5월까지 발생한 임금체불에 대해 전수조사를 실시하고, 사측을 형사입건한 후 3~5월 임금은 체불 시정을 완료한 것으로 확인됐다. 그러나 6월 임금은 지급일인 21일을 넘겨도 지급되지 않았으며, 퇴직자에 대한 퇴직금 지급도 자금 부족으로 지연되고 있다. 노동부는 6월 임금 및 퇴직금 지급 조사와 함께, 회생절차 폐지 결정 후 14일 이내 항고 여부에 따라 파산 여부가 결정될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:44'::timestamp,'2026-07-27 18:43:18.671330'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1571,3519,'2026년 7월 7일 서울중앙지법은 대상, 사조CPK, CJ제일제당 등 3개 제조사와 관련 임직원, 전분당협회장 등 총 24명에 대한 첫 재판을 진행했다. 이들은 2017년 7월부터 2024년 10월까지 약 8년간 전분당 제품 가격을 담합해 총 10조1520억원 규모의 시장 왜곡을 초래했으며, 전분 가격은 최고 73.4%, 당류 가격은 최고 63.8% 인상된 것으로 확인됐다. 각 업체는 담합 사실을 인정했으나 대표이사들에게 보고하지 않았거나 승인받지 않았다고 주장하며 법인 책임을 회피하려는 태도를 보였고, 공정거래위원회는 이들 4개 업체에 총 7476억원의 과징금을 부과했다. 다음 재판은 8월 25일 공판준비기일로 진행되며, 삼양사는 이번 기소 대상에서 제외됐고, 담합 주도 여부와 법인 책임 소재 등이 주요 쟁점으로 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:05:51'::timestamp,'2026-07-27 18:42:57.806849'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1572,3524,'2026년 7월 7일 광주지검은 장윤기 여고생 살인 사건의 부실 수사와 경찰 유착 의혹을 규명하기 위해 광주광산경찰서 형사과 및 수사팀장 A경감 자택 등 5곳에서 압수수색을 실시했다. 이 사건은 2026년 5월 5일 광주광산구에서 이채원(17세) 양이 장윤기(23세)에 의해 살해된 이후, 수사 과정에서 증거인멸 및 공무상비밀누설 혐의가 제기되며 발생한 것으로, 특히 차량 내 발견된 ''케이블 타이''를 확보하지 않은 점과 영상 삭제 지시 등이 핵심 의혹이다. 검찰은 A경감과 수사팀 관계자 등 다수를 입건하고, 빌트인 블랙박스 미설치, 증거 인멸 방조 등 혐의를 수사 중이며, 경찰도 전담팀을 구성해 A경감을 긴급체포하고 구속영장을 신청한 상태다. 검찰과 경찰은 동시 수사에 나서며, 형사소송법에 따라 먼저 청구한 기관이 증거 송치요구권을 갖지만, 검찰은 해당 권리를 행사하지 않겠다는 입장을 밝히며 신속하고 공정한 수사를 진행할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:00'::timestamp,'2026-07-27 18:38:04.794796'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1573,3526,'정이한 전 개혁신당 부산시장 후보와 공모 관계에 있는 A씨(30대)에 대해 부산 금정경찰서가 위계공무집행방해 및 공직선거법 위반 혐의로 구속영장을 신청했으며, 8일 부산지법에서 영장심사가 진행된다. 이는 정 전 후보가 4월27일 선거운동 중 승용차에서 뿌려진 음료수를 맞아 뇌진탕 진단을 받았다고 주장한 사건이 자작극 의혹으로 전환된 결과로, 경찰은 선거 다음 날인 4월4일 선거사무소 압수수색과 A씨 휴대전화 포렌식을 통해 사전 통화 기록 등을 확보했다. A씨는 전직 헬스 트레이너로 정 전 후보와 알고 지내던 사이이며, 정 전 후보는 현재 개혁신당을 탈당한 상태다. 영장심사 결과는 8일 저녁에 나올 예정이며, 경찰은 학적 논란, 여론조사 의혹, 부친 계열사 직원 선거운동 동원 등 추가 사안에 대해서도 수사를 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:06'::timestamp,'2026-07-27 18:37:10.436460'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1574,3533,'2026년 6월 3일 지방선거 당시 부산시장 후보였던 정이한 씨가 선거운동 중 음료를 뿌리는 사건을 겪었다고 주장했으나, 이후 경찰이 이 사건을 자작극으로 의심하며 정 전 후보와 관련자 2명에 대해 위계공무집행방해 및 공직선거법 위반 혐의로 구속영장을 청구했다. 사건 발생 후 경찰은 정 전 후보의 선거사무소를 압수수색하고, 음료를 뿌린 30대 남성과 정 전 후보 간의 통화 기록을 확보하며 자작극 의혹을 수사 중이며, 정 전 후보 부친의 회사 계열사 직원들이 선거운동에 동원된 정황도 확인하고 있다. 이에 따라 정 전 후보는 2026년 7월 8일 부산지방법원에서 영장실질심사를 받을 예정이며, 현재까지 음료를 뿌린 남성에 대한 구속 영장은 기각된 상태다. 이후 경찰은 정 전 후보의 학적 논란과 여론조사 의혹 등에 대해서도 수사를 확대하고 있으며, 이 사건은 선거 부정 여부와 정치적 신뢰에 대한 논란으로 확산되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:12'::timestamp,'2026-07-27 18:34:18.718015'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1575,3572,'2024년 5월 6일 서울 배재고등학교 야구부 학생들이 광주제일고등학교를 방문해 5·18을 조롱하는 응원을 한 사건에 대해 공식 사과했다. 이 사건은 역사적 민감성을 무시한 학생들의 행동으로 인해 전남광주지역에서 큰 논란을 일으켰으며, 교육계와 시민사회에서 역사교육의 필요성과 민주시민교육 강화가 요구되었다. 김대중 전남광주교육감은 사과 이후 학생들의 정서적 회복과 학업·운동에의 전념을 당부하며, 과도한 비난과 논쟁을 자제할 것을 요청했고, 교육청은 이번 사례를 교훈 삼아 역사교육과 민주시민교육을 강화할 계획이다. 이후 두 학교 학생 간의 화해와 교류를 통한 교육적 성찰이 이어질 전망이며, 향후 교육과정 내 역사 인식 제고와 지역 간 소통 프로그램 운영이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:17'::timestamp,'2026-07-27 18:23:12.553145'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1576,3600,'더불어민주당은 2024년 10월 2일 출범 예정인 중대범죄수사청과 공소청 운영을 위해 형사소송법 개정안을 전당대회(2024년 10월 17일) 전에 처리할 계획이다. 이는 검찰의 보완수사권 폐지를 포함한 검찰개혁의 핵심 과제로, 현재까지 남은 기간은 약 2개월 반으로, 입법 절차를 빠르게 진행해야 한다는 판단이다. 개정안은 보완수사 기한을 명확히 하고, 경찰의 부실수사에 대비해 수사심의위원회 실질화와 인권보호국 설치를 통해 견제 체계를 강화할 예정이다. 이후 검찰개혁의 속도와 입법 절차의 공정성, 선관위 특검의 추천 방식에 대한 여야 간 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:22'::timestamp,'2026-07-27 18:14:29.871335'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1577,3604,'김민석 전 국무총리는 2024년 12월 계엄 해제 표결 당시 불참 의혹을 제기한 이성윤 민주당 의원의 ''감기약 발언''을 ''대장동 비리 논란과 유사한 정치적 공세''라며 비판했다. 이 의원은 당시 표결에 불참한 김 전 총리가 감기약을 복용했다며 성분을 캐물었고, 이에 대해 김 전 총리는 ''표결 당시 국회 안에 있었다''며 허위 사실 유포로 반박했다. 이에 친청계를 지지하는 박범계 의원도 ''이게 그분 인격이냐''며 비판하며, 친명계도 비슷한 논리로 무소속 한동훈 의원의 행적 캐기와 비교하며 지켜야 할 선을 지적했다. 현재 민주당 내부에서는 당권 경쟁과 함께 이성윤 의원의 발언이 당내 갈등을 부추기며, 향후 당내 정책 방향과 인사 문제에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:28'::timestamp,'2026-07-27 18:09:57.943428'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1578,3605,'구윤철 경제부총리 겸 재정경제부 장관은 7월 말 부동산 세제 개편안을 발표할 예정이며, 보유세와 거래세의 균형을 유지하겠다고 밝혔다. 정부는 실거주자 중심의 주택 시장 정착을 목표로 하며, 국민 의견 수렴을 거쳐 최종 방침을 결정할 계획이다. 3대 메가 프로젝트에 참여하는 지방 근로자에 대해 세금 감면 및 자녀 교육비 지원을 검토하고 있으며, 초기 기반 조성 단계에서는 일시적 지원이 필요하다고 설명했다. 이후 세제 지원의 지속성은 지역 기반 조성 여건에 따라 결정되며, 반도체·인공지능 분야에 대한 R&D 투자 세제 지원과 미래대응기금 조성도 내부적으로 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:32'::timestamp,'2026-07-27 18:01:58.650940'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1579,3608,'이재명 대통령은 2026년 7월 7일 취임 후 처음으로 나토 정상회의 참석을 위해 튀르키예를 방문하며, 세계 평화와 안보에 책임 있게 기여하는 나라로의 전환을 강조했다. 이 대통령은 지난달 G7 정상회의에 이어 나토 무대에서 한국의 역할을 확대하겠다는 의지를 밝히며, 뤼터 나토 사무총장이 한국 방산을 ''환상적''이라고 평가한 점을 언급하며 국민적 자부심을 표현했다. 이번 순방은 15년 만에 이뤄진 한국 대통령의 몽골 국빈 방문을 포함하며, 나토는 2022년부터 아시아·태평양 지역 국가들과의 협력을 강화하기 위해 한국을 포함한 IP4 국가를 정상회의에 초청하고 있다. 이후 이 대통령은 몽골 방문을 통해 양국 관계를 강화할 예정이며, 이번 순방의 성과와 외교적 영향에 대한 국내외 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:40'::timestamp,'2026-07-27 17:57:01.739241'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1580,3609,'이재명 대통령은 2024년 7월 7일 캐나다 차기 잠수함 사업(CPSP) 수주 경쟁에서 최종적으로 패배한 것에 대해 ''기대한 결과는 아니지만, 대한민국의 기술 저력을 국제사회에 다시 한번 입증했다''고 밝혔다. 이는 한국이 과거 독일에서 기술을 배운 이후 현재는 그 원조국과 동등하거나 더 높은 성능을 인정받을 정도로 방위산업 기술이 발전했음을 보여주는 사례로, 세계적인 잠수함 강국들과의 경쟁에서 기술력을 입증한 것으로 평가된다. 이번 경쟁에서 한국은 캐나다 정부의 선택을 존중하면서도, 대통령 비서실장 강훈식이 특사 자격으로 현장을 직접 챙기며 ''방산 원팀''의 역량을 집중한 것으로, 아쉬움이 크다는 반응이 나왔다. 이후 정부는 이번 경험을 바탕으로 기술 고도화와 경쟁력 강화를 위한 정책적 지원을 지속할 예정이며, 향후 국제 방산 시장에서의 입지를 더욱 확대해 나갈 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:46'::timestamp,'2026-07-27 17:53:33.165212'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1581,3612,'이재명 대통령은 6일 청와대에서 열린 민관합동 점검회의에서 삼성전자와 SK하이닉스가 광주 군공항 부지(약 826만 m²)에 반도체 팹 4기를 건설하기로 결정했다고 발표했다. 군공항 부지는 평탄화가 완료된 대규모 부지로 공사 기간 단축이 가능하며, 광주 도심과 KTX역 인접으로 인력 확보와 정주 여건이 우수하고, 도로·공항·항만과의 연계로 물류 접근성도 뛰어나다. 정부는 광주 클러스터의 환경영향평가는 인근 지역 평가 결과를 원용해 기간을 단축하고, 용인 팹 10기 클러스터의 완공 일정도 최대한 앞당기기로 했다. 이후 토지 수용 절차의 병행 추진과 규제 완화, 입법 개선 등이 필요하며, 기후에너지환경부는 광주 클러스터에 대해 기존 평가 결과를 활용할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:52'::timestamp,'2026-07-27 17:38:27.379858'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1582,3613,'2024년 4월 7일, 정보통신망법 개정안에 따라 허위·조작 정보를 고의로 유통한 게재자는 최대 5배의 가중 손해배상 책임을 지게 되며, 2회 이상 반복 유통 시 최대 10억 원 과징금 부과 가능하다. 이는 온라인 공간의 신뢰를 확보하고 불법·허위 조작 정보로 인한 피해를 구제하기 위한 조치로, 정부는 일반적인 의견 표현이나 정치적 주장은 규제 대상이 아니라고 밝혔다. 다만, 허위 조작 정보의 판단 기준이 모호해 표현의 자유 침해 우려가 제기되며, 한국기자협회는 명확한 판단 절차와 보호 장치 마련을 요청했다. 여야는 법 시행을 두고 논쟁을 벌였으며, 국민의힘은 ''입틀막법''이라며 비판했고, 더불어민주당은 악의적 허위 정보에만 집중하는 ''핀셋 규제''라고 반박했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:06:57'::timestamp,'2026-07-27 17:38:44.024297'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1583,3615,'정부는 6일 광주 군공항 부지를 호남권 반도체 클러스터의 핵심 부지로 결정하며, 삼성전자와 SK하이닉스의 총 800조 원 규모 팹 4기 건설을 추진한다. 광주 군공항은 약 826만 m²(250만 평) 규모의 국유지로 평탄화가 완료되어 공사 기간 단축이 가능하며, 광주 도심과 KTX 역 인접으로 인력 확보와 정주 여건이 우수하다는 점이 장점으로 꼽혔다. 반도체 클러스터 조성에 따라 전력(6.3GW 필요)과 용수(하루 65만 톤) 확보가 과제로 남아 있으며, 정부는 신규 원전, 변전소 신설, 하수 재이용 등을 통해 공급을 확보할 계획이다. 군공항 이전은 10월 주민투표를 거쳐 11월 무안군 망운면을 최종 확정할 예정이며, 이에 따라 공군 제1전투비행단 이전과 탄약고 재배치, 안보 공백 우려 등이 후속 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:05'::timestamp,'2026-07-27 17:37:51.063694'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1584,3617,'국민의힘과 더불어민주당은 2024년 5월 6일 정보통신망법 개정안 시행을 하루 앞두고 정면 충돌했다. 개정안은 허위조작정보를 포함한 불법정보에 대한 규제를 확대하고, 혐오·조롱 정보를 고의로 반복 유포한 경우 최대 5년 이하 징역 또는 5000만 원 이하 벌금을 부과하도록 했다. 국민의힘은 이 법을 ''입틀막법''이라며 위헌성과 표현의 자유 침해를 주장하며 검은색 마스크 착용으로 항의했고, 민주당은 허위정보 피해자 보호를 위한 방어벽이라며 법의 필요성을 강조했다. 이후 민주당은 ''일베금지법''을 포함한 추가 제재 강화안을 추진할 예정이며, 여야는 이 법의 시행 유예와 재개정 논의를 놓고 추가 논쟁을 예고했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:11'::timestamp,'2026-07-27 17:39:19.867798'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1585,3618,'김민석 전 국무총리는 6일 광주와 서울에서 각각 기자회견을 열고 더불어민주당 당대표 출마를 공식 선언하며, 정청래 전 대표의 ''자기 정치''를 직접 비판하며 당정 협력의 혼선을 지적했다. 그는 공천의 일관성 부족, 합당 추진과 검찰개혁 과정에서의 숙의 부족, 6·3 지방선거 공천 잡음 등을 문제 삼으며, 당원 주권과 1인 1표제를 자신의 오랜 지론으로 강조했다. 친청계 의원들은 김 전 총리가 계엄 해제 국회 표결에 불참한 점을 문제 삼으며 ''시대착오적 발언''이라며 반격했고, 김 전 총리는 계엄 위험을 사전에 경고한 인물이라며 반박했다. 송영길 전 대표는 8일 출마 선언을 예정하고 있으며, 2030세대의 정치 참여를 강조하며 당대표 선거에 진입할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:18'::timestamp,'2026-07-27 17:39:04.359703'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1586,3620,'민주당은 2026년 1월 6일 보완수사권 전면 폐지를 전당대회 전에 처리할 방침을 밝혔으며, 김한규 원내정책수석부대표는 이를 재논의할 사항이 아니라고 강조했다. 이는 8·17 전당대회를 앞두고 당내 지도부가 보완수사권 폐지에 대한 이견을 차단하기 위한 것으로, 김민석·송영길·정청래 등 당권 주자들 간 공방이 벌어지는 상황에서의 결정이다. 대검찰청은 이에 대해 ''심각한 우려''를 표명하며 의견서를 제출할 예정이며, 일부 의원들은 경찰 기소 의견 송치 사건에 한해 보완수사 허용을 제안하며 보완책 마련 필요성을 제기하고 있다. 이후 형사소송법 개정안은 국회 법제사법위원회에서 심사될 예정이며, 검찰과의 갈등과 제도적 대안 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:23'::timestamp,'2026-07-27 17:37:32.998644'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1587,3623,'캐나다 정부는 2024년 7월 7일(한국 시간) 노바스코샤주 핼리팩스에서 열린 발표를 통해 차기 잠수함 사업(CPSP) 우선협상대상자로 독일의 티센크루프마린시스템스(TKMS)를 선정했다. CPSP는 2030년대 중반 퇴역 예정인 빅토리아급 잠수함 4척을 대체하기 위한 최대 12척의 신형 디젤 잠수함 도입 사업으로, 건조 및 30년간 유지보수·운영(MRO) 비용을 포함해 최대 60조 원 규모다. 독일 TKMS는 사업 기간 동안 캐나다 GDP에 860억 달러 추가 기여와 65만 개 이상의 고용 창출을 약속하며, 나토 동맹국으로서의 상호 운용성과 안보 협력 강화를 내세워 수주에 성공했다. 한국의 한화오션은 민관 협상팀을 구성해 1월과 6월 두 차례 캐나다를 방문했으나, 지정학적 고려와 반대급부 투자 등 절충 조건에서 밀려 수주 실패했으며, 향후 캐나다 정부의 공식 발표와 후속 절차가 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:30'::timestamp,'2026-07-27 17:38:06.830213'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1588,3625,'이재명 대통령이 7일부터 11일까지 나토 정상회의 참석과 함께 15년 만에 한국 대통령으로서 몽골을 국빈 방문하는 가운데, 지난해 8월 주몽골 한국대사관을 찾아 귀순 의사를 밝힌 북한 사회과학원 대표단 통역관의 국내 귀국 절차가 1년 가까이 지연되고 있다. 이 통역관은 북한과 몽골의 전통적 우호 관계를 고려해 몽골 정부의 협조가 필요했으나, 북한 측 반발로 인해 국내 귀국 절차가 지연된 것으로 알려졌다. 현재까지 통역관의 귀국 절차는 완료되지 않았으며, 북한은 주몽골 대사를 교체했다는 보도도 있으나, 실제 교체 여부는 확인되지 않았다. 이재명 대통령은 몽골 대통령과의 정상회담에서 남북 관계 복원을 위한 대화 중재를 요청할 것으로 보이며, 한반도 평화와 안정, 신뢰 구축 방안을 논의할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:35'::timestamp,'2026-07-27 17:39:39.254875'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1589,3631,'국민의힘 장동혁 대표가 6일 최고위원회의에서 당헌·당규 개정을 통해 제명된 당원의 복당을 영구 금지해야 한다고 발언하며 당내 갈등이 고조됐다. 이는 6·3 지방선거 국면에서 접수된 70여 건의 징계 요청서 심사에 앞서, 친한동훈계와 개혁그룹 의원들에 대한 징계 논의가 본격화되면서 발생한 것으로, 특히 조경태 의원의 민주당 후보 지지 의혹과 관련해 징계 필요성이 제기됐다. 현재 윤리위원회는 비공개 회의를 통해 징계 요청서를 검토 중이며, 지난 4개월 만에 재가동됐으나 아직 결론을 내리지 못했고, 징계 기준의 명확화와 절차적 무결성 확보가 요구되고 있다. 당내에서는 징계 정치의 부작용을 우려하는 목소리와 함께 기강 확립 필요성을 강조하는 반응이 공존하며, 향후 징계 기준과 절차에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:42'::timestamp,'2026-07-27 17:16:56.224142'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1590,3635,'이병태 규제합리화위원회 부위원장이 2026년 4월 6일 청와대의 사퇴 권고에 따라 사임했다. 그는 4월 4일 SNS에서 ''5·18 민주화운동이 성역이 됐다''는 발언을 하며 논란을 일으켰고, 이는 배재고 야구부의 ''스타벅스 응원구호'' 논란과 연결되며 정치적 공방으로 확산됐다. 청와대는 해당 발언을 ''부적절한 발언''으로 판단하고 공개 경고를 내렸으며, 여권 내에서도 사퇴 촉구가 이어졌다. 이 부위원장은 사퇴 이유로 표현의 자유와 사회적 유연성의 중요성을 강조하며, 성역 강요를 경계하는 민주주의적 자세를 유지하겠다는 입장을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:48'::timestamp,'2026-07-27 17:10:29.034597'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1591,3636,'20대 남성 이 모 씨는 지난해 12월 어머니를 둔기와 흉기로 공격해 숨지게 한 혐의로 서울남부지법에서 존속살해罪로 징역 12년을 선고받았다. 재판부는 이 씨가 조현병으로 인한 심신미약 상태에서 범행을 저지른 것으로 보이며, 범행을 인정하고 전력이 없어 양형에 반영했다고 설명했다. 범행 당시 이 씨는 환청과 과대망상을 경험했으며, 정신감정 결과 치료가 필요하고 재범 위험이 있는 것으로 판단됐다. 검찰은 징역 15년을 구형했고, 이 씨는 10년간 위치추적 전자장치 부착과 치료감호도 명령받았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:07:55'::timestamp,'2026-07-27 18:53:42.335768'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1592,3681,'성수전략정비구역 4지구 재개발사업 시공사로 롯데건설이 5일 조합원 투표를 통해 최종 선정됐다. 이전까지 롯데건설이 제안한 최저 이주비 20억 원 조건은 입찰 지침 위반 소지가 있다는 이유로 성동구청과 대우건설의 반발을 받았으며, 조합은 이를 최종 제안서에서 삭제했다. 최종 투표 결과 조합원 753명 중 620명이 참여해 롯데건설이 449표, 대우건설이 169표를 얻어 승리했으며, 공사비는 약 1조3628억 원 규모다. 이후 시공사 선정 과정에서 조합의 절차적 중립성과 정보 공개 문제 등이 제기되며, 계약 이행과 조합 운영의 신뢰 회복이 향후 과제로 남았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:01'::timestamp,'2026-07-27 18:57:13.219192'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1593,3644,'경기도는 3일부터 5일까지 수원KT위즈파크에서 열린 ''경기도-KT위즈 브랜드 협업'' 행사에서 현장 여론조사를 실시한 결과, 도민이 가장 바라는 정책으로 ''내 집 걱정 없는 경기''가 520표(41.6%)로 1위를 차지했다. 이는 주거 안정을 위한 정책 수요가 높은 상황을 반영하며, 도민의 주거 부담 해소를 위한 정책 우선순위가 강조된 것으로, 이는 추미애 경기도지사가 취임식에서 강조한 ''대청마루'' 소통 철학과 일치한다. 조사 대상은 행사장에 방문한 1200여 명으로, ''출퇴근이 편한 경기''(22.4%), ''일자리가 늘어나는 경기''(19.2%) 등이 뒤를 이었다. 경기도는 온라인 여론조사 신규 패널 모집도 병행하며, 만 14세 이상 경기·서울·인천 거주자라면 누구나 누리집을 통해 참여 가능하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:06'::timestamp,'2026-07-27 18:29:14.119939'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1594,3656,'2024년 5월 1일 서울 강동구 배재고등학교 정문 앞에 정치적 항의를 표시하기 위해 근조화환이 줄지어 놓인 사건이 발생했다. 이는 지난 4월 29일 제81회 청룡기 전국고교야구선수권대회에서 배재고 야구부원이 ''스타벅스 가야지''라는 구호를 외친 것이 논란이 되었고, 이는 스타벅스 코리아의 ''5·18 탱크데이'' 이벤트와 연결되며 사회적 비판을 불러일으킨 데서 비롯됐다. 이후 배재고 선수들은 5월 6일 광주제일고를 찾아 사과했으나, 이 사건을 계기로 학교 앞에 근조화환이 배치되며 혐오 표현의 일상화에 대한 우려가 제기됐다. 가수 하림은 인스타그램을 통해 근조화환을 ''오프라인 댓글''에 비유하며 정치적 혐오의 수단으로의 변질을 비판하고, 아이들의 정서적 피해와 사회적 감정의 메말라짐을 우려하며 아름다움과 품격을 회복할 필요성을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:13'::timestamp,'2026-07-27 18:21:06.335615'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1595,3658,'제주지역 한 어린이집의 교사 A씨와 운전기사 B씨가 지난 6월 15일 통학버스에 원아 1명을 약 45분간 방치한 혐의로 아동복지법 위반(아동학대)으로 불구속 입건됐다. 사건은 어린이집 교사와 기사가 버스를 운행한 후 원아가 잠든 상태로 뒷좌석에 남아 있음을 인지하지 못한 데서 발생했으며, 당시 시간에 쫓겨 점검을 소홀히 한 것으로 전해졌다. 아이는 건강에 이상이 없었으나, 경찰은 정확한 사건 경위를 조사 중이며 어린이집 측도 관리 소홀을 인정하고 있다. 이후 제주경찰청은 사건에 대한 추가 조사를 진행하고 있으며, 관련 기관은 어린이집 통학버스 운영 절차의 개선 필요성을 제기하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:19'::timestamp,'2026-07-27 18:17:18.434867'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1596,3674,'6·3 지방선거 투표용지 부족 사태를 수사하는 검경 합동수사본부(합수본)는 7일 인쇄업자 1명과 송파·강남·관악·서대문·강서·중랑·마포·서초구 선관위 관계자 총 9명을 참고인 신분으로 소환했다. 이들은 투표용지 부족 상황의 발생 시점, 상급 기관과의 소통 여부, 대응 지침 준수 여부 등을 조사 대상이 됐으며, 인쇄업자는 인쇄 과정에 대한 진술을 요구받았다. 합수본은 지난달 11일 중앙선관위 및 서울시·구 선관위 7곳에 압수수색을 실시했고, 24일에는 서울시·송파구 선관위 관계자 12명의 휴대전화를 확보한 바 있다. 이후 인사·예산 전담팀을 구성해 선관위 채용 비리 및 외유성 출장 의혹 수사도 진행 중이며, 노태악 전 중앙선관위원장 부부의 해외 출장 의혹도 조사 대상에 포함됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:28'::timestamp,'2026-07-27 17:56:22.965047'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1597,3679,'2024년 7월부터 2025년 2월까지 HD현대오일뱅크와 SK에너지 등 4대 정유사가 기름값을 사전 공유하고 가격을 인상하는 방식으로 담합한 혐의로 서울중앙지검이 법인과 임직원을 기소했다. 이는 국내 단일 담합 사건 중 역대 최대 규모로, 특히 2025년 2월 28일 이란 전쟁 발발 직후 국내 기름값이 급등한 배경에 국제 정세 외에도 정유사들의 담합이 영향을 미쳤다는 점이 드러났다. 담합에 연루된 기업들의 거래 규모는 총 26조 원에 달하며, HD현대오일뱅크와 SK에너지의 담합 규모는 14조2000억 원으로 추산됐다. 검찰은 관련 법인과 법무실장, 영업부문장 등에 대해 공정거래법 위반 혐의로 기소했으며, 향후 재판과 함께 불공정 거래에 대한 제도적 개선 방안이 논의될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:34'::timestamp,'2026-07-27 17:36:57.886969'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1598,3698,'삼성전자는 2024년 2분기(4~6월) 연결 기준 영업이익 89조4000억 원을 기록하며, 전 세계 민간 기업 중 분기 영업이익 최대 기록을 달성했다. 이는 전년 동기 대비 영업이익 1810.26% 증가한 것으로, 엔비디아의 이전 기록(약 81조6852억 원)을 넘어선 수치이며, 아람코(2022년 2분기)를 제외한 모든 국영·민간 기업을 앞선 것이다. 영업이익에는 반도체 부문 특별성과급 충당금 약 17~19조 원이 포함되어 있어, 실제 이익은 최소 106조 원을 초과했으며, 2분기 동안 하루 평균 약 9800억 원의 영업이익을 냈다. 증권가들은 올해 삼성전자의 연간 영업이익을 360조~388조 원으로 전망하며, 반도체 호황이 내년까지 지속될 것으로 보고 있으며, 분기 100조 원 이상의 실적이 1년 이상 지속될 가능성도 제기하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:40'::timestamp,'2026-07-27 18:34:04.541728'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1599,3703,'서울 용산구 서계동 33번지 일대 서계통합구역 재개발 사업의 시공사 선정 절차가 올해 말에서 내년 초 본격화될 전망이다. 이 사업은 지하 3층~지상 39층, 20개 동, 2937세대 규모로 조성되며, 사업비는 약 1조 원으로 추산된다. GS건설은 조합 설계사 선정 이후 설계합동사무소를 개설하고 글로벌 설계사 SMDP와 협업하며 맞춤형 설계안을 검토하고 있으며, 성수전략정비구역 1지구 수주 경험을 바탕으로 전담 팀을 투입하는 등 사전 경쟁을 강화하고 있다. 현재는 입찰 지침이 공개되지 않아 정확한 수주 전망은 불투명하지만, 삼성물산, 대우건설 등 주요 건설사들의 관심이 높아지고 있으며, 공사비, 금융 조건, 이주 지원, 사업 기간 등 다양한 요소가 경쟁의 초점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:48'::timestamp,'2026-07-27 18:28:50.659698'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1600,3705,'7일 코스피는 장중 5% 이상 급락하며 매도 사이드카가 발동됐고, 삼성전자의 2분기 잠정 영업이익 89조4000억 원(실질적 106조5000억 원) 발표에도 불구하고 주가는 전일 대비 6.84% 하락하며 29만6500원에 거래됐다. 이는 시장의 기대를 상회하는 어닝 서프라이즈였으나, 실적 발표 후 차익 실현 매물이 쏟아진 ''셀온 현상''과 외국인의 1조5670억 원 순매도가 주가 하락을 주도했다. 이날 오전 11시 2분 기준 코스피는 전일 대비 4.7% 하락한 7672.10에 거래되며, 개인은 1조5590억 원 순매수를 기록했으나 외국인의 매도 압력이 지속됐다. 향후 증시의 단기 흐름은 셀온 물량 출회 여부와 반도체 업황 회복 가능성, 그리고 추격 매수세 유입 여부에 따라 좌우될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:08:54'::timestamp,'2026-07-27 18:26:55.956903'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1601,3710,'2026년 7월 7일 오전 10시23분, 코스피200 선물 가격이 전일 대비 5% 이상 하락하면서 코스피 매도 사이드카가 발동됐다. 이는 올해 16번째로, 사이드카는 프로그램 매도호가의 효력을 5분간 정지시키는 조치다. 발동 당시 코스피는 전일 대비 132.13포인트(1.64%) 하락한 7919.20에 개장했으며, 장중 4% 이상 급락한 후 오전 10시28분 현재 407.70포인트(5.06%) 상승한 7643.63를 기록했다. 이후 시장 안정화를 위한 추가 조치와 향후 시장 감시 강화 방안이 논의되고 있으며, 한국거래소는 시장 메커니즘의 안정성 확보를 위한 절차를 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:01'::timestamp,'2026-07-27 18:20:15.590197'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1602,3853,'강북구는 2026년 6월 26일 열린 ''장애인 건강보건 통합성과대회''에서 보건복지부 장관상을 수상하며 2023년부터 2026년까지 4년 연속 장애인 건강보건관리사업 우수기관으로 선정됐다. 이는 2023년 수유보건지소 개소 이후 지역사회 중심의 재활서비스 확대와 발달장애인·시각장애인 등 대상자 확대, 유관기관과의 협력체계 구축 등 지속적인 정책 시행 결과다. 현재까지 재가 장애인 대상 방문재활서비스를 운영하며 근력 강화, 그룹운동, 요가 등 맞춤형 프로그램을 제공하고 있으며, 의료·복지자원 연계를 통한 통합 지원 체계가 정착된 상태다. 정창수 강북구청장은 앞으로도 의료·복지기관 협력을 강화하고, 맞춤형 서비스를 확대해 장애인의 삶의 질 향상을 목표로 하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:06'::timestamp,'2026-07-27 16:22:51.197440'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1603,3714,'삼성전자는 2026년 7월 7일 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 시장 컨센서스를 크게 웃도는 ''어닝 서프라이즈''를 달성했다. 이는 인공지능(AI) 메모리 수요 증가와 고대역폭메모리(HBM) 납품 확대, 특히 엔비디아향 HBM4 첫 납품으로 인한 반도체 경쟁력 회복이 주요 원인이다. 실적 발표에도 불구하고 주가는 단기 차익실현으로 6%대 하락세를 보였으나, 증권가들은 이를 ''매수 기회''로 평가하며 목표주가를 50만원에서 59만원까지 상향 조정했다. 향후 하반기 메모리 업황의 지속적 공급 부족과 연간 잉여현금흐름(FCF)의 50%를 자사주 소각에 활용할 예정인 대규모 주주환원책이 주가 재평가를 이끌 것으로 전망된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:16'::timestamp,'2026-07-27 18:13:02.998565'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1604,3715,'삼성전자는 2024년 2분기 연결 기준 매출 171조 원, 영업이익 89조4000억 원을 기록하며 역대 최대 분기 실적을 달성했다. 이는 전년 동기 대비 영업이익이 1810.3% 증가한 것으로, 반도체 슈퍼사이클과 글로벌 인공지능(AI) 투자 확대에 따른 메모리 반도체 수요 증가로 인한 가격 강세가 주요 원인이다. 반도체 부문(DS)의 영업이익만 88조 원 수준으로 추산되며, 이는 전년도 전체 영업이익(43조6011억 원)의 2배를 초과한 수치이며, 글로벌 기업 중에서도 엔비디아의 이전 최고 기록(약 81조8000억 원)을 7조4000억 원 웃도는 수준이다. 업계는 반도체 호황이 최소한 내년까지 지속될 것으로 전망하며, 삼성전자의 고성장이 지속될 경우 추가적인 투자 및 생산 능력 확대가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:22'::timestamp,'2026-07-27 18:12:40.914200'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1605,3736,'2024년 3월 이란 전쟁 격화 직후 국내 정유사 4곳 중 HD현대오일뱅크와 SK에너지가 가격 담합을 통해 휘발유 가격을 일주일 만에 약 40% 폭등시킨 혐의로 서울중앙지검이 기소했다. 검찰은 전쟁이라는 국제적 위기 상황을 이윤 추구 기회로 삼아 만성적 담합 관행이 노골화됐으며, 원유 비축 상태에서도 가격을 인상해 폭리 행위를 저질렀다고 밝혔다. 담합 규모는 기소된 두 회사 기준 14조2000억 원으로 추정되며, 전체 4대 정유사 포함 시 26조 원에 달하며, 정부에 허위 가격 보고도 확인됐다. SK에너지는 자진신고자 감면제도(리니언시)를 적용받아 기소 면제를 받았고, GS칼텍스와 에쓰오일은 증거 부족으로 기소 대상에서 제외됐으며, 재판에서 사실관계 소명이 예정돼 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:29'::timestamp,'2026-07-27 17:37:14.549968'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1606,3740,'미국은 2024년 7월 7~8일 튀르키예 앙카라에서 열리는 나토 정상회의에서 유럽 동맹국들의 국방비 증액 이행 상황을 점검하고, 수십억 달러 규모의 미국산 무기 계약을 추진할 예정이다. 2023년 헤이그 정상회의에서 유럽 국가들은 2035년까지 국방비를 GDP 대비 5%로 늘리기로 합의했으나, 폴란드, 북유럽, 발트해 국가들은 앞서 나가고 있으며 독일도 2029년까지 목표 달성 계획을 추진 중인 반면, 다수 국가는 여전히 뒤처져 있다. 이번 회의에서는 이란 전쟁 발발 후 호르무즈 해협 군사작전 참여를 둘러싼 미국과의 갈등 해소도 주요 의제로, 미국은 유럽 동맹국들의 방위비 증액을 자국 무기 수출 기회로 활용할 전략을 추진하고 있다. 이재명 대통령은 일본, 호주, 뉴질랜드와 함께 나토 정상회의에 처음 초대받아 세계 국방비의 55%를 차지하는 나토 회원국들을 대상으로 방산 수출 외교를 펼칠 예정이며, 이는 한국 방산 산업의 해외 진출 기회로 작용할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:37'::timestamp,'2026-07-27 17:39:57.389512'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1607,3744,'2026년 7월 4일 베네수엘라 북부 라과이라주에서 발생한 규모 7.2와 7.5의 연쇄 강진으로 인해 붕괴된 건물 잔해에 갇혀 있던 생존자 4명이 지진 발생 267시간 만에 구조됐다. 이들은 지난달 24일 오후 6시에 발생한 지진 이후 어린이 2명, 여성 1명, 남성 1명이 잔해 속에서 생존하며 S.O.S 신호를 남긴 것으로 확인됐다. 구조된 4명은 현장에서 응급처치를 받은 뒤 병원으로 이송돼 치료를 받고 있으며, 이번 지진으로 현재까지 최소 3342명이 사망하고 1만6700명이 부상한 것으로 집계됐다. 이번 지진은 최근 100여 년간 베네수엘라에서 발생한 가장 큰 인명 피해를 낸 재난으로 평가되며, 정부는 수색 및 복구 작업을 지속하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:44'::timestamp,'2026-07-27 17:34:33.163236'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1608,3757,'트럼프 행정부는 2024년 7월 7~8일 튀르키예 앙카라에서 열리는 나토 정상회의에서 유럽 동맹국들의 국방비 증액 약속 이행 여부를 점검하고, 수십억 달러 규모의 미국산 무기 판매 계약을 추진한다. 2023년 헤이그 회의에서 유럽 국가들은 2035년까지 국방비를 GDP 대비 5%로 늘리기로 합의했으나, 폴란드, 북유럽, 발트해 국가들은 앞서 나가고 독일도 2029년까지 목표 달성 계획을 추진 중이며, 다른 많은 국가들은 여전히 이행이 미흡한 상태다. 트럼프 행정부는 국방비 증액을 미국 무기 수출 기회로 활용하며, 이번 회의에서 수조 원 규모의 무기 세일즈 계약이 예상되며, 이란 전쟁 발발 후 호르무즈 해협 군사작전 참여 요청에 대한 갈등 해소도 주요 의제로 다뤄질 전망이다. 한편, 이재명 대통령은 일본, 호주, 뉴질랜드와 함께 나토 정상회의에 처음 초대되어 방산 수출 외교를 펼칠 예정이며, 나토 회원국들의 국방비 지출 현황과 무기 구매 의향에 대한 실질적 반응이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:09:52'::timestamp,'2026-07-27 16:55:41.286568'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1609,3766,'러시아는 6일(현지시간) 우크라이나 수도 키이우 일대에 미사일과 드론을 다수 발사해 적어도 6명이 사망하고 18명이 부상했다. 이는 나토 정상회의를 앞두고 러시아가 대규모 공격을 준비하고 있다는 젤렌스키 대통령의 경고와 일치하며, 지난 2일에도 키이우에 드론 496기와 미사일 74발 이상을 발사한 바 있다. 공격으로 키이우 시내 주거 및 비주거 건물 다수 파괴되고 정전이 발생했으며, 시민 수천 명이 지하 대피소로 대피하는 등 민간 피해가 심각하다. 젤렌스키 대통령은 패트리엇 방공 미사일 공급 지연을 문제 삼으며 미국과 유럽의 추가 지원을 촉구했고, 러시아가 점령했다고 주장한 도네츠크주 코스티안티니우카에서 전투가 계속되고 있다고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:01'::timestamp,'2026-07-27 16:52:01.532307'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1610,3770,'2026년 7월5일 이진숙 국민의힘 의원이 배재고등학교 야구부 학생들의 5·18 민주화운동 비하 발언을 비판하며 응원 화환을 보낸 것이 논란이 되었다. 이 의원은 5·18 민주화운동을 폄훼한 글에 ''좋아요''를 누르고, 국회 인사청문회에서 관련 질문에 답변을 회피한 전력이 있어 역사 인식에 대한 의문이 제기되었다. 배재고 학생들은 6일 광주제일고를 찾아 피해 학생과 시민들에게 사과했으며, 두 학교 학생들은 국립 5·18 민주묘지를 함께 참배할 예정이다. 더불어민주당은 이진숙 의원의 화환 보냄을 ''매우 부적절하다''고 비판하며, 정치적 이용을 경계하고 갈등 중재와 상처 치유의 책임을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:06'::timestamp,'2026-07-27 17:24:29.531951'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1611,3776,'2026년 7월5일, 이진숙 국민의힘 의원은 배재고등학교 야구부가 5·18민주화운동을 희화화한 논란 이후 사과를 준비하는 상황에서, 자신이 배재고에 ''스타벅스가 5·18과 무슨 관계냐?'', ''배재고 학생들과 함께합니다''라는 문구가 적힌 화환을 보냈다고 밝혔다. 이는 스타벅스의 ''탱크데이'' 마케팅이 5·18 민주화운동과 박종철 열사 고문치사 사건을 희화화했다는 비판이 제기되며, 스타벅스코리아와 정용진 신세계 회장이 사과한 이후 발생한 사건이다. 이 의원은 이와 함께 광주일고에 폭발물 협박 신고가 접수된 상황에서, 배재고 학생들을 지지하는 메시지를 전달하며 공포에 시달릴 수 있는 학생들에게 힘을 주고 싶다는 입장을 밝혔다. 이후 이 의원의 발언은 정치적 색깔론 논란을 불러일으키며, 과거 윤석열 정부 시절 방통위 위원장 재직 시 극우 성향 유튜브 출연 등으로 공직선거법 위반 혐의를 받은 이력이 재조명되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:14'::timestamp,'2026-07-27 16:37:55.157721'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1612,3785,'2026년 7월 2일, 배재고등학교 야구부가 5·18 민주화운동을 조롱하는 발언으로 인해 6개월간 출전 정지 징계를 받은 후, 학교 앞에 조롱 응원을 하는 화환이 등장하며 논란이 확산됐다. 이는 학생들의 발언이 역사적 아픔을 무시한 것으로, 교사와 코칭 스태프의 인성 및 역사 교육 부재가 원인으로 지적됐으며, 특히 어른들의 방관과 책임 회피가 문제로 지적됐다. MBC, JTBC, MBN 등 주요 방송사 앵커들은 징계의 과도함과 함께 어른들의 책임 회피, 정치적 이용, 학생들의 미래에 미치는 영향을 우려하며 범사회적 대책 필요성을 강조했다. 현재까지도 근조화환과 조롱 화환이 교차하며 갈등이 심화되고 있으며, 교육계와 사회 전반에서 책임 있는 어른들의 자성과 제도적 개선이 요구되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:22'::timestamp,'2026-07-27 16:23:18.715556'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1613,3787,'2026년 7월1일, 대한야구소프트볼협회는 청룡기 전국고교야구에서 광주일고 선수를 조롱하며 ''스타벅스 가야지''라고 외친 배재고 야구부에 출전 정지 6개월을 결정했다. 이는 5·18민주화운동을 비하하는 발언으로 간주되며, 스포츠공정위원회가 학생들의 조롱과 극우성 발언이 반복된 배경에 제재가 부족했음을 지적한 결과다. 징계는 7월2일부터 적용되며, 지도자 및 선수에 대한 추가 징계는 6개월 이내에 스포츠공정위에서 재결정될 예정이다. 국민의힘 일부 인사들은 표현의 자유를 강조하며 징계가 지나치다며 이재명 정권의 사회 갈등 조장과 연결지었으나, 진보당은 사과와 반성의 자세가 우선되어야 한다고 비판하며 교육적 책임을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:29'::timestamp,'2026-07-27 16:21:42.239969'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1614,3791,'전현직 기자들이 취재 과정에서 확보한 정보를 바탕으로 주식을 사고, 관련 기사를 내보낸 뒤 주가 상승 후 매도해 부당이득을 취한 선행매매 및 주가조작 사건이 드러났다. 이들은 ''특징주'' 기사를 내보내기 직전 주식을 매수하고, 기사 노출 후 3초 전 매수, 8초 후 매도하는 방식으로 수억 원의 이익을 거두었으며, 일부는 90억 원 이상의 이득을 취한 것으로 확인됐다. 언론노조는 이에 따라 기자들의 취재 정보를 금융투자에 활용하지 말라는 가이드라인을 제정했고, 이재명 대통령은 관련 기자들에게 자수를 촉구하며 ''취재 정보로 금융투자 안 된다''고 강조했다. 현재 관련 기자들에 대한 수사가 진행 중이며, 언론사들은 자체 감사와 책임 소재 명확화를 위한 조치를 취할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:34'::timestamp,'2026-07-27 16:14:40.075620'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1615,3792,'2024년 6월 19일 서울 마포구 상암동 JTBC 사옥 앞에서 개인 채권 투자자 50여 명이 집회를 열어 중앙그룹 사주 일가의 사재 출연과 개인 투자자 원금 100% 보장을 요구했다. 이들은 JTBC 등 중앙그룹 5개사가 채무불이행을 선언하기 이틀 전까지도 채권을 판매하며 투자자들에게 위험성을 숨긴 것으로 보고, 방만 경영과 정보 비공개를 비판했다. 피해자들은 총 1억 원 이상의 JTBC 채권을 보유하고 있으며, 일부는 전 재산을 투자한 것으로 밝혀졌으며, 회생 절차에서 개인 투자자 보호가 우선시되어야 한다고 주장했다. 이후 법원의 회생 절차와 구조조정 협상 과정에서 개인 채권자 원금 보장과 경영진 사퇴, 사죄가 반드시 이행되어야 한다는 입장문을 JTBC에 전달하며, 향후 절차에 대한 감시를 강화할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:41'::timestamp,'2026-07-27 16:13:08.755103'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1616,3793,'방송미디어통신위원회(방미통위)는 JTBC가 회생절차를 신청한 것과 관련해 2024년 4월 18일 전체회의에서 점검반을 구성하고 상시 모니터링을 시작했다. JTBC는 중앙홀딩스의 파산 가능성과 매각, 최대 출자자 변경 등으로 인해 재무적 위기 상황에 놓였으며, 채무불이행 후 회생신청을 한 것으로 확인됐다. 방미통위는 월드컵 주관 방송사로서 국민의 시청권 보장을 위해 자료 제출 여부, 단기 차입금 만기 현황, 채권자 구성, 계열사 자금 거래 등을 점검하고 있으며, 자율 구조조정, 정식 회생, 신규 투자 유입, 파산 등 다양한 시나리오에 대한 대응 방안을 마련 중이다. 이후 방미통위는 JTBC 대표이사 청문회 개최 여부와 재허가 조건 위반 여부에 대한 시정명령 등 후속 절차를 검토할 예정이며, 특히 월드컵 중계의 차질 없이 진행될 수 있도록 지속적으로 감시할 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:47'::timestamp,'2026-07-27 16:12:44.045995'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1617,3794,'2024년 12월 12일 JTBC의 채무불이행으로 시작된 중앙그룹 유동성 위기가 확산되며, JTBC를 포함한 5개 계열사가 기업회생절차를 신청했다. 이는 콘텐츠 시장 위축과 방송광고 수익 감소, SLL중앙에 대한 IP 매각으로 인한 수익 구조 악화, 계열사 간 재무적 의존 구조 등이 복합적으로 작용한 결과다. 현재 JTBC의 신용등급은 D로 하락했으며, 구성원들은 법인카드 중단과 복지포인트 소멸로 인한 생계 위기와 불안을 겪고 있다. 중앙일보도 워크아웃 추진 중이며, SLL중앙 매각 실패와 함께 회생 절차 내에서의 법적·재무적 대응 방안과 노동조합의 반응, 투자자 집단행동 예고 등 후속 이슈가 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:10:57'::timestamp,'2026-07-27 16:12:29.355384'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1618,3796,'중앙일보는 2024년 3월 15일, 그룹사 5곳(중앙홀딩스, JTBC, 메가박스 등)이 법정관리를 신청한 가운데, 언론의 공적 책무를 유지하기 위해 법원 주도의 법정관리가 아닌 채권단과의 협의를 통한 기업구조개선작업(워크아웃)을 추진한다고 밝혔다. 이는 중앙그룹의 재무 악화와 계열사들의 법정관리 신청으로 인한 리스크 확산을 막기 위한 자구책으로, 중앙일보는 독립 법인으로서 계열사와 경영적 분리 상태를 유지하고 있다. 중앙일보는 2025년 60주년을 맞이하며, 신문 발행과 디지털 콘텐츠 발행을 지속할 계획이며, 지난달 21일 5500억 원 규모의 사옥 매각을 통해 자산 유동화를 추진해 재무 구조 개선을 기대하고 있다. 이후 워크아웃 진행 상황, 채권단 협의 결과, 매각 대금의 활용 방향 및 언론사의 지속 가능성에 대한 후속 절차와 시장 반응이 주목되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:03'::timestamp,'2026-07-27 16:11:09.438036'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1619,3798,'홍정도 중앙그룹 부회장은 2024년 5월 15일 긴급 기자회견을 통해 JTBC 등 계열사의 회생절차 신청을 발표하며 채권자, 주주, 이해관계자에게 세 차례 고개를 숙여 사과했다. 이는 JTBC가 206억 원 규모의 유동화 차입금 상환 실패로 신용등급이 ''CCC''로 하락한 지 이틀 만이며, 콘텐트리중앙의 코스피 거래가 중지되는 등 경영 위기로 이어졌다. 회생 절차 신청으로 인해 계열사들의 법인카드 정지, 임직원의 고용 불안 등 내부 혼란이 발생했으며, 중앙그룹은 북중미 월드컵 중계 등 주요 업무는 정상 운영할 계획이라고 밝혔다. 이후 회생법원의 심문 절차가 진행되며, 재무 평가 포함 재승인 여부와 기업회생 절차의 성패가 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:09'::timestamp,'2026-07-27 16:10:55.785127'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1620,3799,'2024년 5월 15일, 홍정도 중앙그룹 부회장은 JTBC, 콘텐트리중앙, 메가박스중앙, 중앙홀딩스, 중앙피앤아이 등 5개 계열사가 법원에 회생절차를 신청했다고 밝혔다. 이는 누적된 재무 부담과 장기화된 자본시장 경색으로 인해 경영 안정을 유지하기 위한 불가피한 결정으로, 그룹의 본질적 경쟁력과 미디어 콘텐트 산업 생태계를 지키기 위한 선택이다. 회생절차는 기존 경영진이 관리인으로서 영업을 계속하며 채무를 조정하는 제도로, 법원 감독 하에 재무구조 개선과 상장사 거래 정상화를 목표로 하고 있다. 현재 경영진은 법원 및 관계 기관과 협력해 재무 안정화를 추진하며, 임직원들의 업무 흔들림 없이 일상 운영을 유지할 것을 당부하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:14'::timestamp,'2026-07-27 16:10:44.499923'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1621,3800,'이재명 대통령은 2025년 12월 13일 X 계정을 통해 기자들이 특정 주식에 대한 기사를 쓰기 전에 매수해 90억 원의 부당이익을 취한 ''기자 선행매매'' 사례를 언급하며, 관련자들에게 자수를 촉구했다. 이는 금융감독원 특별사법경찰이 2025년 12월 12일 기사 브로커와 현직 기자 등 2명을 구속하면서 드러난 사건으로, 공인회계사 출신 브로커 A씨의 지시 하에 3명의 기자가 2000건 이상의 기사를 작성해 주가조작을 벌인 것으로 조사됐다. 현재 해당 사건은 수사 중이며, 기자와 브로커 등 핵심 피의자들이 구속된 상태로, 기사 작성 전후 주가 변동과 매매 내역이 정밀 분석되고 있다. 이후 정부는 기자들의 부정행위에 대한 처벌 강화와 언론 윤리 제도 개선을 포함한 후속 조치를 검토 중이며, 관련 법적 절차와 제도 개선 논의가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:20'::timestamp,'2026-07-27 16:10:02.078204'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1622,3801,'JTBC는 2026년 6월 12일 유동화차입금 206억 원 중 일부를 상환하지 못해 나이스신용평가와 한국기업평가로부터 무보증사채 신용등급을 각각 BBB/부정적에서 CCC, BBB 부정적에서 BB로 하향 조정받았다. 이는 미르제이차 56억 원과 제일티비씨제이차 150억 원의 상환 불이행 발생으로 인한 유동성 위험 증가와 방송광고시장 위축, 콘텐츠 투자 부담 증가, 당기순손실 누적 및 차입금 증가 등 재무적 악화가 원인으로 분석된다. 단기신용등급도 기업어음과 전자단기사채 모두 A3에서 C로 하향 조정되며, 기업의 적기상환능력에 대한 의문이 제기됐다. JTBC는 방송 콘텐츠 제작과 방영은 정상 운영 중이며, 유동성 위기 극복을 위해 비상경영체제를 가동하고 있으며, 대·내외적 수단을 동원해 최선을 다할 것이라고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:27'::timestamp,'2026-07-27 16:09:54.525089'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1623,3803,'젠슨 황 엔비디아 CEO가 8일 오후 네이버 사옥을 방문해 이해진 네이버 이사회 의장과 회동하며, 기가와트(GW)급 초대형 글로벌 AI 팩토리 구축을 위한 공동 사업을 합의했다. 이는 네이버의 국내 최대 하이퍼스케일 데이터센터 ''각 세종''을 기반으로 2027년 상반기 55MW, 같은 해 100MW, 2028년 200MW 규모로 해외 확장을 통해 글로벌 시장 진출을 추진하는 계획이다. 양사는 2027년까지 1GW급 인프라 구축을 목표로 하며, 엔비디아의 최신 GPU 수십만 장을 수용할 수 있는 규모로, 아시아·태평양을 넘어 유럽·중동 시장까지 공동 진출 방안을 논의했다. 이후 네이버는 엔비디아의 DSX 플랫폼과 자체 GPU 클러스터 기술을 융합하고, ''코스모스'' 모델에 서울 월드 모델 구축을 포함한 공간 인텔리전스 분야 협력을 확대할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:33'::timestamp,'2026-07-27 16:09:03.687851'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1624,3807,'삼성전자 DX 부문 중심의 동행노조는 2026년 임금협상 잠정합의안 찬반투표 중지를 요구하며 26일 수원지법에 가처분 신청을 예고했다. 이는 삼성전자 노사가 지난 20일 공동교섭단을 통해 잠정합의안을 도출한 후, 동행노조가 반도체 부문 중심의 성과급 교섭에 불만을 제기하며 4일 공동교섭단을 탈퇴한 데 따른 것이다. 동행노조는 가입자 수가 1만3000여명으로 증가했으며, 현재 잠정합의안 부결 운동을 벌이고 있으며, 투표는 27일 오전 10시까지 진행된다. 이후 가처분 신청의 법적 심리 여부와 투표 절차의 합법성, 노조 간 협의체 구성 방식에 대한 후속 논의가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:38'::timestamp,'2026-07-27 16:08:31.314810'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1625,3811,'2026년 7월 6일, 조선일보는 배재고등학교 야구부 선수들이 5·18민주화운동을 폄훼하는 구호를 외친 사건을 두고 이병태 전 대통령직속 규제합리화위원회 부위원장의 ''표현의 자유'' 옹호 발언을 사설로 지지하며 갈등을 부추겼다. 이 전 부위원장은 배재고 선수단의 징계를 ''북한의 모습''에 비유하며, 민주당의 압도적 의석수와 계엄 여파로 인한 정치적 독주가 문제라고 주장했다. 조선일보는 이 발언을 옹호하며 표현의 자유가 위태로워졌다고 지적했고, 미디어오늘내일 라이브에서 기자들은 언론의 책임 소재와 사회적 혐오 조장 문제를 지적하며 조선일보의 입장을 묻는다 해도 답변을 받지 못했다. 이후 이병태 전 부위원장은 사퇴했으며, 이 사건은 정치적 정쟁화와 지역 혐오 문제, 언론의 책임성에 대한 논의로 확산되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:45'::timestamp,'2026-07-27 18:38:41.121837'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1626,3814,'2024년 5월 29일 서울 목동야구장에서 열린 청룡기 전국고교야구선수권대회에서 배재고등학교 야구부 학생들이 광주제일고를 향해 ''탱크데이'', ''가야지, 가야지, 스타벅스 가야지'' 등의 혐오 발언을 한 사건에 대해, 배재고는 6일 광주제일고를 방문해 사과했다. 이는 5·18민주화운동을 상징하는 광주를 비하하는 발언으로, 사회적 논란을 일으켰으며, 배재고 감독과 주장은 부적절한 행동에 대해 책임을 인정하고 진심으로 사과했다. 광주제일고는 사과를 수용하며 배재고 학생들에게 ''고개 들고 당당하게 경기를 펼쳐달라''고 화답했고, 선수 대표는 이번 사건을 계기로 야구 활동에서 상처 주는 언행을 자제할 것을 약속했다. 이후 배재고 선수단은 서울시교육감과 함께 국립 5·18민주묘지 참배를 진행하며 사과의 의미를 이어갔으며, 향후 교육청과 학교는 유사한 사건 재발 방지를 위한 교육 프로그램 마련을 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:51'::timestamp,'2026-07-27 18:17:12.051599'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1627,3816,'경기 성남에서 50대 남성이 접근금지 명령을 받은 후 전 연인인 60대 여성을 살해한 사건이 발생했다. 피해자는 스토킹 신고를 여러 차례 했으나, 가해자가 조치를 위반하지 않았고 위험도 평가에서 ''보통''으로 분류되며 경찰이 전자장치 부착이나 구속 처분을 신청하지 않았다. 언론사들은 피해자 보호 실패를 지적하며 전자장치 부착 요건 완화, 접근금지 기간 무기한 확대, 유관기관 간 정보 공유 체계 구축 등 제도 개선을 촉구했다. 한편 7일 시행되는 허위조작정보근절법에 대해 표현의 자유 침해와 전략적 봉쇄소송 우려가 제기되며, 정부는 법 시행 전 보완책 마련을 요구받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:11:59'::timestamp,'2026-07-27 17:23:25.181076'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1628,3819,'방송미디어통신위원회(방미통위)는 6일 KBS 이사 4인, MBC 이사 8인, EBS 이사 8인에 대한 임명 및 임명제청안을 의결했다. 이는 방송법 개정 이후 정치권 외의 다각적 주체가 이사 추천에 참여하는 첫 사례로, 각 방송사별로 방송미디어학회, 변호사단체, 임직원, 시청자위원회, 교육단체 등 다양한 추천 주체가 참여했다. KBS와 MBC, EBS의 이사 임명 제청은 방미통위에서 결정되었으며, 대통령이 최종 임명한다. 현재 국민의힘은 후보 추천을 하지 않아 KBS·MBC·EBS 각각 2명씩 총 6명의 후보 추천이 누락된 상태이며, 방미통위는 추천 지연을 우려하며 빠른 추천을 촉구하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:05'::timestamp,'2026-07-27 17:06:30.289108'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1629,3820,'서울 배재고등학교 야구부 선수들이 6월 29일 목동야구장에서 열린 청룡기 야구대회 중 광주일고를 비하하는 ''스타벅스 가야지''라는 응원구호를 사용해 파문을 일으켰다. 이는 5·18민주화운동을 언급한 것으로 오해될 수 있는 발언으로, 광주 지역의 역사적 상처를 무시한 것으로 비판받았다. 6일 배재고 선수단은 광주일고를 방문해 야구부 주장과 감독이 피해 학생 및 시민에게 직접 사과문을 낭독하며 진심 어린 사과를 했다. 이후 배재고는 교사와 학생 모두가 윤리와 역사 인식의 문제를 반성하며, 관련 기관 조사에 성실히 응하겠다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:10'::timestamp,'2026-07-27 16:56:14.642636'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1630,3822,'내일(7일)부터 정보통신망법 개정안에 따라 허위·조작 정보를 고의로 유포한 언론·유튜버 등에 대해 손해액의 최대 5배 배상 청구가 가능해지고, 대규모 플랫폼 사업자에게 허위조작정보 삭제 및 처리 의무가 부과된다. 이 법은 구독자 10만 명 이상 또는 월평균 조회 수 10만 회 이상 유튜버를 적용 대상으로 명시했으나, 기준의 명확성에 대한 비판이 제기되고 있으며, 허위 정보 판단을 방송미디어통신위원회 산하 사실확인단체가 담당하는 점에서 표현의 자유 침해 우려가 제기되고 있다. 언론계는 법 시행으로 인해 플랫폼의 과잉 삭제 조치와 이용자의 자기 검열이 발생할 수 있으며, 특히 허위 정보 판단 기준의 모호성과 정치적 중립성 문제에 대한 우려를 표명했다. 이후 법의 시행 이후 플랫폼은 6개월에 1회 이상 정보 처리 내역을 공개해야 하며, 허위 정보 판단 기준과 사실확인 단체의 독립성, 신고 제도 남용 방지 절차 등이 후속 논의와 개정의 대상이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:18'::timestamp,'2026-07-27 16:53:11.730916'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1631,3825,'2025년 지방선거에서 국내 거주 외국인의 투표권이 보장되면서 이주민에 대한 혐오보도가 증가한 것으로 분석됐다. 선거 전후 언론보도 분석 결과, 2월1일부터 5월20일까지 외국인과 지방선거를 주제로 한 기사 383건 중 45건이 이주민 혐오로 판단되었으며, 선거운동 기간인 5월21일부터 6월5일까지는 434건 중 6건으로 비중이 감소했다. 그러나 정치인들의 이주민 혐오 발언과 언론의 여과 없는 보도가 부정선거 음모론과 결합되며, 특히 중국계 이주자에 대한 혐중 시위와 연계된 보도가 지속됐다. 인권운동네트워크 바람은 선거관리의 부실과 언론의 구조적 배제를 지적하며, 이주민 혐오보도 감시의 필요성을 강조하며 민주주의와 인권 보장을 위한 모니터링의 중요성을 제기했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:26'::timestamp,'2026-07-27 16:39:26.521725'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1632,3835,'이란군은 20일(현지시간) 미국이 종전 양해각서(MOU) 제1조를 이행하지 않았다며 호르무즈 해협의 선박 통행을 허용하지 않겠다고 밝혔다. 이란은 지난 18일 도널드 트럼프 미국 대통령과 마수드 페제시키안 이란 대통령이 서명한 종전 MOU를 근거로 한 조치로, 이스라엘군의 지속적인 공습이 이란의 결정을 유도한 것으로 보인다. 이로 인해 호르무즈 해협의 해상 운송이 중단되며, 중동 지역의 에너지 수송과 국제 무역에 영향을 미칠 전망이다. 이후 이란은 미국의 약속 이행 여부에 따라 추가 조치를 취할 계획이며, 국제사회는 이에 대한 대응 방안을 논의하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:30'::timestamp,'2026-07-27 16:13:27.819739'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1633,3840,'2026년 퓰리처상은 도널드 트럼프 행정부의 언론 탄압과 검열 행위를 직격한 보도들을 수상자로 선정했다. 트럼프 행정부의 연방 기관 구조조정, 이민 단속, 이해충돌 논란 등에 대한 보도가 공공서비스, 탐사보도, 전국 보도, 지역 보도 부문에서 수상했으며, 특히 워싱턴포스트, 뉴욕타임스, 로이터, 시카고 트리뷴 등이 주요 수상 기관으로 이름을 올렸다. 미국의 언론자유지수는 2026년 RSF 보고서에서 180개국 중 64위로 역대 최저를 기록했으며, 트럼프 행정부의 언론 압박이 주요 원인으로 지적됐다. 이에 따라 퓰리처상 이사회는 ''검열에 반대한다''며 언론자유를 지지하는 입장을 밝히며, 향후 언론 보호 정책과 관련한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:37'::timestamp,'2026-07-27 16:08:27.538277'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1634,3843,'도널드 트럼프 미국 대통령 행정부 기간 동안 미국의 언론자유지수가 180개국 중 64위로 역대 최저를 기록했다. 이는 전년 대비 7계단 하락한 것으로, 2002년 RSF가 지수를 발표한 이후 최저 수준이며, 트럼프 행정부가 비판 언론을 법적·정치적 압박으로 탄압한 것이 주요 원인이다. 언론인 구금, 자금 지원 삭감, 소송 제기, 내부 고발자 위축 등이 지속되며, 특히 ABC 방송사 면허 재검토와 육군 참전 용사 체포 사건이 논란이 되었다. RSF는 미국을 포함한 전 세계 절반 이상 국가가 언론자유지수 ''나쁨'' 또는 ''매우 나쁨''으로 평가받으며, 권위주의, 무능 정치, 온라인 플랫폼 규제 미흡이 주요 원인이라고 지적했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:43'::timestamp,'2026-07-27 16:08:16.579037'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1635,3845,'2024년 5월 25일 오후 8시40분경, 백악관 출입기자협회 주최 만찬에서 도널드 트럼프 미국 대통령이 참석 중 총격 사건이 발생했다. 총격범 콜 토머스 앨런은 범행 전 성명을 통해 행정부 당국자를 표적으로 삼겠다고 밝혔으며, 사건 직후 체포됐다. 언론인들은 대피 대신 현장에 머물며 실시간 속보를 전달했고, 트럼프 대통령은 이에 대해 ''책임감 있는 보도''라며 이례적으로 칭찬하며 언론에 감사를 표했다. 그러나 트럼프 대통령은 동시에 언론에 비판적인 지미 키멀 해고를 요구하는 등 이중적 태도를 보이며, 만찬의 정당성에 대한 논란이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:50'::timestamp,'2026-07-27 16:08:10.815475'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1636,3847,'2024년 1월 25일 워싱턴DC 힐튼호텔에서 열린 백악관 출입기자단 만찬 중 도널드 트럼프 미국 대통령이 총격 사고를 당했으나 사망자는 없었고, 총격범은 31세 콜 토마스 앨런으로 체포됐다. 이 사건은 트럼프 대통령이 반복적으로 폭력 사태에 휘말렸다는 점을 역사적 중요성으로 해석하며, 에이브러함 링컨 전 대통령을 언급하며 자신을 ''영향력 있는 대상''으로 자화자찬했다. 트럼프는 사전에 언론에 대한 강한 비판을 예고했으나, 이번 사건 이후 언론의 책임감 있는 보도를 칭찬하며 태도를 전환했고, 백악관 연회장 보수 필요성을 강조하며 4억 달러 규모의 신축 계획을 재추진할 가능성을 시사했다. 이에 대해 뉴욕타임스는 보안 실패를 지적하며 트럼프 대통령 주변 보안의 충분성에 의문을 제기했고, 국제사회는 정치적 폭력의 정당성 부정을 강조하며 각국 정상들이 메시지를 발표했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:12:58'::timestamp,'2026-07-27 16:08:00.107949'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1637,3850,'서울 노원구는 2024년 7월 22일부터 8월 20일까지 산책로 11곳과 하천변 7곳 총 18곳에서 ''힐링냉장고''를 운영해 무료 냉장 생수를 제공한다. 이는 2020년부터 시행된 폭염 대응 사업으로, 전국 지방자치단체가 벤치마킹한 제도로, 지난해에는 약 228만 병의 생수를 공급하고 약 183만 병을 회수해 회수율 80%를 기록했다. 생수는 하루 평균 8~12차례 보충되며, 회수된 페트병은 친환경 의류 등으로 재활용되며, 지난해 만족도 조사에서 응답자 4만 5786명 중 98.2%가 만족했다. 노원구는 우천 시 운영 중단 여부를 현장 여건에 따라 판단하며, 자율방재단이 현장 관리를 맡는다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:03'::timestamp,'2026-07-27 16:50:34.833470'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1638,3851,'서울 강북구는 65세 미만 심한 장애인을 대상으로 보건·의료, 일상돌봄, 주거지원을 통합한 통합돌봄 서비스를 2024년 4월부터 본격 시행한다. 기존 동 주민센터 중심의 노인 통합돌봄과 달리 구청이 행정과 서비스를 총괄하며, 사전조사 절차를 간소화하고 종합판정조사 중심의 단일 체계를 도입했다. 서비스 대상은 강북구에 거주하는 65세 미만 심한 장애인으로, 초기에는 지체·뇌병변 장애인을 우선 지원하며, 총 65개의 맞춤형 서비스를 제공한다. 이후 3개월마다 정기 모니터링을 실시하고, 이상 징후 발생 시 48시간 이내 보고해 7일 이내 지원계획을 조정하는 등 지속적인 사후관리를 시행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:08'::timestamp,'2026-07-27 16:49:01.261434'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1639,4419,'이재명 대통령은 7일부터 11일까지 3박 5일간 튀르키예에서 열리는 나토 정상회의 참석과 몽골 국빈 방문을 위한 순방을 시작했다. 이 대통령은 나토 사무총장의 초청으로 앙카라에서 열리는 정상회의에 참석하며, 인도·태평양 파트너국(IP4) 대표들과 소인수 회담을 진행하고, 나토 방위산업 포럼에서 기조 발언을 했다. 튀르키예 방문 기간 중 방산 분야 협력 수요 국가와 양자 회담을 진행하고, 몽골에서는 후렐수흐 대통령과 정상회담을 통해 ''한몽 관계의 황금시대'' 공동선언을 발표하며 협정 및 양해각서(MOU)를 교환했다. 순방 마지막 날인 11일에는 몽골 최대 명절 ''나담축제'' 개막식에 참석한 뒤 귀국하며, 이번 순방을 통해 나토 방산 시장 진출과 한몽 경제 협력 강화를 위한 기반을 마련했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:14'::timestamp,'2026-07-27 18:03:28.826193'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1640,3855,'중랑구는 1일부터 주거개선과 내에 재건축 사업을 지원하는 ''신속추진지원팀''을 신설해 2만 86세대에 달하는 30년 이상 노후 공동주택의 정비사업을 본격화했다. 중랑구는 민선 9기 공약인 주거환경 개선과 주택 공급 확대를 실현하기 위해 서울시의 주택 공급 확대 방침과 연계한 조직 개편을 추진하며, 특히 신내1택지지구 내 10개 단지가 올해 연한을 충족해 재건축 관심이 높아진 상황에서 초기 단계부터 행정 지원을 강화하고 있다. 신속추진지원팀은 재건축 절차와 제도 안내를 위한 ''중랑 재건축 정비사업 교육''과 ''주민과 함께하는 재건축 정비사업 포럼''을 운영해 현장 중심의 맞춤형 소통 체계를 구축하고, 사업 혼선을 줄이고 원활한 추진을 지원하고 있다. 이후 주민의 참여 확대와 사업 진행 상황 모니터링, 정비사업 포럼의 지속 운영 여부 등이 주요 후속 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:20'::timestamp,'2026-07-27 16:22:31.195123'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1641,3858,'노원구는 2024년 7월 16일부터 8월 16일까지 화랑대 철도공원(화랑로 622)에서 ''2026 꿀잼 워터파크''를 운영한다. 이는 기존 서울과학기술대학교 운동장에서 옮겨진 것으로, 폐선된 경춘선 철길과 옛 역사를 활용한 기차 테마공원인 화랑대 철도공원에서 열리며, 문화체육관광부 ''대한민국 로컬100''에 2회 연속 선정된 공간이다. 올해는 워터슬라이드를 무료로 전환하고 50m 에어바운스형으로 개선하며, 클라이밍풀, 유수풀, 에어슬라이드, 회전물썰매 등 전 연령층 시설을 확충했으며, 안전요원 배치, 수질 2시간마다 측정, 인조잔디 및 방수포 설치로 미끄럼 사고 예방에 주력했다. 입장료는 노원구민 무료, 타 자치구 주민 2천 원, 36개월 미만 영유아 무료이며, 주말에는 가족 참여형 프로그램 운영과 함께 20일 휴장일에 장애인 가족 초청 행사도 진행한다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:26'::timestamp,'2026-07-27 16:20:32.901401'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1642,3861,'노원구는 2024년 폭염 예상에 따라 7억 원을 투입해 생활밀착형 폭염 대응시설을 확충하고, 취약계층 보호를 위한 대책을 추진했다. 지난해 210개였던 횡단보도 그늘막을 217개로 늘리고, 노후 그늘막 35곳을 교체하며, 쿨링포그 시설을 총 10곳으로 확대하고 야외 무더위쉼터 ‘해피소’를 2곳 추가 조성했다. 현재 298곳의 무더위쉼터가 운영 중이며, 7월 1일부터 8월 16일까지 구청 카페도 주말에 개방하고, 폭염특보 발효 시 고령자 대상 야간 쉼터도 제공한다. 폭염특보 발효 시 야외 작업 현장에 대한 안전점검을 실시하고, 저소득층 가구 197곳에는 벽걸이형 에어컨 설치를 지원하며, 야외 근로자 165명에게는 휴대용 선풍기 등 맞춤형 방한물품을 지급할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:33'::timestamp,'2026-07-27 16:18:44.017125'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1643,3863,'서울 강북구는 7월 4일부터 8월 23일까지 벌말어린이공원, 고갯마루어린이공원, 우이동만남의광장 등 3곳에서 물놀이시설을 본격 운영한다. 이는 지난해 정비공사를 통해 단장된 고갯마루어린이공원과 우이동만남의광장이 올해 처음으로 물놀이장을 운영하는 것을 포함하며, 지역 어린이들이 가까운 공원에서 여름을 즐길 수 있도록 하기 위한 조치다. 물놀이장은 평일 오후 1시~4시(3회), 주말·공휴일 낮 12시~오후 5시(5회) 운영되며, 회차별 50분 가동 후 10분 휴식을 반복한다. 또한 수유일어린이공원 등 7개소는 9월 30일까지 바닥분수와 계류시설을 운영하고, 북서울꿈의숲은 8월 30일까지 주말·공휴일에 3회 운영되며, 안전과 위생 관리를 위해 시설 점검과 운영 중단 조치를 시행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:39'::timestamp,'2026-07-27 16:17:56.121050'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1644,3869,'유동균 마포구청장은 2024년 7월 1일 취임 후 첫 결재로 ''재개발·재건축 신속 추진 전담반(TF) 구성 계획''을 승인하며 민선 9기 핵심 공약인 정비사업 속도를 높이기 위한 첫 발을 내디뎠다. 마포구는 현재 총 61개소의 정비사업이 진행 중이나, 부서별로 업무가 분산되어 있어 신속한 대응과 체계적 관리에 한계가 있었으며, 주민들은 오랜 기간 정비사업 지연으로 인한 불편을 호소해왔다. 전담반은 분산된 관리 체계를 일원화하고, 권역별 책임관제를 통해 사업장별 현황을 밀착 관리하며, 월 1회 구청장 주재 간담회를 통해 조합장 등과 직접 소통하고 긴급 현안에 대해 수시 면담을 실시할 계획이다. 이후 정비사업의 지연 해소와 주민 갈등 조정, 서울시 협조 방안 등에 대한 구체적 실행 계획과 성과 평가가 예정되어 있으며, 이는 마포구의 도시 재생과 주거 환경 개선에 대한 장기적 방향성으로 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:45'::timestamp,'2026-07-27 16:20:54.560918'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1645,3872,'마포구는 2026년 7월부터 10월까지 용강동, 신수동, 서강동, 서교동, 합정동, 망원1동, 연남동, 성산1동의 8개 동평생학습센터에서 ''실뿌리배움터 하반기 교육프로그램''을 운영한다. 이 프로그램은 주민 생활권 내에서 평생학습 기회를 제공하기 위해 마련된 마포구의 동 단위 학습 거점으로, 디지털 역량, 인문·독서, 건강·생활, 문화예술, 가족 소통 분야의 총 16개 강좌를 제공한다. 수강 대상은 마포구민 및 소재 직장인으로, 7~8월 강좌는 6월 29일, 9~10월 강좌는 8월 18일 오전 10시부터 온라인 및 전화로 신청 가능하며, 수강료는 무료이나 재료비·교재비 등은 별도 부담해야 한다. 마포구는 이번 프로그램을 통해 주민의 삶의 질 향상과 지역사회 활성화를 도모하고, 향후에도 맞춤형 평생학습 프로그램을 지속적으로 발굴할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:52'::timestamp,'2026-07-27 16:17:48.273283'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1646,3883,'서울 용산구 남영동 업무지구 제2구역 도시정비형 재개발사업이 2024년 6월 4일 서울시 통합심의위원회에서 조건부가결을 받아 본격 추진된다. 이 지역은 서울지하철 1호선 남영역과 4호선 숙대입구역에 인접한 역세권으로, 노후 건축물 밀집으로 도시정비 필요성이 지속 제기되었으며, 2022년 정비구역 지정 및 2023년 조합설립인가를 거쳐 진행됐다. 이번 심의를 통해 지하 8층∼지상 최고 42층의 공동주택 3개 동과 지상 35층 업무시설 1개 동이 건설되며, 건축물 최고 높이는 기존 120m에서 150m로 상향되고 주거 비율은 57.5%에서 68.8%로 확대된다. 총 657세대가 공급되며, 재개발 의무임대주택 35세대와 공공임대주택 45세대를 포함하고, 지하 1층부터 지상 1층까지 판매시설과 운동시설이 조성되며, 약 1만5000㎡ 규모의 공공임대업무시설과 5700㎡ 규모의 남영동 복합청사가 기부채납된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:13:59'::timestamp,'2026-07-27 16:09:05.834519'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1647,3885,'마포구는 2024년 7월 6일부터 9월 18일까지 주 1회 총 10회에 걸쳐 초등학생 2~5학년을 대상으로 생활과학교실을 운영한다. 이 프로그램은 마포구에 거주하는 학생을 대상으로 하며, 이화여자대학교 생활과학교실 지역운영센터의 전문 강사진이 인공지능, 생물, 물리, 공학, 수학 등 다양한 과학 주제를 체험형 수업으로 진행한다. 수강료는 무료이나 실험 재료비 5만 원이 별도 부담되며, 기초생활수급자 등 사회적 배려계층은 반별 선착순 3명까지 재료비 전액 지원받을 수 있다. 신청은 마포구청 누리집에서 통합온라인신청으로 진행되며, 모집 인원 초과 시 전자추첨을 실시한다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:04'::timestamp,'2026-07-27 16:08:57.327146'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1648,4605,'정점식 국민의힘 원내대표는 2026년 7월 7일 시행된 정보통신망법 개정안을 ''온라인 입틀막법''이라며 헌법소원심판 청구와 전면 개정안 발의를 당론으로 추진하겠다고 밝혔다. 이는 조선시대 연산군의 ''신언패''를 비유하며, 국가가 사실과 혐오를 정하는 권한을 행사하는 것이 독재적이고 위헌적이라고 주장한 것이다. 정 원내대표는 장윤기 사건에서 경찰 수사팀장이 증거물을 가족에게 넘기는 등 조직적 은폐가 있었다며 검찰 보완수사권 유지와 여야정 수사체계 개편 협의 테이블 구성 필요성을 제안했다. 현재까지 수사체계 개편 논의는 이뤄지지 않았으며, 검찰 보완수사권 폐지 논의는 경찰 신뢰 회복 전까지 중단되어야 한다는 입장이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:10'::timestamp,'2026-07-27 18:03:45.040879'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1649,3887,'마포구는 6월 1일부터 구룡근린공원, 양화어린이공원, 삼개어린이공원 등 3개소의 바닥분수를 물놀이 가능한 시설로 개선해 운영을 시작했다. 기존의 경관용 바닥분수에 여과기와 정화설비를 추가해 수질을 관리하고, 안전을 확보하기 위해 주 1회 저류조 청소와 물 교체, 월 1회 시설 안전점검을 실시하고 있다. 현재 마포구는 창전어린이공원, 새빛문화숲을 포함해 총 5곳에서 물놀이용 바닥분수를 운영하며, 매일 오전 11시부터 오후 6시까지 40분 가동·20분 휴식 방식으로 운영된다. 수질은 15일마다 검사해 결과를 안내판에 공개하고, 공덕오거리 교통섬 등 23개소의 경관 수경시설과 함께 여름철 쾌적한 휴식 공간을 제공하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:15'::timestamp,'2026-07-27 16:08:41.071710'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1650,3894,'2024년 12월 3일 윤석열 전 대통령이 위헌적 비상계엄을 선포한 당시, 김민석 전 국무총리는 국회 본회의 표결에 불참해 논란이 됐다. 이는 계엄 해제 결의안이 본회의에서 의결된 상황에서, 김 전 총리가 본회의장에 출석하지 않았다는 점에서 비판을 받았으며, 친청계인 이성윤 최고위원이 페이스북에서 ''왜 안 왔는지''를 묻는 등 공격을 가했다. 김 전 총리는 KBS라디오에서 표결 당시 국회 안에 있었고, 직후 본회의장에 착석했다고 반박하며 허위사실에 의한 명예훼손이라고 주장했다. 이에 대해 정청래 전 대표는 ''네거티브 중단''을 선언하며 이재명 대통령과의 연대를 강조하며 ''동지의 언어''를 사용하겠다고 밝히며 내부 단결을 촉구했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:21'::timestamp,'2026-07-27 18:27:29.398723'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1651,3897,'2024년 7월 7일 캐나다 정부는 차기 잠수함 도입 사업의 우선협상대상자를 독일 기업으로 선정하며, 한국 기업의 수주 실패를 발표했다. 이는 한국이 1949년부터 유지해온 나토 군사안보동맹의 강력한 벽과 기술 외적 요인(비용, 협력 조건 등)이 수주에 영향을 미쳤음을 보여준다. 캐나다 현지 언론과 전문가들은 한국과 독일의 잠수함 성능과 협력 조건이 대등했다고 평가했으며, 한국은 독일의 기술 원조국으로서 성능 면에서 오히려 앞선 평가를 받았다. 정부와 기업은 이번 도전을 성과로 삼아 연구개발, 수출 지원, 국제협력 강화를 통해 다음 수주전에서의 성공을 준비하고 있으며, 세계 각지에서 한국 방산 제품에 대한 수요가 지속되고 있음을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:27'::timestamp,'2026-07-27 18:19:36.310817'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1652,3898,'이재명 대통령은 7일 나토 정상회의 참석을 위해 튀르키예 앙카라로 출국했다. 이 대통령은 나토 사무총장과의 면담을 시작으로 인도태평양 파트너국과의 회담, 방위산업포럼에서 ''대한민국과 나토의 방위산업 연대''를 주제로 기조연설을 할 예정이며, 레제프 타이이프 에르도안 튀르키예 대통령의 환영 만찬에도 참석한다. 이 대통령은 캐나다 잠수함 프로젝트 수주 실패 이후에도 K-방산의 글로벌 도전을 지속하겠다는 입장을 밝히며, 나토 내 방산 협력 수요국들과의 양자 회담도 추진 중이다. 트럼프 미국 대통령과의 회담 가능성도 주목되며, 이번 순방은 방산외교 강화와 국제적 위상 제고를 위한 전략적 행보로 평가된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:32'::timestamp,'2026-07-27 18:19:04.870521'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1653,3900,'6·3 지방선거 투표용지 부족사태와 관련해 더불어민주당 한병도 대표직무대행은 서울 올림픽공원 핸드볼경기장에 보관 중인 247만장의 투표용지에 대해 여야 협의를 통해 재검표 및 수개표를 국조특위에서 추진하는 방안을 적극 검토하겠다고 밝혔다. 이는 국민의힘 윤상현 선관위 특위 위원장이 제안한 공개 재검표 계획에 대한 긍정적 반응으로, 선관위는 투·개표 오류가 없음을 입증해야 한다는 입장이며, 경기장 임차 비용 약 2억원과 재검표 비용 5000만원을 비교해 한 번의 재검표가 효율적이라고 판단했다. 강동완 중앙선관위 사무총장 대행도 재검증 필요성을 인정하며 ''좋다, 하겠다''는 입장을 밝힌 바 있다. 현재 여야는 재검표 절차와 방식, 책임 소재 규명을 위한 국조특위 운영 방향에 대해 협의 중이며, 국민 신뢰 회복과 선거의 투명성 확보가 핵심 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:38'::timestamp,'2026-07-27 18:18:32.656820'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1654,3901,'2026년 7월 7일, 정보통신망법 개정안이 시행되며 온라인 허위정보 및 혐오 표현 규제가 강화됐다. 이 법은 국가가 정보의 진위와 혐오 여부를 판단하는 권한을 부여함으로써 카카오톡, 유튜브, SNS 등 일상적 온라인 표현까지 감시와 통제의 대상이 될 수 있다는 우려가 제기됐다. 국민의힘은 이 법을 ''현대판 신언패''라며 위헌성과 표현의 자유 침해를 주장하며, 헌법소원 청구와 전면 재개정안 발의를 예고했다. 이후 언론인, 변호사, 민간단체 등이 헌법소원 준비에 나서며, 법적·사회적 논란이 확산될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:43'::timestamp,'2026-07-27 18:17:32.926111'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1655,3903,'중앙선관위는 6·3 지방선거 투표지 247만매를 송파구 잠실 올림픽공원 개표소에서 과천청사로 이송하기 전 검증에 9시간과 5천만원이 소요될 것으로 추산했다. 이는 투표지의 육안 재확인, 정당·후보자별 분류 및 확인을 위한 인력 440명과 예산이 필요하며, 현재 보관된 투표지는 서울시장 선거 37매, 송파구의회 마선거구 25만매, 잠실7동 4만매 등이다. 이송 과정은 국회 원내정당별 추천자 1명씩 참관하에 차량 적재 후 과천청사로 이송하며, 이송 중 촬영 및 참관인과 경찰관 동승, 특수봉인지 부착, CCTV 설치 등 안전 조치를 취할 계획이다. 다만 현행 법규상 선관위의 자체 재검표는 불가능하므로, 투표지 무결성을 입증하기 위해 국정조사특위의 의결을 거쳐야 하며, 국조특위는 14일과 22일 청문회를 거쳐 잠정 결과보고서를 채택할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:50'::timestamp,'2026-07-27 18:12:02.358812'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1656,3905,'국회 6·3 지방선거 투표용지 부족 사태 국정조사특별위원회(국조특위)는 7일 중앙선거관리위원회 과천청사와 서울시선거관리위원회 종로구 사무소를 현장 조사했다. 이는 본투표 당일 투표용지 부족 사태 발생 후 중앙선관위와 서울시선관위의 초기 인지 시점, 보고 체계 및 위기 대응 능력에 대한 검증을 목적으로 했다. 조사 과정에서 윤상현 위원장이 제안한 올림픽공원 개표소 투표지 재검표 추진 가능성도 검토됐으며, 이는 사태의 책임 소재 규명과 투표 시스템 개선 방향에 영향을 미칠 전망이다. 국조특위는 추가 조사와 증인 신청을 통해 사태의 전모를 밝히고, 향후 선거 관리 제도 개선 방안을 논의할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:14:55'::timestamp,'2026-07-27 18:09:28.195723'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1657,3907,'이재명 대통령은 7일 나토 정상회의 참석을 위해 튀르키예 앙카라를 방문했다. 이는 취임 후 첫 나토 정상회의 참석이며, 마르크 뤼터 나토 사무총장의 초청으로 성사된 것으로, 지난달 G7 정상회의에 이어 국제사회의 평화와 안보 기여를 강조하는 외교적 지평 확대의 일환이다. 대통령은 나토 방위산업포럼에서 ''공동의 가치, 더욱 강한 산업기반''을 주제로 기조발언을 하며, 한국의 방산 기반을 세계가 인정하는 경쟁력으로 발전시킨 과정을 강조했고, 나토 동맹국들을 중심으로 한 방산협력 확대를 추진할 계획이다. 이후 8일까지 앙카라에 머무른 뒤 9일 몽골로 이동해 국빈방문을 진행하며, 도널드 트럼프 미국 대통령과의 현지 대면 가능성도 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:00'::timestamp,'2026-07-27 18:06:16.666899'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1658,3910,'외국인 투자자가 13거래일 연속 삼성전자와 SK하이닉스를 순매도하며, 삼성전자 외국인 보유율은 2009년 이후 최저인 46.69%로 떨어졌다. 이는 미국과 이란 간 긴장으로 인한 투자심리 위축과 함께, 2023년 5월 이후 지속된 외국인 매도세의 결과다. 반면 개인 투자자들의 빚투는 확대되며, 삼성전자 신용잔고는 5조5천75억원, SK하이닉스는 5조3천49억원으로 사상 최대치를 기록했다. 향후 SK하이닉스의 미국 ADR 상장(10일 예정)과 하반기 메모리 가격 강세 전망이 외국인 투자 회복의 변수로 작용할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:07'::timestamp,'2026-07-27 18:49:50.686790'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1659,3911,'SK하이닉스는 2024년 6월 6일(현지 시간) 나스닥 상장 절차를 공식 개시하며, 280억 달러 규모의 기업공개(IPO)를 진행한다. AI 데이터센터 수요 증가로 메모리 반도체 수요가 급증하면서 SK하이닉스의 지난해 매출은 97조1000억원, 영업이익은 42조9000억원으로 전년 대비 각각 47%와 두 배 이상 증가했으며, 올해 1분기 매출은 전년 동기 대비 약 3배 증가한 52조6000억원을 기록했다. 이번 상장에서 전직 오픈AI 연구원이 설립한 헤지펀드 시추에이셔널 어웨어니스와 영국 투자사 베일리 기포드 등이 최대 70억 달러어치의 미국주식예탁증서(ADS) 인수를 의향을 밝히며, SK하이닉스 주가는 지난 1년간 코스피에서 750% 이상 상승해 시가총액 1663조원을 기록했다. 상장된 자금은 국내 반도체 공장 신설과 네덜란드 ASML의 EUV 스캐너 구매 등 생산능력 확대에 사용되며, 7월 3일 기준 주당 약 158달러(약 24만원) 수준의 공모가가 결정되고, 뱅크오브아메리카·JP모건·골드만삭스·씨티그룹이 대표 주관사로 참여해 미국 시장에서 10일부터 거래가 시작될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:15'::timestamp,'2026-07-27 18:47:14.702824'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1660,3915,'2024년 7월 7일 코스피는 장중 7.73% 하락하며 7,428.60까지 떨어졌고, 오후 1시 35분 기준 7,439.17로 전날 대비 612.16포인트(7.60%) 하락했다. 이날 하락은 반도체 업종 중심으로 집중되었으며, 삼성전자(-9.28%)와 SK하이닉스(-10.07%)가 각각 9%대와 10%대 하락하며 지수 하락을 주도했다. 외국인과 기관이 각각 3조1천908억원, 1천631억원 순매도를 기록한 반면, 개인은 3조2천866억원 순매수로 시장 하방을 지지했다. 이후 유가증권시장에서 프로그램매도호가 일시효력정지(매도 사이드카)가 발동되었으며, 이는 시장 안정화를 위한 조치로 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:20'::timestamp,'2026-07-27 18:44:37.150357'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1661,3922,'국세청은 A씨가 남편 친구 B씨에게 아파트를 허위 이전해 1세대1주택 비과세 혜택을 부당하게 받은 사례를 적발하며, 총 731억원 규모의 부동산 탈세를 확인했다. 이는 다주택자가 저가주택을 명의만 허위 이전해 양도세 비과세를 받거나, 부모로부터 고가 아파트를 편법 증여받아 증여세를 회피한 사례를 포함한 것으로, 자금 흐름 조작과 거래 증빙 조작이 확인됐다. 국세청은 A씨와 B씨, C씨와 모친, 모친의 지인, D씨 배우자, E씨 등 총 6명을 조세포탈 혐의로 검찰에 고발하고, 총 318억원의 세금을 추징했다. 이후 다주택자 증여거래와 가족 간 편법 거래를 중심으로 세무조사를 강화하고, 증여재산 저가평가 및 세금 대납 여부를 점검할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:27'::timestamp,'2026-07-27 18:32:56.053495'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1662,3934,'2026년 4월 27일 부산 금정구 구서나들목에서 열린 개혁신당 정이한 전 부산시장 후보의 유세 도중 차량에서 던진 음료에 맞아 병원에 이송된 사건에 대해, 음료를 던진 30대 헬스트레이너 A씨와 정 전 후보에 대해 경찰이 위계에 의한 공무집행방해 및 공직선거법 위반 혐의로 구속영장을 청구했다. 사건 발생 전 두 사람 간 통화 기록이 확인되며, A씨가 정 전 후보와 평소 알고 지내던 사이였다는 사실이 드러나 자작극 의혹이 제기됐고, 이에 따라 정 전 후보는 SNS를 통해 정계 은퇴를 선언하고 탈당한 뒤 두문불출했다. 검찰은 증거인멸 및 도주 우려를 이유로 구속영장을 부산지법에 청구했으며, 구속 전 피의자 심문은 8일 오후 2시 부산지법에서 예정되어 있다. 현재 사건은 자작극 여부와 선거법 위반 여부에 대한 법적 판단을 기다리고 있으며, 향후 법원의 영장실질심사 결과가 핵심 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:34'::timestamp,'2026-07-27 18:45:16.170345'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1663,4606,'이재명 대통령은 7일 나토 정상회의 참석과 몽골 국빈 방문을 위해 3박 5일간의 순방을 시작했다. 취임 후 처음으로 나토 정상회의에 참석하는 이번 방문은 유럽 방산시장 공략과 공급망 협력 확대를 목표로 하며, 세계 국방비 절반 이상을 차지하는 나토 회원국들의 방산 확대 수요에 대응하는 것이 핵심이다. 이 대통령은 나토 사무총장과 IP4 정상들과의 회담, 방산포럼 기조발언 등을 통해 K-방산의 경쟁력과 협력 비전을 제시할 예정이며, 나토 일정 후 9일부터 몽골을 국빈 방문한다. 이번 순방은 2011년 이후 15년 만에 이루어지는 대한민국 대통령의 몽골 국빈 방문으로, 외교적 의미가 크며, 방산 수출 확대와 국제 협력 강화를 위한 후속 절차가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:39'::timestamp,'2026-07-27 18:00:33.323616'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1664,3950,'러시아는 2024년 7월 5일 나토 정상회의 개막 전날 우크라이나 수도 키이우를 대상으로 탄도미사일 23발과 공격용 드론 351대를 발사해 융단폭격을 실시했다. 이는 지속된 전쟁으로 인해 우크라이나의 방공망이 부족한 상황에서 발생했으며, 러시아는 공격을 무기 공장과 방공 시설, 에너지 기반 시설 겨냥한 것으로 주장했다. 이번 공격으로 키이우에서 최소 23명이 사망하고, 어린이 포함 56명이 부상했으며, 인근 지역에서도 48명이 다쳤고, 아파트 3동이 붕괴되는 등 도시 곳곳에 피해가 발생했다. 젤렌스키 대통령은 나토 정상회담에서 방공망 지원 확대를 요청하며, 요격 미사일 생산량 부족 문제를 지적했고, 트럼프 미국 대통령과의 회담 및 EU 집행위원회의 방공 능력 증강 논의가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:44'::timestamp,'2026-07-27 18:28:41.366514'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1665,3954,'지난 3월 24일(현지시간) 베네수엘라에서 발생한 연쇄 지진으로 사망자가 3,535명으로 집계됐으며, 이는 전날보다 193명 증가한 수치다. 지진은 라과이라주 등 일부 지역에서 건물 856채가 피해를 입고, 그중 190채가 붕괴되며 부상자 1만6,740명, 이재민 약 1만7,854명이 발생했다. 정부는 육군과 보안군 2만9,567명, 자원봉사자 2만7,930명을 동원해 구조·복구 작업을 진행했으나, 지진 발생 후 10일이 경과하면서 매몰자 생환 가능성은 크게 감소한 상태다. 현지 언론이 보도한 어린이 4명 구조 소식은 오보로 확인되었으며, 당국은 구조된 인원 수가 6,462명으로 지난 2일 이후 변동이 없다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:50'::timestamp,'2026-07-27 18:08:38.055913'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1666,3962,'베네수엘라 라과이라주에서 발생한 6월24일 지진으로 인해 사망자 3342명, 부상자 1만6700명, 이재민 1만7000명 이상이 발생했으며, 신원 미확인 시신 150여구가 라 에스페란자 공동묘지에 개별 무덤으로 매장됐다. 지진 직후 병원 영안실과 항구 임시 보관소의 수용 한계를 초과하면서 시신은 비닐에 싸인 채 땡볕 아래 방치되며 부패가 심화되고, 유가족들은 지문, 사진, 옷가지 등 단서로 신원 확인을 시도하는 등 어려움을 겪고 있다. 신원 확인이 불가능한 시신은 법의학적 절차를 거쳐 매장되며, 일부 유가족은 장례비 부담으로 인해 장례를 치르지 못해 지역 공동묘지의 무료 매장 공간을 이용하는 상황이다. 정부는 집단 매장 계획이 없으며 신원 확인 절차를 엄격히 운영하고 있으나, 유가족들 사이에서는 신원 확인 없이 매장될 수 있다는 공포가 확산되고 있으며, 국제 구조대의 철수와 유엔의 주도권 이관으로 현장 수습 작업이 마무리 국면에 접어들고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:15:58'::timestamp,'2026-07-27 17:17:24.256177'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1667,3963,'나토 32개 회원국 정상들이 7일(현지시간) 튀르키예 앙카라에서 정상회의를 개최하며, 도널드 트럼프 미국 대통령의 국방비 증액 압박과 유럽 미군 감축 계획에 대한 반응을 논의했다. 트럼프 행정부는 나토 회원국들이 안보 무임승차를 하고 있다고 주장하며, 2035년까지 GDP 대비 5%의 국방비 지출을 약속한 합의 이행을 점검하고 있다. 지난해 기준 미국을 제외한 나토 회원국의 국방 지출은 5740억달러(약 879조원)로 전년 대비 20% 증가했으며, 방산업계는 수요 증가로 인한 생산 수용 능력 한계에 직면해 있다. 이번 회의에서는 제5조 집단방위 의무 재확인, 우크라이나 및 이란 문제, 방산 협력 확대 등이 논의되며, 이재명 대통령도 참석해 방산 협력 추진 의지를 표명했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:04'::timestamp,'2026-07-27 17:15:21.131282'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1668,3967,'러시아는 2024년 7월 6일(현지시간) 우크라이나 수도 키이우를 대상으로 탄도미사일, 순항미사일, 드론을 사용한 대규모 공격을 감행했다. 이는 나토 정상회의를 하루 앞둔 시점으로, 우크라이나 정부와 국제사회가 주목하는 외교적 무대를 겨냥한 것으로 분석된다. 이번 공격으로 키이우와 주변 지역에서 최소 11명이 사망하고, 수도에서 46명, 주변 지역에서 15명이 부상했으며, 일부 건물이 붕괴되고 잔해 아래에 사람들이 갇힌 것으로 확인됐다. 러시아는 군수산업 기업과 에너지 시설을 타격했다고 밝혔으나, 우크라이나는 러시아가 외교적 관심이 집중되는 시점에 의도적으로 공격을 실시한 것이라고 반발하며, 향후 국제적 대응과 안보 정책 재조정이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:10'::timestamp,'2026-07-27 16:58:50.884909'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1669,3970,'50대 남성이 사고를 일부러 일으킨 뒤 경찰이 도착할 때까지 누워있는 방식으로 보험사기를 저지른 사건이 발생했다. 이 남성은 2024년 4월 26일 서울 강남구에서 자동차 사고를 조작해 보험금을 청구한 것으로 확인됐다. CCTV 영상 분석 결과, 사고 후 11분간 누워있던 이 남성은 보험사기 혐의로 검찰에 송치됐으며, 현재는 수사가 진행 중이다. 이후 보험사기 방지 대책과 사고 조작에 대한 법적 처벌 강화가 논의되고 있으며, 관련 법 개정안이 국회에 제출될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:15'::timestamp,'2026-07-27 18:54:54.798727'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1670,3971,'서울중앙지방법원 형사합의부는 생후 19개월 딸을 방임해 사망하게 한 혐의로 기소된 A씨(29)에 대해 2024년 3월 28일 징역 3년을 선고했다. A씨는 딸을 19개월 동안 방치하며 식사, 보육, 의료 등 기본적인 돌봄을 제공하지 않았고, 이로 인해 딸이 영양실조와 질병으로 사망했다. 재판부는 A씨의 방임 행위가 중대한 범죄로 판단해 관대한 처분을 요구하는 진술에도 불구하고 엄격한 형량을 결정했으며, A씨는 항소할 예정이다. 이번 사건은 아동 방임에 대한 사회적 관심을 높였고, 아동 보호 제도의 보완 필요성에 대한 논의가 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:23'::timestamp,'2026-07-27 18:52:47.062370'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1671,3973,'조경식 전 의원이 전 여친을 흉기로 위협하고 감금한 혐의로 법정구속됐다. 이 사건은 2023년 9월 15일 서울중앙지방법원에서 진행된 재판에서 발생했으며, 조 전 의원은 연어 술파티 증언 이후 범죄 혐의를 받았다. 검찰은 조 전 의원에게 감금 및 폭력 협박 혐의로 징역 4년을 구형했고, 법원은 이를 받아들여 구속 판결을 내렸다. 이후 조 전 의원은 항소할 예정이며, 사건은 향후 항소심에서 재판될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:31'::timestamp,'2026-07-27 18:41:36.665287'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1672,3976,'2024년 7월 20일, 종합특검은 김건희씨 관련 ''황제조사 의혹''과 관련해 이원모 전 대통령실 비서관을 참고인으로 소환해 조사를 진행했다. 이 전 비서관은 2022년 3월 당시 대통령실에서 김건희씨의 청와대 입성과 관련한 정보를 처리한 인물로, 특검은 그가 조사 과정에서 특정 인물에 대한 불이익을 초래할 수 있는 정보를 제공했는지 확인하고자 했다. 조사 결과, 이 전 비서관은 관련 정보를 보고한 바가 없으며, 특검은 추가 증거 확보를 위해 다른 관계자도 대상으로 조사할 계획이다. 이후 특검은 이 사건과 관련한 추가 소환 및 증거 수집을 지속하며, 공직자들의 정보 처리 행위에 대한 법적 책임을 명확히 하기 위한 절차를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:38'::timestamp,'2026-07-27 18:26:22.225505'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1673,3977,'합동수사본부는 2023년 9월 총선 투표용지 인쇄 계약과 납품 과정을 조사하기 위해 인쇄업자 및 선거관리위원회 관계자를 소환했다. 이는 투표용지 인쇄 계약이 비공개로 진행되면서 공정성과 투명성에 대한 의문이 제기된 데 따른 조치로, 계약금액은 1470만 원이었다. 현재까지 조사 결과, 인쇄업자와 선관위 관계자 간의 계약 체결 및 납품 절차에서 의심되는 점이 발견되었으며, 관련자들은 조사에 협조하고 있다. 이후 합수본은 추가 조사와 공직자 징계 여부를 검토하며, 투표용지 제도의 투명성 강화 방안 마련이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:45'::timestamp,'2026-07-27 18:26:14.878123'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1674,3980,'7월6일 서울 배재고등학교 야구부 학생들과 학부모, 교사 86명이 광주일고를 찾아 지난달 29일 열린 경기에서 광주 지역을 비하하는 구호를 외친 행위에 대해 사과했다. 이는 배재고 선수들이 서울 목동구장에서 광주일고 더그아웃을 향해 ''스타벅스 가야지'', ''탱크데이''라고 외친 영상이 공유되며 지역 감정을 자극한 데 따른 후속 조치다. 사과 후 배재고는 자체 조사를 통해 관련 학생 2명을 생활교육위원회에 회부했으며, 대한야구소프트볼협회는 6개월 출전 정지와 몰수패를 결정했다. 이후 양측은 광주학생독립운동 기념탑과 5·18 민주묘지에서 참배하며 민주·인권·평화의 가치를 공유했으며, 서울시교육청은 교장·교감 등 관리 책임 여부를 조사 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:52'::timestamp,'2026-07-27 17:06:19.003043'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1675,3982,'경찰청은 광주 여고생 살인사건에서 부실수사 의혹이 제기된 것을 계기로 6일 ''광주광산서 살인사건 관련 진상규명 특별수사팀''을 편성했다. 이 사건은 2024년 5월 5일 광주 광산구에서 발생한 여고생 강간살인 사건으로, 수사 과정에서 장윤기의 부친이자 경찰관인 장아무개 경감과 수사팀 간의 유착 의혹이 제기됐으며, 수사팀장이 케이블 타이를 이용해 증거인멸한 혐의로 긴급체포됐다. 특별수사팀은 홍장득 총경이 팀장을 맡고, 경찰청 중대범죄수사과에서 6명의 수사관을 추가 투입해 총 27명으로 구성되며, 광주청 지휘라인을 배제하고 독립적으로 수사를 진행한다. 현재 특별수사팀은 사건 발생 후 100일이 넘은 상황에서 핵심 증거 확보 실패와 수사 편의 제공 의혹 등을 조사 중이며, 최종 수사 결과는 홍석기 국가수사본부장에게 보고될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:16:58'::timestamp,'2026-07-27 17:06:01.963370'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1676,3983,'2024년 5월 23일, 대한민국의 온라인 커뮤니티 ''일베''(일반인 베이비)에서 ''노무현''과 ''리센느'' 등 정치적·문화적 인물에 대한 혐오 표현이 확산되며 사회적 논란이 일었다. 이는 5·18 민주화 운동을 기념하는 날에 발생한 것으로, 일베 사용자들이 특정 인물과 사건을 비하하는 표현을 반복적으로 사용하며 공적 논의의 토대를 훼손했다는 비판이 제기됐다. 관련 게시물은 수천 건에 달하며, 일부는 ''노무현''과 ''리센느''를 혐오 대상으로 지목해 사회적 갈등을 유발했고, 이에 대해 시민단체와 언론이 ''인터넷 혐오 표현의 확산''을 우려하며 제재 필요성을 강조했다. 이후 일베 운영진은 일부 게시물을 삭제했으나, 혐오 표현의 지속적 유포와 관련된 법적·제도적 대응 방안이 논의되고 있으며, 정부는 온라인 공간의 건전한 운영을 위한 정책 절차를 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:17'::timestamp,'2026-07-27 17:05:48.330509'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1677,3986,'2024년 7월 7일, 정보통신망법 개정안이 시행되며 온라인 허위·조작정보 유포에 대해 최대 5배 손해배상 청구와 최대 10억원 과징금이 가능해졌다. 이 법은 플랫폼이 자체 판단 또는 국제팩트체킹네트워크(IFCN) 인증기관을 통해 정보를 검증하고, 법원이 최종 판단을 내리는 절차를 두고 있으며, 대상은 하루 이용자 100만 명 이상의 플랫폼 및 구독자 10만 명 이상의 수익형 게시자로 제한된다. 야당과 시민사회는 표현의 자유 침해와 사전검열 우려를 제기하며 헌법소원을 예고했고, 일부 플랫폼에서는 ''77법 생존 매뉴얼''이 유포되며 공론장 위축이 우려되고 있다. 이후 헌법재판소는 이 법의 위헌 여부를 판단할 예정이며, 공익 보도 및 진실을 믿을 만한 이유가 있는 경우 면책 조항이 적용된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:24'::timestamp,'2026-07-27 17:00:09.506609'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1678,3987,'성남시에서 발생한 교제 살인 사건의 가해자 B는 2023년 10월 15일 A를 살해한 혐의로 기소되었으며, 피해자 A는 성남시에서 ''A등급''으로 분류된 범죄 전력이 있는 인물이었다. 사건의 배경은 가해자 B가 피해자 A와의 관계에서 지속적인 갈등을 겪었고, 이로 인해 범행이 발생한 것으로 파악된다. 현재 가해자 B는 구속 상태이며, 검찰은 영장 청구를 하지 않았고, 법원은 구속 전 피의자 심문을 진행 중이다. 이후 사건은 법원의 재판 절차를 거쳐 최종 판결이 예정되어 있으며, 이는 범죄 예방 및 정신 건강 관리 제도의 개선 필요성에 대한 논의를 촉발하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:33'::timestamp,'2026-07-27 16:59:09.503618'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1679,3989,'국립통계원은 2025년 1월부터 소비자물가지수에 클라우드 서비스와 마라탕 등 외식식품을 반영하기로 결정했다. 이는 2020년 외식물가지수 개편 이후 5년 만에 대규모 개편으로, 외식물가지수의 구성품을 현행 312개에서 312개로 유지하되, 클라우드 서비스와 마라탕 등 신규 품목을 포함시켰다. 현재까지 반영된 품목은 총 312개이며, 외식물가지수의 변화는 2025년 1월부터 적용되며, 2026년 12월까지 추가로 10개의 품목이 추가될 예정이다. 이후 외식물가지수의 정기적 개편과 품목 조정이 예정되어 있으며, 이는 소비자물가지수의 정확성과 실시간 반영을 위한 지속적인 개선 과정으로 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:42'::timestamp,'2026-07-27 18:55:24.884431'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1680,3993,'미국 헤지펀드 시추에이셔널 어웨어니스, 영국 자산운용사 베일리 기포드, 미국 벤처캐피탈 코튜 등 3개 투자사가 SK하이닉스의 미국주식예탁증서(ADR) 공모에 최대 70억 달러(약 10조7000억원)를 인수할 의사를 밝혔다. 이는 SK하이닉스가 나스닥 상장을 위해 발행하는 총 280억 달러 규모 ADR 공모 물량의 약 25%에 해당하며, 인공지능 및 테크 기업에 강점이 있는 투자사들이 주목한 것으로, SK하이닉스의 장기 성장 가능성에 기대를 걸고 있다. SK하이닉스는 10일 나스닥에서 ADR 거래를 시작하며, 발행 주식의 약 2.5%에 해당하는 1779만 주를 신주로 공모한다. 투자자들 사이에서는 메모리 반도체 시장의 사이클 타이밍과 시장 변동성에 대한 우려가 존재하지만, 장기 성장 스토리로의 인식이 확산되며 상장 성과에 대한 기대가 형성되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:49'::timestamp,'2026-07-27 18:43:39.001571'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1681,3998,'삼성전자는 2024년 7월 29일 코스피 시장에서 주가가 전일 대비 6.29% 하락하며 29만 8000원을 기록하며 30만원선을 하회했다. 이는 엔비디아 등 글로벌 반도체 기업의 성장세 속에서도 삼성전자의 시장 점유율과 수익성 악화가 지속되고 있음을 반영한다. 삼성전자의 주가는 최근 1개월간 약 4% 하락했으며, 이는 메모리 반도체 수요 둔화와 경쟁사들의 기술적 우위로 인한 시장 압박이 주요 원인이다. 현재 삼성전자는 반도체 사업의 재편과 신기술 투자 확대를 통해 실적 회복을 추진하고 있으며, 향후 2분기 실적 발표와 기술 혁신 전략 발표가 주요 이벤트로 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:17:58'::timestamp,'2026-07-27 18:10:10.491806'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1682,4000,'이재명 대통령은 2024년 5월 26일 캐나다의 잠수함 수주 입찰에서 한국이 탈락한 결과에 대해 ''K방산의 담대한 도전을 계속하겠다''고 밝혔다. 이는 한국이 캐나다의 80억 달러 규모의 잠수함 수주 프로젝트에 참여했으나, 최종적으로 프랑스의 잠수함이 선정되면서 발생한 결과로, 한국의 방산 수출 경쟁력에 대한 우려가 제기된 상황이다. 이번 입찰 탈락으로 한국 방산 산업은 해외 수출 확대에 있어 중요한 기회를 놓친 것으로 평가되며, 정부는 향후 해외 수주 전략 재정비와 기술 혁신을 통한 경쟁력 강화를 추진할 예정이다. 이후 정부는 캐나다와의 방산 협력 강화와 함께, 유럽 및 아시아 시장에서의 수주 활동을 확대할 계획을 발표했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:05'::timestamp,'2026-07-27 18:04:36.992143'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1683,4001,'삼성전자는 2024년 2분기 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 글로벌 테크 기업 중 분기 실적 최고치를 달성했다. 이는 지난해 동기 대비 매출 129%, 영업이익 1810% 증가한 것으로, 반도체 수요 정점론(피크아웃) 우려를 잠재우는 성과로 평가된다. 영업이익에는 노사 합의에 따른 성과급 충당금 약 15조~19조원이 포함되어 있으며, 이 변수를 제외하면 분기 영업이익이 100조원을 초과했을 것으로 추정된다. 삼성전자는 분기 매출 1117억3000만 달러로 ''1000억 달러 클럽''에 진입했으며, D램과 HBM 등 고부가가치 메모리 수요 증가로 인해 시장 내 공급 부족이 지속될 전망이며, 하반기에도 안정적인 성장이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:12'::timestamp,'2026-07-27 18:04:13.474567'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1684,4006,'정부는 청년미래적금을 234만3000명이 신청하며 27일부터 계좌 개설을 시작했다. 이 상품은 19~34세 청년을 대상으로 하며, 연 1000만원까지 적금을 납입할 수 있고, 정부는 연 50만원까지 보조금을 지급한다. 신청자 중 30~34세가 38.8%로 가장 많았으며, 25~29세는 36.5%, 19~24세는 24.7%를 차지했다. 이후 27일부터 본격적인 계좌 개설이 진행되며, 정부는 보조금 지급 절차와 관리 체계를 확립할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:17'::timestamp,'2026-07-27 17:04:50.378386'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1685,4007,'홈플러스는 일부 카드사가 매출 대금 지급을 보류한 것에 대해 즉각 철회를 요구했다. 이는 홈플러스가 카드사와의 결제 계약 조건을 위반했다는 이유로 일부 카드사가 2024년 3월부터 대금 지급을 보류하면서 발생한 갈등이다. 현재까지 약 3개월 간 지급 보류가 지속되며, 홈플러스의 매출 회수에 악영향을 미치고 있으며, 이로 인해 일부 매장 운영에 차질이 발생하고 있다. 이후 카드사와의 협의가 예정되어 있으며, 정부의 중재 요청 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:23'::timestamp,'2026-07-27 17:04:04.738611'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1686,4008,'국민의힘 ''6·3 국민참정권 침해 진상규명 및 선거관리 개혁 특별위원회''는 7일 정부에 선거관리위원회 내부 고발자 면책안 마련을 촉구하며 사전투표제 폐지 등을 포함한 선거 시스템 개혁안을 추진하기로 했다. 이는 선관위 내부 문건에서 전원 유임 및 국회 회의록 회피 시나리오를 마련한 사실이 드러나면서, 조직의 폐쇄성과 부패 우려가 제기된 데 따른 것이다. 특위는 선관위 조직개편, 선거 관리 시스템 개선, 6·3 선거 의혹 규명 3개 분과를 구성해 전면적 개혁안을 마련할 예정이며, 사전투표 폐지와 상임위원 확대, 독립적 감사기구 설치 등 방안을 논의 중이다. 이후 특위는 선관위 사무처 슬림화 또는 해체 방안, 법관 겸임 철폐, 상근 위원장 도입 등 구체적 개혁 방안을 정부에 제안할 계획이며, 사전투표 폐지 방안은 당론으로 추진될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:29'::timestamp,'2026-07-27 18:59:53.502829'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1687,4018,'2024년 7월 6일 캐나다 정부는 초계잠수함 프로젝트(CPSP) 우선협상대상자로 독일 티센크루프마린시스템스(TKMS)를 선정했다. 이 프로젝트는 2030년대 중반 퇴역 예정인 빅토리아급 잠수함 4척을 대체하는 디젤 잠수함 최대 12척을 건조하는 사업으로, 건조비와 30년간 유지보수운영(MRO) 비용을 포함해 최대 60조원 규모다. 한화오션과 HD현대중공업 원팀은 독일 TKMS와 경쟁했으나, 캐나다 정부는 나토 동맹과 군수 상호운용성 등 안보적 요인을 고려해 독일 측을 선택했다. 강훈식 대통령 비서실장은 이번 결과를 ''잘 싸웠다''는 위안으로 끝내지 않겠다며 정부와 기업의 협력 체계를 유지하고, 부족한 점을 보완해 다음 도전에 나설 것임을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:35'::timestamp,'2026-07-27 18:10:35.356932'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1688,4021,'국민의힘 중앙윤리위원회는 6일 한동훈 무소속 의원의 선거 지원 행위를 비롯한 당내 해당행위에 대한 징계 심의를 착수했다. 이는 6·3 지방선거 이후 처음 열린 윤리위 회의로, 이상규 당대표 정책특보 등 김예지·배현진·박정훈·안상훈·우재준·정성국·진종오 의원 등 친한계 의원과 장동혁 대표를 비판한 소장파 의원들을 대상으로 한 징계 요청서 수십 건이 접수된 데서 비롯됐다. 징계 대상은 수십 명에 달하며, 당내 혼란 가능성과 함께 장동혁 대표는 징계를 통해 복당을 영구 금지할 필요가 있다고 주장했고, 윤리위는 당헌·당규 위반 여부를 판단하는 초기 단계에 있다. 현재 당내에서는 징계 정치의 적절성에 대한 논란이 일고 있으며, 일부 의원들은 당내 질서 유지보다는 다수의 여론 억압을 우려하며 혁신의 목소리가 커지고 있다고 지적하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:42'::timestamp,'2026-07-27 17:09:43.501777'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1689,4034,'2026년 월드컵 아시아 지역 예선에서 북한이 32강 진출에 실패했다. 북한은 2026년 월드컵 아시아 3차 예선 A조에서 3경기에서 1승 2패를 기록하며 조 4위에 머물렀고, 32강 진출을 좌절했다. 이로써 북한은 2018년 러시아 월드컵 이후 8년 만에 월드컵 본선 진출에 실패했으며, 2010년과 2022년 월드컵에서도 본선 진출에 실패한 바 있다. 북한은 2026년 월드컵 예선에서 33경기 중 34경기에서 1승을 기록하며 성적 부진을 이어갔고, 향후 국제축구연맹(FIFA)과 아시아축구연맹(AFC)의 규정에 따라 추가 예선 절차를 밟을 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:49'::timestamp,'2026-07-27 16:16:32.651051'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1690,4037,'2026년 월드컵 아시아 지역 예선에서 한국 축구대표팀이 32개국 중 8위로 밀려났다. 이는 2024년 11월 27일 기준으로, 3라운드까지의 성적을 바탕으로 한 결과로, 3승 2무 3패로 11점 기록했다. 현재 한국은 8위에 머물며, 12위까지 진출 가능성이 남아 있지만, 12위 이내에 머물기 위해서는 나머지 3경기에서 최소 6점 이상 확보해야 한다. 이후 12월 11일과 12월 30일 예정된 경기에서 대한민국은 J조와 K조의 상위팀과 맞대결하며, 최종 순위와 12위 진출 여부가 결정될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:18:57'::timestamp,'2026-07-27 16:16:25.364665'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1691,4039,'2024년 3월 27일, 한국 선박 2척이 호르무즈 해협에서 이탈해 총 5척 중 3척이 남아 있는 상태로, 이는 이전에 2척이 탈출한 데 이어 추가적인 이탈을 의미한다. 이는 이란과 이스라엘 간 긴장이 고조되며, 중동 지역 해상 안보가 악화된 배경에서 발생한 것으로, 호르무즈 해협은 전 세계 에너지 수송의 핵심 통로로, 최근 유사한 사건이 반복되며 해상 운송에 영향을 미치고 있다. 현재 남은 한국 선박은 총 3척이며, 이 중 2척은 이란 해상 경비대의 감시를 받고 있으며, 1척은 중립국 지역으로 이동한 것으로 확인됐다. 이후 한국 정부는 해상 안전 확보를 위해 외교적 대응과 해상 경비대의 추가 배치를 검토 중이며, 해양수산부는 선박의 안전한 이동을 위한 국제 협력 강화를 추진할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:19:05'::timestamp,'2026-07-27 16:16:13.481296'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1692,4324,'이병태 대통령 직속 규제합리화위원회 부위원장이 5·18 민주화 운동을 ''성역화''한 것처럼 비판하며 배재고등학교 야구부의 지역 비하 응원에 대해 ''표현의 자유''를 주장한 발언으로 논란이 일었다. 이 부위원장은 2일 페이스북에서 광주제일고와의 경기에서 사용된 ''스타벅스 가야지''라는 응원 구호를 ''역사의 성역화''로 비판하며 북한의 상황과 비교하는 발언을 했고, 이후 삭제 후 4일 다시 글을 올려 표현의 자유의 중요성을 강조했다. 청와대는 4일 공지에서 이 발언이 정부의 혐오·조롱에 대한 단호한 거부 기조와 부합하지 않으며, 책임 있는 공직자로서 부적절하다고 경고했고, 6일에는 이병태 부위원장의 사퇴를 권고했다. 현재 이 부위원장은 거취를 판단 중이며, 이 사건은 표현의 자유와 역사적 민감성 간의 갈등을 여전히 논의의 대상으로 삼고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:19:11'::timestamp,'2026-07-27 16:58:20.152948'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1693,4040,'2026 FIFA 월드컵 아시아 지역 예선에서 한국 축구대표팀은 32강 진출 가능성이 36.04%로 나타났다. 한국은 A조에서 27일까지 5-0 승리를 포함해 3경기에서 3승을 기록하며 조 1위를 유지하고 있으며, 현재 조 2위인 일본과의 승점 차는 3점이다. 조 1위는 32강 직행이 보장되며, 조 2위는 16강 플레이오프를 치러야 하며, 현재 한국은 플레이오프 진출 가능성이 36.04%로 나타났다. 한국은 28일 A조 4차전에서 일본과의 맞대결을 앞두고 있으며, 승리 시 32강 직행이 확정된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:19:19'::timestamp,'2026-07-27 16:16:07.047230'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1694,4041,'미국과 이란은 2023년 9월 26일, 9일 전 체결한 군사적 합의(MOU)를 위반하며 무력 충돌을 재개했다. 이란의 이슬람혁명수비대(IRGC)는 미국의 무인기 격추를 통해 합의 위반을 주장했고, 미국은 이란의 무력 도발을 반박하며 군사적 대응을 강조했다. 이 사건으로 인해 중동 지역의 긴장이 고조되었으며, 이란은 미국의 무인기 격추를 정당화하며 군사적 자율성을 강조했다. 이후 양국은 외교적 대화 재개와 군사적 긴장 완화를 위한 후속 절차를 논의할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:04'::timestamp,'2026-07-27 16:16:00.177222'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1695,4042,'2026 FIFA 월드컵 아시아 2차 예선 D조에서 한국은 26일 호주와 0-0 무승부를 기록하며 32강 진출 가능성이 크게 줄었다. 한국은 이전까지 파라과이와의 경기에서 승리해 32강 진출을 앞두고 있었으나, 호주와의 무승부로 인해 진출 조건을 충족하지 못했다. 현재 한국은 32강 진출 확률이 55.10%로 낮아졌으며, 나머지 2경기에서 승리해야만 진출 가능성이 생긴다. 이후 남은 경기 결과에 따라 진출 여부가 결정되며, 특히 파라과이와의 마지막 경기에서 승리해야만 32강 진출이 가능하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:09'::timestamp,'2026-07-27 16:15:53.351088'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1696,4044,'2025년 6월 16일 일본은행은 정책금리를 0.75%에서 1.0%로 31년 만에 최고 수준으로 인상했다. 이는 다카이치 사나에 총리가 영국·프랑스·이탈리아 순방과 G7 정상회의를 마치며 ''경제안보 동맹 외교''를 강화하는 가운데 이뤄진 것으로, 중국 견제와 영유럽과의 협력을 통한 ''다카이치노믹스 2.0''의 핵심 전략이다. 일본은 2026년도 본예산으로 사상 최대인 122조 엔을 편성하고, 적극 재정을 추진하며, 동시에 금리 인상으로 통화 정상화를 추진하고 있다. 이에 따라 일본의 금리·엔화 향방, 공급망 재편, 동북아 안보 비용 증가 등이 한국 경제에 영향을 미칠 전망이며, 시장과 전문가들은 재정 지속 가능성과 일본은행의 독립성 존중을 주문하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:16'::timestamp,'2026-07-27 16:13:44.643878'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1697,4045,'이란은 2024년 5월 17일, 이란-이스라엘 간의 종전 합의 체결 사흘 만에 호르무즈 해협을 재봉쇄했다. 이는 이란이 2024년 5월 15일 이스라엘과의 합의를 체결한 후, 17일에 해협 통행을 제한하며 군사적 긴장을 높인 조치다. 이란의 호르무즈 해협 재봉쇄로 인해 국제 해상 운송에 영향이 발생했으며, 이스라엘과 미국은 이에 대해 강력히 반발하며 외교적 대응을 준비 중이다. 이후 5월 19일 이란은 해협 통행 제한을 유지하며, 이스라엘과의 관계 악화를 예고하며 추가 조치 가능성도 시사했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:22'::timestamp,'2026-07-27 16:13:38.655367'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1698,4048,'서울시 종로구는 창신소담 공영주차장 및 복합시설이 2일 한국부동산원으로부터 ''장애물 없는 생활환경(Barrier Free)'' 본인증 우수등급을 받았다. 이 시설은 지하 1층에서 지하 5층까지의 주차공간(총 180면, 장애인전용주차구역 4면 포함)과 지상 1층 청소년 소담도서관, 2층 청소년문화의집, 3층 한옥 청소년 문화의집으로 구성되어 있다. 점검 결과, 차량 진입로는 보행통로와 구분돼 있으나 주차현황판에 장애인전용주차구역 안내가 부족했으며, 지상 1층 주출입문은 여닫이로 점자블록 설치로 인해 휠체어 이용 시 불편이 발생했다. 또한 2층 모임룸 책상 높낮이 조절 불가, 3층 한옥 구조로 휠체어 접근 어려움, 세면대 하부 배관 방해, 휴지걸이 높이 등 개선이 필요한 시설이 확인됐으며, 향후 시설 개선 및 정기 점검이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:28'::timestamp,'2026-07-27 16:49:32.517260'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1699,4050,'인천 중증장애인거주시설 색동원 성폭력사건 공동대책위원회(색동원 공대위)는 2일 서울지방법원 앞에서 기자회견을 열어 시설장에 대한 성폭력 재판부에 선입견 없이 공정한 재판을 진행해달라고 촉구했다. 사건은 2023년 인천의 중증장애인거주시설 색동원에서 발생한 성폭력 피해와 관련된 것으로, 피해자의 진술이 유도됐거나 영향을 받았을 가능성에 대한 재판부의 반복적 질문이 논란이 되고 있다. 재판부는 피해자의 진술 형성 과정에 대해 ''아이스브레이킹'', ''권유'', ''압박'' 등을 언급하며 신빙성을 의심하는 발언을 반복했으며, 이에 대해 공대위는 장애인 특성과 시설 내 권력관계를 고려하지 않은 편견적 판단이라고 지적했다. 공대위는 장애인권과 성인지 감수성을 기반으로 한 국제인권기준에 따라 재판이 진행되어야 하며, 향후 재판의 중립성과 공정성에 대한 감시가 필요하다고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:33'::timestamp,'2026-07-27 16:21:15.968972'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1700,4052,'오세훈 서울시장이 2023년 9월 16일 서울시 장애정책 5개년 계획 기자간담회에서 ''권리중심 공공일자리''를 ''기형적인 일자리''라고 표현해 장애계의 강력한 반발을 일으켰다. 이 발언은 장애인 당사자 90여명이 국가인권위원회에 ''수치심과 모욕감''을 느꼈다며 괴롭힘 차별 진정을 제기한 계기가 되었으며, 인권위는 이 진정을 기각했다. 기각 결정에 따라 장애계는 인권위가 유엔장애인권리협약 이행 의무를 방기한 것이라며 사과와 기각 근거 공개를 촉구했고, 오 시장의 발언이 장애인 정책을 비하하는 차별적 표현이라는 점에서 동일한 법리 적용이 이뤄져야 한다는 주장이 제기됐다. 현재까지 인권위는 기각 결정의 구체적 판단 근거를 공개하지 않았으며, 장애계는 차별 인정과 정책 개선을 위한 추가 절차를 예고하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:38'::timestamp,'2026-07-27 16:19:33.310344'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1701,4053,'서울 강남구 율현공원 책쉼터가 2024년 6월 24일 한국장애인개발원으로부터 ''장애물 없는 생활환경(Barrier Free) 본인증 우수등급''을 획득했다. 이는 1층 단층 구조로 건립된 대지 52,143.50㎡ 규모의 시설로, 장애인 편의시설 점검을 통해 접근성 문제를 확인한 결과다. 점검 결과 주출입문은 터치식자동문 1곳과 점자블록 설치로 휠체어 이용 시 불편이 발생했으며, 계단 점자표지판은 한쪽 손잡이에만 설치되어 있어 시각장애인의 이용에 제한이 있었고, 책상 및 세면대는 높낮이 조절이 불가해 휠체어 사용자에게 불편함이 있었다. 현재는 남녀 장애인화장실과 경사로, 음성안내기 등 일부 편의시설이 설치되어 있으나, 직원호출벨 부재, 점자블록 미설치, 배관 구조물로 인한 휠체어 접근 방해 등 개선이 필요한 사항이 남아 있으며, 향후 시설 개선 계획과 추가 점검이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:44'::timestamp,'2026-07-27 16:19:21.163326'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1702,4055,'2025년 4월 17일, HIV 감염인 A 씨가 대구 달서구의 접합 전문병원에서 골절 수술을 거부당한 사건에 대해 장애인차별금지추진연대 등 10개 단체가 국가인권위원회에 진정을 제기했으나, 인권위는 ''HIV 감염인이라는 이유로 수술을 거부했다는 직접적 증거가 없고 피해가 확인되지 않는다''며 진정을 각하했다. A 씨는 수술 거부로 인해 대체 치료도 제공되지 않아 6주간 깁스 치료를 받아야 했으며, 병원 측은 면역계통의 내과적 이유로 수술 불가를 주장했다. 연대는 이 사건이 장애인차별금지법 제2조에 해당하는 장애 상태에 기반한 차별이며, 의료법 제15조에 위반된 진료 거부 행위라며 인권위의 각하 결정을 명백한 행정법 위반으로 지적했다. 현재 공익인권법재단 공감 등 12개 단체는 인권위의 결정을 즉각 철회하고 재조사를 실시할 것을 촉구하며, 이 사건이 취약계층의 구조적 차별을 보여주는 사례라고 강조하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:51'::timestamp,'2026-07-27 16:18:55.513589'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1703,4058,'국가인권위원회는 2022년 유엔 장애인권리위원회의 지적을 바탕으로, 장애여성들이 임신·출산·양육 전 과정에서 정보 부족, 의료 접근성 문제, 사회적 편견 등 교차적 차별을 경험하고 있음을 확인했다. 조사 대상 669명의 장애여성 중 11.3%만이 장애친화 산부인과를 이용했으며, 주요 이유로는 장애친화 산부인과를 모른다는 응답이 48.9%에 달했다. 응답자들은 임신 중 가장 어려운 점으로 ''장애인 맞춤 정보 부족''을 꼽았고, ''자녀를 입양해서는 안 된다''는 인식적 차별이 가장 높은 차별로 인식됐다. 보고서는 장애인복지법과 모자보건법에 모성권 보장 조항을 명시하고, 자기결정권과 양육권, 안전한 양육 환경까지 포괄하는 법제 정비가 필요하다고 제안했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:52:57'::timestamp,'2026-07-27 16:15:30.380627'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1704,4059,'2024년 2월, A병원은 청각장애가 있는 간호사 출신의 보험심사관리사가 육아휴직 후 복직하자 건강검진센터에 배치했으며, 이에 대해 국가인권위원회는 차별 행위로 판단하고 특별인권교육 수강과 인사 매뉴얼 마련, 장애차별 예방교육 실시를 권고했다. 진정인은 병원 업무 중 청각장애가 발생한 후 보험심사 업무를 수행해 왔으나, 복직 후 건강검진센터 업무로 배치되면서 업무 적합성과 차별을 주장했다. 병원 측은 사전 면담을 통해 동의했고, 업무 성격이 유사하며 정원 초과로 인해 추가 배치가 불가능했다며 인권위 권고를 거부했다. 인권위는 병원의 불수용을 유감스럽게 여기며 장애인차별금지법 제42조에 따라 법무부장관에게 통보했으며, 향후 법적 조치 가능성과 제도 개선이 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:01'::timestamp,'2026-07-27 16:15:18.253213'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1705,4063,'국가인권위원회는 2025년 9월, 정신의료기관에 전과된 환자가 1개월 이상 다른 병원에서 치료를 받은 후 복귀할 경우 보호의무자 2명 이상의 동의와 전문의 진단을 거쳐야 입원 절차를 다시 진행해야 한다고 판단했다. 이는 정신건강복지법 제43조 및 국립정신건강센터의 안내에 따라 전과 기간이 30일 이상일 경우 퇴원 처리가 원칙이기 때문이며, 해당 병원은 2025년 5월부터 9월까지 3개 병원에서 치료를 받은 진정인을 복귀 시 배우자 1명의 동의만으로 입원시켰다. 인권위는 이 과정에서 보호의무자 2명 이상의 동의와 전문의 진단이 이뤄지지 않아 신체의 자유 침해로 인권 침해로 판단했으며, 병원장에게 퇴원 신청 시 즉시 퇴원 처리하고 직원 대상 입·퇴원 절차 교육을 실시할 것을 권고했다. 이 사건은 정신질환자 입원 절차의 법적 준수 여부와 보호의무자 수의 중요성에 대한 제도적 쟁점으로 이어지고 있으며, 향후 병원의 절차 개선과 교육 시행 여부가 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:07'::timestamp,'2026-07-27 16:13:51.379797'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1706,4064,'19일 장애인교육아올다를 비롯한 10개 단체는 국가인권위원회 앞에서 장애 등 특별지원이 필요한 아동·청소년의 교육권 차별 문제를 이유로 집단 진정을 제기했다. 이들은 건강장애와 중증식품알레르기, 최중증뇌병변장애, 발달장애, 청각장애 등 다양한 장애 유형의 학생들이 어린이집 입학 거부, 각서 요구, 수어 통역 부재, 의료 지원 인력 부족 등으로 교육 현장에서 배제되고 있다고 주장했다. 특히 중증식품알레르기 학생은 외식을 한 번도 하지 못했고, 학부모가 매일 도시락을 준비하거나 학교에 상주해야 했으며, 현장체험학습과 방과 후 수업 참여도 부모 동행 없이는 불가능한 상황이었다. 이들 단체는 인권위의 면담 조사와 포럼을 통해 교육기본권 침해 문제를 지속적으로 제기하고, 정부가 전담간호사 배치, 특수교육지원인력 확충, 평생교육 기관 설치 등 근본적 대안을 마련할 것을 촉구했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:14'::timestamp,'2026-07-27 16:12:52.439161'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1707,4066,'2024년 4월 22일, 전국장애인부모연대 등이 모인 대책위가 대법원 앞에서 학대피해 장애인의 권리보장을 위해 제3자 녹음금지 예외를 인정할 것을 촉구하는 1차 집회를 예고했다. 이는 자폐성 장애아동 학대 의심 사건에서 어머니가 교실 내 발언을 녹음한 행위가 통신비밀보호법 위반 여부를 놓고 1심은 증거능력을 인정했으나 2심은 이를 배제해 무죄 판결이 나면서 발생한 법적 쟁점이다. 현재 대법원은 해당 사건을 계류 중이며, 녹음이 학대 피해 입증의 유일한 수단이 되는 중증장애인·치매노인 등에 대한 일률적 증거 배제는 헌법상 실질적 평등과 인권 보호에 반한다는 지적이 제기되고 있다. 대책위는 미국·영국·독일·일본 등 주요국의 사례를 들어 사안별로 녹음 증거의 허용을 촉구하며, 법률가 112명이 의견서를 제출해 헌법합치적 해석을 요구했고, 온라인 탄원서 모집도 진행 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:20'::timestamp,'2026-07-27 16:12:00.437455'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1708,4067,'2024년 6월 17일, 한국피플퍼스트와 장애인차별금지추진연대 등은 청와대 분수대 앞에서 기자회견을 열어 이재명 대통령의 발달장애인 참정권 관련 발언에 대해 ''정부와 함께 제도 개선을 만들어가겠다''는 입장을 밝혔다. 이 대통령은 6월 29일 사전투표 당시 발달장애인 활동가들이 제출한 편지를 경청했으며, 취임 1주년 기자회견에서 그림투표용지 도입은 ''현실적으로 불가능''하다고 밝혔지만, 소수자 보호를 위한 투자와 지출은 낭비가 아니며 참정권 보장을 위한 다른 방안을 모색해야 한다고 강조했다. 이후 17일 대통령비서실과의 면담에서 발달장애인들은 이해하기 쉬운 선거자료, 그림투표용지, 공적 투표보조인, 모의투표 전국 실시 등 구체적 제도 개선을 제안했고, 비서실 측은 자료 검토 중이며 추가 면담을 통해 구체적 방안을 논의하겠다고 약속했다. 현재까지는 구체적 시행 계획은 없지만, 당사자와 정부 간 지속적인 대화 구조 마련이 필요하다는 점에서 향후 제도적 논의의 지속성과 실질적 변화가 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:27'::timestamp,'2026-07-27 16:11:34.868351'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1709,4068,'한국장애인고용공단과 한국사회적기업진흥원은 7일 서울 소재 진흥원 대회의실에서 ''장애인 표준사업장과 사회적기업의 판로 활성화를 위한 업무협약''을 체결했다. 이번 협약은 장애인 표준사업장과 사회적기업의 경제적 자립과 사회적 가치 창출을 목표로 하며, 판로개척을 위한 ''같이일터''와 ''가치장터'' 연계, 사회적기업 인증교육 지원, 우선구매제도 강화 및 지역 기반 인프라 구축을 주요 내용으로 한다. 양 기관은 협약을 통해 표준사업장의 판로 확대와 장애인 고용 확대를 추진하며, 특히 ''같이일터''와 ''가치장터'' 플랫폼을 활용한 공동 홍보 및 구매 촉진을 계획하고 있다. 이후 협약 이행 상황 점검과 함께, 지역별 협력 모델 확산 및 정부 지원 정책과의 연계 방안이 후속 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:31'::timestamp,'2026-07-27 18:25:02.435254'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1710,4069,'2025년 기준 전국 226개 기초지방자치단체 중 139개(61.5%)가 장애인 의무고용률(3.8%)을 달성하지 못한 것으로 나타났다. 장애인고용촉진 및 직업재활법에 따라 지자체는 일정 비율 이상의 장애인을 고용해야 하며, 이는 장애인의 노동권 보장과 지역사회 자립 가능성을 나타내는 지표로 평가된다. 전라남도 보성군(1.14%)이 가장 낮은 고용률을 보였고, 부산광역시 연제구(5.85%)가 가장 높았다. 서울·부산·광주·대전·울산은 모두 의무고용률을 충족했으나, 수도권과 일부 지방권에서는 대부분의 지자체가 미달 상태이며, 향후 지자체별 맞춤형 공공일자리 확대와 법적 의무 이행 강화가 필요하다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:35'::timestamp,'2026-07-27 18:21:19.004914'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1711,4072,'고용노동부 주최, 한국장애인고용공단 주관으로 2026년도 수도권 발달장애인기능경기대회가 1일 일산직업능력개발원에서 개최됐다. 이번 대회는 전국 4개 권역 대회 중 첫 번째로, 데이터 입력, 바리스타, 사무행정, 영상콘텐츠편집, 요양보호보조, e스포츠 등 6개 직종에서 총 149명의 발달장애인이 참가해 기능을 겨뤘다. 대회 결과 금메달 6명, 은메달 5명, 동메달 5명 등 총 16명이 입상했으며, 이는 발달장애인의 직업능력 향상과 사회참여 촉진을 위한 기반을 마련하는 계기가 됐다. 다음 단계로는 나머지 3개 권역 대회가 순차적으로 진행될 예정이며, 입상자들은 전국대회 진출 자격을 갖게 된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:39'::timestamp,'2026-07-27 16:21:33.423702'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1712,4075,'2024년 기준 장애인기업 수는 17만5176개사로 전년 대비 0.5% 증가했으며, 이 중 92.1%가 소상공인이다. 조사에 따르면 장애인기업은 금융지원(71.3%)과 세제지원(49.8%)을 가장 필요로 하는 정책으로 꼽았으며, 전체 종사자 수는 58만6595명, 장애인 종사자 수는 18만5821명으로 전체의 31.7%를 차지했다. 매출총액은 70조 1830억원, 영업이익은 6조 6316억원으로 각각 전년 대비 0.8%, 1.5% 증가했다. 중소벤처기업부는 이번 조사 결과를 바탕으로 금융·판로 등 맞춤형 지원을 강화할 계획이며, 장애인기업의 지속적 성장을 위한 정책 수립이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:44'::timestamp,'2026-07-27 16:18:25.111171'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1713,4076,'2026년도 발달장애인기능경기대회가 7월 1일부터 10일까지 수도권, 중부권, 영남권, 호남권 등 전국 4개 권역에서 순차적으로 개최된다. 이 대회는 고용노동부 주최, 한국장애인고용공단 주관으로 매년 열리며, 발달장애인의 기능 향상과 직업적 자긍심 고취를 목적으로 한다. 경기 직종은 데이터입력, 바리스타, 영상콘텐츠편집, 사무행정 등 4개 기본직종과 e스포츠, 요양보호보조 등 2개 특화직종으로 구성되며, 입상자에게는 상장과 상금이 수여되고, 기본직종 입상자는 9월 부산에서 열리는 전국장애인기능경기대회 참가 자격을 부여받는다. 대회 관련 세부 사항은 한국장애인고용공단 홈페이지 또는 능력개발지원부를 통해 확인할 수 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:48'::timestamp,'2026-07-27 16:18:13.808897'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1714,4079,'2026년도 지방장애인기능경기대회가 24일부터 26일까지 전국 17개 시도에서 개최되며, 정규직종 17개, 시범직종 5개, 레저직종 3개 총 25개 직종에서 2766명의 장애인 선수가 참가한다. 이 대회는 고용노동부 주최, 한국장애인고용공단과 한국장애인고용안정협회 주관으로, 지역 내 우수 기능장애인을 발굴하고 장애인 고용 인식 제고 및 고용 촉진을 목적으로 한다. 참가자 중 정규직종 금상 수상자는 2026년 부산광역시에서 열리는 전국장애인기능경기대회 출전 자격을 부여받으며, 입상자에게는 상장, 메달, 상금(정규직종 최고 50만원)과 기능사 실기시험 면제 혜택이 주어진다. 이후 2026년 부산 전국대회 참가 자격 부여 및 기능사 면제 등 후속 혜택이 시행되며, 장애인 직업능력 향상과 고용 기회 확대를 위한 제도적 지원이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:53'::timestamp,'2026-07-27 16:14:28.606914'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1715,4080,'2026년 5월 장애인기업종합지원센터는 장애인기업의 경기 체감 지수(BSI)가 전월 대비 2포인트 상승한 95.7p, 6월 경기 전망 지수는 2.6포인트 상승한 101.9p로 나타났다. 이는 전반적인 경기 회복세를 반영하며, 강원권과 수도권, 경상권 등 주요 지역과 제조업, 서비스업 등 업종에서 상승세를 보였으나 충청권과 제주권 등 일부 지역과 도소매업, 건설업은 하락했다. 장애 정도별로는 심한 장애 기업의 체감 지수가 93.1p에서 7.9포인트 상승했으며, 전망 지수는 105.7p로 중증 장애 기업의 회복세가 두드러졌다. 센터는 내수 변화에 대응하기 위해 공영홈쇼핑 및 경기청년복지몰 연계 사업을 확대하고, 해외 온라인 쇼핑몰 입점 지원과 수출상담회 규모 확대를 통해 판로 다각화를 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:53:58'::timestamp,'2026-07-27 16:14:17.714659'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1716,4083,'한국장애인고용공단과 강동대학교는 2024년 4월 16일 강동대학교에서 장애대학생 취업역량 강화 및 취업 활성화를 위한 업무협약을 체결했다. 이번 협약은 장애대학생의 취업 장벽을 낮추고 기업 수요에 부합하는 인재를 양성하기 위해, 공단의 전문성과 강동대학교의 교육 인프라를 결합하려는 목적을 가졌다. 양 기관은 장애대학생 인력풀 구축, 전문가 연계, 진로·취업 상담, 맞춤형 취업지원 등 다양한 분야에서 협력할 예정이며, 이를 통해 장애대학생의 취업률 향상과 사회적 자립을 목표로 하고 있다. 향후 협약 이행 상황과 효과에 따라 장애인 고용 활성화 모델의 확산 여부와 정부 정책에 대한 반영 가능성 등이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:02'::timestamp,'2026-07-27 16:11:16.863291'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1717,4085,'국회예산정책처는 민간기업의 장애인 고용 확대를 위해 기업 규모별 차등 적용과 완전미고용기업에 대한 고용부담금 중과를 검토해야 한다고 제안했다. 우리나라 장애인 고용률은 2023년 기준 48.3%로 독일·프랑스·영국보다 낮으며, 2024년 민간기업 의무고용이행률은 42.4%로 전년 대비 감소 추세다. 특히 근로자 100인 미만 기업의 고용이행률은 32.0%로 하락하고, 완전미고용기업 비중이 33.4%에 달해 소규모 기업의 고용 기반이 취약한 상황이다. 국회는 2026년까지 의무고용률을 공공 3.8%, 민간 3.1%로 상향하고, 독일·프랑스 사례를 참고해 완전미고용기업에 대한 부담금 중과 및 기업 규모별 차등 적용 방안을 도입할 필요성을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:08'::timestamp,'2026-07-27 16:09:52.507469'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1718,4086,'2026년도 대기업 장애인 고용촉진 협의체 간담회에서 한국장애인고용공단은 장애인 고용컨설팅 사업의 추진 방향을 논의했다. 이는 장애인 고용 확대와 고용 유지 지원을 위한 기업과의 협력 강화를 목적으로 하며, 2026년도 사업의 운영 개선과 장애 대학생의 노동시장 진입 지원 방안을 중심으로 논의되었다. 현재까지 장애인 고용컨설팅 사업은 기업의 고용 안정성 제고와 장애 근로자의 장기근속을 목표로 하고 있으며, 현장에서의 개선 필요성과 컨설팅의 지속 가능성에 대한 의견이 제기되었다. 향후 공단은 협의체와의 지속적 소통을 통해 장애인 고용 친화적 환경 조성과 정책 발전 방향을 모색할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:12'::timestamp,'2026-07-27 16:09:43.540377'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1719,4607,'광주제일고와 광주서중·일고 총동창회가 5·18 민주화운동을 조롱한 배재고 야구부에 대한 6개월 출전정지 징계에 대해 선처를 요청했다. 이는 배재고 학생들이 5·18 민주화운동을 조롱하는 응원을 한 사건으로 인해 대한야구소프트볼협회가 1일 배재고 야구부 전체에 6개월 출전정지 처분을 내린 데 따른 후속 조치다. 광주제일고 교장과 총동창회는 학생들의 사과와 참배를 확인하며 교육적 회복과 스포츠맨십 회복을 강조하며 재심 절차를 통한 징계 완화를 기대하고 있다. 배재고는 재심 신청 기한인 8일까지 재심 여부를 논의 중이며, 재심 절차는 최소 2개월 이상 소요될 것으로 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:17'::timestamp,'2026-07-27 18:59:11.876718'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1720,4087,'한국장애인고용공단과 한국고용정보원은 2024년 4월 9일 공단 본부에서 차세대 인공지능(AI) 고용서비스 협력체계 구축을 위한 업무협약을 체결했다. 이는 장애인 고용서비스의 디지털 혁신을 위해 공단의 장애인 취업지원 데이터와 고용정보원의 AI 분석·매칭 기술을 결합하려는 목적에서 비롯됐으며, 기존 서비스의 접근성과 효율성을 높이기 위한 공동 추진 계획이다. 협약에 따라 AI 기반의 취업 매칭 시스템 개선, 데이터 기반 맞춤형 서비스 제공, 디지털 접근성 향상 등이 추진되며, 장애인의 채용 확대와 고용안정을 목표로 하고 있다. 이후 양 기관은 협력 체계의 구체적 실행 방안을 마련하고, 2024년 하반기 중 시범 서비스를 도입할 예정이며, 서비스 효과에 따라 전국 확대가 검토된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:21'::timestamp,'2026-07-27 16:09:28.328566'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1721,4091,'더불어민주당 전국장애인위원회와 서미화 의원실은 2024년 5월 29일 이룸센터에서 2026 지방선거 장애인 당선자를 대상으로 한 워크숍을 개최했다. 이번 워크숍은 장애인 당선자들의 의정 역량 강화를 위해 예산·결산 검토, 조례 제정, 행정사무감사 등 실무 중심 교육을 진행하며, 장애 당사자의 목소리가 지역사회에 실질적으로 반영될 수 있도록 지원하는 데 목적을 뒀다. 서미화 위원장과 김용석·정병기 전 의원 등이 강사로 참여해 조례 개정, 예산감시, 행정감사 활용 등 현장 중심의 전문 지식을 공유했으며, 참석자들은 워크숍을 통해 실질적인 의정 역량을 강화하는 데 기여했다. 이후 전국장애인위원회는 당선자들이 지역에서 유능한 민생 정치인으로 성장할 수 있도록 정책 지원과 연대 활동을 지속할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:26'::timestamp,'2026-07-27 16:18:37.390521'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1722,4092,'국민의힘 김예지 의원은 장애인학대범죄자 및 성범죄자 전력자가 중증장애인 근로지원인으로 활동하지 못하도록 하는 ''장애인복지법 일부개정법률안''을 29일 대표발의했다. 현재 법은 장애인학대나 성범죄 전력자가 장애인관련기관에 취업하는 것을 제한하고 있으나, 근로지원인 서비스 제공기관은 제외되어 사각지대가 존재했으며, 이로 인해 범죄경력 조회가 법적 근거 없이 거부되는 사례도 발생했다. 개정안은 ''장애인고용촉진 및 직업재활법''에 따른 근로지원인 채용 기관을 취업제한 대상에 포함함으로써 전국 136개 근로지원인 수행기관의 제도적 공백을 해소할 예정이다. 이후 법안은 국회 보건복지위 심사 절차를 거칠 예정이며, 장애인 안전과 권리 보장을 위한 제도적 기반 마련이 핵심 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:30'::timestamp,'2026-07-27 16:17:37.443636'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1723,4094,'국민의힘 김예지 의원은 26일 중증장애인 기업 대표자도 업무지원인 서비스를 받을 수 있도록 하는 ''장애인기업활동 촉진법 일부개정법률안''을 대표발의했다. 현행법은 중증장애인 기업 대표자를 근로자로 보지 않아 업무지원인 제도 대상에서 제외해 왔으며, 소규모 기업(종사자 10명 이하) 중 94.3%가 중증장애인 대표자인 것으로 조사됐다. 이로 인해 대표자가 업무를 수행하는 데 어려움을 겪고 있으며, 업무지원인 서비스를 받을 수 없어 경영 부담이 크다. 이번 개정안은 소상공인인 장애인기업 대표자를 업무지원인 지원 대상에 포함시켜 영세 기업 대표자의 경영 안정성을 높이고, 후속적으로 예산 및 지원체계 확충이 필요하다는 점이 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:34'::timestamp,'2026-07-27 16:15:51.469630'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1724,4100,'국회는 2024년 3월 18일 ''특수교육법'' 일부개정안을 통과시켜 각 시도 교육감이 매년 특수학급 설치 계획을 교육부 장관에게 제출하도록 의무화했다. 기존 법은 특수학교 및 각급학교의 특수학급 설치 기준을 정했지만, 교육청의 대응 부족으로 학교 현장에서 수요에 비해 학급이 부족한 문제가 지속됐다. 이번 개정으로 지역별 특수교육 수요를 반영한 연차별 계획 수립이 법적으로 보장되며, 장애학생의 원거리 통학 문제 해소와 교육 환경 개선이 기대된다. 이후 교육부는 각 교육청의 계획을 검토하고, 특수교육 연차보고서에 반영하는 절차를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:38'::timestamp,'2026-07-27 16:12:16.787730'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1725,4128,'정이한 전 개혁신당 부산시장 후보가 6·3 지방선거 당시 음료 피습 사고를 자작극으로 꾸며 선거운동을 한 혐의로 구속영장이 청구됐다. 이 사건은 2024년 4월 27일 부산 금정구에서 발생한 것으로, 정 전 후보가 승용차에서 뿌려진 음료수를 맞아 뇌진탕 진단을 받았다고 주장했으나, 경찰은 사전 통화 기록과 휴대전화 포렌식을 통해 자작극 의혹을 확인했다. 검찰은 위계공무집행방해 및 공직선거법 위반 등 혐의로 정 전 후보와 공모한 A씨(30대, 전 헬스 트레이너)에 대해 구속영장을 신청했으며, 영장심사는 2024년 5월 8일 부산지방법원에서 진행된다. 현재 경찰은 정 전 후보의 학력 논란, 여론조사 조작 의혹, 부친 계열사 직원 선거운동 동원 등 추가 조사를 진행 중이며, 정 전 후보는 사건 보도 전 탈당 및 정계 은퇴를 선언했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:43'::timestamp,'2026-07-27 18:40:10.529617'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1726,4104,'이정헌 더불어민주당 의원은 2024년 5월 9일 장애인 최저임금 적용 제외 규정 폐지를 골자로 한 ''장애인 소득·안전 보장 3법''을 대표발의했다. 현행 최저임금법 제7조는 정신·신체장애로 근로능력이 현저히 낮은 사람에 대해 고용노동부장관 인가를 받으면 최저임금 적용을 제외할 수 있도록 규정하고 있으며, 이는 1988년 최저임금법 시행 이후 38년간 유지되어 왔다. 이번 개정안은 최저임금을 장애 여부와 관계없이 모든 근로자에게 전면 적용하도록 제도를 개선하고, 중증장애인 고용을 유도하기 위해 고용노동부장관이 임금 일부를 지원할 수 있도록 근거를 마련했다. 또한 다중이용시설의 피난안내도 점자 제작과 피난안내 영상에 한국수어 통역·자막 제공을 의무화하고, 위반 시 과태료 부과 조항을 신설해 장애인의 안전권 보장을 강화했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:48'::timestamp,'2026-07-27 16:09:35.917792'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1727,4105,'이재명 대통령은 8일 취임 1주년 기자회견에서 발달장애인들이 요구한 그림투표용지 도입에 대해 ''현실적으로 불가능하다''고 밝혔다. 발달장애인 활동가들은 2016년부터 이해하기 쉬운 선거자료, 그림투표용지, 투표보조, 모의투표 환경 접근권 보장을 요구해 왔으며, 지난 29일 사전투표 후 이 대통령과 면담해 이 같은 제도 개선을 요청했다. 대통령은 전국 사전투표소에서 출마자가 1만 명 이상인 상황에서 모든 후보자 사진을 그림투표용지에 반영하는 것은 현실적 불가능하다고 판단했으며, 전자투표 방식을 고려할 수 있다고 제안했다. 이후 전자투표 도입의 실현 가능성과 부정투표 우려, 소외계층의 참정권 보장 방안에 대한 후속 논의가 필요하다는 점이 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:52'::timestamp,'2026-07-27 16:09:21.860468'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1728,4106,'4일 국회 보건복지위원회 소속 최보윤 의원은 ''장애인권리보장법 제정, 그 이후''라는 주제로 장애계와 긴급 간담회를 개최했다. 이번 간담회는 최근 국회 본회의를 통과한 장애인권리보장법의 실질적 이행을 위해 하위법령 제정과 장애인복지법 전부개정 등 법제 정비 방향을 모색하기 위해 마련됐다. 참석자들은 장애 정의의 사회적 모델 확대, 장애수당의 소득과 무관한 보전, 탈신청주의 복지 체계 도입, 생애주기별 지원 확대, 장애 분리 통계 도입 등 구체적 개정 방향을 제안했으며, 행정 혼선을 막기 위해 권리 중심의 제도 연계 필요성을 강조했다. 최 의원은 간담회에서 도출된 의견을 후속 입법 과정에 반영하고, 보건복지부와 장애계 간 정례 소통 창구를 신속히 가동해 유엔 장애인권리협약 정신을 국내 법제에 실현할 계획이라고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:54:57'::timestamp,'2026-07-27 16:08:51.413130'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1729,4108,'목포시의회는 6일 제13대 전반기 의장단을 구성하며, 민주당 소속 의원들이 의장과 부의장, 상임위원장 5개 직책을 전부 차지했다. 전남광주통합시 목포시의회는 민주당 15석, 정의당 2석, 진보당 1석, 조국혁신당 1석, 무소속 3석 등 총 22석으로 구성되어 있으며, 비민주계 7석(31.8%)은 의장단 및 상임위원장단에서 완전히 배제됐다. 이에 따라 민주당의 의장단 ''전석 독식''이 울산시의회와 같은 의석 구조에서도 협치를 선택한 사례와 대비되며, 무소속 손혜원 의원을 포함한 비민주계 의원들로부터 견제 기능 상실과 소수의견 배제에 대한 비판이 제기됐다. 이후 7일 개원식을 개최하며, 다수당 독식과 소수의견 반영 문제에 대한 향후 논의와 협치 방식의 재고가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:03'::timestamp,'2026-07-27 17:10:13.507818'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1730,4114,'제13대 제주도의회 더불어민주당은 김대진 의원을 원내대표로 선출하고, 수석부대표 양경호, 정책위의장 강명균, 부대표 장정훈·박안수·오경남, 대변인 고석준·오은초로 구성된 제1기 원내대표단을 확정했다. 이는 제주도의회가 2024년 7월 1일 제13대 의회로 개원한 후 여당으로서의 교섭단체 운영을 위한 조직 구성을 마무리한 것으로, 전문성과 경험을 갖춘 인물들로 팀을 구성해 소통과 협력을 중시하는 운영 체계를 구축했다. 현재 원내대표단은 의원 간 소통 창구로서의 역할과 정책 역량 강화를 통해 제주도민의 삶을 최우선으로 하는 정책 마련과 집행부와의 건전한 협력·견제를 추진하고 있다. 향후 원내대표단은 제주도정의 정책 추진에 대한 견제와 협력, 민생 안정 및 제주 발전을 위한 의정 활동의 성과를 높이기 위한 구체적 정책 제안과 의회 운영 방향을 수립할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:07'::timestamp,'2026-07-27 16:40:32.032520'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1731,4115,'제주특별자치도의회는 2024년 4월 2일 제13대 의회 개원식을 개최하고, 송영훈 의장이 의장으로 선출된 후 상임위원장 선거를 진행했다. 이는 1일 제1차 본회의에서 의장단을 구성한 데 이어, 의정활동을 본격화하기 위한 절차로, 전반기 상임위원장 7명이 선출됐다. 개원식 이후 의원들은 국립제주호국원과 제주4·3평화공원을 참배하며 책임 있는 의회 운영을 다짐했으며, 송영훈 의장은 민생 중심, 미래지향, 도민 신뢰를 기반으로 한 ''행동하는 의회''를 목표로 제시했다. 이후 제13대 의회는 민생 정책과 지역 현안 해결을 위한 상임위원회 활동을 본격화할 예정이며, 정파 간 협력과 소통을 통한 의정 활동의 질적 향상이 주요 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:12'::timestamp,'2026-07-27 16:40:24.459488'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1732,4610,'2017년 7월부터 2023년 10월까지 대상, 사조CPK, CJ제일제당 등이 전분 및 당류 가격을 담합한 혐의로 재판에 넘겨진 사건의 첫 공판이 7일 서울중앙지법에서 열렸다. 이 사건은 담합 기간 동안 전분 가격이 최고 73.4%, 당류 가격이 최고 63.8% 인상되며 약 10조 1520억원 규모로 국내 식료품 담합 중 역대 최대 규모였다. 대상 대표 임모 씨는 공소사실을 전면 부인하며 직원들의 담합 보고나 승인 사실이 없다고 주장한 반면, 사조CPK와 CJ제일제당은 대부분의 혐의를 인정하고 반성하는 입장을 밝혔다. 다음 공판준비기일은 내달 25일 오전 10시로 지정되었으며, 법인 및 개인의 책임 범위, 퇴직 임직원의 행위에 대한 법적 판단이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:17'::timestamp,'2026-07-27 18:48:32.954589'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1733,4116,'이재명 대통령은 2024년 7월 5일 미국 독립 250주년을 맞아 공식 X 계정을 통해 트럼프 대통령과 미국 국민에게 축하 인사를 전하며 한미동맹의 새로운 도약을 강조했다. 이는 한국전쟁 당시 미국의 희생을 기리며 70년 이상 지속된 한미 안보 동맹의 가치를 재확인하는 것으로, 최근 안보를 넘어 경제, 첨단기술, 에너지, 원자력, 인공지능 등 미래 분야로 협력 영역을 확대하고 있는 상황이다. 현재 한미동맹은 군사적 협력뿐 아니라 기술·에너지 분야에서의 공동 연구 및 투자 확대를 추진 중이며, 양국은 2025년까지 협력 프로젝트를 정비할 계획이다. 이에 따라 한미동맹의 지속 가능성과 미래 협력 방향에 대한 논의가 정책 회의와 외교적 대화를 통해 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:21'::timestamp,'2026-07-27 16:34:57.525901'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1734,4117,'2024년 3월 3일 추미애 경기도지사는 광주 병원 간호사의 ''태움'' 사망 사건을 계기로 경기도의료원 산하 6개 병원(수원·의정부·파주·이천·안성·포천)에 직장 내 괴롭힘 실태 전면 점검을 지시했다. 이는 병원 내 위계적 폭력과 괴롭힘 문화가 뿌리내린 상황에서 발생한 피해 사례로, 피해자에 대한 안타까움과 함께 ''태움''을 교육이 아닌 명백한 직장 내 괴롭힘으로 규정한 것이 배경이다. 점검은 익명 상담과 현장 면담을 통해 진행되며, 도내 120여명의 마을노무사를 통해 노동자 권리구제를 지원하고, 2024년 170명, 2025년까지 총 562명 규모의 지방노동감독관 조직을 차질 없이 구축할 예정이다. 이후 3년간 소규모 사업장과 취약 노동현장을 중심으로 임금체불, 부당한 근로조건, 산업안전 기준 위반, 직장 내 괴롭힘 등 반복적 문제를 예방하는 방향으로 정책을 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:26'::timestamp,'2026-07-27 16:34:38.955976'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1735,4120,'이재명 대통령의 국정 수행 지지율이 한국갤럽의 6월 30일~7월 2일 조사에서 전주 대비 3%p 상승한 54%를 기록했다. 이는 취임 후 최저 지지율을 기록한 전주 조사 이후 회복세를 보인 것으로, 긍정 평가의 주요 이유는 경제·민생(24%), 외교(14%), 전반적 수행(8%) 순이었다. 부정 평가는 36%로 5%p 하락했으며, 정당 지지도는 더불어민주당 41%, 국민의힘 26%로 나타났다. 한성숙 국무총리의 적합 여부에 대한 평가는 31%가 적합하다고 답했고, 46%는 판단을 유보했으며, 정치적 성향에 따라 의견 차이가 나타났다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:30'::timestamp,'2026-07-27 16:22:39.228506'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1736,4123,'국회 6·3 지방선거 투표용지 부족 사태 국정조사 특별위원회(국조특위) 의원들은 2일 서울 송파구 올림픽공원 핸드볼경기장 개표소에 27일 만에 진입했다. 이는 지난 5월 5일 잠실7동 제2투표소 투표함이 개표소로 이동된 후 시민들이 투표용지 부족과 부정선거 우려를 이유로 봉쇄 시위를 시작한 지 27일 만의 현장 조사였다. 경찰은 대화경찰 100여명, 형사 300여명, 기동대 25개 부대 등 약 1600명을 배치해 의원들의 진입로를 확보했으며, 시위대와의 몸싸움과 충돌이 발생했다. 현재 개표소에는 투표록 104부, 투표함 4개, 투표지 보관 상자 428~434박스, 개표 관련 비품 및 서류 등이 보관되어 있으며, 국조특위는 이날 투표용지 관리 및 사태 대응 상황을 조사할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:36'::timestamp,'2026-07-27 16:21:03.219517'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1737,4125,'제13대 목포시의회 개원 전, 더불어민주당이 의장단과 상임위원장 자리를 모두 독점하려는 방침을 내세우며 원 구성 논란이 발생했다. 이번 지방선거에서 비민주당이 전체 의석의 약 3분의 1을 차지한 점을 고려하면 시민의 다양한 목소리 반영이 필요하다는 주장이 제기되었으며, 정의당·조국혁신당·진보당·무소속 의원 7명은 이를 ''시민의 선택을 무시한 일당 독식''이라며 반발했다. 민주당은 과거 협치 실패를 이유로 배려 없이 원 구성 독점을 주장했으나, 손혜원 무소속 의원은 이에 대해 ''사실 왜곡''이라며 협치를 위한 제안이 있었음을 밝히며 민주당의 배제 논리를 반박했다. 현재 이 논란은 단순한 자리 배분을 넘어 지방의회의 대표성과 협치 원칙에 대한 논의로 확대되었으며, 민주당이 과반 의석을 확보했음에도 다당 구도를 반영하지 않으면서 정치적 갈등이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:42'::timestamp,'2026-07-27 16:20:56.407384'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1738,4126,'2026년 지방선거 기간 중 언론 보도가 이주민 혐오를 확산시켰다는 조사 결과가 나왔다. 인권운동네트워크 바람은 2024년 2월 1일부터 2024년 6월 5일까지 국내 주요 언론의 보도 817건을 분석해, 이주민에 대한 혐오를 조장하는 기사 51건을 발견했으며, 이 중 45건이 선거 전 의제 형성기(2월 1일~5월 20일)에 집중됐다. 특히 정치인의 혐오 발언을 그대로 인용한 보도가 24건(47%)으로 가장 많았으며, 외국인 여론 왜곡 방지법, 원정투표 금지법 발의 등이 주요 사례로 나타났다. 이주민을 ''민주주의 위협''이나 ''잠재적 범죄자''로 묘사한 보도와 정주 이주민의 권리 의제 무시, 경제적 이익이 없는 이주민에 대한 배제적 시각이 지속된 것으로 분석됐으며, 이에 따라 언론의 인권보도준칙 실천과 이주민 정책 수립이 시급하다는 지적이 제기됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:48'::timestamp,'2026-07-27 16:20:46.960362'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1739,4127,'이재명 대통령과 문재인 전 대통령은 2024년 1월 1일 청와대 상춘재에서 오찬 회동을 갖고 민주진영의 단합과 국민통합을 강조했다. 이는 더불어민주당 전당대회를 앞두고 친문재인·친이재명계 간 내분이 심화되며 당내 갈등을 수습하기 위한 행보로, 국정 현안과 검찰개혁, 한반도 평화, 지방 주도 성장 등 주요 정책 방향에 대해 의견을 나누었다. 두 전·현직 대통령은 검찰개혁의 속도감과 국민 피해 최소화, 수도권 집중 해소를 위한 호남 반도체 클러스터 투자 등 구체적 정책에 공감하며, 수시 소통을 통해 국정 전반을 협력하기로 했다. 이후 민주진영 내부 단합과 외연 확장의 조화, 특히 청년 문제 해결과 국가균형 발전을 위한 정책 추진이 주요 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:53'::timestamp,'2026-07-27 16:20:39.649838'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1740,4131,'검찰은 광주 여고생 살인 사건과 관련해 광산경찰서에 대한 압수수색을 7일 실시하며, 공무상비밀누설 및 증거인멸 혐의로 경찰 관계자들을 입건했다. 사건은 2023년 5월 5일 발생했으며, 장윤기(23세)가 피해자를 납치·살해한 혐의를 받고 있으며, 범행 시 사용된 케이블타이가 차량 압수수색 과정에서 발견되지 않은 것으로 확인됐다. 검찰은 김봉진 형사1부장을 팀장으로 하는 전담팀을 구성해 수사 중이며, 광산경찰서 수사팀장 A 경감을 증거인멸 혐의로 긴급 체포했고, 경찰청은 수사 주체를 국가수사본부로 격상해 인력을 파견했다. 현재 검찰은 증거 인멸 정황과 수사 기밀 유출 여부를 심층 조사하고 있으며, 향후 수사 결과에 따라 추가 입건 및 책임 소재 규명이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:55:58'::timestamp,'2026-07-27 18:20:31.447749'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1741,4135,'20대 남성 A씨가 김포시의 한 아파트에서 마약을 투약한 혐의를 받고 7일 부모의 신고로 경찰에 긴급체포됐다. A씨는 마약류 관리에 관한 법률 위반 혐의를 받으며, 현장에서 투명 비닐봉투에 담긴 하얀 가루와 주사기 3개를 발견했고, 소변 검사에서 필로폰 양성 반응이 나왔다. 경찰은 마약 소지 및 투약 사실을 확인하고, 범행 경위를 조사한 뒤 구속영장 신청을 검토할 예정이다. 이후 A씨에 대한 수사 결과와 구속 여부, 마약 중독 치료 및 가족 간 관리 방안에 대한 사회적 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:01'::timestamp,'2026-07-27 18:09:34.511325'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1742,4151,'2018년 8월 28일, 도널드 트럼프 미국 대통령이 FIFA 회장 잔니 인판티노에게 전화를 걸어 미국 선수 폴라린 발로건의 레드카드 출전정지 징계를 유예하도록 요청한 것으로 알려져 국제적 논란이 일었다. 발로건은 32강전에서 상대 선수의 발목을 밟아 퇴장당했으나, 16강전 출전을 허용하기 위해 1년간의 정지 처분이 유예됐으며, 이는 현행 제도 하에서 사상 처음이었다. 이 결정은 벨기에 대표팀과 유럽축구연맹(UEFA)을 비롯한 다수의 기관에서 ''규칙 훼손''이라며 강하게 반발했고, 벨기에축구협회는 즉각 FIFA 항소위원회에 항소를 제기했다. 현재 항소 절차가 진행 중이며, 16강전은 유럽시간 기준 8월 7일 오전 2시에 열릴 예정이며, 이 사건은 스포츠의 공정성과 정치적 개입의 경계에 대한 논의를 촉발하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:07'::timestamp,'2026-07-27 17:50:55.722511'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1743,4154,'이란의 전 최고지도자 아야톨라 알리 하메네이가 2024년 2월 28일 미국과 이스라엘의 공습으로 사망한 지 126일 만인 4월 4일(현지시각)부터 테헤란에서 일주일간 장례식이 진행되고 있다. 하메네이는 1989년부터 37년간 이란 최고지도자로 군림하며 이슬람 혁명의 상징이었으며, 그의 사망은 이란 내부의 권력 구조 변화와 외교적 긴장의 전환점으로 평가된다. 장례식에는 100여 개국 대표단이 참석했으며, 파키스탄, 러시아, 중국 등 주요 국가와 하마스, 헤즈볼라 등 반 이스라엘 세력도 조문했고, 테헤란에서는 약 1,000만 명의 추모객이 몰려 현대사에서 가장 큰 규모의 국장 중 하나로 기록될 전망이다. 현재 이란의 후계자인 아야톨라 모즈타바 하메네이는 공개석상에 모습을 드러내지 않으며, 그의 건강과 권력 유지 가능성에 대한 의문이 제기되고 있으며, 이는 내부 권력 분열과 외부 협상의 방향성에 대한 불확실성을 초래하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:25'::timestamp,'2026-07-27 16:51:11.499946'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1744,4155,'OPEC＋는 5일 화상회의를 통해 8월 하루 18만8천배럴 증산을 결정했다. 이는 2023년 4월 자발적 감산 조치 이후 생산량을 회복하기 위한 조치로, 주요 7개국(사우디아라비아, 러시아, 이라크, 쿠웨이트, 알제리, 카자흐스탄, 오만)이 공동으로 결정했다. 2023년 감산 이후 누적 165만 배럴 감산량을 2024년 9월까지 회복할 예정이며, 현재 오펙 플러스의 하루 생산량은 약 4,277만 배럴로 세계 수요의 40% 이상을 차지하고 있다. 9월에도 동일한 증산이 이어질 경우 감산 조치 전 생산 수준으로 복귀하며, 이란전쟁으로 인한 호르무즈 해협 교통 차질로 인한 유가 급등에 대응하는 시장 안정화 전략이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:30'::timestamp,'2026-07-27 16:46:12.065908'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1745,4156,'미국 동부 해안 지역에서 기록적인 폭염과 강한 뇌우로 5일(현지시각) 기준 최소 25명이 사망했으며, 뉴저지주에서만 22명의 사망자가 발생했다. 폭염은 지난 3일 뉴욕 기온이 약 38도까지 상승하며 시작되었고, 워싱턴DC, 필라델피아, 보스턴 등도 역대 최고기온을 기록했으며, 열돔 현상과 한랭전선의 충돌로 강한 뇌우와 폭우가 발생했다. 뇌우와 강풍으로 약 90만 가구가 정전 피해를 입었고, 암트랙과 뉴저지 트랜짓 등 주요 교통 수단의 운행도 지연됐으며, 워싱턴DC 내셔널 몰에서는 온열질환자가 속출해 주방위군이 긴급 투입됐다. 현재 미 국립기상청은 뉴욕시 일대에 홍수주의보를 발령했으며, 뉴저지, 뉴욕, 코네티컷 등 동부 지역에 강풍과 기습 폭우가 지속될 것으로 예보되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:35'::timestamp,'2026-07-27 16:45:47.061295'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1746,4158,'도널드 트럼프 미국 대통령과 베냐민 네타냐후 이스라엘 총리는 2024년 3월 3일 통화를 통해 조만간 미국에서 정상회담을 개최하기로 합의했다. 이는 미국과 이스라엘 간 오랜 동맹 관계를 기반으로 하며, 특히 이란의 핵무기 개발 프로그램 해체를 목표로 한 2024년 2월 28일 공동 공습 이후 양국의 협력이 지속되고 있음을 반영한다. 그러나 미·이란 간 종전 협상 과정에서 이스라엘이 사실상 배제되면서 이스라엘은 자국 안보 우려가 반영되지 않았다고 불만을 표하며, 이란 문제 해결 방안에 대한 입장 차이가 드러났다. 이후 양국 정상은 9월 뉴욕 유엔총회를 계기로 회동할 가능성이 제기되며, 이란 문제를 포함한 양자 관계의 향방이 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:40'::timestamp,'2026-07-27 16:25:42.271557'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1747,4159,'도널드 트럼프 미국 대통령은 집권 2기 첫해인 2024년에 22억달러(약 3조4200억원) 이상의 소득을 올리며 재산을 수조원 증가시킨 것으로 확인됐다. 이는 전년도 6억달러 대비 16억달러 증가한 수치로, 가상자산 관련 사업 수익이 주요 원인으로 분석되며, 관세 유예 발표 전날 개인투자계좌에서 우량기업 327개사 주식을 대량 매수한 사실이 공개되며 이해충돌 논란이 확산됐다. 현행 연방윤리법은 대통령의 이해충돌 자산 처분을 의무화하지 않지만, 역대 대통령들은 자발적으로 자산을 매각하거나 백지신탁해 왔으나 트럼프 대통령은 이 전통을 따르지 않았다. 11월 중간선거를 앞두고 민주당은 트럼프 대통령과 그 주변 인물에 대한 조사를 준비하며, 하원 장악 시 증언 소환과 탄핵 시도를 예고하고 있으며, 공화당 내부에서도 전방위적 조사 위협에 대한 위기감이 커지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:45'::timestamp,'2026-07-27 16:25:23.120113'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1748,4161,'이란은 4일(현지시각) 미국과 이스라엘의 공습으로 사망한 2대 최고지도자 아야톨라 알리 하메네이의 장례식을 시작했다. 하메네이는 2월28일 전쟁 공습으로 사망한 지 126일 만에 장례를 치르며, 테헤란과 마슈하드 등 전국에서 일주일간 추모 행사가 진행된다. 약 100개국에서 200명의 고위급 조문단이 참석했으며, 이란 당국은 전국에서 1천만 명 이상의 시민 참여를 예상하고 있다. 장례식은 이라크 카르발라와 바그다드, 아프가니스탄 등지에서 이어지며, 이란은 이를 반미·반이스라엘 결속의 계기로 삼고 있으며, 후계자인 모즈타바 하메네이의 참석 여부는 아직 미정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:50'::timestamp,'2026-07-27 16:25:03.875824'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1749,4163,'테일러 스위프트와 트래비스 켈시가 결혼을 앞두고 미국 전역의 20개 자선 단체에 총 2600만달러(한화 약 400억원)를 기부했다. 두 사람은 결혼식을 치르기 전인 2024년 5월 2일(현지 시간) 뉴욕 매디슨 스퀘어 가든에서 예정된 행사에 앞서, 푸드 뱅크, 의료·교육·식량 지원 단체 및 동물보호 기관 등에 기부를 완료했다. 기부 대상은 내슈빌과 캔자스시티 등 두 사람과 인연이 깊은 지역의 단체들이 포함되었으며, 이는 그동안의 사회적 기여와 연계된 것으로 분석된다. 결혼식은 사전 파티를 포함해 5월 2일부터 3일까지 진행되며, 공식 허가를 받은 대규모 행사로 전 세계 팬들의 관심이 집중되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:56:55'::timestamp,'2026-07-27 16:23:05.365697'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1750,4166,'2024년 6월 2일(현지시각) 뉴욕증시는 반도체 업종의 약세 속에서 혼조로 마감했다. 다우존스30 산업평균지수는 전장 대비 594.83포인트(1.14%) 상승해 사상 최고치인 5만2,900.07을 기록했으나, 기술주 중심의 나스닥 종합지수는 207.36포인트(-0.80%) 하락하며 2만5,832.67에 마감했다. 반도체 업종은 AI 수요 둔화와 차익실현 매물로 인해 연속 하락했으며, 마이크론(-5.49%), 엔비디아(-1.39%), AMD(-4.26%), 인텔(-5.25%), 마벨 테크놀로지(-9.84%) 등 주요 기업이 하락했다. 미국 노동부는 6월 비농업 일자리 증가가 전월 대비 5만7천명으로 시장 전망치(11만5천명)를 하회했으며, 4∼5월 일자리 데이터도 하향 조정됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:00'::timestamp,'2026-07-27 16:22:11.807194'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1751,4170,'삼성전자는 2024년 2분기 매출 171조원, 영업이익 89조4000억원을 기록하며 분기 기준 역대 최대를 달성했다. 이는 지난해 동기 대비 매출 129.31% 증가, 영업이익 1810.26% 급증한 것으로, 1분기 실적(매출 138조8700억원, 영업이익 57조2300억원)보다 각각 27.74%, 56.21% 증가한 결과다. 상반기 누적 매출은 304조37억원, 영업이익은 146조6300억원으로 각각 지난해 상반기 대비 98.34%, 1190.76% 증가하며 반기 기준 최대 기록을 세웠고, 연간 매출과 영업이익도 전년 대비 각각 1.1배, 2.3배 이상 증가했다. 삼성전자는 올해 상반기 실적을 통해 지난해 연간 실적(매출 333조5060억원, 영업이익 43조6000억원)에 근접했으며, 향후 3분기 실적과 반도체 수요, 글로벌 시장 동향에 따른 전망이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:05'::timestamp,'2026-07-27 17:54:51.209708'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1752,4179,'서울회생법원 회생4부는 3일 홈플러스의 기업회생절차를 폐지했다. 홈플러스는 지난해 12월 29일과 올해 3월 30일 두 차례에 걸쳐 구조혁신형 회생계획안을 제출했으나, 수익성 낮은 점포 정리와 M&A 추진 등이 이뤄지지 않아 약 2천억원의 자금 조달이 불가능하다고 판단됐다. 회생계획안 수행 가능성이 없다고 판단된 결과, 홈플러스는 파산 절차를 밟을 수밖에 없으며, 현재 공익채권이 급증하고 매출은 감소하는 상황이다. 홈플러스는 14일 이내에 즉시항고를 제기할 수 있으며, 항고 시 회생절차 폐지 결정이 취소될 가능성도 열려 있으나, 그렇지 않을 경우 파산 절차가 확정될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:10'::timestamp,'2026-07-27 16:23:30.053161'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1753,4180,'미국과 이란은 6월 19일 스위스에서 호르무즈 해협의 전면 재개방 합의를 발표했다. 이는 중동전쟁으로 인해 2024년 5월 중순부터 막혀 있던 해협 통행이 재개된 것을 의미하며, 원유 운송과 국제 공급망 회복에 기여했다. 6월 마지막 주에는 총 43척의 선박이 호르무즈 해협을 통과했으며, 원유 수송량은 전주 대비 1218.8% 증가한 422만 DWT를 기록했다. 이후에도 해상 통행이 지속되고 있으며, 특히 한국 선박 중 HMM의 ''유니버설 위너''호가 10일 울산 앞바다에 도착해 원유 하역을 진행하며 국내 수송 체계 회복의 신호를 보였다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:13'::timestamp,'2026-07-27 16:22:04.849396'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1754,4184,'2024년 7월 1일 서울 신라호텔에서 열린 ''제5회 여성기업주간'' 개막식에서 여성기업인들의 기술 혁신과 성장을 주목하는 행사가 진행됐다. 이 행사에는 세계 최초 AI 아이돌 ''이터니티''와 감정을 전달하는 AI 더빙 기술 등 여성기업의 창의적 기술 성과가 전시되었으며, 중소벤처기업부는 여성기업 전용 벤처펀드 200억원, 정책자금 1조원 등 지원 정책을 발표했다. 올해는 대한오케이스틸 김연선 대표 등 11명의 여성기업인이 정부포상을 수상했으며, 여성기업 주간은 7월 한 달간 전국에서 여성창업경진대회, 판로 지원 등 다양한 행사를 통해 이어질 예정이다. 여성기업의 기술 혁신과 사회적 가치를 인정받기 위한 정책적 지원 확대와 글로벌 경쟁력 강화가 향후 주요 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:19'::timestamp,'2026-07-27 16:20:09.483454'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1755,4185,'원민경 성평등가족부 장관은 1일 서울 중구 더플라자 호텔에서 열린 제4차 대한상공회의소 여성기업위원회에서 AI 시대 여성기업의 성장 전략을 논의했다. 이날 회의는 AI 전환(AX) 시대에 여성기업의 경쟁력 강화를 위해 마련되었으며, 정기옥 대한상의 여성기업위원장과 다양한 업종의 여성기업 대표 등 30여명이 참석했다. 원 장관은 AI 생태계에서 성편향을 방지하고 공정한 기회를 보장하기 위해 신뢰할 수 있는 데이터셋 구축을 추진하겠다고 밝혔고, 김지현 SK AI위원회 부사장은 AI를 협업 파트너로 활용해 조직 변화를 이끌어내야 한다고 강조했다. 이번 회의에서 김민영 방앗간컴퍼니 대표, 서소영 콘콘 대표, 정연자 현대금속산업 대표가 신규 위원으로 위촉되었으며, 향후 여성기업의 AI 도입 지원 정책과 협업 모델 개발이 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:23'::timestamp,'2026-07-27 16:19:48.839554'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1756,4188,'2026 북중미 월드컵 16강전에서 미국 대표팀이 벨기에에 1대 4로 패한 가운데, 도널드 트럼프 미국 대통령이 피파 인판티노 회장과 통화해 주공격수 폴라린 발로건의 퇴장 징계를 유보하도록 압박한 사실이 확인됐다. 발로건은 32강전에서 타리크 무하레모비치의 발목을 밟아 VAR 기반 퇴장 판정을 받았으나, 트럼프 대통령의 개입으로 16강전 출전이 가능해졌다. 이에 유럽축구연맹(UEFA)은 ''레드카드 자동 출전 정지'' 규정을 무시한 결정이 ''레드라인''을 넘었다며 깊은 유감을 표하며 공정성과 대회 신뢰성에 대한 우려를 제기했다. 이후 트럼프 대통령은 벨기에 승리에 대해 ''2020년 대선과 마찬가지로 조작된 경기''라며 논란을 부추기며, 피파의 결정에 대한 비판과 국제적 신뢰 저하가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:30'::timestamp,'2026-07-27 18:33:42.567673'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1757,4190,'2025년 10월 21일 다카이치 사나에가 일본 자민당 창당 이후 첫 여성 총리로 취임하며, 전후 140년 만에 여성 총리가 탄생했다. 그는 아베 신조 총리의 정책을 계승하며 헌법 개정, 방위력 강화, 경제 성장 등을 주요 과제로 제시했고, 2026년 2월 중의원 선거에서 자민당이 단독으로 316석을 확보하며 안정적 지지를 확보했다. 이에 따라 방위비 증액(향후 5년간 GDP 대비 2% 이상), 반격 능력 보유, 무기 수출 확대 등 안보 3문서 개정을 추진 중이며, 특히 ''비핵 3원칙'' 중 ''반입하지 않는다''는 조항의 수정 여부에 대해 명확한 입장을 밝히지 않고 있다. 현재 일본은 중국의 군사력 증강과 대만 문제를 둘러싼 외교적 긴장 속에서 군비 경쟁과 외교적 대응의 균형을 모색하고 있으며, 이는 중·일 관계 악화와 한국의 지정학적 난처함을 초래할 수 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:46'::timestamp,'2026-07-27 18:11:09.773807'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1758,4193,'2022년 카타르 월드컵 32강전에서 미국 축구대표팀의 폴라린 발로건이 퇴장당한 후, 도널드 트럼프 전 미국 대통령이 피파 잔니 인판티노 회장에게 전화를 걸어 징계 재검토를 요청했고, 이에 피파는 1962년 이후 처음으로 퇴장 선수의 경기 출전을 허용한 바 있다. 이 결정은 피파 징계 규정 27조에 따라 발로건의 출전 정지 조치를 1년간 유예한 것으로, 유예 기간 중 추가 위반 시 징계가 복구된다. 그러나 벨기에 축구연맹은 피파의 결정이 규정 위반과 공정성에 어긋난다고 강하게 반발하며 가능한 대응 방안을 검토 중이며, 영국 축구 전문가들 역시 규칙의 일관성과 투명성에 대한 비판을 제기했다. 이 사건은 인판티노 피파 회장이 트럼프 전 대통령과의 특별한 관계를 고려해 정치적 중립성을 위반했을 가능성과 함께, 1962년 가린샤 사건과 유사한 특혜 논란을 불러일으키며 국제 스포츠의 공정성에 대한 우려를 키우고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:54'::timestamp,'2026-07-27 16:49:49.247193'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1759,4195,'도널드 트럼프 미국 대통령은 4일(현지시간) 악시오스와의 인터뷰에서 베냐민 네타냐후 이스라엘 총리로부터 백악관 회동 제안을 받았다고 밝혔다. 이는 지난 2월 ''상황실 회담'' 이후 처음으로, 트럼프 대통령은 나토 정상회의 후인 이르면 다음 주 회담 개최 가능성을 시사했다. 네타냐후 총리는 3일 트럼프 대통령에게 전화를 걸어 미국의 250주년 독립기념일을 축하하며 양국 간 긴밀한 관계를 강조했고, 조만간 미국에서 회동하기로 합의했다. 이후 양국 정상 간 회동이 성사될 경우, 이스라엘의 이란 공습 계획 등 안보 이슈 논의가 예상되며, 외교적 협력 강화가 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:57:58'::timestamp,'2026-07-27 16:31:51.279905'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1760,4203,'2025년 6월 30일 기준, 도널드 트럼프 미국 대통령은 백악관 복귀 첫 해에 가족이 공동 설립한 암호화폐 기업 ''월드 리버티 파이낸셜(World Liberty Financial)''을 통해 약 8억 달러, ''$TRUMP'' 코인 판매로 약 6억 달러를 벌어들인 것으로 나타났다. 이는 그가 2024년 한 해 동안 기업에서 벌어들인 최소 6억 2200만 달러보다 높은 수치로, 특히 2025년 1월 아랍에미리트(UAE) 정부와 연계된 투자사가 지분 49%를 인수한 직후 반도체 칩 수출 계약이 체결된 점에서 이해충돌 가능성이 제기됐다. 트럼프 대통령은 취임 후 스테이블코인 규제 완화, 증권거래위원회(SEC) 위원장으로 암호화폐 친화적 인사를 임명하는 등 암호화폐 업계에 유리한 정책을 도입했으며, 이는 그가 업계 주요 사업자이자 정책 입안자라는 점에서 이해충돌 논란을 불러일으켰다. 백악관은 이해충돌이 없었다며 대통령의 정책이 국민 최선의 이익을 위한 것이라고 반박했지만, 전직 윤리 전문가들은 대통령의 투자 자산 제한과 윤리법 개정 필요성을 제기하며 제도적 개선이 시급하다고 지적했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:07'::timestamp,'2026-07-27 16:19:56.846146'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1761,4205,'2026 북중미 월드컵 조별리그에서 탈락한 한국 축구 국가대표팀의 홍명보 감독이 2024년 6월 28일 멕시코 과달라하라에서 사퇴 기자회견을 열며 사임했다. 이는 2013년부터 재임한 정몽규 대한축구협회장의 장기 집권과 감독 선임 절차의 비공정성, 팬과 정부의 비판이 누적된 결과로, 문체부는 2024년 11월 정 회장 등 임원진의 직무 정지를 권고했다. 정 회장은 2025년 2월 26일 제55대 회장 선거에서 4연임에 성공했으나, 월드컵 이후 사임 의사를 밝히며 ''자신의 부족함''을 인정했고, 한국 축구는 J리그에 비해 아시아 클럽 대회 성과와 유럽 진출 유망주 수에서 뒤처지고 있다. BBC는 한국 축구가 일본의 장기적 비전 모델과 대비되며 감독 변화가 정치적·개인적 변덕에 따라 반복되고 있어, 현재의 분노와 변화 열망이 아시아 축구 강국으로의 전환점이 될 수 있다고 조언했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:13'::timestamp,'2026-07-27 16:19:03.416732'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1762,4210,'2024년 2월 27일 이란은 미국의 공습에 대한 보복으로 쿠웨이트와 바레인의 미군 기지를 미사일과 드론으로 공격했다. 이는 전날 미 중부사령부가 이란의 유조선 공격에 대응해 이란 내 감시 기반시설, 통신 시스템, 방공 기지 등을 공습한 데 따른 연쇄 반응이다. 이란은 공격을 ''휴전 위반''으로 규정하며 미국의 공습을 ''종전 양해각서 위반''이라고 반박했고, 트럼프 대통령은 이란의 존재를 위협하며 군사적 대응 가능성을 시사했다. 현재 호르무즈 해협과 레바논 지역에서 이란과 미국, 이스라엘 간 긴장이 고조되고 있으며, 헤즈볼라가 미·레바논·이스라엘 간 평화 합의를 ''굴욕''이라며 거부함에 따라 레바논 지역의 휴전 협정도 위태로운 상태다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:19'::timestamp,'2026-07-27 16:17:16.305527'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1763,4211,'베네수엘라에서 24일 발생한 연쇄 강진으로 사망자가 1430명으로 늘어났고, 비공식 실종자 신고는 6만8900명에 달했다. 지진 발생 후 72시간이 지난 현재까지 구조 활동은 여진과 교통 체증, 정부의 허가제로 인해 지연되고 있으며, 일부 지역에서는 약탈과 치안 붕괴도 발생했다. 국제사회는 미국·스페인·엘살바도르 등 10개국에서 1600명의 구조대원을 파견했고, 미국은 1억5000만 달러의 원조를 발표하며 추가 지원을 예고했다. 유엔개발계획은 피해 규모가 GDP의 6%에 달하는 67억 달러로 추산하며, 장기적인 복구와 인프라 회복이 필요한 상황이라고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:26'::timestamp,'2026-07-27 16:17:01.596175'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1764,4214,'민주당은 7일 한병도 당대표 직무대행 겸 원내대표가 ''보완수사권 완전 폐지''를 확고한 원칙으로 삼고, 형사소송법 개정안을 신속하게 발의하고 처리할 계획을 밝혔다. 이는 검찰의 보완수사권 남용 논란과 공소청, 중대범죄수사청 출범을 앞두고 법적 기반을 마련하기 위한 것으로, 당내 TF를 중심으로 논의를 진행 중이다. 현재까지 국민의힘 반대로 본회의 문턱에서 지연된 민생법안은 59건에 달하며, 민주당은 9일 본회의 개최를 요청해 법안 처리를 촉구하고 있다. 이후 여야 간 협의가 이어질 전망이며, 보완수사권 폐지 법안의 처리 시기와 민생법안 처리의 진척 상황이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:30'::timestamp,'2026-07-27 18:39:33.629194'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1765,4219,'국민의힘 장동혁 대표는 6일 윤리위원회를 통해 친한동훈계 및 비당권파 인사들을 대상으로 한 징계 절차를 재개하며 당내 통합을 강화하려는 의도를 드러냈다. 이는 6.3 지방선거 이후 약 4개월 만에 재개된 윤리위 활동으로, 한 전 대표의 무소속 출마 지원 및 장 대표 사퇴 촉구 행위 등을 이유로 수십 건의 징계 요청이 접수된 상황이다. 장 대표는 비공개 최고위에서 ''심각한 해당 행위자에 대해 복당을 영구 금지해야 한다''고 발언하며 징계의 강도를 강조했고, 윤리위원장도 장 대표 임명 인사로 독립성에 의문이 제기되고 있다. 이에 대해 정점식 원내대표를 비롯한 의원들은 징계 절차의 신중함과 당내 민주주의 보장 필요성을 지적하며, 장 대표의 통합적 리더십을 촉구하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:35'::timestamp,'2026-07-27 17:12:22.065076'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1766,4220,'이병태 규제합리화위원회 부위원장이 5.18 광주민주화운동을 폄훼하는 발언을 한 데 이어 6일 사의를 표명했고, 청와대는 이를 수용했다. 이 부위원장은 지난 3일 페이스북에서 배재고 야구부 학생들의 응원 구호를 두고 ''5.18이 성역이 됐다''며 비판적 발언을 하며 논란이 발생했으며, 청와대는 4일 부적절한 처신이라며 경고했으나, 8.17 전당대회를 앞두고 정치적 비판이 확산되자 사퇴 권고를 공식화했다. 사퇴 이후 이 부위원장은 자신의 발언이 정치적 갈등을 부추겼다고 인정하면서도, 표현의 자유와 다양성 존중이 필요하다고 강조하며 사퇴가 정치적 공세에 의한 것이라며 법치주의에 대한 우려를 표했다. 이후 이 사건은 표현의 자유와 사회적 성역 문제에 대한 논의를 촉발했으며, 향후 정부 인사의 발언 기준과 정치적 책임에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:41'::timestamp,'2026-07-27 17:09:59.832675'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1767,4221,'청와대는 5.18 민주화운동 폄훼 발언을 한 규제합리화위원회 부위원장 이병태에게 6일 사퇴를 권고했다. 이 부위원장은 SNS에서 ''5.18이 성역이 된 것''이라고 발언하며 논란을 일으켰고, 청와대는 이전에 공개 경고했으나 그가 입장을 굽히지 않아 사퇴 권고로 수위를 높였다. 이 부위원장은 임기 2년이 보장된 직위이므로 일방적 해임이 불가능하며, 스스로 거취를 결정할지 주목되고 있다. 청와대는 이 사건을 계기로 보수와 진보를 넘어 포용적 인사 기조를 유지하겠다는 입장을 재확인했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:44'::timestamp,'2026-07-27 17:04:21.544253'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1768,4224,'정부는 ''3대 메가 프로젝트'' 일환으로 호남권 반도체 클러스터를 광주 군공항 부지에 조성하기로 결정했다. 광주 군공항은 약 250만 평의 부지가 확보 가능하며, 평탄화가 완료된 상태로 공사 기간 단축이 가능하고, 도심 및 KTX역 인접으로 인력 확보와 정주 여건이 우수하며, 도로·공항·항만과의 연계로 물류 접근성도 높다. 삼성전자와 SK하이닉스의 투자 계획 발표 이후 지역 부동산 시장의 이상 조짐을 우려해 부지 선정을 서두르며, 관계부처 협의를 거쳐 후속 절차를 진행할 예정이다. 정부는 전력·용수·인프라 확충과 함께 정주 여건 개선을 위한 인프라 계획을 조속히 수립하고, 대통령 주재 민관합동 점검회의를 매달 개최해 프로젝트 진도를 총괄할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:49'::timestamp,'2026-07-27 16:55:05.362933'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1769,4227,'더불어민주당 당권 주자인 김민석 전 국무총리가 6일 광주에서 전당대회 출마 기자회견을 열고, 정청래 전 대표 지도부를 향해 ''자기정치로 당정 협력이 혼선에 빠졌으며, 공천 일관성과 원칙에 의심이 생겼다''고 비판했다. 그는 지난 1년간 민주당이 대통령과 정부에 대한 국정지지를 선거 결과와 연결하지 못했고, 합당 추진, 검찰개혁, 공천 등에서 숙의와 절차 부족이 문제였다고 지적하며, 당의 혁신이 국정 성공과 총선 승리의 전제라고 강조했다. 김 전 총리는 보완수사권 완전 폐지, 1인1표제, 당내 ''적통론'' 등 정 전 대표와 대립하는 주제에 대해 자신을 ''민주대연합론자''로 규정하며 통합을 강조했고, 1인1표제에 대해선 현행 유지와 유럽식 주기적 재등록 제도 도입을 제안하며 보완 가능성을 시사했다. 반면 정청래 전 대표는 김 전 총리의 비판에 대해 ''네거티브를 하지 않겠다''며 동지적 언어를 사용하며 김대중·노무현·문재인 정신을 바탕으로 이재명 정부 성공과 당내 통합을 강조했고, 검찰개혁 완수와 보완수사권 폐지 추진을 재확인했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:58:57'::timestamp,'2026-07-27 16:52:20.794455'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1770,4228,'국민의힘은 6일 더불어민주당이 6.3 지방선거 투표용지 부족 사태 진상규명을 위해 선관위 특검법을 발의할 예정임을 밝히며, 제3자 추천 방식을 비판하고 야당 추천, 수사 범위 무제한을 요구했다. 이는 민주당이 특검 추천을 대한변호사협회 등 제3자에게 맡기려는 방안에 반발한 것으로, 국민의힘은 선관위 내부와 행정안전부까지 수사 대상에 포함해야 한다고 주장하며 위철환 중앙선관위원장 직무대행을 수사 대상 1호로 지목했다. 국민의힘은 특검 수사 범위 제한과 민주당의 추천권 배제를 요구하며 ''침대 특검 작전''이라며 무책임한 진상규명 거부라고 비판했고, 동시에 7일 시행되는 개정 정보통신망법에 대해 ''입틀막법''이라며 검은색 마스크 착용으로 항의했다. 이후 국민의힘은 특검법과 정보통신망법에 대한 재개정 논의를 촉구하며, 민주당에 야당 추천 특검 수용과 법안 유예를 요구하는 등 후속 절차를 예고했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:03'::timestamp,'2026-07-27 16:51:46.053180'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1771,4231,'진중권 동양대 교수는 5일 페이스북에서 ''무섭노'' 발언 논란과 이진숙 국민의힘 의원의 배재고 야구부 응원 화환 사건을 지적하며, 온 나라가 폭력적으로 유치해지고 있다고 비판했다. 이 사건은 리센느 멤버 원이 경상도 사투리로 말한 ''무섭노'' 발언이 일베식 표현으로 비판받은 데서 시작되었으며, 배재고 야구부가 5·18 민주화운동을 조롱하는 구호를 외친 가운데 이진숙 의원이 ''학생들과 함께합니다''라고 적힌 화환을 보낸 것이 논란이 됐다. 이에 대해 진 교수는 ''망탈리테''와 ''상시빌리테''의 극단적 성향이 동일한 민족성의 산물이라며, 5·18 영령의 뜻과는 거리가 멀다고 지적했고, X랄과 유치한 집단적 반응에 대해 적당한 수준을 요구했다. 이후 이 사건은 정치적 논란으로 확산되며, 5·18 기념일을 앞두고 민주화 운동에 대한 존중과 표현의 한계에 대한 사회적 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:08'::timestamp,'2026-07-27 16:47:03.884012'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1772,4233,'이진숙 국민의힘 의원은 5월 5일 페이스북에서 배재고등학교 야구부 학생들이 스타벅스를 언급한 발언을 두고 ''5.18 모욕''이라고 비판한 것에 대해 ''생각에 수갑을 채우는 나라''라며 강하게 비판했다. 이 의원은 스타벅스가 5.18과 광주를 모욕하는 상징이라고 주장하며, 해당 발언을 한 학생들을 징계하는 것은 표현의 자유를 침해하는 행위라고 지적했다. 그는 교육부 장관이 대통령 시해일을 ''탕탕절''로 부르는 등 좌파적 발언을 용인하는 현 상황을 비판하며, 정치적 편향이 교육 현장에 침투하고 있다고 주장했다. 이에 대해 정치권과 시민사회에서는 표현의 자유와 역사 인식의 갈등이 다시 부각되며, 향후 교육 정책과 사회적 논의의 방향성에 대한 논쟁이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:12'::timestamp,'2026-07-27 16:43:02.594097'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1773,4235,'오세훈 서울시장은 5일 페이스북을 통해 육·해·공군사관학교 통합 추진에 대해 반대 입장을 밝혔다. 그는 장교 양성체계가 국가안보의 백년대계라며, 충분한 검토와 국민적 공감대 없이 대통령 공약 이행을 명분으로 추진하는 것은 부적절하다고 지적했다. 오 시장은 세계 주요 군사강국들이 사관학교를 별도 운영하면서도 합동참모체계와 교육을 통해 연합작전 능력을 강화하고 있다고 강조하며, 합동성은 학교 통합보다 각 군의 전문성 기반 협력에서 비로소 완성된다고 주장했다. 현재 정부는 사관학교 통합과 육군사관학교 이전을 추진 중이며, 사관생도와 현역 장병의 의견 반영 여부, 숙의과정의 충실성 등이 향후 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:16'::timestamp,'2026-07-27 16:39:13.350765'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1774,4329,'SK하이닉스는 10일 미국 나스닥 시장에 약 43조원 규모의 미국주식예탁증서(ADR)를 상장하며 국내 반도체 기업 최초로 글로벌 대형 증시에 진입한다. 기업은 증권신고서를 통해 생산시설 확충 지연으로 인한 시장 주도권 상실과 글로벌 고객사 이탈 가능성, 반독점 소송 등 규제 리스크, 대규모 투자 이후 공급 과잉 우려를 투자 위험 요인으로 명시했다. 현재 용인과 청주 공장 건설 중이지만 글로벌 메모리 수요 증가에 대응하기 위해 추가 생산 거점 확보가 필요하며, 메모리 반도체가 전체 매출의 90% 이상을 차지해 경기 변동 주기(2~3년)에 따라 실적 변동이 클 수 있다고 분석했다. 이후 미국 증시 상장 후 국내 주가와 ADR 주가 간 동조화가 보장되지 않으며, 향후 공급 과잉 시 실적 악화 가능성과 함께 규제 리스크 대응 방안이 주요 쟁점으로 부각될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:21'::timestamp,'2026-07-27 18:40:29.643954'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1775,4240,'삼성전자는 2024년 2분기 영업이익 89조4000억원을 기록하며 사상 최대 실적을 달성했고, 이는 3분기 연속 최대 실적 기록이다. 이는 인공지능(AI) 반도체 수요 증가로 인한 반도체 사업의 호황과 지난해 동기 대비 1810.3% 증가한 영업이익 성장에 기인하며, 매출은 171조원으로 작년 동기 대비 129.3% 증가했다. 전년도 전체 영업이익의 2배를 한 분기 만에 달성한 것으로, 반도체 부문이 전사 실적을 주도하는 구조가 지속되고 있다. 삼성전자는 이 같은 실적을 바탕으로 향후 반도체 투자 확대와 AI 기반 신제품 개발을 예정하고 있으며, 시장은 지속적인 성장 전망에 주목하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:25'::timestamp,'2026-07-27 17:55:28.659166'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1776,4241,'서울회생법원 4부는 홈플러스의 회생절차 폐지를 결정했다. 홈플러스는 점포 126개를 67개로 축소하고 인력 50% 감축을 통해 1조 2000억 원의 비용 절감을 목표로 한 회생계획안을 제출했으나, 2000억 원 규모의 추가 자금 조달 문제가 해결되지 않아 수행 가능성이 부족하다고 판단됐다. 회생계획안 인가 시한인 2일까지 자금 조달이 이뤄지지 않아 법원은 절차를 종료했으며, 홈플러스는 현재 회생절차를 종료한 상태다. 이후 홈플러스는 자산 매각 및 사업 구조 조정을 통한 재도약 방안을 모색할 예정이며, 법원은 관련 절차의 적절성에 대해 추가 검토를 진행할 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:28'::timestamp,'2026-07-27 16:23:03.215443'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1777,4244,'은마아파트 재건축 사업시행계획이 2024년 2월 서울시에 의해 인가됐다. 은마아파트는 1979년 준공된 노후 아파트로, 23년간 재건축 조합설립추진위원회 활동과 정비계획 변경을 거쳐 신속통합기획 2.0을 적용해 단계별 처리 기한을 약 1년 단축했다. 재건축 후에는 지하 6층~지상 49층, 29개 동, 총 5850세대가 건설되며, 이 중 909세대는 공공임대, 195세대는 공공분양주택으로 제공된다. 착공은 2028년 목표이며, 강남구는 재건축 신속화를 위해 구청장 직속 TF를 구성해 행정 처리와 갈등 예방을 추진하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:32'::timestamp,'2026-07-27 16:21:40.104278'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1778,4261,'2026년 5월 말 기준 한국 투자자가 증권사에서 빌린 ''빚투'' 금액은 39조4000억 원으로, 2015년 통계 작성 이후 역대 최대치를 기록했다. 이는 전년 동기(19조2000억 원)보다 두 배 이상 증가한 것으로, 주가 상승과 함께 레버리지 ETF 등으로의 자금 유입이 확대되며 신용융자 및 마이너스 통장 등 기타대출이 증가한 결과다. 올해 1분기 연체진입률은 5.5%로 장기평균을 상회하고, 1년 이상 연체된 장기연체차주 비중도 8.0%로 전년 동기(7.2%) 대비 증가했다. 한은은 가계신용 레버리지(88.2%)와 기업신용 레버리지(110.4%)가 선진국 및 신흥국 평균보다 높은 수준이며, 주가 변동성 확대와 취약차주 증가 가능성에 우려를 표명했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:37'::timestamp,'2026-07-27 16:14:58.468896'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1779,4245,'2024년 4월 2일 코스피지수는 반도체 지수 급락 여파로 전거래일 대비 5.34% 하락하며 7860.13으로 출발, 8000선이 무너졌고, 이에 거래소는 매도 사이드카를 발동했다. 이날 뉴욕증권거래소에서 필라델피아 반도체지수가 6.27% 급락했으며, 마이크론(-10.57%), 샌디스크(-10.62%), 인텔(-9.03%), AMD(-6.89%) 등 주요 반도체주가 대거 하락했고, AI 테마 대장주 엔비디아도 1.25% 하락했다. 코스피는 오전 9시 8분 기준 전일 대비 443.28포인트(5.34%) 하락하며 낙폭을 확대했고, 코스닥지수도 3.47% 하락한 897.11을 기록했다. 시장은 반도체 관련주에서의 차익실현과 외부 시장 악재에 따른 하방 압력에 직면했으며, 향후 국내 증시의 회복 가능성과 정부·금융당국의 대응 방안이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:42'::timestamp,'2026-07-27 16:20:23.989012'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1780,4247,'국민연금공단 김성주 이사장은 1일 페이스북을 통해 ''74조 매도폭탄'' 우려를 ''터무니없는 소리''라고 반박하며 리밸런싱이 시장에 폭탄을 쏟아낼 가능성은 제로라고 강조했다. 이는 지난 1월 기금위에서 시장 변동성 고려로 유예된 리밸런싱을 7월부터 점진적으로 재개하는 것으로, 5월 기금위에서 리밸런싱 규칙을 조정해 장기적이고 점진적인 시행을 확보한 것이며, 코스피 지수 상승만으로 매도를 결정하지 않는다는 점을 설명했다. 리밸런싱은 주가 수준뿐 아니라 채권, 대체자산 수익률, 금리, 환율 등 다양한 요소를 종합적으로 고려해 결정되며, 국민연금은 단기적 수익 실현을 목적으로 하지 않고 기업 성장과 함께하는 ''유니버설 오너''로서 장기적 안정을 추구한다. 김 이사장은 일부 비전문가와 언론의 과도한 공포 조장에 주의를 당부하며, 시장 변동성에 일희일비하지 말 것을 요청했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:47'::timestamp,'2026-07-27 16:20:17.136407'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1781,4248,'한국의 월간 수출액이 6월에 1022억5000만 달러를 기록하며 사상 처음으로 1000억 달러를 돌파했다. 이는 지난해 같은 달 대비 70.9% 증가한 것으로, 반도체 수출도 처음으로 월 400억 달러를 넘어섰으며, 독일·중국·미국에 이어 세계 네 번째로 월 수출 1000억 달러를 달성한 국가가 됐다. 상반기 누적 수출은 4967억 달러로 전년 동기 대비 48.4% 증가했고, 무역수지는 1383억 달러의 역대 최대 흑자 기록을 달성했다. 산업부는 하반기 관세 및 유가 변동성 등 불확실성에 대응해 우호적 수출 환경 조성을 추진할 계획이며, 반도체 및 주력 품목의 수출 호조가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:52'::timestamp,'2026-07-27 16:19:40.140637'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1782,4249,'올해 1분기 자영업자 대출 잔액은 1095조 5000억 원으로 통계 작성 이후 최대치를 기록했다. 이는 지난해 말보다 2조 6000억 원 증가한 것으로, 사업자대출(745조 5000억 원)과 가계대출(350조 원)이 각각 역대 최대 규모를 기록한 결과다. 연체율은 2.04%로 2015년 2분기 이후 최고 수준이며, 저축은행과 카드·캐피털 등 2금융권 연체율도 각각 12.79%와 3.98%로 최고치를 기록했다. 기준금리 인상 시 연간 이자 부담이 1조 8000억 원 증가할 수 있어, 향후 금리 정책과 자영업자 지원 정책의 방향성이 주목된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 12:59:56'::timestamp,'2026-07-27 16:19:11.331883'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1783,4252,'5대 시중은행의 6월 개인 신용대출 잔액이 전월 대비 2조2118억 원 증가하며 2021년 4월 이후 5년 2개월 만에 가장 큰 폭으로 증가했다. 이는 주식 투자 열풍과 집값 상승 기대감에 따른 ''빚투''와 ''영끌'' 수요가 지속되며, 대출 규제 강화 전 ''막차'' 수요가 집중된 결과로 분석된다. 마이너스 통장 잔액은 43조3363억 원으로 3년 8개월 만에 최대 규모이며, 보험계약대출도 4월 46조3203억 원에서 46조8430억 원으로 약 5000억 원 증가했다. 금융당국은 가계대출 증가 추세 안정화를 위해 가계부채 비상 관리체계를 유지하고, 일부 카드사에 대한 소집도 예정하며, 은행권은 주택담보대출 모기지보험 가입 중단 및 타행 대출 접수 중단 등 자율 규제를 시행하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:02'::timestamp,'2026-07-27 16:17:24.589030'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1784,4254,'금감원은 지난달 신용융자 잔액이 38조원으로 최근 5년 평균 대비 17조9000억 원 증가하며 약 2배로 늘어났다고 밝혔다. 이는 레버리지 ETF와 지수선물·옵션 거래 증가로 인한 차입투자 확대와 관련된 것으로, 시장 변동성 확대 시 투자자 손실 및 금융사 건전성 부담이 우려된다. 금감원은 신용융자 및 증권담보대출 지표를 상시 모니터링하고, 과도한 레버리지 투자 위험을 투자자에게 지속 안내할 계획이며, 필요 시 금융사 리스크 관리 체계도 점검할 예정이다. 또한 보험대리점(GA)의 불건전 영업행위 방지를 위해 경영컨설팅 등 이해상충 업무를 겸영 금지 범위에 추가하고, 다음 달부터 시행되는 보험 수수료 개편 방안도 차질 없이 이행할 방침이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:07'::timestamp,'2026-07-27 16:17:00.098313'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1785,4257,'MBK파트너스는 2015년 영국 테스코로부터 홈플러스를 7조2000억 원에 인수하며 차입매수(LBO) 방식으로 4조 원을 대출해 자금을 조달했다. 이 과정에서 홈플러스는 2016년부터 2024년까지 28개 점포 및 물류센터를 매각하고, 점포의 절반 이상을 임차 형태로 전환하며 자산 유동화를 추진했으나, 임차료 부담 증가와 영업손실 지속으로 부채비율이 1400%를 초과해 2025년 3월 서울회생법원에 기업회생절차(법정관리)를 신청했다. 홈플러스는 현재 37개 점포 폐점 결정을 내리며 약 3500명의 직원이 피해를 입었고, 2024년 4월 기준 직원 수는 1만5398명으로 2023년 말 대비 2500명 이상 감소했다. MBK는 투자펀드 3호에서 약 1조2300억 원의 보수를 수령했다는 추정에 대해 반박하며, 법정관리 이후 신규 대출 및 DIP 자금 조달을 위한 채권단 협의가 지연되고 있어 노동자들의 급여 및 퇴직금 지급이 불투명한 상황이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:19'::timestamp,'2026-07-27 16:15:38.842953'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1786,4262,'정부가 전세사기 방지를 위해 도입한 ''126% 룰''이 빌라 전세 시장을 마비시켰다. 이 규제는 공시가격과 담보인정비율을 기준으로 전세보증금의 보증보험 가입 한도를 제한하며, 실제 시세와 공시가격의 괴리로 인해 빌라 전세보증금이 2억2000만 원을 초과하면 보호를 받지 못하게 한다. 결과적으로 세입자는 경매 시 보호받지 못하고 보증금 손실 위험이 커지며, 이로 인해 아파트 전세로의 전환을 선택하는 등 전세 시장의 불균형이 심화되고 있다. 이에 전세권 설정 등기 의무화, 전세 에스크로 제도 도입, 공인중개사의 무한 연대책임 법 개정 등 세입자 보호를 위한 제도 개선이 필요하다는 주장이 제기되고 있으나, 정부는 여전히 전세대출 규제와 공공임대 매입에 집중하고 있어 정책의 균형성에 대한 비판이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:25'::timestamp,'2026-07-27 16:14:41.282524'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1787,4263,'10만 명의 생계가 달린 홈플러스가 파산 절차로 내몰릴 위기에 처하자, 김상근 목사, 함세웅 신부 등 시민사회 원로 135명이 이재명 대통령 면담과 정부 차원의 2000억 원 긴급 자금 마련을 촉구했다. 서울회생법원은 지난 3일 홈플러스 회생절차 폐지 결정을 내렸고, 즉시항고 기한은 17일까지다. 이에 따라 홈플러스는 직영 노동자 2만 명과 협력업체 노동자 10만 명, 납품업체 1800여 개, 입점업주 8000여 개까지 포함해 수십만 명의 피해가 우려된다. 현재 메리츠그룹이 2000억 원 대출을 제안했으나, MBK 경영진이 보증을 1000억 원만 제공하겠다며 대출이 불발된 상태로, 정부의 긴급 개입 여부가 핵심 쟁점이 되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:30'::timestamp,'2026-07-27 18:57:54.396678'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1788,4265,'탈모 치료의 건강보험 급여화 논의는 청년층의 정신적 고통과 의료화 문제를 중심으로 사회적 논쟁을 불러일으켰다. 의료화는 외모 중심의 사회 구조에서 개인의 심리적 고통을 의학적 문제로 재정의하며, 비만처럼 인과관계가 입증된 질환과 달리 탈모가 질환으로 인정받는 근거에 대한 비판적 논의가 필요하다. 2025년 기준 102조 4000억 원에 달하는 건강보험 재원은 효율적 배분이 필수적이며, 현재 감기 치료나 임상적 가치가 불분명한 의약품에 과도하게 지출되고 있는 현실이 문제로 지적된다. 이에 따라 중증질환 치료와 아동 치료에 우선순위를 두고, 보험료 수입 내에서 지출을 효율화하는 양입제출 방식으로의 전환과 기금화가 필요하다는 제안이 제기됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:36'::timestamp,'2026-07-27 18:51:20.748693'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1789,4267,'광주지검은 광산경찰서 수사팀장 박모(59) 경감을 증거인멸 및 공무상 비밀누설 혐의로 강제 수사에 착수하고, 7일 광산경찰서를 압수수색했다. 이는 광주 여고생 살해 사건에서 장윤기의 차량에서 발견된 케이블타이를 압수하지 않았고, 수색 영상을 검찰에 제출하지 않은 등 증거인멸 의혹이 제기된 데 따른 조치다. 경찰청 국가수사본부는 27명 규모의 특별수사팀을 구성해 유착 의혹을 조사 중이며, 박 경감은 현재 구속 상태다. 이후 검찰과 경찰의 수사 책임 소재, 내부 감찰 절차 및 향후 재판에 미치는 영향이 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:39'::timestamp,'2026-07-27 18:13:18.588989'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1790,4271,'2026년 상반기 한국에서 탈모 치료제의 건강보험 급여화를 둘러싼 정책 논쟁이 발생했으며, 이재명 대통령의 지시로 정부가 청년층 대상 방안을 마련하고 국민토론회를 예정했으나, 비판 여론이 확산되자 정책 추진을 무기한 연기하고 토론회를 전격 취소했다. 이 논쟁은 청년 세대의 상대적 박탈감과 복지 제도에 대한 불신에서 비롯되었으며, 고령화로 인한 건강보험 재정의 중노년 중심 편중과 청년의 의료이용 비용 부담이 주요 배경이다. 실제로 약물의 저가 처방 및 전립선비대증 치료 경유 등 우회적 접근이 이미 시장에서 정착되어 있어, 공식 급여화가 실질적 변화를 가져오지 않을 가능성도 제기되었다. 이후 논의는 생존과 삶의 질의 경계, 자원 희소성 속에서의 우선순위 문제로 확대되었으며, 중증질환자와 소수자들의 목소리가 배제되는 구조적 문제를 드러내며, 건강보장의 보편적 원리와 공론장의 성숙한 토론 방식 마련이 시급하다는 점이 후속 쟁점으로 부각되었다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:48'::timestamp,'2026-07-27 17:10:41.302161'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1791,4273,'배재고 야구부 선수단과 지도자 등 86명이 6일 오후 광주제일고를 찾아 ''스타벅스 가야지'' 등 부적절한 응원에 대해 자필 사과문을 전달했다. 이는 지난 29일 서울 목동구장에서 열린 제81회 청룡기 전국고교야구선수권대회에서 광주제일고를 상대할 당시, 5.18민주화운동을 조롱하는 듯한 응원구호를 외친 데 따른 후속 조치다. 사과문에서 배재고는 선수들의 발언이 광주일고 선수 및 학부모, 광주 시민에게 심각한 상처를 줬다고 인정하며, 인성과 태도의 중요성을 깨달았다고 밝혔고, 감독은 지도자로서의 책임을 통감하며 자책했다. 이후 교육청은 사건에 대한 조사와 후속 조치를 진행할 예정이며, 관련 논의는 지역사회와 교육계에서 지속적으로 이어질 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:52'::timestamp,'2026-07-27 16:55:58.472433'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1792,4299,'이재명 대통령은 2024년 5월 15일 광주 군공항 부지를 호남 반도체 클러스터 조성지로 확정했다. 이는 전국 4700조 규모의 반도체·AI 투자 계획 발표 후 일주일 만이며, 삼성전자와 SK하이닉스가 국유지로 토지 수용과 보상 절차가 간소화된 점을 이유로 추천한 결과다. 부지 규모는 약 250만평(여의도 면적의 약 3배)이며, 광주 도심과 KTX역 인접으로 인력 확보와 정주 여건이 우수해 공사 기간 단축이 가능하다. 현재 군 공항 이전과 전력·산업용수 확보 등 안보 공백 해소와 인프라 구축이 남아 있으며, 20년 넘게 지속된 이전 문제 해결이 기대된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:00:56'::timestamp,'2026-07-27 17:55:48.867852'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1793,4395,'2024년 6월 17일, 한국 축구의 위기 극복을 위해 ''K-축구 혁신위원회''가 출범했다. 이는 홍명보 감독과 정몽규 회장의 잇따른 사임으로 인한 축구 혁신의 필요성과 국민 신뢰 저하가 원인이다. 박지성 위원장과 유승민 공동위원장이 공동으로 이끌며, 대표팀 경쟁력, 유소년 시스템, 축구 행정 개선 등 주요 과제를 논의하고 실질적 실행 방안 마련에 나설 예정이다. 혁신위는 대한축구협회 회장 선거를 앞두고 있으며, 향후 정책 제안과 제도 개혁의 방향성에 따라 축구 행정의 구조적 변화가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:00'::timestamp,'2026-07-27 17:07:03.919022'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1794,4276,'정몽규 대한축구협회 회장이 2026년 월드컵을 앞두고 6일 천안 코리아풋볼파크에서 열린 마지막 임원회의를 마무리하며 사임서를 제출했다. 정 회장은 2013년 첫 당선 이후 4선을 역임하며 11년간 협회를 이끌었으며, 지난달 29일 월드컵 전 사퇴를 선언한 바 있다. 사임 후 대한축구협회는 정관 제23조에 따라 부회장 중 한 명이 대한체육회의 인준을 거쳐 회장 직무를 대행할 예정이다. 이후 협회는 신임 회장 선출 절차를 진행할 것으로 보이며, 이 과정에서 내부 혁신과 조직 개편이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:03'::timestamp,'2026-07-27 16:51:18.031206'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1795,4277,'2024년 6월 6일 서울중앙지검은 HD현대오일뱅크, SK에너지, GS칼텍스, 에쓰오일 등 4대 정유사와 관련 임직원을 공정거래법 위반 혐의로 기소했다. 이들은 2021년 1월부터 최근까지 주유소에 전량구매 계약을 강제 체결하고 일방적으로 공급 가격을 통보하며 우월적 지위를 남용한 혐의를 받고 있으며, 특히 미국과 이란 전쟁 직후 유가 급등을 유도한 담합 행위가 확인됐다. 검찰은 HD현대오일뱅크와 SK에너지의 가격 결정 부서가 담합해 14.2조 원 규모의 가격 인상을 조정했으며, GS칼텍스와 에쓰오일이 이를 참고해 유가를 인상함으로써 총 약 26조 원 규모의 경쟁 제한 효과가 발생했다고 판단했다. 현재 기소된 법인과 임직원은 재판을 앞두고 있으며, 정유사들의 가격 결정 방식과 공정거래법 준수 여부에 대한 후속 조사와 제도 개선 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:08'::timestamp,'2026-07-27 16:50:25.075667'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1796,4281,'광주일고에 폭발물을 설치했다는 협박성 게시글이 온라인 커뮤니티에 게시되면서 경찰청은 5일 수사에 착수했다. 이 사건은 4일 오후 11시 47분경 특정 온라인 커뮤니티에 ''광주일고에 폭발물을 설치했다. 배재고 청소년들의 미래를 짓밟았다''는 내용의 협박성 글이 올라온 데서 시작되었으며, 이는 전날 광주일고 야구부가 전국대회에서 배재고 선수단의 지역 비하성 응원으로 인해 상처를 입은 사건과 관련이 있다. 경찰과 소방은 해당 게시글을 접한 후 폭발물 수색 작업을 실시했으나 특이 사항은 발견되지 않았고, 현재까지 피해는 없었다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:12'::timestamp,'2026-07-27 16:34:44.940260'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1797,4320,'이병태 규제합리화부위원장이 5·18 민주화운동을 ''성역''으로 규정하며 학생들의 조롱 섞인 응원을 비판한 발언으로 논란이 일자, 6일 사퇴했다. 이 부위원장은 지난 2일 페이스북에서 ''역사의 성역화''를 비판하며 학생들의 장난에 가까운 일탈도 정치적 처벌을 받는 것은 민주주의를 부정하는 것이라고 주장했으며, 이후 발언을 삭제하고 다시 ''표현의 자유''를 강조하는 글을 게시했다. 청와대는 이 발언이 정부의 혐오·조롱에 대한 단호한 거부 기조와 배치되며, 책임 있는 공직자로서 부적절하다고 판단해 사퇴를 권고했고, 이에 따라 사퇴를 수용했다. 이후 이 사건은 표현의 자유와 역사 인식 간의 갈등, 공직자의 발언 책임 등에 대한 논의로 확산될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:16'::timestamp,'2026-07-27 17:09:18.312436'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1798,4290,'조국 전 조국혁신당 대표가 걸그룹 리센느 멤버의 ''무섭노'' 표현을 일베식 혐오 표현으로 지적하며 논란을 일으켰다. 이 표현은 온라인에서 자연스럽게 사용되는 언어적 놀이로, 일부 시민사회와 정치평론가들은 이를 정치적 개입으로 보며 풍기단속반과 탐정놀이에 비유하며 비판했다. 정치권의 논란 중심 논의가 민생과 정책 문제보다 앞서면서 2030 세대의 정치적 거리감을 키우고 있다는 지적이 제기됐다. 이후 정치권의 언어 감시 논의가 지속될지, 사회적 합의를 위한 대화가 이뤄질지가 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:20'::timestamp,'2026-07-27 18:52:59.390997'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1799,4294,'국민의힘 조경태 의원이 박덕흠 국회부의장 낙선을 요청한 전화를 민주당 의원들에게 했다는 이유로 징계 요청이 제기되자, 7일 SBS 라디오 인터뷰에서 강하게 반발했다. 조 의원은 박덕흠 의원이 내란 탄핵 반대 세력이라는 점을 들어 국회 부의장으로 선출하는 것이 정상적이지 않다고 주장하며, 자신의 행동은 정당한 정치적 입장 표현이라고 밝혔다. 이에 따라 국민의힘 윤리위원회는 징계 절차를 검토 중이며, 김민수 최고위원은 조 의원에 대한 징계를 주장했고, 장동혁 대표는 해당 행위자에 대해 영구 복당 금지를 요구했다. 조 의원은 징계 대상이 아닌 장동혁 대표가 오히려 심각한 문제를 일으킨 주체라고 반박하며, 당 내부 논의와 징계 절차의 공정성에 대한 논란이 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:24'::timestamp,'2026-07-27 18:30:51.998424'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1800,4296,'김민석 전 국무총리가 2024년 6월 6일 국회 소통관에서 당 대표 출마 선언 후, 친청계 의원이 제기한 ''계엄 해제 표결 불참'' 의혹에 대해 ''대장동 때를 보는 듯하다''며 허위사실 유포에 책임을 지라고 반박했다. 이는 2022년 대선 당시 이재명 대통령과 이낙연 전 총리 간 대장동 개발비리 논란을 언급한 것으로, 정치적 비난을 일삼는 행위를 비판한 것으로 해석된다. 김 전 총리는 표결 시점에 국회에 있었으며, 소셜미디어에서 제기된 ''감기약'' 발언은 허위사실로 명예훼손에 해당한다고 주장했다. 친명계 강득구 최고위원도 같은 논리의 문제 제기를 지적하며 당 내부의 선을 지켜야 한다고 강조했고, 이는 당 내부 갈등과 정치적 논란의 지속 가능성으로 이어지고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:28'::timestamp,'2026-07-27 18:23:55.733903'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1801,4297,'이재명 대통령은 7일 나토 정상회의 참석을 위해 튀르키예 앙카라로 출국했다. 이번 참석은 취임 후 첫 나토 정상회의 참석으로, 마르크 뤼터 나토 사무총장의 초청에 따라 이뤄졌으며, 인도·태평양 파트너국(IP4) 대표들과의 소인수회담과 방위산업포럼 기조연설을 예정하고 있다. 이 대통령은 나토 동맹국들의 세계 국방비 55%를 차지하는 방산 시장과의 협력을 강화하고, 일본, 호주, 뉴질랜드 등과의 외교적 협력을 확대할 계획이다. 8일까지 튀르키예 일정을 마치고 9일부터 몽골을 국빈 방문하며, 도널드 트럼프 미국 대통령과의 현지 만남 가능성도 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:31'::timestamp,'2026-07-27 17:58:22.681196'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1802,4621,'경기도는 3일부터 5일까지 수원KT위즈파크에서 열린 브랜드 협업 행사 중 현장 참여형 여론조사를 실시해 도민이 가장 필요로 하는 정책으로 ''내 집 걱정 없는 경기''를 선택했다. 이 조사는 추미애 경기도지사가 취임식에서 강조한 ''대청마루'' 소통 철학을 구현하기 위한 것으로, 1200여 명의 참여자가 5개 정책 중에서 투표한 결과 ''내 집 걱정 없는 경기''가 520표(41.6%)로 가장 높은 지지를 받았다. 주거안정이 교통·일자리·돌봄 등 다른 정책을 앞선 결과로, 도민의 주거 문제에 대한 우려가 가장 크다는 점이 반영됐으며, 온라인 여론조사 누리집을 통한 패널 모집도 병행해 현재 누적 7만6000여 명이 참여하고 있다. 경기도는 온라인과 현장 소통 경로를 확대해 도민의 목소리가 정책에 충실히 반영되도록 하겠다는 방침을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:36'::timestamp,'2026-07-27 18:30:14.482114'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1803,4301,'정몽규 대한축구협회장이 월드컵 실패 이후 13년 5개월 만에 사임하며 축구 혁신위 출범의 계기를 마련했다. 이는 축구협회에 대한 비판 여론과 구조적 문제 해결을 위한 전면적 개혁의 필요성이 대두된 결과다. 혁신위는 박지성을 중심으로 구성되어 한국 축구의 제도적 개선과 투명성 강화를 추진 중이며, 현재 혁신 방안 수립이 진행 중이다. 한편, 트럼프 미국 대통령의 개입으로 미국 대표팀 공격수의 퇴장 처분이 취소되며 국제 스포츠 외교의 영향력이 재조명되고 있으며, 광주 5·18 민주묘지 공동 참배는 학교 간 사과와 역사 인식 개선의 사례로 평가받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:41'::timestamp,'2026-07-27 17:48:38.242738'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1804,4308,'국회 문화체육관광위원회는 2022년 월드컵 성적 부진과 감독 선임 논란을 이유로 22일 대한축구협회를 상대로 청문회를 개최할 예정이다. 축구협회는 일본의 장기적 로드맵인 ''재팬즈웨이''와 비교해 체계적인 선수 육성 시스템과 지도자 교육 체계 부재를 지적받았으며, 전문가들은 지도자 수준 저하와 젊은 인재 양성 부족을 문제로 지적했다. 이용수 축구협회 부회장은 쓴소리를 듣고 ''다음 집행부에 정리해 넘기겠다''고 밝혔으나, 차기 회장 선거 방식 등 구체적 개혁 방안에 대해서는 언급하지 않았다. 이후 청문회에서 축구협회의 조직 개편, 선임 제도 개선, 장기적 전략 수립 여부가 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:45'::timestamp,'2026-07-27 17:15:56.892925'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1805,4312,'이병태 규제합리화위원회 부위원장이 5·18 기념일을 둘러싼 발언과 페이스북 글로 인해 청와대의 공개 경고를 받은 후 자진 사퇴했다. 이 부위원장은 배재고 야구부 학생들의 스타벅스 응원 구호를 두둔하며 ''5·18이 성역이 됐다''고 발언했고, 영국 정치인 토마스 모어의 사례를 인용해 ''신념을 지키는 비용''이라는 제목의 글을 게시해 논란을 일으켰다. 청와대는 책임과 권한이 큰 대통령 직속위원회 구성원으로서 정부 국정 기조에 부합해야 한다며 사퇴를 권고했고, 사퇴 요구 후 약 두 시간 만에 사퇴 의사를 밝히고 이를 수용했다. 이 사건은 정부 고위 인사의 발언이 국정 기조와 충돌할 경우의 책임 문제와 공직자 윤리에 대한 논의를 촉발하고 있으며, 향후 공직자 발언 기준과 정책적 일관성에 대한 검토가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:49'::timestamp,'2026-07-27 17:12:39.119941'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1806,4313,'이재명 대통령이 발표한 서남권 반도체 클러스터의 부지로 광주 군공항 부지가 확정됐다. 이는 반도체 투자 계획 발표 후 일주일 만이며, 삼성전자와 SK하이닉스가 해당 부지가 토지 수용이 용이하고 도심 및 KTX 접근성이 뛰어나 적합하다고 평가한 데 기반한다. 부지 규모는 약 250만평(여의도 면적의 약 3배)으로, 국유지이므로 수용과 보상 절차가 단순해 공사 기간 단축이 가능하며, 20년 넘게 지연된 군공항 이전 문제 해결에도 기여할 전망이다. 이후 전력과 산업용수 확보, 안보 공백 해소 등 이전 과정에서의 숙제가 남아 있으며, 이 대통령은 매달 진척 상황을 직접 점검할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:54'::timestamp,'2026-07-27 17:11:46.252705'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1807,4316,'배재고등학교 야구부 학생들이 5·18 민주화운동을 ''성역''이라고 발언한 이병태 규제합리화위원회 부위원장의 발언을 두고 광주제일고등학교를 찾아 학생과 학부모에게 사과하며 자필 사과문을 낭독했다. 이병태 부위원장은 민주당의 ''민주화 역사 부정'' 비판에 따라 즉각 사퇴했으며, 이는 정치권에서 ''5·18''을 둘러싼 이념적 갈등을 심화시켰다. 사과 이후 광주제일고는 용서를 표명했으나, 국민의힘은 이를 ''집단 린치''라며 반발하며 정치적 논쟁은 지속되고 있다. 현재 이 사건은 5·18 역사 해석과 공공 인물의 발언에 대한 사회적 논의로 확산되며, 향후 정책적 논의와 교육 현장의 역사 교육 방향성에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:01:58'::timestamp,'2026-07-27 17:11:15.701891'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1808,4317,'배재고 야구부 학생들이 5·18 민주화운동의 상징적 장소인 광주제일고를 방문해 선수들과 학부모, 시민에게 직접 사과하며 반성의 자세를 보였다. 이는 지난 5·18 기념일에 학생들이 스타벅스 화환을 보내며 상징적 사건을 조롱한 사건을 계기로 한 것으로, 피해자와 지역 사회의 큰 상처를 안긴 것으로 평가받았다. 일부 정치인과 고위 공직자는 해당 행위를 ''표현의 자유''라며 정당화하며, 오히려 학생들의 사과를 무시하거나 비판하는 반응을 보였다. 이에 따라 학생들의 반성과 사과를 존중하는 사회적 분위기 조성과 어른들의 책임 있는 반성, 그리고 국가 기념일에 대한 존중이 후속 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:01'::timestamp,'2026-07-27 17:10:58.151509'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1809,4330,'7일 오전 코스피가 전 거래일 대비 5% 이상 하락하며 유가증권시장의 프로그램매도호가 일시효력정지(사이드카)가 발동됐다. 사이드카는 코스피200선물지수가 5% 이상 하락한 상태가 1분간 지속될 경우 발동되며, 발동 시점인 오전 10시 23분 41초에는 선물지수가 전일 종가 대비 66.26포인트(5.12%) 하락한 1227.32를 기록했다. 이에 따라 코스피는 오전 10시 29분 기준 7597.93로 전 거래일 대비 5% 넘게 하락하며 7500선 아래로 밀렸다. 현재까지 사이드카 발동 이후 시장의 회복세는 나타나지 않았으며, 향후 시장 안정화를 위한 추가 조치와 투자자 심리 회복 여부가 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:05'::timestamp,'2026-07-27 18:16:05.653052'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1810,4331,'삼성전자는 2024년 2분기 잠정 영업이익 89조 4000억원을 기록하며, 엔비디아의 약 82조원을 제치고 전 세계 최고 영업이익 기업으로 올랐다. 이는 D램과 낸드 메모리 시장에서 마이크론 대비 약 2배의 시장점유율을 확보한 것이 주요 원인으로, 클라우드 기업들의 메모리 수요 증가와 가격 상승세가 지속된 결과다. 영업이익률은 52.2%에 달하며, 특별성과급 충당금을 반영한 실적임에도 불구하고 100조원을 넘었을 것으로 추정된다. 증권가에서는 3분기 영업이익이 110조원을 돌파할 것으로 전망하며, 메모리 시장의 지속적 성장과 삼성의 시장 지배력이 향후 실적에 영향을 미칠 것으로 보고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:09'::timestamp,'2026-07-27 18:06:58.306299'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1811,4332,'구윤철 부총리 겸 재정경제부 장관은 7일 MBC 라디오 인터뷰에서 부동산 세제 개편안을 7월 말에 발표할 예정이라고 밝혔으며, 현재 준비 중이라고 설명했다. 이는 실거주자 중심의 주택시장을 확립하기 위해 보유세와 거래세의 균형을 맞추는 것이 핵심 목표이며, 정부는 일방적 결정보다 국민 의견을 폭넓게 수렴할 계획이다. 구 부총리는 공정시장가액비율 조정과 비거주 장기보유특별공제 축소 등 언론 보도 내용을 국민의 의견 중 하나로 수용하며, 다양한 목소리를 반영해 최종 판단할 것이라고 강조했다. 이후 국민 의견 수렴 절차를 진행하고, 세제 개편안의 구체적 내용과 시행 시점에 대한 후속 논의가 예정되어 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:13'::timestamp,'2026-07-27 18:02:14.034625'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1812,4397,'이란 남부 미나브 소재 초등학교가 2024년 2월 28일 미군의 토마호크 미사일 공습으로 폭격되면서 최소 175명의 민간인이 사망했으며, 대부분은 어린이였다. 이 공습은 이란의 대규모 군사시설이 있는 지역에서 발생했으나, 학교가 표적에 포함된 것으로 확인되며 미국은 책임을 인정하지 않고 있다. 공격 피해 유족들은 이란 수도 테헤란에서 열린 전 최고지도자 아야톨라 세예드 알리 하메네이의 장례식에 참석하기 위해 약 1300km 떨어진 지역에서 기차와 버스 등을 이용해 수일간 이동했다. 장례식 이후 하메네이의 시신은 고향인 이란 동부 마슈하드에 안장될 예정이며, 미국은 공습 조사 결과를 4개월 이상 발표하지 않고 있어 국제적 비판이 지속되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:17'::timestamp,'2026-07-27 17:03:13.081116'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1813,4420,'이재명 대통령은 6일 광주 군공항 부지에 호남권 반도체 클러스터를 조성하기로 결정하며, ''속도전''을 강조했다. 이는 지난달 29일 발표된 ''3대 메가 프로젝트''의 일환으로, 약 250만 평 규모의 국유지로 평탄화가 완료되어 공사 기간 단축이 가능하며, KTX 역과 인접해 인력 확보와 정주 여건이 우수하다는 점이 선정 이유였다. 정부는 전력과 용수의 선제적 확보를 통해 신속한 행정을 추진하고 있으며, 이에 대해 야권은 과거 비판과 대비해 이번 프로젝트에 대한 반대를 자제하라고 요구하는 태도를 지적하며 논란을 일으켰다. 이후 매달 민관합동 점검회의를 개최해 추진 상황을 직접 점검할 계획이며, 향후 행정 절차와 지역 주민 반응, 투자 유치 여부가 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:22'::timestamp,'2026-07-27 17:28:30.330789'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1814,4358,'검찰은 장윤기 사건과 관련해 광주 광산경찰서와 수사팀원들의 주거지 등에 대해 7일 압수수색을 실시했다. 장윤기는 살인·살인미수 혐의로 5월 14일 검찰로 송치되었으며, 수사 과정에서 케이블타이, 리얼돌, 차량 등 주요 증거물을 확보하지 못한 점과 수사 내용을 부친에게 누설한 혐의가 제기됐다. 광주경찰청은 수사전담팀을 구성해 사건을 재수사하고 있으며, 수사팀장 A경감은 6일 긴급 체포된 상태다. 이후 검찰과 경찰청은 수사 과정의 투명성 확보를 위해 추가 조사와 내부 감사를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:25'::timestamp,'2026-07-27 18:07:52.385265'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1815,4361,'서울 배재고 야구부 선수들이 5·18 민주화운동을 조롱하는 구호를 외친 후, 광주제일고를 찾아 80여 명의 교사·학부모·선수들이 참석한 가운데 눈물로 사과문을 읽고 성찰을 약속했다. 이는 2024년 5월 18일 광주에서 발생한 사건으로, 배재고 선수들의 발언이 5·18 민주화운동을 희화화했다는 비판을 불러일으켰으며, 광주제일고와 지역 사회의 강한 반발이 있었다. 사과 후 광주제일고는 용서를 받아들이며 배재고 선수들이 위축되지 않고 성장할 수 있도록 격려했고, 두 학교 선수들은 광주학생독립운동기념탑과 5·18 민주묘지를 참배하며 진정성 있는 성찰의 시간을 가졌다. 이후 배재고는 인성 교육 강화와 내부 점검을 위한 조치를 예정하고 있으며, 교육부는 유사한 사례에 대한 예방 교육 지침을 검토 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:30'::timestamp,'2026-07-27 17:56:08.048772'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1816,4362,'중앙선거관리위원회는 올림픽공원 핸드볼경기장에 보관 중인 투표용지에 대해 재검표를 추진하며, 비용 약 5000만원을 직접 부담하겠다고 밝혔다. 이는 지난 10일 투표용지 부족사태로 인한 진상규명위원회 제1차 회의 개최 이후 발생한 조치로, 현행 법규상 재검표는 국회 국정조사특별위원회의 의결이 전제되어야 한다. 재검표는 육안 확인과 정당·후보자별 분류 검증, 심사계수기로 매수 확인을 통해 기존 개표 결과와 일치 여부를 검증하며, 전체 247만표 재검표에는 440명이 투입해 약 9시간이 소요될 것으로 예상된다. 재검표는 국회 국정조사특위의 의결을 거쳐 진행되며, 공개 참관인 제도와 CCTV 설치를 통해 투명성을 확보하고, 완료 후 투표용지는 과천 중앙선관위 선거홍보관으로 이송될 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:35'::timestamp,'2026-07-27 17:51:44.553837'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1817,4366,'광주 여고생 살해 사건의 수사팀장이 차량에서 발견된 케이블 타이를 확보하지 않아 증거인멸 혐의로 5월 15일 긴급 체포됐다. 이 케이블 타이는 성폭행 목적이 있었는지를 판단하는 핵심 증거로, 수사 초기에 발견되었으나 압수되지 않아 현재까지 실물이 확보되지 않았다. 검찰은 경찰이 일반 살인죄로 송치한 사건을 강간살인죄로 재판에 넘기며, 최소 무기징역이 가능한 처벌 기준을 적용했다. 경찰은 수사팀장의 부정행위와 장윤기 아버지인 장모 경감이 수사 정보를 미리 전달받아 증거를 폐기한 의혹을 수사 중이며, 특별수사팀을 구성해 전면 조사할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:38'::timestamp,'2026-07-27 17:18:38.152114'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1818,4372,'2024년 5월 20일, 서울 배재고 야구부 선수들이 5·18 민주화운동을 조롱하는 구호를 외친 후 광주제일고를 찾아 사과했다. 이는 지난 5월 13일 경기에서 발생한 사건으로, 배재고 선수들의 발언이 광주 지역 시민과 학교 측에 큰 상처를 줬던 상황이었다. 사과 행사에서 배재고 감독과 선수들이 자필 사과문을 읽으며 인성과 태도의 중요성을 인식했고, 광주제일고는 사과를 수용하며 화해의 악수를 나눴다. 이후 두 학교 선수들은 광주학생독립운동기념탑과 5·18 민주묘지를 참배하며 상처를 치유하고 미래를 향한 성장을 다짐했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:42'::timestamp,'2026-07-27 17:16:32.809127'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1819,4375,'서울 종로구 창신동의 한 거리에서 오늘 새벽 5시 20분쯤 60대 남성이 마약을 투약한 상태로 길바닥에 누워 있는 것을 경찰이 발견하고, 온몸 떨림과 주머니 내 일회용 주사기, 팔의 주사 자국을 확인해 마약류 관리법 위반 혐의로 긴급체포했다. 이 남성은 음주 측정 결과 술을 마시지 않았으며, 경찰은 마약 간이시약 검사를 통해 실제 투약 여부와 범행 동기를 조사 중이다. 현재 남성은 서울 혜화경찰서에 구속되어 있으며, 마약 투약 사실이 확인될 경우 마약류 관리법에 따라 최대 10년 이하의 징역형에 처해질 수 있다. 경찰은 추가 조사와 함께 마약 사용의 유통 경로 및 관련 범죄 여부를 수사할 예정이며, 도심 내 마약 사용 사례가 증가함에 따라 관계 기관의 대응 방안이 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:47'::timestamp,'2026-07-27 17:06:32.236811'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1820,4377,'배재고 야구부 선수 36명과 지도자, 학부모가 6일 광주제일고를 찾아 지역 비하 발언으로 인한 상처를 사과했다. 이는 지난 시합에서 배재고 선수들이 광주 지역을 비하하는 발언을 한 것이 발단이었으며, 해당 발언은 학교와 교육청의 윤리 교육 부재와 인성 교육의 실패를 드러냈다. 사과 후 배재고는 자체 진상 조사와 징계 절차를 진행 중이며, 서울시교육청은 교장·교감 등 관리자에 대한 책임 소재를 검토 중이다. 이후 교육청은 유사 사례 예방을 위한 인성 교육 강화 방안과 학교 내 윤리 교육 체계 개선을 검토할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:50'::timestamp,'2026-07-27 17:03:52.429024'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1821,4379,'서울시교육청 소속 배재고등학교 야구부 학생들과 교직원, 학부모 등 86명이 5월 6일 광주제일고등학교를 방문해 ''스타벅스 구호''로 인한 5·18 광주 비하 논란에 대해 사과했다. 이 구호는 스타벅스의 ''탱크데이'' 마케팅이 5·18 민주화운동을 희화화했다는 비판과 연관되며, 전국고교야구선수권대회에서 광주일고를 상대로 반복 사용된 것이 문제로 지적됐다. 대한야구소프트볼협회는 배재고 야구팀에 전국대회 6개월 출전정지를 부과했으며, 학교는 구호를 외친 학생 2명을 생활교육위원회에 회부하고 동조자에 대한 추가 조치도 검토 중이다. 배재고는 사과 이후 5·18 민주묘지도 참배할 계획이며, 감독과 선수들은 인성과 태도의 중요성을 깨닫고 반성의 자세를 유지하겠다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:02:56'::timestamp,'2026-07-27 17:01:24.582472'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1822,4398,'이란 전 최고지도자 아야톨라 하메네이의 장례식이 2024년 7월 10일 이란에서 열렸으며, 장남 모스타파와 셋째 마수드, 막내 메이삼 등 세 아들이 참석해 공개 애도했다. 하메네이는 미국의 토마호크 미사일 공습으로 사망했으며, 이 사건은 같은 날 이란 남부 미나브 초등학교에서 발생한 오폭 참사와 겹쳐져 유가족들의 참석이 이슈가 됐다. 장례식에서는 미국과 트럼프 대통령에 대한 보복을 촉구하는 반미 집회가 벌어졌으며, 영국 국기 불태우기와 암살 요구 발언도 있었다. 차남 모즈타바는 중상으로 인해 불참했고, 10일 예정된 매장식에 등장할지 여부가 주목되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:00'::timestamp,'2026-07-27 16:55:23.284281'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1823,4401,'민형배 전남광주통합특별시장은 7일 광주 군공항 부지(약 8.2㎢)를 점검하며, 군공항이 완전히 이전되지 않아도 반도체 산단 조성을 시작할 수 있다고 밝혔다. 정부는 호남권 반도체 클러스터 입지로 광주 군공항 일원을 선정했으며, 이곳은 국유지로 평지이며 주민 수용성도 높아 산단 조성에 적합하다고 평가받고 있다. 현재까지 유류 저장시설 정화 작업은 대부분 완료되었으나, 미군 관련 송유관과 군사시설 정비 등은 여전히 과제로 남아 있으며, 전력(1GW 필요), 용수(6만t 이상) 확보도 병행해야 한다. 전남광주통합특별시는 오후 반도체 전략위원회 현판식을 열고 부지·전력·용수·인허가 등 후속 절차를 총괄하는 실무지원 체계를 가동하며, 대통령 임기 내 사업 안착을 목표로 하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:05'::timestamp,'2026-07-27 18:56:40.822678'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1824,4403,'국민의힘은 2024년 5월 7일 시행된 정보통신망법 개정안을 ''입틀막 악법''이라며 헌법소원 청구와 전면 재개정안 당론 발의를 공식화했다. 이 법은 허위 조작 정보의 유통을 막고 책임을 묻기 위한 제도적 장치로, 유럽 선진국들도 유사한 법을 도입한 바 있다. 민주당은 국민의힘의 반대를 ''정부 여당에 대한 무조건적 반대 심보''라며 법의 안정적 시행을 강조했고, 현재 법 시행 이후 온라인 정보 환경에 대한 논의가 지속되고 있다. 헌법소원 심판 절차가 진행될 예정이며, 향후 법의 시행 효과와 위헌 여부에 대한 법원 판단이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:09'::timestamp,'2026-07-27 18:34:51.429202'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1825,4408,'김민석 전 국무총리는 2024년 12월 3일 비상계엄 사태 당시 국회의 계엄 해제 표결에 불참한 점을 두고 친정청계의 비판에 대해 ''대장동 때를 보는 듯''이라며 역공했다. 그는 표결 당시 국회에 있었으며, 이후 본회의장에 착석했다고 밝히며 이성윤 의원의 비판을 허위사실에 의한 명예훼손으로 반박했다. 이성윤 의원은 김 전 총리가 감기약을 복용해 잠을 잔 것이라며 약 성분의 영향을 의심했으나, 김 전 총리는 이에 대해 사실과 다르다는 점을 강조했다. 김 전 총리는 당 대표 출마 캠페인 중 ''유튜브 백문백답''을 통해 당 내부 문화 개선과 가짜뉴스 정리 필요성을 언급하며, 검찰개혁 외에도 정부 지지와 통합 인사 기조의 엄격한 검증 필요성을 제시했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:13'::timestamp,'2026-07-27 18:28:05.218137'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1826,4411,'2026년 7월 7일, 국민의힘 윤리위원회에서 조경태 의원에 대한 징계요청이 제기되며 당내 갈등이 부각됐다. 조경태 의원은 국회부의장 선출 당시 민주당 의원들에게 ''내란옹호세력은 의장단에 앉아서는 안 된다''고 발언한 것이 해당행위라며 징계를 요청받았으며, 이는 12.3 비상계엄 반대 및 윤석열 전 대통령 탄핵 반대 세력에 대한 비판에서 비롯됐다. 징계요청은 70건에 달하며, 장동혁 당대표는 심각한 해당행위에 대해 복당금지 조항을 당헌당규 개정으로 추진하겠다고 발언해 논란이 됐다. 현재 당내에서는 장동혁 대표의 책임 회피와 당 대표 수명 연장 꼼수 논란이 제기되며, 조경태 의원은 12명의 탄핵 동참 의원이 국민의 안전을 지킨 점을 강조하며 당의 방향성에 대한 재고를 촉구하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:24'::timestamp,'2026-07-27 17:58:53.730756'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1827,4412,'이재명 대통령은 7일 NATO 정상회의 참석과 몽골 국빈 방문을 위해 튀르키예 앙카라로 출국했다. 이번 회의는 한국이 나토 인도·태평양 파트너국(IP4)으로 초청받아 처음으로 참석하는 것으로, 세계 평화와 안보에 기여하는 역할을 강조하는 것이 목적이다. 이 대통령은 튀르키예에서 뤼터 사무총장과 회담하고 방산포럼에서 기조 발언을 한 뒤, 에르도안 튀르키예 대통령의 환영 만찬에 참석하며 방산 협력 수요 국가와 양자 회담을 진행할 예정이다. 이후 몽골 울란바타르로 이동해 후렐수흐 대통령과 정상회담을 갖고 ''한몽 관계의 황금시대'' 공동선언을 발표하고, 비즈니스 포럼, 기념관 방문, 명절 개막식 등 일정을 소화한 뒤 11일 귀국할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:29'::timestamp,'2026-07-27 17:57:40.555307'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1828,4417,'정부는 호남권 반도체 클러스터를 광주 군 공항 부지(약 250만 평)에 조성하기로 결정했다. 이는 지난주 3대 메가프로젝트 발표 후 일주일 만에 부지가 확정된 것으로, 공항 특성상 평탄화가 완료되어 공사 기간 단축이 가능하고, KTX 역 인접으로 인력 확보와 정주 여건이 우수하며 국유지라 토지 수용이 수월하다는 점이 선정 이유다. 이재명 대통령은 민관합동 회의에서 ''속도전''을 강조하며 전력·용수 선제 확보와 행정 신속성을 주문했고, 야권의 비판에 대해 협조를 요구하며 ''방해는 하지 말라''고 촉구했다. 이후 국민의힘은 이 대통령의 과거 발언과 대비해 비판을 제기하며 프로젝트의 실현 가능성과 정책 일관성에 대한 논란이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:33'::timestamp,'2026-07-27 17:48:05.582916'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1829,4421,'이병태 규제합리화위원회 부위원장이 5·18 기념일에 배재고 야구부에 대한 중징계를 조롱하는 발언을 한 데 이어, 청와대의 ''사안 엄중'' 경고와 여론 압박 속에 5월 6일 사퇴했다. 이 부위원장은 지난 2일 SNS에 ''5·18이 성역이 됐다, 북한의 모습''이라는 글을 올리며 민주화 운동을 비하하는 발언을 해 논란을 일으켰고, 청와대는 이를 ''부적절한 처신''으로 규정하며 자진 사퇴를 권고했다. 사퇴 직후 이 부위원장은 정치적 민감성 부족을 인정하면서도 표현의 자유와 사회적 화두 제기의 필요성에는 변함이 없다고 밝혔다. 이후 민주당 지도부와 여권 내부에서도 사퇴를 요구하는 목소리가 커졌으며, 이재명 정부의 공직자 윤리와 사회적 가치에 대한 논의가 지속될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:38'::timestamp,'2026-07-27 17:28:50.118461'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1830,4424,'이재명 대통령은 6일 광주 군 공항 부지를 호남권 반도체 클러스터 조성 부지로 확정했다. 이는 지난달 29일 ''3대 메가 프로젝트'' 발표 후 일주일 만이며, 부지 규모 약 250만 평, 국유지로 토지 수용이 수월하고 KTX 역과 인접해 인력 확보와 정주 여건이 우수하다는 점이 선정 이유다. 정부는 전력과 용수 선제적 확보를 강조하며 신속한 행정 추진을 주문했고, 이재명 대통령은 민관합동 점검회의를 매달 개최해 프로젝트 진행 상황을 직접 챙기겠다고 밝혔다. 반면 국민의힘 장동혁 대표는 이 대통령의 과거 ''대왕고래'' 사업 비판과의 일관성 부족을 지적하며 프로젝트에 대한 비판을 자제하라는 입장에 대해 반발하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:42'::timestamp,'2026-07-27 17:29:18.501014'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1831,4428,'국세청은 지난해 10월 부동산 탈세 혐의자 104명을 조사해 80여 명에게 총 731억 원의 탈루를 적발하고, 그중 318억 원의 양도세를 추징했다. 일부는 가짜 매매를 통해 1세대 1주택 비과세를 악용하거나, 어머니 친구와 허위 거래를 통해 실거주 목적 없이 고가 아파트를 취득한 사례가 확인됐으며, 증여세를 신고하지 않은 외국인 배우자와의 공동 취득 사례도 적발됐다. 이 중 A 씨는 양도세 10억 원, C 씨는 증여세 13억 원을 추징받았고, 관련자 6명은 검찰 고발, 4명은 벌금 상당액 7억 원 납부 통고처분을 받았다. 국세청은 앞으로도 ''부동산 탈세 신고센터''를 통해 제보를 검증하고, 다주택자 증여세 편법 행위를 집중 점검할 계획이며, 제보자 포상금 지급도 신속히 시행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:47'::timestamp,'2026-07-27 18:51:08.596867'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1832,4433,'삼성전자는 2024년 2분기 영업이익 89조 4천억 원을 기록하며 분기 기준 역대 최고 수치를 달성했다. 이는 지난 2023년부터 2024년까지 3년간의 영업이익 합계를 한 분기에 벌어들인 것으로, 성과급 충당금 17조 원을 제외한 수치로, 실제 영업이익은 약 106조 원으로 평가된다. 반도체 사업 부문이 전체 이익의 대부분을 차지했으며, 글로벌 AI 인프라 투자 확대와 메모리 가격 상승으로 인한 공급 부족이 주요 원인으로 분석된다. 반도체 수요는 최소 내년까지 지속될 전망이나, 완제품 사업은 원가 부담으로 인해 부진한 실적을 유지하고 있으며, 주식시장에서는 삼성전자와 SK하이닉스의 하락으로 코스피가 7천700선까지 하락했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:52'::timestamp,'2026-07-27 18:33:19.457780'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1833,4450,'구윤철 부총리 겸 재정경제부 장관은 7월 말께 부동산 세제 개편을 발표할 예정이며, 보유세와 거래세의 균형을 고려해 조정할 방침이다. 정부는 실거주자 중심의 주택 시장 정착을 목표로 하며, 국민 의견과 현장 목소리를 반영해 최종 방침을 결정할 계획이다. 현재까지는 공정시장가액비율 조정 및 비거주 장기보유 특별공제 축소 등 방향성이 논의되고 있으나, 구체적 내용은 미정이다. 이후 정기국회(9월) 전에 관련 법안을 제출하고, 반도체 호황으로 인한 추가 세수를 활용해 미래대응기금을 조성해 AI, 로봇, 조선 등 혁신 산업과 청년 교육·창업 지원에 투자할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:03:57'::timestamp,'2026-07-27 18:09:08.647237'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1834,4486,'중국 해군은 6일 태평양 공해상에서 전략핵잠수함을 통해 사거리 1만km 이상의 잠수함발사전략미사일(SLBM) 1발을 성공적으로 발사했다. 중국 관영매체는 이 발사가 국가 주권과 안보 수호 의지의 표현이며 아시아·태평양 지역의 평화와 안정을 보장하는 데 기여한다고 주장했으며, 발사 전 관련국에 사전 통보했다는 점을 책임감 있는 행동으로 평가했다. 대만 국방 전문가들은 이 미사일이 미국 본토를 사정권에 두는 ''쥐랑-3''(JL-3)일 가능성이 높으며, 미국의 대만 방어 개입을 억제하기 위한 핵 억지력 강화의 목적을 지닌다고 분석했다. 이에 따라 미국과 호주, 일본 등 일부 국가가 우려를 표명했으나, 실무 차원의 반응에 그치며 중국의 평화적 행보가 국제적 신뢰를 얻었다는 평가가 나오고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:02'::timestamp,'2026-07-27 18:51:38.867325'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1835,4489,'엔화 약세 베팅 규모가 2007년 이후 최대치로 증가하며, 7일 오후 1시 기준 달러당 161.88엔 수준까지 하락했다. 이는 미국과 일본 간 금리 격차 확대와 다카이치 사나에 총리의 대규모 지출 계획, 일본은행의 예상보다 빠른 금리 인상에도 불구하고 지속된 약세 흐름을 반영한다. 일본 당국은 4월 28일부터 한 달간 사상 최대인 약 727억 달러를 투입해 엔화 방어에 나섰으나, 시장 전문가들은 개입 효과가 제한적일 것으로 전망하며 170엔 수준까지 약세가 이어질 가능성도 제기했다. 일본 재무상은 언제든 환율 조치를 취할 수 있다고 밝혔으나, 시장은 일본은행의 추가 금리 인상 가능성과 연준의 금리 정책 방향에 따라 금리 격차가 더 벌어질 수 있다는 우려를 내비쳤다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:08'::timestamp,'2026-07-27 18:41:55.229169'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1836,4454,'2026년 7월 3일 서울회생법원은 홈플러스의 회생절차 폐지를 결정하며, 2000억 원의 최소 운영자금 조달 실패를 이유로 14일 이내 즉시항고 기한을 부여했다. 이는 대주주 MBK파트너스와 최대 채권자 메리츠금융그룹이 자금 지원 책임을 서로에게 전가하며 협상이 결렬된 결과로, 홈플러스는 1만 2000명의 직고용 노동자와 4600여 개 협력업체의 생계가 위협받고 있다. 현재까지 MBK는 2000억 원 무상 증여 약속을 이행하지 못했으며, 법원은 회생계획의 실행 가능성을 의심하고 있어 재정적 재편이 시급한 상황이다. 이후 14일 내 자금 조달이 실패할 경우 홈플러스는 청산 수순을 밟고, 정부는 청산 전제로 임시 방편적 지원책을 마련했지만, 공적자금 투입 등 회생을 위한 직접적 개입은 포함되지 않았다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:19'::timestamp,'2026-07-27 18:11:28.039209'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1837,4456,'2024년 6월 28일 뉴욕증시에서 다우지수는 사상 처음으로 5만 3천선을 돌파하며 역대 최고치를 기록했고, 나스닥과 S&P 500 지수도 각각 1% 이상, 0.7% 이상 상승했다. 기술주와 금융주, 커뮤니케이션 업종이 주도하며 상승세를 이끌었으며, AI 관련 기술주 반등과 2분기 실적 기대감, 경기 확장세 및 고용 회복 지표가 투자심리를 뒷받침했다. 미국 공급관리협회가 발표한 6월 서비스업 구매관리자지수는 54를 기록해 24개월 연속 확장세를 유지했고, 고용지수는 2월 이후 처음으로 확장세로 전환했다. 다음 주에는 델타항공과 펩시코의 실적 발표가 예정되어 있으며, 내수 소비와 여름철 여행 수요 전망이 시장에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:23'::timestamp,'2026-07-27 17:53:10.291263'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1838,4459,'JTBC가 기업회생 절차를 밟으며 연기자들의 출연료 수십억 원을 미지급한 사건이 발생했다. JTBC는 지난달 12일 206억 원 규모의 유동화 차입금 상환에 실패해 채무불이행 상태에 들어갔고, 계열사 4곳은 회생절차를 신청했으며, 서울회생법원은 JTBC에 대해 자율구조조정 프로그램을 승인했다. 현재 ''냉장고를 부탁해''와 ''아는 형님'' 등 주요 프로그램의 출연료 지급이 지연되고, 재방송료까지 연쇄적으로 차질을 빚어 총 피해 규모가 수십억 원에 달하는 것으로 파악됐다. 한국방송연기자노동조합은 JTBC에 피해 연기자에 대한 해명과 출연료 미지급 현황의 투명한 공개, 변제 계획 수립을 촉구하며, 촬영 중단으로 인한 일자리 손실에 대한 책임 회피를 비판하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:28'::timestamp,'2026-07-27 18:58:23.017240'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1839,4462,'배재고등학교 야구부 학생들이 5.18 관련 부적절한 구호를 외쳐 대한야구소프트볼협회로부터 6개월 출전 정지 중징계를 받은 사건에 대해 가수 하림이 SNS를 통해 배재고 앞에 늘어선 근조화환 행렬을 비판했다. 이는 5.18을 연상시키는 정치적 메시지를 담은 구호 외침으로 인한 사회적 논란이 확산되며, 피해자와 학생들의 정서적 상처를 악화시킬 수 있다는 우려에서 비롯됐다. 하림은 근조화환과 정치적 성향을 담은 응원 화환 모두가 꽃의 본질을 훼손하는 혐오의 수단이 되었다고 지적하며, 학교 앞에 노출된 이러한 행위가 아이들의 등교를 두려움으로 만들 수 있다고 강조했다. 이후 배재고 학생과 학부모, 교사들은 광주제일고를 찾아 공식 사과하고 국립 5·18 민주묘지를 참배하는 등 사과 절차를 진행했으며, 향후 교육계와 사회적 논의를 통해 청소년의 정치적 표현과 교육 환경의 균형에 대한 대안이 모색될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:33'::timestamp,'2026-07-27 18:58:37.468332'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1840,4467,'공정거래위원회는 대상㈜, (유)사조CPK, ㈜삼양사, CJ제일제당㈜ 등 4개사가 2018년 5월부터 2023년 10월까지 7년 5개월에 걸쳐 전분·전분당 가격을 담합한 혐의로 총 7천476억 원의 과징금을 부과했다. 이는 식품·제지·철강 등 산업용 원료로 사용되는 전분당 시장에서 4개사가 주요 점유율(전분 95.7%, 전분당 86.4%)을 차지하며 가격 인상·인하 시기와 폭을 합의하고, 실수요처에 가격을 인하하되 소규모 거래처에는 가격을 유지하는 방식으로 이익을 극대화한 것으로 드러났다. 담합으로 인해 관련 매출액은 6조 525억 원에 달했으며, 특히 코로나19와 러시아-우크라이나 전쟁 등으로 원가가 상승한 시기에도 판매 가격을 1㎏당 559원에서 971원으로 최대 73% 인상했고, 원가 하락 시에도 인하 폭을 줄여 영업 이익을 개선했다. 공정위는 과징금 외에 3년간 반기별 보고를 요구하는 독자적 가격 재결정 명령과 법 위반 행위 금지 명령을 내렸으며, 이는 전분당 시장의 과점 구조와 장기 담합으로 인한 재발 우려를 고려한 조치다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:42'::timestamp,'2026-07-27 18:52:31.684620'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1841,4497,'모건스탠리의 마이클 윌슨 최고주식전략가는 6일(현지시간) 보고서를 통해 반도체주 상승 모멘텀이 약화되고 있으며, 하이퍼스케일러(대규모 데이터센터 운영기업)로의 투자 이동이 순환매를 유발하고 있다고 분석했다. 이는 아마존·마이크로소프트·메타플랫폼 등 AI 인프라 투자 확대에 따른 기술주 중심의 투자 열기 후, 수익성 확보 미흡과 연준 금리 인상 기대 후퇴, 국제 유가 하락 등이 반도체 투자 심리에 부정적 영향을 미쳤기 때문이다. 필라델피아반도체지수는 지난달 고점 대비 약 14% 하락했으며, 6월 한 달간 11% 상승 후 최근 2주 사이 11% 넘게 급락했고, 지난해 9월 이후로도 여전히 123% 상승한 수준이다. 윌슨 전략가는 반도체주 조정 전망과 함께 하반기에는 경기소비재·운송·바이오테크 등으로의 자금 이동이 예상되며, 연말 S&P 500 목표치로 8,000선을 제시했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:48'::timestamp,'2026-07-27 18:22:54.704601'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1842,4468,'광주지검은 여고생 살해범 장윤기(23)의 아버지와 수사팀 간 유착 의혹을 수사하기 위해 7일 광산경찰서에 압수수색을 실시했다. 이는 장윤기 아버지가 경찰 수사 과정에서 케이블타이, 리얼돌, SUV 등 주요 증거물을 확보하지 못하게 하고, 수사 상황을 누설한 혐의로 인해 발생한 것으로, 검찰은 형사과 수사팀 관계자들을 공무상비밀누설 및 증거인멸교사 등으로 입건했다. 검찰은 수사 초기부터 증거물이 사라지고 리얼돌이 폐기된 점을 중대한 문제로 보고 직접 수사에 착수했으며, 관련 경찰관들의 주거지까지 압수수색했고, 장윤기 아버지는 증거인멸 행위를 했으나 친족 특례로 형사입건되지 않았다. 경찰은 수사팀장 A 경감을 자체적으로 긴급체포하고 구속영장을 신청했으며, 수사 주체를 광주경찰청 전담팀에서 국가수사본부 특별팀으로 격상해 인력을 파견하는 등 경찰 내부 수사도 병행하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:04:53'::timestamp,'2026-07-27 18:53:34.046621'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1843,4470,'국세청은 부동산 탈세 혐의로 A·B·C·D·E·F 등 80여 명을 조사해 총 318억 원의 세금을 추징했다. 이들은 1세대 1주택자로 거짓 신고를 하거나, 친구·가족을 활용한 허위 매매, 증여세 누락, 비자금 조성 등을 통해 양도세·증여세·소득세를 회피한 것으로 확인됐다. 특히 A 씨는 모친 친구와의 가짜매매로 양도세를 회피했고, C 씨는 남편 친구를 이용한 가장매매로 6억 원, D 씨는 미등록 여행업체 운영으로 25억 원, E 씨는 외국인 배우자와의 공동 취득을 통해 4억 원, F 씨는 부모로부터 증여받은 자금으로 13억 원의 증여세를 회피했다. 국세청은 앞으로도 부동산 거래 전 과정에서 탈세 위험을 조기에 포착하고, ''부동산 탈세 신고센터''를 통해 제보를 검증해 세금을 추징하며, 제보자에 대한 포상금 지급도 추진할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:00'::timestamp,'2026-07-27 18:38:20.791728'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1844,4476,'광주지검은 여고생 살해범 장윤기 사건의 경찰 수사팀에 대해 공무상 비밀누설과 증거인멸 혐의로 7일 광주광산경찰서 및 관련 주거지 등을 압수수색했다. 이 사건은 5월 발생한 여고생 살해 사건에서 수사팀이 장윤기 아버지인 A 경감에게 범행 장소 주소, 구속 영장 내용, DNA 감식 보고서 등 수사 기밀을 유출하고, 핵심 증거물인 리얼돌을 폐기한 것으로 드러나 논란이 됐다. 검찰은 수사팀의 부실 수사와 정보 유출 행위를 중대한 직무유기로 판단해 경찰 수사와 별개로 직접 수사에 착수했으며, 수사팀 경찰관들은 입건됐으나 A 경감은 친족 특례법 적용으로 형사 처벌 불가로 별도 입건되지 않았다. 이후 검찰은 수사 결과를 바탕으로 공직자에 대한 징계 절차와 수사팀의 책임 소재를 명확히 하기 위한 후속 조치를 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:05'::timestamp,'2026-07-27 18:34:33.956588'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1845,4479,'정이한 전 개혁신당 부산시장 후보와 음료를 던진 A 씨에 대해 부산 금정경찰서는 위계공무집행방해와 공직선거법 위반 혐의로 구속영장을 청구했으며, 검찰은 3일 부산지법에 이를 신청했다. 정 전 후보는 2022년 4월 27일 부산 금정구 구서 나들목에서 유세 중 차량에서 던진 음료에 맞아 쓰러졌다고 주장했으나, 경찰은 사건 전후 연락 내역과 A 씨가 헬스장 트레이너로 정 전 후보와 친분이 있었던 점 등을 근거로 사전 공모 가능성을 수사해왔다. 사건 발생 67일 후인 6월 1일 구속영장이 청구되었으며, 정 전 후보는 6·3 지방선거에서 2만7천418표(득표율 1.56%)를 얻어 3위에 그쳤다. 현재 구속 전 피의자 심문은 8일 오후 2시 부산지법에서 진행되며, 정 전 후보 부친의 온그룹 계열사 동원 여부와 여론조사기관의 공정성 의혹 등도 별도 수사 중이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:10'::timestamp,'2026-07-27 18:29:42.896335'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1846,4480,'2024년 3월, 경기 고양시에서 80대 어머니를 살해한 아들 A씨와 아버지 B씨가 ''촉탁살인''을 주장하며 헌법재판소에 재판소원을 제기했다. 이들은 2014년부터 11년간 어머니를 간병하며 병세 악화와 생활고, 주거지 퇴거 위기 등으로 인해 동반자살을 결심했으며, 피해자가 사망 전 지속적으로 ''죽여달라''고 요청했다고 주장한다. 범행 후 아들은 한강에 투신했으나 구조되었고, 법원은 각각 존속살해 및 마약류관리법 위반 혐의로 아들 A씨에게 징역 7년, 아버지 B씨에게 징역 3년을 선고했다. 헌법재판소는 이들의 재판소원을 받아들일지 여부가 불확실하며, 지난달까지 접수된 재판소원 1200건 중 전원재판부 회부는 단 10건에 그쳤다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:15'::timestamp,'2026-07-27 18:58:04.548893'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1847,4501,'다카이치 사나에 일본 총리는 2024년 연내 개정을 추진 중인 3대 안보 문서 논의에서 비핵 3원칙 중 ''핵 반입 금지'' 조항의 재검토 가능성을 시사하며, 모든 과제에 대해 논의할 것이라고 밝혔다. 일본의 비핵 3원칙은 핵무기 보유, 제조, 반입을 금지하는 국시로, 미국의 핵우산에 기반한 확장 억지력 강화와 맞물려 전술 핵의 역내 배치를 금지해 왔다. 일본유신회는 ''반입 금지'' 조항의 현실적 검토를 요구했고, 자민당은 이를 언급하지 않으며 확장 억지력의 신뢰성 강화를 주장하며 현 상태 유지 입장을 밝혔다. 다카이치 총리는 당 내부의 입장 차이에 당혹감을 표하며 연말까지 검토 작업이 필요하다고 언급했고, 나토 정상회의에는 외무상과 방위상이 대신 참석할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:20'::timestamp,'2026-07-27 18:15:15.135471'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1848,4503,'미국 헤지펀드 시추에이셔널 어웨어니스, 영국 자산운용사 베일리 기포드, 미국 벤처캐피탈 코튜 등 3개 기관이 SK하이닉스의 미국주식예탁증서(ADR) 공모에 최대 70억 달러(약 10조7천억원)를 인수할 의사를 밝혔다. 이는 전체 공모 물량 280억 달러의 약 25%에 해당하며, SK하이닉스는 발행주식의 약 2.5%에 해당하는 신주 1천779만주를 ADS 형태로 나스닥에 상장할 예정이다. 현재까지 투자자들의 수요는 견조한 편으로 평가되며, 특히 AI 및 테크 분야에 강점을 가진 기관들의 참여가 주목받고 있다. 다만 메모리 반도체 시장의 사이클 타이밍과 상장 시점의 적절성에 대한 전망은 엇갈리며, 향후 상장 후 주가 변동성과 장기 성장 가능성에 대한 투자자 반응이 주요 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:25'::timestamp,'2026-07-27 18:13:55.533100'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1849,4507,'2026 북중미 월드컵 16강전에서 프랑스 대표팀 주장 킬리앙 음바페가 파라과이 상원의원 셀레스테 아마리야의 인종차별 발언을 강력히 규탄했다. 아마리야 의원은 4일 프랑스와 파라과이의 16강전에서 음바페가 페널티킥을 성공시킨 후 그의 출신, 외모, 가정교육 등을 조롱하는 인종차별적 발언을 엑스에 게시했다. 이에 음바페는 ''그 자리에 있을 자격이 없는 비열한 여성''이라며 발언을 비판했고, 프랑스 스포츠부 장관과 프랑스축구협회는 이를 ''용납할 수 없는 혐오 발언''으로 규정하며 사법 당국에 고발할 계획을 밝혔다. 파라과이 정부는 해당 발언이 국가나 국민을 대변하지 않으며 인간 존엄성과 평화로운 공존의 가치에 위배된다고 밝혔고, 프랑스는 1-0으로 승리하며 8강에 진출했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:30'::timestamp,'2026-07-27 18:07:12.248047'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1850,4508,'미국은 6일(현지시간) 중국이 태평양 공해 해역에서 핵 탑재 가능 잠수함발사탄도미사일(SLBM)을 시험 발사한 것을 비판하며, 중국이 대륙간탄도미사일 및 우주발사체 발사에 대해 정기적인 통보 체제를 마련하고 군비통제 논의에 참여할 것을 촉구했다. 이는 중국이 연간 군사 훈련 일정에 따라 발사한 것으로, 유관 국가에 사전 통보했으며 특정 국가나 목표를 겨냥한 것이 아니라고 설명한 바 있다. 일본과 타이완은 발사의 투명성 부족과 역내 긴장 고조를 우려하며 각각 심각한 우려를 표명했고, 일본은 발사가 영토나 배타적경제수역 상공을 통과했으나 피해는 확인되지 않았다고 밝혔다. 미국은 동맹국 방위 공약을 지키며 중국의 핵무기 증강과 군사 활동에 대한 국제적 대응을 강조하고 있으며, 향후 군비통제 논의 참여 여부와 발사 통보 체제 구축이 주요 쟁점으로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:36'::timestamp,'2026-07-27 18:05:26.496630'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1851,4510,'베네수엘라에서 지난 4월 24일(현지시간) 발생한 연쇄 지진으로 사망자가 3,535명으로 집계됐으며, 이는 전날보다 193명 증가한 수치다. 지진은 라과이라주 등 일부 지역에서 건물 856채가 피해를 입고, 그중 190채가 완전 붕괴되며 대규모 인명 피해와 이재민 발생을 초래했다. 정부는 육군과 보안군 2만 9,567명을 투입해 자원봉사자와 함께 구조·복구 작업을 진행했으나, 지진 발생 후 10일이 경과하면서 생존자 구조 가능성은 급격히 감소했고, 현재까지 구조된 인원은 6,462명으로 확인됐다. 일부 SNS를 통해 퍼진 어린이 4명 구조 소식은 오보로 확인되며, 현지 언론은 해당 보도를 바로잡았고, 구조 현장의 신뢰성과 정보 전달의 정확성에 대한 우려가 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:40'::timestamp,'2026-07-27 18:04:54.100246'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1852,4512,'일본 미쓰비시전기의 폐에어컨에서 희토류를 재활용하는 사업이 중국 관영매체에 의해 ''실행 불가능''하고 ''홍보용''으로 평가받았다. 이는 중국이 전 세계 희토류 생산과 가공을 독점하고 있어 공급망 리스크를 줄이기 위한 일본의 도시광산 전략이지만, 에어컨 한 대당 희토류 함유량이 약 10.5g에 불과해 수집 및 정제 비용이 원광석 구매보다 높아 경제성 부족으로 지적됐다. 특히 재활용되는 대부분은 경희토류이며, 전기차와 군사장비에 필수적인 중희토류는 거의 포함되지 않아 전략적 가치가 제한적이다. 중국은 이에 대해 비용 문제와 기술 집중 구조를 지적하며 일본의 노력은 자원 안보 차원의 대비일 뿐, 중국을 이기려는 목적은 아니라고 보고 있으며, 일본은 이 사업을 상업용 시스템으로 확대해 해외 의존도를 낮추는 방향으로 나아가고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:47'::timestamp,'2026-07-27 17:59:48.710078'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1853,4525,'한국경제인협회는 7일 서울 여의도 FKI타워 컨퍼런스센터에서 ''AI와 일자리의 공존: 노동시장의 구조적 변화와 대응전략'' 세미나를 개최해 AI 확산에 따른 고용 구조 변화에 대응하기 위해 근로자 역량 강화와 직무 재설계 필요성을 제시했다. OECD 연구에 따르면 AI는 향후 10년간 연간 노동생산성 증가율을 0.4~0.9%포인트 끌어올릴 잠재력이 있으나, 금융·법률 등 고임금 부문의 AI 노출도가 높고, 돌봄·운송·음식점 등 저임금·저숙련 부문은 인력 대체가 어려워 노동수급 불균형이 심화될 수 있다. 세미나에서는 AI 도입을 통해 생산성 향상과 고용 안정을 동시에 달성하기 위해 중소기업과 취약계층 지원, 교육훈련 확대, 고용 친화적 AI 도입 지원, 그리고 역량 중심의 인재 채용·육성 생태계 구축이 필요하다는 의견이 나왔다. 이후 정부는 AI 시대에 맞춘 평생학습 제도 확대, 기업의 채용·교육훈련 비용 지원, 근로자의 역량 분석을 기반으로 한 직무 전환 경로 제공 등 정책적 대응이 필요하며, 이는 2024년 이후 정책 논의와 제도 개편의 핵심 과제로 부상하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:05:54'::timestamp,'2026-07-27 18:45:42.452315'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1854,4528,'롯데바이오로직스는 송도 바이오캠퍼스 제1공장의 상업 생산 준비를 위해 2553억원 규모의 유상증자를 단행했다. 이는 12만 리터 규모의 항체의약품 생산시설로, 2024년 착공 후 약 2년 만에 건설을 완료하고 사용승인을 획득한 후 시운전 및 생산 시스템 검증을 위한 후속 투자다. 확보한 자금은 공장 건설 잔금 및 운영 비용에 사용되며, 2024년 하반기부터 시운전을 시작해 GMP 생산 체계를 확보할 예정이다. 롯데그룹은 이번 투자를 포함해 총 1조4600억원을 롯데바이오로직스에 투자했으며, 미국 시러큐스와 송도를 연계한 ''듀얼 사이트'' 전략을 통해 글로벌 CDMO 시장 경쟁력을 강화하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:00'::timestamp,'2026-07-27 18:40:54.770862'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1855,4541,'LG전자는 2024년 2분기 영업이익으로 1조5788억 원을 기록하며 전년 동기 대비 146% 증가했다. 이는 반도체 및 가전 사업의 수익성 개선과 함께 글로벌 수요 회복 및 원가 효율화가 주요 원인으로 분석된다. 2분기 실적은 전년 대비 두 자릿수 성장률을 기록하며, 특히 로보틱스와 데이터센터 냉각 기술 분야에 대한 시장 관심이 증가하고 있다. 향후 LG전자는 AI 기반 제품 확대와 글로벌 시장 진출 전략을 통해 성장세를 지속할 전망이며, 외부 전문가들은 목표 주가를 상향 조정하며 긍정적인 전망을 제시했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:04'::timestamp,'2026-07-27 18:22:36.428108'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1856,4542,'코스맥스는 프랑스 BIPEA가 주관한 자외선 차단 지수 숙련도 평가에서 ISO 23675 기반 체외 SPF 평가법을 활용해 ''새티 스팩 토리(Satisfactory)'' 등급을 달성했다. 이 평가는 자외선 차단 수치가 제공되지 않은 블라인드 시료를 대상으로 체외 평가를 수행한 후 결과를 제출하는 방식으로, 코스맥스는 안정적인 결과 도출을 통해 평가 역량을 입증했다. ISO 23675는 PMMA 판을 이용한 비임상 평가법으로, 인체 시험 대비 평가 기간 단축과 피부 자극 없이 자외선 흡수 특성을 측정할 수 있어 유럽 시장 진출을 위한 제품 개발에 유리하다. 코스맥스는 올해 2월부터 이 평가법을 도입해 선케어 연구개발 및 평가 인프라를 강화하고 있으며, 유럽 시장 진출을 추진하는 고객사 지원을 확대할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:09'::timestamp,'2026-07-27 18:21:38.816277'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1857,4600,'국회 6·3 지방선거 투표용지 부족 사태 국정조사특위는 7일 중앙선거관리위원회에서 현장 조사를 진행하며, 선관위가 투표용지 부족 사태를 인지한 지 1시간 반 이상이 지난 후야 비로소 지침을 내리는 등 총체적인 대응 부실했다고 지적했다. 사태는 6월 3일 선거 당일 서울 올림픽공원 개표소와 송파구 선관위에서 발생했으며, 선관위 상황실의 느슨한 운영과 정보 취합 지연, 민원 처리 미비 등이 원인으로 분석됐다. 투표 종료 후에도 송파구 선관위에 4만2000여 장의 투표용지가 남아 있었음에도 일부 투표소에서 용지가 부족해 투표가 중단되는 상황이 발생했고, 이에 대해 특위는 재분배 조치만으로도 참정권이 보장될 수 있었다고 강조했다. 이후 핸드볼경기장에 보관된 투표용지의 공개 검증 및 재검표 절차가 논의되며, 검증 목적과 공식 절차의 명확화가 필요하다는 후속 쟁점이 제기됐다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:15'::timestamp,'2026-07-27 18:57:32.259404'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1858,4558,'투썸플레이스는 7일 서울국제정원박람회 아이파크 정원에서 IPARK현대산업개발과 함께 ''IPARK X 투썸플레이스, 텀블러와 함께하는 특별한 한 잔'' 캠페인을 진행했다. 이번 캠페인은 서울국제정원박람회 방문객들이 일회용 컵 사용을 줄이고 다회용기를 직접 사용하는 친환경 소비 문화를 체험할 수 있도록 하기 위해 마련되었으며, 민관 협력 방식으로 성동구자원봉사센터 등과 함께 진행됐다. 캠페인 기간 동안 선착순 400명에게 세척된 텀블러에 아이스 아메리카노와 아이스티를 제공했으며, 현재 투썸플레이스는 POS, 키오스크, 투썸하트 앱, 테이블오더 등 모든 주문 채널에서 개인 텀블러 사용 옵션을 운영하고 있다. 투썸플레이스는 이번 캠페인을 계기로 일상 속 다회용기 사용 문화 확산을 지속적으로 추진할 계획이며, 향후에도 친환경 가치 실천을 위한 다양한 활동을 이어갈 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:21'::timestamp,'2026-07-27 18:02:33.840189'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1859,4565,'hy는 7일 면역 기능과 장 건강을 동시에 관리할 수 있도록 설계한 ''바이오리브 면역 유산균''을 출시하며 브랜드 라인업을 확대했다. 이 제품의 주원료인 ''HY7017''은 인삼 뿌리에서 분리한 유산균으로, 식품의약품안전처로부터 국내 최초로 면역 증진 기능성을 인정받았으며, 동물실험과 인체적용시험에서 자연살해세포(NK Cell) 활성도가 5.0% 증가하고 면역 반응에 관여하는 사이토카인 2종에서 긍정적 변화가 확인됐다. 제품은 실온 보관이 가능한 3중 차단 구조의 유산균 전용 용기와 초소형 캡슐 형태로 제작되어 섭취 편의성을 높였으며, 네이버 스마트스토어 등 주요 온라인 채널에서 판매 중이다. hy는 이 제품을 계기로 액상 중심이던 기존 제품군을 분말과 캡슐 등으로 확대하며 고기능성 프로바이오틱스 제품의 지속적 개발을 추진할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:26'::timestamp,'2026-07-27 18:01:01.609485'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1860,4573,'국제금융센터는 7월 글로벌 리스크 1위로 ''위험자산 가격 조정''을 지목했다. 이는 원달러환율이 1500원선을 넘는 고환율 지속과 강달러 리스크 확대, 선진국 고금리 지속, AI 투자 버블 우려 등이 복합적으로 작용한 결과다. 위험자산 가격 조정의 발생가능성은 높음, 영향력은 매우 높으며, 달러화 강세(5위)와 호르무즈해협 정상화 지연(4위)도 주요 리스크로 분류됐다. 이후 연준의 통화정책 방향과 미국의 경제적 우위가 지속될 경우 강달러 현상이 지속될 수 있으며, 글로벌 자금 흐름과 기술주 변동성에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:30'::timestamp,'2026-07-27 18:53:17.562329'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1861,4575,'전분·전분당 제조·판매 업체인 대상, 사조CPK, 삼양사, CJ제일제당 등 4개사가 2018년 5월부터 2025년 10월까지 약 7년 5개월에 걸쳐 전분당 가격을 담합한 사실이 적발됐다. 이들은 옥수수 가격 상승 시 빠르게 판매가를 인상하고 하락 시 인하를 지연하며 영업이익을 유지했으며, 러시아·우크라이나 전쟁으로 국제 옥수수 가격이 급등한 2022년에는 판매가를 최대 73% 인상했다. 공정거래위원회는 이들에 대해 총 7475억 7800만 원의 과징금을 부과하고, 법 위반행위 금지명령과 독자적 가격 재결정 명령을 내렸으며, 이는 공정위 역사상 최대 규모다. 이번 조치는 전분당 시장의 독과점 구조와 장기적 담합이 소비자와 후방산업에 미친 영향을 반영한 것으로, 향후 유사 담합 행위에 대한 감시와 제재가 강화될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:37'::timestamp,'2026-07-27 18:48:16.796318'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1862,4584,'공정거래위원회는 대상, 사조CPK, 삼양사, CJ제일제당 등 4개 전분당 제조 및 판매사업자에 대해 2016년 9월부터 2025년 6월까지 입찰담합 및 2017년 8월부터 2025년 10월까지 부산물 가격 담합 혐의를 추가로 심의하기 시작했다. 입찰담합은 포스코 등 7개 대형 실수요처의 전분 및 전분당 입찰에 사전에 낙찰자, 가격, 물량을 합의하고 배분한 행위로, 관련 매출액은 9400억 원으로 추산됐으며, 부산물 가격 담합은 3개 업체가 매달 가격을 조율한 것으로, 매출액은 1조5500억 원에 달했다. 공정위는 공정거래법 제40조 위반으로 판단하고, 입찰 담합에 대해 최대 1880억 원, 부산물 가격 담합에 대해 최대 3100억 원의 과징금을 부과할 수 있다고 밝혔다. 업체들은 8주 내 서면 의견과 증거자료를 제출할 수 있으며, 공정위는 방어권 절차를 마친 후 최대한 신속하게 전원회의를 열어 처분을 결정할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:43'::timestamp,'2026-07-27 18:36:54.414402'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1863,4585,'국세청은 2023년 10월 1일부터 진행한 초고가주택 부동산 탈세 동시조사에서 104명에 대해 세무조사를 실시해 총 731억원의 탈루금액을 확인하고, 318억원을 추징했다. 주요 탈세 수법으로는 가장매매, 가족 간 편법 증여, 법인자금 유출, 미등록 사업 수입을 통한 아파트 취득 등이 있었으며, 이 중 6명은 사기 및 부정행위로 검찰에 고발됐고, 4명은 통고처분(총 7억원)을 받았다. 부동산실명법 위반 20명은 관할 지자체에 통보되어 과징금 및 형사처벌 조치가 예정되어 있으며, 특히 고가아파트를 1세대 1주택자로 위장해 양도소득세를 회피한 사례가 다수 적발됐다. 국세청은 앞으로도 다주택자 증여거래, 가족 간 저가 양도, 매매 위장 거래 등 세금 회피 행위를 지속적으로 점검하고, 조세정의와 주택시장 안정을 위해 강력한 대응을 이어갈 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:49'::timestamp,'2026-07-27 18:31:10.577268'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1864,4587,'홈플러스는 3일 서울회생법원의 기업회생절차 폐지 결정을 앞두고 있으며, 이에 따라 파산 가능성이 높아지고 있다. 홈플러스는 지난해 3월 회생절차를 시작해 6월 임금과 퇴직급여 지급이 지연되며, 12월부터 고용노동부가 서울남부지청 전담반을 구성해 모니터링 중이다. 현재 6월 임금은 미지급 상태이며, 퇴직급여도 자금 부족으로 중순 지급 지연 공지가 있었으나, 퇴직 후 14일이 지나지 않은 경우는 체불로 판단되지 않아 상황은 유동적이다. 홈플러스는 회생절차 폐지 결정일로부터 14일 이내에 즉시항고를 제기할 수 있으며, 이를 통해 결정 취소 가능성이 남아 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:53'::timestamp,'2026-07-27 18:30:02.629237'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1865,4592,'정부는 7월 말 세제개편안을 발표할 예정으로, 부동산 보유세와 거래세를 함께 개편해 실거주 중심의 주택시장을 확립하기로 했다. 최근 집값 안정과 실수요자 보호를 위해 부동산 세제 개편을 추진하며, 공정시장가액비율 조정과 비거주 장기보유특별공제 축소 등 구체적 방안을 검토 중이다. 보유세와 거래세의 균형을 고려해 두 세제를 통합적으로 손질하고, 지방 근로자에 대한 소득세 감면 및 자녀 교육비 지원 등 지역 균형발전을 위한 세제 혜택도 검토 중이다. 이후 국민 의견 수렴을 거쳐 최종안을 확정하고, 9월 정기국회 전에 관련 법안을 마련할 계획이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:06:57'::timestamp,'2026-07-27 18:05:54.591322'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1866,4597,'SK하이닉스는 10일 나스닥거래소에 미국주식예탁증서(ADR)로 상장할 예정이며, 미국과 영국의 기관투자자 3곳이 최대 70억달러를 투자할 의향을 시사했다. 이는 SK하이닉스의 전체 공모 물량(약 280억달러)의 4분의 1 수준으로, 전 오픈AI 연구원이 설립한 헤지펀드 시추에이셔널어웨어니스, 영국 베일리기포드, 미국 코튜 등이 참여한 것으로, AI 및 테크 분야에 강한 투자 성향을 보이고 있다. 상장 이후 미국 투자자 접근성 확대와 나스닥100 지수 편입 가능성, 관련 ETF 및 인덱스펀드의 기계적 매수 수요 기대가 있으며, 마이크론과의 기업가치 비교가 시장 관심사로 부각되고 있다. 다만 ADR와 국내 주가 간 가격 괴리와 AI 호황의 지속성에 대한 시장 변동성 우려가 존재하며, 단기적 국내 주가 재평가 가능성은 제한적이라는 전망도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:03'::timestamp,'2026-07-27 18:50:48.549916'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1867,4633,'삼성전자는 2024년 2분기 연결 기준 매출 171조원, 영업이익 89조4000억원을 기록하며 역대 최대 실적을 달성했다. 이는 전년 동기 대비 매출 129.3%, 영업이익 1810.3% 증가한 수치로, AI 인프라 수요 확대와 반도체 공급 부족, 메모리 가격 상승이 주요 원인으로 분석된다. 반도체 부문(DS)이 실적을 주도한 반면, 완제품 부문(DX)은 원가 부담으로 상대적으로 부진했다. 한편, 제9호 태풍 ''바비''는 7일 오전 중심기압 910hPa, 최대풍속 초속 56m로 매우 강한 세력을 유지하며 서북서진 중이며, 한반도 직접 접근 가능성은 낮지만 장마전선과 폭염에 영향을 줄 수 있어 기상청이 주의를 당부했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:08'::timestamp,'2026-07-27 18:02:54.907638'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1868,4639,'더불어민주당은 서울 송파구 올림픽공원 핸드볼경기장 개표소에 남아 있는 247만 장의 투표용지에 대해 여야 협의를 통해 재검표와 수개표를 추진하는 방안을 적극 검토하겠다고 밝혔다. 이는 6·3 지방선거에서 선관위 투표용지 부족 사태로 인한 신뢰 위기와 함께 국정조사특위가 조사 중인 문제에 따른 조치다. 현재 국조특위는 중앙선관위와 서울시 선관위를 대상으로 현장 조사를 진행하며, 투표용지 처리 과정의 투명성과 정당성을 확보하기 위한 절차를 밟고 있다. 이후 여야 협의를 통해 재검표 실시 여부가 결정될 예정이며, 이는 선거 제도의 신뢰 회복과 향후 선거 운영 개선에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:12'::timestamp,'2026-07-27 18:22:20.983793'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1869,4640,'민주당은 6일 국민의힘이 선관위 특별검사 추천권을 본인들만 행사해야 한다고 주장하며 특검법 처리를 방해하고 있다며, 이에 대한 소모적 공방을 중단하고 실질적 논의에 나서야 한다고 촉구했다. 선관위는 1963년 설립된 헌법상 독립기관으로 삼권분립 원칙에 따라 행정부·국회·법원과 동등한 지위를 갖으며, 특정 정당이 추천권을 독점하는 것은 반헌법적 주장이라는 것이 민주당의 입장이다. 민주당은 특검 추천권을 직접 행사하겠다고 한 바 없으며, 이해당사자인 정치권이 아닌 제3의 기관이 추천하는 것이 객관성과 중립성을 확보하는 합리적 방식이라고 설명했다. 이후 국민의힘의 특검법 추진 의지와 실질적 논의 참여 여부가 향후 정치적 논의의 핵심 쟁점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:17'::timestamp,'2026-07-27 18:18:09.375260'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1870,4642,'중앙선관위는 6·3 지방선거 투표지 247만매를 송파구 잠실 올림픽공원 개표소에서 과천청사로 이송하기 전 약 9시간 소요 및 5천만원의 비용이 드는 검증 절차가 필요하다고 밝혔다. 이는 투표지 장기 보관으로 인한 국민 불안 해소와 올림픽공원 핸드볼경기장의 본연 기능 회복을 위한 조치로, 현재 보관된 투표지는 서울시장 선거 37매, 송파구의회 마선거구 25만매, 잠실7동 4만매 등이다. 검증에는 육안 확인, 정당별 분류, 인력 440명이 필요하며, 이송은 국조특위 추천자 1명씩 참관하에 차량에 적재 후 과천청사로 이송하고, 촬영 및 경찰관 동승, 특수봉인 및 CCTV 설치로 보안을 강화할 계획이다. 국조특위는 14일과 22일 청문회를 거쳐 잠정 결과보고서를 채택할 예정이며, 투표지 무결성 입증을 위해 법적 근거가 없는 선관위 자체 재검표는 불가능해 국조특위 의결을 통한 검증이 필요하다고 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:23'::timestamp,'2026-07-27 18:13:36.282373'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1871,4643,'정점식 국민의힘 원내대표는 2026년 7월 7일 시행 예정인 개정 정보통신망법을 ''입틀막법''이라며 헌법소원을 청구하고 전면 재개정안을 당론으로 발의하겠다고 밝혔다. 이 법은 국가가 사실 여부와 혐오의 기준을 직접 정하고 처벌하는 독소 조항을 포함해 위헌이라는 비판이 제기되며, 조선시대 연산군이 관리들에게 입을 닫고 혀를 간직하라며 신언패를 착용하게 했던 만행과 유사하다는 지적이 나왔다. 정 원내대표는 이 법이 정치적 이해관계에 따라 사실과 거짓이 뒤섞이고, 아이돌의 사투리 한마디에도 ''일베 낙인''이 찍히는 등 마녀사냥식 폭력을 정당화하며 공포와 침묵의 사회를 조장할 것이라고 주장했다. 이후 헌법소원 심판 절차가 진행될 예정이며, 이 법의 시행 전에 재개정안이 통과될지 여부가 정치적 논쟁의 초점이 될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:28'::timestamp,'2026-07-27 18:11:43.459333'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1872,4645,'김민석 전 총리는 12·3 비상계엄 당시 국회의 계엄 해제 표결에 불참한 점을 두고 친청계의 비판에 대해 ''대장동 사건 때를 보는 것 같다''고 반박했다. 이는 친청계가 그의 계엄 불참에 대해 ''감기약을 먹고 잤다''는 해명을 문제 삼으며 이재명 대통령을 비판했던 대장동 사건과 유사한 맥락에서 비판을 펼쳤다는 점에서 비유적 표현이다. 김 전 총리는 표결 시점에 국회에 있었으며, 표결 직후 본회의장에 착석했다고 밝히며 이성윤 의원의 발언을 허위사실에 의한 명예훼손으로 반박했다. 이후 이성윤 의원은 계엄과 관련한 전화를 받고도 국회에 오지 않은 점을 문제 삼았으며, 이에 대한 법적 대응 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:31'::timestamp,'2026-07-27 18:05:06.346442'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1873,4646,'김민석 전 국무총리는 7일 KBS 라디오에 출연해 친청계 의원들이 그의 계엄 해제 표결 불참에 대해 ''감기약 먹고 잤다''는 발언을 제기한 것에 대해 ''대장동 때를 보는 듯하다''며 비판했다. 이성윤 최고위원 등 친청계 의원들은 김 전 총리가 계엄 선포 직전 국회에 불참한 이유에 대해 ''감기약 성분''과 ''민주당 의원과 통화했다''는 근거를 들어 의혹을 제기했으며, 이는 김 전 총리가 허위사실에 기반한 명예훼손이라고 반박했다. 김 전 총리의 당대표 출마 선언 직후 친청계 의원들이 연달아 비판을 쏟아내는 등 내부 갈등이 심화되고 있으며, 반면 친명계 의원들은 그를 지지하며 진영 간 대립 구도가 확대되고 있다. 이후 정치권은 김 전 총리의 공식 출마 여부와 내부 분열이 당 대표 선거에 미치는 영향에 대해 주목하고 있으며, 향후 논란이 지속될 가능성도 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:36'::timestamp,'2026-07-27 18:07:37.486039'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1874,4647,'이재명 대통령은 7일 나토 정상회의 참석과 몽골 국빈 방문을 위해 튀르키예 앙카라로 출국했다. 이는 취임 후 첫 나토 정상회의 참석으로, 마르크 뤼터 나토 사무총장의 초청에 따라 성사되었으며, 지난달 G7 정상회의에 이어 국제사회의 평화와 안보 기여를 위한 외교적 지평을 확장하는 계기로 평가된다. 이번 일정에서는 나토 방위산업포럼에서 기조발언을 하며 방산협력 강화를 선언했고, IP4 국가 대표들과의 소인수회담을 통해 인도·태평양 지역과의 군사적 협력 가능성을 타진했다. 트럼프 미국 대통령의 현지 방문 예정으로 인해 양자 대면 가능성에 관심이 쏠리며, 8일까지 튀르키예에 머무른 뒤 9일부터 몽골 국빈방문을 진행할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:41'::timestamp,'2026-07-27 17:59:38.002898'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1875,4648,'이재명 대통령은 7일 한화오션이 캐나다 잠수함사업(CPSP) 우선협상대상자로 선정되지 못한 데 대해 ''도전에는 성공도 있지만 아쉬움도 따르기 마련''이라며 앞으로 나아가는 자세의 중요성을 강조했다. 이는 6일 마크 카니 캐나다 총리가 독일 티센크루프마린시스템스(TKMS)를 최종 우선협상대상자로 선정한 데 따른 결과로, 한화오션은 예비 공급업체로 지정되며 협상권을 보유하고 있다. CPSP 사업은 캐나다 해군의 까다로운 기술 요구 조건을 충족한 TKMS와 한화오션 모두가 경쟁했으며, 최종적으로 TKMS가 선정됐다. 이 대통령은 이번 실패를 기술 고도화의 계기로 삼고, 연구개발, 수출 지원, 국제협력 강화를 통해 K 방산의 글로벌 경쟁력을 제고하겠다는 방침을 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:46'::timestamp,'2026-07-27 17:54:12.126647'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1876,4650,'이재명 대통령은 호남권 반도체 클러스터의 부지로 광주 군공항 부지를 선정하고, 행정 절차를 최소화해 속도를 내도록 지시했다. 광주 군공항 부지는 약 250만 평 규모로 평탄화가 완료되어 공사 기간 단축이 가능하며, 도심과 KTX역 인접으로 인력과 물류 접근성이 뛰어나 선택된 배경이다. 이 대통령은 용인 산단의 부지 확정부터 착공까지 6년이 걸렸던 사례를 들어 행정 절차 병행 추진과 전력·용수 선제 확보를 강조하며, 야당의 ''호남 특혜'' 주장에 대해 ''불가능하다는 전제로 비난하지 말라''고 당부했다. 이후 매달 민관합동 점검회의를 통해 기업 투자 계획의 완공 이행을 직접 관리할 예정이며, 이는 2024년 6월 이후 진행될 행정 절차와 투자 집행에 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:51'::timestamp,'2026-07-27 17:51:58.401140'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1877,4655,'감사원은 2022년 이후 4년 만에 중앙선관위 및 지방선관위의 회계를 대상으로 회계 검사에 착수했으며, 이는 지방선거 투표용지 부족 사태와 관련된 예산 집행 내역을 점검하기 위한 것이다. 감사원은 통상보다 약 4배 많은 42명을 투입해 검사력을 강화했으며, 헌법재판소의 직무 감찰 금지 결정으로 인해 회계 검사 방식으로 전환했다. 국회 국정조사특위는 7일 중앙선관위와 서울시 선관위를 현장 조사하며, 선관위의 총체적 무능과 불신을 지적하며 감사의 필요성을 강조했다. 여야는 특검 도입에 공감하지만, 특검 추천 방식(제3자 추천 vs 여당 추천 후보 배제)을 두고 공방을 이어가며, 특검 출범까지 지연될 가능성이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:55'::timestamp,'2026-07-27 17:50:35.860501'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1878,4659,'국민의힘은 지방선거 이후 처음으로 중앙윤리위원회를 재가동해 현역 의원들에 대한 무더기 징계 심의에 착수했다. 친한계 의원들을 겨냥한 징계요청서가 수십 건 접수되며, 특히 부산 북구갑 보궐선거에서 무소속 한동훈 의원을 지지한 행위가 해당행위로 판단되면서 논란이 확산되고 있다. 징계 대상으로는 한동훈 무소속 의원과 오세훈 서울시장도 포함되며, 당내에서는 징계 정치라는 비판과 기강 유지 필요성에 대한 엇갈린 반응이 나타나고 있다. 윤리위의 결정이 당내 계파 갈등의 분수령이 될 전망이며, 향후 징계 결과에 따라 당의 내부 통합 여부가 좌우될 것으로 보인다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:07:59'::timestamp,'2026-07-27 17:15:01.233601'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1879,4660,'한국 해군의 최신 잠수함 ''도산안창호함''이 미국 하와이 진주만 기지에서 열리는 세계 최대 다국적 해상훈련 ''림팩''에 참가하며, 태평양을 횡단한 장거리 작전 능력을 입증했다. 이는 캐나다 정부가 내일(7일) 발표할 예정인 60조 원 규모의 차세대 잠수함 사업 최종 수주자 선정에 긍정적 영향을 미칠 것으로 기대된다. 도산안창호함은 국내 기술로 개발된 3천 톤급 잠수함으로, 4,300km 거리를 이동하며 해군의 기술력과 전력 운용 능력을 세계에 과시했다. 캐나다 정부의 최종 결정 발표를 앞두고, 한국의 수주 가능성에 대한 관심과 국제적 반응이 집중되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:03'::timestamp,'2026-07-27 17:13:22.653439'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1880,4661,'이재명 대통령은 호남권 반도체 클러스터의 부지로 광주 군공항 부지를 선정하고, 행정 절차를 최소화해 속도를 내도록 지시했다. 광주 군공항 부지는 약 250만 평 규모로 평탄화가 완료되어 공사 기간 단축이 가능하며, 도심과 KTX역 인접으로 인력과 물류 접근성이 뛰어나고, 전력·용수도 선제 확보를 요구했다. 이에 따라 용인 산단의 부지 확정부터 착공까지 6년이 걸렸던 점을 비교하며, 행정 지연을 막고 투자 집행을 가속화할 계획이다. 야당의 ''호남 특혜'' 주장에 대해 ''불가능하다는 전제로 비난하지 말라''며 협조를 촉구했고, 매달 민관합동 점검회의를 통해 투자 계획의 완공 이행을 직접 관리할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:07'::timestamp,'2026-07-27 17:14:31.328359'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1881,4663,'이병태 규제합리화위원회 부위원장이 5·18 관련 폄훼 발언으로 논란이 일자, 사퇴 권고를 받은 지 약 2시간 만에 자진 사퇴했다. 이 부위원장은 5·18 민주화 운동을 ''사실과 다르게 해석한 것''이라는 비판을 받으며, 청와대와 여당 지도부, 최측근 의원들까지 사퇴 압박에 나서며 정치적 위기 상황에 놓였다. 사퇴 직전까지 강경한 입장을 유지했으나, 임명권자와 정부에 부담을 주지 않겠다는 판단과 권고에 따라 직을 내려놓았다. 이후 청와대는 이 부위원장의 사퇴를 수용하며, 이 대통령의 포용적 정책 기조가 유지될 것임을 강조했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:10'::timestamp,'2026-07-27 17:14:48.403643'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1882,4664,'국민의힘은 정보통신망법 개정안 시행을 하루 앞두고 검은 마스크를 착용한 채 ''입틀막법''이라며 반발했으며, 이재명 대표 반대 댓글이 사라질 것이라고 주장했다. 이 법은 가짜뉴스와 혐오 표현을 규제하기 위한 것으로, 민주당은 공론장과 피해자를 보호하기 위한 최소한의 방어벽이라며 표현의 자유 제한이 아니라고 설명했다. 법 적용은 악의성, 부당이익, 명확한 법익 침해가 모두 인정될 경우에 한정되며, 현재까지 관련 신고 건수는 12건으로 집계됐다. 여야는 법 시행 이후 표현의 자유와 가짜뉴스 방지 간 갈등이 심화될 것으로 전망하며, 향후 법적 해석과 집행 기준에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:14'::timestamp,'2026-07-27 17:14:13.746231'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1883,4666,'2026년 7월 7일, 코스피 지수는 장중 8%대 급락하며 서킷브레이커가 발동됐다. 이는 글로벌 금융시장 불안과 미국 연방준비제도(Fed)의 금리 인상 전망 확대 등에 따른 투자자 심리 악화가 원인으로 분석된다. 코스피는 전일 대비 8.2% 하락하며 2,350선까지 밀렸고, 거래량은 전일 대비 2배 이상 증가하며 시장의 급격한 변동성이 확인됐다. 이후 금융당국은 시장 안정을 위해 유동성 공급 조치를 검토하고 있으며, 향후 금리 정책과 경제 지표 발표가 시장 흐름을 좌우할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:23'::timestamp,'2026-07-27 18:44:58.623053'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1884,4667,'7일 오전 10시 23분 41초, 코스피200선물지수가 전일 종가 대비 5.12% 하락하며 5% 이상 하락 조건을 충족, 유가증권시장의 프로그램매도호가가 5분간 정지되는 ''매도 사이드카''가 발동됐다. 이는 코스피200선물지수가 1분간 5% 이상 하락할 경우 자동으로 발동되는 시장 안정장치로, 이날 발동 시점의 코스피200선물지수는 1,227.32였다. 코스피 지수는 오전 10시 29분 현재 5% 이상 급락해 8,000선을 밑돌며 7,597.93에 거래되고 있으며, 이는 7,800선 이하로 후퇴한 상황이다. 이후 시장의 안정화 여부와 추가 사이드카 발동 가능성, 향후 시장 회복 전망 등이 주요 쟁점으로 부각되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:27'::timestamp,'2026-07-27 18:20:48.950718'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1885,4668,'2026년 7월 7일 코스피 지수가 급락하면서 증권사가 매도 사이드카를 발동했다. 이는 코스피가 하락 출발하며 8,000선 아래로 떨어진 상황에서 시장 안정을 위해 자동으로 작동한 조치이다. 매도 사이드카 발동으로 인해 주식 거래에 제한이 생기며, 투자자들의 매도 물량이 일시적으로 억제되는 효과가 나타났다. 이후 금융당국과 증권사가 시장 동향을 모니터링하며 추가 조치 여부를 검토할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:35'::timestamp,'2026-07-27 18:16:22.229034'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1886,4669,'마이크론은 포드자동차와 차세대 차량용 반도체 장기공급 계약을 체결했다. 이는 최근 자동차의 첨단 운전자 보조 시스템(ADAS)과 고전력 인포테인먼트 시스템 등에 메모리 칩이 증가하면서 반도체 수요가 급증한 배경에서 이뤄졌다. 마이크론은 버지니아주에 첨단 D램 생산시설을 확충하는 투자 계획을 추진하며, 올해 들어 D램 가격이 약 70% 상승한 상황에서 공급 안정화를 도모하고 있다. 이후 마이크론은 미국 내 반도체 생산 인프라 확대와 함께 자동차 업계와의 장기 협력 관계를 강화할 예정이며, 이는 글로벌 반도체 공급망 재편의 일환으로 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:39'::timestamp,'2026-07-27 18:09:43.541974'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1887,4680,'캐나다 정부는 차세대 잠수함 12척 건조 사업의 우선협상대상자로 독일 TKMS를 선정했다. 이 프로젝트는 빅토리아급 잠수함 4척의 2030년대 퇴역에 대비해 디젤 잠수함 12척을 건조하고, 30년간 유지보수를 포함해 총 60조 원 규모로 진행된다. 한화오션이 지난 2023년부터 참여해 2023년 말까지 적격 후보로 선정되었으나, 최종적으로 독일 업체가 선정되면서 수주 실패했다. 캐나다 정부는 독일과 협상이 결렬될 경우 한화오션을 다음 우선협상대상자로 선정할 수 있다고 밝혔다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:43'::timestamp,'2026-07-27 17:50:18.322041'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1888,4685,'삼성화재는 암·뇌혈관·심장질환 등 6개 질병 영역의 치료비와 간·폐·신장·근골격계 질환까지 보장하는 신상품 ''온(ON)통보장''을 출시했다. 기존 상품은 치료비 보장에 그쳤으나, 이번 상품은 치료비 외에도 돌봄 서비스인 방문요양과 가사 돌봄을 지원하는 요양보호사 서비스를 추가하며 치료 후 회복 단계까지 보장하는 통합보장 구조를 도입했다. 가입 후 10년마다 보장금액이 최초 수준으로 복원되며, 치료비로 사용하지 않은 잔여 보장금액의 일정 비율을 사망보험금(상해)으로 활용할 수 있다. 삼성화재는 이 상품을 건강고지형과 간편고지형으로 운영하며, 갱신형·비갱신형 및 해약환급금 미지급형을 선택할 수 있도록 했으며, 향후 의료 환경 변화에 맞춘 서비스 확대를 예고했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:47'::timestamp,'2026-07-27 16:50:13.098032'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1889,4691,'올해 상반기 농식품과 농산업 수출액 합계가 70억 5천만 달러(약 10조 8천억 원)로 역대 최고를 기록했다. 핵심 원인은 K-푸드 수출의 중심 상품인 라면의 수출액이 작년 대비 28% 증가한 9억 4천만 달러(약 1조 4천억 원)에 달했으며, 미국을 비롯한 중동 지역을 포함한 다양한 시장에서 성장세를 보였다. 과자류는 4억 달러로 7% 이상 증가했고, 아이스크림과 김치, 농기계, 비료 등도 각각 유럽, 인도, 필리핀 등으로 수출이 확대되며 성장세를 유지했다. 앞으로도 라면을 비롯한 K-푸드의 해외 시장 확대와 농식품 수출 다각화 전략이 지속될 전망이며, 정부는 수출 유망 시장 개척과 품질 관리 강화를 통한 지속 가능한 수출 성장 방안을 모색할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:52'::timestamp,'2026-07-27 16:38:33.704124'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1890,4693,'홈플러스는 법원의 회생절차 폐지 결정으로 인해 파산 절차에 들어갈 가능성이 높아졌으며, 14일 안에 2천억 원 규모의 자금 조달을 못 할 경우 공중분해 후 자산 매각 절차를 밟게 된다. 홈플러스는 대주주인 MBK파트너스와 최대 채권자인 메리츠금융그룹으로부터 자금 지원을 받지 못했고, 점포 62개가 메리츠에 신탁 담보로 잡혀 있어 독자적으로 매각 가능하다. 메리츠는 점포 부지를 주상복합·물류센터·오피스 등으로 용도 변경해 매각하는 방안을 추진하며, 동대문점은 이미 공동주택 복합 시설로 재개발된 사례가 있다. 현재 홈플러스는 파산 신청 전망이며, 노조는 정부의 적극적 개입을 요구하고 있으며, 자산 청산 과정은 부동산 시장 침체로 인해 장기화될 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:08:57'::timestamp,'2026-07-27 16:37:20.403898'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1891,4701,'2026년 7월 7일, 서울 배재고등학교 학생들이 광주에서 발생한 5·18 민주화운동 관련 발언 논란으로 인해 광주제일고 학생들과 지역 주민에게 사과했다. 이는 배재고 학생들이 과거에 5·18을 비하하는 발언을 한 후, 사회적 비판과 정치권의 공방이 확산되면서 발생한 사건이다. 사과는 학생들의 인성과 태도 문제를 인식한 결과로, 광주 지역 사회와 교육계에서 논란이 지속되고 있으며, 교육부는 관련 사안에 대한 조사와 교육 정책 개선을 검토 중이다. 이후 배재고는 학생 대상 인성 교육 강화와 지역 역사 교육 프로그램 도입을 예정하고 있으며, 정치권은 이 사건을 통해 교육 정책의 방향성에 대한 논의를 이어가고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:07'::timestamp,'2026-07-27 18:30:34.207292'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1892,4704,'2026년 7월 7일, 광주 군 공항 부지에 호남 반도체 클러스터 조성 계획이 발표됐다. 이는 반도체 산업의 지역 균형 발전과 기술 경쟁력 강화를 위해 정부가 추진하는 3대 메가프로젝트 중 하나로, 기존 군 공항의 폐기 후 산업용 부지로 전환하는 것이 핵심이다. 해당 클러스터는 전력·용수 인프라 확충과 함께 2027년부터 본격적인 공사에 들어가며, 무안군수 등 지역 관계자들이 토지보상 및 인프라 준비를 진행 중이다. 이후 정부는 2026년 하반기 중 토지 보상 절차를 완료하고, 2027년 초까지 반도체 팹 입주 기반 조성을 목표로 하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:17'::timestamp,'2026-07-27 17:46:00.752261'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1893,4705,'삼성전자는 2026년 2분기 영업이익으로 89.4조 원을 기록하며, 엔비디아를 제치고 글로벌 기업 중 영업이익 1위를 달성했다. 이는 반도체 수요 증가와 AI 관련 제품 수요 확대, 특히 메모리 반도체 시장에서의 강세가 원인으로 분석된다. 삼성전자의 2분기 영업이익은 전년 동기 대비 약 120% 증가했으며, 이는 글로벌 반도체 시장에서의 점유율 확대와 함께 기술 경쟁력 강화의 결과다. 이후 삼성전자는 반도체 시장의 지속적 성장과 AI 기술 확산에 따른 투자 확대 계획을 발표하며, 향후 시장 지배력 유지 여부가 주목받고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:26'::timestamp,'2026-07-27 17:45:41.545009'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1894,4710,'광주지검은 ''여고생 살해범'' 장윤기의 아버지와 수사팀 간 유착 의혹을 조사하기 위해 7일 광주 광산경찰서에 수사관을 파견해 압수수색을 실시했다. 이는 장윤기 사건 담당 경찰관들이 5월 5일 긴급체포 후 케이블타이, 리얼돌, SUV 등 주요 증거를 확보하지 않고, 현직 경찰인 장윤기 아버지에게 수사 상황을 누설한 혐의로 공무상비밀누설 및 증거인멸 등으로 입건된 데 따른 조치다. 검찰은 경찰의 자체 수사와 별도로 직접 수사를 진행하며, 관련 경찰관들의 주거지까지 압수수색하고, 수사 주체를 광주경찰청 전담팀에서 국가수사본부로 격상해 인력을 파견했다. 이후 검찰은 수사 결과를 바탕으로 추가 입건 여부와 경찰 내부 징계 절차, 그리고 수사의 투명성 확보를 위한 제도적 개선 방안을 논의할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:31'::timestamp,'2026-07-27 18:19:19.302689'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1895,4718,'개정된 정보통신망법이 7일 시행되며, 고의로 허위정보를 유포한 게재자는 최대 5배의 징벌적 손해배상 책임을 지게 됐고, 하루 평균 이용자가 100만 명 이상인 대형 플랫폼은 신고된 허위·조작 정보에 대해 삭제나 차단 조치를 의무화했다. 법은 허위정보를 ''의도적으로 인격권, 재산권 또는 공공의 이익을 침해하는 정보''로 정의했지만, ''공공의 이익 침해''의 범위가 모호해 법 적용의 모호성과 남발 우려가 제기됐으며, 피해 당사자 외 누구나 신고할 수 있어 특정 집단이 반대 의견을 차단하는 수단으로 악용할 가능성도 제기됐다. 법 시행 후 한 달 만에 국회 국민청원에 14만 명 이상이 동의하며 철회를 요구했고, SNS에서는 ''7·7법 극복법''이라는 표현 방식 팁이 확산되며 ''셀프 검열'' 현상이 우려되고 있다. 여당은 이 법이 가짜뉴스 피해자 보호를 위한 최소한의 방어책이라고 설명했으나, 표현의 자유 침해 논란과 함께 향후 법 해석 및 집행 기준에 대한 논의가 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:37'::timestamp,'2026-07-27 18:05:42.376943'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1896,4725,'베네수엘라에서 발생한 연쇄 강진으로 사망자가 3,535명으로 증가했으며, 6일 기준 부상자는 6,740명, 이재민은 1만 7,854명으로 집계됐다. 지진 발생 후 11일 만에 어린이가 구조됐다는 보도는 소셜미디어에서 확산된 오보로, 현지 일간 엘나시오날이 구조 영상이 이전 장면이었다고 정정했다. 현재까지 구조된 인원은 6,462명이며, 이 수치는 지난 2일 이후 변동이 없으며, 육군과 보안군 2만 9,567명, 자원봉사자 2만 7,930명이 구조·복구 작업에 투입되고 있다. 지진 발생 후 열흘을 넘긴 상황에서 매몰자 생환 가능성은 낮아졌으며, 정부는 지속적인 구조 활동과 복구를 추진하고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:41'::timestamp,'2026-07-27 18:08:54.446833'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1897,4726,'이란 이슬람혁명수비대(IRGC)는 2024년 3월 7일 오만 리마 동쪽 15km 지점에서 남쪽으로 항해 중이던 유조선 2척 중 한 척을 미사일로 공격했다. 이는 미국과 이란이 종전을 위한 양해각서(MOU)를 체결한 이후에도 혁명수비대가 강경 노선을 유지하고 있음을 보여주는 사건으로, 특히 아야톨라 하메네이 전 최고지도자의 장례기간 나흘차에 발생했다. 공격으로 유조선 좌현에 발사체가 충돌해 화재가 발생했으나 인명피해나 환경오염은 보고되지 않았으며, 피해 선박은 카타르 국영 LNG 산업의 해운 계열사가 소유한 ''알 레카야트''로 추정된다. 혁명수비대는 해상 무선통신을 통해 ''미사일과 드론은 언제든 발사할 준비가 돼 있다''고 경고하며, 오만 해안 인근 미군이 지정한 항로를 이용하지 말 것을 위협했고, 이는 이후 외교적 긴장과 해상 안보 리스크를 야기할 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:46'::timestamp,'2026-07-27 18:21:58.169592'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1898,4729,'베네수엘라에서 지난 6월 24일 발생한 연쇄 지진으로 사망자 수가 3,535명으로 집계됐으며, 부상자는 1만 6,740명, 이재민은 1만 7,854명으로 확인됐다. 지진은 라과이라주 등 주요 지역에서 856채의 건물이 피해를 입고, 그중 190채가 붕괴되며 구조 작업이 긴급히 진행됐다. 정부와 자원봉사자 등 총 약 5만 7천 명이 구조·복구 활동을 벌였으나, 지진 발생 12일째를 넘긴 현재 매몰자 생환 가능성은 희박한 상태다. 일부 SNS를 통해 퍼진 어린이 4명 구조 소식은 오보로 확인되며, 현지 언론은 잘못된 정보 유포에 대해 사과했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:50'::timestamp,'2026-07-27 18:00:04.780592'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1899,4738,'미국 전역에서 열돔 현상으로 인한 폭염으로 최소 25명이 사망했으며, 뉴저지주에서만 22명이 에어컨이 없는 주거지나 차량에서 사망한 것으로 확인됐다. 폭염은 뉴욕 등지에서 체감온도 43도까지 치솟으며 초콜릿이 녹는 등 일상이 위협받았고, 폭염과 함께 북쪽 찬 공기와 충돌해 폭우까지 발생했다. 반면 남미 아르헨티나는 겨울임에도 불구하고 7월 초 평균 기온이 한국의 늦가을 수준이었으나 체감온도가 0도까지 떨어지고, 눈이 내리지 않는 수도 부에노스아이레스에서도 눈이 내리는 이례적인 강추위가 발생했다. 극단적인 기상 현상이 빈번해지고 있는 상황에서 기후 변화에 따른 기상 패턴의 변화가 지속될 경우, 각국의 대응 정책과 기상 예보 시스템의 개선이 필요하다는 지적이 제기되고 있다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:55'::timestamp,'2026-07-27 17:13:08.636308'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1900,4744,'베냐민 네타냐후 이스라엘 총리는 2023년 10월 5일 미국 폭스뉴스 인터뷰에서 이란 문제를 포함해 미국과의 관계에 균열이 없다고 밝혔다. 그는 미국이 이스라엘을 ''모범적인 동맹''이라고 평가하며, 양국이 이란의 핵무기 프로그램 폐기와 핵연료 농축시설 해체라는 동일한 목표를 공유하고 있다고 강조했다. 이어 트럼프 미국 대통령을 역대 가장 친밀한 동맹자로 평가하며, 트럼프가 이스라엘의 레바논 폭격에 대해 격하게 반응한 사례도 언급했고, 백악관 회동을 제안받아 북대서양조약기구(NATO) 정상회의 다음 주에 회담이 열릴 가능성을 시사했다. 한편, 네타냐후 총리는 레바논 남부 기독교 마을들이 헤즈볼라로부터 보호를 요청했다고 밝히며 이스라엘의 보호 의지를 재확인했다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:09:59'::timestamp,'2026-07-27 16:44:56.150803'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1901,4745,'이란의 알리 하메네이 전 최고지도자(2023년 2월 28일 사망)의 장례식은 3월 3일부터 테헤란에서 진행됐으며, 반미 성향의 집회로 전개됐다. 하메네이는 미국과 이스라엘의 공습으로 사망했고, 장례식에는 중국·러시아 등 30여 개국 고위 인사가 참석했으나, 한국은 대사급 조문을 위해 준비했으나 이란 측이 장소 사정을 이유로 참석을 거부했다. 장례식은 6일 테헤란을 출발해 9일 고향 마슈하드에 안장될 예정이며, 미국과 이란은 장례 후 11일 파키스탄에서 후속 협상을 예정하고 있다. 이란의 조문 거부는 한국 외교적 접근성과 중동 정세에 대한 영향을 미칠 전망이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:10:04'::timestamp,'2026-07-27 16:44:22.836700'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1902,4747,'미국은 2024년 7월 4일 독립기념일 250주년을 맞아 전국적으로 대규모 불꽃놀이를 개최했으며, 특히 워싱턴 DC와 뉴욕에서는 총 85만 발의 폭죽이 발사됐다. 이날 축제 중 워싱턴 DC의 기념탑 뒤에서 불꽃과 함께 거대한 번개가 동시에 발생했고, 뉴욕 브루클린 다리에서는 불꽃이 튀며 다리에 불이 붙는 상황이 발생해 화재 위험이 제기됐다. 다행히 인명 피해는 없었지만, 축제 현장의 안전 관리와 폭죽 발사 시설의 기술적 안정성에 대한 우려가 제기됐으며, 관련 기관은 사고 원인 조사에 착수했다. 이후 정부와 지방자치단체는 향후 대규모 공공 행사에서의 화재 위험 대비 안전 절차를 재검토할 예정이다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:10:08'::timestamp,'2026-07-27 16:44:39.513156'::timestamp);
INSERT INTO public."article_ai_results" ("id","article_id","summary","abuse_score","abuse_label","keywords","status","last_error","created_at","updated_at") VALUES (1903,4749,'도널드 트럼프 미국 대통령은 4일 미국 독립 250주년 기념 연설에서 공산주의를 ''암과 같다''며 시작 전에 즉시 제거해야 한다고 강조했다. 이는 지난 4일 러시모어산 연설에서 공산주의 위협을 경고한 데 이어 중간선거를 앞두고 반대 진영을 ''공산주의자''로 규정하며 지지층 결집을 노린 것으로 분석된다. 연설은 폭염과 폭풍으로 인해 약 1시간 지연됐으며, 워싱턴 D.C.를 비롯한 여러 지역의 독립 기념행사가 취소되거나 연기됐다. 이후 트럼프의 공산주의 비판은 정치적 메시지로 해석되며 중간선거 전후 논란이 예상된다.',NULL,NULL,'{}','event_assigned',NULL,'2026-07-26 13:10:11'::timestamp,'2026-07-27 16:38:49.637768'::timestamp);
